CREATE TEMP TABLE _platform_release_items ON COMMIT DROP AS
SELECT *
FROM pg_catalog.jsonb_to_recordset($platform_items$[{"claim_id":"0038ea5e-d68a-48bb-9d97-0fc436549ae0","items":["【市政第一、民意優先】 強力監督市府施政，為市民發聲，揭發弊案絕不手軟。","【發展台北，讓世界看見台灣。】 推展商圈經濟，發展大稻埕、大龍峒，再造老舊社區風華。連結東西向，花博、美術館、圓山地區,打造人文薈萃藝術文化。","落實居住正義、台北好宜居。：監督市府利用閒置國有市有土地廣建社會住宅，提供民眾居住機會。","落實居住正義、台北好宜居。：監督市府改善市民停車問題，運用公共空間興建地下停車場。","落實居住正義、台北好宜居。：遷移松山機場及第一殯儀館，加速都市更新。老舊社區再造，放寬容積獎勵，提升居民居住環境。","落實居住正義、台北好宜居。：推動成家基金，鼓勵年輕人留在台北市成家立業生子。","老弱婦孺、安心幸福。：清查市有閒置教室土地空間，作為公托及長照中心的關懷據點。","老弱婦孺、安心幸福。：推出「五成公托兩歲專班中籤率」，讓台北市家長安心上班。","老弱婦孺、安心幸福。：推動「凍卵補助」，保障女性未來的生育選擇權。","老弱婦孺、安心幸福。：推動長者、弱勢族群健康午晚餐、65歲以上長者公費裝假牙。","老弱婦孺、安心幸福。：加強中、低收入戶及獨居老人等弱勢族群之生活照顧。","老弱婦孺、安心幸福。：嚴查毒品，強化防制新興毒品進入校園。","老弱婦孺、安心幸福。：全力保護受虐婦女及孩童安全。","友善動物、尊重生命。：加強流浪動物救援機制，尊重生命。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["election_metadata","candidate_introduction","heading_or_slogan"]}}},{"claim_id":"00503adc-5ea7-4ea3-9117-8f70b5528fd1","items":["持續爭取經費協助警義消、社區發展協會、愛心媽媽、環保志工等社團，協辦各項活動，發揮社區組織功能，提升鄉親生活品質。","促請縣政府寬列預算，執行校園安全及防疫，充實國中小各項設備，以提升教育品質，俾利學子身心健全發展。","督促縣政府落實社會福利及長照政策，照顧鰥寡孤獨老人及中低收入戶生活。","強化婦幼安全與保護，尊重身障者權益，重視無障礙生活空間。","督促縣政府加強輔導農民提升專業智能、推動產業升級，強化農產特色、增加農業產值收益，因應國際化趨勢。","督促縣政府積極輔導勞工職能訓練，提升就業機會，重視勞工職場安全及工作環境。","持續督促鄉轄大排、中排區域排水治理，徹底解決礁溪水患，保障居民生命財產安全。","持續積極推動鐵路以東腹地，結合礁溪市區成為溫泉水岸城市，擴大市區腹地、改善市區交通並紓緩塞車。","推動活化風景區觀光景點，結合溫泉資源，使礁溪成為溫泉觀光旗艦城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0054b952-43bf-42db-b947-ed1ba1a78c4b","items":["爭取苗栗醫院改制為台大醫院分院。","持續爭取中央在苗栗興建青年住宅，讓青年居住免煩惱。","持續提出《財政收支劃分法》修法，增加苗栗創稅分配。","推動跨部會反詐騙專責單位，從源頭防止詐騙。","檢討民進黨假國家隊名義推動的不當政策。","監督政府不當介入媒體，反對NCC淪為民進黨打手。","修改《國營事業管理法》，杜絕政黨酬庸。","重新檢討雙語政策內容，加強技職教育。","修法推動65歲以上長者、55歲以上原民免納健保費。","根據各年齡增加各項醫療項目補助。","提高社福項目，讓老弱婦孺皆有所養。","因應苗栗低丘緩坡地形，檢討不合時宜法令。","滾動檢討保安林地解編，因地制宜符合地方需求。","加強保障農漁民權益，提升應有福利。","制定營養午餐專法，家長、學生都放心。","提高勞工權益保障，共享經濟果實。","爭取年輕世代福利，讓青年子弟能扎根苗栗。","檢討能源政策，推行綠能核電。","維護中華民國主權，以自由民主為基礎向外拓展國際關係。","堅持九二共識、一中各表，推動兩岸多元交流對話，避免戰爭。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"00679afa-4cc7-42ac-9404-9fe38c15b9f8","items":["觀光要盈：規劃市集推廣在地農產品：海山漁港規劃販賣區外設置假日市集、原住民特色市集。","觀光要盈：優化海山漁港自行車道：強化導覽功能與旅遊深度。","觀光要盈：海山漁港週邊導入藝術展演空間：提升在地觀光量能與就業機會。","觀光要盈：婚後孕前健康檢查補助，創造更友善父母的環境。","觀光要盈：好孕專車加強2.0版：孕期補助產檢外，更延伸到產後帶寶寶回診的健兒門診。","觀光要盈：爭取大湖里市民活動中心：設置關懷據點、共餐食堂，照顧長輩。","觀光要盈：香山建設預算倍增：香山區面積超過本市一半，力推香山區公所工程預算倍增，有效提升鄉親生活品質。","觀光要盈：運輸載具官方媒合平臺：導入預約服務，將社區關懷據點結合幸福小黃，建立更有彈性與安全的公共運輸。","觀光要盈：Youbike新設站點：鹽水圖書館、內湖國小周邊增設新站點，將站點延伸至內湖國中、中隘、南隘等，讓Youbike發揮在地通勤、山海串聯的觀光移動功能。","觀光要盈：友善車友：中華路沿線（特別是五段至六段）規畫自行車道及導覽說明。","觀光要盈：高使用率人行步道優先重新舖設：例如：中華路沿線、香山國小至公道三間，以及中華路進入元培街之人行步道等學校、商圈周邊。","觀光要盈：落實科技教育：香山區中小學建立完整科技教育課程與教學推動計畫，包含程式設計與運算思維等，培養學生學習興趣。","觀光要盈：設置通勤專車：面臨公車減班次及路線，設置通勤專車保障學生通勤便利。","觀光要盈：續推華德福教育：目前已招收幼兒園與國中小，其校舍將於今年完竣啟用，後續規劃高中部設置。","觀光要盈：完成富禮國中射箭館：全力協助學校，盡快完成富禮國中射箭館。","觀光要盈：規劃香山體育園區、香山圖書館：推動都市計畫檢討，規劃設置體育或文教設施，如香山體育園區、香山圖書館等。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan","web_promotion","candidate_introduction"]}}},{"claim_id":"00acdcd4-20cd-4684-b925-928a014d1103","items":["極力促進二林精密機械園區近期內通過環境影響評估並儘速完成園區開發，創造更多就業機會，以解決人口老化及外流問題。","爭取經費徹底整治二林區四鄉鎮區域排水設施，做好防汛防災，確保民眾生命財產安全。","輔導發展特色農業及休閒農業，振興農村經濟並扶助傳統產業，照顧農民生計。","積極建置長期照護據點並結合社會資源關懷獨居老人及弱勢家庭、低收入戶等，落實社會福利政策。","輔助廠商進駐中科四期園區生產，造就年輕人在地就業機會。","督促東西向76線快速道路二林芳苑段聯外道路週邊工程整治。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"00bf0f85-ef0b-43f7-945c-35e9da09caa9","items":["推動桃園大圳加蓋（內壢交流道至中華路），緩解交通壅塞情況。","推動埔頂支渠水圳加蓋（龍慈路至後寮一路），暢通交通網路。","爭取未開闢的計畫道路與瓶頸道路開通。","閒置公有土地活化再利用，開闢公園及停車場供大眾使用。","爭取桃園市南區婦女館設立。","增設社區關懷據點，關心長者日間照顧，減輕家庭照顧長者的負擔。","輔導青年就業、創業、多元學習管道。","爭取埤塘綠美化，增加民眾休憩活動場所。","持續推動老舊校舍與教學設備汰換更新。","提供專業律師、地政士、會計師免費諮詢服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"00c2139e-d601-4c0e-a86e-2ef6c927875e","items":["支持18歲公民權，創造年輕活力的新時代。","督促羅東都市計畫區工業區保護區區段徵收案儘速完成，加速羅東地區整體發展。","督促羅東轉運站早日興建完成，提供便捷完善的公共交通運輸。","督促鐵路高架工程早日完成，疏通東西向交通。","推動高齡與幼齡資源服務社區化，建構羅東成為幸福城市。","推動活化休耕地、發展精緻農業、增加農民收入及推廣安心農產。","督促落實學校午餐安全檢核機制，確保學童健康。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0119795c-455d-4b95-8646-b1b37186ec8a","items":["督促市府積極爭取新市至善化路段鐵路高架化，解決平交道塞車問題。","督促市府積極爭取捷運深綠線，串連南科園區與綠能科學城雙引擎，形塑科技生活廊帶。","督促市府加速進行A、B、C、D、E、N、O區塊南科特定區開發，建構完整的產業及居住生活圈。","爭取在南科特定區設置大型醫院，以解決南科周邊地區日增人口，醫療量能不足的問題。","爭取普設路口監視器，有效釐清交通肇事責任及遏止犯罪。","爭取教育經費，改善新市、新化、善化、安定、山上等五區幼兒園、國中小學校，校園環境及老舊校舍，讓學童上課專心，家長放心。","爭取興建立體停車場、地下停車場，改善停車問題。","爭取南科火車站旁公滯11 用地，設置特色公園及兒童遊戲場。","爭取提高生育、托育補助，增設平價公共托嬰中心及幼幼專班，讓年輕人敢婚、願生、樂養。","爭取65 歲長者免健保費。","督促市府打造毛小孩樹葬園區，讓毛小孩有安息處所，提供主人追思懷念的地方。","督促市府加速建設南科周邊地區污水下水道系統，將南科周邊地區打造為宜居科技城。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0174069c-8e7e-4344-8be3-582fc66a739d","items":["引進優質銀髮族養生照護機構,樂活退休生活。","活化政府閒置會館,改為孩童才藝培育單位,培養孩童課外才藝興趣。","推動休閒農業區鐵馬道觀光產業。","推動大型「七夕活動」讓單身貴族找到幸福。","推動設置BOT市區停車塔,方便民眾購物需求。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"01a322ea-5a9e-4457-bcf9-6c4315460e3d","items":["強化醫療資源：促成大型醫院與在地醫院所更多的合作，增加重要專科。","推動觀光領航：除強化縣內唯一縣級的落山風風景區軟硬體建設外，並要求投入資源辦理聚客活動及相關輔導措施，吸引更多遊客，興盛觀光產業鏈。","農業精緻化、機械化：提高農產品價值，並透過強化農業設備，降低農民勞動力成本。要求修建轄內各漁港，讓漁船停靠更方便安全。","爭取交通建設：交通紓解是地方大事，除了聯外道路的優化外，各鄉鎮間的聯絡道路更應該順暢，且達到路平、安全的要求。","文化產值再提升：文化是我們的驕傲，未來以興建中的恆春展演中心為軸心，保存及發揚鄉鎮文化的根，再結合觀光及影視產業，進而刺激商業發展。","社服完整照顧：因應人口老化趨勢，狹長的恆春半島在社福、長照的需求殷切，將督促做完整配套，讓本地的弱勢及長輩都能得到政府的照顧。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction","heading_or_slogan"]}}},{"claim_id":"01c69693-1ad7-46e5-8043-4a73a1ae39bd","items":["積極爭取地方建設經費、改善農村、社區、居住環境、提升生活品質。","改善農田排水、減少農民損失。","落實社會福利政策、加強照顧弱勢團體、關心長老婦幼之福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"02449a9d-e6fe-4956-a116-0be688310df0","items":["積極爭取經費,重視強化各部落基礎建設。","重視原住民各族文化傳承,輔導創意產業發展,創造在地就業機會。","督促政府重視在地觀光開發,休閒旅遊創造就業機會增進收益。","督促政府重視單親弱勢婦幼安全福利,保障婦幼權利。","督策政府提升原住民老人社會福利,部落獨居老人長期照護計畫, 醫療照顧的福利。","督促政府加速原保地核發權狀,國有地放租解編作業。","督促政府重視原住民音樂、舞蹈、軍動人才,提升多項才能人才培育。","不分鄉鎮、社區、部落全方位服務努力爭取族人權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0262afa9-10b8-4e37-8e24-6c391730f1eb","items":["推動市府招商引資，重視基隆三大工業區（五堵、六堵、大武崙）再造計畫，吸引各類廠商進駐基隆，創造就業機會，讓基隆人才回流，增加家庭團聚時間。","結合「四師平台」，留住在地建築師、律師、醫師、會計師服務市民、企業。","推動雨天跑場、現代槌球場、區域室內運動中心，強健市民身心；推動親老館，館內設置老人、兒童運動中心及教練，減少老人肌少症、培養兒童健康運動習慣，減少健保支出及家庭負擔。","落實社會福利，檢討政府釋出閒置空間，獎勵社區力量整合民間資源做合理之配置運用。","推動市府成立公托中心，鼓勵企業成立托嬰中心，協助新手爸媽適應新生活。","增加婦女生育及相關疫苗施打補助；以優惠稅率鼓勵企業提供有薪育嬰假。","要求市政府設置青年對話平台，鼓勵年輕人參與公共事務。","推動新豐街303巷聯外道路計畫，以消解新豐街塞車困境。","爭取推動三軍總醫院於基隆成立教學醫院及海洋醫學研究中心。","持續推動基隆港內客外貨政策，促進港務再生計畫，提振基隆經濟活力。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"02a04880-84e8-42dd-ab24-0a596c08b363","items":["社會福利：長者：爭取市府落實長照2.0，並力爭65歲以上老人健保免費，增加老人裝假牙條件放寬。","社會福利：孩子：爭取全齡育嬰補助，多元公共托育家園、臨時托育中心24小時服務機制。","社會福利：青年：爭取青年社會住宅興建，放寬承租條件，讓年輕人可輕鬆成家。","社會福利：壯年：爭取完善社會福利，照顧年幼、年長者，減輕家庭經濟支柱的負擔。","社會福利：婦女：提高社會尊重婦女工作權，爭取婦女職業訓練，建構「月嫂」制度，營造二度就業婦女工作機會。","社會福利：弱勢：爭取放寬低收入戶審核標準，讓社會邊緣戶可獲得社會福利照顧，並避免被標籤化。","公共建設：社區：爭取台南市一里一活動中心，開放假日校園作為社區臨時停車場，資源共享共榮。","公共建設：交通：監督台南鐵路地下化工程、捷運系統興建；公共自行車活化，完善大台南交通建設。","公共建設：公園：爭取建設大台南特色公園，塑造人文城市形象，全民休閒遊樂園。","公共建設：道路：全面體檢大台南道路、人孔蓋路平，危險路口改善；重視行人路權，推動友善交通。","公共建設：教育：極力爭取國中小營養午餐免費；營造美語教育環境，活化各校閒置教室再利用。","公共建設：新冠肺炎疫情，打亂全民生活、工作、商家生機，強力監督市府超前部署，做好防疫工作；增加防疫補助金，緩解市民生活窘境。","公共建設：監督各局處以人性為出發點，應以輔導為出發點，讓各行各業循正規模式運作，勿以開罰作為目的，避免以罰款成為政府的主要歲入。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"02b784dc-346a-400f-92e0-8ac49cd0a17f","items":["要求縣政府推動更多的親子活動空間、青少年運動場所，讓全民運動更普及。","充實學校軟、硬體設備，讓學生有更好的學習環境與空間。","結合學校與社區關懷據點，讓長輩樂活，促進世代共融共好。","督促縣政府重視農業發展，能與各鄉鎮農會配合，協助農民行銷方式並提供行銷平台，幫助青農創新農業發展，使農業能升級，成為可世代傳承的事業。","爭取經費改善地方產業農路、野溪治理、邊坡護岸修建，以保障民眾及農民出入安全。","結合地方歷史、文化、古蹟、農特產、藝文、小吃等，推動在地人文特色，促進地方觀光。","關懷弱勢，結合社會愛心資源幫忙、協助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"03168a6a-4bf5-4533-941a-f1293172611f","items":["性推動婦幼文教發展關懷服務，實施一里一據點。","銀髮身心健康發展活動企劃與長期照顧服務產業。","北五堵國際研發新鎮規劃案，增加在地就業機會，吸引青年返鄉，帶動產業發展。","七堵社會住宅興建案，進而輔導在地青年人創業計畫申請。","基隆捷運計畫案週邊交通改善，提升交通網絡發達。","風雨運動場、寵物公園、兒童設施、銀髮設施，提供七堵區民眾雨天的青少年、親子活動空間。","動確認捷運路廊、務必及早通過環境影響評估、讓捷運工程進度早日落實、以帶動地方繁榮。","府落實長照 2.0 及降低公辦幼托收費政策、敦使民間疾苦充分改善。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0353e68c-b5ca-4894-9f00-d277050f8ad6","items":["強力監督政府，落實交通平權、醫療平權、教育平權、經濟平權、環境平權。","因應少子化、高齡化人口變遷，優化產業結構、增進生產效能、提高薪資待遇，持續強化國家總體競爭力。","面對境外敵對勢力威脅國家安全，積極推動國防自主、捍衛民主。","鞏固台灣在印太區域的重要地位，持續推動新南向經貿、醫療、農業、教育、文化、人力資源交流。","迎接全球6G行動通訊趨勢，善用屏東地緣優勢，發展低軌衛星與周邊之太空產業。","因應2050淨零碳排，充分運用台灣資源優勢，發展氫能、太陽能、海洋能等潔淨能源。","發展智慧農業、擴大農業金融，藉由循環農業減輕環境負荷、增進農民收益、充實農業生產、保障糧食安全。","推動環島軌道網絡，完善聯外交通建設，包括高鐵、高捷和快速道路等延伸工程，督促按期完成規劃、加速執行、早日通車。","促進學用合一、關懷弱勢學子，減輕家庭負擔。","完備偏鄉緊急醫療網、提升醫護待遇、強化健保財務永續經營。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"03cecf0a-da3a-41c6-b0d5-a108244944dd","items":["育兒福利：年輕夫妻結婚買房，房屋稅減免，讓年輕人減輕負擔，敢結、敢生、有錢養。","育兒福利：0至2歲公托不足，加速公托建置；沒抽到公托者可獲補助就讀私立托兒所。","育兒福利：協助爭取桃園育兒津貼6,000元、托育補助10,000元、兒童課後輔導補助券。","運動政策：協助爭取國民運動體適能中心第1個小時免費。","運動政策：爭取國民運動中心開辦女性運動課程及活動，提供優惠女性方案。","運動政策：提高身心障礙者運動權益的保障。","交通政策：爭取機車族路權，減少右轉汽車與直行機車車禍，開放機車左轉。","交通政策：通盤檢討車道線（10公分）與路面邊線（15公分）的疑義。","交通政策：加速興建桃園綠線捷運，提早完成通車，為居民帶來更大的便利性。","教育政策：培養學生「多元學習」的核心素養與探索興趣，讓孩子與世界接軌。","教育政策：要求市府善用閒置校舍，以長照、青年就業、幼兒托育以及身障者庇護中心等面向作長遠規劃，將閒置資源發揮最大價值。","教育政策：持續監督市立圖書館總館建置工程，後續協助爭取軟體設備及各項書籍之預算，讓市民有優質文化閱讀空間。","建設政策：推動都市老舊建物健檢：督促都發局結合專業技師，針對都市發展較早區域老舊建物，檢查安全結構等問題，輔導並補貼進行改善或都更。","建設政策：協助爭取桃園區中路四號基地社會住宅新建工程結合微型運動場館之規劃，提供市民更便利優質之運動空間。","建設政策：要求興設南崁溪親水公園連結自行車道，透過綠廊步道串聯桃林鐵路步道、虎頭山風景區，形成桃園區完整休憩動線，打造新城市水岸新風貌。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0404b859-eff7-4bd5-ae92-2714865aa949","items":["交通建設：爭取捷運由內壢火車站延伸至桃園高鐵站，確實監督「鐵路地下化」、「新設中豐交流道」以及周邊相關計畫，完善中壢交通網。","產業發展：積極推動亞洲矽谷創新研發中心與中原創業村之發展，促進周邊產業轉型升級；爭取內壢－青埔廊帶成為企業永續經營發展之基石，帶動地方成長，接軌國際潮流。","人才培育：配合產業發展趨勢，爭取預算開設相關課程，鼓勵有志人士自我進修；擴大產學合作，培育人才提升競爭力。","幼兒托育：積極增設公共托育、公立與非營利幼兒園；推動兒童臨時托育服務媒合平台，減輕家長負擔。","長者關懷：爭取預算提升社工服務量能與品質，整合醫療資源，使長者獲得更優質之關懷與照護；配合就業服務站中年轉職、退休後再職，創造新的就業機會。","運動城市：協助推動龍岡全民運動館，確實監督並完善中壢體育園區之規劃，打造健康活力的運動城市。","新住民：推動安心關懷包，協助新住民提升語言能力，快速融合台灣的生活與文化。","寵物友善：推動寵物友善空間標章，爭取新設寵物公園，創造市民與毛小孩的同樂空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"041caeef-1272-4b67-b720-c0556b321a07","items":["樂活竹北：推動竹北在地海洋觀光遊憩環境，帶動地方觀光發展。","樂活竹北：爭取規劃自行車道，串聯竹北、新竹及新豐，打造綠色廊道。","樂活竹北：爭取鳳崎步道整建，提升整體環境，成為友善休閒登山步道。","樂活竹北：持續推動共融式遊戲場及增闢公園綠地，提升市民休閒空間。","樂活竹北：持續推動動物保護政策，推廣寵物友善環境。","樂活竹北：優化大眾運輸環境，爭取智慧站牌、候車亭及轉乘設施。","樂活竹北：爭取興建停車場，改善停車需求，提供優質停車環境。","教育願景：持續檢視竹北老舊校園，致力改善學校環境，提升各校軟硬體設施設備及教學品質，教育資源合理配置，並推動特色學校。","教育願景：爭取竹北增設高中，推動國際實創優質高中，落實在地就學。","經濟就業：監督AI智慧園區開發進度並促儘速營運，增加就業機會。","經濟就業：持續推動青創基地，爭取創業低利貸款，鼓勵青年創業。","經濟就業：爭取農特產展售站，建構多元銷售通路，提升青年返鄉。","地方建設：爭取豆子埔溪整體水環境改善，改善水源不足、水質汙染，並復原水文風貌。","地方建設：爭取新月沙灘周邊整體環境改善，並解決停車不足問題。","地方建設：落實托育幼老福利政策，監督按時發放，減輕家庭負擔。","地方建設：整合長照資源，提升服務能量，完善社區醫療照護網絡。","地方建設：爭取社區公共空間活化利用，設置托幼托老之關懷據點。","地方建設：爭取敬老卡點數擴及YouBike多元用途，讓長輩走出戶外。","地方建設：落實新住民福利政策，協助適應生活，改善語言問題。","地方建設：推動產學合作，培育教育、技能，提升家庭經濟力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"04b1b667-9e8c-441f-832b-1c2dc8ae9d2b","items":["以紮實的問政內涵監督縣政,加強花蓮縣政質化與量化的全面提升。","力促縣府縮短城鄉差距,擴大就業機會,將人才留在花蓮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"05265dc9-e877-43f5-8839-77eaabd0e15a","items":["協助社區關懷據點,長者共餐常態化。","協助社區多辦老人康樂活動,讓長者溫馨生活。","持續爭取老人健保全額補,減輕家庭負擔。","爭取「婚後孕前健康檢查」,對市民全面補,並積極爭取更多的育兒福利。 基礎建設升級","爭取增加農、水路經費,加強農路及排水改善,增加農民收益,保障鄉親財產安全。","推廣山區特色旅遊,結合地方農特產以及宗教場所,打造複合式休閒旅遊。","爭取玉井青果市場改建,打造觀光市場。 山區教育實改善","落實官方第二語言,持續爭取英語學習空間,提升偏鄉英語教學師資及設備。","營養餐嚴格把關,監督食材來源,爭取全面營養餐免費,提升學童餐飲水平。","持續爭取偏鄉學校教育設備、課後輔導補並改善教育環境,縮小城鄉差距。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"05364465-70fc-4e73-8ba7-90fdee0da7df","items":["老舊機車汰換，市民可享電動車補助，或享大眾運具月票2年免費，推動綠色運輸。","政府新建物需規劃一定比例之停車空間，幫台北交通減壓。","一殯拆遷後，原址應作為托老育幼中心或青創基地，大安、文山區受交通衝擊，市民應享優先保障名額。","推動寵物健康保險，增加北市寵物友善環境。","增加公立幼兒園比例，幼兒園轉為全日托，配合父母下班時間，一起拼經濟。","推動防災型都市更新，大安區、文山區老房最多，市府應展現魄力，捍衛市民身家財產。","補助汰換老舊冷氣，台北一起節能用電。","因應少子化，閒置校舍改裝為老育幼、社區活動中心。","持續改善人行道，推動路面整平，讓長輩走得更安心。","強化長者關懷，重新發放重陽敬老金、補助輔具及照護服務。","友善長者，所有候選人的政見應用10號字體以上宣傳，別讓長輩傷眼睛。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"05416bad-b079-4a1c-b7c7-f41348bbe652","items":["促進觀光文化新亮點","提升就醫資源方便性","爭取航道疏浚及漁港轉型"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0573bf11-4e17-4021-a17d-23c52fc04304","items":["爭取65歲老年健保免費。","強力爭取台南市警政同仁近千位缺額於112年內補齊。","爭取中西區和緯路五段延伸工程30公頃學產地能夠活化變更為都會科技產業專區及住宅用地，促進產業發展、增加就業機會、優化居住環境。","爭取延平國中校園腹地興建地下停車場，以解決公園沿路停車空間不足問題。","爭取北區鎮北坊歷史街區串連及致力整合交通、觀光、文化政策，帶動舊城區觀光與文化經濟同步提升。","要求市府就中西區原有商圈進行特色整合，舉辦大型活動可串連，並極力爭取接駁車至路外停車場以利遊客觀光動線，減少市區交通打結。","致力推動友善育兒環境，"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"059160b7-9ab1-4010-b8a8-0c42930b5ab0","items":["推動高雄捷運延伸屏東，經台1線進入客家鄉鎮之環狀路廊，促進地方發展。","推動公墓遷葬種電，在綠電下增建體育休閒園區和公益設施。","推動汙水下水道接管率，改善河川汙染環境衛生。","185線沿山公路枋寮鄉（隆山村）至內埔鄉（隘寮村）高架快速道路並延伸國道3號。","「高雄－屏東第二東西向快速公路」延伸至內埔鄉境內為終點。","國道3號於竹田鄉南勢、頭崙段設立體交流道。","屏107線拓寬工程（內埔鄉文化路通往萬巒鄉五溝村道路）。","屏85線拓寬工程（內埔鄉振豐村新東路並改善排水溝）。","開闢內埔鄉豐田地區都市計畫區15米外環道路。","推動龍頸溪、五溝村水系環狀水岸環境營造、淨水設施，發展聚落觀光。","加強整治區域排水功能；推廣在地滯洪，增加承洪韌性。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0593d0c5-e868-4460-850a-6df9c6e4d35e","items":["候車空間改善：安樂沿線候車空間，過去四年，顯著改善，長庚醫院站擴建，友善人行道，之豪將繼續監督改善。","路平品質改善：麥金路示範道路計畫，基金一二三路改善計畫，皆在過去四年內陸續推動完工，之豪將繼續監督推動地下管線更換與路面改善。","親子特色公園：過去四年，成功催生安樂三期（四維）親子公園，基隆市內尚有眾多公園空間安全、品質、可玩性，有提升之空間，之豪將持續監督改善。","推動國際交流：過去四年，台灣躍升國際矚目焦點，基隆市在後疫情時代，需要積極拓展國際交流，不僅是商機，更是城市發展之關鍵。之豪將持續監督基隆的國際交流。","推動行政改革：基隆市行政制度需要在國土規劃與區域整合下，審慎重新思考各種可能性。基隆未來發展之利基關鍵為能否有效創建有效率之機構單位，吸引優質行政擘劃官僚，處理捷運與新市鎮發展之複雜課題，之豪將持續監督行政改革。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"05cd932d-2d1c-4b05-a02a-2ce06835cf9d","items":["簡化青創輔導申請程序","落實勞動權益與性別友善","爭取增建特色共融式公園","監督工程、減緩彰化交流道區域壅塞問題","檢討不合理待轉、人本設計強化行人安全","推動台鐵宿舍村為國家級園區","引介公私部門資源協助社區據點","增加據點、不老健身房進入社區","打造母語環境、提升外語教育資源"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":11,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"05ce00db-aeb0-4181-9184-e20c687813ce","items":["推動興建「南北竿跨海大橋」有效資源整合，縮短城鄉差距。","爭取推動「北竿機場擴建工程」，全面提升馬祖對外空中交通。","督促縣府成立專案小組，推動北竿鄉合宜住宅及社會住宅興建計畫。","提升白沙碼頭設施，未來建設及動線作整體規劃，逐年推動完成（包括新增浮動碼頭、南堤延伸工程、北堤貨運碼頭改善、新旅運大樓、馬祖大橋銜接點等）。","爭取經費，推動北竿鄉芹壁村停車場興建工程。","充實北竿觀光，督促北竿鄉北海坑道重新開放，以利觀光發展。","推動北竿塘岐老人活動中心興建工程。","積極推動北竿鄉塘岐靶場遷移。","爭取推動馬鼻灣遊憩休閒（育樂漁業）碼頭，帶動地方觀光多元發展。","督促推動橋仔漁具展示館內部設施，提升漁村文化內涵。","充實北竿醫療量能，增加北竿鄉衛生所洗腎醫療服務。","爭取水環境計畫，改善橋仔阿南境周邊整體環境。","推動興建北竿鄉芹壁龍角峰景觀平台。","改善上村到壁山、壁山到莒光堡道路，以維人車安全。","爭取推動坂里村40據點到混砲連濱海道路工程。","充實規劃塘岐村得天泉到馬鼻灣道路系統。","爭取推動塘岐至橋仔88據點濱海道路，維護行車安全性與便利性。","推動北竿中沃口碼頭延伸工程。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"0619f849-604a-4292-8f09-f086ff12dc94","items":["西岸文化展現：推廣「蒐集舊地名活動」，從罾仔寮、鬼仔坑、碼頭、流籠頭、香蕉湖、仙洞、火號仔、白米甕、外木山、孚基仔、內木山、大竿林、烏橋頭、蚵殼港等中山區各地舊地名，以「東歷史場景、西貨漁博覽」推動西岸風情文化觀光廊帶。","社福友善城市：推動基隆社會安全網建置，發展銀青共融室內場所，監督全市公共場所完整設置無障礙空間。推動滿六個月寶寶施打免費13價肺炎鏈球菌疫苗，中山區長者免費全口假牙、就醫搭乘計程車由敬老卡補助，中山區小巴公車延伸路線直達長庚醫院。","交通快捷便利：協調中山區城際快捷客運1813D通車成功，持續完善中山區第二條城際快捷客運1550B從中和路發車。推動市內公車持續發展區域跳蛙公車，市民遊客區域移動更便利。","智慧海港城市：爭取公車客運到站資訊合併，到站準確報時系統優化，市內道路路段維修資訊、公有停車場資訊、客輪船舶靠港資訊，並爭取增設智能大數據即時看板。","樂活宜居：積極爭取設置公有立體停車場，持續爭取親子全齡遊憩公園、寵物友善公園，監督地下公共管道纜線（自來水、瓦斯）施工及路面鋪設規範，確保路面平整。主張廢除機車二段式左轉。","綠能環保護海：推動市政、議政公文系統無紙化，全市增設充電站，爭取設置市區UBIKE租還點。推動協和電廠轉型燃氣電廠改善空氣品質，推動採用FSRU。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"062826e2-bcc6-4353-9c80-0d7794064ea3","items":["強力監督市政府預算、決算及整體資源分配，落實基層服務。","爭取公共托育中心與公立附設幼稚園的設立、推動過嶺地區增設國小，持續關心龍岡國小及環北國中遷校進度，並爭取學校地下室設立公有停車場及設立單親家庭免費課後輔導中心、弱勢家庭餐點補助，以減輕家庭負擔。","提倡全民運動健康生活，活用閒置公有建物、空地，增設里民活動空間，規劃全年齡市民都可以參與的豐富多元課程，鼓勵舉辦各式活動競賽，讓生活有氧更年輕。","推動老屋重建與公辦都更，讓城市翻新、市容更好，打開瓶頸道路、改善交通，進而提升居家安全。","持續推動全市電線、電纜全面地下化，還給市民乾淨的天際線。","督促過嶺地區增設消防分隊及原興國分隊遷移進度，提升救援能量，守護市民家園。","推動低碳、綠能完善交通路網，串聯捷運輕軌、公車、YouBike及電動運具，降低空污，強化相關配套，增加大眾運輸搭乘誘因，永續家園。","推動第二行政園區盡速建置，以利民眾洽公。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"065f6d0c-c1c3-4069-8c7a-33f909ab97dd","items":["永續發展有機精緻農業,淨零碳排倡議,認證品牌行銷,擁抱前瞻科技思維,產業觀光多元永續","河川公有租地撥用、開發、放領,不合時宜土地政策檢討、解編、還地於民,落實土地正義。","督促廉能、效率、主動積極縣府團隊.“\"打造後山亮麗伊甸園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"067bde29-67f5-4dc4-9c12-4ec45ce18a7e","items":["在地就業：爭取屏科園區錄取本區居民","在地就業：促進產學合作，鼓勵在地就業","創生地方：發揚地方特色，爭取各級補助","創生地方：農業產銷升級，鼓勵青年創業","安養生活：爭取擴大敬老補助","安養生活：假牙、老花眼鏡、助聽器等老年安養補助從優從寬"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"06833911-96a9-4c07-b7a5-1c4da008beaa","items":["爭取中央建設經費超過1,200億，持續增加中。","幸福台南12大政見：因應後疫情時代，推動產業創新升級、維持全球競爭力關鍵產業領先地位。","幸福台南12大政見：保障農漁民權益，度過天然災害困境。","幸福台南12大政見：監督推動2030國家雙語政策，強化年輕世代國際競爭力。","幸福台南12大政見：加速爭取長照衛福據點，完備社福與數位長照服務。","幸福台南12大政見：協助在地文創、藝文團體爭取資源補助經費。","幸福台南12大政見：加速落實台灣2050淨零排放目標，促成產業轉型。","幸福台南12大政見：持續爭取治水及排水改善經費，落實河川治理與解決水患問題。","幸福台南12大政見：持續捍衛弱勢、勞工、婦女、農漁民、青年、中小企業等權益。","幸福台南12大政見：串連地景、宗教、文化、美食景點，完善地方觀光產業發展。","幸福台南12大政見：擴大爭取教育、體育經費資源，改善國中小學設備及體育設施；培訓在地優質體育運動選手。","幸福台南12大政見：整合各部會資源，加速推動台南地方創生計畫。","幸福台南12大政見：推動優質台南生活圈道路、打造台南運輸交通網、落實便利經濟生活圈。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0742aa7b-ad12-4a8c-975c-d8b725972e7c","items":["爭取人本交通建設超過100件！","開辦行動服務站1,140場次！ 民主台灣，世界典範 我支持：繁榮而自主的經濟，讓台灣產業與正在重組的國際供應鏈緊密連結，與世界共榮。 我主張：民主且多元的台灣，堅守國家主權，不分族群、性別、背景的人民皆享有尊嚴與保障。 吳沛憶進入國會，推動立法","《交通基本法》立法，提升交通安全。","《社會救助法》修正，降低弱勢補助門檻。","《人工生殖法》修正，保障女性生育權。","建設：捷運萬大線通車，道路、人行道更新，發展沿線商圈。","建設：串連中正區藝文廊道，催生親子美學空間。","文化：提高文化預算，促進藝術振興，保障藝文工作者權益。","文化：支持「台流」，扶植文化內容創作，發展影視音產業。 育兒","文化：降低育兒負擔，公托補助提升至7千元起，準公托及保母服務補助提升至1萬3千元。","文化：增設公托、公幼，彈性育嬰假以「日」或「小時」計算。 銀髮","文化：長照住宿式機構補助提高至每人每年18萬元，強化家庭照顧者「喘息服務」。","文化：打造樂齡社區，增加銀髮健康運動據點。","教育：家長減壓，高中職免學費，補助私大生每年3萬5千元。","教育：推動雙語教育環境，加強母語教育。 居住","教育：囤房稅2.0、遏止房屋炒作、落實《平均地權條例》。","教育：實現居住正義，加速社會住宅興建，試辦入住輪候制。 體育","教育：主張「體育署」升級「體育部」，增加全國體育預算。","教育：支持街舞、滑板新興運動，推展「全民體育」基層培育。 性別","教育：落實《性騷擾防治法》《性別平等工作法》《性別平等教育法》。","教育：防治數位性暴力，性平教育再升級。 年輕國會","教育：推動國會外交，加強民主交流。","教育：落實透明國會，資訊公開揭露。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"08278386-d6ca-4fbd-bf2e-ad2d62e2b363","items":["「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」","強化原住民主體性，落實推動原住民政策主流化。","監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。","爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。","活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。","重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。","提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。","強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。","充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。","積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。","積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"084b60e5-df6c-42d7-9cd7-88b21c9b1365","items":["爭取佈建偏鄉社區服務據點,讓服務與關懷不受地域性的影響,並開發各項到宅服務,主動發現個案 並提供即時的協助及辦理社區衛教及宣導活動,提升偏鄉照顧服務資訊的觸及率,讓偏鄉長輩都能做 快樂老人家。","爭取經費在頭份市設立羽球場。","督促縣府謀因應對策、有效激勵縣總生育率促進人口成長。","爭取義消福利、強化治安巡防,防止詐騙。","爭取學生冷氣及營養午餐補助,減輕家長負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"08611220-e01d-416b-9cf6-961e00fc0f5e","items":["反對家族干政，建立廉能宜蘭縣政。","支持公民權下修至18歲。","推動安農溪朝生態運動大公園方向建設，完善設施，早日完成上游整治綠美化，並設置國家級激流標竿（輕艇）場域。","落實紅柴林溫泉休閒區建設，加速設置平地地熱溫泉公園。","爭取太平山森林鐵道（五分火車路）復駛，優先建置林鐵土場站往東路段。","撥用原榮工砂石場23公頃國有土地，作為農業園區，發展休閒農業。","加速上將路大義至歪仔歪橋段拓寬，開闢完整天送埤路段，實現196縣道全線拓寬。","爭取國道五號三星聯絡道由宜蘭監理站延伸至三星，完善交通路網。","於蘭陽溪南岸堤外建置砂石車專用道，並將水防道路拓寬設為一般道路。","要求縣府加碼營養午餐，讓孩子吃得飽，也兼顧吃得好、吃得更健康。","推動農民農作物天然災害保險及個人化農業保險基金，因應極端氣候，由縣府擔保以減輕農民負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"088c1d5d-2b70-4c48-bdda-904f4fe4d266","items":["施政以民為尊，簡化各種行政作業流程，提升公務體系效能與效率以落實整體便民措施。","積極落實食品安全與衛生稽核，保障日常飲食安全與健康，藉以提升縣民優質的生活品質。","重視農業產銷問題，協助改善農作環境，提升農作物生產品質，以多樣化銷售通路取代傳統產銷型態。","落實老人政府社福長照政策，以因應社會環境變遷的高齡縣民生活需求，讓家庭經濟生產者無後顧之憂。","務實營造青年就業環境與落實政府合宜住宅政策，讓人才回流與適才發展，嘉惠青年成家立業需求，進而建構完善家庭生活。","正視學校教育資源合理分配，發掘並培育各類藝能人才，期使教育得以適性發展，並藉以提升整體教育成效。","重視各弱勢族群的基本生活照顧與服務層面，提供適當完善的就業輔導，以利改善生活環境與品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"08c6cda1-0cdb-4786-8307-84169e661ac7","items":["落實推動完成全縣國中小學教室裝設紗窗、冷氣。","推動完成斗六鐵路高架化。","推動落實長照業務及老人供餐。","完成內環路與文化路口延宕30年之擴寬工程。","推動雲林農業經濟化整合農業行銷落實照顧農民生計。","完成斗六市後站整體都市發展以及區域商圈的建立。","督促工業區要求廠商提供就業缺額。","完成建構路口監視器以確保人民生命安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"08d8418e-e7ad-4003-a226-9e255ff9d527","items":["以負責、專業的從政理念，落實推動本鄉各項建設及謀取族親最大福祉。","理性問政，嚴謹監督縣政府施政，保障我原住民權益。","有效並積極開發三地門鄉各種自然資源，勠力提升觀光、農特產業競爭力，發揚我排灣、魯凱族文化精髓，躍名國際。","積極爭取各項經費，暢通全鄉輸運要道，保障人民行的安全，財產安全，更促進地方繁榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"08d87af6-669a-4ab3-ada9-f0ac39ca687a","items":["不分黨派屬性，肯全域服務雲林縣民各項陳情案件。","不分鄉親富貧老幼，為地方拚經費建設村里鄉間基層設施。","不分縣政預算規模繁簡，勤於審查暨合理監督。","專注問政縣政府推動攸關民生、弱勢福祉、文藝、社區再造、亮點觀光等計畫的執行。","協助及支持縣政府規劃各項產業園區，及促進科技、工商業投資雲林。","敦促縣政府加速規劃雲林農特產多元通路管道，並建立農漁產品產銷儲功能設施以穩定供需。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0912d63e-fbea-4514-95c6-762145e69bfe","items":["打擊犯罪、治安維護;提升裝備、鼓舞士氣。","18歲公民、支持修憲;培力青年、自律負責。","高廠整治、環境永續;高廠宿舍、保障權益。","新台17線、貫通南北;改善交通、促進交流。","鼓勵婚育、育兒扶助;敬老扶幼、世代共好。","重職安衛、消防管理;活化場館、提升維運。","古蹟維護、文化傳揚;城市美化、生態觀光。","跨域合作、異業結盟;經濟文化、永續發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0931846a-55d0-4fbc-96f7-169ae43ec9ed","items":["推動竹南地方創生計畫/打造優質生活環境。","改善大埔重劃區停車與運動空間問題/活化生活機能。","加速醫療機構建置/改善醫療品質。","爭取高速公路橋下交通、運動設施與公園建置。","爭取生孕補助與公立托嬰學校普及。","督促縣府落實中小學國際教育2.0。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"098d06c4-a039-45be-a7d4-898de54609ca","items":["台中市成為開放進步城市","1､落實居住正義，建構完善住宅政策，人人住得安心。","2､守護世代正義，環境永續；落實減碳政策，發展綠色能源。","3､獎助生育、補助養育、強化托育；育兒政策升級，確保孩子自由自主成長。","4､擴大長輩生活層面，建構樂齡好生活；國中小營養午餐免費、營養加倍；廣設長照中心、公托、親子館。","5､捷運藍線市區地下化，儘速動工；建構完整捷運路網。","6､督促市府加速開發水湳轉運中心。","7､打通市政路延伸至工業區一路；督促市府打通漢翔路、福林路，串連新市政中心、水湳、中科、台中工業區。","8､督促市府扶植新創產業，發展策略產業，創造就業機會，提升薪資所得。","9､營造人本生活，增設人行友善空間；建設共融親善公園；打造人與寵物互動、互樂環境。","10､強化治安，建構警民聯防體系，通報系統電子化，加強處理治安事件能力。","11､營造台中地方文化特色，加強國際與區域文化交流，培養學童本土觀與國際觀。","12､強化社會安全網，照顧弱勢；檢討並放寬各項福利津貼申請標準，簡化申請手續。","13､市民導向的市政監督，市民才是台中市的主人。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0999d617-33da-4887-ab09-2505e4184fb8","items":["海洋生態永續發展","推動秋冬觀光賽事活動","教育語言多元化發展","優化長照、弱勢照顧"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"09e85e28-e73e-45e8-9e5e-fa6b3f0c3771","items":["成功阻擋全台最大殯葬特區設置五股觀音山。","爭取國道一號五股出口增設匝道直接銜接台64快速道路，恢復新五路正常車流。","加速辦理五股洲子洋公園闢建地下停車場。","爭取林口41B交流道改善工程，化解未來工一工業區交通衝擊。","爭取國道一號增設泰山大科一路北出匝道，縮短泰山市民行車時間。 我們用行動兌現承諾，新北民意哥Uber Service！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["past_achievement"]}}},{"claim_id":"0a5683c1-53c9-4379-bf9e-d65c0792d377","items":["協助婦女，爭取婦幼權益。","及家庭爭取安全平等的生活權利。","實社會福利政策，照顧弱勢家庭。","及其家族成立各項組織及活動，打造幸福城市。","施保留地檢討，維護地主權益，提昇地方建設。","助社區、社團、長壽會、義警、義消、守望相助隊、環保義工隊…，做好社區總體營造。","動，提升縣民文藝氣息。","育場所，增加公立托兒所，降低年輕人養育負擔。","動中心，推動豐富多元課程，讓長輩身心靈提升，快樂學習。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0a576b49-0007-48a2-8c98-ae88b9434d4b","items":["督促縣府招商建設須兼顧環境永續,輔導企業導入ESG並推廣 循環經濟與事業廢棄物減量。","協助推動活化苑裡工業區","協助推動苗南藝文中心","爭取提升通苑自來水普及率","爭取建構通苑老人運動安養設施","協助推動房裡溪、苑裡溪生態親水保育","爭取通苑增設長照復健治療服務空間設備","持續爭取通霄綜合運動場","爭取拱天宮媽祖文化園區","持續推動福興休閒農業區溫泉開發"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0ade5653-06ae-4c4f-a3eb-ef8c33fc74b2","items":["配合縣府繼續爭取高雄捷運延伸到新園、東港，延續上屆未竟政見。","爭取加速新園鄉鹽埔漁港、漁業遊憩、觀光綜合開發計劃。","協助農漁民建立生產履歷，產官學通力合作，打開行銷通路，增加農漁民收益。","爭取利用東港共和新村用地成立「青創園區」。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0aebeba4-4a0d-4380-96f5-d73254cb7836","items":["爭取設置「原住民勞工育才中心」。","爭取設置「原住民族語發展中心」。","爭取擴大「原民微型0歲起納保」。","爭取建置「原民多功能安養中心」。","爭取提升「原住民事務幹部津貼」。","爭取提高「原住民入住社宅比例」。","爭取增設「原民北區農耕示範區」。","爭取推動「原住民法律巡迴講座」。","爭取推動「一區一集會所及天幕」。","爭取推動「產業創生原青小聚堂」。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"0b478152-dfb2-4403-a98d-b834ccd56c02","items":["督促市政資訊公開，強化議會及公民監督功能。","嚴格要求工程落實查核驗收，杜絕「未驗收就敔用」。","嚴格把關棒球場缺失改善，避免市府重蹈覆轍。","推動舉辦「重大施政前期公聽會」，讓民間團體及市民充分參與。","把關追加預算合理性，杜絕市府浮報經費、重複施工。","監督各項活動辦理成效，納入在地參與並留下永續效益。","督促活化閒置資產，訂定合理租金及權利金。","監督改善道路標誌標線設計，降低交通事故率。","推動車速車向分流，逐步取消強制機車兩段式左轉。","督促新設人行道、整平騎樓，保障行人權益。","檢討大眾運輸現況，力促改善市區公車。","營造友善育兒、多元教育環境：加速推動建置社會住宅、公托中心。","營造友善育兒、多元教育環境：督促提高國中小正式教師比率，穩定教育品質。","營造友善育兒、多元教育環境：促進學校教育均質化，發展各校特色教學。","營造友善育兒、多元教育環境：推廣體育活動，督促設置運動場地及設施。","營造友善育兒、多元教育環境：督促改善市場環境，活化武昌街活動中心、中正台夜市。","營造友善育兒、多元教育環境：協助推動舊城復興計畫及都市更新，媒合空間及青創團隊。","營造友善育兒、多元教育環境：鼓勵藝文團體在地發展，以城市為舞台，創造舊城新魅力。","營造友善育兒、多元教育環境：推廣南寮漁村及造船文化，協助發展漁港觀光。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["candidate_introduction","heading_or_slogan"]}}},{"claim_id":"0b4dcae3-3772-44ce-b0dd-547845756f23","items":["爭取創設青銀共融平台，薪火相傳。","爭取釋放湖庫灌溉水源，嘉惠農民。","爭取振興新市沙美商圈，再創商機。","爭取開闢海上藍色公路，多元觀光。","爭取水試所遷移到田墩養殖區，善盡地宜。","爭取培養古蹟活化再利用人才，活絡地方。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"0b8d01dc-3ea9-4603-9e5b-76a8b13067c4","items":["成就永康交通好生活：監督捷運藍線一期儘速進入設計階段，並完善施工期交通疏導措施。","成就永康交通好生活：加快捷運藍線一期延伸線與深綠線進度。","成就永康交通好生活：推動捷運藍線與黃線串連，有效抒解永康至南科間交通瓶頸。","成就永康交通好生活：催促永康鐵路地下化進度與銜接整合。","成就永康交通好生活：持續增設小綠人行人專用號誌，人行道淨空，保障行人安全便利。","成就永康交通好生活：增設多元共融式停車空間。","成就永康交通好生活：路口車道動線暢流規劃。","成就永康居住好生活：持續增設青年社會公宅與準公宅租屋平台","成就永康居住好生活：要求市府確保住宅消防安全，購置住警器與定期安檢。","成就永康居住好生活：強化社區排水通暢，建構海綿城市，避免淹水之苦。","成就永康居住好生活：完善污水下水道接管工程並提高接管率。","成就永康休閒好生活：推動文教用地解編後之市地重劃設置休閒空間與活動中心。","成就永康休閒好生活：增設特色公園與推動舊有公園與學校遊憩區特色化。","成就永康休閒好生活：推動增設許縣溪、鹽水溪畔河岸歷史休憩空間。","成就永康休閒好生活：推動社區自主綠美化獎勵與補助","成就永康文教好生活：推動三嵌店歷史生態園區設立。","成就永康文教好生活：持續監督飛雁新村文化園區儘速完工。","成就永康文教好生活：推動獎勵社區認識鄉土文史教育。","成就永康文教好生活：推動本土語言教學普及與向下紮根。","成就永康文教好生活：持續增加公托、準公托以及準公幼設置以及寒暑假開班。","成就永康文教好生活：結合新總圖以及創意園區資源，建立永康文創基礎","成就永康社福好生活：衡量財政狀況持續爭取增加年長者健保補助。","成就永康社福好生活：強化弱勢家庭醫療照顧關懷。","成就永康社福好生活：推動弱勢家庭嬰幼保母與老年安養補助。","成就永康社福好生活：獎勵在地企業進用在地青年，就近為社會服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0b8d1d5b-a99c-4bd6-b110-ae33251a6539","items":["宗麒熱心專業協助民眾爭議調解，連續7年獲得「縣長獎」肯定，並多次取得全縣第一榮譽，7年多完成近400件調解案件，本於服務社會精神，持續協助民眾解決難題。","宗麒號召「萬丹青年軍公益團隊」近4年已協助逾250件弱勢家庭急難救助，將透過整合社福資源，協助遭遇困難民眾渡過難關。","爭取提高社會福利預算，扶助弱勢家庭及社福團體。","爭取弱勢家庭學童助學預算，讓學習資源沒有差距、起跑沒有差異。","整合行銷萬丹、新園觀光資源，串連東港推動觀光旅遊帶，活化地方創造就業。","爭取落實延長幼托「課後照顧」時間，減輕家庭照顧壓力，讓家長安心工作。","爭取經費改善社區老人福利、協助社福團體關懷弱勢長者。","監督縣政，爭取基礎建設，提升居住品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0c104d65-2ab2-4d3a-aae5-6ca364758899","items":["台灣中國、一邊一國,推動國家正常化,以確保台灣安全。","去除司法的黨國意識形態,扁案是政治案件,應予平反。","綠色生活:持續改善空污,裁罰應考量資力;提倡廢棄物再生及循環經濟;爭取重污染區居民每年免費健檢。","高齡安居:活化公有閒置空間,提供日照及長照使用,培訓足夠的照服人力,並普及社區照顧關懷據點。","弱勢保障:優化公車無障礙設施,爭取博訓中心課程增額,推動瑞智互助家庭喘息服務,建構無障礙友善環境。","育兒福利:提高準公共化托育中心之佔比,以減輕家長負擔,爭取增加臨托及夜托服務,鼓勵企業申設托兒設施。","便利交通:加速推動國道七號,保障居民生命安全,爭取興建小港機場車行地下道與南高雄東西向軌道運輸系統。","城市安全:推動危老重建工作,加強老舊建築線路巡檢,爭取擴大住宅用火災警報器補助對象,以降低事故風險。","勞動權利:健全勞檢,改善勞動條件,訂定違反勞基法之統一裁罰基準,獎勵勞工幸福企業,提高工會勞教補助。","沿海六里遷村權益:爭取最有利的遷村安置條件,儘速開放居民登記意願,並監督遷村工作後續執行成效。","監督財政:強化財政紀律,訂定還債計畫,積極招商引資,擴大財政稅基;落實青年租金補貼,防杜租屋黑市。","人才留鄉:增設高中產學合作專班,建構在地產學生態系;加速興建社宅,維護居住正義,重視鄰里基礎建設。","韌性城市:訂定極端氣候因應方案,執行區域排水通盤改善計畫,啟動前鎮河定期清疏與親水環境改造工程。","文化觀光:文化底蘊乃城市之靈魂,應加強歷史文化類觀光景點之多元行銷,開拓後疫情時代的國內外市場。","智慧創新:規劃5G+AloT智慧生活示範區,設置資訊科技局專責對接數位發展部,並提升城市數位治理能力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0ce50d85-a26f-484c-9e65-124be2a93f74","items":["護權益 顧民生：促請設立卓溪鄉老人長照中心，建置「醫養合一」照護機制，讓老人能在自己家鄉安老，讓照護更安心，實現長照在地化。","護權益 顧民生：促請改善原鄉照服員薪資及勞動條件、精進服務模式、強化人力培育及技職訓練，滿足原鄉及偏遠地區長照需求。","護權益 顧民生：後疫情時代各項產業環境變化，爭取加強原住民族亮點產業推升計畫，設置部落行銷據點，開展創新投資、創造經濟動能。","護權益 顧民生：後疫情產業發展策略：爭取配合輔助政策計畫鼓勵創業投資，促進產業升級，振興部落經濟發展，穩定部落生計。","護權益 顧民生：爭取智慧農業輔導團隊，設立部落－生技有機農場，增進部落種植技藝、農地畜產管銷技術，增加部落婦女及族人收入。","護權益 顧民生：爭取環境永續、產業創新、運用部落生態優勢環境資源，輔導部落種植高經濟作物，加強現有特用作物品質產銷多元發展。","護權益 顧民生：面對極端氣候環境衝擊，部落簡水及農灌水源，遭受暴雨沖刷，地質變動，年年水荒，生計深陷困境，促請政府勇於面對從速從優檢視水荒困境地區，全面改善部落人民民生用水。","護權益 顧民生：面臨高齡社會，爭取設立「原鄉國際慈悲關懷」部落，建置部落追求互信合力醫到宅 老終安目標，關懷長者、身障者、弱勢族群及社會邊緣人，提供完善的人性關懷服務。","護權益 顧民生：國土計畫法114年4月30日制度實施，促請重視原住民傳統領域土地劃設、適度調整及放寬農地變建地之變更、更正編定政策，並加強化社聚落居住環境土地，因應部落居住需求。","護權益 顧民生：促請加強督促申辦增劃編原住民保留地辦理進度與稽核機制，依法處理核配不實取得耕作權與所有權之土地，杜絕侵權。","護權益 顧民生：爭取設立平地鄉鎮山地原住民聯誼中心基地與設施，提供族人生活關懷照護聯繫、留鄉青年子女各技職資源培訓，民族文化技藝傳承學習與諮詢服務平台。","護權益 顧民生：為落實原住民族教育，運用脈絡戮力向上級爭取各項資源及經費推動原鄉教育、充實在地產業、地方教育、民族文化等資源。為促進花蓮縣原鄉農業部落產業發展，促請政府重視小農特殊化、強調品種特殊性，做好花蓮縣農業三品三專（品種專有、品牌專區、品質專業）讓花蓮縣的商品有更好的價值、奠定花蓮縣休閒農業發展的基礎。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0cfd0b19-30a9-4b2d-afb8-d0c2d30b46be","items":["審查監督縣庫，為人民看緊政府的荷包。","最完善的校園安全網，維護學童受教安全。","都自條例，因地制宜，放寬保護區建物面積。","國際藝術島活動經費，至少一半由縣府統籌使用。","獨居或窮苦老人的福利，及居家照顧等措施。","6歲的小孩政府來養經費，向企業界、慈善團體募款。","將自來水管汰舊換新，使居民安心飲用自來水。","要求將警察與消防人員編制足額到位，不可缺編。","求每個月定一~二天為縣民時間，由縣長一整天親自接待縣民陳情。","合立委，縣長，議會力量，共同要求中央政府早日恢復小三通。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0d26b8d1-9675-48eb-8a0a-4c2d1276d97a","items":["長輩有照顧：爭取65歲以上長者免健保費,日照區化,照顧更擴大。","爸媽有補助：提高生育津貼與托育補助,增設臨時托育中心以及公托暑期專案收托服務。","青年有幫助：贏地創新育成基地引進體創業課程,自體的時代,掌握流量就是幫自己加薪。","影視有發展：鹽水岸內重現台北榮町,國片拍攝首選,發展數位影視與鹽水觀光。","公園有特色：有特色有主題的公園,才能提高小朋友放下手機,願意外出遊玩的機會,也能增進親子間的互動。","寵物有公園：有養寵物的家庭日益增多,毛孩就如自己的小孩,給予毛孩們一個安全的運動空間,不僅能讓飼主安心,也能拓展飼主的社交圈。","農產要保鮮：爭取冷鏈中心,為農產品保鮮、調節產銷供貨,協助穩定農產品價格。","污水下水道：推動鹽水污水下水道,改善月津港水質,進而推動親水遊憩。","車站立體化：主張新營車站立體平台化,以引道改善平交道險境,以立體化爭取車站商業空間,帶動周邊商業經濟。","小黃變公車：台南已有20條小黃公車路線,目前只在白河,而東山、後壁、柳營、鹽水的長輩學童也非常需要小黃公車接送。","轉運站開發：新營轉運站周邊土地利用開發,帶動新營、鹽水一帶發展。","鐵道綠地景：提倡後壁烏樹林-白河仙草埔的軌道修復,推動觀光小火車,帶動後壁、東山、白河一日遊。","騎行來共享：汰換舊版TBike為UBike、引入共享機車,通勤觀光都可騎。","嘉南服務站：台南第一選區與嘉義縣緊緊相連,宣貿能夠成立服務站,服務兩縣市的案件,共創兩縣市的合作及建設。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"0db093b3-08f0-43aa-afa1-c52a3b0aacca","items":["1督促市府在111年年底前動工興建捷運黃線。","2督促市府向中央爭取捷運黃線前鎮區公所站延伸前至前鎮漁港港區內。","3督促市府加快興建社會住宅。","4繼續支持、關懷弱勢、艱苦人活動。","5督促市府保障大林蒲居民權益,並儘速完成遷村計畫。","6督促市府在113年年底前完成興建小港國民運動中心。","7督促市府加速增設公托中心與公共托育家園。","8督促市府正視長照人員不足的問題。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"0deabcfa-51d9-4c7e-afb3-fbd1b9725a8e","items":["推動失智長者公費安置機構。","推動校園安全及嚴格把關食安問題。","建議縣府落實兒童與青少年生活輔導與教育。","督促政府關照新移民居住學習及就業權益。","協助農村、漁村再生轉為經濟型地方生創。","兩性平權，提高婦女就業機會。","監督縣府落實校園掃毒工作，建立學童防護毒品機制，將毒品趕出校園，保障學生身心健康。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0e6c1ad4-9955-4873-b312-165ba1fb0092","items":["超越藍綠、民意優先、專業問政、守護弱勢。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"0e904b1b-f02c-48fc-bef2-ef9698b2c327","items":["發展智慧農業，推動農業轉型升級","保障農民福利，爭取各種補助。","導入智慧農工，提高農業產值。","加速及擴大農業廢棄物再利用。","活絡地方經濟，促進勞工就業","推動循環經濟，讓經濟環境雙贏。","推動產業園區蓬勃發展，吸引民眾返鄉就業。","結合地方特色，打造觀光新亮點。","重視偏鄉教育，照顧弱勢與關懷社會","修正《教師待遇條例》、落實《偏遠地區學校教育發展條例》，充實偏鄉教育的師資與資源。","持續推動關懷據點，強化在地照顧服務。","協助減輕弱勢家庭的負擔。","推動銀髮族適用的福利設備與服務。","打造友善生育環境。 衣鳯在任內關注智慧農業、循環經濟的發展，並致力於推動青年返鄉、產業升級，為地方爭取各項建設，為民眾爭取各種福利；衣鳯有能力、有信心，跟鄉親一起建立更美好的家園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"0ee33a15-1354-450c-9dc0-6966842e8fb2","items":["落實長照2.0與關懷據點，讓長者受到完善的照顧。","爭取增設國軍桃園醫院觀音分院、增設關懷站。","積極爭取設置市場。","爭取觀音區各國中、國小學雜費減免。","提高教育資源，充實軟體、硬體建設，縮短城鄉差距，提升孩子競爭力。","爭取觀音區重要道路之瓶頸道路拓寬與打通。","重視與提升社區發展協會、環保志工隊、守望相助隊之福利。","行銷觀音區觀光產業、協助在地農民推廣農特產品。","爭取埤塘設置步道及環境綠美化，讓民眾有休閒及運動的地方。","監督市府，貫徹環保法規，建設乾淨、美麗家園。","監督市府，落實食安、治安、公安檢查，讓觀音成為一個宜居安全的城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"0f3515d1-ee99-40aa-bddc-7dc3f96a9aad","items":["督促市政府提出並執行有效的後疫情振興地方經濟方案。","推動社宅倍增計畫，協助青年安心成家。","擴大生育補助，推動能生敢養政策。","強化長照2.0能量，增設社區據點及日照中心。","擴大大里都市計畫，增加公共設施用地，改善大里生活環境。","推動霧峰都市計畫，打造霧峰為綠色觀光文化城，活絡地方經濟。","加速開發夏田產業園區與塗城產業園區，解決中小企業缺地問題。","全面盤點大里及霧峰學校及公家閒置空間，爭取廣設停車場","利用大里、霧峰河川地，開闢水岸步道及綠地公園，並設立運動休憩場。","爭取大里德芳路一段(省農會至東榮路)拓寬工程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"0f7e1f38-e25d-49de-ad51-b97e1d6da705","items":["爭取地方道路農路、排水溝、擋土牆工程。","配合縣政府：農工大縣政策，發展觀光，提升農特產經濟效益。","傾聽民意反應問題，解決問題。","監督縣府政策執行，注重社會福利政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1142f577-a843-4dda-a47b-6039808f2490","items":["高屏溪河川公地養殖合法化有條件開放，輔導魚塭養殖業者取得圍築魚塭使用許可。","易淹水地區水患治理計畫「武洛溪排水系統」引進武洛溪之水源為高屏溪支流隘寮溪之入滲伏流水，搭配地表水淨化的運用，可形成「地表水與地下水聯合運用模式」。","高樹及里港地區砂石車專用道建設計畫－「拓寬載興村至里崇路廢鐵道銜接台3線及台22線」施作基礎改建及擴建，拓寬之行車路線為現行砂石運輸業者習慣行經之路線。規劃將現有廢鐵道8米道路拓寬為20米道路，向西南由出里港市區外之台3線接往國道3號，向西由台22線接國道10號。得以紓解高樹鹽埔地區砂石運輸業者交通運量。","期盼建構屏北地區直捷聯繫路網，新闢國10里港至新威大橋道路。","維護本縣天然資源降低衝擊地方景觀，爭取土石採取景觀維護特別稅回饋造福地方。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1168d42e-c986-4afc-bb61-0bacedcb761e","items":["爭取65歲以上長者免繳健保費，使老有所終。","爭取國中、小學生營養午餐免費，使幼有所長。","爭取提高生育補助第一胎3萬、第二胎以後（含2胎）5萬，鼓勵生育，減緩少子化趨勢。","爭取免費提供嬰幼兒尿布，結合生育補助，減輕年輕父母育兒壓力與負擔。","爭取永康特色公園遊戲場，並加速推動規劃永康區國民運動中心建置完成。","爭取興建「資源回收細分類場」，解決後端垃圾問題，落實資源回收與循環經濟政策。","持續推動於二王公墓整體開發案中的公園體育用地，並已爭取二王、三合、五王里聯合活動中心，監督盡速完工。","持續監督燕祝所爭取鐵路地下化延伸至永康站之工程進度與施工品質，並推動新市- 善化路段立體化或地下化，解決道路壅塞問題。","持續監督完成大灣區域雨水截流至鹽水溪分流工程，紓解三爺宮溪主流量，徹底解決永康區淹水夢魘。","爭取太子廟中排整治工程（3.8 億），紓解崑山、南灣、東灣、仁德區太子等里及崑山科技大學週邊區域淹水問題。","爭取永康區中華路CF幹線第三期新建工程（經費7000 萬），來解決成功里、中興里長期淹水及老舊箱涵問題。","爭取補足臺南市警察與消防人力編制員額，並強化同仁們的應勤裝備，且要求中央與地方配合，確保同仁執勤地方治安與救災救護時的人身安全。","持續爭取編列鄰長每月2千元工作協助費，來感念體恤鄰長協助推動市政之辛勞。","加速推動青年社會住宅，紓解青年購屋經濟壓力，來落實居住正義。","加速推動多元創業平台，爭取職訓種類及名額增加，解決身心障礙者、中高年及婦女的就業問題。","加速推動動保處「動物之家」的環境規劃更加妥善，並加強犬隻源頭控管，減少流浪犬隻攻擊事件發生。","加速推動托育人員( 保母) 落實證照登記制度，並強化托育環境監視器要零死角監測，杜絕虐童事件發生。","加速推動永康車站北側產業專區的市地重劃地規劃，美化地方市容。","加速推動大成長城搬遷案，還給周圍居民好空氣，提升當地生活品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"1195085e-e833-4209-a9e0-8750daef2b44","items":["已爭取平林里辦公處晴雨棚及地面修繕工程（已設計發包）。","已爭取162+300公尺與98路口改善工程（施工中）。","專業問政：監督政府施政、降低城鄉差距、落實均衡發展。","婦幼代言：爭取婦幼福利、關懷幼童青少年就學及身心健全發展。","關心老年：促請政府關懷獨居老人心靈健康及心理輔導。","關懷弱勢族群：關懷新住民生活適應、輔導單親家庭、身心障礙者心理成長。","農民代言：野溪、擋土牆、堤防施作及整治、灌溉溝渠、產業道路改善，以利農產品運輸、增加農民收入。","持續爭取國中、小學軟硬體設施，促使學童德智體群均衡發展。","加強大埔美工業區釋放更多職缺，讓北漂青年能返鄉就業，照顧年邁長者，共享天倫之樂。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"11a86b0f-f229-4b3d-b04a-a31838791088","items":["民生-空氣污染廢棄物傾倒專責小組科技執法取締","幼兒-市府優先提供0-5歲公托及公幼服務","交通-推動高鐵橋下道路工程串連嘉義、新營到南科","農業-簡化農業補助申請減輕農民負擔","經濟-溪北招商引資打造電動車產業聚落","運動-爭取全民運動館維護改善現有運動空間","長者-逐年提高長者健保補助費用至一萬元","警消-提升警義消權益降低工時增補人力","休閒-持續增設特色公園和親子育樂空間"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"11b48057-0fce-4122-b59b-8b946d474533","items":["୯ၰ 2 ဦܿՋୁၰၡǴ‫ׯ‬๓ϖΰၡαًࢬǶ!! ġ ġ ໒Јၭ൑Ƕ!","୯ၰ 2 ဦླྀఘᓐҽࢤଯࢎ‫ܗ‬ቨीჄǶ!! Ɍ࡭ុ௢୏࠼ৎЎϯђᙬߥӸǴ!","Ӏܴ΋ၡᆶയճΖຉ఼ࢰǶ!! ġ ġ ᒪౢߥӸǶ!","΋ၡᆶԋфΖၡ఼ࢰǶ! ѤǵࠤѱሽॶᆶऍᏢ;!!","ጕඹжၰၡǴ79!‫ז‬ೲၡ‫ݓ‬ഊၡαௗԮчࢤǶ!! Ɍပჴ೿ѱीฝǴଯԡࢉԖྟ֙ౢ཰ᇻᚆՐӻ୔Ƕ!","ࢤѠ៓ᕵೣጕଯࢎϯǴϯှԮчܿՋ୔౟ᓍǶ!! Ɍһቺख़Ⴤ୔ǴಷལчၡӛчѺ೯‫ډ‬ስξྛ൒ٛၡǶ!","ԮчОًઠՋୁҬ೯ǴӾঢ়ਔࢤቚуОً੤ԛǶ! Ɍᅱ࿎ϦӅπำࠔ፦Ǵ௢୏ಃΟБϦ҅ൂՏᇡ᛾Ƕ!","Ɍပჴӝ‫ܕݤ‬኱Ϸᡍԏࢬำ TPQǴගϲπำࠔ፦Ƕ!","ࢂಥ೦‫ޑ‬໘ఊǴख़ຎ১༈‫ޑޣ‬௲‫ػ‬ᐒ཮Ƕ! Ɍഹ৲୍ܺǴྣ៝ԴύߙѴǴᡣ΢੤௼ӼЈπբǶ!","UFBN ௲Ꮲ‫ݤ‬Ǵ่ӝ౛ፕᆶᔈҔǴࢲϯ௲Ꮲ‫ݤ‬Ƕ! Ɍु‫ۓ‬ԾᒤၭӦख़ჄቲԦН௨‫ܫ‬ᆅ౛చ‫ٯ‬Ƕ!","௲‫ػ‬ၗྍǴගϲ௲Ꮲࠔ፦Ƕ! Ɍᑈཱུቩࢗᑜϣख़Ⴤ୔ԦН௨‫ܫ‬ᆅ౛ᆶᆢៈǶ!","નᎦǵউ౛ᆶၰቺ௲‫ػ‬Ǵ୻ᎦࡘԵှ،ୢᚒΚǶ!!ϖǵඵችᔈҔ;!","ख़Ⴤ୔࡭ុೕฝቚ೛୯ύ୯λཥᏢਠǶ! Ɍ௢ቶ BJpU)ඵች‫ނ‬ᖄᆛȑǴЋᐒ BQQ ඵች୍ܺǶ!","੝௲.Ԑᕍ)1.7 ྃ*୍ܺǴံ‫ى‬Ԑᕍၗྍό‫ى‬Ƕ! Ɍ၂ᒤคΓԾᎯϦًၡጕǴ໽ғඵችε౲ၮᒡ‫س‬಍Ƕ!","ၭ੝ౢࠔԾᎍ୯ύλᏢᔼᎦϱᓓǶ! ɌඵችϦً‫س‬಍่ӝ ZpvCjlfǴගϲϦً٬Ҕ౗Ƕ!"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"11bd364e-a3ec-4c5e-ae0b-044412760547","items":["做一個『看得到、找得到、服務周到』的專職市議員。","活化原住民族事務委員會之功能，共創友善和諧之府會良性溝通模式，以順利推動原住民族事務。","爭取青年族群發展資源並輔導就業，獎勵及培訓原住民人才，強化生存競爭力。","爭取原住民表演藝術人才的表演空間，爭取原民專屬建設空間，並增加原民商品曝光度，活出原民尊嚴。","促進原住民產業品牌化，輔導原鄉精緻農業產業升級及輔導認證。","教有方\"落實原住民教育精神、帶動並提昇原住民教育品質與競爭力。","居有土，行有路\"敦促市府成立專案小组改善安全居住與交通問題。","樂其業\"爭取大臺中原住民勞工應有工作權益的保障並加強並改善原住民族人法律扶助的功能。","安其養\"加强原住民婦女及家庭生活協助，尤其讓年長者有受到關心及照顧。","强化原住民族族語的保留與傳承，以及加強原住民民族文化的發展。","加強原住民族醫療保健及原鄉後送醫療的改善。","爭取大臺中原住民休閒運動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1211321f-374a-4653-b029-8e4096846471","items":["加強提升婦女地位、保障婦女工作權益。","幼兒就學補助，爭取向下延伸到3歲。","積極推動增設公托班，減輕年輕家庭養育負擔。","加強監督路平建設，給機車族和開車族駕駛安全回家的馬路。","公共場所與交通樞紐地區增設免費WiFi。","公辦銀髮族安親班，廣設社區關懷據點，豐富和安定老人生活。","增加中、小學圖書室、圖書收藏。雙語圖書列為優先增加項目。","加強勞工安全監督，避免勞工災害。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"12549bfc-58f9-49ee-9cb6-ab62892627fd","items":["為孩子打拼 ．守住營養午餐水果補助 ．潭雅神三區設置親子館 ．基層運動員更多訓練資源 ．爭取新闢公園綠地、設置共融遊具 ．神岡高工：改善體育館地板鋪面、戶外籃球場夜間照明、 活動中心座椅 ．社口國小：提早裝設冷氣 ．神岡國小視聽設備、外圍牆改善;神學堂共讀站 ．圳堵國小設置無障礙電梯 ．岸裡國小運動場鋪面改善 ．文雅國小校園遊具改善 ．大雅國小冷氣電力改善 ．潭子國中運動場鋪面改善、活動中心影音設施 ．頭家國小周邊路面改善、後門動線改善","為青年發聲 ．提案修正〈台中市社會住宅出租辦法〉 ．要求市府重視低薪高房價","改善交通 ．潭雅神超過40站YouBike2.0 ．推動國四豐潭段工程進度 ．潭雅神超過40處路面改善 ．神岡庄後里增多處公車站 ．潭雅神多處設電子站牌","產業發展 ．加速潭子聚興產業園區點交、改善聯外道路 ．推動神岡豐洲二期、擴大神岡產業園區 ．推動設立大雅學府商圈 ．加速未登工廠臨登納管 ．推動豐潭雅神都市計畫","為長者請命 ．神岡庄後社區活動中心改建 ．大雅秀山社區活動中心照明 ．媒合社團捐贈潭子家福社區全新電視 ．協助重啟神岡里C據點","專業問政 ．每年抓出十多億煙火式預算 ．為基層運動員爭取訓練資源","潭雅神綠園道、新田登山步道 ．綠園道沿線多處設施改善 ．中科公園溜滑梯廣場旁公廁 ．社南廣場設置火車頭遊具 ．媒合企業認養綠園道公廁 ．新田2、3號登山步道修復工程"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"12aac061-8b61-426e-bb95-d227dab11091","items":["善盡代議士責任與義務—賡續全天候專職服務，落實監督縣政、專業問政，提供優質效率第一的服務。","配合中央民意代表爭取永久屋土地所有權、督促屏東縣政府修正永久三方契約，找回居住正義。","督促屏東縣政府積極解決永久屋產業發展及空間不足之建築管理問題。","敦請屏東縣政府成立青年政策諮詢委員會或青諮顧問，俾利因應公民權年齡下修等相關青年參政之權益。","主動關懷青年勞工相關權益及福利議題，保障青勞未來步入中年或退休後等相關補助及津貼。","爭取「來義鄉青年聚會所」在部落之心；辦理相關體育賽事，督促縣府編列體育獎勵金，改善體育環境及設施設備。","賡續配合「醫療．長期照顧服務…」等各項完善照顧服務一體化—落實在地安老、關懷高齡者福利政策。","爭取提高重陽節各年齡層敬老禮金，重視各文健站，日托及樂智關懷據點需求。","敦促縣府善用貼心巴士，結合鄰近醫療網—推動本鄉及都會區長者居家醫療輔導計畫。","力推「地方創生」、整合鄉內及都會區「觀光產業」，發展各部落特色景觀主題，發展藝文亮點，培育在地藝術人文青年，協助提供舞台及展演機會，以在地人文為特色重點培育及專業設計。","爭取每年辦理大型產業推廣活動，結合地方文化特色及行銷推展本鄉農特產品，爭取本鄉與都會區部落產業市集，促進城鄉社會發展接軌。","家園安全：督促縣政府加強原居地部落安全問題，嚴格列管追蹤各項申請及陳情案，保障鄉民各項法定權益。","家園安全：家園安全—賡續向中央爭取各項建設經費，落實執行縣議會提案及陳年案件，以解決鄉民需求。","家園安全：爭取屏東縣政府擬定「潮州人工湖回饋金編列及運用要點」，爭取水資源源頭之來義鄉民最高權益及福祉。","家園安全：勞工保障—逐年寬列預算造福在外發展鄉親，關懷失業勞工就業權益，協助改善勞動環境。","家園安全：農業補助—敦促各項禁伐補償金、造林獎勵金、天然災害救助，應以最快速之行政程序處理，重視及關心鄉民重大權益與需求。","家園安全：文化教派—爭取各部落傳統民俗文化活動及各宗教預算，強化鄉內傳統民俗文化工作及社區功能。","家園安全：重視軍警消—賡續關心原鄉軍警消公教子弟，寬列預算資源分配；補助各校教學環境及基礎設備，落實政府全民照顧的理念。","家園安全：法律扶助—提供法律諮詢，協助解決鄉親民、刑事、勞資糾紛等案件。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"12f496b9-03a6-472c-acff-aa13e012cbda","items":["監督縣府落實原住民基本法及各項福利政策。","關懷原住民中的弱勢團體使之能有更好的生活保障。","催促縣府迅速制定原住民相關產業發展計劃。","協助發展原住民部落的文創產業，讓商品更具競爭性，並能打入市場。","督促縣府重視原住民教育的未來發展並讓每位原住民的下一代接受良好的教育。","重視原住民的傳統文化、語言、技能及祭典儀式的傳承。","捍衛有關原住民各項權益及政策，創造原住民的新未來。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1324dba3-bd10-4851-95cf-ec4e6ac6cfca","items":["國土規劃,擴大花蓮土地利用價值及經濟效益,吉安鄉東側海岸線土地規劃為風景休閒區。","大花蓮都市計畫,擴大吉安鄉、花蓮市、新城鄉都市計畫,以利地方繁榮發展。","國土計畫新增宗教用地,補辦寺廟登記,比照工業輔導法辦理,以利宗廟納管與輔導。","因天候異常,災難頻傳,基礎建設非常重要,地方防洪工程及排水系統,應確實規劃並爭取經費辦理。","為照顧農民,增加資材補助,協助農業加工升級,鼓勵青年返鄉投入有機農業生產,扶植有機農業並結合觀光休閒,增加農民收益。","落實照顧婦女、老人、殘疾、低收入戶及弱勢團體,結合社會資源,爭取閒置空間,成立老人日托中心,提供完善照顧及加強各社區關懷福氣站功能。","黃馨期待以豐富完整的資歷及經驗,繼續營造花蓮,讓花蓮成為樂活友善、安全、養生、觀光、休閒的魅力城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"13376001-c32f-403b-bced-e4c7531e110c","items":["教育政策：加強落實原住民族語言、文化復振，廣開原住民族語言教學課程，編列族語、體育及樂舞、技藝人才培育獎金，藉以鼓勵原住民語言、體育及樂舞、藝術等專門人才，並建構完善的原住民族教育知識系統及教材以利永續傳承。","就業暨經濟產業政策：督促政府落實原住民族工作權保障法，提供原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，培育、輔導原住民青年就業及創造中高齡二度就業之創業機會。爭取發展原住民傳統技藝，多點設立原住民文創商品行銷據點，打造屬於原住民族文創產業，以改善原住民經濟，提升就業機會。建置原住民勞工就業、職能輔導、勞資協調、法律協助與溫暖陪同等全面性的服務平台，讓族人安心就業與生活。","社會福利政策：爭取設置都會區原住民族文化健康站及各區老人日間關懷站、長青食堂等。促政府落實原住民福利政策，積極爭取原住民各項社會福利資源，法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。","文化傳承政策：持續爭取原住民族多功能會館前方建構原住民族多元文化主題公園。強化原住民族文化發展，並爭取提高編列原住民族教育、文化、歲時祭儀、體育、樂舞藝術發展等活動經費，增列相關預算以保存發揚原住民族傳統文化，提昇原住民族發展協會、社團辦理活動能力等。","族群共融政策：持續要求辦理宜蘭縣都會區原住民遷移史紀錄計畫，以利未來列入宜蘭縣史，補足都會區各原住民族群遷移至宜蘭的文史紀錄。建構安全、便宜及便利之租屋服務平台，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。保障縣內各住民共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"139336e5-2aec-4003-83b5-dfe428c6f362","items":["爭取經費持續建設更進步、更現代化幸福冬瓜山，讓冬山再次偉大。","育兒補助：爭取提高生育補助及嬰、幼兒的托育補助經費，增加公托育名額，減輕年輕人的經濟壓力。","推動品格教育：培養良好的品行，從教育做起，啟發孩子的智慧，養成良好的習慣；「以德為成人之本、以智為成才之源」，是千古不變的法則。","活化在地經濟：結合社區營造、社會企業與休閒農業，創造經濟發展與就業機會。","樂活高齡城市：爭取經費協助增設樂齡學習中心、老人日托班、長青食堂，讓老人生活快樂有尊嚴。","完備交通系統：爭取義成、梅花、梅林、富農計畫道路開闢，完成冬山環狀交通網，設立交通資訊網路，並建請國五交流道應縮短工期儘速開闢通車。","進化建設：全力協助綠色轉運亮點計畫之執行，建設一個美輪美奐的冬山城市成為現代化景點，讓冬山亮起來。","完善社福機構：建議增設長照機構（含身心障礙者），提供需要照護者最好的安身之所。","反對家族干政，廉能宜蘭縣政。","支持公民權下修18歲，擴大青年參政意願，鼓勵共同參與公共事務，讓台灣更好。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"13ff6899-562e-4da5-a6cb-b2bcfcd88b51","items":["積極爭取綠島鄉的觀光資源,改善碼頭動線,給鄉民和遊客一個友善的搭船空間。","為漁民爭取最大的福利,為弱勢族群爭取更多的資源。","為偏鄉醫療爭取最大的、最好的醫生及醫療資源。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"14842f25-3971-4845-ac28-79fdc3e6281c","items":["安全優先：將建立完善高雄捷運路網。","安全優先：將爭取中央經費，改善港工業區周邊交通道路環境。","安全優先：將持續爭取海空雙港建設，提升高雄港城市國際化形象。","產業優先：將推動亞洲新灣區計畫，打造智慧科技、半導體及國際金融商辦重鎮，吸引國內外投資、企業人才深耕高雄。","產業優先：將續推動海洋產業，發展都會特色海洋、漁業觀光、遊艇郵輪等。","產業優先：未來將持續建設新旗津，打造海洋觀光大島。","環境優先：將促中央地方合作，多管齊下，推動空污減汙、淨零碳排目標，打造永續產業發展及宜居家園。","環境優先：將確保居民權益、落實居住正義。","環境優先：將促中央、地方、企業攜手合作，增加城市綠地公園，改善空污，打造健康美麗花園城市。","環境優先：將持續盤點閒置土地空間，促中央地方民間合作，興建停車場、室內運動場館等公共空間，提升市民生活品質。","環境優先：爭取選區高中職國中小各項建設超過2億元。","環境優先：將爭取中央支持高雄治水防洪設施，有效分配資源因應，維持社會經濟正常運作。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"14a8e29d-86c3-4d41-a9fc-6433a1bf873c","items":["縣政，力推地區平衡發展。","財源－金酒公司穩健永續發展，維護鄉親福利。","聲，維護社會公平正義。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"14e894a7-ef13-403f-94ac-b21d119e87f6","items":["推動桃原新政福利2.0升級。","爭取成家基金補助，減輕青年負擔。","依據桃園市原住民族自治發展條例，持續督促市政府迅速擬定相關子法，以落實保障原住民族政治參與、經濟發展、創業就業、教育文化、社會福利及居住權益。","整合原住民族權益服務機構，設置原住民族專責諮詢專線1994；爭取成立原住民就業人力站，由單一窗口整合局處資源，主動聯繫、輔導、追蹤，訓用合一協助青年族人就業。","爭取提高考取技術士證照補助。","推動原住民族經濟產業服務平台，協助原住民族取得創業基金與事業維持扶助金之貸款或補助。","積極盤點閒置空間設置文化健康站，並培力長照相關人才投入長照事業。","協助原住民族長者發揮銀色智慧，建立青銀族群互為導師制度，協助文化健康站轉型成為青銀共榮共好基地。","全面推動國中小雙語教育，提升國際競爭力。","建立體育人才資料庫，協助輔導轉職、創業，擴大專任教練員額，鼓勵投入基層三級體育教育。","爭取提高事務幹部工作津貼，提升族群領袖地位。","提高各區原住民生活教育協進會預算，辦理各項活動。","持續爭取設置集會空間及天幕廣場。","加速完成原住民專屬社會住宅，並提高社宅原住民優先戶申請比例。","支持18歲公民權。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"1540064b-8b77-4e5b-aaae-c47e431a74e0","items":["發展工商：推動嘉義科學園區、馬稠後產業園區、水上南靖產業園區加速開發，帶動嘉義縣全面發展。","農業升級：督促縣府持續提出智慧農業計畫，輔導農民增加農產品品質、產量，強化品牌、行銷世界。","促進觀光：督促縣府運用水上、鹿草、太保豐富人文與自然風貌，規劃觀光軸線亮點，吸引遊客商機。","強化建設：針對鄉親所需地方建設如道路修建、防洪排水、公園綠地，積極協調各政府單位全力解決。","完善社福：關心年長者、婦女、兒童及弱勢民眾的社會福利需求，督促縣府完善措施，擴大服務資源。","清淨家園：督促縣府積極改善影響縣民健康的空氣、水、廢棄物等各項污染問題，提升生活環境品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"156e4558-0a6f-42e0-8672-69c73ad12490","items":["吃在地、食當季，支持縣府推動營養午餐免費，鼓勵學校採用在地食材，爭取提高一成餐費，讓學童更均衡營養","推動企業認養從小學課後照顧，讓家長減輕負擔、安心打拼","增加閱讀場域，延長圖書館閉館時間至晚上8點","推動親子共享、共讀、共學，藉由陪伴增進親子關係","維護校園安全，爭取校園守衛","永續農業：因應淨零排放政策，支持推動循環農業、減碳環保，將農業剩餘資源、廢棄物再利用，達到減碳目標","永續農業：推動景觀作物專區，以維護農田地力，結合在地觀光產業，提高農田利用","永續農業：爭取增加幸福長青卡使用品項，如搭乘計程車等交通工具","永續農業：爭取搭乘公車距離6公里內免費","永續農業：結合民間產業，提供關懷據點共餐之水果品項","永續農業：推動學校社區化，妥適利用校園公共空間","永續農業：爭取設置共融式遊具，滿足孩子的遊戲需求","永續農業：爭取警消軟硬體設備的更新或增設","永續農業：提升警消保險等相關保障的加強","永續農業：輔導新住民融入在地文化，爭取辦理各項交流活動","永續農業：推動整合公寓大廈成立管委會，加強大樓公共安全","永續農業：督促公共空間無障礙設施檢核，落實環境友善空間","永續農業：配合長照2.0審視閒置空間，廣設巷弄長照站","增加社區長青運動設施及空間：輔導社區增設關懷據點，讓銀髮長輩能在地樂活、在地安養","增加社區長青運動設施及空間：深耕文化，爭取更多藝術家展演平台，拓展藝術能量","增加社區長青運動設施及空間：推廣傳統工藝技術，傳承並向下扎根","增加社區長青運動設施及空間：監督管理文化資產，保存原有的地方紋理","增加社區長青運動設施及空間：支持縣府推動老屋活化政策，守護歷史建物","增加社區長青運動設施及空間：輔導廟宇紀錄其文化、並發展一廟一特色，落實民俗的推廣與傳承","增加社區長青運動設施及空間：爭取興建國民暨兒童親子館及運動中心","增加社區長青運動設施及空間：改善現有運動環境、完備各項體育設施","增加社區長青運動設施及空間：增設社區長青運動空間及器材","增加社區長青運動設施及空間：推動全民運動，舉辦各項類別體育季","觀光經濟：推動央廣打造為文創園區及觀光市集，造就地方就業機會","觀光經濟：輔導特色社區，增添觀光深度、並開拓鄉村觀光商機","青年發展：支持青年創業與輔導返鄉規劃","青年發展：整合各方資源，提供青農、青商、青文（文史工作）最有利輔導與輔助","青年發展：爭取福鹿秀設立青年住宅","青年發展：推廣輔導飼主良好的飼養習慣，打造人與寵物共好的環境","青年發展：協助推行下鄉絕育，推動毛小孩結紮，並鼓勵認養不棄養，以解決流浪動物問題","熱忱服務：協助醫療、急難救助等相關事宜","熱忱服務：服務處提供律師免費法律諮詢"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"157e02c1-0d5c-4c65-bf8d-4bfe2e09750b","items":["疫後拚經濟，爭取萬華專案振興。","結合青山王祭，打造城市觀光亮點。","改造16座特色公園，爭取2座河濱兒童遊戲場。","捷運小南門站雙向手扶梯，水源永春天橋無障礙電梯。 未來四年，讓我陪你。台北值得更好 我陪你 都市再生","發展街區經濟，串連在地商圈店家。","都更審查加速，都市設計導入美學。","老屋拉皮裝電梯，政府介入輔導、增加補助。","社宅興建4年4萬戶，每戶租金降10%。","我陪你 永續生活：永續環境，因應氣候變遷，打造綠地戰略。","我陪你 永續生活：營造親水空間，找回城市親水記憶。","我陪你 永續生活：廣設社區親子遊憩室，促進兒童身心發展。","我陪你 永續生活：擴增特色公園遊具，分齡專屬遊戲場。 我陪你 育兒減壓","我陪你 永續生活：坐月子有補助，產婦由政府一起顧。","我陪你 永續生活：提供緊急幼兒臨托服務，減少預約限制。","我陪你 永續生活：優先開設2歲專班，增設公立、非營利幼兒園。","我陪你 永續生活：促進兒少心理健康，專業諮商團隊入校園。 我陪你 青銀共好","我陪你 永續生活：活動中心伴唱機版權，政府公費支應。","我陪你 永續生活：增設日照中心，延長服務時間。","我陪你 永續生活：主張18歲公民權，支持修憲複決案。","我陪你 永續生活：創設青年參與式預算，公民參與扎根。 我陪你 文化升級","我陪你 永續生活：催生台北文學館，打造國際文學基地。","我陪你 永續生活：活化中正萬華市有文資，轉型藝文據點。","我陪你 永續生活：支持劇組拍片，打造影視觀光景點。","我陪你 永續生活：催生台北ACG政策，促成動漫創作聚落。 我陪你 運動台北","我陪你 永續生活：大巨蛋保障打職棒，監督市府與遠雄議約。","我陪你 永續生活：發展台北街舞文化，首創專責窗口。","我陪你 永續生活：輔導管理運動場館，保障消費者權益。","我陪你 永續生活：推廣社區銀髮運動站，一里一據點。 我陪你 友善城市","我陪你 永續生活：動物之家收容數增加，提升犬貓照顧品質。","我陪你 永續生活：成立寵物專責單位，增加寵物長照機構。","我陪你 永續生活：性別友善城市，尊重多元平等。","我陪你 永續生活：人本交通，增設無障礙人行道、退縮行穿線。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"15c02d94-beb4-43d5-982d-e5c1d80758b7","items":["推動新竹市成為有豐富文化內涵的科技智慧城","文化、教育：監督總圖書館興建進度，增設圖書分館","文化、教育：降低代課教師比例，建立各校特色教學","文化、教育：增加關埔地區國中小學容量，檢討學區劃分，強化居住查核，落實就近入學","交通運輸：檢討公車路網，建構更便捷的公車系統","交通運輸：優化交通號誌，建構全市智慧交通體系","交通運輸：改善慈雲路園區周邊交通，設巡迥公車","青年、婦幼、長者：開辦平價公辦民營日、夜間及假日臨托","青年、婦幼、長者：補助私立幼兒園改善設施、設備","青年、婦幼、長者：東區增設親子館，辦理幼兒親子課程","青年、婦幼、長者：提高學童營養午餐費，增進學童健康","青年、婦幼、長者：扶植青年創業，增設長者終身學習場域","都市發展、公共建設：加速興建光埔關埔地區二樓空橋系統","都市發展、公共建設：加速興建東區污水下水道，提升接管率","都市發展、公共建設：監督檢討65億大車站、上千億輕軌計畫","都市發展、公共建設：改善行人環境，健全無障礙人行道及學生通學步道，建構自行車友善環境","都市發展、公共建設：加速關埔二期，並闢建市民的運動公園","都市發展、公共建設：政府主動輔導老舊宅、老商圈之都更","衛生、醫療：優化兒童醫療品質，擴建台大浦雅院區","衛生、醫療：強化銀髮照護體系，增設日夜假日托老","衛生、醫療：社區設置體適能設施，聘請教練指導","動物福祉：落實寵物源頭管理及零安樂死，推廣TNVR，重罰任意棄養"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"161a93e6-b9ca-4319-a32c-85dc48b62903","items":["督促市政，為民喉舌，落實地方建設。","推動福利計劃與社會救助，關懷弱勢族群。","爭取65歲以上老人免費裝假牙之政策。","爭取政府機關的閒置空間活化，讓市民的生活品質提升。","重視教育問題，並重視托育整合措施，促進教育向下紮根。","提升住戶生活品質及經濟發展，創造商機。","監視器全面總體檢，強化陰暗巷道錄影，並設立「本區道路全面治安連線錄影」防制犯罪標示牌。","積極推動淨化、綠化、美化運動，消除髒亂，重視環保，提高生活品質環境。","以民意為依歸，做專業專職議員，爭取民眾權益及福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"16831738-2d5e-4e5d-a752-eba64e5b57a7","items":["爭取生育補助、育兒津貼123：第一胎2萬、第二胎3萬、每月補助2千至三歲。","鄉鎮特色將現有公園規劃或新建，設「親子共融寵物公園」。","持續爭取設立國民運動中心、棒球場（提供青少年運動、老年人活動、親子館、表演場館）。","爭取敬老愛心卡可搭計程車、國道客運、縣內合作之醫療院所就醫費、付健保費。","加強推廣各鄉鎮老街商圈及社區產業、市場進行創意營造辦理促銷活動，搭配在地特色與節慶活動刺激消費活絡商圈。","改善市區停車問題，督促設立部分路段路邊停車收費。","爭取縣府推動單親、弱勢兒童課後安親；公辦民營托育中心。","關注偏遠產業道路、邊坡堤防、水圳護欄之修建與維護，保護居民與農民安全。","爭取青創基地，鼓勵南投青年留在家鄉，發展文創產業，創業築夢。","爭取國中小學軟硬體設備更新及補足，免費校外體育教學活動。","針對重要道路及易肇事路段加裝監視器及交通號誌改善，以促進交通安全及民眾生命財產的維護。","優化與廣設監視系統，治安加強，提升警力配置及裝備。","要求縣府配合內政部推動「宗教團體以自然人名義登記不動產處理暫行條例」，加強協助宗教團體輔導其土地使用合法化。","加強鼓勵宗教團體辦理習俗推廣及傳統祭儀文化活動，以傳承正向信仰教化人心。","增加原住民及新住民、客家族群等多元文化活動辦理，促進族群融合，同時強力推動性別平等、反家暴與反詐騙。","推動「幼托保母、長照及看護服務人力管理平台」。","補助國一女生免費接種HPV子宮頸癌疫苗。","爭取生活圈道路投17線，北中寮延伸到南中寮（中寮國小），道路拓寬。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"168fbd35-c28f-4cbf-86c2-171c8954babe","items":["推動綠色捷運一站一特色，G06站美術館、G07站九九經濟大樓、G08站臺灣傳統美食館、G09站步行街、G10站兒童館、G11站國際光雕館、G12站創意商圈，讓桃園經濟起飛","推動公設安親班","推動0~3歲公托家園","爭取老人三節獎金恢復2500元","爭取環保志工辦理常年訓練經費每人500元","爭取鄰長報紙免費，另也可轉換看電視 生活慧更好","優化陳情管道、設立「網路陳情資料庫」。","廣設學童通學步道，維護孩子上下學「行的安全」。","全齡共融公園之設置，打造各年齡層皆合適的使用環境。","國道橋下空間活化再利用。","全面檢討無障礙空間以友善身障人士。 育兒慧更好","爭取托育補助、育兒津貼再加碼，讓桃園成為最適合年輕家庭居住的城市。","廣設圖書館之親子閱讀區，提升共讀共學風氣。","爭取增加兒童病床床數、專科醫院、兒科夜間急診。","爭取口服輪狀病毒疫苗/自費疫苗補助。 交通慧更好","爭取南桃園交流道之替代道路計劃，舒緩車流。","連結桃-北生活圈、桃-北公車路線擴增及站點新增。","中路/藝文特區周遭停車空間檢討、爭取各區停車格擴增。","捷運站點沿線之UBike站點設置、公車站點之配合。","捷運建置之交通黑暗期，替代道路設置的方案。 環境慧更好","加強監督汙水下水道設置之進度、爭取提高補償比率。","熱點常駐車輛噪音監控管制，還給市民安靜生活品質。","分區增設寵物公園，增加寵物奔跑綠地。","落實寵物普查、晶片管理，從源頭控管以避免寵物流落街頭。","媒合市府與民間資源，協助新住民降低語言溝通的障礙與文化上的差異性。 樂齡慧更好","完善社區關懷計畫（關懷據點設置/獨居老人定時關心）","完善敬老愛心卡福利。","爭取65歲以上長輩驗光及老花眼鏡補助。","爭取65歲以上長輩助聽器補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"169e0faf-091e-4c28-8cd6-2b8fb8edd78c","items":["勇敢監督","服務優先"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"16a9f66d-fe81-45b5-8a18-79270cac47be","items":["督促新北市衛生區針對瑞芳醫療長照樓依約於115年完工啟用，以提升東北角四區醫療品質。","要求市府水利局針對瑞芳區汙水下水道(總經費23億，已核定)，必須依照期程於113年正式動工，以解決汙水排放問題。","為提升瑞芳城鄉風貌改善，並解決長期平交道所延伸的交通問題，推動瑞芳火車站大平台計劃，並要求市府加速與中央溝通協調爭取經費。","要求市府針對非都市計劃內之老舊房屋放寬修繕規定，並制定相關自治條例，以解決東北角四區老舊房屋修繕及改建問題。","後疫情時代，要求市府針對瑞芳水金九、平溪天燈、貢寮海洋音樂祭，推動相關觀光系列活動，以帶動觀光人潮，提升在地經濟。","雙溪三貂生態隧道已正式啟用，但週邊環境配套措施不足，持續要求市府全力改善，以帶動雙溪區觀光產業。","為提升東北角四區農、漁民福利，要求市府持續滾動式檢討，擴大增列預算與補助，以照顧農、漁民生計。","因應氣候變遷地球暖化，要求市府水利局提高簡易自來水預算，以解決山區民眾夏日無水飲用之問題。","要求市府增設關懷據點與日照中心，並落實長照計畫。另為減低年輕家庭負擔，應增設公共托嬰中心，並優化褓母素質與福利。","結合教育部生生用平板政策，爭取東北角各校教室均設置大屏及遠距教學設備，打造孩子以科技力連結國際競爭力的學習環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"16dedf11-d53d-44e2-8857-a80a7fa1ef14","items":["（一）守護長輩：爭取假牙、老花眼鏡及助聽器等各項補助。","（二）婦女保障：補助婦女凍卵及各項健檢免費補助。","（三）兒童教育：落實學齡前教育義務化。","（四）青年政策：敦促市府設青年局，幫助青年圓夢，生涯發展。","（五）完善醫療：提升市立聯合醫院成為醫學中心。","（六）民生汐止：加速推動並增設捷運民生西路、重慶北路站。","（七）大圓環站：增設捷運圓環站，活絡圓環商圈。","（八）社子輕軌：爭取民族西路輕軌站，延伸路網至臺北車站。","（九）淡水河岸：發展大稻埕水岸人文園區。","（十）廢除一殯：爭取區域再造。","（十一）文創平台：加強傳統藝術、文化與世界文創業交流。","（十二）公園活化：完善花博、河濱、新生公園機能。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"17a101c6-4047-471b-a2d6-ec6dbbbcc9e0","items":["扮演政府及民眾溝通管道,加強為民謀福利","告辦公民論壇,培育青年參政","加強族群融合,共存共好共榮","監督公部門經費支出及效能,提升台東全民實質幸福感","為弱勢、阪老、身心障礙、中低收經濟弱勢者爭取更周全福利","導入大型企業投資,增加縣民就業機會"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"181d4fa4-44cf-4142-a5f7-a0963df77266","items":["愛顧鄉親、監督縣政，爭取地方最大福利。","重視婦幼高齡者安全照護及弱勢團體權益福利保障。","情誼地方中少，專職認真，熱情付出，爭取地方所需。","義不容辭，介接北港、水林、口湖個別文化觀光樣貌，促使風華再現。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"186055b7-be62-44fa-ac78-9b463ae12756","items":["【路面坍塌，危險至極，不容小覷！】 要求縣府成立「公共危險審查專案小組」，建商應定期提出監測數據，對工地傍鄰宅、周邊道路等地質全面體檢，以保障住戶及用路人安全。否則應依法開罰、全面停工，專案調查徹底解決！ 【竹北戶政，老舊建築，早應汰除！】 竹北戶政事務所民國77年啟用至今，人口從5萬6千人成長至21萬人，建築老舊、空間狹小、櫃檯服務受限，抽號、等候、大排長龍，每天上演！洗手間與市公所共用，停車不易、一位難求，種種不便，馨竹難書，唯遷建一途。 【改善校園電力系統，全面裝設冷氣！】 要求教育局全力協助各校對於電力改善、冷氣裝設、屋頂太陽光電設置、能源管理系統建置等應如期完成，讓師生有舒適的學習環境。 【營養午餐－校園食品安全衛生再升級！】","要求教育局一律採用國產豬肉、牛肉及在地有機食材，支持有機農業永續發展。","推動聰明營養午餐，由營養師開立「聰明餐」食譜，將全穀雜糧、深海魚、堅果類等食材加入營養午餐，藉由優質午餐食材，開啟每天的靈活腦力。 【豆子埔溪整治，刻不容緩！】 增編整治經費，提高汙水下水道接管率，嚴格監控、取締工業廢水偷排，定期清淤疏濬、河畔綠美化，為住戶生活品質強力把關！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"190b6e26-481a-4234-a48e-941f78a0769f","items":["便捷交通：打通塞車瓶頸：新闢道路或高架橋；道路拓寬、道路截彎取直","便捷交通：興建停車場；建置及優化人行步道；為長者、通勤族及學生增加大眾運輸；爭取TPASS普及全台 前瞻教育","便捷交通：依財政收入成長，爭取提高全國教育經費編列下限1%（預計300億）","便捷交通：檢討108課綱，檢驗教育妥適性","便捷交通：竹縣高中增校增班，充實教學設備設施","便捷交通：推動智慧校園；優化英語學習環境、增加國際教育資源","便捷交通：學生學貸免利息；穩定教師待遇與福利；重視技職就學環境 魅力觀光","便捷交通：坡頭漁港擴港；設立農漁產銷交易中心；發展西濱海岸休閒觀光；各鄉鎮農漁產品進入六都產銷平台；推動在地社區營造；結合各鄉鎮農村特色發展多元化休閒農業觀光 優質生活","便捷交通：增設老中青皆宜的全齡共融特色公園、親子館、各類運動場所及休閒步道","便捷交通：各鄉鎮自來水接管及天然瓦斯延管；加速石門水庫至新竹聯通管工程；推動電線桿地下化","便捷交通：整治野溪、建置河堤；興建活動中心；翻新舊市場；火車站門面整修","便捷交通：提高育嬰留職津貼；就讀公立、非營利準公共化托嬰托育和幼兒園一律免月費；就讀私立機構每月補助1萬元","便捷交通：給予職業婦女彈性工時或遠距工作；推動職場對女性更平等的績效考核制度 健全福利","便捷交通：支持青年創新創業；提供青創基地、青創貸款","便捷交通：基本工資調高至33,000元；勞工加薪企業減稅；力保勞保基金永續發展","便捷交通：老農津貼每月1萬元；建置缺工人力平台解決農漁民缺工問題；提高：公糧收購價格、停灌休耕補助及綠色環境給付","便捷交通：新住民：懷孕全面納入健保、打造就業平權環境、開設高階職訓班","便捷交通：推動「長健法」：讓國人長壽而且健康 立法守護 強力監督","便捷交通：修正預算法，明訂實徵數大於預算數時之差額應用於特定之福國利民使用","便捷交通：立法保護吹哨者及其家屬或密切關係人之人身及各項安全","便捷交通：《財政收支劃分法》修法，為新竹縣爭取中央預算之合理分配","便捷交通：稅制改革：調降自住稅率1.2%降至0.6%；檢討各項不合理賦稅予以減稅","便捷交通：打擊詐騙：修法提高詐騙刑責，加強跨國聯合查緝","便捷交通：強化監察院的功能；避免成為政治打手或功能不彰","便捷交通：監督政府：資訊公開、人事獎懲有據、任用公開透明 成立「行動服務處」熱忱服務！無所不在！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"197d459e-d1fe-4d97-9855-64f595d1eec8","items":["提案調降房屋稅，已於108年7月調降完成。","提案身心障礙及中低收入者日間照顧及住宿法定權益，已從112年調增經費至3億3千萬元。","提案保障18歲已是成年權益，已修正身心障礙者購買或租商店攤販的低利貸款年齡。","民雄為中心，規劃未來發展（別只重視縣治特區）並成立專案小組督促辦理。","督促原北勢仔營區社會住宅週邊做好有利地方發展規劃。","督促民雄航太產業園區早日完成。","督促民雄鐵路高架化早日完成，以上並納入專案小組督辦。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"19a9b938-a4dc-4fd1-9bc0-7f413a396655","items":["專業團隊，專業問政： 解決一直以來問政專業度不足和缺席的情況，並成立專業問政團隊包含：法律、教育、文化、醫療、家庭等各項專業人士。","強力監督，維護權利： 監督政府政策並維護民眾權利，提升政府行政執行能力，強調民眾權利優先。","服務在地，跨越族群： 服務不分族群一同創造共榮，接受落實族人申請案件之追蹤、考核，落實陳情案件受理、審理，維護族人權益。","地方創生，產業發展： 復興地方產業、創造就業人口，促進青年人口回流，建立產業品牌。","勞工權益，創造就業： 協助取得良好勞動條件並處裡勞資糾紛，依族人需求提供就業、創業培訓。","婦女權益，落實保障： 促進婦女參與社會，維護婦女健康，保障婦女權益，提供婦女互助平台。","醫療健康、長照體系： 推動原民健康醫療網，建立完整醫療機制，透過長照機構、社工提供醫療協助。","教育升級，文化傳承： 強化原民教育落實原教法，推動文化傳承，增設文化據點，協助世代對話。","基礎建設，觀光升級： 強化部落基礎建設，推動部落社區營造，執行各項部落觀光發展計劃。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1a3cbafa-772a-4e21-aa0a-6f48fa7fbb3c","items":["監督政府並爭取資源，落實弱勢、老人及弱勢族群照顧。","推動社區文化與教育，促進就業與發展。","協助農漁業轉型與市場開拓。","建設道路與公共設施，提升生活品質。","改善交通與路網，保障行車安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1a559ded-e439-4804-9e35-8c2b9d02789d","items":["促成113年1月起，老農津貼每月增加至8,080元。","促成113年1月起，國民年金（含原住民給付）每月增加至4,036元。","花東基金補助興建部落聚會所，花東已完工41座、興建推動中80座。","促成中央補助建置「都會區集會所、祭典場所」及「公共服務空間」。","尚未編定使用地類別土地可申請原保地，花東1,203筆、665公頃。","保障用海漁獵權：都會、原鄉均得依傳統文化祭儀或非營利自用。","提高租屋租金補助，戶籍得不在租屋縣市。","承租之國有地申請原保地緩收、免收、退還租金。","提高建購、修繕住宅補助。","擴大托嬰、托教補助，完成《原住民族健康法》。","調高大專學生獎學金為3萬2千元、助學金2萬及3萬元。","促成增設文健站經費，全台已設置503站文健站。","自治：設置部落公法人。制定原住民族自治法。推動共管區或先導自治區計畫。","土地：立法要求政府將《臺灣省土地權利清理辦法》第8條收歸國有之土地劃設為原住民族保留地。制定原住民族土地及海域法。","住宅：興建原住民族社會住宅，提高租屋、購屋及修繕補助。","教育：0至6歲公私立托育托教實質免費。提高原住民大學（專）生學雜費減免，學貸免利息。設立原住民族學校。","經濟就業：推動銀行專案辦理原住民低利率貸款、儲蓄互助社專案利率。擴大政府、公營事業及公設財團法人進用原住民。","都市原住民：增加都原發展經費，興建集會所、祭典場所，強化安居、就學、就業、融資、就養、健康及社會適應等發展方案。","語言文化：提高族語老師及語推人員待遇，增加部落、教會及同鄉會等語言文化扎根據點。設置族群領袖、頭目文化傳承事務補助費。","自然資源：立法開放使用安全有效之制式獵槍，推動都會區漁獵及海河岸採集權。","福利：原民勞保補助。勞工退休、老農津貼、台鐵及高鐵敬老票等原民調降至55歲。提升原鄉醫護資源。開辦原民長照保險。加速增設文健站。","預算及建設：設置原住民族建設發展基金，增加部落、文化、體育發展經費，持續推動花東鐵路雙軌化、花東快速道路、蘇花改二期工程，加強經濟產業及農田灌溉建設。普及機動幸福巴士。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1a8ebf40-6b14-4267-992f-a92f39be8013","items":["加速推動捷運綠線大坑延伸線、藍線、屯區線。","繼續爭取廍子、廍興、兒童公園兒童遊戲場改善。","維護公寓大廈公共安全，補助住宅加裝住宅用火災警報器、滅火器。","拒絕核食嬰幼兒食品，推動市府購買純鍺偵檢器。","支持推動台中購物節、十大伴手禮票選、大坑千人宴。","強化校園安全，營養午餐禁用萊豬，支持嚴懲重罰狼師。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["past_achievement"]}}},{"claim_id":"1ae0c002-ec73-4f12-aa9f-ea9bb6720e54","items":["強而有力監督縣政府，落實照顧弱勢低收入戶及幼童婦女們。","強而有力監督縣政府，重視推動農業、文化觀光宗教及親子休閒活動提升縣民生活品質。","強而有力監督縣府，平日做好持續疏濬樟平溪、貓羅溪等河川，以確保正常水流量，以防水患之苦，保障人民的生命及財產安全。","強力要求縣警察局，改善社會治安，維護人民生命安全，建立快樂、希望的新南投縣。","強力要求縣府與人民溝通平台，提升施政效率。","提倡清廉政府，不分藍或綠，團結改革，共同為大環境努力打拼，刷新南投縣更亮麗形象。","全力支持照顧勞工團體，推動基層勞工政策，增進人民福祉。","長期都堅持著28年郵差及2任特優里長的服務精神。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1b813875-ad91-442a-a7fa-ac2af8c930fa","items":["楊梅在改變、在進步，楊梅不一樣！阿吉認為只要肯努力，一定看得到成績，我們也相信只要認真去做，楊梅會更好。","持續爭取廣設YouBike站點。","爭取增設公立托兒所，增加托嬰名額，提高生育補助、育嬰津貼，減輕年輕家庭的負擔。","爭取楊梅地區設置籃球、排球、羽毛球、桌球、滑板等場地，以滿足愛好運動之民眾需求。","督促桃園市府儘快完成楊梅體育園區之建設並拓寬、改善周邊道路，避免交通壅塞。","爭取提高長照、關懷據點經費及三節敬老金、擴大敬老愛心卡用途，落實照顧老人之政策。","爭取楊梅區設立觀光夜市，提供民眾休閒去處，刺激消費促進地方發展。","爭取楊梅區內各大車站，結合客家文化，整建具地方特色之車站，吸引人潮促進觀光。","持續爭取各里設置活動中心，全力改善基層建設，所有建設補助款公開透明、全民監督。","持續爭取建設水岸步道，打造楊梅環形水岸步道網，形成楊梅獨有之地方特色。","爭取提高教育預算之編列，提升教學品質與優質的學習空間。","尋覓合適地點增設寵物公園供毛小孩活動。","增設特色公園及共融式遊戲場。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1b956da8-55fc-44b5-b3b0-096d0bdfddde","items":["轉型顧經濟,繁榮看得見,加速推動捷運到林園時程、國道七號,翻轉林園大寮工業區的宿命。","顧大又顧小,家長好放心,社會住宅在林園大寮、盤點現有閒置空間並活化,持續增設日托、臨托、夜托、開懷據點等,托幼","觀光再升級,形象大翻轉,增加大寮林園自行車步道,推動老街再造,加強林園海岸線景觀美化,擴大觀光效益。","親子加藝文,預算要增加,爭取各大藝文活動在林園大寮,盤點區域增設特色公園、寵物友善公園、兒童運動公園,讓孩子能 就近玩也讓寵物有去處。","人口不外流,留住好青年,支持在地青年創業,國營企業優先聘用在地子弟,石化稅收專款專用建設地方,讓人才適得其所, 讓企業不再缺工。","弱勢加倍顧,各族群都要,身心障礙、特殊境遇、新住民、二度就業等身分,彌平資訊落差,加速融入社會。","空汙要改善,全力來監督,務實面對問題,輔導工業、企業進行綠能減碳措施,實際解決問題。","18歲公民權,一定要同意,青年是我們的末來,力挺18歲公民參與公共事務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1bc9110b-8f04-43ca-8a33-566657a054a3","items":["奕德秉持「服務德來速」精神，迅速反映民意、理性監督市政。","持續重視教育及校園安全，並推動校校有外語師資，校園接軌國際，提升雙語競爭力。","因應強降雨極端氣候，敦促廣設水撲滿、透水性人行磚、加強清淤，打造更具韌性的海綿城市防洪洩水。","關注交通安全，隨時滾動式檢討調整為最適宜之措施。","敦促市府成立「青年發展處」，大力提高青創補助；並媒合更多平台資源，提升青年返嘉、來嘉創業之意願。","推動文資教育、深化館藏，重視在地文化進而創生、行銷，利於發展嘉義文化觀光商機。","持續關注社會安全網，媒合社會資源協助弱勢及邊緣戶渡過難關。","強化警察、消防人員及協勤民力裝備，避免出勤發生憾事；並提升民力福祉權益。","重視空汙問題並輔助社區打造綠美化景點，讓嘉義處處是亮點。","持續關心並對年長者、新住民家庭、毛小孩等面向政策建言。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1bcdc483-919a-40fe-8617-55f42d8a2f94","items":["督促縣府重視坡頭漁港船筏進出航道及港內定期清淤工程，紅毛港紅樹林至鳳坑漁港周邊工程進度控管及長期環境維護。","持續爭取農委會農路改善工程，提升農產品運輸及進出安全。","協助偏遠國中小教學環境改善，提升在地就學意願，縮小城鄉差距。","督促縣府活化各國中小閒置空間，設置社區圖書室，提供在地學子假日閱讀使用。","督促縣府加速「台一線替代道路，竹北—新豐段」新闢工程，以解決上下班壅塞情形。","督促縣府解決大山崎地區就學問題（短期目標儘速完成松林國小擴建案，長期目標透過新設學校疏解山崎、松林等校學童活動空間不足問題）。","爭取設立特色公園，並於公園改造同時評估設置地下停車空間，以解決都市計劃區內停車位不足問題。","督促改善新豐火車站周邊髒亂問題，還給鄉民一個乾淨門面。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1c69e67e-929f-4059-a109-11531f733648","items":["規劃麟洛鄉第二條、第三條聯外道路，以紓解屏東義大醫院營運後對當地交通之衝擊。","規劃麟洛鄉埔圳巷納入公路系統並拓寬，另於南麟洛規劃一條聯外道路，以紓解台一線交通流量及提升該鄉防救災量能。","建立屏北觀光，整合休閒農業、藝術、文化、產業為複合型休閒景點。","督促政府重視兒童、原住民、新住民及大陳義胞權益，照顧弱勢團體及提倡兩性平權。","督促政府建立農特產品產地認證及生產履歷，協助農會行銷農特產品，增加農民收益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1c98a208-a997-4c9e-b282-b7ee2bfc2608","items":["打造竹苗發展區域核心一香山城鄉願景力 積極串聯竹苗的生活與產業，打造一個與生態、文教、科技共生共榮的永續未來。香山讓竹苗更美好! 人本好行一香山交通順暢力","優化中華路公車候車亭、人行道","增設香山區You Bike站點","加速推動香山路平","偏遠公車路線轉型幸福小黃 教育升級一香山優質學習力","推動校園發展科技教育與食農教育","提高香山區公托、公幼、非幼量能","增加正式教師名額與代理教師聘期 青銀共照一香山健康樂活力","維持長輩肌力，普設銀髮健身俱樂部","爭取香山區失智社區服務據點","提供長輩免費衰弱症及失智評估","推動社會住宅，青銀共住共助 環境永續一香山產業綠能力","推動在地農食與科技創新聚落","推動新竹市達成2050淨零碳排 動保生態一香山動物幸福力","制定新竹市友善動物白皮書","維護野生動植物棲地生態多樣性","實施流浪犬貓小範圍高強度TNVR 藝文社企一香山自然文創力","推動香山濕地藝術季結合生態教育","擴大文化資產保護，推廣地方文史"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1cc15fa1-cfd2-45d7-a2f9-902cbe796b5c","items":["新世代，新花蓮。胡仁順傳承強力問政，為民監督，敢衝敢拚；要讓縣政與議政重回正軌，讓花蓮人找回光榮，與鄉親同行展望繁榮新花蓮。","打造宜居花蓮：要求推動社會住宅，徹底檢討並長遠規劃市區停車與交通問題。","厚植教育：鼓勵新住民及各民族子女掌握母語與文化，成立專責業務小組；強化職業與運動教育，開辦中小學課後照顧；重視弱勢教育權並落實正常教學與聘用。","環境永續：垃圾問題在地解決，推動源頭減量、提升回收總量並引入新技術。","動物福利：推動領養代替購買、打造寵物公園及疫病防治，讓花蓮成為友善毛孩的城市。","青年未來：要求縣府正視花蓮青年需求，以政策工具與財政政策改善人口流失。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1d4322c3-8191-4ff6-9215-5c9ec19e46aa","items":["要求「確實執行臺北市原住民族生活發展自治條例，建立符合我們自己的規範。」","監督「臺北市原住民族文化創生基地之規劃，提供族人創造及發揮的場域。」","改變「政策概念應以家及人口數為基礎，才能有效全面照顧」","持續「推動原住民族教育，從學齡前至高中職有系統的傳授」","改善「原民老人安養安居品質，增加原民家庭臨托顧養彈性，豐富提升原民長者生活內容和品質」","強化「都會區原住民族認同感，增加原民生存、文化、技藝、語言學習管道」"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"1d6c8216-c60b-409a-802c-94a42e651f64","items":["爭取溪北設立公托中心。","提高生育獎勵金，第一胎1 萬5 千元、第二胎2 萬元。","爭取坐月子到宅服務補助2 萬元。","爭取國小孩童課後安親全額補助。","65 歲以上長輩全面補助健保費。","爭取65 歲以上長輩入住長照機構，最高1 萬元。","爭取於柳營機關9 用地設立溪北社會福利綜合大樓。","推動政府即時人力媒合平台。","爭取大新營區社會住宅興建及包租代管數量。","新住民友善城市，促進族群融合。","交通：爭取於新營區建設立體體車場，解決停車場不足問題。","交通：爭取高鐵橋下道路優先興建新營市段接嘉義縣道167 線，縮短至太保路段時間。","農業：持續爭取大新營區內之農水路更新改善工程，保障農民權益。","農業：爭取柳營八翁設置酪農農業專區，推動在地農業發展。","農業：持續推廣溪北農業觀光廊道走線，發展休閒農業旅遊。","藝文空間：修復卸鹽台，糖鐵復駛，持續推動岸內糖廠至烏樹林糖業文化路徑計畫。","藝文空間：推廣SDGs永續發展目標，閒置空間活化，設置藝術聚落，舉辦藝術家駐村活動。","藝文空間：推動藝文特區，建構人文、民俗、藝術多元友善城市。","藝文空間：爭取三太子宮宗教專區儘速通過。","藝文空間：持續爭取特色公園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1d84f9ea-da38-419c-ac8c-4538d06c0e9d","items":["全力優化大溪及復興地區 教學環境，以提升學習效果。","持續推動大溪埔頂公園，設置圖書館及親子館"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1db9e957-be8f-4c09-a08d-aecb175ccd8f","items":["拼長照：推動科技長照普及；一區一公立日照；提升照服員福利。 拼生育：提高生育、托育補助；推動放寬凍卵限制門檻；推廣定點臨托設施布建。 拼生活：加強食安管控、食品供應資訊公開透明、加重不實罰則；增設海線屯區新住民服務中心；調整不合理貨物稅課稅制度。 拼建設：大肚生活圈四號道路；爭取海線鐵路雙軌高架化；加速社會住宅建設、納入多元房源；擴大接管增加自來水普及率；爭取海線地區老舊電網優先汰換；持續推進南山截水溝三期。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1dda9b3a-b092-47d7-9c5d-16d1636a0946","items":["擘劃交通長遠規劃.積極爭取馬祖大橋。","增進財源活絡發展.興建馬祖酒廠二廠。","產業輔導地方創生.鼓勵青年返鄉創業。","落實馬祖文化平權.擴充藝術島策展面。","實現永續淨零碳排.‧打造馬祖碳匯經濟。","打造健康樂活島嶼.推動發展休閒運動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1e0d86be-320f-4983-9f10-60f3f2dd16eb","items":["力挺市民，反映民意，監督市政。","督促計畫道路拓寬、污水下水道工程，改善排水系統流暢，嚴防豪大雨成災。","爭取警消人員福利，加強維護治安及防災演練，保障市民生命財產安全。","監督市府通盤檢討都更，打造嘉義市成雲嘉觀光中心，帶動觀光休閒發展。","關懷照顧老、弱、婦、孺、殘障人士，落實各項社會福利相關政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1e9eeed4-773b-48c9-aa8f-552178ab09b4","items":["交通建設完善再進化","貫通開闢聯外道路、瓶頸道路，健全楊梅交通路網。","積極爭取桃園—楊梅捷運替代路網，完善偏鄉地區公共運輸需求。","福利照護再提升","友善托育補助再加碼，爭取定點臨時及假日、夜間托嬰托育照護服務。","爭取醫療就醫專車及桃園南區兒童專責醫院。","均衡楊梅四大生活圈，推動共融式遊具，強化公園休憩及體健設施的改善。","推動楊梅分局重建及活化周邊市場等用地、續行社子溪流域整治及登山步道，打造近山親水休憩好環境。","文化特色產業再提升","串聯地方特色，發展休閒農業區，提升在地資源能見度。","催促鐵道藝術節配合鐵馬等觀光資源，開發鐵道地景文化產業。","監督縣政再用心","嚴格把關市府預算，強化公務部門服務品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1eb1b7b0-4960-4dbb-a9de-887da39460d9","items":["民進黨唯一新人 唯一女力 港湖再進化！ 交給何孟樺！ 【01】國際城市再進化","強化觀光指引及增加觀光資訊站設置","強化各區特色宣傳，推動台北深度旅遊","促進姊妹市多面向交流 【02】宜居港湖再進化","推動公園多元：樂齡運動設施、兒童特色遊具推動及毛孩運動區域","強化社區照護：增設公托及非營利幼兒園、長者日托、共餐等照顧服務","婦幼回家安心：盤點港湖街區明亮度，監督監視器增設及品質 【03】首都美學再進化","落實電線桿地下化，美化街區景觀","推動危老與都市更新，住的安全市容換新","推動美學設計納入公共建設改善城市景觀 【04】地方建設再進化","智慧城市檢討交通：大數據為基礎改善紅綠燈秒數、公車班次等規劃","監督捷運東環線、東區門戶計劃、內科2.0等建設，確保如期如質完工","推動法規鬆綁，振興新創與青創經濟 【05】國際城市再進化","落實交通平權：檢討路口兩段式左轉、落實車向分道","力挺行人路權：檢討人行道寬度、推動實體人行道、騎樓平整度及公共空間無障礙設施","氣候友善，增設公園、公車候車亭等公共設施遮雨遮陽空間","落實居住正義，監督社會住宅建造、包租代管流"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1f670db2-3006-49f8-8a6c-cab7d140d8c8","items":["甲安埔六大願景：縫合都市，山海串連 鐵路海線雙軌化 海線鐵路部分高架化 輕軌上環線 連接山海線 增設YouBike站點、爭取大甲轉運站","甲安埔六大願景：產業升級 為農民找通路 推動營養午餐擴大採買在地食材 推廣在地農產品牌、擴大舉辦地酒節 六級產業再加值、推廣智慧農業","甲安埔六大願景：海洋經濟帶動地方發展 大安濱海樂園水質改善 讓遊客都能安心戲水 打造松柏漁港成為中台灣衝浪基地","甲安埔六大願景：老幼有顧 減輕青年照顧負擔 將大安發展長期照顧的發展重點區域 帶動地方照顧產業以及就業機會 爭取公托倍增 提升公托中籤率","甲安埔六大願景：完善基礎設施 提升生活品質 爭取施作雨水下水道工程 爭取提升污水處理設施覆蓋率 爭取設置運動中心 新設大安納骨塔","甲安埔六大願景：甲安埔好藝文 規劃台鐵八間日式宿舍 大甲火車站前文創園區計畫 利用閒置教室空間 增設圖書室、親子館 爭取兒童劇團、藝文展每年來甲安埔演出"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1f9ebeb3-5502-4be3-afca-1c2be52ea5e4","items":["我主張： 以對話取代對立，確保兩岸和平。 邀請總統到立法院發表國是演說。 提高毒品及詐欺犯罪刑度。","我承諾： 健全區域交通網絡的建設。 重啟板南線延伸汐止的評估。 優化台鐵及大眾運輸服務的品質。","我支持： 恢復特偵組編制，嚴格查辦政府弊案。 設立創業基金，讓年輕人施展長才。 地方創生，讓青年返鄉成為可能選項。","我重視： 行人通行的權益、道路平權的推動。 每個孩子是否能受到平等的教育。 長輩的銀髮生活是否受到足夠照顧。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"1fad25d2-a31d-4ef3-ac25-4921ee3b09b6","items":["社會關懷:持續關心八德區無自來水供應角落,讓民眾家戶都有自來水。","持續監督八德大鶯豐德交流道,要求二年內土地徵收及動工。","原行政用地規劃興建北區青少年活動中心(桃寶館、 桃漾館)。","因文小二用地閒置而設棒壘球場,去年提議興建仁德國小,預計113年招生。","持續督促中央大學在八德擴大都市計畫預定地興建八德分校打造『智慧健康創新園區』。","爭取整治大仁溜池、廣興溜池及瑞興溜池綠化美化及環湖步道。持續推動公園特色化、埤塘活化及打卡景點。","關心捷運綠線G01、G04招商及商場規畫,完善周圍商業機能,打開G02至G03橋下道路連接六號生活道路。","爭取八德公車轉運站,交通更快速便捷,加強醫療便利性,增加大型醫院專車。茄苳路國小永豐路截彎取直。山下街打 通至新興路。 中華路5巷瓶頸道路打通工程、規劃興豐路2189巷至福德一路177巷道路拓寬8米道路。 八德區茄苳路91巷瓶頸道路打通工程、樹仔坡截彎取直瓶頸道路打通工程、和平路到介壽道路工程定線案","積極推動仁德國小、公托及青少年活動中心,優化校園環境,減輕家庭負擔,青年多元學習。","持續關心雨水下水道、滯洪池及汙水下水道工程。","加強路平道路養護、道路拓寬及交通安全問題。爭取閒置用地,有效利用。","爭取大勇國小擴建、大福國小增建、永豐國中小增建、八德國中擴建、督促教育局重劃中華電信國中預定地增建。","持續推動八德公托中心及親子館,提供優質托嬰環境、減輕家庭負擔及親子共同學習成長空間。","配合長照2.0政策佈建ABC據點,持續設立日照中心,並爭取八德一據點一藥師制度,對特殊需求長者提供送藥到府及 居家藥事服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1fb9a0a3-0356-42a6-b4f9-ef271898cd18","items":["構多元職能培訓場域 女銀青技能專培課程 者賦能運動設備投入 髮族俱樂部落地拓展 青輔導媒合創造就業 色產業電商平台鏈結 地文化維護深耕資源 報告議會工作成果及助理名單。","媒合大型醫院的醫療巡迴車定時駐點接 地方及中央補助，建設東方美人茶送，服務偏遠鄉村。 柑為主的觀光產業博物館。","增加警消設備預算，確保治安及人民生 在地觀光農場，促進地方青年回鄉活安全無虞。 。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"1fc1060e-f6b7-4b15-b2ca-a159d5bdc585","items":["美梅這幾年擔任市議員無論是出席率、爭取社會福利和地方建設都受到地方民眾的肯定,要讓大家在桃園生活的每一步,能夠更方便、更安心!用理性問政,同理心服務,一本初衷做有益大眾的事。美梅持續推動虎頭山公園和周邊的南崁溪的休閒場域的串連、大有梯田公園、民富社福館、南昌營區和桃林鐵路活化、文昌公園地下停車場、爭取完成體育班三級銜接教育、青年就業補助和中高齡就業補助與中路足球場的興建、社會租宅和租金補貼政策、國中小班班有冷氣、易淹水地區的改善和延平路延伸打通到八德;了解婦幼與長者需求,完成65歲以上長者的健保補助和愛心敬老卡可以搭乘桃園機捷和托育補助和幼童上幼兒園的教育補助費、國強幼兒園興建,努力推動貼心政策,就是要讓大家更幸福!未來,美梅持續推動增設公立幼兒園、爭取市立醫療院所。","公共建設:爭取增設活動中心和停車場和運動相關場地、推動共融式公園、整治南崁溪、東門溪、茄苳溪與監督污水下水道建設,提升居住環境品質。持續關心中油的遷廠和公安問題。","交通:爭取全市及往返雙北間完善公車運輸網。爭取新增設交流道和桃園往中壢的快速道路,督促市府如期完成捷運綠線、棕線儘速施作。爭取國際路延伸富國路和幸福路延伸、爭取無尾巷打通讓居住更安全交通便利。持續推動公共租借式自行車的設置。持續推動無障礙愛心計程車,讓身障者行的更便利、爭取愛心敬老卡點數搭火車。","社會福利:推動社會租宅和租金補貼政策,讓弱勢家庭和新婚青年安居。督促市府制定幼兒教育補助和生育補助。落實照顧低收入戶及急難救助;爭取殘障福利,建構完善無障礙空間。推動青年和婦女創業補助輔導措施。老人和幼兒照護方面推動一區一日照中心、長期照護和關懷據點,增設2歲以下公托,解決上班族的負擔,充分利用學校和公家廳舍閒置空間。爭取巡守隊、義警、義消民防志工設備經費補助。爭取培育體育運動選手相關補助費。爭取農民發展精緻農業,補助肥料和農機購置經費。推動友善動物環境相關政策。願以豐富之經驗,全力爭取人民權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1feb642a-661e-4f1f-a04c-ed94e4f61267","items":["議會：「清廉從政，勤奮問政」，堅持理性問政品質，專職議員有力監督。","社福：全力維護勞動權益，避免無良雇主剝削；要求完善弱勢族群社福措施並協助就業。","教育：監督後疫情時期多元途徑學習成效、落實資訊教育平權；深化校園防制藥物濫用教育、推動規劃新住民社區大學。","財經：嚴格把關縣府預算編列，反對恣意動用第二預備金。","建設：從嚴檢視公共工程建設執行，不浪費公帑與肇生民怨；監督綠能產業發展；貫徹「路平專案」。","治安：推動警消勤務合理化、充實現代化裝備；充實義警消等福利；推進監視系統總體檢並雲端化，杜絕治安死角。","環保：嚴格監督六輕工業區工安作為，持續要求精進揚塵治理、工廠排廢等作為。","專題：持續監督興建社會住宅進度、落實居住正義；持續協助庇護工（農）場設立；爭取農產優惠價購，保障農民權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"1ff757f1-b92a-4275-8db6-bfe39adc9f07","items":["以負責、專業的從政理念，落實推動本鄉各項建設及謀取族親最大福祉。","理性問政，嚴謹監督縣政府施政，保障我原住民權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2026caf3-d108-470b-b2ce-4cf5c428a5a8","items":["監督縣政總體發展、提升縣民生活品質。","爭取鎮政經費補助、改善鄉親居住環境。","推動社區藝文展覽、營造教育書香氣息。","協助弱勢族群自立、保障四就（就學、就養、就醫、就業）權益。","專業優質問政服務、理性思辨縣政規劃。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"205dd2ba-a3b0-4c92-9908-997ffe9e3451","items":["爭取教育資源","爭取高中擴校或增建，讓學生就近入學優質高中。","爭取特教資源與課程，擴大照顧特教生與其家庭。","整合各階段創客資源，提供各年齡孩子由淺入深的科技教育規劃。","增加教育預算投注於軟體之比例，含獎勵優良師資、提升老師福利、鼓勵創新教學。","升級社會福利：責成縣府積極舉辦親職講座、活動，提供家長育兒教養之完整協助。","升級社會福利：推動銀髮俱樂部，鼓勵長者多運動，落實以長健代替長照。","升級社會福利：擴大敬老卡使用範圍，可用於敬老消費，讓竹縣成為友善樂齡城市。","升級社會福利：環境再造：推動豆子埔溪再造，讓豆子埔溪與周邊景觀成為竹北的驕傲！","升級社會福利：便捷交通：增加公車路線與YouBike站點，讓竹北成為綠色交通友善城市。","升級社會福利：開放政府：責成縣府整合公共服務之資通訊共同管溝，掌握數據並應用數據，增加便民創新服務。","升級社會福利：科技應用：增加固定式噪音照相維護夜間安寧、推動科技長照以科技輔助長者照顧、深化智慧交通應用，舒緩塞車問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"20600aec-d19a-4642-af5a-8e40bbdd0e45","items":["公園及寵物運動公園。持續爭取！","運動中心丶一鄉鎮一親子館。持續爭取！","小黑蚊，還給民眾良好的生活環境。持續督促！","建築物耐震安全強化、校園老舊廁所修繕改建。持續督促！","勤務裝備機具強化、消防人員救災救護設備器材精進。持續督促！","政府及民間資源，使社會福利更有效性、可及性、便利性。持續督促！","路至十六股大道，開闢直通道路銜接，提升花蓮後站往來美崙便利性。持續爭取！","溪左岸堤防，近中正橋無防汛道路之斷點銜接，可防洪並兼具親水休憩。持續爭取！","觀光推展，增強各族群文化之在地優勢，並協助業者爭取無障礙旅遊商機。持續督促！","仔尾地區淹水解決方案、汙水下水道接管進度、周邊街區巷道環境與景觀改善。持續督促！","蓮市至干城鐵路高架，與花東雙軌電氣化併行，有助大花蓮都市發展，並避免浪費公帑。持續督促！","區熱點開闢汽機車停車空間、提升友善行人交通環境、校園周邊劃設綠斑馬行人穿越線。持續督促！"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"2083859e-b328-4435-8939-386038852077","items":["爭取改善村（里）基層建設經費，帶動地方繁榮與發展。","推動縣內文化環境結合地方特色，提升縣內文化觀光。","改善地方排水系統，讓居民免受水患影響，生活更加美好。","推動青年返鄉創業與青創專區，增加青年返鄉就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"208b039f-fd5c-43c9-aeac-c44ddcbaa8db","items":["議員薪水捐贈保障婦幼、老人長照、青年、藝文權益。","爭取市府政策應由下往上，回歸地方真實民意。","爭取住宅區設置噪音科技執法，還給居民安寧生活。","爭取平價、就近便利、優質的公共化幼兒照顧服務。","爭取在地安老，健全各里專業醫護級長照協助。","爭取青年及中高年齡多元就業、創業共享及輔導。","爭取司法平等，提供全方位法律扶助及訴訟陪伴等捍衛人民權益。","爭取後站都更重啟，讓居民能即早擁有安心住宅。","爭取建設汙水下水道，使家戶旁水溝及南門溪、客雅溪、汀埔圳乾淨無污染。","爭取各里流浪動物保護隊，落實在地結紮、認養、安置等設施。","實際關懷喪家，提供喪葬補助，減輕沉重治喪費用。","爭取高峰里都更計劃應充份尊重在地居民意見，都更條件應更優惠於民。","爭取定期維護山區坡崁施作，讓市民下雨天可安心行走不怕坍方。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"20993bcd-a06e-45ed-bdf3-b28ee2f2bd0b","items":["以「堅持對,骨力做」的精神全力打拼,張漢忠全心全力貢獻地方,爭取鳳山的繁榮和進步","儘速新建鳳山捷運黃線路網,積極爭取沿線商家、住家的損失補助與措施辦法,在黃線捷運的落實過程中,讓市民","發揮鳳山衛武營藝文中心、大東文化藝術中心等硬體優勢,結合周邊景點,如:鳳儀書院、曹公圳、兵仔市等特色 街,以及百年廟宇文化、美食小吃,運用新創科技體驗,與傳統共生,形塑「吃」、「玩」、「遊」之高品質鳳山文","持續推動老舊社區活化更新,危險及老舊建築優先體檢,強化安全結構,讓民眾住得安心。","監督市府保障勞工生活、權益與就業的安全,爭取提升最低基本薪資與福利政策。支持地方創生,爭取青年創業計 畫與補助措施。","高齡人口多,落實加強長期照顧設施、廣設關懷與樂齡據點,提升照護量能,降低家庭照顧者負擔,讓長者互助學 習,保持社交,並享有新知識技能。","徹底改善道路品質,改進危險路口,增加市區公有停車位供給量,讓市民交通更便利。","改善流浪動物處境,落實寵物晶片管理制度,提倡認養代替購買。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"20d29449-5e50-4219-abe2-fbf4980d6b21","items":["體育、音樂、育樂，強化孩童心、身、靈的健康快樂。","鄰近城市的互惠合作。桃園市、新北市、台中市、新竹縣、花蓮縣；百萬買房子，億萬買好鄰居。（好鄰居勝過好房子）","蘇澳、南澳、頭城、壯圍、五結加起來面積多新加坡近1倍大，新加坡能，宜蘭為何不能？","宜蘭是世界的淨土、地球唯一的淨土，只欠福報。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"21e80b64-caee-4bca-aeba-2cba98a68b8e","items":["推動0-6歲幼兒國家養、台中市政府一起養。","鼓勵興建安老社宅及青年工作住房。","社會局補助生育多胎家庭，優先入住社會住宅。","推動設立元宇宙科研中心，培養AI科研人才與產業。","工業為國力基礎，獎勵並爭取產業入駐台中市，增加就業機會。","推動都市更新與危老獎勵的容積，可移轉至低容積地區，讓新舊都市計劃區同步發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2222596a-f819-46fb-b1e5-e36945fa0983","items":["服務選民-心繋民瘼民需","監督市政-營造希望城市","健康促進-古道強身保健","關懷弱勢-建構幸福社區","重視社福-強化幼教托育"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"226b26f9-c4a1-4b44-9fac-ed3f4a9849dd","items":["督促政府重視屏東市之經濟活絡性。","全面檢討公共設施保留地，遵循監察院糾正案，保障人民生存權及財產權。","督促縣府加強屏東市之軟、硬體之建設，促進都市發展。","督促縣府全面檢討交通問題，維護用路人之安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"22acf00f-6681-4eac-b9a1-6d027e532235","items":["守護台灣主權，強化國防自主，提升與國際民主陣營的安全合作。","防洪治水後，美化溪流沿岸，讓已擺脫淹水之苦的鹽水溪、三爺溪、二仁溪沿岸更加親水宜居。","教育優先，持續校園軟硬體設施優化，讓孩童擁有友善的成長學習環境。","監督政府，縮短沙崙綠能智慧科學城後續醫療產業園區、工業區建設期程，讓沙崙科學城外溢效應迅速擴及東區、龍崎、關廟、仁德各地區。","建構便捷交通網。督促政府早日完成台86線延伸、打通東區仁和路至仁德勝利路；整合中央、地方資源，儘速完成捷運建設。","鏈結東區雄厚教育、工商底蘊與南關線綠能科技發展潛力，讓串連東區東門路、南關線中山路的182線，成為南臺灣最亮眼的新廊帶。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"23659deb-83dd-41cc-a969-7f4b48acc04c","items":["推動彰化縣政府遷移至田中高鐵特定區，均衡彰化縣整體發展。","監督縣府財政預算統籌，落實公平原則，爭取教育預算合理分配，縮短城鄉差距。","持續推動改善長青福利卡使用功能，讓此卡不僅只能搭公車，新增旅遊、飲食、搭乘計程車的功能，讓長青福利卡成為電子錢包、悠遊卡及國民旅遊卡四合一福利卡，促進長輩使用福利卡的便利性與多樣性，照顧長者的晚年生活。","響應政府長照 2.0 政策，持續全面推動彰化縣長者免費共餐。","推動托育一條龍再進化，提升公托質與量，增設非營利幼兒園。建構友善親子共學共遊空間，廣設親子廁所及停車格，擴展友善育兒環境。","加速推動水域整治計畫，兼顧生態水質改善，提供優質親水河岸空間。整治區域排水，改善易淹水問題，確保鄉親生活安全。","力促縣府輔導農民發展精緻農業，改善農業發展，增加農民收入。","爭取興建社會住宅，只租不售，以嘉惠勞工、青年及弱勢家庭。","推動建構微型創業平台，提供優質青年創業環境。","督促縣府持續推動中小學童免費營養午餐政策，並充實校園設備。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2380d5a8-803b-4ef9-8e13-f794794eb8b5","items":["三個5億再持續：醫療再進步、海洋要永續、觀光拚升級","爭取5億以上經費，讓兩家醫院持續升級醫療與檢查儀器，甄補優秀醫事人才；協助衛生所室更新設備，完善遠距醫療照護，優化在地就醫品質。","爭取5億以上經費，擴大投入清除海底覆網及海漂垃圾；強化復育海洋棲地與生態，為下一代留下這片美麗的海。","爭取5億以上經費，深化澎湖觀光內涵，打造亮點觀光建設，提升休憩品質；在兼顧島嶼環境承載量的前提下，持續推展秋冬觀光。","要求中央政府充實照護服務員人力，設立優質平價的照顧機構；增加社區關懷據點功能性與更新設備，實現長者在地安養目標。","持續優化校園空間，讓孩子擁有舒適的學習環境、安全的運動場域。","要求三軍總醫院澎湖分院建置放射腫瘤中心，讓病人及家屬免於舟車勞頓，就近接受治療。","修法推動由中央政府撥補勞保基金及負起最終給付責任，保障勞工權益。","要求中央政府維持漁業用油補貼；輔導低度利用漁港轉型共用及航道清淤，維護港埠設施安全；要求海洋委員會加大力道驅離中國越界漁船，並對澎湖周遭海域生態環境進行生態監測。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"23f1d658-a3f9-427f-97e7-e64cdfe02c82","items":["結合民間團體強化農產、漁產品行銷，改善生活經濟。","整合在地文化、景點、美食亮點，強化觀光旅遊經濟。","爭取規劃升級抽排水系統及防汛工程，解決水患隱憂。","強化各關懷據點功能，鼓勵長者社會參與及多元互動。","爭取醫療資源挹注，提升急症、重症醫療品質與量能。","爭取充實學童課後多元輔導，減輕雙薪家庭育幼壓力。","推廣藝文活動；鼓勵青年創意開發活化在地文化特色。","整合行銷客家庄文化意象，打造客家庄觀光空間廊帶。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"240280d7-dda5-418d-b9cb-effa55b8e4e6","items":["推動高雄市政府行政中心北遷仁武西營區。","爭取國十大社交流道。","打通仁武水管路穿越中油廠區，連接左營後昌路與台17線接軌。","爭取仁武區仁林路拓寬案。","開發文小四學校預定地，爭取籌建學校，滿足仁武區人口增長、學童就學需求。","有效開發高屏溪沿岸土地，增加大樹區學子休閒運動場所。","新設納骨塔，解決納骨塔位嚴重不足問題。","迎接仁武安居，廣建社會住宅，讓年輕人住得起、負擔得起。","持續為解決水患找方法，為急降雨淹水找出路。","持續緊追大社區段徵收進度，不能再讓當地居民等十年。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"24b66f2b-61be-4cd0-a87c-020344afb79d","items":["扶弱勢、減負擔 ◎ 增加資源、推動長照3.0，強化長者照顧 ◎ 力爭政府各項弱勢補助、津貼修正調降門檻、擴大補助 ◎ 要求政府增加老幼貧疾弱勢族群經費預算 ◎ 緊盯政府，確保民生物資充分供應、全力平穩物價 ◎ 要求政府強化扶助措施與擴大就業機會","顧孩子、挺青年 ◎ 0-22歲，加碼投資未來世代，因應台灣少子化 ◎ 繼續爭取調高育兒津貼、托育補助金額 ◎ 擴大提供公共托育托嬰，提高幼教品質與教保服務 ◎ 家庭、學校、社會三方聯防，強化兒少保護機制 ◎ 提升教育資源，維護城鄉學校師生權益 ◎ 全力爭取縮小公、私立大學（專）學雜費差距 ◎ 擴大租屋補貼、推動社會住宅安心入住","拚建設、好生活 ◎ 台74草湖匝道已通車、督促十九甲、六順橋匝道早日完工 台74銜接國道1號2024年5月完工 ◎ 爭取台63中投公路銜接國道3號，解決南台中塞車問題 ◎ 改善排水及下水道系統，防災防洪防淹水 ◎ 爭取中央預算，打通交通瓶頸、改善危險路口、通學步道 ◎ 繼續力拚捷運進屯區，藍線延伸、橘線、環狀線 ◎ 活化閒置國有地，設置綠地、公園好休憩 ◎ 保護珍貴文化資產，打造文史記憶好故鄉","重民生、拚經濟 ◎ 堅持國家經濟成果由全民共享 ◎ 力爭中央資源，解決中小企業勞工、土地、資金困境，推動傳統產業轉型再升級 ◎ 因應少子化，政府應編列經費，強化並建立人才培育及留用制度 ◎ 改善農業生產環境、產銷制度、協助解決青農困境 ◎ 持續爭取自來水管汰舊換新、普及自來水"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2519c601-5c7f-4ca5-96c7-4e5fddab8c17","items":["海洋教育從小扎根：花蓮擁有全台灣最長海岸線、太平洋珍貴的黑潮資源、漁業、海洋生態及各種特殊的海岸地形地貌等資源，……。","健康老化，減少老年臥床時間：據衛福部統計資料，國人平均餘命雖逐年提高到79.5歲，但健康平均餘命僅70.8歲，代表有長達8.7年的時間是受到不同程度的病痛所苦，……。","提高誘因，吸引青年回鄉服務：花蓮主要產業以農業、觀光業為主，這也使得花蓮的平均薪資普遍較低，加上房租及物價又偏高，這是青年回鄉首要面對的艱難困境，……。","持續關心弱勢族群、農民及環境等議題：我將接續美琴委員及振富議員長期以來對弱勢族群的關懷並持續關注農民及環境等議題，為其發聲並積極協助解決問題。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"25491161-20e9-4751-85a0-1ba93cafccee","items":["凸顯地方農村特色,推動觀光休憩產業,創造樂活新商機。","推動新住民友善照顧政策,保障婦女權益,增進獨居老人健康照護服務。","督促市府全面檢視排水系統,避免雨水無法宣洩造成災情。","監督政府,革新行政效率,落實提升為民服務品質。","督促政府加速改善投資環境,增進市民就業條件。","督促政府落實就業輔導及工安維護。","爭取擴充教學設備,提升教學品質。","堅持照顧基層權益,爭取地方建設經費,全力為地方發聲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"25c8ac37-d8dc-41c6-8526-e6bac9809171","items":["提升與民主夥伴、周邊國家的城市交流，促進各領域合作","鼓勵市府增聘東南亞語言人才，提供新住民更完善的生活 【文化友善 城市底蘊】","鼓勵藝術文化，爭取邀請國際藝術家來台辦展、參加市府活動","持續落實台北市國中小學之母語教學，包含東南亞語言課程 【母嬰友善 好孕城市】","從孕期、產後、托嬰、托幼，整體提升孕養福利","爭取高齡產婦產檢納入市府補助","提高公幼、準公幼及非營利幼兒園數量，監督品質達質量兼具","爭取月嫂補助，協助產後育兒、月子休養","計程車安全座椅補助，提高嬰兒搭車安全性 【河岸友善 親水都市】","增設樓梯、電梯設備方便出入河濱公園","河濱公園舉辦假日市集、獨木舟、划船課程與活動 【公園友善 空間開放】","增加親子特色遊樂設施，共享公園的綠意與優點 【交通友善 智慧安全】","檢視台北的用路環境，以降低交通事故風險與傷亡","透過大數據分析、動態號誌系統紓解塞車，兼顧交通安全與順暢","全面檢討、改善老舊社區停車供給不足問題 【重現中山橋，保存歷史文資】 【活化舊兒童育樂中心，改善空間價值】"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2657d341-419c-4c90-bf29-02c25b550521","items":["服務基層逞魄力、發展社區展活力","推動青年運動、創意文化入社區","推動自然環保、生態美化起源頭","推動基層照顧關懷活動、導向社會福利社區化","監督縣府積極推動屏東大學城計畫"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"26d8c6d9-65b1-457a-82dd-06d40cdfbf31","items":["要求並監督縣府全面推動品德教育，提倡「禮義廉恥」為共通校訓，導正社會道德風氣。","致力修正「雲林縣犬貓保護及管理辦法」，落實現有市場機制缺失之調整。","因應農民農地租賃機制，力促縣府全力協助農民制定合理承租配套暨適法性問題之解決。","持續完成推動口湖鄉下崙大型抽水站建置，解決數十年數千口村民水患問題。","致力協助口湖鄉第九養殖區（即：新設公魚池養殖漁業生產區）之規劃推動，改善生產環境、降低生產成本、提高養殖產業競爭力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"26e3b677-d3e5-4fa1-8e29-bcb75ffa88ce","items":["支持公民權行使年齡下修至 18 歲，讓年輕新世代皆能參與公共事務，用自己的公民權，決定自己的未來。","堅決反對台電四接填海造地，保護海洋生態及人民安全。 3 爭取捷運直達基隆站，串聯北北基都會生活圈，讓市民通勤更便利。","繼續爭取中正路公車修理廠開發為第二座東岸商場，引進大型購物中心及停車場，帶動三沙灣地區整體發展。","爭取推動義二路及和平島老街再造，提升優質生活環境並推廣低碳旅遊，打造休閒新據點。","監督東五軍港遷移進度，盡速打造郵輪產業園區，帶動產業創新，創造就業機會，振興基隆經濟。","振興傳統市場轉型，加速推動富貴市場拆除並改建為觀光市場，提升哨船頭地區的生活機能，促進就業，帶動繁榮。","爭取閒置低度利用之國有地，進行綠美化改造，增加市民多元休憩空間。","因應少子化、老年化社會現象，爭取建置社區銀髮醫療與長照系統。","解決高地用水需求，爭取加速更換老舊自來水管線，捍衛民眾用水權。","爭取台電變電箱地下化，保障人民用電安全。","推動親善動物城市，加強宣導動保法教育，廣設動物友善空間及設施，打造友善兼具休閒娛樂的毛小孩保護園區。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2730e39b-a90a-4540-ab2c-4c9d01d4c3eb","items":["強化在地語言及雙語教育，培養國家未來人才，順利接軌國際。","發揚傳統宗教文化價值，並爭取廟會傳承交流補助。","提倡運動風氣及教育，推廣體育活動，監督及爭取全民運動館。","重視文化保存、環境教育，監督及爭取活化中央廣播電台鹿港分台用地。","積極發展鹿港觀光產業，結合鄰近鄉鎮特色產業，爭取假日市集，提供街頭藝人表演平台。","落實長期照護，整合社區與鄰里資源，打造友善高齡環境；媒合義診醫護人員，為弱勢族群強化醫療照護需求及相關資訊上的供給。","促請縣府加強並推廣青年職業訓練，成立青創基地協助青年創業，建立創業平台，增加青年朋友互動的機會，提升各領域的創新能量及職場競爭力。","加強推廣寵物登記及飼主責任教育，增加預算對寵物絕育、疫苗，推動認養代替購買，改善寵物殯葬問題，落實生命教育及爭取寵物公園。","超越黨派，爭取建設，監督縣政，勤跑基層，傾聽民意，做好服務，落實社福，關懷弱勢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"27d80fb9-7944-4076-8001-cfe0cb15f66a","items":["提升緊急救難設備及搶救能量,107 年 11 月張正治捐贈花蓮消防局吉安仁里分隊,一部升級版的四輪傳動救護車,四年來總共出勤執行救護次數 3,024 件,成功急救無生命徵象患者 8 人,守護鄉親寶貴生命。","自 101 年起,於縣內廿二所高國中小學開辦「張正治議員獎助學金」,北起海星高中、四維高中、宜昌國中、化仁國中、吉安國中、壽豐國中、鳳林國中、北昌國小、宜昌國小、太昌國小、吉安國小及稻香國小等學校,九年來共頒發 10,200 名以上學生獎助學金,勉勵花蓮學子奮發向上,將來事業有成回饋社會。","與內人姜景文攜手服務鄉親,秉持「夫妻同心,為民請命」的工作使命,改善各村里設施及設備,打造更幸福更安全的生活環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"282ec5f0-f6db-499b-b77a-c2c61aaa4a84","items":["信賴台灣，團結一致拚正義，與瑾同行，打造宜居大台南！","地方建設 永康產業宜居，爭取治水預算，改善淹水問題，加速永康鐵路地下化工程，推動全民運動館建設。 新市科工重鎮，監督南科三期擴建，完備大眾交通接駁，推動新市鐵路立體化，擴大新市都市計畫。 新化文資山城，爭取纜車串聯景點，活化新化老街，改善停車問題，力促觀光發展，再現山城榮光。 闢建特色公園，強化設施品質，讓公園變樂園，大人小孩一齊享受天倫之樂。","青年未來 續推十八歲公民權，鼓勵青年參與國家未來。 0-22歲投資未來世代，擴大公共托育資源，高中職學費全免，增加私立大學生學費補助。 協助南科招商，增加就業機會，發展經濟，改善青年就業低薪問題。 落實居住正義，擴大租金補貼，續建社會住宅，提高「青年安心成家貸款」額度。","醫療長照 增加長照預算，引進資源改善長照，串聯醫療資源，加強社福照護環境，創造高齡友善社會環境。 消滅血汗醫療，改善醫療人員工作待遇，支持三班護病比入法，病患就診更安心。 設立「百億癌症新藥基金」，醫界與國人齊心戮力達到2030癌症死亡人數減少33%。","教育文化 杜絕性騷霸凌，嚴守校園淨土，保障身心障礙學生及家長權益，父母放心打拼，孩子安心就學。 落實轉型正義教育，強化國家語言教育，壯大台灣本土文化。 寬列文化預算。強化藝文工作者權益保障，培育文資修復人才。支持無形文化資產保存、傳承與再生。 提高學子科研興趣，讓太空發展向下扎根，同時豐富觀光色彩，爭取台南設立太空博物館。","體育產業 體育地位再提升，推動「體育暨運動發展部」升格，推廣全民運動，健康台灣。 落實儲訓選手零用金加碼，照顧選手生涯多元發展，發展運動產業，擴展產業規模。","交通建設 改善道路規劃，降低事故發生率，支持嚴懲酒駕肇事累犯者。 重視人本交通，翻轉以車優先觀念，建置友善安全的行人環境。 持續推動台南捷運建設，促進大眾運輸使用，建立完整路網，奠定台南大眾運輸基礎。","國防治安 整治黑金槍毒，重罰毒品、肇逃，強化國家公權力。 體恤公安警消，配補人員編制到位，增加消防預算，更新消防裝備。 備戰才能避戰，支持國艦國造，提高國軍威懾力，強化外交關係，鞏固國際民主建設性盟友。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"283cc3ec-43e9-493d-bf20-b5b4cb4719d4","items":["在地深耕、專業問政、傾聽民意、服務用心。","公民政治：推動公共議題焦點探討，讓好的公民意見納入縣府施政。","服務用心：建立選民服務機制，即時回報，您的問題，美露處理。","樂活苗栗：結合縣內山海美景與客家特色，協助地方創生經費爭取，讓觀光產業升級。","幸福苗栗：於議會督促縣府擴大服務老人、婦女、兒少、新移民、身心障礙與弱勢團體之資源，加強長期關懷與輔導等服務。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"2876ea23-53ea-4ca2-9ab3-bc59013d7999","items":["優化雙語教育，提倡運動培養、幼兒美感教育學習。","打造樂活公共空間和戶外公園，推動分齡、共融、性別友善的活動場域。","推動青年友好政策，成立國際級的青年創業研發基地。","提早規劃塭仔圳社福用地，提高青年社宅數量並放寬申請條件。","營造性別友善公共場域，設置第一座性別友善標章廁所在新莊。","弱勢保護友愛，爭取婦女保障權益，以及新住民協助輔導。","公共空間美感改造設計，兼具複合式、多功能用途。","寵物友善環境，爭取合格的毛孩運動場，推動動物飼養指南。","改善道路和巷弄行車、行人安全，建構安全、無礙的通學廊道。","平衡南北交通，增設公車路線，推動智慧電動公車，加速輕軌進程。","推動地方創生2.0，發展城市價值與定位。","催生塭仔圳新都心，結合性平、全齡、青年友善概念，打造為聯合國永續發展指標區域。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2895fa41-e632-47d3-9bd9-6c72a5140646","items":["提升在地產業與市容","協助五甲老舊公寓社區更新，改善市容，維護民眾居住安全。","獎勵在地傳產升級綠能產業，打造特色品牌，提高產值、降低污染。","伸張人民權益、共造友善環境：推動免費「婚後孕前健康檢查」，協助婦女安心懷孕。","伸張人民權益、共造友善環境：關懷新住民，加強就業、職訓、創業輔導，提升所得，增進族群和諧。","伸張人民權益、共造友善環境：設置鳳山青少年活動中心，提供12～24歲民眾室內、室外運動區、電競專區、才藝表演等多樣化休閒與教育功能。","伸張人民權益、共造友善環境：推動青年公共參與相關事項，增加施政決策考量。","伸張人民權益、共造友善環境：關心毛小孩，主張領養不棄養、結紮不撲殺；落實寵物晶片管理制度。 發展新世代、邁向國際化","伸張人民權益、共造友善環境：重視雙語教育，推動國中小學「友善英語」環境。","伸張人民權益、共造友善環境：建議成立資訊局，推動高雄「智慧城市」布局，接軌國際城市。","伸張人民權益、共造友善環境：連結衛武營、大東藝文中心、鳳儀書院成為文藝觀光廊帶，帶動經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"28b1af64-7e81-4c41-9708-175190b12988","items":["活化公園綠地，打造親子與毛孩友善空間： 盤點公園綠地，爭取有效活化，打造親子安全遊戲場域和毛孩友善空間，促進親子休閒娛樂。","農業農產升級與改善農民產業道路： 結合在地農會與縣農會推廣農產價值再提升；無論夜間巡視或清晨耕作，農業產業道路安全有其重要性，改善道路路燈照明或使用標線以保障農民安全。","推動老人食堂再進化，中央廚房有保險、有保障： 推動社區老人食堂安全升級，對村里社區老人食堂建立保險機制，更有保障。","發展綠色能源，打造永續嘉義新風貌： 爭取嘉義縣社區轉型，推展綠色能源接地氣，人民參與公民電廠生產合作社，永續社區發展目標。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"28d5bf95-fb15-443a-9c95-899d21a52ee4","items":["進擊六、市民空間大躍升 新住民事務科升格新住民事務局 1. 爭取桃園區里里有市民活動中心(含聯合場域) 閩南民俗文化科升格閩南事務局 2. 規畫桃園更多元之市民活動空間 進擊七、交通建設再進擊 女性凍卵補助 1. 持續推動綠線、棕線捷運、桃鐵地下化之進程 女性衛生棉，改善「月經貧窮」。","爭取將捷運G08車站取名「景福宮」 進擊","交通安全再晉級 籍，打造桃園成為寵物友善城市","持續監督桃園殯葬生命園區之規劃 動物殯儀館","持續爭取建設桃園市立醫院之設置 發展"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["web_promotion","heading_or_slogan"]}}},{"claim_id":"28ee7985-cb15-45df-a423-6126faf35f50","items":["力拚台積電六廠建廠營運，建構半導體產業鏈，扭轉人口外移、低薪產業困境。","推社宅、技職教育、勞訓、合作事業，緩和高科技轉型衍生貧富差距、青年窮忙、結構性失業。","產製以高雄為主題之自產國際手遊，將遊戲產業發展策略由「鼓勵玩」扭轉為「設計生產」，推展結合元宇宙、區塊鏈數位影音內容產業。","訂定以產值、獲利、就業人口成長為KPI指標之能源轉型、5G AIoT產業發展計畫。","推動以海音中心、衛武營、駁二、旅運大樓、會展中心營運為主架構的高階服務業轉型與夜經濟發展計畫。","推動以社群主題、文創事業為內涵的傳統商圈發展計畫。","建構主攻日韓中觀光客來客數為主軸的觀光政策。","強化社會安全網社區聯防，鼓勵民眾通報。","嚴促交通、警政執行降低高雄車禍死傷率相關措施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":15,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"290e1410-7760-43e7-a92c-55c9d03c8394","items":["強力監督市政，捍衞市民權益。","加強警民合作，反詐騙宣導及肅槍肅毒，維護社會治安。","興建鯤鯓安平跨港大橋，連接四草大橋，紓解塞車不便，帶動大安平區之觀光人潮。","促進安平觀光遊艇園區發展，提升觀光熱潮商機。","台南機場應軍民分離，提升為國際機場，便利商務觀光需求。","加速南山公墓徵收遷移，將其綠美化，打造成為現代化生命宗教園區。","要求南區老舊國宅公辦都更+危老條例，改善生活機能，增加停車空間與拓寬道路。","督促喜樹、灣裡市地重劃，完善公共設施及加速社會住宅完工，結合黃金海岸的自然生態，以觀光休閒振興鯤喜灣區域繁榮。","推動青年就業方向，畢業即就業。","爭取台86快速道路橋下，加強照明設備，興建免費停車場及青少年運動場。","比照五都，爭取65歲以上老人免繳健保費，減輕年輕人負擔。","爭取國中、小學童免費營養午餐。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"297e28ec-4cc0-4ba0-9624-9350f0b25f44","items":["爭取全縣生育補助津貼。","爭取弱勢老年人社會福利補助。","萬丹、新園區域排水規劃改善。","東港第一排水渠道規劃整修。","即早完成烏龍大排、改善南龍大橋橋面低陷，儘速改造完成。","發展海灣城市觀光文化交流，增加年輕人就業機會。","萬丹、新園、東港三鄉鎮地方建設未完成部份繼續爭取。","爭取大烏龍、港西西線低窪地區增設大型排水溝再匯入台17線下水道。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2984623c-0e8f-4ada-ad0f-065db85ada54","items":["持續推動幼兒福利與幼托教育補貼。","保障老人年金持續發放與醫療服務。","勤走基層做最好服務，傾聽民意做最有力的代言人。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"29aef48e-f3b1-44d3-8b08-199eb339bd46","items":["持續推展九九峰步道延伸工程，並結合當地農產業特色、藝術人文、觀光、休閒，期使能俾益地方發展。","敦促並監督縣府，落實乘車卡可搭計程車或繳健保費。","持續監督促縣府，推動高科技、綠能轉化中心，並於各鄉鎮建置垃圾分篩場，減低垃圾量，維持並提升垃圾處理的量能。","督促縣府落實相關青年政策，俾能讓北漂青年得有回鄉就業，就近照顧父母的機會。","持續監督縣府，對於推展新住民的各項業務辦理，期使新住民更融入台灣社會，了解台灣精神、文化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2a2c9292-504a-457b-b4c6-dde983c4070c","items":["一步一腳印，從基層民意代表做起，二十幾年來的從政經驗延續服務，解決民眾需求。","爭取全縣鄰長團體意外險補助。","推動公辦民營長照中心，開辦老人供餐與日托。","八卦山風景特定區放寬水土保持管制。","爭取補助農民購置小型動力農機及農業資材、肥料補助，開發農產行銷策略，降低經營成本，提高農業之競爭力及調適能力。","增設MOOVO（運點科技股份有限公司）公共自行車，促進三鄉市低碳觀光發展。","督促縣府儘速完成員林184重劃未完成的公共設施，監督重劃基金專款專用，解決員林市新、舊道路銜接問題。","推動員林市藤山步道建設為員林地區之後花園。","推動30米員林大道北側延伸至東彰路高鐵聯絡道及縣道137線山腳路交通網。","督促縣府興闢東彰路高鐵聯絡道至大葉大學之學府路。","監督縣府加速開發永靖鄉園藝景觀產業園區升級。","推動永靖南外環道闢建，東起東彰路高鐵聯絡道經浮圳接福德巷至園藝景觀產業園區。","建請縣府大村鄉、員林市石笱排水兩岸水防道路，提升為一般道路及提升道路水準，配合兩岸民眾及一般民眾使用。","針對國土規劃，請縣府就員林、大村、永靖產業及交通未來的發展辦理座談會，使民眾瞭解參與，共榮共好。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2a607bd3-7e01-4367-984d-cd1ed53b0358","items":["全力催生「青年局」，以能統整年輕人之需求，務使年輕人在政府的專責服務單位下，能工作有前景成家住有屋。","督促設置「癌之愛全人關懷大樓」。類此大樓在許添財市長時代曾經公開動土要興健，卻動土之後灰飛煙滅！在罹癌比率高漲的社會，台南市政府有責為市民健康提供更貼切的醫療服務。","請加速位於東區生產路上已延宕12 年的國立科學未來館之興建案，食言未有東區小巨蛋的政府，請積極推動東區重大建設。","增加污水下水道管路之埋設，提升市民現代化的生活品質。","還成大里民遭拆除之成大里活動中心，以多功能使用為目標，不只嘉惠成大里民，以成就多贏之高效能建設案。","爭取65 歲以上老人健保全額補助，並推動老人看病公車。","重陽敬老金應比照其他五都提高至一千五百元，並依年齡累進增加。","強化0-6 歲國家養政策，爭取普設公托公幼，提高生育及托育補助，減輕經濟不穩定的年輕父母生活壓力。","國中小營養午餐免費、減少流浪教師數額、提供代理教師完整聘期、落實特教生就學權益降低師生比保障師資。","因應通膨驚人房物價高漲，中低收入戶審議標準應適當調整以落實照顧弱勢之衷旨！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2afe8b3b-22f5-486b-a45b-0bd5e08d49fc","items":["監督縣政建設","爭取鄉親福利"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"2b3f7e75-9297-4463-a395-f1416d34d181","items":["堅守主權・守護台灣 守護自由民主體制，合理增加國防預算，捍衛台灣主權價值。","發展高雄・產業升級 協助傳統產業科技化、爭取高科技產業在地化，形成產業聚落，開創高雄經濟好願景。","便捷高雄・捷運成網 推動高雄交通建設，建立高快速公路網，加強爭取高雄捷運網建設、推動捷運黃線等四線齊發、爭取捷運紫線連結紅黃兩線，促進公共運輸發展，改善停車空間不足問題。","觀光高雄・亮點打造 打造高雄區域旅遊品牌，加速高雄機場升級擴建計畫、爭取高雄機場新增國際航班、推動高雄港郵輪母港、爭取國際郵輪停靠高雄，促進國內外旅客至高雄觀光。","治水防洪・安居安心 持續強化區域防洪治水能量、推動建立完整滯洪池防護網，打造安全宜居家園。","商圈再造・特色推廣 打造高雄觀光商圈新亮點，開創高雄火車站大商圈新氣象，擴大經費挹注、加強大連、長明、後驛、三鳳中街等商圈觀光行銷，建置工商服務機能特區。","科教升級・空間優化 推動科工館空間改造大計畫、結合優化綠園道與科工館場域、創建社區休憩共享空間、打造科工館升級高雄科學教育園區，深耕普及科學教育。","運動高雄・體育升級 推動三民運動中心升格運動園區，強化學校運動設施與空間，促進在地運動發展，提供優質運動場域。","優質教育・平價普及 落實教育平權，推動多元均質優質教育環境、均衡學術與技職教育，持續推動廣設公共化幼兒園。","推動母語・深耕文化 持續推動多元母語教育，推廣客家文化特色、爭取建設客家公園，深耕多元文化交流，發展在地文藝聚落。","性別平權・守護多元 落實性別主流化，持續打造平權職場，營造無暴力無騷擾安全社會環境。","增進勞權・捍衛勞工 保障勞工退休生活、穩定勞保基金、監督撥補勞保、促進勞工權益、基本工資年年調漲、提高有薪產檢假及陪同產檢假為十天、加強職災勞工保護、推動高雄設置勞工醫院。","完善長照・保障銀髮 持續推動優質平價長期照顧、增設社區關懷據點、擴大長期照顧補助、推動長照3.0、提高長照服務涵蓋率、加強照顧服務功能，建立友善自主的高齡生活環境。","支持青年・降低負擔 降低學貸負擔、推動居住正義、提高青年房貸優惠、擴大租屋補貼、支持青年創新創業、打造青年多元創業基地、提供優惠創業貸款。","無礙環境・關懷弱勢 持續優化無障礙環境、促進弱勢就業、加強支持系統、推動友善親子環境、推動興建社會住宅、擴大社區心理衛生服務。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"2bd35228-5840-4a82-bbfc-71f5198d704d","items":["教育：爭取營養午餐補助。","教育：教師權益維護。","教育：爭取體育發展基金。","老人福利：老人年金發放持續推動。","老人福利：持續爭取老人假牙補助津貼。","老人福利：加強老人醫療及安養照顧。","老人福利：推動爭取失智老人配戴定位失智手環。","老人福利：加強友善老人環境，讓戶外活動的人們更安心。","民生福利：協助與關懷勞工問題，保障勞資雙方權益。","民生福利：照顧弱勢族群，協助單親、中低收入戶及身心障礙者得到應有的權益。","民生福利：設立婦女保護安立之家，協助家暴及失婚婦女身心重建。","民生福利：爭取生育補助1胎2萬元、第2胎3萬元、第3胎5萬元。","民生福利：加強警消設備，確保治安及人民生活安全無虞。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2c49857d-027f-4c2f-b32c-f7b5a0bc7416","items":["推動都市更新，放寬容積，增加樓地板面積，讓老舊社區更有都市更新意願並拆除釘子戶。","市有土地活化，建構青年住宅，完成青年住者有其屋。","主張廢除12 年國教入學方式，恢復基測，減輕學子痛苦。","小平路平，爭取九十處道路重新銑鋪及側溝更新、同安街新建電梯、中華路景觀人行天橋及舊環南高架橋墩美化改善、水源永春天橋彩繪，落實地方建設。","成立多處YouBike 微笑單車及智慧型公車站亭，銜接回家最後一哩路。","督促中正區、萬華區各里衛生下水道工程銜接、修護及後巷美化。","爭取多處公園綠美化及園內各項休閒設施設置。","興建青年公園首座頂棚籃球場，於4 號出口改建共融遊戲場及體健設施、增設座椅、路燈、導擺步道及修護園路。","爭取中正區首座古亭狗公園活動專區。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2cfa5fe9-5160-4349-a93a-5be71f16ab73","items":["推動台中海線捷運路網，加速捷運藍線到台中港、機場捷運到梧棲漁港、鐵路雙軌化、海線轉運中心興建，建構便捷港區大眾運輸路網。","台中港鐵路支線觀光化，串連港區高美濕地、梧棲漁港、舶來品商圈、三井outlet、客庄觀光景點。","捷運車站設計融入在地特色，廣邀在地人才參與設計新車站。","加速海線雙港國際化，推動市鎮中心發展與台中國際機場周邊整體開發。","持續推動滿65歲老人、社會弱勢族群免費健保、免費裝假牙。","孕婦產前檢查及無痛分娩免費、0至6歲幼童育兒津貼一萬元。","爭取國中、國小免費營養午餐、弱勢學童免費課後輔導(單親、隔代教養家庭、低收入戶)。","爭取開發關連工業區二、三期，加強工廠輔導與管理。","推動海洋及風電產業技職教育及專長訓練，創造地方商機與就業機會。","爭取海線會展中心、濱海遊憩區與大型購物中心投資，促進港區經貿發展。","持續台中市樹木保護與動物保護工作，推動大肚山、海岸濕地自然生態保育。","加強海線河川（南勢溪、米粉寮溝（清水大排）、梧棲大排、安良港大排、仁民中排）污染監測與防治工作，運用ＡＩ人工智慧提升環保查緝成效。","推動台中港區污水管線建置與家戶接管。","推動海線古蹟歷史建築活化再利用，促進觀光旅遊導覽。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2d41ca1b-b652-45db-9ac0-208e279b68b7","items":["要求市府加強稽查力道，爭取空污、水污智慧檢測機制。","要求市府比照雙北1280推出桃園大眾運輸通勤月票，爭取公車預算，培養捷運運量。","要求政府推動公寓大廈管理升級，爭取政府輔導機制、提供專業諮詢服務。","棕線捷運進度，隨時監督、誠實回報。","大崗高中獨立設校、大坪頂公園擴大範圍。","文青國中小準時落地、活化滯洪池增加公園綠地。","專案預算補助眷村國宅「中庭公園化」。","第一公墓遷葬完成，爭取大山頂萬坪共融公園。","電線桿地下化、增補清潔隊人力改善市容。","尋找迴龍公有空間：活動中心、便民服務、圖書分館進駐。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2d437ee1-b963-47dc-ac42-6ba072a54411","items":["設立綜合社福中心：要求縣政府在湖口設立綜合社福中心，提供幼托、長者日間照顧及公立坐月子中心等全方面服務。","湖口增設特色公園：公園設施考量全年齡層民意，設置兼具在地特色與實用性的遊具及公共設施。","監督縣政府加快榮光路拓寬進度，舒緩新竹工業區上下班塞車困擾。","增加縣內國小實施課後輔導的班數，特別是偏鄉小校。縣府應加強媒合青年志工資源，鼓勵年輕人擔任志工。","勞權教育除現有的國中以外，持續推動到高中及大專院校。縣府主辦的青年學習活動，應納入勞動權益主題。","新竹縣累積上億元的身心障礙者就業基金，應積極運用，由縣政府主動創造適合身心障礙者的就業工作機會。","重視鳳山溪北建設，要求溪南溪北均衡建設，推動AI親子公園、國民綜合運動中心及埤塘步道休閒。","重視湖口人文氣息，爭取中大型藝文中心。","檢討公車行駛問題，解決偏村交通，爭取湖口環狀公車。","推動農業精緻化、科技化，打造湖口宜居綠城鎮。","監督嫌惡設施，嚴審縣政不當施政。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"2da90323-2afb-4237-aa87-b20a0da7a7b3","items":["輔導青年創業，建構地方創生特色產業！","行銷體驗觀光，發展金門休憩旅遊亮點！","推動幸福長照，打造青銀樂活美麗家園！","爭取東西平衡，積極擘畫金湖！","推動多元賽事，形塑金沙縣級運動基地！","以心為「新」，爭取新住民友善環境與生活！"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"2ddcc3a9-99cb-4e33-9280-3e9031cb58e8","items":["提高原住民購屋補助。","持續關注原住民各項福利政策。督促政府落實執行。","制定原住民年滿55歲就能享有長者各項福利。","強化族語學習環境。 落實族語家庭化。","堅持專業全方位的服務。 嚴守清廉從政不包工程、不從事非法事業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2e1b24d8-5ad5-4479-8bcb-5e01fc2462a5","items":["支持興建金廈大橋,繁榮大金廈生活圈。","推動小三通之復航,力挽金門低迷經濟。","督促縣府開源節流,正視嚴守財政紀律。","提升金酒營運績效,富裕縣庫支應建設。","強化長期照顧體系,布建更多服務資源。","開展新四通(通水、通橋、通電、通氣)之規畫,融合兩岸繁榮金門。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2e6c962d-02fa-40ea-8724-b4514ecdadb0","items":["新基建-改善基礎建設，擺脫老舊都市，活化閒置空間，創造市民活動空間，持續汙水下水道建置、汰換老舊水、電、瓦斯管線，打造優質生活環境。","新安居-加速、鼓勵危老都更，爭取更多公辦都更機會、活化閒置場域興建社會住宅，守護市民居家財產安全。","新捷運-推動秀朗區段捷運規劃完善大眾運輸路網，優化周邊交通，改善聯外交通路線，通勤路線更加多元方便。","新校園-提升新北教學品質、校園環境與新北技職教學，推動特色教育和在地就學，建置全面性校園安全網，守護保護學童更安全。","新社福-重視社福關懷，建置銀髮俱樂部及日間照護中心，完善在地醫療體系，讓長者得到最好的照顧，鼓勵銀髮學習，讓長者走出家門，享受樂適快活不在家當LKK。","新育兒-完善婦幼政策，打造共融環境，結合產、官、學力量，讓公托、幼收量成長，減輕家長壓力，讓父母安心，打造特色共融公園與友善校園，讓親子同樂共享好時光。","新商圈-改造舊有商圈，振興地方經濟，保存在地特色，研擬「商圈自治發展條例」法規，永和每個角落都充滿太多故事，延續在地價值，透過熱情與理念，傳承世世代代。","新保育-打造保育都市，豐富綠色生活，打造生態遊憩資源，創造自然環境教育的體驗，為當代與下一代人們更好的環境發展，都市保護區是重要的公共空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2ec4390a-c0f6-4963-84a4-22fad9051e0d","items":["繁榮社會：增設社會住宅減輕入住負擔；強化法制保障租屋權益；擴大AI與城市治理帶動生活產業發展；守護勞工權益增進勞動所得。","自信台灣：強化國防自主實力；平等互惠國際合作；增補臺灣人力裝備。","多彩高雄：打造立德棒球場成為三級棒球基地；以動物權精神推動友善空間及臨終制度；發展城市擬人化、實境角色扮演等新藝文產業；提升運動設施擴大體育人口。","安心環境：完善大眾運輸發揮串連效益；加速淨零碳排促進產業升級；精進道路設計提升交通安全；推廣電動共享運具改善空品。","溫暖生活：深化尊重教育防治暴力霸凌；增設共融遊具打造特色公園；擴大長照設施服務量能；爭取急難弱勢補助相互扶持。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"2ecffe2c-627c-41a8-b529-288460760001","items":["改善台北停車問題 ・爭取於校園改建時增設地下停車場，創造更多停車空間。 ・推動更新現有老舊立體停車場、增設新式機械停車場。 ・推動公有停車場運用車牌辨識系統驗證資格，讓全部在地里民皆享有停車優惠。","打造友善育兒城市 ・推動台北市聯合醫院婦幼院區升格兒童醫院，強化兒童醫療。 ・爭取新設服務業家長適用時段之公托，讓更多家長可享受公托福利。","打造寵物友善城市 ・爭取增設狗狗活動區，讓飼主可就近帶寵物放風。 ・推動寵物友善交通運輸，讓中大型犬也能便利出門。","活絡市場商圈發展 ・爭取傳統市場優化整建，為市場注入新活力。 ・爭取市府協助商圈發展特色，再創地方繁榮。","推動民生汐止線 ・督促市府加速捷運興建工程，提供居民便捷交通並促進沿線商圈發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2eec230a-56a1-4f97-8cf0-8bea596f9bef","items":["傾聽民意、深耕基層、最瞭解鄉親需求，認真打拼，服務看得到。","爭取經費，全方位推動地方建設，促進地方發展；規劃闢建產業道路、出海路，以利農漁民生產運輸，提高農漁業收入。","爭取道路養護經費，以維行車安全；加強區域排水浚渫及排水溝渠清淤，以維排水暢通。","結合和美區觀光資源，推動地方觀光產業，增加鄉親觀光收入。","爭取經費，配合社區社團辦理社區生活講座或聯誼活動，並結合地方公益團體，加強扶助弱勢、守護婦幼、關懷長青福利，以利鄉親安居樂業。","全力促進地方產業轉型及升級，以及農民提升農業智能、推廣休閒農業，以利地方農工業均衡發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2f2547b7-c14a-479b-b1b1-c3636e44e089","items":["【農工綠能新經濟示範城市】：推動地層下陷及低地力區、非公有建築屋頂型綠能設置納入本縣綠能政策重點，並制定自治條例，使本縣成為節能減碳綠能農工大縣。","【長照與社會福利．弱勢照顧】：持續推動低收、中低收及身障者納入微型保險補助；放寬社會邊緣戶補助認定，加大弱勢族群保護傘。爭取長照福利政策，完善社區長者照護系統。","【品德扎根．教育力及校園安全環境提升】：品德教育扎根，堅實學童健全人格與身心發展重要基礎。推動老舊校舍整建及充實電腦、英語教學視聽設備，及改善體育運動設施場地安全，提升全方位校園安全學習環境。","【大北港區宗教文化、產業觀光讓香客變遊客】：北港糖廠及萬有紙廠土地活化，強化北港、水林、口湖宗教文化、地景特色風貌（宜梧、北港滯洪池）及產業觀光發展，招商引資，吸引青年返鄉人口回流。","【爭取設立海線國民運動中心】：爭取山海線民眾運動休閒場館建設的公平正義，不讓民眾健康及運動權利遭受差別對待。","【環境永續、海線農廢再利用】：推動沿海廢棄文蛤殼回收再利用，讓農廢變資源，降低環境污染，使垃圾變黃金。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"2fb20372-caf1-4847-9a56-dc74d67c8dce","items":["專業問政、理性敢言、把關預算、嚴格監督縣政。","永遠站在雞蛋（弱勢）的一邊，為弱勢族群（原墾農、勞工、農民、身心障礙者、婦幼、新住民）維權發聲。","支持偏鄉教育，平衡城鄉落差。推動特色教學、外語學習、行政減量、教師安定、校園安全、實驗教育。","提高文化藝術經費與完善公共展演空間，扶植在地文化創意團隊。","整合自然、文化資源發展阿里山深度旅遊，打造國際觀光品牌，行銷在地優質農特產品。","改善山區農路、村里聯絡道與編號公路系統之交通品質與安全。","支持低碳減塑，增設綠能設施，深化環境教育，嚴管公害污染，追求永續發展。","捍衛居住正義，推動房地稅率改革，督促興建社會住宅，加強租屋市場透明化及弱勢租金補貼。","保障青年就業及勞動權益，落實勞動稽查。輔導青年創業，建立在地優質品牌。","增加育兒津貼及友善親子空間，廣設托嬰、托育中心、兒童館，提供社區親職教育與喘息服務，爭取兒童遊戲權及共融式遊戲場，減輕爸媽育兒負擔。","強化社區老人照護據點之服務品質與公共安全，落實在地老化、活躍老化、快樂老化。","倡議農業優質化、科技化、企業化，掌握農情，精準生產及行銷，為農民創造收益。","促進城市前瞻治理，強化科技智慧管理，辦理專業研討會議與國際交流。","堅定台灣主體價值，支持正名制憲、進入聯合國，追求台灣國家正常化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"2feba5f0-302a-4018-9982-6e2536e32e1d","items":["全力協助推動成立農業發展協會，以爭取農業政策補助及維護農民權益。","全力協助爭取在地肥料供貨中心，使農民購肥方便降低其生產成本。","積極爭取農路改善之經費，並嚴格把關施工品質，以提升農民工作環境及用路安全。","強力爭取旅行部落生態旅遊及文化體驗觀光並爭取相關軟硬體設施之經費，創造地方就業機會。","全力協助文化健康站爭取長照經費，以改善站內環境及基礎設施，強化社區長者照顧關懷據點。","重視並協助都會區原住民辦理居住、就學、就業及社會福利之事宜。","積極爭取縣府經費，協助公所辦理各項運動事務及歲時祭儀。","督促縣府辦理部落消防演習、爭取改善警消設備及演訓之經費，以強化救災及救護量能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"30113679-d271-4ccc-ae46-f4039869d9e0","items":["督促捷運綠線大坑延伸線儘速動工、捷運橘線、紫線路線儘速核定，完善捷運網及接駁公車路網。","照顧長輩，增加佈建長照資源(如日照中心等)、提升居服員福利增加照顧人力，讓年輕人不擔心長輩照顧問題，能安心工作。","督促地方重大建設加速進行，水湳會展中心、水湳轉運站、北屯國民運動中心、台中巨蛋、重劃區新設國小國中等建設之推動。","督促社會住宅興建，促請市府盤點北屯區市有地，增加北屯社會住宅戶數，讓青年朋友、弱勢市民不用擔心住的問題。","促請政府挹注更多資源協助青年創業、簡化青創貸款申請，增加青年就業機會，讓年輕人能對未來充滿希望。","北屯機捷特區、12單元重劃區聯外道路開闢，紓解未來重劃區交通壅塞問題。","爭取北屯區好玩特色公園(如親水設施公園、輪動場設施公園)、確實納入使用者意見、引進職能治療師專業意見，打造全齡都能使用的公園。","增設公托、公幼、增加公立2歲幼幼班，督促北屯親子館興建。強化臨托功能，建立緊急臨托服務、公設臨托據點，提供育兒喘息服務。照顧懷孕婦女、生產後婦女、新手父母心理健康，提供心理諮詢協助。","幫忙解決婦女生育與就業二擇一的困境，加強婦女就業培力課程並輔導就業，獎勵企業任用，協助婦女重返職場。","打造北屯水岸綠廊，改造北屯區旱溪水岸及大里溪水岸，打造北屯觀光休閒亮點。","爭取整合資源，活化大坑商圈，結合大坑步道改善之進行，創造觀光、農產及商業行銷結合的大坑。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"30312a75-dd49-4d1c-9351-4e2b48e803f7","items":["監督縣政。","推動彰化市東區盡速完成擴大都市計劃。","推動彰化鐵路高架化工程早日動工。","支持警政、消防及防災預算，打擊犯罪，強化防災。","爭取婦女朋友福利，提升生育率，並支持增加婦女第二、第三胎生育補助及幼兒教育補助金。","督促政府關懷婦幼安全及權益，弱勢族群照護，銀髮族身心保健。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"30861439-11d6-4ed7-a2c3-4080465a3e65","items":["原住民土地權利，解決原住民保留地……等土地相關問題。","各部落聚會所土地取得以及相關程序上問題，儘快完善各部落聚會所，落實一部落一聚會所，並建設多功聚會所，讓建設有一物多用的功能。","原住民長照服務體系，讓部落老人家老有所根、心有歸屬，並發展老幼共學，發揮部落長者的智慧與部落一同學習一同成長，實踐文化傳承。","原住民優秀子弟公費留學機會，讓優秀原住民子弟能拓展眼界、擁有國際觀和大格局來回饋部落、鄉里。","體育人才培育及完善後續職涯規劃，讓優秀的運動健將能留鄉有所發展。","婦女權益，協助舉辦相關研習課程發揮部落婦女所長，讓文化、藝術、手工藝……等，文化傳承重要工作，在生活中的每個角落。","爭取原住民疫情重創補助金，因疫情重創生計的家庭，藉由這類補助能轉型、重建原本產業穩定生計。","免費法律諮詢、案件調解服務，解決土地案件、勞資糾紛、行車糾紛……等棘手法律問題，守護原住民族友的法律權益。","齊頭式教育環境，爭取原民教育補助編列，讓花蓮的孩童有更好的教育師資、環境、設備。","監督政府增加編列原民各項福利預算。","醫療體系的人員編制和醫療效能、相關醫療設備是否在重大傳染疾病擴散前能有效防堵、運作，保障所有的生命安全。","原住民部落相關基礎建設，與鄉里基層民代合作，傾聽地方所需。","原住民傳統領域相關課程、計畫，扶植部落培養部落優秀人才。","積極爭取婦女權益，協助辦理各項婦女研習。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3092192d-ce78-4b14-a1f7-738c565b7030","items":["友善親子共融環境 | 推動共融式遊具公園，打造親子共遊環境。","社區安全絕不退讓 | 集結社區共識，推動居家環境安全。","社區關懷永續經營 | 推動各項學習課程，落實社區關懷活動。","推動觀光接軌國際 | 藝術文化進駐，活絡產業，提升就業率。","推動市區便捷巴士 | 推動市區交通網路，增進共運輸量能。","榮民榮眷權益 | 保留眷村文化，推動眷村再造計畫。","新住民照顧協助 | 開設文化課程，推動交流活動。","居住品質優化 | 爭取經費改善路面整平及排水系統。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"309d859e-477c-42f6-b7ec-afc468afb1d5","items":["政府正視獅球嶺步道改善及環境維護工作。","政府發展紅淡山、獅球嶺觀光登山活動，吸引外地人利用假日時間搭乘大眾運輸工具前來登山，同時帶","觀光產業發展。","政府改善假日市區塞車問題，妥善進行道路交通維持工作。","政府改善少將頂、南榮新村、獅球嶺等地區高地供水問題。","政府對於公園街、自來街等老舊社區進行環境改善，活化商圈，再造榮景。","政府對鄰里公園盡速進行兒童遊具改善，並適度改造鄰里公園為社區共融公園。","政府強化對於弱勢、身心障礙人士的生活照顧，協助鄰里推動相關照顧工作。","市政府增加公托、公幼的名額，減輕年輕父母的負擔，並推動幼兒智慧教育。","推動「美化商國、老宅更新」，以利青年就業及創業。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"309f28cc-6c8a-455e-af01-06c2c13fc736","items":["堅決保護林內鄉居住環境與土地的決心，持續監督林內焚化爐後續終止營運過程。為避免重大公共建設閒置，建議在相關專業機關（構）及地方民意之評估需求下，將焚化爐轉型種籽銀行、農業新創基地，除了可以帶動雲林農業，可以與鄰近水利文物教育園區結合，成為農業環境教育園區，提高觀光產值。","規劃與企業、縣內大專院校合作月光天使輔導計畫，利用學校空間或圖書館，針對單親、新住民、弱勢家庭及隔代教養家庭提供寒暑假課後輔導。","持續推動樂齡學習中心、增設老人關懷據點、長期照護巷弄站及長青食堂。","全面規劃及施作排水設施，並整合地方政府農水路與水利會職權，以解決一區排水多方管轄之問題。","督促縣府發展縣內農特產重鎮，利用林內、莿桐、斗六地區豐富的農特產及便利的交通網路，設立農特品行銷中心。","督促縣府積極解決空污問題，改善縣內空氣品質。","「清廉從政，勤奮問政」，堅持問政優良品質，全心做好為民服務之職責。","維護紫斑蝶、八色鳥大自然生態環境及文化維護，讓土地一直美好，讓河川永續美麗。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"30fe94ac-541c-4225-ade7-9fd3987ddce1","items":["交通再邁進:加速推動鐵路立體化延伸至楠梓、橋頭,縫合楠梓市容拆除楠梓陸橋。打通楠梓產業園區串連仁武楠梓,新設楠梓產業園區通勤車站。新台17線南段加速推動,分流翠華路車流。","產業再邁進:中油舊五輕廠汙染整治進度持續監督,楠梓產業園區台積電設廠進度持續關注,創造在地青年就業機會,促進後勁社區發展。","青年就業再邁進:持續推動青年就業輔導、創業投資輔導政策,補助青創優秀人才、加強青年實習媒合,提升青年就業率,返鄉青年不必再出走。","育兒政策再邁進:左楠區人口發展快速,力促廣設公托、公幼、育兒中心,減輕家長負擔鼓勵生育。持續推動企業設置托育機構,友善職場環境鼓勵雙薪家庭勇於生育,改善少子女化!","生活品質再邁進:持續推動共融式公園、關注空氣品質改善、督促人行道整平電纜下地,打造友善身障、親子及樂齡各族群的宜居生活環境。","長青樂齡再邁進:關懷老人長輩族群充實長照人力,爭取閒置空間打造長照中心、推動一里一社區關懷據點,長輩都能活到老學到老。","都市規劃再邁進:推動左營眷村閒置用地都市更新,爭取社宅、軍宅及托育、日照等公共設施進駐。","蓮潭觀光再邁進:打造蓮潭文化園區,由蓮潭風景區串連兒童公園、舊城古蹟、見城文化計畫、親水活動,力促蓮潭觀光再翻轉,打造左營高鐵門戶。","後勁溪畔再邁進:高雄不只有愛河!持續督促後勁溪水質整治,並推動後勁溪畔打造親水空間,爭取假日市集活動辦理,打造後勁溪畔特色風光。","議會過半再邁進:持續用心監督專業問政,共創高雄華麗轉身新世代!"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3129d1fd-2eb4-40d8-9309-57ff77345d7b","items":["「給孩子更好的未來」是我的承諾。打破政治世家的包袱，羅廷瑋是小家庭的發言人，更懂大家的心聲與需要。我承諾市政、經濟與福利優先，理性問政。","推動特色好玩公園及親水公園。","持續增加公立幼兒園與公共托育。","持續爭取親子館並增加內部軟體設施。","已爭取社會住宅900戶，後續持續推動社會住宅。","監督市府老樹保護及柳川整治。","持續改善更新校園環境。","協助民眾申請輔具及處理就業問題。","推動兒童早期療育篩檢補助。","爭取加強節電優惠補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3137535b-1867-4e73-b8ae-cbd3d6d55eab","items":["監督縣政：落實預算審查，看緊人民荷包，做人與政府溝通的橋樑。","爭取資源：連結中央部會與國會資源，推動地方建設發展。","世代共融：推動「老幼共學」課程計畫，打造進階長者照護模式。","長者健康：推動各社區據點裝設AED（自動體外心臟去顫器），於緊急狀況時爭取急救時間。","兒童遊戲安全：重視共融式、口袋公園遊具的安全管理維護，為孩子遊戲安全嚴格把關。","重大交通建設：加速屏東縣內各項重大交通建設規劃期程、以及施工進度。","亮點觀光：盤點屏東市觀光資源，並結合各文創園區（勝利新村、屏菸1936文化基地、大武營文創園區），建構完整的屏東市觀光地圖。","青年就業：透過屏東科學園區促進產業升級，增加高薪就業機會，讓青年不再北漂。","環境永續：推動「太陽能面板回收機制」，以行動落實環境永續發展。","空汙防制：持續推動制定《跨縣市空汙防制計畫》，力求有效減緩屏東嚴重空汙。","照顧農民：強化農、漁產品冷鏈系統，整合內、外產銷系統，搭建國際農、漁特產品銷售平台。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3170aa85-f161-4980-8cb6-6f17ab0fb5a8","items":["捍衛中華民國，守護臺灣！下架民進黨，避戰爭，保和平！","平衡區域發展，落實花東建設。","繼續推動環島高速路網。","推動環島高鐵路網、宜蘭延伸花蓮。","持續完成花東雙軌電氣化、花蓮市吉安鄉七個危險平交道高架化。","治山防洪，提升防災型基礎建設。","打破城鄉差距，全國65歲以上長者免健保費。","爭取台灣燈會及國際賽事在花蓮。","友善生育補助，支持兒少教育。","強化居住正義，完善銀髮長照。","協助農業發展，開拓外銷市場。","推動港區開發，觀光休閒漁區。","扭轉能源政策，確保產業升級。","落實平等教育，推動16年義務教育至大學畢業，培養弱勢生享有同等受教權。","推動大學與企業合作，企業晉用青年並提高工資得減免稅賦，解決青年低薪困境。","國家開放外資，投資臺灣，並訂定本國勞工比例不得低於80%。","國家訂定本國勞工與外國勞工薪資脫勾，留住台灣人才。","國家支持青年成家專案，補貼首次購屋利息50%，期間15年。","國家訂定長照「時間銀行」之完善配套，以利老人安養關懷。","信賴保護、回復正義，對不合理的軍公教年改要廢止，實現國家承諾，返還公道。","持續推動寵物友善環境，增設寵物園區及運動空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"31d0bd63-eb57-4730-b05c-f27e67c99fe9","items":["持續捐血、做志工，推動社會善良風，帶動民代優質服務。","持續堅持三不：不交際、不應酬、不包工程，全職服務、監督市府。","已建制全市最多路口監視器及停車場設置(育賢路 900 格停車位)，持續爭取充電樁改善太平區治安及停車不足問題。","持續爭取公車候車亭興建及公車串聯讓公車族更方便。","持續督促市府培訓失業勞工第二就業專長及多舉辦就業徵才活動，以改善失業勞工就業問題。","持續督促市府輔導農民發展精緻農業，改善農業發展、增加農民收入，打造太平成為台中的小瑞士。","持續督促市府寬列預算，充實警察、消防及救災人員之裝備設備，以維護第一線救災值勤人員之安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["past_achievement"]}}},{"claim_id":"31d4842b-b334-4051-8f48-58a1471c7010","items":["強力要求增設科學園區聯外道路，解決園區周邊交通壅塞問題。","督促園區污水廢氣排放，落實環境保護工作。","敦促市府加強開辦社區關懷據點，推動老人健康篩檢，加強體適能檢測與正確運動指導，增加失智症篩檢量表，延緩失能失智，落實老人照護。","敦促市府廣建日照中心達到一國中學區一日照。","敦促市府於關埔二期增設國中小學，以利學童就近入學。","爭取打造友善公車，透過科技輔助及政府監督，提升公車文化。","敦促市府加速興建汙水下水道系統，改善區域排水。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"31f508ad-ea0b-4351-a937-18680b155aeb","items":["督促市政府釋出閒置空間建築物，作為原住民文健站及社團辦公據點。","督促市政府重視原住民弱勢家庭扶助，鬆綁相關法規，落實公私資源整合。","督促市政府重視與協助原住民教會推動社會公益活動，減少犯罪行為之發生。","督促市警局重視原住民警消人員工作升遷之保障，並且確實發放重點加給津貼，符合公平正義。","督促市政府增編農路維修預算，暢通農產運輸要道，方便農產運銷。","督促市政府結合茂林風景區管理處之行政資源，推展原鄉觀光產業發展，增進原鄉居民經濟收入。","督促市政府重視原住民文化教材之編撰，提供教師教學及學生自學之資料庫。","督促市政府興建專屬原住民社會住宅，保障都會區原住民家庭居住正義。","建置都會區原住民健康大數據，預防疾病、延長壽命與增進健康之作為。","督促市政府盤點高雄S廊帶半導體產業園區所需人力，主動媒合產業與學校養成教育，促進原住民青年學子落地就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"32055847-bc7b-40d3-bedf-4b6a507d5fd3","items":["積極爭取婦女權益,協助辦理各項婦女研習。","協助青年提升職業技能,爭取並創造就業機會。","積極籌設物資銀行,使急難受助者能即時獲得協助。","努力推動原住民部落特色產業,開發建立行銷平台。","關懷照顧老弱婦孺、低收入戶、單親及高風險家庭。","積極協助急難救助,法律扶助及交通事故的工作。","努力推動原住民族語學習及文化扎根工作。","積極督促政府辦理各類公職考試輔導。","積極爭取各部落聚會所設立,文化場域設置。","努力爭取原住民地區各項建設。","積極爭取原住民文化健康站,達成每部落皆有文化健康站。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"322f85d2-dbb5-4ea3-a897-cc9a5b798530","items":["充實澎湖體育硬體設施，推廣全民運動，培育優秀體育人才。","督促縣府正視澎湖醫療、交通困境，研提有效因應方案，增進澎湖縣民福祉，達成幸福城市目標。","促請縣府規劃馬公市、澎南區觀光動線，帶動澎南區經濟活絡。","督促縣府嚴密控管澎防部、團管區外遷作業期程，俾利馬公市區活絡繁榮。","積極爭取中央經費，以斜張橋方式改建澎湖跨海大橋。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3232dcca-c7fc-4cb3-9d43-43069219f445","items":["(二) 監督縣政府施政，做好民眾與縣府的橋樑。","(三) 為地方爭取實質建設，帶動地方觀光發展。","(四) 爭取相關農作物之補助，促進農業永續發展。","(五) 爭取年輕人及青年返鄉工作機會，由年輕人帶動地方發展。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"32665e70-a946-4782-a2ac-22446901cba0","items":["理性監督縣政，為民服務，全力以赴","持續爭取地方建設，繁榮地方發展","持續爭取經費補助優質社團，活絡樂齡族學習休閒場域","持續關心並爭取長輩、婦幼、弱勢族群權益，督促政府強化長照服務及社會福利補助政策","加強促進農漁業多元化，促請縣府結合觀光農漁業、強化在地品牌，創造在地觀光產業鏈","優化各級學校軟硬體設備，提升學子競爭力"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"329bd52c-437a-4b53-b891-e35d546384eb","items":["1 經濟要創新 打造科技島 ・強化半導體國家級戰略，產業導入AI、5G與大數據應用，打造智慧科技島。 ・加速綠能科技，超前部署減碳與自動化提升競爭力，穩健邁向2050淨零目標。","2 增建停車場 社後蓋捷運 ・持續爭取地下停車場，建構捷運、公車、單車和更友善行人的大眾交通環境。 ・加速興建泰板輕軌社後支線，讓社後居民出入更便利，生活機能更完善。","3 長輩要照顧 樂齡輕鬆GO ・檢討巴氏量表標準，強化喘息服務；打造居家、社區、醫療一體式長照服務。 ・提高敬老卡搭乘台鐵補助額度，爭取未來也能搭高鐵，鼓勵長輩外出走動。","4 司法要改革 修法打詐騙 ・修正「法官法」，加強對法官及檢察官的行政監督責任，改善司法審判品質。 ・針對金融商品P2P等新型借貸設立專責篇章，杜絕假債權及金融詐騙。","5 板橋再進化 在地好生活 ・督促新板特區國家兒童未來館如期興建，打造出亞洲第一的兒童遊樂場館。 ・加快都市更新、危老整合的審議通關時程，加碼補助老舊公寓安裝電梯。","6 照顧下一代 國家一起養 ・爭取廣設公托公幼；推動公共幼兒園寒、暑假服務，延長平日晚間托育時間。 ・提高生育、育嬰留職停薪津貼補助，加碼坐月子補助，讓年輕世代安心生養。","7 弱勢要照顧 城市更友善 ・修法中低收入補助要實際貼近救助申請者的生活現況，通盤檢討計算標準。 ・加速《動物保護法》修法，建立公共寵物殯葬服務，寵物往生善終有依靠。","8 體育要扎根 教育更多元 ・運動全民化、多元化，提高預算補助各中小學如足球、街舞、直排輪等社團。 ・國中、小學開設「情感教育課程與教學」，避免校園性騷擾、霸凌問題發生。","9 投資新世代 畢業即就業 ・支持青年創新創業，提供資金及擴增地方創生工作站，支持年輕人在地創生。 ・投資技職教育，串聯技職學校設備、師生和產業界的需求，讓畢業即可就業。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"32a8b60a-5dbf-427b-8950-27fa78abd162","items":["**爭取資源** 連結中央部會及國會資源，建設第一，服務優先。","**亮點觀光** 打造竹鹿觀光軸線，推動低碳輕旅行，串連觀光產業策略聯盟；推動宗教文化結合美食嘉年華，帶動地方發展。","**健康樂活** 爭取多功能運動環境設施，打造親子健康運動公園。","**建設產業** 補助各村里及社區改善經費；持續推動南雲交流道西向通彰化快速道路，串連彰化生活圈；推動竹產業園區。","**保護婦幼** 提高生育補助津貼；推動受家暴婦幼緊急庇護所；整合公部門與民間資源推動「微型保險」擴大免費納保的弱勢族群。","**照顧農民** 推動農產市集並整合產銷平台，搭建農特產外銷電商，協助茶葉及農特產行銷，推動設置青農基金。","**升級教育** 升級電子化教學環境，改善資源不均，健全線上教學。","**青年返鄉** 開設青年返鄉創生資源媒合平台，推動青年發展單一窗口，輔導補助基金申請，提高青年首購自住房屋補助。","**老人福利** 推動敬老愛心卡搭乘火車；補助老人輔具；建立獨居老人安心通報網；設置樂活老人日照中心，完善長照服務。","**新住民權益** 友善新住民生活環境，挹注經費，提供免費法律扶助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"33604f6c-d97b-42fa-b586-3a4c5bf112f2","items":["務實監督彰化縣政府，確保政策施行符合民眾權益。","如實反映民意，成為民眾和縣政府之間溝通的橋樑。","爭取地方基礎建設，改善道路行車品質及排水系統。","加強警消預算並強化裝備，保障人民生命財產安全。","積極關懷並協助弱勢團體，傳遞公益理念無遠弗屆。","深化文教建設基礎，鼓勵積極參與並強化社區認同。","縣內推廣各項體育活動，強身健體並創造運動經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"340b3db8-f276-4e61-bcd1-c7bd205b0ff2","items":["持續推動捷運外環線北環段：1.蘆洲、社子、後港地區連結至士林捷運站。","泰北高中連結至文湖線，繁榮士林、北投、社子交通。","推動社子島開發：1.以最優惠之拆遷補助方案，落實戶戶配售公有住宅。","打造社子島成為市民的生態城市綠洲。","4年內全力協助全市國中小轉型為100%雙語學校；優化公共托育及提升育兒、托嬰各項補助，改善青年家庭負擔。","保障青年就業：提高與放寬青年創業貸款額度；擴大企業與學界之建教合作與實習機會。廣建青年住宅：降低首購門檻，青年輕鬆圓夢成家。","增設樂齡照護發放敬老年金：推動65歲長者免繳交健保費、完善長照機制，增加日照中心並擴大敬老卡使用範圍，確保4年內敬老年金不中斷。","照顧弱勢族群：保障身心障礙人士就業機會，全市全面增設無障礙空間，扶持變故家庭提供即時急難救助；輔導外籍配偶職訓與就業機會，提供諮詢與全面協助。","再創樂活經濟園區確保居民居住權益：推動關渡平原連結北士科，蘊藏寫意經濟動脈；修改陽明山不合理之都市計畫，制定陽明山特別地區條例，確保當地居民居住權益。","健全工業宅條例推動合法工業住宅：配合產業發展重點地區及在地居住使用需求，推動工業宅條例調整變更，確保居住權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"345ee693-152f-4158-bb04-6a82a90c5041","items":["醫療照護 打造醫療照護城市 已爭取臺大二期擴建，拚醫學中心 全國首座國家級高齡醫學 暨健康福祉研究中心經費150億元","社福溫馨 周延全齡照顧體系，國民年金再加碼 推動長照3.0，爭取坐月子津貼6萬 0-6歲國家養2.0，加碼社會住宅 彈性育嬰假","教育優先 提升校園設施、特教品質 打造友善校園，減輕教師行政負擔 推動營養午餐專法","產業專精 AI智慧產業轉型，持續推動雙技農業 培育跨域產業人才，媒合高齡科技產業 落實勞動職場安全","農業轉型 老農津貼再加碼，綠色照顧普及化 成立跨域青農陪伴育成中心 西螺果菜市場升級國家級智能市場 古坑產業加值園區","城市翻新 加速農水路溝渠改善，推動危老重建 督促斗六鐵路高架化 古坑側車道向北延伸 完成149甲清水溪橋興建 打造濁水溪堤防南側道路 爭取百年濁水溪抑制揚塵21.7億元 （持續爭取第三期8.1億元） 全民體育扎根計畫","文化魅力 再現斗六糖廠新魅力 世界客家博覽會在崙背 設立斗南鐵道文化園區 推動樂齡觀光巴士 打造河川綠色廊帶"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"34905f8a-da6d-4dfe-8908-53a56f1883d5","items":["美燕議員對於南區、安平區未來發展的構想。","都市建設：南區南山公墓活化、灣裡抽水站興建、安平區漁光島建設，都市機能再升級。","交通便捷：拓寬道路、路面修繕、增設停車場，無障礙設施普遍化，完善交通系統。","教育發展：提升學生競爭力，持續加強產業、學校、培訓合作，讓畢業即就業，讓教育持續扎根。","鄰里更新：加速傳統市場更新、鄰里公園改造，提升居民生活品質。","親子友善：擴大育兒津貼發放對象、增加提高育兒津貼額度，爭取一公園一親子友善廁所。","文化軸線：水交社眷村文化、灣裡鯤鯓喜樹宗教文化、鹽埕臺灣第一鹽文化、安平歷史文化，共同打造文化生活圈、再現文藝復興與創新。","就業無憂：開創在地產業資源，開拓經濟機會，協助青年創業與成家。","照顧老弱：完善托老機構，減輕家庭身心壓力。","運動普及：增設運動空間，落實運動產業的發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3491f592-285a-4a2a-8350-200122c98c0e","items":["監督縣府辦理原住民保留地增、劃編計畫執行進度,以落實東海岸三鄉鎮原民土地所有權之取得。","督促縣府培養原住民族教師及進用,以利原住民語言之傳承及原民語言政策之發展。","督促縣府強化消防設施,以保障人民生命及財產之安全。","督促縣府重視原住民的傳統文化、語言、技能及祭典儀式的傳承。","督促縣府強化偏鄉醫療設施及環境。","創造青年人就業機會,加強農漁產業及觀光行銷,改善族人生活,增加農漁民收入。","注重原住民部落各項軟硬體建設,農路溝渠改善、六水池、簡易自來水增設。","監督縣府縣政。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"34a04112-43bf-4ccd-8827-5db6cbcca9b5","items":["持續追蹤：路不平，找建名！持續推動新竹路平","持續追蹤：靖廬「神社大公園」神社修復及公園開闢","持續追蹤：西門國小通學步道","持續追蹤：客雅大公園","持續追蹤：活化西市仔，回復西市榮光","持續追蹤：汙水下水道用戶接管協調","持續追蹤：新竹市立幼兒園重建進度","持續追蹤：延平路、公道三、林森路、育英路道路標線改善","持續爭取：西門聯里民眾活動中心","持續爭取：「中雅安居」社宅空間回饋，設立中雅、客雅里民眾活動中心","持續推動：各里長輩共餐食堂","持續推動：公托公幼、敬老卡點數加倍","持續推動：仁德、長安、江山、世界交通動線系統改善","持續推動：搭配米粉節，推廣「南勢迷宮：米紛寮深度體驗之旅」","持續推動：推動縣市政府「市區縣有地維護、活化、處分作業協調平台」"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"350a35ef-cc79-4d50-b149-08c76f49edf2","items":["制定農產品保障價格以維護農民權益。","爭取放寬農作物天然災害補助認定標準作業，以維護農民權益。","社會福利：爭取由各鄉鎮設立公共老人日間托護、安養中心、醫療會館以照顧年長者。","社會福利：爭取設立配合縣政府的政策，長青食堂及老人供餐的設備補助。","社會福利：補足偏遠鄉鎮師資的不足，教育資源盡其所用，減輕家長的經濟負擔。","社會福利：爭取二崙國中成為完全中學，使十二年國教高中教育區域性普及化。","社會福利：加強各鄉鎮的農田道路排水改善。","社會福利：加強改善各社區發展協會活動中心修繕作業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3513dc64-d20d-4c73-8edd-0fc578695d8d","items":["建議政府推動農路修復路平專案，以利發展農村經濟。","推動貧困弱勢家庭補助政策及落實實際查訪作業。","促進社區發展公益活動，打造祥和互助的友善社區。","推動各村里社區照顧關懷據點設置。","促進地方文物特色發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"357eb181-bac6-4a20-a83e-591c7bd11d6e","items":["持續監督廍子里太和段224、225地號興建市場(核定規劃中)","持續監督北屯區兒童公園闢建地下停車場(核定規畫中)","持續監督北屯區設置寵物公園(核定規劃中)","持續監督梅川南、北路拓寬工程(核定規畫中)","持續監督大坑里光明橋及和平里光榮橋改建(已會勘)","推動全面美化人孔蓋(已提案)","推動松山街往西打通至昌平東八街(已提案)","推動北屯溪東地區新增派出所(已提案)","推動南興公園籃球場興建風雨球場(已提案)","推動制定汽柴油車占用電動充電車格處罰條例(已提案)","推動綠線捷運從延伸至大坑經補庫(多次提案)","推動敬老愛心卡搭乘台鐵區間車(多次提案)","推動重劃區普設號誌燈及監視器","推動廣設汽、機車停車格","堅持清白專職從政不包工程不收紅包不兼職不買票"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3594659e-140a-4bdd-a1c8-7f9ab2b5eeab","items":["不分黨派屬性，肯全域服務雲林縣民各項陳情案件。","不分鄉親富貧老幼，為地方拚經費建設村里鄉間基層設施。","不分縣政預算規模繁簡，勤於審查暨合理監督。","專注問政縣政府推動攸關民生、弱勢福祉、文藝、社區再造、亮點觀光等計畫的執行。","協助及支持縣政府規劃各項產業園區，及促進科技、工商業投資雲林。","敦促縣政府加速規劃雲林農特產多元通路管道，並建立農漁產品產銷儲功能設施以穩定供需。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3599043a-b3b3-44f9-a74f-79049256d713","items":["爭取屏東幼兒生育及教育補助解決少子化問題及年滿65歲者健保費由政府付擔。","推動引進榮民總醫院及屏東義大醫院入駐屏東，提升屏東醫療設備品質。","推動設置屏東市第三消防分隊在西北區，形成救災防護黃金鐵三角。","爭取屏東市長安里六塊厝設置體育運動休閒園區，提供民眾運動休憩好去處。","爭取屏東第二條快速道路及高雄捷運延伸進入屏東市，建構便利交通網。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"35c0b7d5-9925-4300-a87f-fde402e81011","items":["民主和平，維持現狀：以「中華民國台灣」團結台灣社會，以「四個堅持」維持現狀：堅持自由民主的憲政體制、堅持中華民國與中華人民共和國互不隸屬、堅持主權不容侵犯併吞，以及堅持中華民國台灣的前途必須遵循全體台灣人民的意志。","四大支柱，追求和平：提升嚇阻防衛能力、強化經濟韌性及確保供應鏈安全、與全世界民主國家建立夥伴關係，以及維持務實、一致的兩岸政策，以具體且負責任的行動向全世界展現台灣致力維持現狀、追求台海和平的決心。","人民作主，開放政府：組成公開透明的政府，讓全民都能參與並監督政府施政，積極贏得人民對政府的信任；落實民主大聯盟的精神，跨黨派、跨世代、跨領域為國舉才，用人不分黨派，持續推動國家的進步與繁榮。","均衡台灣，在地希望：深化地方自治，建立區域治理平台，均衡區域發展；建構以人為本、智慧安全的交通系統；推動地方創生，創造多元就業，吸引人才回流；完善農民福利體系，確保糧食安全，提高農民收入，促進農村再生；推動觀光立國，將台灣打造成國際旅遊品牌。","0-22，投資未來世代：推動「0-6歲國家一起養2.0」，擴大公共化及準公共化托育量能，增加補助減輕家長負擔，實施彈性的育嬰假，全面落實高中職免學費，挹注資源提升特教品質，補助私立大專院校學生3.5萬/年學雜費，公立大專院校弱勢助學最高達2萬/年，投資高教品質、教研及國際化，設立百億海外圓夢基金，擴大投資技職教育。","健康台灣，樂齡社會：推動「長照3.0」，擴大長照服務涵蓋率，增加重度失能者的住宿式服務機構量能，提升相關補助至每月最高1.5萬元，改善巴氏量表，建立多元標準，對家庭照顧者提供喘息服務，並鼓勵企業提供彈性工作安排；通過「健康憲章」，提升醫事及護理人員的待遇及勞動環境，支持三班護病比入法，設立「百億癌症新藥基金」，優化兒少醫療，擴大「年輕族群心理健康支持方案」，擴大全責照護制度，確保健保永續經營；成立「體育暨運動發展部」，預算提升至200億元，推展全民運動，完善競技選手及專業人才培育發展。","創新經濟，智慧國家：以投資人才、產業創新、科技創新、金融創新及創新創業，帶動經濟的創新驅動成長；鞏固高科技優勢，發展半導體、人工智慧、軍工、安控及通訊「五大信賴產業」，持續推動加入CPTPP、IPEF等區域經濟合作機制；促進AI產業化、產業AI化；以社會需求帶動數位轉型，強化提供數位公共福祉，推動台灣成為數位民主的新典範；鼓勵金融創新，兼顧金融監理與發展；協助中小微、服務業及傳統產業發展，實現包容成長，並化氣候挑戰為契機，追求綠色成長。","文化永續，世界台灣：提高文化預算，推動「再造歷史現場2.0」並強化文資保存；推動「重建台灣藝術史2.0」，發展藝術產業，續推16-22歲青年文化幣；成立「國家語言研究發展中心」，提出博物館政策白皮書，推動在地藝文創生，強化藝文工作者權益保障；壯大文化傳播及「台流經濟」，行銷國際，未來十年帶動至少千億投資。","淨零轉型，永續台灣：發展多元綠能，推動深度節能、科技儲能及智慧電網，確保供電穩定與電力去碳化；透過科技研發、金融支持與碳定價，推動產業的數位與綠色雙軸轉型，促進綠色製造與循環經濟；建立專業團隊提供廠商諮詢服務，並定期公布因應指引；確保不同個人、社群及地區的公正轉型。","公義社會，溫暖台灣：推動「囤房稅2.0」，至2032年累計達成興辦25萬戶社會住宅、25萬戶包租代管、50萬戶租金補貼，以協助百萬租屋家戶，並增加青年安心成家貸款額度與利息補貼；強化弱勢兒少的就學、交通、營養及健康等協助；提升高齡者生活安全及弱勢保障，發展高齡產業；促進無障礙的環境與服務，擴大補助老舊公寓增設電梯或升降機；4年完成建置100處社區心理衛生中心；擴大社會安全網，調整中低收入認定標準，協助近貧家庭；堅定打擊黑金、槍、毒與詐騙。","尊嚴勞動，友善職場：持續調高基本工資，完成《最低工資法》立法，積極協助失業勞工再就業，強化非典型勞動權益保障；支持「雙就業、雙照顧」，建立性別友善及育兒友善的職場環境，縮減女性與男性勞工薪資差距，協助媒合中高齡及高齡者勞動參與，保障新住民就業零歧視；持續挹注勞保年金，支持勞保財務穩定。","尊重多元，社會平權：強化女性決策參與，促進女性身心健康與經濟安全；深化多元全齡的性平教育，落實性平措施；推動多元性別社會平權，增進同志家庭權益保障；提出「族群主流化政策綱領」，促進族群生活圈社會經濟發展，推動多元族群的文化產業發展，構築尊重多元族群的教育環境及公共空間，迎向多元共榮的民主共同體。"],"content_split":{"method":"official_numbered_lines","version":"presidential-platform-items-v1","confidence":100,"reviewStatus":"auto_approved"}},{"claim_id":"374d5e10-4c1c-484c-92aa-754f66fff813","items":["市政發展：積極推動航空城產業專區，推動產業智慧轉型升級，提高企業競爭力。","便捷交通：加速推動桃園捷運網，開發三民路延伸至中原路、桃42號道路第三期延伸至觀音，解決青埔大竹交流道壅塞；改善道路瓶頸，廣設停車場。","衛福照顧：推動長照居家照護服務；廣設公托中心，提供平價優質托育服務；強化防疫、醫療、食品衛生，推動全民防衛災害緊急應變。","居住品質：監督體育園區、A20、A21工程開發品質；推動青年、社會住宅興建；建構老街溪綠帶延伸至青埔、新街溪兩岸綠色長廊；爭取公園綠地、里民活動中心設置；落實環保政策。","勞工保障：整合勞工就業服務資源；爭取勞工權益、輔導工會健全運作，協助身心障礙、弱勢者就業促進。","資訊網路：推動智慧城市、科技生活服務，整合機關業務網路e化服務。","教育關懷：推動優質教學，促進教師專業成長；打造雙語教學環境；關懷新住民教育；爭取兒童免費營養午餐。","治安維護：寬列警政預算，充實警勤設備，加強民防、義警、守望相助巡守隊訓練及裝備，推動導入自動化監視網路防範犯罪。","農業產銷：推動農業精緻化及增加行銷通路，輔導休閒農業、青農及農村活化再生。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"376c1259-6807-4912-9238-fe2741f19b83","items":["爭取增設南臺中原民中心","爭取提高社會住宅原住民優先分配比例","爭取市府閒置空間利用, 開放教會及族人使用","爭取提升原住民文化與AI人工智慧結合","爭取推廣原住民文化,校園增設族語老師","爭取學校與企業建教合作,增加實習就業機會","爭取整合資訊系統,提供完善資料查詢","爭取原民運動項目場所建設完善,培訓臺中體育專業選手補助","爭取成為原住民弱勢代言 ,為弱勢爭取福利"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"37791042-b8d0-4c78-8d91-5ffc0375a5b4","items":["加速建設火力全開，招商引資就業都來。","監督新市鎮開發建設，加快岡山大鵬九村社會住宅發包施作。","青年職涯探索媒合，傳產、科技、青創三贏。 「拚」宜居樂活大翻新","落實「農經濟」加值，打造「綠色經濟」，堅決反對屠宰場遷至燕巢的「血色經濟」。","加速進行義大醫院周邊重劃。","興建南岡山複合式立體停車場，改善停車問題與增加營運空間。","永安行政中心重新規劃成綜合行政中心，擴大服務效能。","梓官蚵仔寮觀光區域再升級，規劃停車空間及電纜地下化。","「拚」捷運觀光大發展：捷運紫線北延，暢通海線交通路網。","「拚」捷運觀光大發展：推動都更與都市計畫變更，結合「漁村創生」與「文化體驗」，打造觀光亮點。","「拚」捷運觀光大發展：漁塭加熱器補助，提升漁產加工商業價值。","「拚」捷運觀光大發展：漁村觀光再升級，彌陀南寮海岸光廊導入啤酒音樂大型活動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"37b078dc-8280-4754-831b-3bbfb009cd13","items":["推動台北市東側南北向捷運系統(捷運東環段)、民生汐止線加速興建。","爭取捷運信義線東延段延伸至中央研究院。","爭取社會住宅配合捷運路網持續興建，並調降社會住宅之租金。","持續推動市立聯醫系統擴大資源推動社區居家醫療。","持續爭取資源投入港湖區山邊野溪、邊坡護牆整治；規劃港湖區休閒步道，形塑好山好水的山林景緻。","持續關注大湖公園、碧湖公園及南港公園之水質優養化及外來種魚種入侵、保育本土魚種之議題。","持續監督南港、新明路及北勢湖工業區轉型為產業生活特定專用區之計畫。","持續監督北市府針對台北市所有人行道、公園及馬路上之路障移除，維護無障礙空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"37c82901-c58c-4692-beee-d541af84c98f","items":["提高長青食堂質量，推動有機蔬食。","推動年滿65歲老人減免健保費用。","鼓勵生育，增設公共托育名額與機構，並提高生育補助。","持續監督並加速興建二結至羅東鐵路高架化。","結合高鐵站公車常態化，推動五結鄉及縣內觀光產業發展。","督促縣府儘速改建蘭陽溪危老橋樑及辦理疏濬。","督促縣府早日完成宜25線（五結中路）拓寬。","加速提升都市計畫區內污水下水道接管率。","增建五股圳抽水站，解決低窪地區長年淹水問題。","加速開闢二結聯絡道高速公路以東至台二線濱海公路路段。","配合高鐵站建置，爭取連接宜蘭市環道與羅東環道，並力促於五結鄉規劃專用道路，解決平面交通瓶頸。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"381fa9ce-8a24-472c-9d81-d35a0f376096","items":["### 一、打造青年返鄉友善環境","創造青年友善創業環境，鼓勵青年返鄉！","支持青年舉辦山城音樂祭，打造青年家鄉認同感！ ### 二、老有所依，提升老人居住福利","鼓勵年輕人回鄉創業，長者有陪伴。","老人福利爭取，協助社區發展。","### 三、長期關注教育：盡力爭取先進教學設備。","### 三、長期關注教育：提升竹鹿學子競爭力。","### 四、推動在地基礎建設：持續爭取太極峽谷建設。","### 四、推動在地基礎建設：持續關注垃圾場建設案。","### 四、推動在地基礎建設：任內已爭取多項建設，如投49線、第二部救護車及人力等！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"38783821-9c4b-436a-8a6e-bcdd6469c507","items":["勢：提案婦幼教育、弱勢家庭及急難救助各項補助計畫。","設：持續爭取促進公共建設，包括推動西湖溪路堤共構第四期延伸至台13線計劃。","事：成立鄉親公益服務中心，反映民情需求及爭取地方社團經費。","益：水資源是農民的命脈，站在第一線為農民的水利資源發聲。","心：解決銀髮長照安養問題，以達到「在地老化、健康樂齡」的目的。","業：串聯在地特色景點、小吃、民宿，打造觀光行銷產業鏈。","家大院道路截灣取直改善"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"38abfc81-49bd-41f3-829f-f9b4590c4c24","items":["十八尖山森林新美學：十八尖山總體環境維護管理,並針對破損階梯及路面爭取改善經費,給市民安全舒適的登山健行環境。","監督污水及雨水下水道建設：持續監督雨水下水道建設,解決城市積水、水災問題並監督污水下水道接管率過低,效率不足問題。","客家文化發揚與保存：持續監督市府辦理客家活動的效益及客家會館空間運用效率;推動客語檢定及各項客家文化學習課程。","北新竹車站周邊環境：持續推動北新竹車站周邊環境改善,包含排水、光線、路面平整及環境治安問題。","完善市民活動中心制度：市民活動中心管理與借用機制應尊重該里里長、理事長,使其機制助於各里里民學習、交誼使用。","活化閒置空地：持續爭取活化閒置空地作為足球、槌球等各項運動訓練發展場地。避免空地環境髒亂,成為治安死角。","監督關埔空橋完工：督促市府尊重並依都市計畫蓋空橋,除提供安全的用路空間,也讓交通更順暢。","長幼福利爭取與照護：推動長者多元化的居家與在地服務模式,讓長輩樂齡學習,安心養老;推動特質教育並致力於讓孩童就近入學,提高教育預算以落實教育優化。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"38b980fa-e7c1-4727-8fbc-850014dd95f8","items":["彥毓受國家及納稅人栽培十數年,願意將學到的功夫回饋給我最初參與公共事物的起點-前鎮、小港,","人本低碳好交通:監督捷運黃線、捷運紅線南延林園,完善高雄捷運路網。推動國道七號加速定案興建,減少交通事故,提升高雄港貨運 競爭力。並推動「高雄機場周邊交通整體改善計畫」,爭取地下道及周邊道路串連國道、台88快速道路,提升國際機場交通格局及競爭力。","公園升級更友善:為毛小孩服務!設置前鎮、小港第一座寵物、親子共融公園,讓毛小孩安心、自在盡情玩耍,打造親子寵物友善城市。","運動學習更安心:為孩子的未來打拚:爭取市府加速拆除校園危樓興建校舍、老舊校舍耐震補強、添購新設備、鋪設通學步道、加裝監視 器提供師生優質且安全的教學環境。並活化前鎮、小港周邊運動場、球場等空間,爭取設備設施更新經費,提升使用人次,全民運動風潮普及。","居住正義更理想:爭取大林蒲遷村沿海六里居民最大權益!加速凝聚共識、行政效率,創造多贏。並監督小港、前鎮興建社會住宅、公共 設施升級及綠地增加,解決青年弱勢居住問題。此外,將監督前鎮河兩側199座儲油槽遷移,提昇土地利用,達成港區產業經濟轉型升級,擴 大高雄觀光遊憩發展。推動老舊市場翻新改建升級,優化軟硬體設施,友善購物環境、活絡在地消費觀光發展。","亞洲新灣區•高雄新核心:加速205兵工廠遷移後再造開發,力促2年內完成遷移釋地,引入國際級投資,推動企業總部、區域金融中心發 展,增加高雄優質就業機會,打造智慧科技新城。並加速前鎮漁港整體開發及招商,引入亮點業者進駐,爭取捷運黃線進入,打造國際及產銷 用及觀光一體魚市場,多元加值、潛力無限。國公營土地及港區土地活化加速招商開發,結合高雄展覽館、市立總圖、高雄流行音樂中心、港 埠旅運中心、駁二等地標,5G AIoT創新園區及高軟園區(一、二期),推動科技、觀光、文創、會展及遊艇產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"38c80e9f-0440-4b3c-ae01-523d433609f6","items":["持續爭取高鐵六甲站；在未設站前，往嘉義高鐵站各線公車，憑高鐵車票可享免費轉乘優待。","串連南科沿台一省道官田工業區、六甲工研院南分院、柳營科技工業區、新營工業區等科技產業廊道，互補提升及擴大區域，吸引產業進駐、增加工作機會，促進優秀青年返鄉工作。","除了已聯通的南化、曾文、烏山頭等水庫，另有各種中小型埤塘，可透過既成灌溉水系統整合各種水資源再利用，使農業用水不匱乏，無需犧牲農民。產業用水也獲得足夠備用量，全力發展在地產業，吸引各類人才。","增加老農年金至10000元。","在現行基礎上，提高各類生育補助、延長有薪育嬰假及各種相關補助。","清查閒置或低利用率之設施及公有土地（含軍方），改建修繕成社福及老人安養機構，再次活化恢復附近區域過去榮景，如白河榮家、停用軍營、兵舍、眷村等。","利用國中小學閒置教室增設幼教空間，國民義務教育向下延伸三年，幼教托育納入國教範圍。","加強農漁產業與學術結合，成立農業科技園區，釋出政府持有技術，發展高附加價值作物；針對畜牧、養殖業導進數位監控與AI管理；搭配成大水試所，結合各漁會發展高經濟水產。","強化「青農返鄉計畫」，要求農業部輔導高附加、精緻化、知識化的農業，增加農業貸款及補助，讓年輕人帶著新思維、新技術、新知識返鄉，提升本土農業競爭力，鼓勵返鄉務農。","利用交通便捷之軍方閒置營舍，廣設青年及社會住宅，實現人人住得起、買得起的居住正義。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"38dcce6d-31fd-41e8-9f14-bc6e9d873d8b","items":["教育優先 課業與才藝並重、雙語教學、AI教育落實，並支持老師專職教學與行政分工。","於東勢鄉同安昌南東側台糖地規劃冷鏈物流、農產品加工園區。","於台西舊公所改建為林國基娃娃館或多功能生活館。","繼續爭取沿子寮漁港護堤延伸，疏濬通航、再現風華。","長照醫療 推動老人福利、社區樂齡學習與共餐，完善醫療照護。","弱勢翻轉 繼續督促推廣弱勢單親、新住民、身障者第二專長培養，包含農業大學相關課程，能於沿海各鄉鎮輪流開課，就地學習、就地成長；無障礙公車、無障礙計程車、友善空間繼續加強推廣。","交通建設：麥寮台塑工業區跨隔離水道橋樑，經雲2道路接雲2-1到雲1-1線即停止，未連接到台17線將功虧一簣；需強力爭取雲1-1停止點向東再延伸約2公里銜接台17線，才能真正減緩麥寮市區上下班交通問題。","交通建設：爭取麥寮至西螺北側興建「78乙濁水溪南岸快速道路」，從六輕北堤平面道路結合現有堤岸道路拓寬整建或高架化，連通到西螺國道1號，以完善雲林縣北端交通網絡，帶動濁水溪南岸各鄉鎮區域發展。","交通建設：爭取東勢鄉從北環東路與雲158線交叉口向南新開闢扇形外環道，貫穿三塊厝西側並銜接153線，以解決東勢鄉市區南北向交通問題。","交通建設：督促160縣道拓寬工程第三段（飛沙至三條崙）、雲129文化路（林厝至崙北）路面改善工程早日完成。","交通建設：協助地方爭取於台西鄉、東勢鄉內設立運動公園及興建台西鄉立圖書館；督促改善沿海各村易淹水區，擴大滯洪池、加強抽水馬力、定期排水清淤，以減少淹水發生。","交通建設：贊成沿海四鄉合併升格為市，山海平衡、回饋共享、進步共榮。","交通建設：繼續反對各村莊一公里內設立風力發電或變電所，以捍衛沿海各鄉鎮居民健康與生計。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"39224826-4b48-4ab5-b360-a044a866e2b4","items":["提高國中小教育經費，強化中小學語言教學資源，提升英文能力。","提高幼兒教育補助金，增設幼兒遊戲場所，落實營養午餐的品質。","整合學校發展主題運動，爭取專任教練、專業設備與經費。","推動社會福利，優先照顧兒童、老人、婦女、身心障礙及弱勢族群。","加強新住民社區文化教育、子女課輔，協助新住民與社區的緊密融合。","監督縣政，爭取建設鄉鎮道路、排水及公共設施。","傾聽鄉親聲音，善盡民代職責，強化服務效能，為鄉親提供及時的服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"395120be-79c9-4413-9a7a-832e18109ed6","items":["認真問政，關心地方建設及落實地方發展；勤快服務，忠於民意、反映民情。","活化校園閒置教室及校園空間、廣設公幼、增加托幼名額，降低養育壓力。","盤點老舊校舍、推動更新維護，提供學子舒適安全學習環境。","督促政府廣設托嬰中心，減輕年輕家庭負擔。","支持社會福利住宅政策，提供弱勢族群居有其所。","建請爭取警、消員額，減輕工作負擔。","建請市府盤點老舊公寓、協助成立管委會，改善住宅環境。","積極爭取弱勢族群福利，能確實有效照顧低收入戶家庭。","健全長照2.0，提升被照顧者及照顧者生活品質。","建請盤點閒置公有空間，增設日照安養中心，減輕照顧者壓力。","監督政府加強勞基法、性別平等法之宣導及協助，保障勞工權益。","持續關注鐵路地下化進度，並監督內壢之心都市再造計畫，帶動內壢地區前後站發展並提升內壢地區生活機能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"39853686-d855-49d8-8273-f92a9f46f96a","items":["推動苗栗地區整體醫療品質提升。","推動高鐵特定區都市建設整體發展,並督促縣府以兼顧永續發展指標做規劃。","督促縣府規劃後龍設置產專園區,帶動地方經濟繁榮。","督促縣府落實長照2.0政策,完善長照機制。","監督縣府推動高齡、婦幼、兒少、身障等各項福利及設施,關懷新住民生活權益,協助弱勢及高風險家 庭,並追蹤後續安全照顧。","爭取增加公共托育設施等計畫,減輕家長負擔。","捍衛警、消、醫護、勞工族群等權益。","督促縣府發展數位治理及開發實用性APP,均衡數位落差。","督促縣府做好農、漁、牧產銷制度及提高農漁民收入。","推動永續好生活、健康好生活、快樂好生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3ae78410-1478-432f-8897-1b372b315397","items":["用心服務選民：二十年的專業問政，一輩子的用心服務。","公務警消福利：爭取發放三節慰問金，提高警消勤務加給津貼、健檢補助金額及放寬補助年齡。","友善幼托環境：擴大育兒津貼，推動托育公共及準公共化，力求幼教資源均衡分配。","鼓勵青年留鄉：地方產業創意產品人才培育，獎勵年輕人留鄉創業，一起為澎湖打拚。","幸福高齡社區：持續推動長者共餐及在地安養，營塑溫暖幸福快樂銀髮族社區。","推動旅遊市場：設立市區觀光市場，推動文創農漁市集，打造澎南線等旅遊動線特色品牌。","新住民文化融合：運用閒置空間，成立新住民交流學習中心，促進社會多元文化融合發展。","活化市區土地：力促澎防部及後指部外遷，串連市區觀光漫遊動線，打造澎湖旅遊新亮點。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3af94d8f-2106-4128-8387-2c3f476a0e6d","items":["設置原住民托嬰中心免費","租屋補助提高到1萬元","區主席及頭目津貼提高至最低薪資","建購修繕補助門檻要降低以嘉惠更多族人","市府工程就業保障並提高原住民任用員額創造族人就業機會","保障原住民單親扶養家庭者工作優先權","結合工商企業者對原住民團體提供廣泛的贊助","企業任用原住民及弱勢者提高獎勵金額","於桃園中正國際機場及桃捷各站設立原住民手工藝服飾音樂及美食展售店","增設原住民射箭練習場","爭取原住民各區設置原住民集會所","簡化政府相關補助經費核銷流程","都會區原住民老人安養中心設置","爭取原住民族人安祥歸根車馬費"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3b15939e-bca3-426d-ba9b-d571948d5f29","items":["廣設育兒設施、成立兒童醫院、增設老人長照機構。","加速整頓虎頭山交通、闢建停車場、公車增班。","加速都更、成立主動專責整合老屋重建的輔導機制。","各公園廣設兒童遊樂器材及老人健身休閒設施。","加強消防公安檢查、確保市民居住安全。","捍衛勞工權益、加強勞動檢查、協助解決勞資爭議。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3b373c1a-189a-4976-8def-bcb407dbd904","items":["爭取打造水岸公園城市，改善城市景觀。","爭取延續捷運到中清路大雅公園，民生路至豐原經神岡。","爭取增設工業區用地，並加速豐洲二期及擴大神岡都市計畫產業園區推動。","爭取大雅第一市場設施環境及設備改善。","爭取調降房屋稅、地價稅。","爭取重新調整都市計畫公設用地比例","爭取大雅區六寶及忠義里、神岡區山坡地地目解編。","爭取改善教學環境及設備，提升教育品質。","爭取公托數量及教學品質提升，監督非營利幼兒園教學成效。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3bc391dc-66ac-49a6-8f73-45c8dfcb9821","items":["嚴格監督縣府 , 落實施政目標。","秉持專業問政 , 爭取農民權益。","關懷弱勢族群 , 強化社會福利。","照顧老弱婦孺 , 打造安康家園。","整合縱谷區及溫泉風景特定區暨休閒農業等觀光特色 , 爭取土地重劃編定建設大卑南。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3bc41a96-cab7-47b0-aece-4423b52dc7fa","items":["督促台九線公路拓并工程,保障民眾權益,持續爭取花東快速道路,縮短農特產品運輸時程。","爭取充實學校設備及建構校園安全網絡,提升多元學洗成效,減少城鄉差距。 同","加強監督縱谷四鄉鎮,基礎建設維護與修繕,路平、燈亮、水溝通,提供民眾舒適安全的生活環境。","因應氣候變遷,水源議題,關係著農業穩定發展及農民收益,加強推動攻水、取水等灌流設施改善與建置,提 高農業水資源最佳利用效率。 一","Deen Ei *協助縣府推動智慧農業,將生產、行銷與消費納入系統建立,推動倉儲冷鏈設備及災損預防 SI)。","因應南橫公路通車,觀光人淹激增,迷促縣府提升統谷觀光產業發展,並爭取易肇事路口,加裝智慧交通號誌 (例如1oT來車警示系統'“'等,提醒用路人交通安全)","提升縱谷地區醫療照護及專科門診需求,爭取新建鹿野、關山衛生所,以因應嚴峻疫情及民眾就醫品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3c213eab-dac5-42a8-aae1-b7051d239af1","items":["強力監督縣府合理分配資源，強化南區建設促進觀光產業鏈經濟。","督促縣政加速健全鄉鎮社福網絡，拉近城鄉差距，打造優質友善環境。","促進地方整體規劃，以文化為創意行動平台協助地方改造活化閒置空間及地盡其利的舒適環境。","培訓青年力新思維，吸收專業人才創造城市蛻變，促進地方多元面向發展就業商機。","充實學校教育資源，提升偏遠校區數位學習能力強化學生競爭力。","尊重軍、公、教、警、消專業強力捍衛其權益及尊嚴，督促治安及救災相關單位救災設備及人員訓 練，建立完整防災體系，保障人民生命財產安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3c333394-fea9-498a-8e02-c56f1f7af784","items":["敦促縣府對社會福利,落實老人長青照護,獨居老人、婦幼、新住民、身心障礙、弱勢家庭,生活有所依。","敦促補足警消人力,社區巡守隊,義警消裝備經費補助,推廣智能e化監視器。","關懷原墾農民,依法爭取土地所有權,保障原墾農民生存權與工作權。","積極爭取,縣內國中、國小建設經費,充實學校軟硬體設備,提升教學環境及學習競爭力,給在地子弟受教更好環境。","爭取青少年戶外體適能活動場地,補助設施及經費。","推動文化升級,爭取傳承與創新客家文化藝術,落實客家文化藝術多樣性。","超越黨派,積極爭取地方建設,勤跑基層,傾聽民意,秉持為民服務為天職信念,全職全時服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3c3b43bb-5c25-4555-bf76-985c3fa0e672","items":["爭取年滿65歲長者，四節福利金2,500元，每年可領10,000元。","廣設托嬰、非營利幼兒園、老人日間照顧中心，造福幼童及長輩。","爭取設立平鎮區機車考照練習場。","爭取設立多功能游泳池，提供全家大小遊憩。","爭取平鎮區規劃老街或市集，推廣平鎮文化及美食。","加強各大路口監視系統及交通號誌更新，提升市民治安與交通順暢及安全。","改善平鎮區危險道路路口及拓寬（如正義路口、新光路四段至五段、營德路經寶馨公司至快速道路等）。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3c3b7697-1673-49e8-873a-f1db58cb8536","items":["督促市府加強蓋社會住宅。","督促市府多蓋運動場所(籃球場、羽球場、網球場、直排輪等)。","爭取各大小公園廣設成人健身器材、兒童遊樂設施。","督促市府落實老人長照及幼兒托育政策，提高生育津貼。","爭取敬老愛心卡能連結各種交通工具(台鐵、高鐵...等)。","針對高速公路或平面道路易塞車路段，督促市府積極爭取中央協助解決。","重視學童營養午餐品質，加強幼童照顧措施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3cfc1352-59a5-48e1-bfaa-10083791ffd9","items":["守諾─認真踏實勤走基層,堅守承諾、延續服務,落實品質。","警消─關心警察及消防人員執勤的安全與勤務制度,是否超出負擔,爭取應有的福利。","基層—勞工的生活及工作的關懷,督促縣府相關單位,落實勞工政策。","監督─服務不分黨派、監督縣府施政及預算,加速地方建設。","發聲─反應基層民情,協助弱勢族群,資源合理分配。","前瞻─衝觀光,結合產業觀光資源,拚農業,推動精緻農業發展。","教育─提升教育環境,縮短城鄉差距。","防護─加強治安及改善交通,保障縣民生活品質。","環保─消除公害污染,維護居住生活環境。","扶弱—加強關切扶助弱勢團體,照顧中、低收家庭生活。","活化—爭取政府機關的閒置空間活化,讓市民的生活品質再升級。","環保—污水整合接管整理,提升兩側住戶生活品質及經濟發展。","觀光—推廣自然步道,導覽及植物解說,整修損壞設備,提供健康自然的休閒管道。","社福—關懷婦幼、老人等社會福利議題,推動社會服務。","托育—公、民共辦托育,平價優質,讓年輕人敢婚敢生。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3d14d54d-2645-457e-9fb4-7c00dbc3d317","items":["強力監督重大工程品質 精準把關市府預算，有陳慶齡在！","促進海山漁港活化，帶動漁港整體經濟與觀光效應","爭取老人福利加碼，敬老卡點數加倍及使用範圍擴大","青青草原再進化，打造新竹後十八尖山遊憩觀光區","疫情期間，加強香山社區鄰里消毒，提升安全居住環境","傳統產業統整及升級，成立香山精密機械園區","設立香山攤販零售據點，規畫屬於香山的菜市場","照顧社區據點及關懷站，豐富課程及加強守望"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"3d44785c-023e-41bd-ada0-e15aad4edf92","items":["爭取全民運動館、風雨球場","提高每月育嬰補助","爭取1村里1公園及親子公園","推廣深度旅遊打造南投文化品牌","建立農業特色品牌及電子銷售平台","爭取青年住宅，協助青年返鄉","活化橋下及會展中心閒置土地"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3d675826-567c-4100-bcc7-6d263f41ff43","items":["爭取興建南竿鄉介壽-梅石-仁愛濱海自行車步道，開發縣民休閒新景點。","督促新任縣長建議中央辦理離島特考，維持本縣各機關用人安定，增加本縣子弟擔任公職機會。","督促都市計劃通盤檢討，讓土地發揮最大價值，以平民怨。","與新任縣長共同向交通部、NCC爭取加速興建第四條台馬海纜，建立本縣安全及高速的網路環境。","督促縣府開通南竿-高雄航線，服膺民意需求。","要求馬酒公司規劃觀光工廠目標，提升馬酒企業形象，廣開財源謀求縣民福祉。","要求縣府制定真正有利於身心障礙者的工作機會及友善環境空間。","監督縣民樂活多功能體育館暨社福中心工程進度，充實體育休閒硬體設施，推廣全民運動及兒少福利。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3dc80306-500f-4640-8824-46fed3755883","items":["爭取提升原住民社會住宅比例","增加公托原住民族生錄取名額","協助輔導成立原住民課後輔導班","利用E化教學,落實原住民學生學習族語之權益","增加羅浮完全中學科系多樣化及發展原住民族教育特色","推廣原住民傳統文化活動及技藝,常辦理相關技藝課程及建立原民技藝交流平台","結合各族群成立原住民青年諮詢委員會,並定時舉辦青年論壇及交流活動","增加原住民多元職業訓練專班及證照班","爭取自來水管線延伸至羅浮、義盛、霞雲","推動原鄉醫療,爭取成立醫療中心及洗腎中心","協助族人處理電信通訊問題","市管道路及增加觀光亮點,美化部落","市管風景區及羅浮溫泉攤販租金優惠及長期輔導"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3e5418ee-2af5-4f6f-b9ae-3c3bb6123313","items":["強化偏鄉醫療、社區長照與托育資源。","增加竹南地區運動與休閒空間。","改善道路、騎樓與公共運輸，打造友善通行空間。","推動多元平權與公民參與。","推動議會資訊公開透明。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3ea178c0-ee75-45e2-a6e8-8bc14be5d3c8","items":["爭取及捍衛基層醫護權益。","完善育兒政策，減輕家長負擔。","推動社會住宅，保障居住正義。","持續爭取65歲以上全口假牙補助。","關懷老弱婦孺，落實各項社會福利政策。","督促市政府成立「毛孩專責委員會」，落實及關懷各項動保福利政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3edbddae-c9f2-4c6a-824c-1dff3732ead4","items":["秉持熟悉行政法令及運作的特質，及時提供民眾最佳的全方位服務。","持續爭取地方所需的軟、硬體建設，造福地方。","協助弱勢團體爭取應有權益，增進社會安祥樂利。","有效監督縣政，協助縣務推動，造福民眾。","持續督促冬山河親水公園溫泉開發。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"3f6d392c-7fff-4ac8-ac78-edddb78423b0","items":["長照 - 爭取設置複合園區。","公園 - 推動親子公園。","寵物友善政策 - 建置基隆第一家寵物公園。","監督市區道路平整，維護市民通行安全。","清寒家庭、身障人士、獨居長者及弱勢族群爭取社會福利。","推動市政建設，督促市府提昇行政效率。","國光客運 1813 線，延伸行駛「深澳坑 - 東光路 - 東信路」之台北城際快捷公車。","市府研議「基隆─台北」之台鐵軌道，採行「班次密集 ( 直鐵）捷運化」，方便市民就業就學通勤所需。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3f761d22-15bc-4091-9f59-51618167cd27","items":["保護金融，防詐護財：持續健全金融服務、打擊詐騙、監督租賃及融資公司金融風險、保障民眾權益及財產。","保護弱勢，擴大守護：放寬救助條件，提升補助，落實關懷機制，擴大社會安全網。","保護主權，安全永續：維護台灣和平穩定、提升防衛力量、強化經濟安全，確保民主永續。","利民生養，快樂育兒：提高育兒補助，優化育兒制度及產業，提升育兒人員待遇，早產兒養育照護，爭取凍卵補助，提高不孕症協助，減輕生兒、育兒壓力。","利民居住，安心成家：提高青年房貸及租金補貼，推動興建社會住宅，減輕居住壓力。","利民照護，守護銀髮：長照制度再優化，提高照護補助、擴大服務範圍、增加照護彈性、強化服務品質、串聯長照資源，守護不中斷，減輕照護家庭壓力。","利民生活，降低負擔：推動減稅利民，降低工作者的負擔，續行改善水電等民生基礎設施。","升級交通，好行好停：成功爭取並加速五股交流道完工、台65新設新莊南出匝道、捷運環狀線二期、捷運萬大樹林線二期完工、爭取泰板輕軌、西盛支線落實、持續優化交通瓶頸、改善行人通行環境，解決停車問題。","升級文教，多元發展：促進在地與多元文化發展，爭取國家電影文化中心二期儘早落成；爭取減輕、平衡受教育成本，提高補貼人才培育，持續改善新莊學校設施設備。","升級經濟，扶持創新：督促解決產業面臨的困境、加強扶持新興產業發展，監督國內外經濟風險，強化輔導青年創業，改善勞動權益。","升級健康，完善醫護：成功爭取並加速台北醫院新大樓完工，促進醫療產業發展及相關醫護人員待遇改善，強化兒少守護及心理輔導，提高對孕幼、長者的健康照護。","升級環境，友善樂活：續行改善新莊居住環境，持續優化水環境，解決廢水排放問題，推動電纜地下化，解放居住環境天際線，爭取增加綠地及休憩空間。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"3f892f33-bc4d-46b4-b1a1-1cb08c1c121d","items":["從當選立委開始具體兌現「幸福168」的政見，遷移看守所、土城變電所室內化、金城交流道動工、闢建司法園區、爭取捷運三鶯線、萬大線、三峽全面飲用翡翠水、過去的政見逐步都實現，未來土城更好、三峽更好，再許一個AI發展的好未來，留用人才在地方。我將一生懸命為土城、三峽的發展而努力，過去一起和大家努力的成績單如實呈現。","變電所室內化完工：爭取27億，化身為綠色廊道。 金城交流道動工：爭取56億，監督工程如期如質於116年完工。 爭取台65延伸：土城三峽列為優先段已定案。並將先行辦理綜合規劃及環評作業。 全面飲用翡翠水：爭取三峽供水戶數達四萬五千戶，生活品質再提升。 危橋改建：長福橋重建總工程費9.19億，預計114年8月完工，三鶯大橋改建完成，總經費23億，已全線雙向通車。 遷移土城看守所定案：爭取171億，現正辦理招標。園區中建設7.8公頃森林親子主題公園，媲美大安森林公園。 司法園區已動工 捷運交通網：三鶯線爭取502億經費並規劃軌道全罩式隔音，預計114年完工。萬大線總經費555億，積極爭取總經費增加200億。 三峽河整治：爭取經費達1億5千萬，配合周邊步道改建，打造運動休憩好場所。 爭取教育資源不間斷：班班有冷氣，爭取26所國中小校舍修繕超過2.2億（補助修繕校舍、PU跑道、廁所整建等）。","推動AI科技廊道！ 極力推動土城、三峽AI科技園區，結合捷運、快速道路及高速公路整體路網，串聯各科學園區，並透過立法院與行政院來共同推動，培養國家下一個兆元產業，帶動地方發展與就業，讓在地青年有未來。","推動親子守護大聯盟！ ①到6歲國家養2.0，青年學生國家挺！ 爭取親子陪伴票，在地推動年年有紙風車，兒童星光電影院，支持凍卵補助、產婦心諮，改善產育環境。","全面電線電纜地下化！ 推動台電電纜、電箱地下化，保護市民行走空間，恢復清潔的天空。","積極推動地方建設！ 推動樹林雙向交流道，解決北大塞車困境，爭取長福立體停車場改善三峽停車問題。續推學校地下停車場，改善都市停車問題，推動公館溝改善計畫，打造兩岸櫻花親水廊道。闢建零碳公園，創造減碳綠化生活。","打造三峽文化之都推動三峽觀光！ 爭取觀光署資助，推動三峽好行旅遊巴士。重新規劃整合連結，打造觀光熱點。","推動長照3.0 爭取老人全面照護 爭取土城、三峽捷運站站有社宅、解決青年居住問題！ 興建中1294戶、已決標423戶、規劃中782戶。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"3f8d8c02-e5b6-4be5-b696-f4580889dc06","items":["支持縣政發展，監督縣府各項預算。","努力協助湖口鄉政發展。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4005dcb3-afaf-4442-a6a2-1025e937869b","items":["為鄉親爭取福利，好央甲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"40199564-034a-4193-a175-7e5cf5d801b4","items":["主張安全與環境最少破壞下興建外環道改善關西交通問題。","督促縣府加強查緝防止環境污染事件發生。","爭取關西地區急重症醫療機構。","推銷關西休閒觀光、傳承客家多元文化。","打造創生機會、鼓勵青年返鄉創業。","加強高齡化照顧及社區關懷據點服務。","爭取社會福利提高育兒津貼及學齡前教育補助。","爭取監視系統建置釐清交通事故責任、打擊不法。","提倡社區營造及農村再生，打造關西為宜居鄉鎮。","建立與縣府良好溝通機制，監督把關縣府各項施政。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"40367687-3c3a-4597-9b8e-28cebe100fbb","items":["行車安全的里程碑：建立台灣車輛撞擊測試制度（TNCAP），提供消費者公開完整車輛安全資訊，讓消費者有更多安全的車輛可選擇，降低道路意外事故傷亡率。","強化「銀新未來城」公益性：要求擴大日照中心服務量能與納入市價租金打八折的友善銀髮宅規劃。","督促地方建設如期如質施工：中央全額負擔工程款33.36億五股交流道改善工程動工；中央核定補助2.67億的汙水下水道倒閉工程也決標復工；爭取中央全額負擔五股疏左堤防增高工程共15.24億元，守護五股居民生命財產安全；爭取中央建設五股水環境治理及親水空間營造，109年起投資五股地區約25億元！","改善觀音山硬漢嶺通訊品質：成功協調中華電信完成基地台架設，緊急救援無阻礙，第二階段持續與其他電信業者溝通協調。","爭取空大校園社區化：空中大學分兩階段拆除保和街與中正路圍牆，形成友善人行步道空間。","升級、翻新學校建設：國中、小學班班有冷氣，設施設備、跑道、操場、老舊廁所全面更新，爭取經費超過億元，讓學生開心，家長放心。","歡迎加入淑芬 Line：@linshufen"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"407e7f09-a6da-4ff0-9f15-fbd7e6814340","items":["居住正義：嚴格監督市府賤賣市有土地","居住正義：聯開案住宅歸還市府優惠出租","居住正義：推動合法健全有效率都更","交通安全：統整改善交通號誌、指標","交通安全：要求台電水電信等相關單位施工時皆需整條馬路庖舖整平","城市美學：電線桿纜線、電纜、違法之線路皆應拆除","城市美學：電線桿、電力(信)設備地下化","友善育兒：推動社區共照喘息育兒空間","友善育兒：增設公幼公托臨時及夜間托育","友善育兒：加開2歲幼兒收托班級數","藝文三蘆：增設三蘆國中小藝文班","藝文三蘆：定期舉辦藝文活動陶冶身心","藝文三蘆：妥善規劃三蘆社區公園為藝文展演平台","活力再現：65歲以上免費裝假牙","活力再現：增設公共托老長照中心","活力再現：推動社區青銀互助共餐"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"408da69e-9e37-42e3-892c-ec5498c1517c","items":["爭取風雨球場建設；讓運動民眾更便利提昇運動人口","推動寵物友善空間","公園景點增設洗手台及廁所","協助爭取自來水資源普及化","新住民友善就業環境：閒置校園空間轉型活化為銀髮日照中心","新住民友善就業環境：推動新埔產業打造特色鄉鎮"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"410ef66a-4b94-4496-85df-4a3b0e52410f","items":["支持18歲公民權修憲案","爭取提高生育補助及育兒津貼","爭取65歲以上長者免繳健保費","補足警消人員編制，強化社區安全網絡","捍衛年青人權益，促設市府青年局","加速推動永康全民運動中心","加速推動永康鐵路地下化、以利改善交通","加速推動永康區社會住宅進度、落實居住正義","捍衛勞工權益，落實弱勢族群保障","優化地方產業，增加在地就業機會"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"41236b3c-8036-4e4e-909e-c266122f8a25","items":["社頭、田中、二水有山有水有人情味。 但這裡少了年輕人的聲音！少了年輕人共同參政。 妤亘願意為鄉親請願與發聲，貢獻年輕的熱情與創意。 監督政府，建議政府，全心照顧這片土地。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan","candidate_introduction"]}}},{"claim_id":"415a82ff-0c89-4299-a3fa-53047e9eb61f","items":["敦促市府改善產業結構,建構具循環經濟思維的生態產業鏈。","救空汙!儘力推動高雄及早達成無煤家園。","鼓勵市府推動全市企業 ESG,落實提升環境、社會與治理的企業社會責任。","全面推展“科丁”教育:已開辦 867 班、培育超過 3.7 萬位科丁學童、十種學程,目標人數再成長 100%並列入小學課程。","打造高雄“志工”社會:已培育 1.2 萬名合格志工,目標培訓人數再增 50%。","開辦“心智圖”課程:已有 2.1 萬名學童上課,目標人數再成長 50%。","籌辦“跳跳屋”: 完全免費「何爺爺跳跳屋-高雄幸福水樂園」活動,共辦理 8 場次、3 萬人進園同樂,持續辦理中。","推動“微型保險”: 整合公部門與民間資源,推動並擴大免費納保的弱勢族群項目與人數,目前已達 5.5 萬人納保,目標含低收入戶、中低收入戶、身心障礙輕度和中度有補助者、弱勢單親家庭等全市符合納保對象約 12.6 萬人集體納保,將推動自治條例法制化。","廣徵民意:已舉辦 202 場“公聽會”,廣泛邀請產官學民間人士共同探討市政議題,持續辦理中。","監督財政紀律:8 年來為高雄減債 432 億元減赤,提升政府效能,改善高雄財政困境。","加強土地活化:推動「公共設施保留地解編」還地於民,舒緩近千億市庫負擔,持續督促市府解編進度。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"41882c86-bcd2-44d3-9da4-6825ca77b69f","items":["督促與加強大都會公園(二重疏洪道)防洪防災、生態保育、休閒育樂等項目。","爭取體育會經費推動全民運動、單項競技與推廣樂活休閒。","延長青年就業獎勵、產業紓困、振興措施至疫情後。","落實社區守望相助治安聯網，爭取防災、減災、避難計畫經費。","推廣觀光夜市、敬老親子、宗教文化與捐血公益活動。","活化閒置公共空間，佈建公幼收托及長者照護能量。","提出「重力排水」專案解決三重、蘆洲易淹水狀況。","更新公園老舊遊具及體健設施，打造安全共融式遊憩空間。","堅持土地正義，提高容積比例，繼續爭取蘆南蘆北完善重劃。","全面檢討蘆洲老舊社區都更危老改建，提升容積率。","督促防洪治水，疏濬淡水河，還三蘆市民河岸城市。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"41e34289-5faf-4e5d-9cdc-ffeba2e6ade0","items":["積極爭取各項建設經費及落實城鄉平衡發展。","配合縣府農業政策推動，建構產銷機制，保障農民利益。","敦促縣府爭取經費來為新住民婦女及弱勢團體的生活，並舉辦輔導就業及技能訓練。","提案爭取社區預算，辦理老年人活動與學習課程，提升照顧樂齡族鄉親。","敦請政府重視山區林班地承租人權利，尋求合法、合理之政策，得使百姓安心永續經營，安居樂業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4230ee7c-bf4b-4d8a-b462-eb9c4d589baf","items":["縮短城鄉醫療衛生差距，提升偏鄉地區就醫品質。","促請政府重視全民運動，加快增設各項體育設施。","督促政府開發觀光亮點，結合社群行銷發展觀光。","推動建立智慧預警系統，有效因應極端氣候傷害。","落實推動長者福利措施，保障弱勢團體基本權益。","協助地方產業創新發展，提升在地人口就業機會。","深耕節能減碳環保教育，攜手維護環境永續發展。","監督改善香榭大道缺失，重新省思花蓮城市品牌。","協助新住民適應新環境，打造職場生活友善空間。","因應少子化高齡化危機，推動長照婦幼福利政策。","推動設置智慧交通號誌，提升行車效率減少意外。","爭取預算改善警消裝備，保障警消同仁值勤安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"425ad7ea-a75c-4f1c-8260-650e491ec21e","items":["家庭,我來顧：幼兒照護加倍，更敢生","家庭,我來顧：敬老卡再升級，更方便","家庭,我來顧：社會住宅興建，更好住","家庭,我來顧：跟愛長髖服務，更安心","交通，我暢通：先便利，台61快速高架化","交通，我暢通：先銜接，武陵高架橋打通","交通，我暢通：先多元，共享運具更便利","交通，我暢通：先興建，殯所第二停車場","建設,我要做：加速！汙水管線建置","建設,我要做：推動！果菜市場遷建","建設,我要做：爭取！新竹監獄遷建","建設,我要做：增建！公團友善廁所","在地,我最懂：加速第五公墓改建公園","在地,我最懂：光華街(公21)公園興建","在地,我最懂：里活動中心歸還於人民","在地,我最懂：興建各項運動休閒場地","產業,我力挺：青年創業，補助升級","產業,我力挺：活化商圈，舊城再生","產業,我力挺：在地藝文，支持推廣"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"42ba0525-3af7-48f5-9f35-a7c14e697d7f","items":["加速老舊社區都市更新，讓您過得更好。","強化弱勢族群照護及福利，加強銀髮族安養扶助，落實敬老社會政策；","建立公平、和諧、福利社會。","保障婦女權益，貫徹兩性平等。","推動無障礙空間環境，爭取身心障礙者工作權力。","強化社區治安聯防與社區整體營造加速傳統市場更新，鄰里公園改造，","都市機能再升級配合都市更新設計發展主題商圈。","促進觀光夜市國際化。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"42cd94cb-b07e-4e8d-9beb-21c0c643fdad","items":["壹、四大縣政監督：交通（人本好行）：人行道規劃、定樁式共享單車、公車捷運化。","壹、四大縣政監督：建設（民生優先）：東港路變電所室內化、南北館市場活化、鼓勵開闢停車場。","壹、四大縣政監督：文化（舊城新貌）：維管束計畫2.0、綠水岸生活廊道、南機場文化園區。","壹、四大縣政監督：社福（全齡照顧）：鼓勵準公共幼兒園、保母托育補助、長青食堂加菜金。","貳、配合黨團二大共同政見：反對家族干政，廉能宜蘭縣政。","貳、配合黨團二大共同政見：支持公民權下修18歲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"42cff4e8-9670-4a98-b74d-30c15ca3614d","items":["幸福教育：推動三蘆新增9所公托，持續爭取加倍增設公幼2歲專班","幸福教育：推動公校校校有課後輔導","幸福教育：積極增加準公共化幼兒園、三蘆公幼増26班","幸福教育：成立課後社團老師查詢系統","幸福教育：全面提升校園視聽、操場、冷氣設備","幸福教育：建置數位教室、優化改善校園遊具","幸福長輩及婦幼：加速碧華國中原址改善長照銀新未來城","幸福長輩及婦幼：推動三重聯醫第二醫療大樓","幸福長輩及婦幼：加速蘆洲醫院設立進度","幸福長輩及婦幼：爭取新北設立兒童醫院","幸福長輩及婦幼：爭取推動三蘆弱勢長輩送餐之中央廚房","幸福長輩及婦幼：增加受暴婦女庇護所容量，提升中繼所品質","幸福長輩及婦幼：強化跟蹤騷擾法執法落實","幸福長輩及婦幼：催生新北玩具租借網","幸福長輩及婦幼：加強未婚懷孕關心，提升產後憂鬱協助","幸福長輩及婦幼：推動到宅做月子服務","幸福青年：社會住宅再加倍，依收入提供租屋補貼","幸福青年：強化役前職業訓練","幸福青年：降低工時，落實加班給付","幸福青年：優化交通減少交通時間","幸福生活：爭取熊猴森、大智、大同、永福特色遊具及籃球場，持續推動共融遊具","幸福生活：爭取三蘆公園6座停車場，持續爭取","幸福生活：推動騎樓整平及人行道改善","幸福生活：加速設置智慧公車站牌，提升公廁水準"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"430555e3-f30a-4ac8-b25a-4a912897063d","items":["為地方爭取建設、為百姓謀福利，為民喉舌！","督促六甲外環道二、三、四期後續工程進度，極力爭取六甲的生命紀念館。","台灣首府大學退場後，督促市府全力推動麻豆全民運動館的設置。","爭取六甲、官田、麻豆、下營區重劃區內農水路改善工程。","督促官田區南 120 道路拓寬工程盡速完工；極力爭取二鎮環保運動公園內設置風雨球場。","下營區的抽水站必需重新、徹底評估設計、改善未解決淹水的損失與痛苦。","督促市府盡速改善麻豆、大內、下營、官田等易淹水區，免除民眾長久飽受淹水之苦。","爭取石仔瀨抽水站加裝 3CM 機組以防風災淹水；大內區石仔瀨天后宮至大內分駐所段道路拓寬工程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4347b6b7-abdf-494f-a141-a768f37bf5e7","items":["參選是為了服務更多鄉親,我來自基層,了解民眾所需,為民喉舌,縮短民眾與政府之間的距離,扮演鄉親與政府部門溝通之橋樑,扮演好人民公僕的角色,服務鄉親。","擔任民意代表從基層做起,一步一腳印,瞭解民眾所需,體認民眾所苦,點滴皆存於心。『苦民所苦,憂民所憂』,現下失業率偏高,如何讓勞工權益獲得更好的保障?婦幼、身障等弱勢團體等的社福利政策制定與落實,居住環境治安的改善,監督政府部門,期能更有效率的解決民眾問題,讓鄉親皆能擁有更好的生活品質。","碧玉的努力─看緊公帑杜絕浪費。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"43d783e3-4448-47b5-9845-e092ca5cb15e","items":["爭取65歲以上長者免繳健保費。","曾文區產業文化，及觀光路線應連成一線，如麻豆文旦，六甲台灣鯛、米食、火鶴，官田菱角 ，下營鵝肉、黑豆，大內木瓜，規劃擴大辦理並執行臺南觀光二天一夜計劃，創造新的就業機會。","爭取設置臺南市「農業創業基金」因臺南多屬小面積耕作性質，故應提供無息創業貸款，協助中壯青年回鄉加入農業大軍打造城鄉共榮。","爭取建設曾文區全民運動中心。","爭取早期農地重劃農水路更新工程。","爭取國中、小學生營養午餐免費。","爭取六甲區西側外環道路工程(北段銜接市道165線)。","爭取曾文區設置公、私立托育資源中心。","爭取曾文區都市計畫10公尺以下計劃道路開闢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"43e6e132-a32f-490c-b856-5cb3ca1e8dc3","items":["協助青創育成，衣級棒：盡速增闢板橋區青創基地、規劃合理、便宜的創業據點，協助青創進駐共享辦公室。","協助青創育成，衣級棒：每年輔導100組專案新創團體、組織，強化新創動能。","協助青創育成，衣級棒：敦促青年局整合完整的諮詢服務、統整資源、空間、資金補助方案。","協助青創育成，衣級棒：協助在地地方創生團體及社企，引入公私資源，用創新方法解決社會、環境問題。","建立青銀共好，衣級棒：敦促增加公托、公幼比例及普及率、降低公辦、委外課後安親服務收費、弱勢家庭學童免費。","建立青銀共好，衣級棒：增設老幼特色公園、善用中、小型閒置空間打造樂齡據點。","建立青銀共好，衣級棒：督促落實建構社區、優質、平價的長照服務、讓市民長者、失能者就近照顧、在地照顧。","打造寵物友善，衣級棒：積極打造「寵物友善公園」據點、既有公園設立寵物友善專區。","打造寵物友善，衣級棒：推廣寵物保險，爭取適當補助；公共運輸落實寵物友善精神。","打造寵物友善，衣級棒：健全動保相關法令，推生動物福利，並加強孩童對寵物的生命教育。","推動人本交通，衣級棒：打造板橋智慧交通系統、提升電動公車營運及候車亭標示。","推動人本交通，衣級棒：部分路段拓寬人行道，增加行人庇護島、強化交通視覺引導動向。","推動人本交通，衣級棒：全面檢討板橋區待轉區、禁行機車路段的設置與改善。","推動人本交通，衣級棒：逐步落實車速分流、車向分道，取代車種分流思維。","促進板橋新生，衣級棒：推動電線電纜地下化。","促進板橋新生，衣級棒：要求盤整公共垃圾桶並改善家戶垃圾清運。","促進板橋新生，衣級棒：督促提升板橋區市場攤商和購物者便利及舒適度。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"443438fc-b838-4287-826a-825386d3ef31","items":["經濟要更好 提案加速輔導在地產業升級，照顧在地農漁工商產業，協助縣內工業區與地方商圈良善發展，堅決捍衛勞工權益。","生活要更好 提升縣內民生基礎建設，打造安居樂業且富有雲林文化的生活環境。","青年要更好 爭取雲林青年在地租屋、就業、生育、創業獎勵補助，增加青壯年休閒娛樂運動場所，促進雲林青年根留雲林、回來雲林。","社福要更好 加強雲林弱勢照護網，獨居長輩、傷殘病友、單親幼童、失業民眾、新住民媽媽、人人急難救助；提案普查追蹤，降低認定門檻，增加補助配套。","警消醫護要更好 加強警消醫護工作安全裝備與職安訓練，爭取「感謝有您」旅遊津貼，提高雲林警消醫護福利與量能，強化雲林縣民日常生活安全後盾。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"448c2e31-165b-443b-9e7a-d583c8669a12","items":["成功之路或許很艱辛,但我喜歡挑戰,我並不畏懼。沒有什麼能阻止我為家鄉全力以赴的決心。無黨派的我,無色 無畏!"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"44f7cd4c-300f-4e0a-8fae-c45a52c97007","items":["老人小孩國家養,擴大生育補助,廣建托嬰中心、平價幼兒園,關懷橘世代、銀髮世代,落實長照及關懷據點,推動全齡","推動正派政治,打造公義高雄,監督政府謹守行政倫理、程序正義、財政紀律。","督促捷運黃線以TOD導向模式開發鳳山,提升土地使用強度、高效能聯合開發,安全施工,優質完工。","中崙引進新產業園區,以國土計畫、都市更新提高土地利用及公共設施配置效益,永續都市發展。","推廣智慧交通,路口號誌智慧調整車流時間,增加路邊戶外停車供給量及智慧資訊,加強鳳山交通流暢度。","落實鳳山中城計劃,優質開發重劃區、購物中心、藝文特區、藝術村,優化聯外交通系統,活化地方經濟。","終結鳳山水患,鳳山溪整治分洪導流,污水、雨水下水道定期清疏。","深化客家語言傳承,獎勵客語認證,辦理客家族群節慶活動,扶植客家音樂、文化人才,鼓勵客語歌曲創作。","打造流行音樂產業鏈,運用豐富多元的音樂、表演、藝術展演設施,扶植在地音樂演唱、創作人才,發展音樂相關產業。","推動運動康健城市,鼓勵騎乘自行車,推廣滑板、霹靂舞、運動攀岩等奧運新增運動,擴大運動中心使用效益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"457eb47c-6faa-4deb-bb3d-a95e129a6f5e","items":["貫徹無障礙：督促政府落實公共設施無障礙動線。","滿足親子遊憩空間需求，爭取政府規劃遮風避雨的孩子放電場所。","檢討閒置空間、推動實驗劇場與live house、擬定青創協力方案。","媒合資源，推動藝文團隊冬季軟實力培訓方案。","維護行人通行權與檢討禁行機車道等交通問題。","從公部門落實友善品牌：多國語言服務、生理友善服務、行動裝置即時充電服務。","鄉市托、國小附幼、準公幼與公托資源整合，全力滿足托育、幼教需求。","提升大眾運輸便利性，票務e化，並檢討班次，更符合使用者需求。","力推流浪動物絕育，取締未打晶片飼主及非法放養，減少動物與民眾衝突問題。","確保外聘或計畫聘用之治療師、社工、專業臨時人員，不因行政程序而遭積欠薪資。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"45b573d4-0919-41b5-8c42-f77f45c4bc8c","items":["配合蔡其昌市長侯選人建設大台中藍圖，攜手並進追求市民福祉，創造幸福人生。","爭取國中小學生營養午餐全面免費。","支持18 歲公民權，讓青年朋友參與公共事務 。","人才留故鄉，地方大發展，住家買得起，世代有正義。","完成台 74 快速道路3處匝道及平面道路第二期工程。","催生擴大大里都市計劃區段徵收案。","爭取德芳路一段、美群橋及銀聯二號橋改建拓寬工程。","興建完成益民國小、立新國中，成功國中活動中心及地下停車場。","加速開關大里夏田、塗城產業園區。","儘速興建霧峰農會第二酒莊。","力促大里菸葉場活化再利用，再造地方新亮點。","振興光復新村，修復閒置房舍，建置故事館。","爭取放寬敬老愛心卡使用範圍，提高使用金額，並讓長輩自由運用 1000 元配額。","廣設長照中心、關懷據點，照顧老年人口。","增設公立托兒所、非營利幼兒園，關懷幼兒成長。","爭取老舊橋樑、農路全面改善及改建。","爭取自來水全面普及化並整治下水道系統。","規畫霧峰林家古厝歷史風貌區，活化運用文化資產。","重視農業生產及農產品行銷，協助農民解決蟲害防治並提高農損補助。","增設共融公園及寵物公園，提升生活品質。","打造水岸綠廊，提供鄉親休閒憩空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"45e44c9c-47e5-4687-ad21-aef3120829aa","items":["城市永續發展：導入循環經濟，帶動都市更新。","城市永續發展：提倡綠色運具，保障機車族權益。","城市永續發展：以人為本設計，落實行人友善與無障礙公共環境。","城市永續發展：推動綠化工程，打造全齡共融遊憩空間。","青年夢想未來：支持青年創業，完善青年社宅政策。","青年夢想未來：提倡透明政府，推動參與式預算鼓勵青年公共參與。","青年夢想未來：輔導文創產業，推廣藝術文化活動與美學創新。","青年夢想未來：支持多元發展，爭取新創產業實習機會。","親子安心樂活：增設公托公幼、臨時托育與夜間托育。","親子安心樂活：要求充實警力，強化社區安全網路。","親子安心樂活：重視動物保護，推動寵物友善環境。","親子安心樂活：學童適性發展，促進校園心理健康。","監督三蘆建設：監督蘆南蘆北整體規劃與推動進度。","監督三蘆建設：監督舊碧華國小、三重圖書館等重大建工程。","監督三蘆建設：完善老舊校舍整建與通學巷道工程。","監督三蘆建設：要求加速釋出停車空間。","監督三蘆建設：監督捷運環北段工程進度。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"4601d47c-d209-41ae-8c49-1d9b4b9086a2","items":["願意生：提升育兒津貼、及「父母未就業」育兒津貼，爭取設籍台中女性生育後坐月子補助津貼。","助弱勢：加強弱勢兒童及少年生活扶助以及課後輔導計畫，整合校園、社福、政府資源，提供孩子更多學習的機會。","快樂育：升級改造后豐地區現有公園綠地，建立親子共融、銀髮輔具、寵物友善的設施評估準則。","放心養：落實居家式托育服務登記制度，預防虐童事件、設置專屬兒童保護自治條例，要求針對12歲以下兒童傷害事實進行加重罰則!","愛毛孩：鼓勵飼主教育及寵物登記並數位化、加強寵物絕育及鼓勵流浪動物TNVR計劃，落實零撲殺。","拼經濟：推動觀光運動產業鍊：葫蘆墩公園水域活動(獨立舟、立槳)、雙馬特色休閒路線，爭取后里「國民及兒童運動中心」。","興商圈：推動大豐原商圈整合計畫：解決停車問題、建立步行街專區、搭配多元低碳運具(公車幹線化、小黃公車、youbike2.0)等。 協助農會開發日本、韓國、新加坡等外國市場，推廣后里豐原特色產物。 爭取中央及地方資源，輔導地方傳統商家轉型升級。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"46591d37-a72d-4f63-bbc3-fb0737369726","items":["深耕基層 致力社區發展：監督市政 落實為民喉舌","深耕基層 致力社區發展：爭取建設 重視市民權益","深耕基層 致力社區發展：關注教育 優化教育品質","深耕基層 致力社區發展：通盤檢討 保障就近入學","深耕基層 致力社區發展：增設公托 完善育幼服務","深耕基層 致力社區發展：力挺空橋 舒緩人車爭道","深耕基層 致力社區發展：改善交通 廣設通學步道","深耕基層 致力社區發展：衝刺體育 推展全民運動","深耕基層 致力社區發展：關懷弱勢 強化照護系統","深耕基層 致力社區發展：敦促市府 速建汙水下水道","深耕基層 致力社區發展：維護路安 推動電纜地下化"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"46fd0c1c-65d5-47d0-8fc1-951cd1563552","items":["重視地方宗教團體儀式整合。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"471c1556-8cf9-404a-883c-7c46b9d4c45d","items":["愛蘆竹，繼續拚！ 大竹地區 1.持續推動共融式公園設置 1.督促規劃大竹國小擴增校地，並規劃設置地下停車場與市民共享使用。","爭取於大竹地區新建大型共融式公園，增設親子共享全年齡遊樂設施。","推動社會住宅兼多功能使用 3.爭取拓寬上竹路為20米，並設置路外停車場，紓解大竹路停車需求問題。","督促市民活動中心設置完成 4.督促儘速興建大竹交流道往青埔高鐵站間跨越縣道110甲的高架道路工程。","督促蘆竹新行政園區設置 5.爭取大興段社會住宅，並附設開放市民共用微型運動中心及公共托育中心。","督促完善老人長照中心服務 6.爭取改建大竹公立游泳池為多功能休閒運動中心，並提供孩童運動空間。","督促捷運及輕軌早日興建 7.督促儘速完成興建新興市民活動中心，並附設長期照護日照中心。","督促增設「噪音偵測拍照系統」以科技執法 方式，杜絕擾人的改裝車輛噪音。 南崁地區 1.爭取羊稠集會所設置無障礙電梯，以利長者及行動不便民眾使用。","加強推動品格及道德教育 2.督促儘速規劃興建南興市民活動中心，並於內部附設下南崁社區圖書館。","落實技職教育協助青年就業 3.督促儘速完成興建蘆竹分局並增設警力，提供安心居住的生活環境。","推動U-Bike 2.0站點設置 4.督促儘速改建蘆竹新行政園區，設置演藝廳、活動中心、地下公共停車場。","因應高齡化社會，督促結合智慧科技興建 5.爭取新南路廢棄加油站改建為平面汽機車停車場，紓解南崁市區停車需求。 老人專科醫院提供長者更優質的醫療服務 6.爭取設置五福國小，並全面增加國際雙語教育，讓蘆竹的孩子與國際接軌。","因應少子化，爭取試管嬰兒補助資格放寬， 鼓勵生育。 山腳地區 1.督促儘速完成興建山鼻及濱海市民活動中心，並附設公共托育中心。","爭取規劃志工銀行，讓志工時數累積，陪伴 2.爭取於A10站社會住宅，附設開放市民共用微型運動中心及公共托育中心。 安心終老。","爭取於山腳地區設置親子館，提供親子互動溫馨共讀休閒空間。","結合科技規劃安心居住環境，串聯蘆竹三區 4.持續推動完善大古山及坑子溪休閒農業區設施，串聯成為休閒好去處。 新都心。","鼓勵青年返鄉創業，發展多元在地文化，結合休閒產業推動地方創生。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"47947752-37ea-48f6-a9f6-2eeab3b0a2d5","items":["全力推動花東快速道路興建。","加速花蓮至吉安段鐵路高架化。","落實警消值勤傷害法律免費諮詢,並編列救助經費,讓警消無後顧之憂。","積極爭取新住民及偏鄉子女教育補助,暨就業保障。","照顧毛小孩權益,爭取往生火化補助。","持續推動社會安全、經濟繁榮、環境永續、居住正義、財政紀律。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"47e2207e-431d-4c85-80ff-4ac3babe4ec2","items":["有社群基地會更好-自媒體時代,社群流量可以自我實現也可以是生財工具。","活化南山會更好-南山公墓活化為生命園區,文化保存與區域發展維持平衡。","支持在地會更好-輔導在地農漁業休閒化,發展觀光魚市場效仿東京築地市場。","海岸經濟會更好-整治海岸環境,由喜樹重劃區及歷史街區民宿帶動商機,鯤喜灣小旅行變大景區。","民宿管理會更好-改善安平民宿深夜噪音問題,狂歡之餘也要照顧他人休息。","有區域醫院會更好-醫療分級分流,大病小病分開看,健保資源有效利用","鼓勵生育會更好-生育津貼比照高雄調高至兩萬,公立幼兒園寒暑假專案收托,提高招生率。","照顧老人會更好-健保有補助,社區有日照,老了以後沒煩惱","終結月經貧窮會更好-擴大免費生理用品發放對象,照顧弱勢女性","有寵物公園會更好-安平1+1,南區0到1,毛小孩跑跳好自在。","有左轉道會更好-單向雙線道逐步推動左轉專用道,左轉不用等機會。","有地方停車會更好-閒置土地要利用,支持使用者付費,提升停車格數與週轉率。","沒有詐領會更好-不聘用三等親內家人為公費助理,支持助理費法制化。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"487c7d68-cc54-4209-94d3-49fd3f0d32e7","items":["（一）監督焚化爐使用、爭取提高回饋金補助造福鄉里。","（二）爭取漁民海上權益、保護漁民作業安全。","（三）爭取農民耕作福利。","（四）爭取提高青年創業基金，增加青年返鄉創業機會。","（五）爭取長青食堂普遍設立。","（六）爭取豆腐岬開放為海上水域區。","（七）爭取65歲健保全額補助。","（八）爭取銀髮族共樂友善空間。","（九）爭取勞工權益、福利。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"493543b3-c801-42bd-915f-612e09ad8eba","items":["拼經濟：照顧傳統店家，創新形象商圈。 升教育：竹東設立完全中學，提升品格教育貢獻所學。 顧勞工、青年：零星工業區建平價住宅（只租不賣，政府營運管理）。 照顧弱勢、樂齡：提高社會福利，培育第二專長。","全鎮安裝監視器，保障大家生命財產安全，打通周邊巷弄道路。","68快速道路延伸至上坪、橫山台三線至南昌大橋；竹科三期力行路30米延伸，東起員崠里、西到柯湖里（科學園區）。","二重國中、二重國小周遭土地被編為校地的，全面徵收；昌益科技產發園區公有土地興建圖書館、公園。","環宇、環球市內道路接通三重路；光明路旭光至上員山水溝加蓋。","中興路採用交通智慧號誌，尖峰時刻小缺口禁止左轉。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"495b5583-175b-428c-b0bc-b262b73cd95f","items":["情為民所繫 利為民所謀 權為民所用 青年承擔 謙恭傾聽 用心服務","推動建置原住民族文化創意園區以及青年創業育成孵化器,形成產業聚落。","規劃首座原住民族文化主題公園,打造桃園為連結國際多元文化國門窗口。","爭取青年國內外不同領域企業職場實習機會,增廣視野及裝備職場競爭力。","協調統合公部門與民間企業徵聘職缺,定期舉辦專屬原住民就業博覽媒合。","設置原住民族語教學幼兒園、增加培訓族語保母人數,語言學習向下扎根。","增設老人日間文化健康關懷站以及提供接送服務,提升照顧服務支持系統。","簡化社會福利申辦程序,建立單一服務窗口,結合教會提供弱勢家庭關懷。","提高預算支持原住民社團協會,舉辦語言文化傳承、學習、發揚相關事務。","建設復興區泰雅族文化觀光園區、推動設置北橫國家風景區升級休旅產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"49ab065d-0fb2-42f2-bf96-cbd57e18dba8","items":["敦促農政單位輔導建構原鄉農特產品產業六級化發展，厚植一至二級產業發展能力，透過建立品牌與借助農民團體產銷組織力量，加強三級產業物流及銷售管道，提升農產品經濟價值。","爭取縣府公辦之營養午餐的食材來源按一定比例採購原鄉之安全農產品，保障學童食的安全，提升農民收益。","推動各項農業補助計畫，補助原鄉農民，降低農事成本。","推動原鄉青年農民專案計畫，爭取原鄉青年從農各項福利，鼓勵青年農民返鄉。","爭取改善原鄉農路，保障農產品運銷出入順暢無礙。","推動設置「原住民族保留地法律諮詢窗口」協助族人釐清疑義。","增加國土計畫原住民族地區農四範圍劃設面積，提高族人建築用地面積。","落實原住民保留地補辦增劃編工作，增加人力加速審案，及早完成原住民保留地權利回復。","建構部落安全網，重新檢視盤點並增強部落防災及消防硬體建設。","檢討原住民警消薦升制度、擴編警消編制，增設力行線及萬豐線二處警消分隊，並優先聘請原住民籍警消擔任分隊主管。","推動「原鄉免費法律諮詢服務」，方便就近解決族人面臨司法程序知識的不足。","爭取部落文健站業務推動執行，幫助原鄉長者就近獲得照顧。","優化原鄉學校網路、督促原鄉教育環境設施升級。","爭取原鄉國民小學免費早餐。","優先聘用原住民族籍合格教師、代理及代課教師應達一定比率。","加強推動原民特殊學童教育，應優先聘用合格原住民籍特殊教育教師。","強化南投縣原住民族教育資源中心功能，增列原住民母語教學預算經費，獎勵母語教師編寫教材及提升母語教學能力。","加強山區醫療服務，編列「醫療專車」經費，方便接送部落長者及族人就醫。","建置「原鄉緊急醫療整合平台」，以利醫療資源調度。","發展原鄉長期照護服務機制，推動在地長照專業人才培訓計畫。","提高弱勢戶原住民老人假牙補助經費。","爭取設置「原住民創意產業平台」拓展原鄉好物之行銷通路。","敦促縣府制訂「原鄉青年回鄉創業補助」計畫，提升原青回鄉創業的動機。","推動舉辦「南投縣原住民族產業博覽會」推廣原鄉農特產、高海拔優質農作物及原鄉人文好風情。","推動成立「部落自然人文生態景觀區」，建構部落共管觀光機制。","串聯各部落，規劃訂客製化套裝遊，發展部落生產、部落銷售、部落消費的部落深度之旅，強力連結各部落發展部落文創、精緻農業、觀光旅遊，帶動原住民部落經濟產業全面發展。","研議南豐村至親愛村直行隧道（自南豐村台14線71公里處北向南設置長隧道至親愛村松林部落）之可行性，以利各部落於醫療、消防、交通、運輸、觀光之安全性與便利性。","改善仁愛鄉法治村聯外隧道之路面及隧道內燈光，提升鄉民用路之安全性。","建請縣府成立「投89線替代新闢道路專案小組」，研擬新生村經惠蓀林場至發祥村銜接投89縣道可行性。","爭取原鄉各部落聯外道路安全，縮短城鄉距離，保障原鄉居民行的權利。","爭取補助原住民族人購置族服補助經費。","振興補助原住民族文化活動（如泰雅、賽德克族歲時祭儀、卓社群射耳祭等）。","支持傳統產業創意轉型，輔導成立「織女學苑」、「獵人教室」等文化產業。","獎勵母語音樂創作發展。","積極爭取設立原鄉綜合運動訓練場地與設施－「原青運動產業中心」。","爭取提升原住民運動會選手獎金，提升體育人才獎勵金制度。","全力推動一村一風雨球場，培訓原鄉體育人才。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"49b2205f-f5c6-4de8-a532-13ead4135784","items":["生活會更好 完成：新設4所國中國小；新建改建2座圖書館；成功打通改善道路橋樑工程40處。 承諾：全力推動台中捷運建設；推動住宅區寧靜法；提高詐騙犯罪最低刑期。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["past_achievement"]}}},{"claim_id":"49bbcc56-c317-4c50-b005-85e276911b9f","items":["確保主權、接軌世界 : 拒絕一國兩制,捍衛中華民國主權與人民安全,支持與世界民主國家持續合作,追求世界和平。","強化教育設施、增加多元資源 : 1. 持續爭取經費,強化學校的教學及學習環境,保障師生權益。","爭取各級學校更完善的 心理健康支持資源,推動非語言形式的諮商運用,使特教生與青少年輔導有更多元的模式。","建構完善的交通網絡、促進地方發展 : 1. 持續督促東彰快速道路興建工程盡早完工,提升彰化東半部的交通便利性。","強 化高鐵彰化站對外交通路網提升運輸能量,包含持續推動台鐵田中支線(田中高鐵站 - 田中台鐵站 ),銜接集集支線,提升 中部地區聯外的便利性,串聯成觀光廊帶,讓田中鎮成為彰化、南投、雲林重要的交通門戶,帶動地方發展。","推動地方創生及擴大青年就業:協助爭取中央經費進行地方創生計畫,根據各鄉鎮特色,再造在地產業,從觀光產業、創 意加值、技術提昇等面向,強化地方產業發展及地方生活機能,吸引青年返鄉。","完善長照、優化見福 : 1. 爭取中央經費,協助地方規劃設置各級長照據點,讓長輩受到妥善的照顧、在地老化。","敦促政 府推動各級幼兒照護,提供優質幼兒照顧能量與設施,減輕年輕人生養的負擔,促進人口成長與回流,確保國家永續發展。","順應環境、深化觀光 : 1. 保護並善用八卦山脈的生態資源,協助爭取員林市藤山步道生態園區、大村鄉五里坑相思步道等 計畫,打造優質遊巷環境。","積極推動在地的鐵道文伺、花卉產業、生態資源、農村文化,結合地方民俗節慶、馬拉松 盛會等,推動深度觀光旅遊,帶動彰化觀光產業發展。","產業升級、活絡經濟 : 1. 敦促政府強化台灣產業及投資環境,爭取員林新設工業區,吸引企業返鄉投資,促進產業升級, 擴大就業機會,保障勞工權益,創造勞資雙贏。","持續支持發展綠能產業、循環經濟,讓產業能符合國際綠能標準,進軍 國際市場帶動產業成長。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4a099606-545a-4554-a9e2-a806b043b678","items":["促進馬公港建設，成為免稅島振興經濟","建議增加駐軍刺激消費"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4a6da7e9-6f69-471f-88ac-a9f6ba7091d8","items":["推廣藝文活動，支持在地藝術家。","加速推行地方／行政機關支付e化。","解決「月經貧窮」，守護婦女權益。","整合社會資源，落實弱勢族群之生活。","增設完善人行道、自行車道，增加用路安全。","推行南投旅遊電子套票、促進觀光，增加觀光財。","推展創客，提升南投軟實力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4a74b3df-a525-4f91-a944-3d9da49f5e70","items":["城市建設：持續推動基隆新市政大樓興建、軍港及貨櫃港西遷，並盤整周邊國公有空間，協助三沙灣、大沙灣地區都市更新。","社會住宅 2.0：推動祥豐街海關宿舍更新案，配合東岸整體發展，興建基隆第二座社會住宅，提供市民友善、平價的居住環境。","全國首座海洋國民運動中心：爭取海科館海生館預定地轉型作為全國首座海洋國民運動中心，並結合海洋休閒運動產業，如潛水、划船、衝浪等，完善市民多樣運動空間的需求。","推動青年文創聚落：以正濱青年孵育基地（紅磚屋）為核心，媒合舊漁會大樓、正濱色彩屋周邊閒置空間，並結合地方青年團體及商家，推動基隆文創藝術聚落，提供青年產業發展的新選擇。","安全住居：要求中油公司儘速完成八斗子地區大型儲油槽遷移，維護周邊居民生活安全，並將拆除後的空間結合望憂谷濱海步道，增設親子及長者共融的公園空間。","交通運輸大革新：推動藍色公路，舒緩東岸交通困境、並提升基隆港區觀光效益。爭取共享運具進駐，提供短程運輸新選項，並減少私人載具的使用。","老幼弱勢關懷：爭取弱勢團體、新住民專屬行政及活動空間，減輕市民負擔。推動在地照養，打造銀髮族樂齡生活，並結合社區關懷據點，提供照顧服務減輕子女負擔。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"4ae7715f-e21f-4805-b932-486254533c81","items":["縣政效能革新","醫療環保落實","經濟觀光有感","教育體育升級"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"4b080580-4b5d-4685-9c59-8078d507a0d6","items":["監督縣府辦理原住民保留地增、劃編計畫執行進度 ，以落實東海岸三鄉鎮原民土地所有權之取得。","督促縣府培養原住民族教師及進用 ，以利原住民語言之傳承及原民語言政策之發展。","督促縣府強化消防設施 ，以保障人民生命及財產之安全。","督促縣府重視原住民的傳統文化、語言、技能及祭典儀式的傳承。","督促縣府強化偏鄉醫療設施及環境。","創造青年人就業機會 ，加強農漁產業及觀光行銷 ，改善族人生活 ，增加農漁民收入。","注重原住民部落各項軟硬體建設 ，農路溝渠改善、蓄水池、簡易自來水增設。","監督縣府縣政。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4b3d7881-f392-4306-bfed-006c61aaf7e8","items":["積極推動國中、小雙語教學課程，規劃良好英語教學環境。","積極要求市政府將田寮河的景觀改造、河水整治，給市民一個運動休閒的地方。","積極爭取經費改善易淹水地區路面及排水系統，以利市民免受淹水之苦。","促請自來水公司更換老舊管線，改善高地供水加壓設備，增加大型蓄水池，以利民眾供水問題。","促請市政府維護全市砲台，保存文化資產。","促請市政府加強婦幼、身心障礙、老年、失業者等弱勢族群照顧與保護。","積極推動救急救災通報系統，健全監視系統，做到治安無死角。","積極要求市政府路平專案並改善騎樓的地面高度一致，推動市容整頓，加強公共建設，營造美麗新基隆。","促請市府打造「基隆科學園區」，串聯成為北台灣科技產業廊帶，重整活化六堵工業區、大武崙工業區、北台科技園區，創造就業機會，留住優秀人才。","積極推動維護基隆海域自然生態。","積極爭取寵物公園，打造一個動物友善城市。","強力監督基隆市田徑場主建築拆除重建（含停車場）及周邊運動服務設施改善工程施工進度及品質，提供市民優質運動空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4c5df43a-2a5f-4c75-8669-a8e5bd2f7e30","items":["監督縣政，為民喉舌。","發揚客家文化，爭取六堆客家權益。","爭取潮州鎮Pbike自行車租賃站多設幾站，以利交通觀光動線。","注重全民體育，提高獎金，提昇本縣體育水準。","輔導農業轉型，推動精緻農業、漁業之共同產銷制度。","推動東港溪河川整治，營造自然生態親水環境、水岸廊道。","推動屏東縣健康產業園區之美綠化景觀及週邊交通道路的拓寬。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4cae85a6-c6ca-4aa1-9037-dfe2f71463a0","items":["爭取通學步道，守護學童上下學安全。","爭取運動空間，提升鄉親生活品質。","陪伴不老社區，落實在地安老，爭取提高老人食堂供餐補助。","爭取廣設日照中心。","推動適性閱讀，設立漂書站，讓知識漂流，二手書自由。","創造藝文空間，為地方村莊注入藝術、生活美學。","推廣在地農產，提升附加價值。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4cd0e0ca-8782-4858-a067-468e19d7a9ec","items":["監督交通建設(輕軌、黃線捷運)不要有交通黑暗期。 督促市府提出周延交通計劃、提供足夠停車空間,並與市民溝通。","成功監督市府還債 71 億,持續監督市府減債績效。","高雄要有好空氣,監督中區焚化廠如期於 2025 年除役。","關心年輕人就業與創業,持續監督市府青創績效,協助在地青年圓夢。","持續督促市府將閒置空間轉為老人長照及幼兒托育的據點。","持續督促市府扶助弱勢家庭,法規鬆綁並整合公私資源落實之。","反毒政見 持續打造無毒高雄,為毒品防制擔任反毒志工。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["past_achievement","heading_or_slogan"]}}},{"claim_id":"4ceae92c-4264-44e6-96b3-5eda06c9e126","items":["均衡新莊共榮發展計畫","力推TOD(捷運)廊道安全整治城市發展","爭取泰板輕軌路線行經西盛地區帶動地方發展","預先開挖塭仔圳重劃區公園，建設停車場","規劃第二國民動中心之兒童運動專屬特色場域","爭取更多配合經費供學校改善使用","文藝活動提升","特色城市規劃"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"4d2617d9-2515-4f0c-9ff5-03a6debe85e8","items":["爭取縣府提高各社區長者營養午餐補助。","促請縣府清查公有閒置建物，改造為日照中心，提供長者就近安養及鎮民就業機會。","極力促請宜蘭縣政府輔導蘭陽技術學院轉型，以利地方發展、增加在地青年就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4d36088a-1675-4b99-8565-dbd3a7b2f293","items":["【社會安全】 推動修繕老舊建築、維護建築合法性，積極落實防災式都更，落實社會安全。","【守護健康】 推動社區健身指導員、擴大推廣「樂齡健康運動站」，讓全齡共融健康運動。","【居住正義】 擴大租屋補助、推動房屋交易出租安檢，確保住的安心安全，實現居住平權。","【互助關懷】 強化安全網，杜絕家暴、保護兒童安全、建立快速救援機制，關懷保護每一個人。","【環境永續】 建立大安文山生態走廊，連結大台北綠色生態棲息鏈，豐富文山都市輕旅行。","【捍衛權益】 改善第一線警察、消防與醫護人員權益及安全，補足設備、改善勤務，安心投入工作，守護民眾健康與安全。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4e0a4130-caf2-443c-98b7-dc28f15621e6","items":["推動「憲法原住民族專章」的制定，提升保障原住民族的地位與權益。","推動「原住民族自治法暫行條例」的立法，加速原住民族自治的進程。","加速「原住民族土地及海域法」的立法進程，落實傳統領域的精神。","推動「原住民族土地調查及處理委員會組織法」，實踐原住民族土地正義。","推動「原住民族交通平權法」的立法工作，強化原鄉部落道路交通安全。","推動「原住民族森林碳匯」的立法工作，落實原住民族自然主權與公平正義。","推動「原住民族銀行」，充實原住民族創業基金，提升經濟與社會地位。","推動「原住民族教育法」修法，原住民重點學校校長、主任一律由原住民擔任，強化教育主體性。","推動「原住民族運動獎勵法」的立法，培訓、獎勵並保障原住民族運動人才。","爭取「原住民族免繳健保」，落實原住民族健康法精神，保障原住民族健康。","推動「原住民族文化資產保護法」的立法工作，加速原住民族文物返還與保護。","推動「原住民文化藝術音樂獎勵辦法」，獎勵、培養原住民族文化藝術音樂人才。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4e7d3644-9e1c-46bd-9397-436e103af48d","items":["極力輔導農業轉型有機及觀光複合產業。","督促老人照護健康站，增設長期照護設施及無障礙設備增修。","積極爭取原住民青年及婦女創業資金貸款，及輔導創業辦法。","政府重大公共工程建設應保障原住民勞工聘僱比例。","增列原住民育兒津貼，提供原住民孕婦待產補助。","落實居住正義，租屋及建構、修繕補助。","爭取提增族人醫療就醫補助及免費健康檢查。","鼓勵原住民回鄉就業，提高在地原住民職訓補助額度及輔導就業。","極力爭取推廣原住民觀光夜市及市集文化。","增列原住民弱勢族群急難基金及保護原住民保留地。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4e90952e-f541-4af7-9503-1e8d30e53824","items":["監督縣政，雲林彬 go！","林文彬做議員，在服務處工作 每週一至週五：5所學校60多位學童，「孤挺花」免費課後輔導。 每週四晚上9至10時：「新雲林之聲」FM89.3電台主持「阿彬開講」，歡迎收聽。 每週五晚上7至9時：專業律師服務，歡迎免費諮詢。","林文彬做議員，在選區（褒忠、土庫、元長、虎尾）服務 傾聽民意，服務紀錄《林文彬時論：從雲林看世界》、《虎尾創生：生活首都》、《獨信陳良：寫給陳良的十八封信》、《台灣的第三條路：社區營造政治學》、《雲林，你忘記了甚麼？》共6冊約56萬字，證明林文彬深耕地方、全方位服務，與鄉親見面率最高，特向雲林鄉親報告的「提案白皮書」、「議員成績單」。 林文彬後續砲火十足，質詢提案更有力；監督縣政，雲林彬 go，品質第一！ 林文彬創新實現，說到做到。林文彬顧家鄉、拚未來，敬請大家繼續牽成。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4ec5d6cd-7a0f-49e9-93ed-1563689580a6","items":["督促政府引進高端產業留住人才，厚植經濟實力，增加青壯年就業機會，提高基本工資。","健全各產業園區功能，園區內設置青創育成中心，降低青年創業門檻。","監督政府防洪排水計畫，整治阿公店溪、典寶溪以及各排水系統，完善抽水站及設備，徹底杜絕淹水問題。","要求政府積極改善空氣品質，嚴格監管廢水排入河川，捍衛市民健康。","督促政府興建全市各區多功能運動中心，充實室內外運動場館設備，滿足市民休閒運動健身之需求。","串連大岡山地區觀光資源，整體規劃觀光景點，活化在地歷史建築，保留眷村文化。","力促捷運紫線（高雄學園線）興建，結合沿線橋科、台積電與周遭大學產學合作，提升本市科技競爭實力。","完整高雄捷運路網，推動北高雄海線（新台17線至台南市政府）捷運規劃，繁榮沿海地區。","督促高雄新市鎮後期開發區與橋頭科學園區發展作通盤整合。","縮減城鄉差距，力促政府調整合理預算資源配置。","督促政府健全農漁貨產銷制度，拓增外銷通路，爭取放寬農漁業天然災害補助標準，保障農漁民收益。","監督政府落實長照保險制度，營造「以家為核心；社區為輔」的多元長照制度。","增加幼兒園托育補助，善用國小閒置校舍增設公立幼兒園，減輕父母育兒負擔。","擴增公共托嬰據點，增加各據點托嬰人數，提供年輕父母喘息服務。","要求全面檢討教改，建立開放多元、資源豐足的終身教育體系。","要求完善警察、消防人員裝備，補足警消超勤津貼。","督促政府完善動保制度，改善流浪犬貓收容環境，增加寵物認養據點。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4f106533-424d-439f-b251-7100e1fddea5","items":["督促新竹縣政府繼續發放老人年金、鄰長津貼、國小、國中學生免費營養午餐、免費提供教科書、新生兒營養補助、身障補助、愛心車卡、老農保障等八大項社會福利政策。","督促新竹縣政府增設公立、非營利及準公共幼兒園。","督促新竹縣政府儘速興建完成垃圾焚化爐解決垃圾問題。","督促新竹縣政府向中央爭取竹東鎮各里家庭汙水廢水下水道系統之管路埋設並銜接至汙水處理廠。","建議政府儘速完成68快速道路延伸至軟橋，以利交通順暢及發展觀光繁榮地方。","爭取竹東河濱公園精緻化增加設施以利民眾休閒運動及生態教育空間，並延伸至外五里段與新竹市相銜接。","督促新竹縣政府開發園區三期土地時要用心細心檢討，傾聽地主聲音、公開透明，以確保地主之權益及繁榮地方。","建議政府儘速興建北二高二重交流道，以利竹東鎮外五里有完善之道路交通網。","二重國中因鄰近科學園區及工研院，且近來外五里新建大樓林立、學生人數逐年增加，造成教室不足，建議政府儘速擴展二重國中升格為二重高中（完全中學），並新建標準運動場、學生室內體育館等。","確實反映民意，積極爭取竹東鎮各里鄰及五峰鄉各村落之各項地方建設。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4f22e89f-9c7b-4f78-a9ad-51765c617ccd","items":["■「好的，就繼續。」 這是府城古都得以傳承數百年依然亮眼的價值基礎，我們這一代，仍得肩負起同樣的責任，守護美好的文化傳統、節慶習俗、古蹟資產，讓台南持續以「台灣魅力之都」邁向國際。 ■我們一起「堅定向前」 回應新時代的需求，城市永續發展必須在傳統中保有新創的活力，請您跟筱薇一起，讓我們不同世代的台南人，能以堅定向前的步伐，為我們共同的家園的建設與福利打拚。","推動由「產、學、研、青壯、樂齡」代表組成「都市願景研議小組」，定期向市府提出民間對於城市發展願景的構想藍圖。","爭取經費推動更具美學概念、在地特色的傳統巷弄風貌。","建置更多現代公共藝術，強化東區藝術、文化、休閒的區域發展特色。","督促市府重新研議在東區建置小巨蛋室內場館的可行性方案。","因應人口高齡化趨勢，主張一區一座國民運動中心；社區公園增設銀髮族強化肌力體健設施。","推動65歲以上銀髮族免費肌力檢測，提早因應肌少症帶來的失智、失能健康風險。","持續督促市府成立青年局，統籌辦理新世代各項城市生活與發展權益。","積極推動綠能及AI數位科技智能導入交通建設網絡。","督促強化國際觀光宣導，佈局因應後疫情時代全球旅遊潮。","持續爭取提高家庭托育補助費用，減輕新家庭負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4f478367-6fbd-4bf4-ab22-67ee22b5bc40","items":["【欣儀為您完成】 Ⓥ學童搭捷運享6 折優惠；「班班有冷氣」冷氣汰換與電費不再由家長募款買單。 Ⓥ恢復發放重陽敬老金及老人健保補助。 Ⓥ推動北市青年尋職輔導津貼。 Ⓥ設置多處捷運雙向電扶梯。 Ⓥ辛亥、懷恩隧道壁體美化及更新改善。 Ⓥ台北市立圖書館在舊AIT 結合音樂中心興建；設置大安森林公園共融式遊具。","欣儀為您爭取","從小顧到老！提高生育獎勵金、增加公托（幼）、社區日照及長照。","教育是最好的投資！落實雙語及數位教育，學童營養午餐物調差額由市府補足。","教師權益我維護！增加學生輔導服務津貼及教師升等檢定補助。","搶救青年失業潮！推動「青年尋職輔導津貼2.0」、把關就業權益。","長者照顧智慧化！推動社區長者緊急照護及救援E 化系統。","提供弱勢便民服務！敦促市府成立一站式窗口、簡化相關補助手續。","推動防災型都更修法！放寬山限區「山坡地老舊社區」都更、降低公辦都更門檻。","行車順暢不再塞！拓寬木柵路四、五段道路用地，推動不合理的交通路型更新。","力拼交通升級！加速推動「捷運南環段」，增設出口；持續廣設「捷運雙向手扶梯及電梯」。","打造台北文化新地標！加速推動「大安音樂圖書中心」建設進度，督促舊市圖儘速轉型「社福基地」。","營造繽紛城市花園！優化「大安森林公園」，打造都會永續棲地。","落實三貓計畫！設置貓空景觀吊橋、振興貓空產業、減少貓纜虧損。","行銷台北走向國際！一站式便利申請北市各大景點拍攝、加碼補助新銳影音團隊。","向英雄致敬！維護警消及醫護權益、提升裝備效能，補足員額。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"4f683737-71a3-436d-a23c-36457469773a","items":["均衡發展：推動縣治中心南移，均衡彰化整體發展。","監督財政：檢視地方財政，要求謹守財政紀律範疇。","健康樂活：爭取共融式休憩設施，打造親子健康運動園區。","關懷身障：建置身障就業前教育，整合身障夥伴就業資源。","保護婦幼：推動完善社會安全網，推動受家暴婦幼緊急避難所。","照顧農民：打造農產市集，整合產銷系統，搭建兩岸農特產銷售平台。","升級教育：改善教育資源不均，合理分配教育預算，縮短城鄉差距。","青年返鄉：推動青年返鄉各項資源整合，提高青年首購自住房屋補助。","長青福利：推動建置社區長青日托中心，建立獨居老人安心通報網。","新住民權益：改善弱勢新住民生活環境、提升弱勢新住民家庭子女教育品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"4f838a98-a0ce-4362-9f1d-64ad33365db0","items":["促進國立陽明交通大學附設醫院二期工程（蘭陽院區）如期完成營運，以改善本縣醫療資源不足，提升醫療品質及水準。","促請政府積極招商帶動宜蘭科學園區發展，提供更多就業機會，以安定縣民生活及繁榮地方經濟。","落實鐵路高架化，減少等候火車通過時間，有效解決鐵路東西交通阻隔，以達成區域平衡發展。","督促高鐵延伸宜蘭早日完成，有效紓解國道5號車潮及減緩塞車現象。","建置重要路口監視系統，有效嚇阻不法行為，防制犯罪發生，確保民眾生命及財產安全。","因應本縣邁入高齡化社會及少子化趨勢，加強多元性老人及兒童福利政策及增加經費。","開闢市區及增設郊區停車空間，提供公車運輸接駁，有效解決交通壅塞問題。","加強宜蘭河水岸慢行道及水域周遭環境維護，增加民眾休憩活動空間有效利用。","推動宜蘭市擴大都市計畫，加速宜蘭市整體發展。","督促縣府限期檢討私有公共設施保留地，對不必要的部分應儘快解編，以維護民眾權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"505a3465-eba2-4d56-a6db-0e109878b87e","items":["一：督促政府，成立青年事務局，協助青年解決就業、創業、結婚、生育、居住問題，讓北漂青年能夠返鄉，讓其它縣市青年，願意移居台南。","二：爭取適合各年齡層使用的全齡化公園，讓老、中、幼童等不同世代，能攜手共享同一休憩空間。","三：爭取西拉雅國家風景區延伸至龍崎，結合龍崎原有景點，特殊地景，讓龍崎成為台南休憩聖地及最美後花園。","四：監督砲校主體工程與5條聯外道路建設時程，讓砲校及早完工，挹注關廟經濟發展，讓關廟擁有更完整的交通網。","五：盤點綠能智慧園區暨南關線各項重大建設案中，需地方政府配合的事項。全力督促市府，抓緊時程，配合中央政府，讓各項建設案如期完工，帶動南關線整體發展。","六：增設食物銀行，惜物平台，擴大關懷據點服務量能。提升監視器妥善率與治安死角見警率，來強化社區安全網。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"5091ab61-a4d7-489c-bc6a-6cc1b46295f7","items":["爭取地方及中央補助，建設東方美人茶送，服務偏遠鄉村。 或椪柑為主的觀光產業博物館。","增加警消設備預算，確保治安及人民生","推動在地觀光農場，促進地方青年回鄉活安全無虞。 就業。","廣設社區長照站及辦理共餐活動。 題，保障勞工相關權益。","改善北埔、峨眉往返竹科的交通路段， 十二、爭取提高新竹縣民平安保險補貼。 提升路燈夜間照明設備。","增設公立幼兒園、平價托嬰中心、結","檢視交通事故頻率較高之道路，評估改合社區保母制度。 善道路品質以降低交通事故。","提高生、養嬰幼兒津貼及老人照護措","提高社福預算給身障、單親、中低收入施和福利，減輕青年成家的經濟負 戶和貧困弱勢家庭。 擔。","爭取老人醫療安養照顧，持續老人假牙十五、推行各社區協會發展、 客家文化傳 補助。 承。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"50bc9a00-7af7-4ac5-9e33-e17e2d7d59a9","items":["親子空間再升級 已成功完成信義區景勤一號、松山區民生公園兩座共融式公園。 未來將持續推動特色公園，並爭取建設「兒童體適能運動館」。","智慧城市 更新台北 爭取 3000 萬元治水工程預算，針對松山區易淹水區域進行排水工程改善。 持續推動都市更新相關政策，讓台北發展更迅速、市容更年輕。 推動設置違建處理委員會，讓違章建築狀況更公開透明。","社會福利與正義 增設公共托嬰中心、幼兒園，要求降低師生比，重視學生權益。 持續推動日照中心、老人共餐，並且加強推廣樂齡學習與運動，要求運動中心納入無障礙設備。 持續與動保團體合作，推動各項動物保護政策。 都市再生 台北回春 增設公托、公幼，提高生育補助，緩解少子化危機。 加速城市更新，打造更宜居、安全、美觀的台北。 推動青年住宅，提供年輕人起步階段的居住保障。 持續爭取共融式公園，實現不分世代的同樂。 強力監督執政者與市府，為市民爭權益、為人民討公道！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"50c6feb7-494b-4ca4-b45c-f51f8a31958c","items":["婦幼安心 質量兼顧：爭取廣設公托公幼，減輕家庭養育負擔","婦幼安心 質量兼顧：舉辦早療篩檢計畫，讓慢飛天使順利接軌","婦幼安心 質量兼顧：兒虐零容忍，強化兒童保育環境","婦幼安心 質量兼顧：保障托育員及教保員工作環境","婦幼安心 質量兼顧：爭取婦女凍卵補助，讓女性擁有生育選擇權","扶老攜幼 樂活相伴：爭取銀髮俱樂部及樂齡課程","扶老攜幼 樂活相伴：爭取運動中心銀髮族運動補助","扶老攜幼 樂活相伴：加強遠距照護及高齡友善的醫療環境","扶老攜幼 樂活相伴：爭取長者假牙補助，讓長輩吃得下，才健康","友善環境 綠化升級：加速瓦瑤溝整治工程，打造綠化清水環境","友善環境 綠化升級：整治中原溝排放廢水及清淤工程","友善環境 綠化升級：監督捷運萬大線工程進度","友善環境 綠化升級：廣設全齡共融式公園(已成功改造秀山公園、光之公園)","居住正義 我們相挺：爭取提高青年租屋補貼，減輕青年租屋負擔","居住正義 我們相挺：監督社會住宅設置進度，讓社宅質量兼備","居住正義 我們相挺：推動社會住宅包租代管比例以及公益出租人減稅優惠","幸福中和 服務延續：持續提供民眾免費法律諮詢服務","幸福中和 服務延續：為捷運工程受影響店家爭取減稅及租金補貼","幸福中和 服務延續：爭取寵物友善公共運輪及寵物公園","幸福中和 服務延續：爭取勝利路電塔搬遷工程及變電箱、電纜地下化作業"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"51893c6f-94d6-4b19-ac16-0896eac8f2cc","items":["善盡為民喉舌職責，監督縣政，俾落實原住民相關政策。","積極協助推動整合自然生態、傳統文化、農特產及觀光，爭取預算改善交通設施、活化空間，提升產業經濟之發展。","監督政府落實原住民族教育，並推動獎勵優良表現教師、學生及文化教育有功人員。","爭取各項福利措施（如中老年人、婦女幼童、身心障礙者……等）及軟硬體設施，扶助照顧弱勢。","秉持真誠奉獻服務的熱忱，為鄉親爭權益、謀福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"51d6bec9-4c6f-4093-b036-f0d05a817f2a","items":["秉持一貫為民服務之精神與理想,為提升市民福祉之政策辯護,推動及展開基層代言急先鋒。","全心全力監督市政,讓地方百姓繳納的稅款真正做到取之於民、用之於民。","維護公益,照顧弱勢,扮演官與民之間的橋樑,盡力消弭兩造之間因認知誤差所產生的不公不義之情事。","監督平衡城鄉之總體發展,督促市政單位用心經營各城鄉地方特色,促銷觀光及文化以推動地方之經濟繁榮。","重視品德教育、提高生育補助、關懷老人長照、捍衛空汙守護食安、拒絕酒駕、以電能帶動經濟發展,打造一個有願景、有"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5214decb-6180-4015-8b0a-54709e209c80","items":["升級中和交通：員山區泰板輕軌增設輕軌壽德站、輕軌國光站兩站與捷運萬大線共構。","升級中和交通：疏通南勢角車流，開闢南勢公路隧道直通中安大橋到達台北信義區（101大樓）。","升級中和交通：特二號快速道路（台65甲）延伸中和市區以及華中橋，推動中和大排水溝東側30米林蔭大道連結北二高、台64線快速道路與新北環河快速道路。","升級中和交通：灰磘農業區轉型科技園區，創造在地就業機會，並加速灰磘都市計畫區段徵收、監督經費開支。","升級中和交通：活化閒置國有地，廣設育嬰公托中心及老人日間照護中心等社福據點，並廣設社會住宅、推動都更與改建，落實青年居住正義。","升級中和交通：爭取中和各公園增設（地下）停車場，緩解鄉親停車需求。","升級中和交通：成立新住民專責中央機構，照顧每位新住民的權益。","升級中和交通：推動年金基本法，建立制度性調整機制，隨物價指數上漲達一定門檻時，同步進行調整。","升級中和交通：立法保障教師管教權，結合輔導室的資源，視學生身心狀況及需求，提供發展性輔導，教導孩子對自己的行為負責，並兼顧教師權益與教學品質。","升級中和交通：徹查疫苗快篩劑與雞蛋採購弊案。","升級中和交通：解散浪費預算的國家隊、辦公室；清理國營事業酬庸弊端。","升級中和交通：重啟特偵組掃貪、抓黑金、拚治安。","升級中和交通：逐步調高基本工資到35,000元。","升級中和交通：所得淨額56萬以下、薪資所得占課稅總額七成以上的受薪階級，所得稅減半。","升級中和交通：扶養12歲以下子女，原本扣除額提高50%。","升級中和交通：公司提撥稅後盈餘為員工加薪超過1%，超過部分扣抵當年營利所得額，可提高至150%。","升級中和交通：為30歲以下年輕人加薪，可扣抵當年營利事業所得額，由150%提高到220%。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"52978743-36d0-4f5b-a8ae-6a92d9b9eff0","items":["落實老人長期照護、日間照護及社區老人食堂開辦。","振興山區觀光產業，建設經濟、特色之旅遊動線規劃。","保護農民特殊產業推廣，青年返鄉種植各項優惠方案。","推行閒置空間再利用，創造更多生活學習運動空間。","選區內路平、排水、平坦順暢，讓回家之路安全，讓生命財產，得以保障。","關懷弱勢權益，保障勞工權利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"53275eda-6a42-4ae9-96da-33680d8cf0b1","items":["教育政策：加強原住民族語言教學工作、廣開原住民族語言教學課程；編列體育及技藝人才培育獎金或健全訓練場域，藉以鼓勵原住民體育及藝術人才。另外，持續推動免費營養午餐、族語教師專職化。","就業經濟政策：督促政府落實原住民族工作權保障法，加強原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，打造屬於新竹縣原住民文化創意產業，以改善原住民經濟，提升就業機會。","社會福利政策：督促政府落實原住民福利政策，並協助原住民納入政府多元福利網絡，充份爭取原住民各項社會福利資源，如專業法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。","文化傳承政策：為積極發揚本縣原住民優良傳統文化，主張擴大舉辦原住民族文化祭儀等活動，以期保存原住民族文化並向下紮根。各鄉鎮市落實頭目組織常設化，並增列相關預算，強化原住民族文化發展。","族群和諧政策：保障縣內各住民共存共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活圈。","原住民的任何事就是我的事，原住民的小事就是我的大事；在地出身新竹女兒，一通電話到府服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"53292131-e90e-48d1-a0b8-cbaf1d3e3229","items":["串連各大眾運輸工具與汽機車道，打造海線交通路網","打造海線觀光廊道","公園遊憩設施規劃體檢革新","加速活化台中港特定區 為孩童","推動寶貝照顧者喘息支援","照顧教保員，爭取福利","老人健保持續補助","愛心卡補助升級、服務擴大","推動公辦青銀共居住宅","擴大推動長照關懷據點 為青年：督促持續興建社會住宅","擴大推動長照關懷據點 為青年：倡議社會住宅多元房源","擴大推動長照關懷據點 為青年：推動青年社宅回饋計畫","青創單一窗口天使計畫 為環境：因應氣候打造韌性城市","青創單一窗口天使計畫 為環境：台中淨零碳排路徑規劃","青創單一窗口天使計畫 為環境：研議推廣垃圾減量獎勵"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"53657df3-bfcd-42ce-93c0-0aefeda5dc58","items":["落成前瞻計畫地下停車場（音樂公園、五權公園、忠孝國中）。","爭取育兒第三胎，補助三萬元（擔任民進黨黨團總召期間，推動成功！）。","守護行人路權，落成人行道改善計畫（漢生東路、府中商圈、板橋三民路、南雅南路）。","建立各式線上選民服務系統，承接超過萬件各類服務案件。","落成特色彩繪牆融入社區（重慶里、國泰里、民族里、華德里、信義里）。","排水系統建設／規劃（浮洲橋人行道排水改善工程、規劃僑中里污水下水道）。","推動青年局成立，完善青年政策（職涯發展、創業資源、創業空間租借）。","守哲健康｜銀髮生活：協助「老齡生活規劃」，爭取「銀髮族生活講座」。","守哲健康｜銀髮生活：清點適合的閒置空間，爭取「日間公共托老中心」。","守哲健康｜銀髮生活：守護銀髮族笑容，爭取「65歲長者免費裝假牙」。","守哲健康｜銀髮生活：促進健康，爭取銀髮族公園健體設施。","守哲健康｜銀髮生活：推動智慧照護，架設「IOT物聯網智慧照護設備」。","守哲健康｜銀髮生活：擴大敬老卡支付範圍，爭取「敬老小黃幸福車隊」。","守哲健康｜銀髮生活：推動「青銀互動社宅」，青年照顧銀髮換宿，跨世代交流社會更幸福。 守哲安心｜婦幼成長","守哲健康｜銀髮生活：盤點閒置教室，增加公共幼托數量。","守哲健康｜銀髮生活：爭取加碼新北市「育兒補助津貼」額度。","守哲健康｜銀髮生活：落實建立「校園關懷機制」反霸凌／反毒品。","守哲健康｜銀髮生活：關懷兒少，爭取「板橋高風險兒少中心」。","守哲健康｜銀髮生活：守護婦幼夜歸安全，增設「夜間感應燈」。","守哲未來｜青年發展：爭取擴大青年媒合新創產業「實習機會」。","守哲未來｜青年發展：整合自媒體產學資源，爭取「雲端自媒體中心」。","守哲未來｜青年發展：支持青年參政，完善「公共政策網路參與平台」。","守哲未來｜青年發展：爭取「發展電競產業，辦理課程培育電競人才，爭取電競從業機會」。","守哲未來｜青年發展：爭取「成家基金」津貼計劃，結婚入籍補貼10萬。","守哲未來｜青年發展：爭取「板橋第二國民運動中心／板橋自由車場地」。 守哲幸福｜動保權益","守哲未來｜青年發展：照顧毛小孩健康，推動「寵物友善健檢」。","守哲未來｜青年發展：爭取「寵物友善公園」／「寵物洗澡設施」。","守哲未來｜青年發展：推動落實「寵物友善社區評鑑」。","守哲未來｜青年發展：捍衛「動保正義」，嚴打黑心寵物繁殖場。","守哲未來｜青年發展：提升動物收容中心環境，改善軟硬體設施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"53c920f3-b93c-48c4-8397-123f7ec636fc","items":["確實監督縣政發展，謀求全縣縣民福祉。","有效活化運用金湖及金沙地區文化資產，創造全新觀光價值。","推動長者照護系統，建構社區連結服務網絡。","促使公共托育政策更臻完善，優化幼兒教育。","縮短城鄉差距，改善公共交通便捷程度。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"53ce1876-4510-4d1b-a64c-cc6e6de1f6be","items":["疼惜西嶼，打造幸福鄉里。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"53d21944-f4ac-424d-b8be-f2cd60369e3f","items":["優化國教：全面推動校園反霸凌。","前瞻高教：設立百億學生海外圓夢基金。","前瞻科技：推動數位轉型、淨零轉型，超前部署太空產業發展與AI產業布局，打造台灣成為智慧科技島。","強健體育：研議成立體育暨運動發展部。","推動長照3.0，提高長照覆蓋率，打造居家、社區、機構、醫療、社福的一體式服務。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"543407ca-983a-4db8-8f73-49121527421a","items":["認真監督縣政，嚴格為預算把關，保障納稅人的權利。","強力督促縣府確實執行鹿港國家歷史風景區計畫各項工程之完成。","積極捍衛代理教師權益，保障國家未來棟樑安心穩定的受教環境及權益。","關懷弱勢族群，爭取社會資源挹注急難救助，強化婦女及新住民福利照顧系統，提升家庭經濟力，促進社會融合。","認真督促政府推動照顧銀髮族的長照政策，落實社區照護據點設立，尊重專業人才及提升長照的品質與效率。","認真督促政府普及公共托育政策及推動社區化非營利幼兒園，協助民眾減輕育兒負擔。此外，為維持托育品質，任期會積極關心專業教保人員待遇及各項權益。","認真督促政府落實推動強勢農業，結合科技、管理與行銷，鼓勵年輕人返鄉投入農業轉型創新。","爭取加強改善福鹿秀三鄉鎮偏遠地帶農路、道路交通號誌，並加強排水系統整治，讓居民出入安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5449bde8-136a-4730-a033-28fe100cb273","items":["各項公共事務的推動，不會因為政黨的輪替而有所停滯。差別的只是在於，執政的人有沒有用心、有效率的推動各項縣政建設。彰化很好，有富含文化的傳統底蘊、有隱形冠軍的中小企業、有多樣豐富物產的農業生產、有各行各業的優質勞動力。我們要做的，是如何有效整合行政效能，讓原本的彰化優勢發光發熱。","彰化，可以更好；陞漢相信，彰化可以大步向前走！","未來，陞漢將持續在「優化教育環境」、「催化基礎建設」、「提升產業環境」、「落實有效福利」等四個面向上努力，促成縣政府訂定相關的施政方針。","優化教育環境：陞漢於108.2首倡國中小減人不減班，終促成111學年度開始，國中小班級人數減少1人。希望降低師生比，減少優質教師流失。未來朝向促成國中小每班再減少2人方向努力。並檢討教育資源分配，提升教安品質，留住彰化好人才。","催化基礎建設：要求針對重大民生基礎建設－火葬場、市民廣場、公共托育與托嬰、社會住宅、藝文展演中心、一鄉鎮一全齡公園、流浪動物收容所等提出具體方案。","提升產業環境：田園工廠轉型面臨問題、產業用地與開發問題、觀光產業提升與能見度、老農保障與青農發展、優化各項行政申辦程序等持續監督縣府作為。","落實有效福利：針對老弱婦孺等福利措施，檢討非法定福利的浪費，有效落實把資源給有需要的人、臨時急難的人。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","candidate_introduction"]}}},{"claim_id":"5472f073-49b6-4463-bca5-b50ff9730262","items":["聽取地方人民之聲音，並兼顧弱勢族群之需求，有效分配社會資源，使有限資源足以發揮最大效能，同時積極推廣公益，促進社會服務活動，發揚民間互助力量。","推廣農業發展，保障農民權利，並改善農民生活，讓農業重現生機。","提倡運動休閒活動，以發揚體育精神，並落實體育之相關政策。","推廣宗教相關之節慶活動，結合文化與觀光，發展在地文化特色，以發揚宗教文化，讓傳統宗教的景致與內涵得永續發展。","推廣在地特色文化，打造文化創意的觀光產業，與在地企業合作徵才，促進地方就業發展，以達雙贏的成效。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"54bec2b7-9680-4bb7-a44f-bc942bfa69bc","items":["爭取提高教育預算比例，充實改善教學環境設備，提昇教育品質與孩子的競爭力。","爭取國中、小提高教師編制，因應少子女化的來臨，維護教師權益保障學生學習品質。","爭取文化與教育結合，督促、建議縣政府由教育著手，向下紮根，佐以觀光宣傳，傳承在地文化，爭取文化預算，提昇居民文化素質。","爭取擴大農、漁產業保險，推動落實補助農民職業災害保險。","積極爭取經費，整治區域內排水系統及農水路道路改善工程。","配合政府積極行銷農產、養殖漁產品，以利產業發展。","督促政府強化協助、補助及關照弱勢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"54cf673e-03be-4b8c-a58c-737121e48d66","items":["積極傾聽民意 爭取地方建設：關懷弱勢團體 協助爭取補助","積極傾聽民意 爭取地方建設：推動長照政策 健全樂齡服務","積極傾聽民意 爭取地方建設：推動婦幼政策 生產教育補貼","積極傾聽民意 爭取地方建設：強化農業政策 改善灌溉溝渠","積極傾聽民意 爭取地方建設：保障警消人員 值勤安全權益"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5586ff8b-68f8-4a93-b4f0-d8ed607ff80b","items":["參選政見：理性問政、推動建設、監督縣政、公益社會、服務人群！","監督台東縣政府，嚴格審查縣政預算，杜絕浪費公帑！","監督台東縣政府，替人民把關施政工作，導正錯誤政策！","挺身為民意發聲，反映人民心聲及訴求，積極解決縣民問題！","推動友善托育環境，增設公共托育中心，減少年輕父母負擔！","重視兒童遊戲權，持續推動興建兒童遊樂設施，營造友善遊戲環境！","鼓勵辦理民俗文化活動，爭取擴大宗教慶典盛會！","監督焚化爐，落實垃圾分類，推動垃圾減量乾淨家園！","推動地方建設發展，爭取規劃台東市區停車空間。","督促教育發展多元化，提升學校設施設備與教學環境！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"55f51e02-3d16-4750-a073-e0d20670a4bc","items":["爭取城市運動環境、提供市民健康好生活。","關懷婦幼權益、推動平價托育、長照2.0推動成效。","爭取台中捷運藍與橘線、YouBike微笑單車設站、興建停車場。","支持全民體育，爭取新建足球場地、監督運動場館更新維護。","要求勞保年金設樓地板、保障勞工權益。","關心並建議解決高房價、物價通膨與勞工低薪問題。","監督食品安全，爭取國中小營養午餐補助增加5元。","爭取公立幼兒園、托兒所倍增地點。","爭取警消工作裝備，支持警械使用條例修法，強化執勤安全。","爭取筏子溪週邊整治，兩岸綠化藍帶，檢討都市計畫。","爭取觀光旅宿產業行銷補助，輔導數位轉型升級。","爭取教育資源補助，新建或汰換學校軟硬體設備。","爭取興建里活動中心、西大墩低碳環保館、福科增建校舍等工程","爭取市政路延伸、環中路二段1036巷道路拓寬等工程","爭取復康巴士汰舊換新、新增消防排煙車。","監督能源政策、穩定民生電價。","監督臺中火力發電廠排放PM2.5數值透明化，還給市民好空氣。","監督中科排放廢氣、廢水，符合環保標準。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"55fcf74a-633c-424d-8860-7af67cc0853e","items":["爭取縣府經費修補道路、架設照明監控設備，改善交通品質維護治安。","重視偏鄉地區教育，充實教學設備，改善學習環境提昇教育品質。","督促縣府推廣農產品產銷制度管道，有效增加農民收入。","推動社區民眾職能訓練、多元技能學習，關懷據點之設置。","關懷弱勢族群、加強婦幼、新住民、中低收入戶及邊緣戶之照顧。","督促縣府積極發展觀光休閒產業，活絡地方繁榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5628ec60-d142-4dc4-9f9c-49164061e7f0","items":["全面推動公托公幼。","提升生育提高補助。","極力推動幼教政策。","積極落實竹東綠肺。","推動老人關懷據點。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5640c190-811e-4eea-9266-e23730ba9b3a","items":["積極推動主管原住民事務為一級單位，升級為原民處。","賡續爭取設置都會區原住民服務中心，提供文化健康站、原住民家庭服務中心事務，辦理文化、會議、語言、活動、教學及課後輔導。","繼續推動在原鄉及都會區廣設文化健康站，守護原住民族長者健康，結合在地文化傳承，深化服務品質。","推動原住民族語訓用合一，鼓勵族人參加專職原住民族語老師甄選，加入原住民語教學與傳習。","設置法律服務平台，依專案申請免費律師協助法律諮詢、法律文件撰寫及訴訟代理。","設置產業平台，結合都會區文創產業、部落農產業及休閒產業，打造原住民族產業鏈。","推動自主製作部落地圖，劃設原本生活空間，包括部落所在地、獵（漁）場、耕地與聖地。","積極爭取原住民部落基礎建設，打造安全、安心的生活場域。","永續推動修憲取消「平地原住民、山地原住民」之分，打破原住民族二分法政策，以求公義。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"56a6e215-4ad6-40f5-87c9-d98b3fc4885b","items":["「爭取興建輕軌建設、完善嘉義交通網絡」：將高鐵與台鐵串連成路網，嘉義高鐵站至市中心輕軌交通，提供更便捷的大眾運輸。","「完善教育環境」：爭取嘉義市圖書總館興建，提升嘉義市文教環境品質；爭取經費改善各級學校設施設備，營造優良成長學習環境。","「推動樂齡家園、守護醫療長照社福」：強化對長者於居家、社區、機構、醫療與社福機構照顧；爭取擴大嘉義醫療服務量能。","「完備托育量能」：爭取經費加強托育體系，提升公托量能。","「爭取更新民生設施」：電纜電線全面地下化、老舊自來水管汰換，提高生活品質。","「文化觀光振興」：完善商圈發展，強化嘉義整體觀光量能、提升歷史建築的文化價值。","「完成建設地方」：持續爭取降低鐵路高架化地方配合款，爭取中央提高補助比例；解決交通困境，爭取新建停車場。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"56c6ec6e-74aa-4f4d-83a7-cdd5d09d9c1d","items":["2050碳中和 監督市府碳中和計畫，嚴格要求市府以身作則，作為典範。加速推動大眾運輸與私人車電動化。 推動農業達成「碳中和」，並轉型為碳權產業，增加附加價值，與企業互利互助，提供碳權交易，促使農民、企業、生態三贏的契機。","智慧交通 全面盤點、改善不合時宜的用路環境。推動合適路口機車左轉，支持用路平權。 推動捷運、輕軌、公車大眾運輸路網整合與改善，朝人本交通方向邁進。","智慧醫療 推動智慧照護中心與社區視訊診所，省時省力又安心。","安心生養 推動以容積獎勵為誘因，鼓勵建商提供空間作為社福公益使用，達成「取之於社會，用之於社會」之精神。 完善社會長照、日照、托兒服務，並推動資源整合，減少社會成本的浪費。","雙語教育 完善雙語教育，增加雙語外師，培養學生語言能力。","上下學平安 推動學校周圍增設科技執法，減少導護志工人力，「開心上下學、平安接送」。","鳳山中城 推動東高雄發展，打造高雄中城計畫，市府整合遷鳳山，節省行政成本。","鳳山智慧之心 推動五甲路以東作為碳中和未來經濟區，結合無人車、智慧號誌、智慧消防、綠能建設、智慧照護、智慧醫療，創造出未來城市的模樣。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"572ddcd4-8699-4d7b-8f6e-20850a679232","items":["村里幫手：協助各村里社區申請水溝清淤、環境消毒及設備爭取。","解決淹水：爭取易淹水地區全面性評估改善方案。","照顧長者：持續推動長照政策，繼續爭取相關福利經費。","關懷弱勢：關懷新住民、弱勢族群，協助社福資源連結。","醫療升級：爭取設立「衛生福利部東石醫院」，普及偏鄉醫療照護。","推廣藝文：培育本縣優秀藝文人才，爭取故宮南院藝文資源連結。","創生共榮：持續推動觀光軸線發展，扶持地方創生，帶動社區復甦。","守護治安：強化居家治安品質，全力爭取社區監視器設備。","活絡農村：改善農漁民生活環境，推動精緻優質農漁產業。","照顧漁民：爭取漁港建設經費，充實養殖漁業生產區健全發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"572f8ba0-21a3-4042-890b-3f73fa8ce3b2","items":["農產加值：打通南投茶葉、農特產外銷兩岸與國際綠色通道；建立「Made in Nantou」標章 多元族群：制定《眷村文化保存法》活化眷村聚落；推動成立新住民委員會保障權益福利 交通建設：完善南投對外交通網；推動台中捷運延伸至南投；推動竹山二水東西向快速道路 育幼升級：推動凍卵補助；保障婦女生育選擇權；公立幼兒園免費、私立補助每人每月1萬元 青年新創：發展國際數位游牧聚落，增設簽證辦法吸引國際人才與青年從投創業 健全長照：落實65歲以上長輩免健保；推動巴氏量表改革；減輕長照者家庭負擔 強化觀光：推動太極美地計畫；增設台中機場國外航線；積極開創藍海市場 投資教育：推動「營養午餐專法」；改善教育「不山不市」資源落差問題 優化醫療：推動遠距醫療服務；引入小兒科急重症專責醫院到南投"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"57865b2a-44b5-41de-a1bb-1def20ee85c4","items":["力促六堆文創環境，發展地方特色，行銷亮點。","督促縣政府福利政策，建立完整社會福利安心網。","協助傳統農業升級，提高農民收益。","爭取路口增設監視器，以維社會治安。","傾聽民意，加強服務，監督縣政，為民喉舌。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"57a6a746-f538-43c5-9bd9-5eddab96966e","items":["爭取建置南庄汙水處理廠,改善中港溪鄉親用水的品質及衛生問題。","爭取興建全功能市民健康休閒中心及全新圖文資訊閱聽中心,為鄉親營造高品質生活環境。","建構頭份便利行路網,擴大北台三強城市生活圈往頭份延伸,推動中山高五楊高架延伸至造橋。","活化頭份建國親子花市,推動市集活動及配合農會推動茶、梨、橘、蜂蜜等頭份特色產業加值品牌行銷。","爭取中央開闢頭份第二交流道,解決頭份市區交通阻塞問題。","全面補強警政市區監視系統,連線整合設置、維護全市鄰里巷弄監視系統,全天候保護市民通行、居住及財產安全。","輔導公私立托育機構,全面監督並提升幼兒照顧保護專業水準,協助分擔年輕父母育兒辛勞。","爭取補助各村里、社區、社團建設與活動經費,充分重視基層民眾對鄰里、社區生活環境、建設改善的心聲,藉由社區活動辦理,展現關愛鄰里、社區的參與推動活力。","照顧新住民及補助弱勢團體。配合中央推動長照政策,照顧銀髮族長者。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"57bd4e46-7d15-4aa3-ab80-568780446275","items":["鹿港、福興、秀水，需要你我一同＃拚未來 正派做事，活化地方，勇敢代言交給＃新世代","〖一〗督促縣府完整規劃促進地方經濟方案，改善傳統市場環境，活絡市場、夜市商圈。 〖二〗爭取青年創業後盾加碼補助，支持年輕人發揮創意參與文創產業。 〖三〗簡化青年創業輔導及補助申請程序，力挺青年留鄉、返鄉扎根。 〖四〗推動特色公園，淘汰老舊罐頭設施，將共融式遊戲場引進公園，催生活化地方景觀。 〖五〗監督及檢討不合宜及不符人本之交通設計，實現以人為本的交通願景。 〖六〗爭取公共閒置空間盤點，藉此活化社區、青創及幼托據點，打造多元並符合地方特色需求空間。 〖七〗改善弱勢困境，簡化弱勢邊緣戶及特境家庭通報程序，深耕基層為人民發聲。 〖八〗守護生活環境、推動文化傳承，以歷史人文為本，推廣福鹿秀地區三百年發展的人文價值。 〖九〗議會透明監督，堅持行使議員的監督職責，堅守民主信念，捍衛進步價值，清廉、勤政、愛鄉土。","『傾聽』及『說明』才能成為稱職的代議士橋梁，未來將在充分溝通的基礎下推動以上工作。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"57ca9276-b734-4362-9b29-09b5daf4921d","items":["支持18歲公民權利，修憲複決案投票贊成。","守護基層民意，拚新莊再發展。","完成新莊設置新北轉運站，讓新北真正升格成為交通便利城市。","推動道路交通平權，爭取機車族權益。","精進友善動物及保護樹木法案。","要求南新莊地區規劃中運量捷運路網。","督促環狀捷運第二階段早日施工通車。","推動市區連結捷運站免費接駁公車、增加公共交通運輸便捷性。","增建公有停車場，要求公有收費停車場降低夜間收費，解決市民停車問題。","儘速完成台65快速道路高架直接連接上國一高速公路，解決新五路塞車問題。","確保基層民生經濟，落實政府照顧基層市民政策。","友善社團發展環境讓民間活力展現。","創造青年就業、創業有利環境，給青年有展現抱負未來。","爭取成立運動局。","督促市政府興建2萬戶社會青年住宅，並推動補助青年成家基金10萬。","爭取新北市公托幼幼班倍增，讓新北的年輕人敢婚能養。","提昇學校教育內涵品質，提供學生適性教育環境，減輕學生及家長壓力。","新莊第一公墓(墓六)完成遷葬及規劃興建為特色森林公園。","爭取補助65歲長輩裝假牙。","推動普及社區高齡關懷中心及長照體系。","盡速完成台灣電影文化中心整體建設，讓新莊成為國際優秀電影人才中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"57fc06f2-566e-420b-b2d7-60a1988251e0","items":["秉持清廉問政，專職為民服務，真實反映民意，堅守民代職責。","全力配合市府向中央極力爭取建設經費，俾促地方發展、繁榮、進步，建構幸福城市。","督促市府社會福利優先，妥善照顧老人、嬰兒兒童、婦女、勞工、攤販、身心障礙弱勢族群權益。","督促市府從寬編列教育文化預算、改善師資、設備、環境，及早落實小班教學，提升教學品質及加強文化資產的保存維護。","督促市府重視學生受教育權及教師尊嚴與福利權益。","督促市府盡速闢建全市八米計畫道路巷道，以利人車通行，俾以保障市民生命財產安全。","督促市府加強治安、消防維護，充實警察、消防器材及配備，普設監視系統，以提高破案率，建構安全城市。","督促市府加強與鄰近縣市觀光資源結合，提高觀光產業，建構對外交通網路，打造嘉義市為雲嘉南觀光休閒旅遊中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"58078a2d-5ac6-44da-a298-75ab7daf4365","items":["為民眾把關","縣離島觀光產業發展","縣離島醫療進步"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"58a112db-876d-434d-b3f2-f29c9ababbe8","items":["督促縣政府重視在地原住民文化特色並落實保存傳承之工作，強化台東原民重鎮之價值。","建議並督促縣政府將原民部落旅遊列為本縣慢經濟政策之發展重點，以促進原鄉經濟發展。","督促縣政府落實原住民族基本法第21條之諮商同意參與權。","為因應後疫情時代帶來之社會變化及衝擊，督促縣政府妥善規劃各項輔導機制，改善縣民生活。","督促縣政府增編經費加強原住民地區基礎建設促進地方發展。","督促縣政府重視偏鄉教育，改善教育設施，提供完善師資，提升學生學力，縮減城鄉差距。","督促縣政府改善偏鄉醫療設施，增編醫療專業人員，充實偏鄉醫療資源，維護縣民健康。","督促縣政府落實長照安養社會福利措施，使縣民老有所終、廢疾者皆有所養。","為因應極端氣候，督促縣政府加強防災措施並強化防災設施，落實防災演習以保障縣民生命及財產之安全。","督促縣府重視環境保護工作，加強環境污染防治措施，推動綠美化，營造健康友善之樂活大縣。","督促縣府重視交通管理措施並改善相關設施，以保障縣民行的安全。","督促縣府強化各地警政措施，維護地方治安，以保障縣民生活安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"58a833da-4574-48dd-9630-d0b6d8bc27e0","items":["帶動各項藝文活動，結合地方公益，提升雲林人文氣息。","重視新住民教育，協助弱勢學童，縮短城鄉教育資源的差距。","推動婦女積極參與社會公益及各項活動，提升婦女的社交能力及地位。","爭取各項補助，協助社會邊緣戶，創造就業機會。","關懷獨居老人，重視日照長照品質，提供給長輩一個好的生活品質與環境。","爭取地方各項建設經費，建立花園城市遠景。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"58e103a4-97ab-4d9f-b07a-f5187b777cc6","items":["爭取開闢龍潭區湧光路沿自由街、工二路、龍平路橫向外環道，以提升交通便捷。","繼續爭取設置龍潭公車轉運站，以方便乘客轉乘。","繼續爭取機場捷運由中壢延伸平鎮至龍潭，以帶動區域性發展。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"59423029-9a5e-4a08-aed3-5ba108b5e58c","items":["落實「高雄表參道計畫」,再打造再繁榮火車站附近特色商圈。","督促高雄捷運黃線儘速完工,並減低施工交通黑暗期負面影響。","加速高雄肉品市場、三民街友服務中心遷移,並有效開發原址。","擴大鐵路地下化後綠園道多元化功能,加強觀光、休憩等功能。","透過都市更新,規劃三民區為連貫大高雄南北經濟重要新樞紐。","中都已經有第二美術館園區之稱,中都磚窯場應配合當地發展。","持續督促降低路邊停車收費,透過減少收費等,減輕民眾負擔。","高雄進入老年化時代,推動長照專業人員培訓,好好照顧長輩。","增添公托中心數目,讓年輕夫妻不用碰運氣抽籤,無後顧之憂。","建構三民區為智慧城市,透過網路讓衣食住行娛樂等更為便捷。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"59c3da7a-1574-4766-aad7-4ed114cc2db7","items":["教育資源需求提升（幼兒～高中職）","醫療量能修正及救災救護效率提升","爭取親子與社區共讀共融新鎮立圖書館","爭取改善放寬嬰幼童與老人津貼發放條件","現有道路規劃重視與強化學童安全步道","以科技協助治安有效性改善","強化公園綠地環境與安全：弱勢團體協助與輔導"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5a32e905-8014-4b38-b0f5-b09d7a35e766","items":["積極爭取跨曾文溪橋防止溪北邊緣化，打進南科生活圈，將工業區跟工業區串聯起來，帶動附近就業人口，跟整個食衣住行的產業鏈發展。","持續推動：爭取台南市六十五歲以上長者健保費補助與其他五都平等待遇。","爭取大北門區之農水路更新改善工程及農路建設加速推動，保障農民權益。","持續推動宗教廟宇傳統文化資產的傳承與保存。","推廣大北門沿海地區漁港及潟湖觀光旅遊結合在地美食文化。","督促及爭取市府建構完善社會福利，照顧長者幼者、保障弱勢團體。","持續監督落實水患改善工程，解決鄉親水患之苦。","爭取增設佳里多功能使用會館，以提升市民生活品質。","爭取建置西港親子悠遊館，讓空間作最大的活用。","推動藝文活動舉辦，提升參與欣賞藝術的機會，以提升居民生活品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5aaa77bb-5dbc-4719-a429-f78393429609","items":["提高行政效率，爭取地方建設。","實長照福利，照顧老人。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5ac621da-e0c7-4e1e-9987-8b609da725a8","items":["促進大湖西觀光園區，將湖西荷塘、湖東荸薺窟、青螺濕地國寶級紅樹林公園、北寮奎壁山、菓葉日出、龍門鼓浪、林投公園、隘門金沙灘，串連成一條觀光動線，帶動大湖西商機。","開發湖東村湖西村之船頭尾為滯洪池，達成蓄水保持原始生態，避免天然災害。","活化湖西鄉農業區廢耕地，帶動強化農產品復育及一村一特色。","汰換湖西各社區路燈、木桿、架空線路燈改為線路地下化，並朝設置FRP燈桿及LED路燈等照明設施，以達成安全、美化、環保、省電效率。","汰舊換新湖西鄉各社區自來水飲用管線，確保飲用水質安全，維護鄉親身心權益。","規劃建設湖西鄉各社區污水下水道，經污水處理場完成淨化後，藉以灌溉農作物，餘水排放大海，以維持潔淨海底生態。","強化社會福利措施，照護弱勢族群。","爭取上級經費，多元行銷湖西鄉，提高知名度與能見度。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5ada5399-91af-4cc3-bbaa-a92c0a686125","items":["完善大眾運輸機制，友善安全用路環境","強力監督市政預算，杜絕貪婪瀆職歪風","蓬勃市場夜市商圈，帶動地區觀光發展","支持性別平權觀念，多元台北友善城市","爭取警政消防福利，落實台北居住安全","補足醫療衛生措施，提高台北環境品質","全力推動都市更新，重塑台北城市美學","鞭策公共建設品質，落實臺北宜居城市"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5ae6ebb3-218c-4eae-8d5c-714f7fdd5606","items":["加速地方重建","爭取凍卵補助","落實淨零碳排","托育設施倍增","雙語教育到位","爭取寵物疫苗"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"5b3b8b6e-bb45-4ce3-84e6-9d213297409e","items":["擴大青年就業：輔導族人創業，推廣原鄉文化及產業行銷，改善收入，職訓補助加成，協助族人發展第二專長，增加媒合工作機會。","加碼福利照顧：擴大辦理租屋媒合、補貼，提升居住品質落實居住正義，爭取各項生活補助隨物價指數調整，擴大育兒、長者醫療補貼，落實原住民族基本法保障。","優化銀髮長照：耆老服務據點社區化，增加休閒娛樂、提高共餐品質，結合衛生局辦理健康衛教、4 大癌篩。","傳承原鄉族語：族語老師分級補貼鐘點費，補足16 族族語教學師資，讓原住民族子弟母語教學、傳承不中斷，健全族語學習環境，提高族語認證獎勵金。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5b60a602-797b-415d-b9d3-7d8bfb7393ca","items":["社會福利相照應 ．鼓勵各區增設日間長照據點，發展老幼共學友善環境。 ．推動食物銀行增設健康檢查服務，吃得開心，身體也安心。 ．爭取65歲以上老人健保持續補助。 ．爭取全面補助公費HPV疫苗施打。","在地文化出頭天 ．爭取補助計畫扶植在地藝文團體，當地傳統文化被看見。 ．推動中部流行音樂中心在烏日，台中音樂人在地出頭天。 ．推廣食農教育結合地區農業，農業文化不遺忘。","交通建設再升級 ．強力爭取臺74線延伸龍井（生活圈四號線大肚段）銜接臺61線西濱快速道路。 ．密集增設YouBike站點、增加小黃公車班次並深入服務。 ．加速住宅密集區電線桿地下化，擴大污水下水道接管範圍。","社區好發展好生活 ．串接新住民家庭和在地資源，促進多元共好新生活。 ．推廣寵物友善公園，毛小孩出門活動煩惱少。 ．推動中小學閒置空間增設公托場域，建構育兒友善環境。","繁榮烏日再進化 ．加速烏日鐵路高架，打通建國南路，捷運綠線延伸彰化。 ．督促成功西路（75-1）道路拓寬工程一期動工、二期儘速核定。 ．推動烏溪、筏子溪水岸公園，實現幸福生態城市。","光耀大肚大翻新 ．督促大肚-和美大橋加速完工。 ．持續推廣大肚王朝歷史文化與下堡媽祖巡廿庄文化季。 ．推動大肚各健康步道串連整合，實現居民山中相會。","大肚台地要革新 ．推動規劃大肚山上第一座全民運動中心計畫。 ．爭取新庄子蔗蔀地區都市計畫納入捷運藍線「坪頂站」及「捷運社宅」規劃。 ．推動大肚山小黃公車串連YouBike電動自行車。","樂活龍井創繁榮 ．推動串連龍井區內自行車道，騎乘體驗更完善。 ．促進活化公有市場，創造產銷新空間。 ．爭取解編台中港特定區，促進國土有效利用，共榮發展地方新生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5b681400-ed7a-4ee8-9555-572e812c27b6","items":["守護主權、堅持民主 : 全力推動相關政策及修法,維護台灣主和體性與民主價值。","農業升級、保障農民 : 完善農業加工體系 ,有效運用穩定產銷 ; 促成冷鏈物流中心,沙腳鄰近農業產地 ; 促進農產多元內銷,拓展農產外銷通路。","照顧銀髮、推動長照3.0 : 爭取增加長照預算,促進高齡樂活,推動優質平價長照體系,健全社區關懷據點,提升機構式照顧品質與環境。","教育優化、投資未來:推動學費補助方案,私立大學費補助 3.5 萬、高中職全免學費 ; 爭取經費整建老舊校舍、操場、廁所,優化教學環境、縮短城鄉教學差距。","防洪治水、普及自來水:持續爭取補助防洪治水、河川整治經費,打造市民親水環境,持續推動無自來水地區延管計畫,提高自來水普及 ©","交通優化、觀光升級 : 爭取重要交通建設經費,並結合農村再生,運用在地觀光自然資源,配合地方民俗節慶活動,推動深度觀光旅遊,帶動地方發展。","友善婦幼,敢生好養 :提高公共化托嬰托兒比例,沙實婦幼福利,減輕育兒負擔。","推動再生醫療法立法、維護病人權益 :確保再生醫療品質與安全,提供病患更多治療選擇,並促進生技產業發展。","支持在地優質好米地產地消 : 推動學校營養午餐使用在地優質米,減少食物運送里程。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"5bda03ae-f1cf-425b-aa07-79ed2c65483b","items":["請給我一次機會，讓我用青年的戰鬥力，來為族人發聲！","常覺得立法委員總是遠在天邊嗎？ 還是覺得政治很遙遠，立委又能改變什麼？ 其實我們所有的生活，都跟法律與政治息息相關。","說是永久屋，土地卻不是我們的？什麼時候山林能還給部落自己管理？ 想用安全的獵槍卻不合法？什麼時候狩獵不用再偷偷摸摸？ 現在都什麼年代了，從學校到社會卻處處是歧視？ 他們說原住民族的語言是國家語言，身分證卻不能單列族語名？ 要求台大歸還馬遠部落丹社群布農祖先遺骨並賠償，他們說沒有法源依據，還罵族人貪婪？ 這麼多我們共同經歷的痛，需要積極修法才有機會改變。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"5c29847a-a439-4285-b046-de6400af9578","items":["【推動透明政府、監督縣政議政】-持續要求資訊公開、落實公民參政權利","【詳審預算決算、看緊人民荷包】-督促落實財政紀律、減少預算浮濫支出","【善用在地資源、島鄉永續發展】-堅持守護公有資產、續推閒置資源利用","【強化醫療能量、厚植文化教育】-促進醫療在地生根、發展優質地方國教","【提倡多元產業、獎助青年回流】-倡議金酒多角經營、傳統產業體質升級","【觀光產業轉型、打造優勢環境】-優化觀光旅遊品質、創造金門島嶼優勢"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"5c50aed9-ea2a-403b-be8e-cc9f12c92b5c","items":["課後托育：單親喘息照顧 行有處所","課後托育：改善74號匝道堵塞 浪有所歸","課後托育：爭取毛孩絕育補助預算增加 居有定所","課後托育：爭取社宅租金平價化"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":11,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5c80fc07-7bb4-47da-8c2d-ae309d157840","items":["「托嬰托幼」及「學前教育」：補助加碼。","試辦「全日臨時托嬰托幼服務」：爭取從桃園區開始。","快樂的學習環境：發放「校外學習券」，補助兒童到校外合法場域多元學習。","建設：推動都市計畫整併：檢討前後站與東西區交通壅塞區域，均衡地區發展。","建設：公共運輸友善城市：強化市區公車與城際通勤路網。","建設：升級市府生活圈：推動市政園區原址重建，帶動市府生活圈發展。","生活：人行環境優化：完善學童通學廊道，及捷運綠線車站至商圈廊道。","生活：醫療資源智慧化：串聯榮民醫院、敏盛醫院及部立桃園醫院，讓市民安心就醫。","生活：桃園煉油廠熄燈：結合殯葬園區公園化及虎頭山園區，升級大檜溪生活區。","生活：寵物友善城市：獎勵寵物友善餐廳，增建公營寵物專屬游泳池。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5c813b7d-a52b-45fe-a65c-3e71aac2461b","items":["整治現有溪道，美綠化兩岸為都會親水公園，做為居民休憩場所。","爭取公立小學增設公托幼兒場所，以減輕年青家長負擔，提升年青人生育意願。","督促加速污、雨、水道施作進度，以利徹底解決安南區水患。","建請市府統籌產、經、學、推廣安南區精緻農、漁業發展，提升農漁民經濟附加價值。","力促安南區外塭屠宰場之遷移，以利該區域之整體發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5c9585d9-1597-4b5b-9a53-ed62994a2ef0","items":["好建設：推動平鎮大車站，帶動平鎮發展。","好建設：推動板龍快速道路，快速連結新北與桃園。","好建設：推動新梅龍（新屋－楊梅－龍潭）快速道路，橫向運輸更方便。","好建設：推動平鎮與龍潭公車轉運站，強化公眾運輸。","好建設：設置桃園公共聯合醫院體系（平鎮、龍潭設置公立醫院）。","好教育：持續爭取教育部經費，改善高中、國中及小學校舍並強化設備。","好教育：爭取提高教師薪資加給，吸引優秀人才投身教育。","好教育：賡續推動設立公共化幼兒園與公托中心。","好教育：爭取桃園設置公立兒童專科醫院。","好教育：2－5歲公立幼兒園免學費，私立一學期學費補助4萬元。","好教育：12歲以下孩童發放家庭照顧津貼1萬元。 好長照","好教育：申請家庭看護移工，免繳每月2,000元就業安定費。","好教育：75歲以上長者，領長照津貼每月3,000元。","好教育：65歲以上長者免繳健保費，政府全額補助。","好文化：推動龍岡、龍潭設軍事文化館。","好文化：推動客家博物館，發展客家文化。","好農業：提高青農貸款額度，享有7年免利息補貼。","好農業：提高公糧收購價每公斤2元。","好農業：爭取農民每戶每年50,000元小型農機補助。 好社區","好農業：義警、義消、守望相助隊提供協勤津貼。","好農業：推動兒童共融遊戲場與寵物公園。","好農業：賡續推動電纜地下化、自來水管汰換。 好勞工","好農業：強化雇主投保責任，受雇員工4人以下之企業，強制雇主為受雇者投保勞保和就業保險。","好農業：推動勞工住宅，年所得60萬以下／夫妻合併所得120萬以下優先入住。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5cd8d03b-0777-4a1f-8f60-1196d8c25c0e","items":["交通建設：監督淡北道路儘速動工","交通建設：推動淡海輕軌延伸至八里及三芝","交通建設：監督淡江大橋如期完工","交通建設：持續爭取開通新市一路二段及新市三路二段","交通建設：爭取YouBike站點普設完善通勤網絡","安居生活：爭取增設公共托育服務","安居生活：爭取各項銀髮安養機制","安居生活：分期施作汙水下水道系統","安居生活：積極推動都市更新","安居生活：積極增設休閒公園及運動球場","教育文化：持續提升學校軟硬體優化更新","教育文化：持續深化有形、無形文化資產保存","教育文化：推動在地文化及觀光活動整合促進發展","教育文化：推動AI課程語言課程入校","區域規劃：推動規劃新北市政府北海岸辦公室","區域規劃：持續爭取設置淡海科技園區","區域規劃：推動八里產業專區發展建設","區域規劃：監督沙崙文創園區並推動周邊發展","繁榮淡水：完善淡海新市鎮生活機能，爭取現代化市場、圖書館、實驗中學、運動及寵物公園等","繁榮淡水：輔導推動有機農業保障在地小農產銷權益","繁榮淡水：落實水碓生活商圈行車、停車、徒步區分離","繁榮淡水：爭取新市國小旁設置北海岸公車轉乘站","樂活八里：爭取觀音山觀光纜車，整合淡水河口兩岸觀光資源","樂活八里：堅決反對在八里區內設置任何嫌惡性設施","樂活八里：八仙樂園周邊國有地結合自行車道為生態自然系公園","樂活八里：爭取微型運動中心、醫療機構、八里國中遷校","宜居三芝：擴大農民權益保障，完善小農產銷制度，爭取天災農業損害補貼加碼","宜居三芝：增設公園裝置藝術，三芝藝術家參與設計公共裝置藝術，提升生活品質","宜居三芝：提升觀光行銷，爭取三芝各海濱風景區舉辦特色活動","觀光石門：爭取於石門各海濱風景區定期辦理特色活動","觀光石門：積極行銷石門三寶(鐵觀音、肉粽、石花凍)","觀光石門：爭取核電廠電力開發協助金以外之專案回饋款"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"5d28ac8a-f0dc-42a0-8fca-024e0628f815","items":["我承諾：專業問政、監督不分黨派、不貪不取、全力為百姓發聲。","我堅定：支持 18 歲公民權，守護嘉義、愛台灣！","我專業：用心監督縣政、嚴格審查預算，避免縣府濫用公帑、使財政持續惡化。","我用心：督促嘉義縣各產業園區之開發，增加就業機會、協助青年返鄉，推動地方創生。","我守護：老弱婦孺殘障人士之權益，督促縣府加速長照服務的普及，健全公共托育保母系統、營造良好育兒環境，讓父母安心生養。","我要求：嘉義縣政府依據都市發展需要及實際發展情況、參考人民建議，加速進行各鄉鎮都市計畫通盤檢討，增加土地利用價值。","我爭取：水上鄉鐵路高架化，解決交通壅塞；活化水上機場並建構完善的聯外道路，促使觀光交通更便利。","我堅持：善用本縣優勢資源、結合本土文化特色，促使嘉義成為國際友善觀光農業大縣。","我推動：公私合力針對空氣、水環境污染物之稽查，加強取締地下工廠、違法開發、不法排放廢水、污水、廢氣和非法棄置固體廢棄物。","我捍衛：軍公教警的尊嚴和權益，爭取教育經費充分編列、提升學童就學品質、充實義警消裝備，保障其生命財產安全。","琬蓁八年來的專業認真，值得您用選票再次支持連任肯定！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5e0039fe-beff-4928-b9b8-e9ae7a89f77b","items":["強力要求文山焚化爐新廠，必須通過環境評估，否則文山焚化爐年限到期後必須遷移至適當處。嚴格把關南屯的空氣要換新。建議文山掩埋場第零期約十公頃(環評法未通過時期掩理區域)，清除掩埋物後，規劃為綠美化公園提供民眾休憩場所。","強烈要求臺中市政府關閉南屯水肥廠，惡臭源頭不應該在密集的住宅區，應該加速家戶汙水接管率，統一將惡水排入水資源處理廠，還給居民宜居的家園。","積極爭取公共停車空間，改善停車問題，增設公共運輸站讓交通網絡更便捷。","爭取鐵路高架化銜接大慶站與烏日站三鐵共構。","爭取臺中市國中小營養午餐免費，營養加倍。社宅倍增，青創加值。長照樂齡社區化。","督促市府除了加強筏子溪、麻園頭溪、南屯溪水患整治外，應規劃串連自行車道及親水公園。","嚴格監督路平及整平效率，保障用路人及駕駛人的安全。打造友善的寵物空問·適當的規劃寵物運動公園。","爭取南屯區精密園區精科路打通至永春南路，中台路(培德路至台貿路)拓寬，同安坑厝幹線排水北側15公尺道路開闢(忠勇路至台貿路)。改善溪西地區交通瓶頸。","要求優先建構【臺中市數位線上遺址博物館】，比照國立故宮博物院數位典藏，因應未來數位網站博物館發展趨勢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"5e1ba257-c668-40d0-b5d6-c05e1247ae71","items":["協助汰換警義消人員老舊設備，確保警消出勤更安全的保障。","全面檢視警民連線及各重要路口監視系統，協助更新軟硬體設備。","積極推動臺東縣的水域運動，山難救護培訓，更新救難救護設備。","健全志工體制，加強維護臺東環境，以增加觀光人潮。","協調各單位及部門達成共識訂立元宵民俗活動自治條例，讓臺東傳統文化得以永續傳承，並且獲多數民眾支持共同為觀光、傳承而努力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5ea3f618-d417-4813-a50a-d6c1bfca193e","items":["1 爭取加速建置公共托嬰中心，讓育兒更輕鬆，托嬰更安心，公共托嬰不再抽籤一位難求。","2 爭取112年起於三年內完成65歲以上長者健保費全額補助。","3 爭取於各行政區，加速建造社會住宅，讓年輕人居住更安心，成家更輕鬆。","4 督促加速南科（善化、新市）-新化-高鐵捷運（深綠線）路線規劃，並於臺南市先進運輸系統中優先建置本路線。","5 督促鐵路立體化北延工程：永康-新市-善化儘速完成規劃建置。","6 爭取建造南科地區大型醫療機構，提昇南科區域居民醫療品質。","7 檢討善化、新化、新市高密度住宅區停車場空間，規劃建造合適停車場（塔），讓居家停車更便利。","8 提案檢討新化、山上、新市、善化、安定區，都市計劃範圍規劃合理性，加速南科生活圈都會化。","9 推動農地使用多功能化，強化農業用地輔導取代罰款處分措施。","10推動制訂交通違規處分行政規則，讓市民安心上路，遵守交通規則，免受取締處分。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"5f43f32b-033e-4cb6-971d-ebde5e356725","items":["打造高雄嶄新文創，人文歷史再復甦。","完善大運輸系統，友善轉運再升級。","改善旗津交通問題，觀光產業再布局。","爭取改善排水設施，永續治水不間斷。","加速引入微型青創，老舊市場促轉型。","推動港市永續合作，新舊城區向前行。","重視弱勢族群權，強化社會安全網。","打造智慧效率政府，推動數位新服務。","爭取培養體育人才，運動風氣再植基。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5f6d2ddb-a7fa-4305-a4b7-14f903301243","items":["觀光推動 結合農漁業輔導產銷班推廣在地特產。","要求政府重視提升在地醫療。","爭取快速道路及鐵路南延恆春半島。","要求原有部落劃墾丁國家公園。","提倡環境保育觀光資源永續發展。","爭取經費推廣恆春半島六鄉鎮傳統文化。","爭取經費整治產業道路及各港口清淤使農漁民安心作業。","爭取經費提倡地方教育資源及提升各項體育發展效能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"5f758a28-e562-4cfc-86e0-a776fb88b38b","items":["監督縣政，克盡言責","交通建設，改善路網","工商發展，扶助創業","農漁升級，建立典範","警消維安，提升量能","教育文化，多元發展","環境保護，節能減碳"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5f8e4c85-6216-42d6-9bda-9809e3344465","items":["督促縣府做好工作，提高施政品質。","督促並爭取落實海線教育資源，減少城鄉差距。","督促關懷社區老人食堂關懷據點設立，讓長者有幸福的生活環境。","用心照顧弱勢族群，提高鄉親權益。","用心照顧農漁民，保障農漁民權益。","用心照顧環境，追求永續經營。","用心輔導更生人就職。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"5fbfd23b-280c-4bf5-8f8b-d3ef5fb5b29c","items":["加速關渡平原開發","督促市府放寬都更法令限制提高誘因","落實改善無障礙空間及生活機能環境","持續廣設士林、北投U-BIKE覆蓋率","增建公宅、放寬條件、降低租金","爭取寵物友善照護機制","繼續推動廣增公立幼兒班級數","增關特色公園共融遊具遊戲場","監督市府淡北路無紓解塞車配套不通車","調高青年就學及創業貸款額度、降低利率"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"5fe7e279-4123-47a2-8e5d-98c6f5305acd","items":["監督市政、為民服務、爭取民眾福祉。","積極關懷長者、婦幼權益、協助及輔導弱勢族群能自力更生。","串聯各景點發展觀光旅遊休閒產業、增進觀光收益、盤點公共土地或鼓勵民間土地參與政府興辦工商科技園區、打造「人文科技大學城」、培育優秀人才、在地服務、振興產業、繁榮經濟、增加地方收益。","積極爭取客雅大道向東延伸、接通高峰路科學園區交通網路更活絡、敦促政府落實環保（空污、水污、噪音污）加強防治。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"5ffdc491-a180-407b-96ff-1b988d791e29","items":["嚴格監督政府施政品質。","爭取地方各項建設經費。","帶動地方繁榮發展。","扶植弱勢族群建立公平祥和社會。","推動各項文化建設讓產業與地方文化結合發展地方特色。","督促政府建立完善社會福利制度照顧老人及弱勢團體。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"60bb8f54-aa9e-40c3-b299-6e2b3b678e57","items":["督促縣府活化花蓮閒置公共空間，全面推動地方創生。","要求健全花蓮社福網絡，加強高齡友善。","推動產業及觀光發展，讓年青人有更多就業機會。","加速推動智慧校園，增加學習資源提升偏鄉數位之機會與能力。","推動東海岸SDGs永續旅行，辦理國際性觀光活動。","配合本縣觀光產業、督促縣府規劃交通網、疏解民眾塞車困境，並縮短城鄉差距、提升觀光品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"60d1c1ca-efeb-4f0d-b3ec-feafab316816","items":["爭取銀髮補助，營造樂齡生活：積極向縣府爭取銀髮族補助，提供失能長者長期照護相關資源連結與轉介服務，改善長輩居住環境，營造適合長者安居生活的樂齡友善小鎮。","加強育兒補貼，廣設優質公托：爭取放寬申請條件、加碼提高育兒津貼、落實友善托育措施，並且廣設優質公托服務機構，積極營造有利生育、養育之樂養環境。","爭取縣府補助，提升教育品質：加強溪南教育預算，爭取縣府資源合理分配，使竹東孩子更全面多元發展，提升竹東教育競爭力。並且監督營養午餐，選用在地食材，讓學生安心健康用餐，為我們下一代吃的健康把關。","監督縣政規畫，改善交通問題：全面監督縣政規劃，針對頭重、二重、三重地區交通壅塞問題，提出改善計畫，多管齊下改善壅塞狀況，提供一個便利的宜居城市環境。","關懷弱勢族群，落實社會正義：為民眾爭取各種福利，加強照顧弱勢族群。監督縣府各項社會福利政策，對於特殊及弱勢者更應該根據他們的需求，給予更多的扶助及照顧。","優化休憩空間，創造良好環境：加速公共空間利用，優化竹東河濱公園休憩場域，升級硬體及增加對民眾友善的設施；活化里活動中心和社大的場域空間，軟硬體的挹注和更新，讓竹東25個里和社區，都能有人文、藝術、休閒的樂居環境。","爭取縣府資源，加速竹東繁榮：為竹東建設及資源爭取更多資源，協助加速產業創新升級及發展，因應青年創業問題和需求提供資源及機會媒合。推動在地觀光的特色亮點，塑造提升竹東鎮的品牌形象，加速竹東繁榮發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"612cb71c-2319-4017-ae76-5a8c5ddced14","items":["教育提升：落實2030國家雙語教育，校校有外師，推動雙語向下扎根，本土雙語教師福利再加碼。","婦幼保障：擴大公托容量與普及率，打造友善的育兒工時與空間，健全幼托機構並擴大兩歲專班，爭取托育補助加碼一千元。","人本交通：廣設停車場並增設轉運站，引進智慧交通科技，推動平鎮龍潭捷運路網，爭取打通瓶頸道路與改善交通動線。","河岸復興：打造「河岸光廊」成為平鎮觀光休憩亮點，開闢親水空間、單車步道，提供大家騎單車、散步與休閒的所在。","空間活化：活化「閒置營地」及66快速道路橋下，廣設公園綠地、運動場與停車場，提升市民空間使用效能。","勞工安全：催生勞工公共安全定型化契約、監督工作環境安全的落實，提高勞工安全的保障，促進就業及協助扮演勞資雙方的橋樑。","農業推廣：發展在地特色農產品，推動有機農業、無毒蔬果之品牌推廣，強化產銷合作，培養青農鼓勵青創。","銀髮健康：擴大敬老卡應用；建構完善社區長照系統，營造健康、安全與樂活的環境。","地方創生：推廣平鎮在地文化節慶、挖掘在地文化特色，開發社區品牌，打造有溫度的人文城市。","居住正義：落實居住正義，提高租屋補貼，推動只租不售社會住宅，青年安心成家。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"617cedc5-575d-4bbc-8c71-4da061aa4837","items":["加速老舊地下水管汰換，用水安全。","醫院學校人行道更新預算提高，走的安全。","增加公託公幼比例，提高私立補助，養的輕鬆。","增加都更專業輔導，合理提高容積獎勵，住的換新。","提案恢復Youbike2.0前30分鐘免費，減輕負擔。","學校改建全面加設停車場，停車供給。","大巨蛋後續強力監督，棒球好場域。","勇敢發聲、專業問政，讓市民聲音不再被忽視，監督有力量。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"618c724e-5d07-440f-827d-1fd171dbf059","items":["加速推動觀音區保障里市民活動中心興建計畫。","督促桃園市政府儘速完成月桃路全線拓寬至草漯地區，縮短與青埔特區路程，帶動周邊地區發展。","推廣在地農產、發展休閒農業。","友善育兒環境、爭取育兒津貼。","落實回饋金回饋在地機制，提升地方各項福利。","要求環境保護單位嚴格稽查固定污染源，確保空氣品質。","「2023世界客家博覽會」連結觀音景點，以帶動觀光發展。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"621e256d-1142-4215-ae9e-a3eb3ddb0207","items":["監督縣政、爭取建設、服務鄉親、敢言顧人民權益","督促縣府儘速完成大北斗區（北斗鎮、田尾鄉、埤頭鄉、溪州鄉）高速公路與觀光景點聯結及濁水溪系淨美化、公路花園、花博公園、地方小吃結合完成觀光旅遊規劃。","督促縣府重視社會福利、照顧困苦無依老人及弱勢殘障同胞。","督促縣府重視社會治安，保護人民生命財產安全，早日完成各重要路口監視系統設置。","督促縣府改善各區域、大、中、小排水系統流暢及各農田道路給水系統改善，以保障農民權益。","當一位專職議員，為人民爭取權益，做好民眾與政府間溝通橋樑。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"63913ed5-cdd8-42e7-a071-ee62a0f70241","items":["新臺馬輪依計畫期程啟航營運，完善海運交通系統。","多功能長照服務中心，落實多元長照在地化政策。","示範住宅，提供青年安居樂業。","醫療品質，緊急後送程序標準化爭取時效。","港埠設施，改善中柱港整體景觀。","建置台馬第四海纜，穩定通訊安全及品質。","爭取經費推動基礎建設，優化鄉親居家生活空間。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"63a38795-98f5-45a2-9558-267f2f8c809e","items":["交通:監督大鶯豐德交流道、捷運綠線、六號生活圈道路等重大交通建設儘速完成。","交通:監督八德轉運站儘速完工並規畫八德市區公車接駁至轉運站路線。","交通:持續爭取瓶頸道路打通,便利市民暢通無礙。","教育:監督仁德國小儘速設立、加速取得大勇國小三角地及大福國小的用地,解決八德學子跨區就學的困擾。","教育:廣設公托及非營利幼兒園,減輕雙薪家庭的經濟負擔。","教育:持續推動桃園市國中小雙語特色教學厚植學童語言能力。","城市發展:監督捷運G01、G04聯合開發案規畫,帶動大湳及八擴商圈發展。","城市發展:持續爭取八德地區設置多功能及綠覆率兼顧的新形態特色公園。","城市發展:通盤檢討八德地區國有土地設置運動場館,滿足八德市民多元運動需求。","社會關懷:持續推動八德榮家轉型成安養中心,減輕有養護需求民眾的經濟壓力,並創造就業機會。","社會關懷:持續關心八德區無自來水供應角落,讓民眾家戶都有自來水。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"645c651d-3cb3-41b6-bebd-6879bafca157","items":["守護下一代，我一直都在 亮眼成績 為桃園市爭取教育資源補助共312億元。完成班班有冷氣、生生有平板、改善老舊校舍及廁所整建、學校操場及設備改善、各級學校校舍新（增）建工程、代理教師全年聘期、提高育兒津貼至每月五千元、調降公幼師生比、疫後就學貸款補助。完成國民教育法、特殊教育法、性平教育法、學校衛生法、幼兒教育及照顧法、高級中等學校建教合作實施及建教生權益保障法等重大修法。 持續推動","檢討新課綱及學習歷程檔案成效，有效減輕教師及學生負擔。","推動校園營養午餐專法立法，讓學童吃得健康、吃得安全。","推動學生輔導法修法，調降各級學校專任輔導教師員額比。","每二年檢討育兒津貼補助經費，依據通膨滾動式調整。","要求中央提高桃園市補助經費，完善桃園重大建設。","爭取桃園鐵路地下化車站，建設具地標性門戶意象，打造前後站新商圈，發展共榮願景。","解決客運缺工，增加桃園市區聯外客運班次，改善民眾通勤問題。","全面協助桃園市社會住宅加速興建，健全住宅市場。","爭取部立桃園醫院升格為醫學中心。","提升護理人員待遇，加速推動三班護病比入法。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"64668674-df7d-47c7-bb08-944a4bb3e915","items":["【居住正義】全力爭取全國各縣市建蓋專屬原住民社會文化住宅。","【捍衛原住民保留地】落實《原基法》，反對原保地解編。根據《原基法》第二條的定義，原住民族土地包含「既有的原住民保留地」以及「傳統領域」兩項。","【原住民保留地應放寬多功能使用】原住民保留地造林納入碳權交易標的，以取代微不足道的禁伐補償金。","【監督落實《原住民族基本法》】落實《花東地區發展條例》明定之原住民族權益條款。","【修法保障原住民族勞工權益】爭取原住民族勞工投保補助。","【打造最多元頂尖—原住民完全中學】提供下一代完善教育環境，傳承原民文化，讓原住民族教育權獲得保障。","【傳承傳統競技、培育體育人才】持續爭取相關培育經費，專款培育體育人才。","【65歲國家養】對於「65歲領不到老人年金」族群，黃仁將提案爭取延續「原住民給付」為終身領取。","【0至6歲國家養】爭取原住民族生產獎勵金，提升原住民族育兒補助。","【爭取原民教育福利】國小至大學學費由中央、地方政府全額補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"64cc8e1d-edfa-458b-96ea-cca8227b436f","items":["爭取原住民福利、 權利 , 維繫原住民文化傳承","貫徹地方制度法 , 並秉持理性問政 , 監督公共工程 , 認真絕不懈人","全力配合各部落、 地方機構單位及社團 , 爭取公共建設經費及補助經費 , 並主動積極處理各申請案及補助款案","積極配合鄉鎮 , 推動整合農業、 觀光、 文化成為鄉民經濟的主流","聘任機動與主動型助理 , 協助處理各項為民服務事務和計畫 , 提高服務品質"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"657f6512-5c78-4537-a7d6-4382214fc2e5","items":["城市更新：監督一殯遷建，強力推動【全齡化照護基地】 (托嬰、托幼、托老、日照長照中心、運動及商展空間)。","城市更新：擴大危老都更，改善都市景觀、確保市民居住安全。","全齡照護：推動幸福喘息、增設長照、日照、居家服務補助及時數。","全齡照護：提升外籍師資比例，落實雙語首都向下紮根。","全齡照護：監督北市各級學校、補習班落實使用台灣食材，守護食安。","全齡照護：增設北市青年新婚獎勵；推動社宅前二年租金半價優惠。","全齡照護：滾動式檢討私幼補助金額，減輕家長撫養教育負擔。","全齡照護：推動領養補助、領養代替購買，擴充北市寵物公園數量。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6591c5c2-d24e-469c-95df-a37cb689212f","items":["原鄉都會Double Double 原鄉都會雙引擎 跟著族人尋好蜜","【原鄉】 捍衛土地公義 永續山河經濟 健全原鄉建設 產業轉型升級 連結教會團體 事務族人參與 佈建健康網絡 加速社會福利","【都會】 連結產業經濟 鞏固就業穩定 豐富財金知識 青年專職培力 育兒養老照顧 安心購租住宅 營造族語環境 深耕文化脈絡","《理念信仰》 行公義好憐憫 謙卑與主同行 支持18歲公民 捍衛青年參政 尋好蜜 找歐蜜 讓我們一起走到流奶與蜜之地"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"6661a05c-ed12-4aa7-9cf2-ab1501f564dd","items":["推動社區在地照顧政策，建立優質、平價、普及的長照體系，落實找得到、用得到、看得到的長照服務。","督促縣府推動無毒農業、發展精緻農業、建立有機農業品牌及行銷網路。","積極推動「私立幼兒園公共化」，提高私幼學費補助，以解決幼兒托育問題。","爭取推動電線電纜全面地下化。","爭取增加義警、義消、民防的裝備訓練、提高基層福利。","推動比照鄉土教學，中小學應建置美學課程，涵括美術、書法、戲劇、音樂、社區營造等，以培養公民參與的文化基礎。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6675e849-ca35-4f62-9c1a-a652c7c2c64a","items":["專業專職、全心投入、理性問政、嚴格監督。","顧家鄉、拚未來，力拚一席優質議員，清廉參政，持續推動議會問政透明。","確保捷運黃線推動進程，整合資源，一併改善沿線交通與排水設施。","結合捷運興建，爭取行政中心、社服設施納入共構，推動社會住宅造鎮。","推動地區交通建設通盤檢討，改善行車環境，降低在地衝擊。","加速專案都更，通盤檢討公共設施配置，提高土地使用效益。","因應人口少子高齡化，提高幼托、完善長照，降低壯年負擔。","追求產業結構高值化，爭取新設職訓園區，改善就業與薪資。","改善農業生產設備，開拓國內外多元銷售通路，確保農民收益生計。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"66ad8978-325e-49a2-a7db-a1ec271c1620","items":["農家子弟、公益律師，取之社會、用之社會，追求公平正義，力求溪南溪北城鄉均衡發展。 壹、交通建設方面：開啟溪南、溪北均衡發展的第一把鑰匙。","爭取新建南41線道路，大塭寮跨曾文溪進入安南區海佃路及新吉工業區。","爭取擴建南44、45線道路，西港跨曾文溪進入安定到南科的交通路網，以疏解麻豆交流道、麻善大橋、台19線、西港大橋，解決塞車之苦，並避免人口流失。","督促儘速執行台61線西濱快速公路跨曾文溪景觀大橋。","拓寬台17線國姓橋以北之道路，因應未來「七股科技工業區」龐大車流和通行安全。 貳、產業發展建設方面：開啟溪南、溪北均衡發展的第二把鑰匙。","督促加速開發「七股科技工業區」、「麻豆工業區」，促進地方經濟發展。","檢討與擴建「學甲工業區」、「佳里工業區」，發揮產業價值。","繼續推動「鹽分地帶藝文中心」，應彰顯鹽分地帶特色，永續教育與形塑文藝聚落產業。","推動設置「農牧專區」活用土地，農業及觀光畜牧並重，並減低因牧場設置造成紛擾。","健全農漁牧業生產行銷機制，確保農漁民生計，增進農、漁、牧產業發展。","啟動規劃「麻豆與佳里和七股都市計畫區約1120公頃都市縫合」執行進度，並結合西港區的興起，促進區域永續繁榮發展。","爭取佳里區中山路公園預定地與金唐殿後方停五停車場用地，納入公共設施用地解編後供停車場使用，疏解佳里市中心嚴重停車問題。","為因應七股工業區發展，應加快「七股都市計畫」執行進度。","爭取規劃興建「佳里、麻豆污水下水道系統」，避免污水流入七股潟湖和北門潟湖。","反對興建「將軍區青鯤鯓海水淡化廠」的鹵水回放機制，衝擊漁民生計和海洋生態。","爭取全市65歲以上比照五都，免繳健保費。","要求加強婦幼福利方案，讓年輕人敢結婚、生育。","百人以下國中小學學生免費提供營養午餐。 柒、強化律師服務團隊，並防制政府機關憑藉公權力違法徵課等侵害人民權利的行為，維護人權，追求公平正義。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"66b9fd50-5d49-431b-97e8-0f774aca9733","items":["精進文山區各校通學巷，保障學童穿越路口通行安全。","推動三語（中、英、電腦語言）教育，將程式語言向下扎根至5歲以上幼兒。","堅持「毒品零容忍」，守護校園安全。","爭取公有市場提供創業青年第一年攤位月租一元、第二年五折。","為初尋職青年（新北市15歲至25歲應屆畢業生）提供一年期定期保險。","提供青創貸款利息補貼及青年租房補貼。","推動新店寶高智慧園區育成青創中心。","推動新店安民段、斯馨段青年集合住宅。","五年內推動十四張站捷運聯合開發（B單元）。","推動智慧園區二期，帶動就業機會及產業年產值。","與公民團體復育和美山螢火蟲棲地，延伸碧潭堰生態廊道。","因應氣候變遷，各項市府建設加入SDGs指標，並鼓勵企業ESG承擔社會責任，公私協力達到2030淨零碳排目標。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"66bbb3d9-bca1-4776-b109-e604851bf3b5","items":["推動生育／育兒津貼再加碼 減輕家長們負擔","推動特色公園 打造孩子遊戲城堡","加速楠梓產業園區 爭取科技大廠進駐","推動5G AIoT產業，打造智慧科技城市","加速橋頭科學園區 打造南部科技S廊帶核心 顧長輩｜落實長輩照顧 柏毅一直都在","爭取中油宿舍區旗艦型日照中心 照顧所有宿舍區在地長輩","持續增設巷弄長照據點、日照中心、住宿型長照機構與一社宅一日照","推行「長照3.0」延長長輩健康年齡 顧安全｜守護國防預算 帶給人民安全感","支持潛艦國造 堅實國防自主","推動國防自主產業 守護台灣安全","推動資安聯防網絡 打擊網路犯罪 顧交通｜交通運輸更暢通 左楠再進化","加速翠華路拓寬 重視機車族通行安全","推動捷運紫線（從高鐵站進右昌、從高雄大學到橋科）","推動左營楠梓橋頭鐵路立體化","爭取楠梓交流道設置引道直通楠梓產業園區","改善人行道問題 用路人走得安全、行得放心"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["candidate_introduction","heading_or_slogan"]}}},{"claim_id":"6756ce32-6825-46ec-bf9a-be6ef38542be","items":["改善基金公路塞車之短期改善規畫已有成效，持續推動長期新闢道路以達徹底改善。","武崙溪淹水整治之短期改善規畫已於五年內展現成效，持續監督與推動中期與長期改善。","活化與改造老舊社區與公共設施，推動監督增建停車場設施。","持續監督推動捷運建置，並爭取相關交通便利措施。","建置各區域所需之籃球場與游泳池等相關運動休閒場所與設施。","秉持初衷監督市政與為民服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6772f59c-1153-4762-8393-f70380d22c28","items":["持續基層服務、理性監督縣政","堅決清廉參選、維護民主素養","關懷弱勢族群、照顧公益團體","爭取中央補助、促進建設發展","創造地方商機、繁榮全民經濟：爭取小校合併教學、校舍轉型托老服務"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"678d17dd-bb8a-4cb3-acd1-053a0a5b457b","items":["推動生態文史景點：大頂埔文史生態、大安圳、龍泉溪系步道、三峽安坑、三峽老街、白雞行天宮、汪洋居古厝、山佳等，以地方創生的力量，實現與土地共好，另推廣國外觀光，深化永續旅遊。","以2030三鶯文創計畫為核心，串聯新北美術館、陶瓷博物館，延伸至鶯歌與三峽老街區，連結鶯歌、樹林山佳、樹林火車站周邊、結合河濱自行車道、微笑山線步道和人行空間，鼓勵旅宿經營，打造新北觀光旅遊品牌。","持續監督捷運三鶯線和新北樹林線完工通車，結合既有板南線等捷運路網，以捷運站為城市中心，全面改善周邊人行系統，完整串接公車、自行車、停車空間與社區，打造臺北、新北、桃園以及新北跨區的大眾運輸生活圈與觀光遊憩路線。","督促土城中央路一段至四段人行道改善完工，提升道路品質、釋出行人友善空間。","持續增設6歲以下平價優質幼、托數量，強化居家保母訓練及媒合方便性，建立臨時及夜間托育服務，以完善托育支持生育，以制度撐住家長，協助減緩生養壓力。","持續增設新北親子館和玩具交流銀行，改善公園綠地，檢視公共與校園兒童遊戲場，打造全齡使用戶外園區，推動博物館舍新近性，鼓勵友善親子用餐和通勤環境，全面建構育兒支持系統。","監督建構銀髮支持系統，包括共餐據點、銀髮俱樂部，銀光咖啡館、社區關懷據點，鼓勵共同學習、運動、結交朋友，延緩老化，多元拓展銀髮生活圈；督促推動銀髮照護系統，包括公共托老中心、照護機構、失智共照站等，達成百家社區長照機構；完善就醫接駁、照顧者媒合與管理、居家復健與護理等服務。","持續支持運動賽事、課程與營隊；監督國民運動中心、運動聚點、體育園區、棒球場等設備維護與營運管理，同時推動幼兒體育，發展友善銀髮運動。","結合土城、樹林智慧產業，發展複合型特色商業，支持智慧製造與研發產業，串聯土城工業區、土城頂埔與永寧科學園區、樹林工業區、三興工業區等，形成科技創新廊帶，確保通勤與生活機能完善，打造新北經濟引擎。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"67b49570-a307-4f94-87f1-bd25638a4c16","items":["母語加值：加強母語教育，爭取客家預算。","居安加值：危老建築要更新，消防安檢需落實。","職場加值：落實勞動檢查、爭取疫後相關補助。","動物加值：鼓勵領養不棄養、開闢寵物友善空間。","交通加值：行人友善有保障、行車路權要正義。","經濟加值：特色商圈要活化，產業體質拚升級。 民權提升，議會認真","捍衛議會政風，杜絕議員關說標案。","基進拚黨團，民主交棒、青年續航。 民主團結，台派向前","捍衛本土利益的監督團隊。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"67c7ed1e-4be4-4a90-84ec-cefd33833025","items":["優化醫療服務","促進交通便捷","營造亮點觀光","堅持關懷弱勢"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"67ef984f-b965-49ed-ad44-f8627d1265ff","items":["### 1. 本屆政見說到做到，下屆持續推動","* 已設立板橋首座天幕籃球場，將持續爭取第二座、第三座…… * 已在13座公園增設長輩新式體健設施，將持續改善公園環境。 * 國中小全面裝設冷氣，將繼續改善學校設備。 * 爭取公共托育中心設立。 * 協助社區汙水下水道接管。 * 關心民眾倒垃圾問題，為新社區爭取垃圾車站點。 * 開放板橋放送所、拍攝影片行銷板橋。","* 關注學校社團運動發展、校園安全、促進代理教師薪資合理化等議題。","### 4. 推動設立銀髮事務局","* 建立銀髮業務單一窗口，推動活躍老化，完善長輩休閒空間，重視高齡人力。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"68046ead-1bbe-4e16-8328-527a1fd4790a","items":["尊重生命我先行！ 制定動保自治法、設公有寵物殯葬。","回家的路我把關！ 改善通學步道品質、巷弄平整安全優先。","國軍文化續傳承！ 遷移公墓改綠地、打造南區新亮點。","社區功能再進化！ 建造各里集會所、爭取充電樁補助。","熟齡照護動起來！ 銀髮健身再加碼、免費疫苗護健康。","舊城維新拼建設！ 重啟後站都市更新、活化前站舊城商圈。","厚植在地煥光采！ 青草湖盛況回歸、藝文季行銷觀光。","智慧科技好安心！ 建置防災感測系統、智慧監控城市管理。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6817a726-955d-4bfa-8280-504721f35c3f","items":["繁榮港湖 ✓ 鬆綁都市計畫，重塑老舊工業區，讓內湖南港成為台北新都心。 ✓ 民汐、東環、基隆捷運加速規劃、興建，評估信義線、板南線東延。 ✓ 公私協力，提升都市更新、危老建物改建量能打造港湖新風貌。 ✓ 推動港湖商圈復興，打造親山近水好環境、生活機能完善的宜居城市。","全齡照護 ✓ 預防醫療新思維，重新盤點疫苗政策，擴大輪狀病毒疫苗、腸病毒疫苗、HPV疫苗、帶狀疱疹疫苗、肺炎鏈球菌疫苗政策補助。 ✓ 從租稅優惠到公有土地釋出，擴大民間參與長照，真正提升長照服務量能，讓長照服務達到平價、優質、普及。 ✓ 從健康促進到延緩失能、復能治療，真正做到降低不健康餘命，尊嚴老化，降低中生代照顧負擔。 ✓ 從小就開始健康，從兒童健康預防到成人健康促進，用行動力健全國力。","友善生育 ✓ 堅持托育、幼兒監視器內容雲端保存，保護親師權益。 ✓ 立法推動友善生育職場，不讓生育、職涯成為婦女單選題。 ✓ 懷孕到6歲一起顧，從經濟補助到育兒資源全面到位。 ✓ 成立行政院層級人口對策委員會，擬定永續人力發展政策跨部會解決少子女化問題。","國家發展 ✓ 建立國家安全思維為出發點的能源政策，確保用電永續、安全、穩定。 ✓ 國家永續發展，全面檢討發展人口、勞動力政策，多方向改善缺工問題。 ✓ 從文化產業到科技產業，尋找下一個策略產業提高台灣韌性實力。 ✓ 堅持中華民國主權，台灣人民優先，推動兩岸穩健交流，讓國際社會看見台灣。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"6842e0bd-ec61-47f2-9fb2-47069678db8c","items":["新建捷運紫線，延伸至高科大及高師大燕巢校區，並直通佛光山。","輔導協助農漁民對冷鏈的需求，提高農漁產品質。","落實整合養殖漁業特區管線路，促成產業升級。","因應氣候變遷因素，提高天災農漁業災損補助金。","觀光：發展北高雄海岸線觀光，並開發海上遊憩業務。","觀光：系統化行銷大岡山美食觀光，如眷村、海味及在地特色料理。","觀光：整合機場及眷村，舉辦空軍主題節慶活動。","觀光：建置觀光軸線，串聯阿公店水庫及月世界觀光特色。","觀光：配合高科技園區成長，檢討土地政策，因應住商需求。","觀光：輔導傳統產業解決土地使用與環保問題。","觀光：輔導農漁工產業轉型升級，改善低薪並協助青年返鄉就業。","觀光：因應社區發展規模，調整鄰里編制。","觀光：持續關注區域排水整治，解決水患。","觀光：持續爭取焚化爐、掩埋場、污水廠及國營事業回饋金。","觀光：嚴格要求工安及環保，確保居住安全與品質。","社福：增設公托、公幼，廣納準公共化托嬰及幼兒園，減輕家長負擔。","社福：降低中低收入戶門檻；整合長照資源，推動各里設立關懷據點，落實長照在地安老。","社福：持續推動社會住宅計畫。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6874fc5c-9fcb-48bc-ab08-9ee5fccbe61f","items":["堅持教育優先，推動雙語教學。","協助青年就業與創業。","提升觀光亮點、支持經濟政策。","鼓勵新婚生育、提高補助及優化育兒環境。","推動公園2.0建設全齡親子遊戲場。","治安、消防、交通設備升級，保障市民安全。","捍衛市民權利以市民利益優先。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"68b51740-af0c-42c2-b8a5-a54ec079c1df","items":["督促台76線東西向快速道路之品質、號誌、照明、排水、聯外道路路口安全等事項。","爭取廠商進駐中科二林園區。","爭取精密機械園區儘速通過。","推動西南角之觀光發展，縮短城鄉差距。","為弱勢團體發聲，爭取更多福利。","監督政府，服務人民，為人民做好與政府的橋樑。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"69447996-6d72-4b09-b73e-bd7ad7f9675a","items":["教育環境：推動教育均質化，落實就近入學精神。市府提供資源鼓勵老師精進。並且提供優渥獎金徵求優秀教案，鼓勵教師創新課程。以課程為重點的校務發展，才是以落實以學生為中心的教育理念。","教育環境：要求市府協助各校充實圖書館藏，並強化本市職涯體驗中心功能，讓學生充分探索職涯性向，並提供經費鼓勵學校發展符合108課綱精神的特色課程或活動。","教育環境：督促市府應當增加正式老師開缺、降低代理老師數量、提高代理老師待遇。同時也應健全暢通不適任教師退場機制以及優秀代理老師續聘制度。革新校長遴選制度，讓每校都能得到最合適的校長。","交通環境：持續督促市府改善步行環境，增加人行步道，在交通流量且人眾多的慈雲路段興建空橋，人車分流更安全。改善大眾運輸，檢討班次、路線，並提高候車品質。上下學時間設置通學公車，降低私人運具的依賴性。檢視交通標線與號誌，讓用路人更易於辨識，行車更安全，交通更順暢。","生活品質：督促市府加強汙水下水道建置進度，並於噪音熱點設置噪音科技執法，且於鄰近園區之社區設置智慧共桿，偵測廢氣排放，數據即時公開上網，以提升東區空氣品質。","生活品質：推動公園或重大公共建設，要求市府於設計規劃初期階段辦理公民參與式規劃，以避免設計出不符合使用者需求的公共建物。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"69612e28-929d-4da9-a0cf-320f8938f9d8","items":["關心青年發展，推動產業升級與創新，改善青年就業結構。","關懷弱勢族群並協助新住民培養競爭力。","爭取農漁牧業產業升級，結合地方資源以推廣觀光事業，行銷地方特色。","推廣中科園區，吸引廠商進駐，增加就業機會。","守護長者，協助各社區關懷據點辦理各項服務。","監督環境污染、廢土處理，實現永續發展。","推動文化傳承，重視教育扎根，建立家鄉認同感。","議會透明監督，堅持行使議員的監督職責。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6963ec17-becb-47d3-bc70-4a3961d8987e","items":["推動嬰幼兒臨時托育政策，結合臨托、長托保母線上平台，讓沒有後援的新手父母有喘息的空間，方便找尋優質安心的保母。","敦促嬰幼兒物資交流中心設立，讓地球資源得以永續，也讓弱勢、邊緣戶的孩子不再資源短缺，留給孩子一個好的地球環境。","敦促青少年福利政策接觸多元文化，得以關心及發展健全的身心教育，降低兒童自殺、霸凌問題。","推行青年培養基地，讓青少年有處去，發揮青年該有的本質與天賦，例如：推動極限運動暨寵物公園興建。","活化轉型閒置建設，讓空間得以使用最大化，例如：增加公立長照名額，減輕讓子女或老照顧少的壓力，或增加商業應用，促進社會經濟活絡。","網路時代，教導孩童使用3C時杜絕數位詐騙、性侵害及性隱私犯罪防治，讓孩子避免蒙上一輩子的陰影。","原住民專員或服務中心設置，關懷原民的狀況。","長照5G遠距關懷，讓出外打拼的兒女能安心，優化醫院、縣府的連結，輔具、資源、租借、補助申請平台。","優化行人路權，檢視道路規劃及安全，提高道安，讓用路人更有保障。","除了既有的復康巴士，引進小黃公車預約平台，解決偏遠或弱勢家庭就醫困境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"69ae0f1c-6747-47d8-bacf-61c2d2ae4668","items":["在地心，打拚為鄉親，打造 Better Life","長照減負擔 80歲以上免巴氏量表，直接申請外籍看護｜65歲以上健保免費｜提高長照補助及特別扣除額｜每月5千元「重度失能家庭照顧者津貼」","化解少子化 補助凍卵｜提高育嬰留職津貼｜三胎家庭百萬房屋補貼","已爭取2千億元地方建設 捷運東環段、南環段、環狀線第1階段｜安坑輕軌｜新店行政園區（含運動中心）｜安坑一號道路1、2期｜新店污水下水道工程1、2期｜寶高智慧園區1期｜碧潭堰｜深美變電所室內化｜無自來水地區延管工程","教育再升級 幼教投資加倍｜全面檢討108課綱｜縮短公私立大學學雜費差距｜學貸免息","讓您有宅住 多元興辦公宅｜二胎家庭優先住公宅｜青年購屋低利貸款增至1200萬元｜檢討「不動產交易所得稅」，漲價歸公，及4戶以上囤房課稅，遏止炒房","未來持續爭取 寶高智慧園區2期｜新店污水下水道工程3、4期｜新店長照園區｜安坑一號道路3期｜安坑運動中心｜安坑快速道路（往土城）｜深坑輕軌（延伸石碇轉運站）｜坪林採茶文化中心｜坪林國中地下停車場｜振興烏來觀光","勞工不辛酸 職場新鮮人2年50萬意外險｜調高基本工資至33,000元｜低薪上班族所得稅減半｜扶養12歲以下子女，扣除額提高50%","寵物好開心 設寵物運動園區、室內運動中心和生命園區｜發展寵物科技產業"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"69ff9b08-bfb0-45cf-9379-568507c42aca","items":["推動全國運動賽事，帶動人潮，創造地方經濟效益。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6a1164f6-f730-428a-a68b-ad422f8d1893","items":["長庚捷運站與觀光纜車：研議由八堵進安樂區、往中山區進入基隆站的捷運路線，並在安樂區設置長庚醫院捷運站；以大基隆觀光戰略建立濱海東西線觀光空中纜車，東線串接海科館、八斗子與九份，西線串接外木山、萬里與金山。","守護自然與強化城市韌性：保護海洋生態，反對台電在外木山海域興建儲氣槽；強化醫療抗疫、新建大型儲水庫並降低漏水率，打造具韌性的基隆。","安樂區交通改善計畫：盤點鄰里間閒置公有土地廣建停車格，將學校操場增建地下停車場；開通區域間外環道路；在大型社區出入口對向道路設置左轉暫停區或左迴轉道；瓶頸路口尖峰時段採科技執法；由安樂路二段開通樂利一街，經拓寬後的自強產業道路連接大華交流道。","基金公路塞車改善：上午運用分流法，將部分車流導向基金三路到萬里；下午採繞道法，經大武崙工業區接七安產業道路，到七堵大華系統上高速公路；長期將台62快速道路以高架工法由大武崙延伸到萬里。","古道縱走風景區：結合劉銘傳隧道、獅球嶺砲台與獅嶺匝雲，推出一日山林古道、山海美食與歷史古蹟體驗行程。","健康運動園區：在安樂區規劃同時擁有戶外與室內空間的運動園區，滿足晴天與風雨天候下的各類運動及體適能需求。","安樂圖書藝文大樓：成立基隆市第二座文化中心，結合圖書、文藝、休閒、學習與服務的社群公共空間。","安樂新都心：發展低密度科技研發園區與文創餐飲園區，將安樂區打造為基隆未來的商業與產業型副都心。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"6a2912c7-a792-4b78-b9be-c355b1d5cf3f","items":["推動溪北以「生活機能區」納入南科規劃。","爭取新建跨曾文溪大橋。","防汛道路拓寬計畫延伸至麻豆、大內。","監督善化、隆田車站擴建，自強號增班。","強化農村再造、農民福利、農業設施。","加速灌溉示範工程，持續廣設農塘。","保障養殖漁業生產、銷售與漁民權益。","監督金融業負起企業社會責任，將ESG納入放貸審查標準。","推REITs法案引導金融資金投入公共建設。","持續監督虛擬資產規範。","推動低利保單貸款後，持續強化普惠金融。","推動國安修法，拒絕中共代理人。","挺潛艦國造、國防自主，促進全民防衛。","加速大北門文化中心進度。","監督善化牛墟遷址、啤酒廠改造。","強化西拉雅族文化保存，推動正名修法。","串連景點打造文資廊道，引流府城人潮。","加強總量管制、生態指標門檻等配套措施。","監督綠能回饋金機制，保障農漁民生計。","定期全面稽查案場，並推動業者自律公約。","遊說日本制定「台灣旅行法」。","推動日本以具體行動支持台灣加入CPTPP。","研議房租漲價備審制，避免不合理漲價。","監督佳里、麻豆社宅進程，爭取官田社宅。","監督玉井長照落成，推動聯合門診與分院。","加速南科周遭幼托設置。","爭取公費HPV疫苗。","推動長照結合智慧醫療。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"6a6bbbfa-fe77-4ec5-8983-a9d17c7b5f01","items":["督促「內門觀光休閒園區」規劃，維護旗美地區不同宗教文化特色及民俗慶典傳承先民優良傳統文化，活絡東高雄觀光景點 旅遊產業。","持續推動馬頭山劃設為「國家自然公園」，保護馬頭山地景與豐富的動植物生態。","建請規劃高雄「輕軌、捷運」路線延伸至旗美地區。","爭取台 29 線，由「杉林小份尾往甲仙寶隆」路段拓寬截彎取直，確保民眾交通安全。","建請政府重視旗美地區溪流之防洪、防災工程及農路產業道路舖設維護，保障民眾生命財產安全。","開創青少年、婦幼、新住民就業機會及保障年長者之權益。","建請市府成立「完整農產品物聯網產銷通路」擴展外銷國際市場保障農漁產品收益。","監督「食品安全」及「學童城鄉教育資源落差」維護學生授教權。","督促市府加強規劃社會福利政策，從生育、保育、教養、教育、就學、就業以及新住民老年長輩與身心障礙者之照顧服務， 協助經濟弱勢族群脫貧計劃之濟助服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6aca1105-35b7-4430-be5b-d63888dde492","items":["示範住宅，落實住者有其屋。","經費興建東莒海淡廠。","經費興建東、西二島停車場。","軍方釋出營區利用價值及規劃。","老人福利，強化照顧服務。","提升，多元化的發展。","縣府海洋政策落實，永續維護海洋資源。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6ad7a224-187e-4668-862d-04ed0750a318","items":["推動大嘉義縣市合作互補發展，共利共榮，促進區域產業整體升級。八掌溪、牛稠溪堤防道路應串聯銜接縣市山區海線，讓藍色公路帶動休閒運動與觀光發展。","推動設置智慧醫療生技園區，建構跨縣市遠距醫療視訊網絡，培養照護體系，讓嘉義成為全國照護醫療人力培育的示範城市，以產業帶動人口成長。","推動各里設置優質長照據點，每里均應有C級長照點及老人食堂，照顧並陪伴里內長者，讓銀髮族的退休生活更充實。","推動增建「社會住宅」，讓年輕人或收入一般的鄉親也可以輕鬆租屋和購屋，真正落實居住正義，提升居住品質。","推動防災治水政策，建置「災害熱區管理系統」，找出問題、有效解決。增建「水撲滿」以提升都市蓄排水效能，建構綠色環保永續城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6b05daf9-5689-42d7-ad15-f21ef8493c1c","items":["爭取基層建設，改善鄉親生活","重視教育發展，扶助弱勢學生","引進科技產業，增加就業機會","發展休閒觀光，活絡地方經濟","農漁產業升級，增加農漁民收入"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6b8bb72b-0968-4b1f-b849-b28727fa0ce4","items":["推動校園設施汰舊換新，加速科技設備的提升，讓孩子們受教育的環境更優質。","配合2030年雙語國家政策，提升各級學校雙語教育資源，接軌國際，並增加與國際間各級學校交流的機會。 長照更幸福","推動更多資源進入社區，強化社區共同照護的能量，並且透過社區供餐關懷長者。","在社區中導入醫療資源協助照護長輩，讓長者安心養身保健，也讓青年族群得以安心在外工作。","生活更安全：補足警察、消防第一線人員員額及盡速汰換老舊設備，並落實警消人員職後定時受訓，強化治安及消防量能。","生活更安全：通盤檢討排水規劃，在面對極端氣候下強降雨的情況，重新整治水路，改善排水系統，避免逢雨必淹的情形。 交通更順暢","生活更安全：優先保留公有大型停車場部分車位給在地居民，舒緩停車空間不足及道路交通壅塞之問題。","生活更安全：通盤檢討騎樓與人行道的使用，打造友善行人的城市，並且透過地方法規完善地制定，讓鄉親『安全行走』。 育兒更安心","生活更安全：持續增設公托、準公托，提高育兒津貼及生育津貼，並且重視托育孩童的環境，讓孩子安全、家長安心。","生活更安全：推動特色公園、共融遊樂場持續建置，並導入孩童參與主題的決定，一同打造快樂親子城市。 青年更宜居","生活更安全：伴隨著高科技產業進駐，持續盤點可以使用並且適合的地點，推動社會住宅的興建。","生活更安全：推動社會住宅納入育兒、長照相關設施規劃，減少青年移居後所面臨的困擾，讓台南成為真正的宜居城市。 觀光更精彩","生活更安全：協助社區營造、地方創生的推動，並串連各商圈、古蹟資源，將台南深厚地文化底蘊融入，提升觀光產值。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6ba952ed-f55f-48e5-9c5e-e0ffbfbb933c","items":["西農產品，解決農產品銷售問題，增加農民收入。","育資源，推動各校特色教學，提升英文學習，減少城鄉差距。","光資源，串連旅遊景點，發展社區輕旅行，帶進人潮及錢潮。","區關懷據點，配合長照2.0計劃，提供共餐服務，關心長輩。","區農村再生計劃，活化社區注入動力，帶動社區發展新力量。","迎風館經營，推動地方產業。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6bc96bc9-98c5-4bb2-b030-77eb60ebbdee","items":["打造本縣濱海地區繁榮與發展，串連桃園市、新竹市與本縣濱海休閒廊道，建設新豐鄉坡頭觀光休閒漁港。","督促縣府儘速完成台1線替代道路新闢工程。","增設公立以及非營利幼兒園。","促成新豐鄉掩埋場轉型綠能經營再生觀光工廠。","督促縣府完成新豐鄉坡頭村石滬親水空間改善計劃。","打造具本鄉特色文化觀光老街。","廣設縣內長期照顧2.0服務及社區關懷據點。","提高鄉內瓦斯天然氣管線普及率。","督促縣府加速完成新豐鄉台61線與台15線銜接道路拓寬工程。","督促縣府輔導新豐鄉辦理農產品推廣活動，以提昇整體的農業經濟價值。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6c5f7402-0b3c-45ee-92a0-cee0639c11f5","items":["爭取市政府廣設社會住宅，緩解因房價高漲導致衍生年輕人居住問題。","檢討市府土地重劃基金、土地增值稅等，提供更有效補貼年輕人租屋津貼。","持續推動爭取大里、霧峰區之美樂地公園計畫，提供民眾優質生活休憩運動場所。","持續關注長照2.0到府服務功能，強化社區關懷據點活動與送餐，讓關懷據點成為讓長輩安心晚輩放心的最佳生活場所。","爭取幼兒學齡前就讀私立幼兒園補助由每年3萬元提高到4 萬元，減輕年輕父母負擔。","爭取大里、霧峰區欠缺活動中心之國中小盡速辦理規畫與興建，並納入地下停車場計畫，讓學校與地方雙赢。","全面檢修大里、霧峰地區各級學校校內田徑場、籃排球場及幼童休憩設施，提供師生舒適活動空間。","全面檢修大里、霧峰地區各級學校校舍年限，並將無障礙電梯納入學校規劃，提供師生安全校園環境。","督促市府交通局通盤檢討大里、霧峰地區欠缺反射鏡、紅綠燈之路口或社區出入口，全面普設提升交通安全。","督促市府建設局針對大里、霧峰地區之道路、公園、排水溝檢查，提升[路平、燈亮、水溝通]之成效，讓民眾擁有安全舒適居住環境。","督促市府建設局盡快完成連接大里、霧峰地區美群橋之重新興建規劃，爭取中央預算配合市府以盡快施工完成。","加強推動大里區仁化工業區仁化公園綠美化，並增設體健設施及休憩設施，提供鄰近社區、社會住宅民眾優質休憩場所。","結合地方意見檢討大里、霧峰地區適合設置Ubike 的地點廣設站，方便民眾騎借，有效推廣綠能減碳。","督促市府盡速興建大里、霧峰地區各里尚未設置之社區里民活動中心(如大元里、中新里、六股里、本鄉里、仁化里、仁德里等）。","爭取市府觀旅局草湖溪自行車步道1-5期設施與綠美化工作，擴大檢討大里溪沿岸仁堤路及十九甲堤防自行車步道綠能路網興建串連。","爭取市府運動局盡速完成草湖溪高灘地塗城里地段規劃成最優質河濱公園，改善大里區公六棒球場、東湖棒球場、舊正棒球場設施。","爭取市府運動局於康橋228公園興建全市第一座匹克球專屬球場，提供選手優質訓練場地為台中爭取成績榮譽。","督促市府水利局、農業局與建設局通盤檢討大里、霧峰地區產業道路開闢興建、狹窄道路與老舊橋樑興建拓寬。","整合霧峰光復新村各業管單位，確定光復新村文創、觀光產業與歷史定位價值。","督促市府勞工局檢討產業外勞聘用程序之相關條例，讓勞力密集之產業可聘僱足額人力。","爭取大里軟體園區結合中興商圈打造OUTLET 商場。督促市府經發局持績向中央爭取特定工廠設置之服制，讓現有產業可更合法運行。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6cc08357-de1f-4114-a70d-370121b3e666","items":["青年政策：青發處升格為青發局2.多元就業及創業輔導3.青年購屋零頭款4.青年創業好貸款5.社會新鮮人待業津貼。","幼兒教育：推動0至6歲免費公托2.獎勵企業成立員工專屬托育中心3.單親家庭免費課後輔導4.弱勢家庭食物銀行。","都市建設：提案增加獎勵文創產業2.發展一里一特色，打造在地文化3.積極參與及推動社子島開發案","都市建設：推動古厝老屋改造，保留歷史價值；老舊公寓公辦都更，讓城市翻新，進而提升全民居家安全。","社會福利：鼓勵全民志工文化，推動設置「社會福利儲值卡」2.多功能青銀共居宅之推動及增設銀髮托老中心","社會福利：65歲以上假牙補助。 【寵物友善】 打造寵物友善公園 推動寵物類健保制度。 【數位城市】 開辦免費線上法律諮詢，以減輕民眾舟車勞頓之苦。 督促市政府快速民生所需之數位化城市生活圈。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6d30a6c7-a129-45f3-9a85-790062810076","items":["推動高捷紅線與台南捷運銜接計畫,促進北高雄繁榮。","要求市府提出短、中、長期的治水計畫,解決民眾淹水之苦。","推動綠能產業發展,興達港特定區成為離岸風電專用母港。","全力推動「高雄半導體S廊帶」,加速南台灣產業轉型。","落實社區長期照護政策與獨居老人的生活照顧。","加速舊高雄縣區都市計畫重新檢討,維護縣區市民權益。","後疫情時代,配合防疫新生活,兼顧經濟與健康。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6df80c16-841a-4ff3-a5e1-a293d9435a99","items":["積極爭取山城區教育資源，縮小城鄉差距，避免邊緣化。","積極推動客家特色文化系列活動。","推動「城鄉特色二日遊」，結合產業、觀光一元化，帶動山城產業商機，發展山城觀光產業。","落實輔導山城農民生產精緻農產品（如花卉、香菇、蔬果 . . 等），提高競爭力，以增加農民收益。","督促農業局建立農產品產銷平台。","全力支持65歲以上長輩健保持續補助及國中、小學校午餐免費營養加倍。","打破派系壟斷，服務不分黨派，落實服務百姓。","爭取弱勢團體各項社會福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6e1013ce-b5d8-4161-bfc3-0bc233463491","items":["（一）嚴加把關預算，杜絕浪費，讓納稅財源做最妥善之運用。","（二）積極爭取建設，均衡城鄉發展，帶動商機。","（三）監督縣政，提升行政效率，加強服務品質。","（四）傾聽民意，重視民眾需求，做縣民最有力的代言人。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6e162d13-ff4f-4899-b985-f92aca20a896","items":["強力監督縣政推動,落實法案。","積極爭取老人、幼兒及新住民福利,強化弱勢照顧服務。","提升生活品質,積極爭取社會住宅再建置。","持續爭取地區兒童室內外共融遊戲區增設。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6e45b6bb-b945-478b-b880-1257b464cc8d","items":["交通：推動台灣高鐵南延至高雄車站，帶來豐沛人潮，以促進南高雄之發展。","產業：推動IC設計產業進駐「亞洲新灣區」，打造高雄「北台積、南IC」產業鏈，讓半導體產業延伸到南高雄，繁榮南高雄。","解決高雄空污問題，讓高雄人呼吸新鮮空氣。","廣設社會住宅，讓居者有其屋，落實居住正義。","增設日照、長青中心，顧老護幼，讓青壯市民無後顧之憂。","爭取警消人員福利，體恤辛勞，保障市民生命財產之安全。","拒絕市府隨意提高地價稅、房屋稅、污水費等，為市民看緊荷包。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6e5f1274-3983-4374-878f-d06b80648a67","items":["監督縣政、為民喉舌。","改善基礎建設、提升社會福利。","為婦幼、新住民及弱勢團體發聲，爭取福利及權益。","督促加速農漁業輔導，拓展行銷通路及建立災害預警機制。","督促觀光發展推動，創造就業機會。","督促安養長照推廣及改善醫療資源差距。","推動動物友善政策（如：重罰棄養、落實絕育），普及寵物運動空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6e96c313-b803-401f-92a7-b1aa81be05c3","items":["設立服務處，專業問政、專職服務，並提供免費法律諮詢，解決民眾問題，保障縣民權利。","關心婦幼權益，爭取設立親子館及共融式公園。","關心地方產業發展，協助青年勞工就業，促進青年返鄉。","關心弱勢族群，確實維護其權益。","嚴格監督縣府預算之編列與執行，讓人民的納稅錢發揮最高效益。","督促縣府做好區域排水系統整治，解決水患，保障人民生命財產的安全。","督促縣府辦理國道一號高速公路溪湖交流道特定區解編並開發，吸引廠商進駐，增加就業機會，增進地方的繁榮。","爭取台76線快速道路福興埔鹽交流道周邊設置農特產品物流及暢貨中心，以利農產品運銷，降低運輸成本，增加農民收入。","爭取縣道148線溪湖外環道新開工程，紓解溪湖鎮市區交通壅塞狀況，增進溪湖地區往來國道一號（員林交流道）之便利性，帶動地方產業發展。","支持18歲公民投票權，擴大青年參政機會，深化台灣民主發展！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6eb4cc8b-3280-4477-8115-79110214224a","items":["大安溪南北兩側沿岸國市共有土地整合再利用。","外埔區第一公墓已遷葬完成利用該土地新闢建設甲安埔大型公園。","大甲運動公園積極推動早日進行施設。","甲安埔附設幼兒園增加招生人數，善用現有閒置空間增設公辦民營幼兒園，達到幼托照護一條龍。","推動日南東一街新闢道路及黎明橋南側銜接處拓寬慢車道寬度一致。","大甲松柏漁港北側爭取合法衝浪區及戲水區。","溫寮溪育德橋連接至台61線西濱濱海快速公路。","大甲區第一市場新建重建。","於甲安埔地區公有地興建社會住宅。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6ed11a15-8f31-453b-bcf2-69371e14929b","items":["協助單親家庭改善養育、教育困境。","加速親子館、共融公園興建,爭取規畫極限運動場。","尊重多元移民族群、規畫進修課程、鼓勵新移民走入社會。","興建青年出租公營住宅、降低就業青年租屋負擔。","強化技職教育、鼓勵就業進修、解決產業人才欠缺困境。","督促政府逐年清運店子湖垃圾場垃圾,規畫興建環保公園。","擴大檢討龍潭都市計畫,釋出可建築用地,解決高房價困境,並取得國民運動中心及轉運站、大賣場用地。","打造桃園成為寵物友善城市,辦理免費寵物健檢、疫苗注射。落實動物保護法。","檢討農業稻作休耕、農藥、肥料補助、紅火蟻防治政策,嘉惠農民振興農業。","優化市區人行道友善行走空間、廣設停車場疏解市區交通壓力。","放寬農地變更為停車場用地門檻,解決老舊社區停車問題。","銅鑼圈山坡地劃出範圍:推動都市計畫、產業專區規畫,均衡地方發展。","督促政府加強石門都市計畫範圍內公共設施修建、養護。解決長期空污問題。","增加國道客運行駛路線及班次,提昇通勤族移動效率。","加強辦理青少年球類、水、陸各項運動競賽,走出戶外,減少電腦、手機使用時間。","自來水、智慧路燈普及化。電線電纜地下化,推動傳統市場現代化。","提高補助辦理烹飪、講座、研習、藝文、歌舞、技藝、攝影、插花、瑜珈、旅遊等課程、強化終身學習環境。","鼓勵各級學校提倡四維八德、品格教育,端正青少年中心思想,強化國家認同。","打造龍潭逐步邁向科技、觀光、文化、農業、幸福、微笑、品格新市鎮。","推動大石門地區成為「三坑水鄉休閒農業區」;活絡農村經濟,加速公共設施新建,吸引青農返鄉服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6edf8418-16a6-4b6f-ab17-cb9386ccf3dd","items":["提高公糧收購價格，保障稻農基本收入。","降低青年養育壓力，廣設托育托嬰據點。","提升專技人員薪資，建構智慧科技農業。","提高山區教師待遇，強化偏鄉學校設備。","打造永續發展農村，推動綠色環境給付。","監督落實居住正義，杜絕炒作健全稅制。","重啟還我土地運動，放寬原墾文件認定。","放寬取消巴氏量表，降低看護申請門檻。","暫緩訴訟司法追殺，改訂輔導落日條款。","檢討現行長照缺失，優化長者照護品質。","檢討國土功能分區，捍衛居住生存權益。","完善長者社群連結，拚壯世代第三人生。","國土保育落實配套，擬定安遷補助方案。","推動長照保險政策，建立穩定永續財務。","輔導工廠數位轉型，營造產業聚落效應。","打造觀光友善環境，國際遊客倍增來嘉。","開發深度套裝遊程，補助旅宿優化環境。","爭取合理水電配置，吸引高科廠商進駐。"],"content_split":{"method":"manually_reviewed_platform_items","version":"election-content-items-v1","confidence":100,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6ef0f971-506e-409e-8056-16678f32bcf8","items":["支持全縣國中小營養午餐免費政策。","支持高齡大學政策，建議增設青銀共學課程，促進跨世代交流。","爭取加速完成冬山交流道，增加冬山鄉居民通行便利，帶動地方產業發展。","持續爭取拓寬梅林路、梅花路及義成路一段，紓解交通、提升用路安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6f76af79-2e38-4dcd-8c29-c94d1290c415","items":["等車會舒適 - 完善候車亭建設。 - 監督改善車輛安全與人本交通。","兒童有公園 - 推動共融式親子公園設置。 - 汰換老舊遊具，打造安全遊憩空間。","青年賺有錢 - 協助傳統產業轉型、青創、新創。 - 推動特色產業活動，增加行銷管道，打造媒合資源平台。","運動有去處 - 推動複合式運動場域。 - 監督運動空間的運用與安全。","觀光能永久 - 結合在地文化、產業，輔導特色觀光永續性。 - 監督觀光開發建設之效益。","社福醫療要升級 - 補強校園、婦幼安全網。 - 監督社福、醫療預算分配的平等性與軟硬體提升。","教育藝文要紮根 - 平衡城鄉硬體設備。 - 推動充實多元教育、技職軟實力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6fbe140b-7c82-4878-a934-54394b60cfce","items":["發展藝文體育活動：音樂藝術氛圍扎根，運動體育發光發熱。","協助農業產銷機制：提升農民農事收入，推廣精緻農業路線。","保障弱勢團體福祉：婦女、老幼、外籍配偶，戮力爭取福利保障。","拉近城鄉教育差距：推動相關教育政策，翻轉嘉義孩童發展。","長照發展老化趨勢：銀髮照護比例加重，樂活長輩輕鬆晚輩。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6fc4dbdf-e2e6-44e4-92cd-2fa4fccb8696","items":["台灣主權-守護台灣人引以為傲的自由民主生活,抵抗中國共產黨的統戰滲透及文攻武嚇。","參政平權-支持符合國際趨勢的18歲公民權,修憲公投我同意,台灣民主向前進!","城市發展永康航","縫合都市-加速砲校遷建及二王重劃,增加蛋黃新都心。加速永康鐵路地下化,打通交通及發展瓶頸。","青創綠廊-砲校基地重劃永康創意園區,結合市總圖書館與大專院校,擘劃電競及動漫等青創聚落。","先進運輸-加速推動高架捷運,建構城市公共運輸骨幹,優化公車搭乘體驗,革新公共自行車營運模式。","立體路網-交通立體化分擔平面車流,鐵路下地與捷運高架,加速都會北外環道全線及國一匝道完竣。","跨溪大橋-爭取永康與安南間第三座跨鹽水大橋,緩解溪頂療大橋及永安橋的交通壅塞。","智慧城市-強化資訊專責部門,擴大城市數據引導市政決策,智慧回應民意,決策品質貼近城市體質。","智能服務-智慧AI即時因應市民大小事,交通號誌調控、路面及路燈養護、空染溯源及追緝噪音車輛。","親水整治-建設開發加強出流管制,易淹水區加速整治。","招商引資-精進單一窗口加投資建設,增加工業地供給。","垃圾去化-因應垃圾大戰危機,加強落實垃圾分類,設置工業區專用爐,加速化爐更新與埋場活化。","騎樓暢通-盤點學校及商業區等步行熱點,優先落實友善行人,確保1.5米步行空間暢行無阻。","機車平權-検討非必要的禁行機車路段及兩段式左轉路口","青年成家-提升青年事務層級,加速青年公宅,推動婚前健檢及不孕症補助,協助安心生育。","安心攜幼-輔助家長喘息,佈設安心臨時托育服務,增加公立幼兒園2歲幼幼班服務。增加特色公園。","樂活銀髮-盤點校舍等閒置空間,因地制宜設置日間照顧或失智關懷等社福單位,提供多元銀髮服務。","共融城市-推動共融環境,使身心障礙者、長輩及孕婦等行動相對不便者,能在城市安心悠活。","勞資永續-普及勞基法與勞權意識,輔導產業避免違規,穩健勞資關係永續經營。","警消安全-甄補警察及消防人力,落實勤務訓練,維護執法尊嚴與執勤安全。","全民運動-加速新建永康全民運動中心,活用閒置空間,增加各類運動場地。","寵物友善-爭取永康寵物公園,落實源頭管理結紮絕育,公私協力優化浪浪收容。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"6fc7eff4-72d5-48f9-a454-db07f8eaa6a3","items":["【教育永續】 1.推動數位學習、強化英語能力、爭取國中小班班有冷氣、提升學童競爭力。","善用閒置校舍，擴大公共幼托能量、廣設學校課後照顧，減輕家長經濟負擔。","推動在地就學，持續發展基層運動，為學生創造更多運動舞臺。","守護校園，打擊毒品犯罪，讓毒害遠離校園。 【建設進步】 1.爭取興建特色公園、極限運動公園、森林園書館、藝文展演中心，地方活動中心及停車場。","加速安坑都市計畫，促進地方發展。","闢建安坑交流道至新烏路之25米計畫道路。","建置安坑捷運沿線高地社區交通接駁。","爭取安坑開放式高地社區老舊柏油路面刨鋪翻新。","推動防災型都更，加速老舊建築早日改建。","加速寶高智慧園區二期開發，增加青年在地就業。","加速推動深坑捷運，打造通勤、觀光兼具之捷運路線。","建置鄰里巷監視系統，維護社會治安。 【社會福利】 1.廣設公共托老、托幼、托嬰中心，讓長輩安心，青年人放心。","提升生育率，爭取提高幼教補助及生育補助，讓年輕人生得放心。 【觀光保育】 1.打造新店地方特色，推動香魚川計畫讓新店成為香魚之都，香魚的故鄉，促進新店觀光發展。","擴大碧潭水域範圍，打造國際級水上觀光、休閒運動風景區。","推動新店溪封溪護漁，宣導垂釣不網魚，遏止魚類資源嚴重濫補。","推動新店、深坑、石碇、坪林、烏來清除外來魚種計畫，維護本土魚類永續生存。","爭取補助流浪動物結紮、標記及植入晶片，並推廣「領養代替購買」。","堅決反對烏來南勢溪引水至石門水庫工程計畫。 【文化推廣】 1.推動客家事務，紮根客語學習及文化推動。","推動新住民母語教學與文化推廣。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"6fd8e015-34f7-4781-81f1-dba35d6640e0","items":["持續推動在金門設置教育學程,提供金大學生及金門籍大學畢業生修習,培育中小學師資在地化。","持續關心特教生及弱勢學生權益,強化適應體育及相關職能與生活能力課程、營隊。","推動成立公辦民營之實驗學校,讓不同特質之孩子可以有選擇教育方式之權利。","爭取金湖金沙地區運動專業教練名額,並以台灣經驗為參考,協助金湖金沙地區成立兼顧基本 學力能力之體育班。","爭取金沙及金湖地區土地重劃範圍,建設東半島。","推動金廈大橋(由金沙接至廈門翔安機場),活絡金沙地區之經濟與發展。","持續監督醫發基金之使用,讓金門醫院持續改善醫療品質。","推動金門醫院成立坐月子中心,以服務為導向。","推動中風醫療中心及中風患者專門復健專區,提高中風患者治療效果並減少家屬辛勞。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7020ad6f-463f-4af8-ba18-568c617151dc","items":["努力爭取婦女、弱勢、殘障及老人福利與權益。","強化安全防護網，保護弱勢與婦幼。","維護教育環境，提升產業競爭力。","監督施政措施，捍衛縣民權益。","建設健全環境，帶動產業發展。","落實無差別服務，建構社區好生活。","專職民代、專業問政、嚴審縣府預算、協助弱勢族群、爭取社會福利、反映民意、效率服務。","持續推動增編社會福利補助，讓老有所終、壯有所用、幼有所養，減輕年輕人負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"702f6bc1-0726-4e3c-b685-fd5cb3ebd181","items":["重嘉自踏入社會，便體會到目前的社會，在政治上有君不君、臣不臣的問題，民主的國家人民做主，但是選出來為我們服務的公僕卻沒有做好他們該做好的事，因此在有機會參政之後，便以我在IT與公司管理上的專業提出「確實」、「有效」、「透明」、「負責」做為基礎的原則。重嘉要求縣府在處理民眾事務及推動縣政的時候要確實，提出的政策或解決方案要有效，在決策及執行的過程要公開透明，並且在最後不論結果好壞都負起該負的責任，同時我也這樣的要求自己，在執行議員的職責時做到「確實」、「有效」、「透明」、「負責」。","這幾年來縣府的政策，有些重嘉認為不對的，會在議會裡阻擋，有些擋得下來，有些擋不下來，也推動了許多重嘉認為是對的政策，這些政策有些沒有重嘉是不會有的。重嘉不選縣長所以無法開支票，只能保證如果有機會會繼續做好議員的工作，誰做縣長，重嘉都會站在縣民這邊，把關預算、監督縣政、為民服務及協助縣府擬定建設彰化的好政策。過去重嘉曾提出工作及食衣住行育樂的「30分鐘生活圈」規劃，從卓縣長到魏縣長，縣府仍認同與支持。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"7033acd5-56c5-4ed3-b869-3f8f17b5cc91","items":["推動８座特色公園","黃金海岸廊帶觀光公園","托育補助提高至8,500元，育兒津貼提高到5,000元","安平跨港大橋興建、臨安橋改建、華平路拓寬","喜樹灣裡市地重劃動土，促進經濟及人口發展","推動觀光發展特定區，串連濱海景點","落實居住正義，推動社會住宅-開南安居己動工","班班有冷氣→改善校園電力系統及冷氣裝設","大家一起來跑步→學校跑道整建工程","讓學生吃得更健康→改善中央廚房設備","讓孩子從遊戲中啟發→學校遊戲場改善","學習無障礙→改善學校視聽設備"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"7033b37d-bd55-40b0-b2ef-1014111f1045","items":["爭取地方建設 智慧交通 讓南區發展持續前進：監督加速大車站計畫與落實後站都市計畫及周邊發展","爭取地方建設 智慧交通 讓南區發展持續前進：爭取青草湖停車場閒置公共場域再活化，水域活動附屬設施再升級","爭取地方建設 智慧交通 讓南區發展持續前進：持續推動南門市場活化，打造觀光人文聚落新地景","爭取地方建設 智慧交通 讓南區發展持續前進：爭取南區智慧交通計畫，改善南區交通","爭取地方建設 智慧交通 讓南區發展持續前進：持續爭取南區¥ouBike2.0站點增設站點","爭取地方建設 智慧交通 讓南區發展持續前進：持續爭取增加南區藝文活動","爭取地方建設 智慧交通 讓南區發展持續前進：爭取增加南區圖書資源","提升老人婦幼弱勢權益美好新竹：持續爭取南區公托、臨托，平衡區域托育需求","提升老人婦幼弱勢權益美好新竹：持續爭取學區通學步道","提升老人婦幼弱勢權益美好新竹：爭取親子館南區分館","提升老人婦幼弱勢權益美好新竹：持續爭取早療及特教教育資源及補助","提升老人婦幼弱勢權益美好新竹：爭取增加南區早療據點及特教課後照顧增班","提升老人婦幼弱勢權益美好新竹：持續爭取公共場所友善哺乳空問與親子廁所設施","提升老人婦幼弱勢權益美好新竹：持續爭取敬老愛心卡增加使用範圍","提升老人婦幼弱勢權益美好新竹：持續爭取多功能社會住宅，打造老幼共托的社宅","提升老人婦幼弱勢權益美好新竹：營造友善失智症照護環境，擴大失智症社區互助系統"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"7080d754-7dfd-4624-b2d6-8465f9da05a1","items":["爭取共構仁武區第三間派出所及社會青年住宅","加速推動仁武產業園區進度","推動大社觀音山國家風景區","推動大社九十八公頃區段徵收","推動大樹區自來水廠為文化觀光古蹟景點","監督鳥松捷運工程進度及爭取規劃延伸路線至仁武、大社","推動升級路口監視器車輛辨識系統 創造青年就業環境,產業優先錄取在地青年 落實社會福利政策,扶助身心障礙、老人獨居及中低收入之關懷措施","推動爭取警察執勤專用個人急救包","督促推動捷運楠梓五甲線並連結仁武區域公共交通運輸網.解決交通顛峰塞車情形","極力爭取開闢國道 10 號大社交流道,讓大社.仁武.鳥松.大樹四區生活區車輛流動更為順暢","爭取仁武區國民運動中心.讓大社.仁武.鳥松.大樹居民有安全完善的運動環境 2030 中央雙語教學環境.爭取開辦雙語實驗國小","推動規劃一里一親子共融特色公園,設置寵物活動區域"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"70dd7a7e-8b53-46ac-b768-0cb883ecd274","items":["人本交通：黃捷挺黃捷！加速推動黃線捷運。","人本交通：改善行人無障礙通行環境。","人本交通：道路權益平等，改革交通設計。 兒少權益","人本交通：確保托育品質、訂定把關機制。 藝文體育","人本交通：推動運發基金、改善澄清湖球場。","人本交通：山岳安全與教育、海洋旅遊與水域解禁。","人本交通：推廣鳳山黃埔新村、明德訓練班及台鐵高雄機廠文資。 動物保護","人本交通：爭取寵物友善空間及設施。","人本交通：訂定寵物臨終制度、修正野保相關條例。","人本交通：多次揭露動物虐待事件、捍衛動物權益。 居住正義","人本交通：推動房屋稅制合理化。","人本交通：保障租屋族權益。 守護勞工","人本交通：挺社工！杜絕回捐、補強勞檢。","人本交通：爭取警消設備及休假制度。","人本交通：處理勞資爭議、改善勞權。 環境永續","人本交通：實質改善空污、燃煤機組除役。","人本交通：鳳山溪水污染管制與改善。","人本交通：制定韌性城市與淨零碳排。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"714806f6-6a43-4f3d-8edc-c40ff6271e06","items":["幸福加倍世代宜居 挺青年顧老年・青銀共好 青年更宜居 勇敢追夢－持續增加社會住宅、包租代管及租金補貼；推動居住正義。增加青創基地、提供補助及無息貸款；推動青創加速器及創業天使基金 安心生養－公共化幼兒園比例提升、兩歲班增班、增加公共托育機構、佈建兒童及親子專屬運動設施 銀髮更宜居 健康老化－廣設銀髮體健設施、運動中心設置高齡運動空間、銀髮運動及健康促進課程擴大開辦 樂活老化－增設長照機構及日照中心、全市公共場所無障礙化、敬老卡擴大使用範圍","都市更新動能加倍 臺北全面都市再生 都更人力加倍，廣設工作站，推動公辦都更及整建維護，老屋改建、老公寓補助加裝電梯 進行全市都市計畫通盤檢討，搭配公有建物改建盤點地區發展議題，提升公共設施水準","公共建設效率加倍 臺北邁向永續發展城 海綿城市加倍推動，減少淹水保障市民生命財產安全 要求公共設施通盤檢討，增加公園及綠地 要求兒童遊戲場安全零容忍，全面通過安全檢驗 加速環狀線核定完工，推動東環段，松山信義便捷加倍 推動人本交通，人行道、道路全面優化，併同增加停車格 自行車道及路線檢討優化、提升公車安全，推動綠運輸","進步價值加倍推動 讓臺北名列全球城市 推動臺北城市美學，改善市容景觀雜亂，設計融入生活 推動城市行銷，推廣松山信義景點商圈，振興經濟及發展 成立國際事務局，臺北成為外籍人士友善城市，走向國際 智慧城市更進步，提升資訊安全、推動智慧便民服務 動物權利更進步，動物之家加速改建、廣設動物友善空間 完善新移民政策，強化新移民權益保障及照顧"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"715f072a-fc2c-4079-b6dc-932ecea4717e","items":["督促儘速完成台鐵地下化及捷運路網、規劃桃園中壢平鎮八德環狀路網；加速道路系統開發、儘速完成龍慈路銜接66快速道路第二期工程、打通龍南路（新生路－宵裡大池段）。新闢紓解中央大學、六和中學、復旦中學暨育達中學之道路系統－復旦路三段、四段之新闢道路；加強道路鋪設品質及坑洞機動修補大隊；增建人行步道及停車空間。","督促市府預算編列符合公平正義，加強身心障礙的就業及就養服務，增加喘息服務、早期療育及建構完善長照體系；督促桃園市轄醫療院所增設友善病房，減少病患看護負擔。","提升教學品質，加強國語文教學、健全教育體制，落實國中小階段多元學習及體健活動，增加程式語言教學；高中教學著重適性探索與發展、加強大學高等教育專業人才培育；增加藝術人文、健體之課程及師資，打造AI研發創業環境與能力。","加強環境保護、河川整治、空氣污染防治及維護集水區水資源永續發展。","區域排水應跨越都市計畫限制，土地重劃及建照發放應增加區域排水系統審查；加快污水下水道建置期程及後巷道綠美化；爭取全面電線電纜地下化。","督促加強取締毒品製造及販售、嚴格打擊網路犯罪，維護治安及民眾生命財產安全。","協助農民加強農、畜牧業之產業升級，推動循環經濟、減少甲烷排放，強化農業全球競爭力。維護農地安全，嚴格取締農地污染、確保糧食安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"719e70bf-fd0e-4da2-96a8-c57d030d2560","items":["新北市烏來南勢溪溪水引流至石門水庫會衝擊當地生態平衡，新北市政府應廣納民意，重新思考。","翡翠水庫集水區相關管制應以人為本，重新檢視相關法令，讓集水區居民生存權益人人平等。","新北市新店都市計劃新店溪右側已發展極致，新店溪左側(部分新店都市計畫及安康都市計劃)督促 新北市政府在本席歷經多年對安坑對外交通堵塞問題極力反應爭取，交通部重新規劃檢討安坑對外交通 系統後，並闢建安坑安一路連接安坑交流道，原垃圾專用道，改為一般道路(祥和路)及興建中安橋與規劃安康輕軌(擬於111年12月底通車)供市民對外交通使用，安坑交通徹底解決後，如何在創造大新店地區\"暗坑\"成為\"安康\"的第二城市。","重新檢討新北市育兒、婦幼政策，讓新北市剛起步創業之青年新婚男女無後顧金之憂。","第三屆市議員因行政作業程序未完成尚未兌現的政見繼續執行。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"71ec2669-0da5-4e38-835a-3745790732e7","items":["核心的理念：營造韌性而不任性的市政建設，重視均衡而不抗衡的社會發展。 守護的願景：住行寬心、環境放心、食品安心、生活順心。 具體政見說明： 1.住行寬心： ‧協助老舊房屋及市場改建，強化居住安全、改善市容、提升都生活機能。 ‧檢討不合宜的道路標線及植栽，讓視線無死角、動線更安全，達成全齡友善的交通環境。 ‧山區聯外道路邊坡之風險評估及檢測再強化。 ‧為日益普及的自動輔助駕駛車輛，提供清楚可靠的道路標線。","環境放心： ‧坡地社區之地層穩定性及安全性加強監測。 ‧老舊擋土牆、堤防及橋樑加強體檢維護。 ‧因應極端氣候衝擊，強化防災及災後回復能力。","食品安心： ‧修改新北市食品安全衛生管理自治條例第6條、第11條，將目前極為多元的食品業納入規範，並強化市府「下架黑心商品」的公權力。 ‧拒絕有安全疑慮的食物進入校園及市場。","生活順心： ‧因應超高齡社會來臨，各項建設應考量年長者人體工學及需求，降低意外風險。 ‧提升在地學校特色、優化辦學品質，讓學子不用捨近求遠、跨區就讀，減輕舟車勞頓之苦。 緬懷唐慧琳議員，其生前所遺留的優質政見，將力促實現。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7237c093-96b7-4755-bc29-ad8abcefeb96","items":["福利權益： 1.要求提高各項補助、急難救助並簡化程序及降低條件。","爭取提高原住民族國宅配比、租屋補助、購屋利息補貼。","爭取增加建構及修繕住宅補助戶並提高補助金額。","敦促市府提高「敬老愛心卡」每月補助點數並擴大使用範圍。","監督落實「新北市保障原住民族就業自治條例」。","健全制度： 1.推動成立公法人「新北市原住民族基金會」，推動就(創)業、長照、教育、居住、法律扶助、語言文化，補足行政資源缺漏。","爭取開辦「原住民族微型保險」，並串聯原家中心、文健站、原教中心、語推人員、就服站、各族群團體、信仰組織，建構完整原住民社會安全網及文化經濟支持體系。","成立原住民族青年服務小組及青年論壇，關注青年族人議題，並分項輔導及培植原住民族青年卓越人才。","監督各項補助及經費公平保障支持多元信仰。","爭取補助族群領導人公共事務費用。","文教體產： 1.監督市府獨立編列常態預算辦理各族群文化祭典、各區歲時祭儀；配合各協進會、同鄉會等人民團體，辦理文化及傳統技藝活動。","爭取挹注經費發展原住民族文創產業及農特產市集，設立交流平台並推廣工藝師制度，辦理文化尋旅相關活動。","爭取新北市原住民族生育津貼、育兒津貼及幼教補助。敦促增加公托原住民族生錄取名額。","擴大體育發展預算，培育原住民族運動人才。訂定獎(補)助辦法，補助原住民族體育生相關器材費、訓練費、營養費、教練費。","敦促市府定期辦理原住民族各項傳統競技及專長運動項目活動，並提高全原運等賽事獎勵金。","整合跨局處資源建立小農、工藝、文創、觀旅等整體原住民產業創就業輔導平台。","原鄉建設： 1.配合區公所推動發展全區文化觀光產業，推廣一部落多休閒。","爭取建設烏來泰雅文化園區，整合資源、建構各部落傳統市集及在地商場。","爭取各項地方建設及產業發展預算，支持各部落及社區推動總體營造。","敦促完成烏來區內聯絡道路、景觀道路。極力爭取各產業道路改善工程。","爭取原鄉泰雅山徑重建及各里舊有登山步道再造工程預算。","監督越域引水計畫進程、捍衛部落權利，守護泰雅山林。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"727a7b3f-4fc2-4a5f-909b-a924c61ecdea","items":["堅持居住正義：社會住宅、包租代管，降低青年負擔。危老重建，提升居住品質。","堅持居住正義：人本交通、道路平權，持續建設捷運，建構完整安全大眾運輸網絡。","堅持居住正義：推進動物之家改建計畫，提升收容品質。","堅持居住正義：監督淨零碳排政策落實進度。","堅持居住正義：持續推動市場改建及食安認證，確保大台北食材安全。","堅持居住正義：落實性別等教育、本土語言教育、反霸凌教育。","堅持居住正義：提升北市公有藝文場館、運動場館硬體設施及服務品質。","堅持居住正義：捍衛台灣主權 民主良善治理","堅持居住正義：落實政府資訊公開。嚴格檢視政府預算，堅守廉政規範及財政紀律。","堅持居住正義：推動台北與日、韓、歐美、東南亞城市外交，讓世界認識自由民主臺灣。","堅持居住正義：刪減浮濫編列的中國交流預算，並禁止公職人員接受中國官方招待旅遊。","堅持居住正義：保障基本人權 多元平等尊重","堅持居住正義：捍衛勞工合法權益。","堅持居住正義：爭取閒置校舍設置幼兒托育與長照中心。","堅持居住正義：資料治理法制化，保障市民資訊自主權。","堅持居住正義：強化消保機制，維護消費者權益。","堅持居住正義：不分性別、性向、族裔，爭取LGBTQ、新住民、移工享有平等的尊重和制度支持。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7287348c-22a0-4f41-8d7d-819690364851","items":["推動內閣制，終結現行有權無責的民選皇帝制。","全面恢復小三通與大三通，重啟兩岸對話，避免戰爭。","NCC打掉重練，終結目前政媒勾結的不當現象。","因應少子化，第三胎生育補助100萬元。","響應AI崛起，推動AI教育全齡化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"72bb76e0-5867-4dce-b44e-808cd5e1a912","items":["要求市府統籌公務空間有效配置，落實公托、公幼、青銀共融專用友善環境，將里民活動中心正規使用。","要求全市推動「通用建設」，打造無障礙環境。","延續爭取學校基礎建設、教學設備提升所需的經費。","加速推動在地學校雙語教學提升學生語文能力。","擴充優化圖書館閱讀環境、提升館內設備全面e化。","爭取經費協助地方廟宇文化延續傳承。","要求擴充衛生單位的編制及業務項目內容，落實特定傳染病的防治措施。","增設優化全區監視系統，維護治安保障居民安全。","有效配置交通運具，提升偏鄉基本權益，建立龍井區東西向居民生活圈專用道路。","打造區內觀光特色景點，串聯旅遊環線創意行銷。","爭取公設用地以多目標用途，設立運動休閒館。既有運動場地增設風雨球場。","配合農會推廣智慧農業、創造多元行銷，提升農民收入。","持續要求關聯工業區二、三期公設開發，大肚山上6里(新庄子、蔗廍新訂都市計畫)產業專區、及新訂烏日(溪南產業發展特定區計畫)加速設立。","打造龍井區山、海、行政、都會區完整友善的宜居環境。","監督台中市政府以公正、公開、透明的方式，持續辦理大肚山上6里(新庄子、蔗廍新訂都市計畫)。","爭取東海里納入都市計畫後，居民既有的權益。","完成龍井建設藍圖、連結大肚地方開發、加速烏日創新門戶。 更多資訊請上FB，搜尋「林孟令-聽您命令」"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"72c762be-1e05-4ff9-9b66-f492d5f4befb","items":["優化・強化・深化 以戰鬥力・執行力・親和力來建設新時代的富麗金門 「優化」金門聯外交通・「強化」金門醫療照護・「深化」金門觀光資源"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":10,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7364317c-1f52-4f8d-9789-f05042acfdc0","items":["交通與城市發展：爭取交通部整合相關資源及補助，改善新竹市交通問題。","交通與城市發展：爭取教育部擴大新竹地區通學專車補助。","交通與城市發展：修正《財政收支劃分法》，提高新竹市統籌分配款。","交通與城市發展：爭取提高竹科回饋金比例，促進共榮發展。 勞工正義","交通與城市發展：督促勞保改革，確保勞工權益得到充分保障。","交通與城市發展：勞保改革方案完成立法前，每年至少撥補1千億元，填補勞保缺口。","交通與城市發展：強化在職訓練，協助各種勞動者提高工作能力，進而提高勞工薪資。 廉政治理與打詐","交通與城市發展：全面檢視政府重大標案，揭發弊端，確保透明、廉潔。","交通與城市發展：督促政府強化打詐策略，提高打詐成效。 長照","交通與城市發展：推動法定長照安排假，30天有薪假加60天彈性請假。","交通與城市發展：提高家庭長照特別扣除額至24萬元，減輕長照家庭負擔。","安心教育：推動國民教育年齡下修至5歲，讓幼兒獲得更好教育資源，減輕家長育兒負擔。","安心教育：制定《學校供餐法》專法，完善校園供餐體系，確保供餐品質及食品安全。 青年支持","安心教育：督促社會住宅加速興建，爭取就業青年房租補助門檻降低。","安心教育：爭取青年就學貸款全面免息，延長還款年限，減輕學子經濟負擔，協助青年就業和創業。 居住正義","安心教育：要求盤點國有閒置土地，嚴格規範國有土地標售，大幅規劃社宅用地。","安心教育：督促全面檢討社會住宅實質進度，加速提升達成率。","安心教育：完善租屋實價登錄制度，租賃市場資訊全面透明化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"73eaf979-cf66-472c-9027-ac255fbbabbc","items":["汰換自來水老舊管線，優化供水系統。","推動公立國中、小全面雙語教學。","爭取多面向運能，便利通勤。","持續推動危老都更。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"742402de-9a7f-425d-b965-de25da677492","items":["【地方產業與在地創生】：推動科技和文化基礎的產業轉型，提供全方位創業支援，同時開放資源和媒合平台協助創業，將基隆打造成一個對新創友善的環境，為城市的產業結構注入新活力。","【改善教育風氣並引入外部資源】：引進優質的教育資源，促成大學與高中職合作，同時接軌國際線上課程，並爭取經費提升學校數位設備，同時開放家庭數位學習器材租借補助，提升教育品質與學子們的資源。","【交通資源整合與現況改善】：優化市內外公共交通，改善道路設施和交通燈調控，同時鬆綁市公車及客運法規以提升服務品質，減輕通勤者負擔，並確保城市發展的命脈。","【工作機會及勞工待遇提升】：透過產業改革和吸引投資增加就業，並修訂法規以改善勞工權益和待遇，打造公平且受尊重的工作環境，並提供多元化的工作機會。","【幼兒公／私托及資源】：基隆近年為全台生育率最低，我將推動增加公托和建立友善育兒環境，如公共設施、相關補助以及友善店家政策，並鼓勵雇主提供育兒福利，同時協助家長重返職場，以解決年輕家長的經濟壓力。","【城市品牌打造】：致力打造智慧共榮城市，推動綠色載具和能源轉型，並由港口出發放眼國際，強化基隆的城市品牌元素，推動國際形象與國內行銷策略；基隆自古以來就是國際貿易的樞紐之一，在當今的世界中，基隆應該走向嶄新的道路，開創自身在國際市場上的可能性。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7474379b-d508-457f-93cc-ee63a51a5644","items":["復興各族群母語保存及推廣。","推動詔安客家族群文化發展，為詔安文化延續、教育建言地方文化保護法，爭取補助經費。","推動公共空間場域、WiFi 建置，把科技資訊系統建構社區居家安全，監控弱勢者的遠端看護、關懷老人照顧。","極力爭取農水路改善，農水路是農民的生命路。","推動濁水溪有古老文化底蘊的三鄉鎮（西螺、二崙、崙背）之人文藝術生命及推廣常態活動。","爭取建言國土政策中之雲林縣農業土地保護面積能降低比例，促進地方經濟。","濁水溪是台灣的母河，保護濁水溪自然生態、關心瓜農發展並督促相關單位整治揚塵的空污問題。","爭取農民減免地價稅及房屋稅。","推動建構區域治安科技行車軌跡辨識路口監視器，加強警民合作，打擊犯罪。","爭取區域易淹水區域及農田排水：新庄子、西螺線大排、舊頂埤投線大排、甘厝線大排、大義崙大排、八角亭大排、南大義崙大排、田尾大排流域治洪經費整治。","結合不同部會長照資源，加大力道串聯資源進入各社區，造福更多長者。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"748a57ef-a5cd-48d4-9689-9f77908d86de","items":["廣設停車格位，強化公車網絡。","道路標線改善，推動汽機車平權。","要求設勞工處，協助勞工組工會。","保障警消權益，勞檢納入招標協議。","推動囤房稅收，抑制投機炒作。","正視青年成家，督促社會住宅。","避免浮濫迫遷，完善包租代管。 拒絕稅金亂花，杜絕不當關說。 線上陳情，王浩服務不分大小。 打造重視本土語言、多元文化的友善城市嘉義市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7566783b-0637-4228-a61c-07262019e640","items":["修改政黨法，政黨名稱不得冠有他國國名，或足以使人誤認為他國之政黨。","推動國營事業及機關正名，鞏固台灣主體性。","檢討區域及不分區立委名額，充分反映多元民意。","立法院應邀請總統進行國情報告，依憲法精神不答詢。","縣市議會增設不分區政黨代表席次，以利青年及專業人士參政。","社會安定、保障民生：打詐用重法，電信公司應建立查核及調查機制，如有疏失應負連帶賠償責任。","社會安定、保障民生：提高公糧收購價格，每公斤增加3元，每4年定期檢討；公糧收購納入有機米。","社會安定、保障民生：各類社會保險投保年資併計，政府應負最終給付責任。","社會安定、保障民生：堅決反對重啟核四。","社會安定、保障民生：督促未來5年6,000億元建設： ◎ 改善國五壅塞：北宜高鐵10年完工，爭取第二條北宜快速道路（台62線），台北－礁溪55分鐘。 ◎ 加速完成鐵路高架。 ◎ 加速台2庚山腳觀光道路開闢。 ◎ 加速國5銜接蘇花改，解決蘇澳市區塞車；東澳－南澳路廊截彎取直，蘇澳到花蓮1小時。 ◎ 加速縣內四縱六橫交通路網建構。 ◎ T-PASS通勤月票常態化。","社會安定、保障民生：爭取陽交大醫學院遷校宜蘭，增加經費改善醫療設施，提升醫療品質成為醫學中心。","社會安定、保障民生：爭取成立「宜蘭國家風景區管理處」，推動宜蘭溫泉大縣計畫，發展觀光。","社會安定、保障民生：爭取老舊漁船收購、釋出船席，發展海上休閒運動。","社會安定、保障民生：爭取宜蘭治山防災及橋梁改建，加速蘇澳分洪道工程、農路、野溪整治。","社會安定、保障民生：督促農業部應優先價購收回保安林地承租權，以保障林農權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"761223ba-0643-4947-98cb-df01e74d472f","items":["交通改善：捷運土城樹林線、三鶯線加速完工","交通改善：整治土城廷寮溝，延伸和城路連通至明德路","交通改善：開闢環大漢溪快速道路(台65通往桃園龍潭)","交通改善：推動三鶯大橋改建、汽機車分流維護交通","交通改善：加速土城第二(金城)交流道工程","交通改善：推動樹林、鶯歌鐵路立體化","交通改善：開闢土城-三峽堤外機車便道","教育&托育：增加國中技藝班數量，為孩子未來找方向","教育&托育：強化社會安全網，補足社工缺額，遏阻兒虐案件","教育&托育：增社公立托育中心、幼兒園、非營利幼兒園","教育&托育：推行分組教學‧因材施教，多元學習","教育&托育：加強學習落後學生補救教學","教育&托育：嚴防毒品進校園，推動設立毒品防治局","教育&托育：鼓勵全民體育，推動設立新北體育區","社會福利：持續興建青年社會住宅，增加包租代管型戶數","社會福利：落實長照2.0，增加老人安養院費用補助","社會福利：推動65歲老人免費補助假牙，開放敬老卡多元使用","社會福利：偏遠地區推動免費接駁公車","社會福利：推動學童免費營養午餐","地方建設：加速土城司法園區教育計畫，推動看守所原址變公園","地方建設：清查閒置土地闢建立體停車場，解決市區停車問題","地方建設：全面開闢都市計畫公園，閒置公有土地變公園","地方建設：推動三峽長福橋改建，營造周邊社區親水空間","地方建設：專案清理天空纜線，推動電杆地下化清理巷弄纜線","地方建設：推動危老建物公辦都更，維護公共安全","地方建設：樹林、鶯歌興建大型公立醫院","地方建設：催生三鶯美術館‧辦理大型國際展覽","地方建設：持續推動共融性特色公園"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"76167026-759b-40ed-92fc-0e7324ba07b2","items":["17 年來的公職服務生涯讓東昇深深了解,一個大有為的政府沒有最好、只有更好。","在花蓮縣的各項公共工程施工,不管在規劃設計階段到施工期程查估、完工驗收。一定要嚴格的監督,預防各項舞弊,要求達到最好的品質,絕不浪費公帑。只有縣市同心將花蓮市打造成友善宜居的國際型都會城市,讓全齡的市民們快樂生活。興建長輩華廈,備有最完善的公共設施、診所、藥局、長照機構,讓長輩們在地老化。打造初老照顧老老的大同社區。","花蓮縣政府打造出全國唯一有所有權的青年住宅,讓年輕人有一個家、創造自己的未來。現在要縣市同心、齊力打拼。在花蓮市公有地再造一個讓長輩們安心的花園城市。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"76be796b-ac61-46a2-aae2-61d8202d4d02","items":["強化青年返鄉的立足點。","數位游牧：老屋翻新使用，政府代為管理，讓屋子有人住、房租有得收。","青年住宅興建、租屋資訊透明化。","經濟｜發展慢經濟：營造生活共感的幸福步調。","經濟｜發展慢經濟：農業加工、觀光加值、服務經濟體精緻化。","經濟｜發展慢經濟：釋迦及其他臺東特有農作物外銷協助。","經濟｜發展慢經濟：保障生命安全的首要防線。","經濟｜發展慢經濟：醫護人員工作環境改善、空間軟硬體設施升級。","經濟｜發展慢經濟：民眾需求度高的專科引入，例如眼科、皮膚科。","經濟｜發展慢經濟：經濟鏈結留住人流與錢流。","經濟｜發展慢經濟：爭取中央持續補助臺東大型活動舉辦。","經濟｜發展慢經濟：推動一鄉鎮一亮點，促進城鄉觀光交流及消費。","經濟｜發展慢經濟：鐵路全面雙軌電氣化、直達班次增班。","經濟｜發展慢經濟：豐年機場改善、飛機班次增班。","經濟｜發展慢經濟：公路用路品質改善。","經濟｜發展慢經濟：綠島及蘭嶼等外島機場、漁港改善。","經濟｜發展慢經濟：創業環境及補助有效化。","經濟｜發展慢經濟：青年就業環境及工作自我價值提升。","經濟｜發展慢經濟：產業升級及價值再發掘。","經濟｜發展慢經濟：親子友善場域及小兒醫療品質提升。","經濟｜發展慢經濟：長照體系協助改善（機構、補貼及關懷鏈）。","經濟｜發展慢經濟：關懷新住民族群需求。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"76e0cd05-6a10-42c6-b427-47604441e7bf","items":["做事的好立委邱志偉，繼續為您顧高雄。 解決產業五缺，提高實質薪資，共創安居樂業","強化供水韌性：擴大開發海淡廠、再生水廠等多元水資源，提升供水備援調度。","完善防洪治水：確保北高雄河川及區域排水整體改善、水岸環境營造如期落實。","海線多元發展：推動漁業生技專區、遊艇產業鏈、漁港整建活化及環境再造。","提高農漁收入：擴大農業保險類別，加強農民福利措施及產業升級轉型輔導。","爭取投資高雄：推動橋科二期、聖森路、嘉華等產業園區，增加高薪就業機會。","加強產業政策：穩定生產要素供給，降低貿易障礙，強化地緣政治風險因應。 完備公共服務，充實文化建設，打造樂活社區","擴大設置定點臨托，育兒工作兩端從容。","爭取綜合行政中心，行政服務遍及鄉里。","充實社區長照量能，維護長者健康尊嚴。","醒村、樂群村活化推進，歷史記憶建構文化肌理。","糖廠增設森林碳匯教育館，綠色教育加值林業軌跡。","籌設岡山國際棒球村，春訓基地帶動觀光商機。","完善區域交通：落實捷運建設：確保岡山路竹延伸線和高鐵右昌學園線如期完工，串聯北高雄和東高雄生活圈，提供高品質捷運服務，打造宜居北高雄。","完善區域交通：強化區域路網：積極推動台39線南延仁武、台61線南延梓官、國1高科交流道東延台19甲線等公路設施，完善區域路網可及性，促進地方發展。","完善區域交通：改善交通體驗：爭取道路改善拓寬，提升道路品質，紓解交通壅塞，推動北高雄公路公共運輸服務升級計畫。 減輕家長負擔，打造優質校園，學校社區共好","完善區域交通：擴增公共化幼兒園，照護品質從嚴把關，減輕家長照顧負擔。","完善區域交通：提升教保人員補助，確保職場待遇合理，推動友善工作環境。","完善區域交通：爭取校園建設經費，串聯在地科技資源，營造科技教學環境。","完善區域交通：落實教育機會平等，協助社經弱勢學子，持續挹注獎助學金。","完善區域交通：善用學校在地能量，連結社區文化歷史，營造創生帶動就業。","完善區域交通：把關營養午餐品質，精進在地食材供應，擴大推動食農教育。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"770ca72a-cc35-4fd2-8a42-f7ed40d03109","items":["公園特色化：爭取大肚、龍井、烏日增設主題式公園如：兒童公園、生態公園、親水公園、寵物公園(無障礙公園)。","全民運動館普及化：體育即國力，爭取大肚、龍井、烏日設置全民運動館，補強基礎硬體設施提升運動風氣，催生全齡化運動場館，長輩青壯年孩童皆能就近運動。","學校交流國際化：推動大肚、烏日、龍井國高中小，積極締結姐妹校，透過實際交換學生或線上視訊方式與不同國家孩子交流，開拓視野，國際化生活化。","社區關懷據點老幼共融共學：有鑒於關懷據點成效亮眼，爭取推行老幼共融，共學社區據點，長輩參與活動時，同時有幼教老師帶領孩童共讀。","交通友善化：爭取人行友善及停車空間，檢討台中市相關交通法規及道路設計，降低車禍傷亡人數。","大肚山觀光風景區：完善周邊交通、觀景平台以台中市夜景為背景舉辦音樂祭等藝文活動。","地方特色商圈振興行銷再活化：東海藝術商圈，結合商圈特色及店家舉辦主題活動吸引人潮。","傳統市場年輕化：輔導傳統市場轉型，建立攤販會員平台等，提升傳統市場商圈永續發展。","協助農產品行銷：爭取輔導農業技術移轉，及建立農業產銷平台。","爭取落實身障者職務再設計：機關應主動宣導為身障者配置合宜的工作環境，並保障其尊嚴。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"77a86364-00b1-4113-ba7f-8163482d3f27","items":["工業區增加或機能提升、吸引企業投資產業發展。","就業機會增加、青壯年工作安心。","老有所養、落實多元社會照顧。","發展休閒經濟、農業經營轉型。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"77bfdda6-6ad0-4423-857a-1f400284a37a","items":["用政府閒置空間，增設公托幼稚園。","府施政建設，縣內郷鎮均衡發展。","民各項補助，改善農民生活品質。","支持縣政發展，監督縣府各項預算。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"77f4570b-c360-42d8-8738-7aa08b436d15","items":["以前我看到選舉公報裡的政見時，雖然每位候選人都洋洋灑灑列了一大堆政見，但如何具體實行卻付之闕如。在有限的表格空間內，我將最主要的三個政見寫上，其餘的請大家參見我的臉書專頁（搜尋: 詹為元 政治我們的事)","建立信任感 加速都更進度 台北市的屋齡已是六都當中最老的，四十年以上的老舊公寓佔了43.95%。而松山區與信義區的屋齡分列北市十二個行政區中的二、三名! 看著年長者面對老舊公寓「望樓梯興嘆」，擁有電梯的嶄新房子刻不容緩。都市更新除了容積獎勵以及釘子戶等艱難的問題之外，更重要的是彼此之間的「不信任感」，民眾不信任民間建商擔心他們私藏利潤，但政府主導的公辦都更又曠日廢時。因此，我提出的政見是導入都更中心成立第三方的監察與仲裁人的角色，透過專案式的管理進入每一個民間都更案，民眾有問題即可請教負責該案的都更中心官員，透過一定公權力的背書來降低民眾與建商之間的不信任感，加速都更的進行。","0-6 歲政府加倍養 公托再增設 目前政府育兒政策皆從補貼著手，但根本的問題還是學費太貴了。以目前兩歲以下的托嬰中心來看，公辦民營的托嬰中心雖然學費最便宜1.1 萬元，但松山區僅有85 位的名額，信義區更僅有40 位而已，根本不夠用。社區公共托育家園雖也是次便宜約1.45 萬元，但松山區只有2 家、信義區只有3 家，隔壁的文山區卻有10 家。準公共化的托嬰中心雖名稱有公共性質，但學費已飆升兩倍到2.1 萬元，更別提私立托嬰中心了。因此，我提出的政見是將托嬰中心市場化，價格較貴的私立托嬰中心自由發展，但政府應提供最低比例的的公共托嬰中心，例如仿照德國將幼兒的托育服務覆蓋率至35%，提供新手爸媽一個平價友善的托嬰環境。","毛小孩的保護與遊憩自由 動保警察設立雖是内政部的權責，但中央始終只聞樓梯響，因此台北市可以優先試辦成立，給予調查權，未來面對動物虐待情事可以更快抓到兇手；另外就是松山信義區的寵物專用公園太少了，幾個比較大的社區公園都應該劃定寵物公園專區，例如信義區中強公園、松山區敦北公園等以不影響現狀運動團體場地為主，讓毛小孩能解開繩子的束縛開心的遊憩。 剩下政見諸如推動台北成為NFT Taipei 的亞洲示範城市、加速Youbike1.0 與2.0 的整合、重視長者權益打造銀髮友善城市……請見臉書。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"780a7a83-f5be-492b-918c-c7de139b7cc0","items":["托育瑜你：打造托育友善空間：盤點閒置空間，做為社區托育與幼教場所，落實托育社區化。","托育瑜你：打造托育友善空間：輔導具有相關專業之公私立機構，經營前項托育空間。","托育瑜你：打造托育友善空間：增設特色公園與綠地，擴大市民休憩空間。","托育瑜你：打造托育友善空間：國小國中教育配套銜接，讓孩子們可以在地長大。","安養瑜你：老人日照長照社區：盤點閒空間，作為微型化日照據點，延緩長輩老化。","安養瑜你：老人日照長照社區：長照社區化，減輕小家庭經濟與交通接送因難。","安養瑜你：老人日照長照社區：協助社區增加活動中心，提供全年齡休息遊憩社交空間。","助青瑜你：產業翻轉升級：全面檢討都市計畫更新，讓城市發展符合地方需求。","助青瑜你：產業翻轉升級：推動文化內容產業，發展電商通路。","助青瑜你：產業翻轉升級：推動在地青創基地，支持青年創業孵化夢想。","助青瑜你：產業翻轉升級：推動智慧城市與產業創新園區，發展智慧產業。","文化瑜你：找回歷史文化記憶：地方建設與產業轉型，以文化與歷史，向下紮根。","文化瑜你：找回歷史文化記憶：歷史遺址轉型公園化，串聯交通建設，彰顯在地人文價值。","文化瑜你：找回歷史文化記憶：盤點舊古道，轉型親山步道。","文化瑜你：找回歷史文化記憶：以文化和歷史結合地方創生，留住人才，讓地方生生不息。","交通瑜你：暢通道路、網路、通路：爭取道路、產業道路、停車空間場域、公車路線等交通基礎建設，讓市民行得便利。","交通瑜你：暢通道路、網路、通路：強力要求完善電信收訊、網路等基礎建設，保障市民通訊，提升在地數位力。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"781402b4-7d1b-451d-8735-8e3a205d0824","items":["將「初心」與「愛心」相結合，推及到「老吾老以及人之老，幼吾幼以及人之幼」的精神。","監督拓寬芒果大道，串聯虎尾市區及高鐵特定區盡速完成，讓虎尾市區與高鐵合而為一。","監督台大虎尾院區二期擴建醫療大樓盡速完成。","監督虎尾農博園區新建布袋戲傳習中心盡速完成。","爭取增加安養照護及日間托老中心，建立完整的銀髮照護系統。","整合「虎尾、土庫、褒忠、元長」為「區域發展聯盟」，朝向區域型規劃，用共同發展的方向前進未來。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7821a21d-4bd4-4666-a5f7-b5302ab5b9cd","items":["未來將極力爭取 1.推動新北智慧城市 打造智慧城市生態系，做到便民利民的科技城市。","顧好下一代教育 增加教保員師資名額，讓每一位教保員照育3或4位小朋友，加強監視系統，保護幼兒及教師安全。活化國中小學閒置教育，增加公托與課後輔導以減輕家長負擔。","幫助青年人解決就業、創業和住房問題 推動產官學合作共推在職訓練專班協助青年增加斜槓與職缺技能；增加重劃區興建青年社會住宅的比率。","推動全方位照護長者 爭取捷運站共構大樓與區域行政中心設立日照中心，並在每里設置關懷據點提供關懷、訪視、共餐等服務，讓長者就近照護。","加強地方建設，提升市民生活品質 爭取閒置空地規劃藝文中心，提供優良展演舞臺及藝文欣賞空間；建立客家會館，發揚客家文化促進多元交流的重要基地；監督徵收都市計畫公園預定地進程；規劃區域醫院讓市民方便就醫；建立深水游泳池強化救生訓練；新增機車考照練習場，方便考照者練習。","讓市民安心登山 推動新北登山步道總體檢，確保各個登山步道安全及休憩設施完善，優化山區訊號為消防爭取搶救時效，維護良好的登山環境。","加強社區消防安全 定期舉辦消防安檢與消防講座，讓市民瞭解消防器具使用。","打通交通瓶頸 土城 一.打通和城路延伸到明德路，疏解捷運施工造成的交通壅塞。","監督興建金城交流道進程，早日完成通車以疏解交流道車流。 樹林 一.監督捷運萬大樹林線工程，提早動工。","推動樹林鐵路地下化。","監督台65線銜接浮洲橋工程，並加速落成啟用。","爭取活化後站空地興建為公有停車場。 三峽 一.爭取土城環河道路延伸到三峽大橋。","仁愛街打通延伸至文化路復興路。 鶯歌 一.爭取鐵路改善，截彎取直不入市區，無平交道零事故。","爭取增加鐵路首發車。 為你‧衝第一"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"78320f8d-e360-4dca-ac97-0b406f86de0e","items":["爭取65歲以上長者健保福利金補助。","有一間國中就有一所日照,一區一日照擴大為一學區一日照,數量翻倍照顧更多長輩。","小黃公車增加醫療院所與廟宇景區路線,方便長者看病買菜還可出外遊覽。","持續強化長期照護、低收入戶、身心障礙者,協助社會安全網建構與關懷服務。 爸媽負擔少","爭取台南市生育津貼第一胎20000起","一區一公托家園,0-2歲托育高品質低收費,讓國家一起幫忙養。","一區一特色公園,好看好玩的新型態公園,孩子放電最佳首選。 青年有人罩","爭取市政府自編租屋補貼預算,優化流程放寬標準認定從簡。","成立青年事務局,鼓勵青年回鄉創/就業,爭取大北門創新育成基地成為青創企業的孵化器,並提供青年創業貸款優惠。","職訓再升級,增加社群自體課程,開啟青年斜槓人生,找到人生不同可能。","保障婦女生育補貼及設公辦托育中心加強新移民生活輔導,擴大就業機會。 運動身體好","積極活化大北門區市民運動空間,爭取風雨場地、更新現有室內場館設備,以多功能球場為主要訴求。","爭取大北門國民運動中心與藝文展演中心設置,促進各年齡層運動強身與美學建構養成。 治水沒煩惱","滾動式檢討區域治水成效,強化水利監控防患機制,定期疏濬、清淤以杜絕水患。","臨時抽水機升級為抽水站,加速推動學甲工業區M幹線、營後排水抽水站,內水排得快,外水進不來。 大北門更好","爭取台61南延,四橫三縱路線連接,往返台南更方便。","大北門六區一體,強化共同生活圈,橫串連整合區域亮點,打造幸福北門郡。","振興地方經濟,提高就業機會,促加智慧產業園區、科技工業區開營運。","推動大北門區國旅亮點串連計畫,結合民俗慶典、農漁特產與文創產業、漁港鹽田、微型企業,打造濱海旅遊廊帶的主題地景觀光軸線,吸納人流與人才。","監督政府建設算精準投放,平衡溪北地區交通、文教、遊憩資源的城鄉差距,建立均衡平等、機能互補的共同生活圈。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"78329738-161c-4ee4-bbba-4877c5815be8","items":["竿示範住宅之興建，解決鄉民最迫切的住屋需求，以維居住正義。","委、縣府爭取北竿機場擴建以及南北竿大橋之興建，以提昇地區長遠發展。","照南竿福利園區，設置大同之家，讓長者老有所養。","強北竿道路網之綠美化工作，以及規劃林相更新，以厚植觀光實力。","同風管處針對壁山觀景台及停車位置加以規劃設置提昇觀光形象。","竿室內多功能展演館，活化地區藝文生根工作。","理北竿全區都市計畫通盤檢討，以促進土地有效利用，活絡地方經濟。","北竿中正路老舊國宅進行安檢，並規劃都更之可行性，以維居民安全。","塘岐怡園至馬鼻灣濱海道路，讓重型車輛、貨、卡車改由該路段行駛，以維街道","北竿塘岐老人活動中心，讓長者能有個安全舒適之休閒場所。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7856fab8-05ce-4d40-b23b-5f4b5ed09918","items":["長者福利好完整：敬老不能少：妥適發放敬老金，爭取設立祖父母節相關福利","長者福利好完整：照護要更多：利用間置空間與國有地等，爭取公有長照中心與老人住宅","市民權益好完整：居住正義動起來：落實增加青年社會住宅，因應物價設定合理房租","市民權益好完整：特色公園在旁邊：增加與更新公園設施，提升公園遊戲設施預算","交通網絡好完整：萬大捷運不延宕：捷運萬大線興建進度不延遲，確保如期如質完工","交通網絡好完整：增設社區交通網絡系統：照顧長者，配合公共運輸增設接駁與社區巴士","環境舒適好完整：老舊房舍不擔憂：加速都市更新，健檢老舊住宅，爭取撥補修繕預算","環境舒適好完整：艋舺公園要改造：綠地結合周遭景點、回復艋舺記憶，並協助無家者安置","環境舒適好完整：綠意盎然巷弄間：提升線地覆蓋與遊憩空間,推動淨零減碳","婦幼保障好完整：生育補助要更多：爭取每胎生育補助比照其他縣市達3萬元","婦幼保障好完整：晚歸婦女更安心：結合警政與24小時超商通報系統，打造夜間回家廊道","經濟振興好完整：傳統市場新思維：改善市場環境，增設市場行銷人力資源，提升消費力","經濟振興好完整：經濟大振興計畫：結合地方創生與在地故事，強化在地品牌促進觀光發展","教育政策好完整：公幼托兒要增加：爭取國有地與校園閒置空間，增加公幼公托班級與員額","教育政策好完整：雙語教學不能等：因應2030雙語國家政策，加強相關課程安排","教育政策好完整：共學廊道完整化：結合各方資源推動制定各級學校通學廊道，孩子更安全"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"787c4bc0-f36d-4d3c-a661-65a2fa648c94","items":["監督淡江大橋如期完工，疏解交通壅塞問題。","爭取淡水河北側道路盡速開工，解決台二塞車困境。","爭取淡海新市鎮設立（國、高中）完全中學，讓學子在地就學。","推動淡海輕軌完整路網，帶動北海岸整體觀光發展。","督促市府加速完成（四區）無自來水供水問題。","督促八里龍形市場盡速完工，提升居住品質及便利購物環境。","爭取三芝萬坪公園整體規劃及串連三芝後厝漁港，促進北海岸地方產業觀光。","督促石門十八王公整體營造盡速完成，爭取完整旅遊產業鏈，連結青山瀑布、百年梯田、富基漁港，富貴角燈塔等等景點，振興地方觀光產業。","推廣有機農業及活化農漁觀光之休閒產業，打造黃金北海岸觀光休憩新亮點。","監督沙崙文創園區BOT案建立海水游泳池，符合地方需求，串聯漁人碼頭，帶動周邊經濟繁榮，增加在地就業機會。","爭取危險或老舊之合法建築，提高重建各項獎勵及容積率。","爭取將（四區）閒置之公有設施，興建集合式社會住宅及規劃多功能活動中心【托嬰、托老、長照】達成在地安居，照顧地方需求。","爭取新北市政府成立體育局，為新北市各項運動委員會及優秀體育選手提供更多資源。","監督淡海新市鎮特定區第一期主要計畫後續規劃及淡海新市鎮特定區第二期開發進度。","推動淡水竹圍市場儘速興建，提供便利購物環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"78dbc686-092e-40a4-9baa-d0f5d8a2fd77","items":["打拼國會：專業問政，監督揭弊，顧民眾權益，向中央發聲，解決民生需要，爭取地方建設。","樂齡幸福：65歲以上免健保費，80歲以上長者免除巴氏量表，推動高風險癌症預防及放寬篩檢，疫苗及醫藥採購透明化，PM2.5超標縣市民眾，放寬低劑量電腦斷層掃描（LDCT）免費標準。","農業永續：解決農業缺工困境，適時隨物價調漲老農津貼，強化農產運輸公共設施，健全農村基礎建設，發展特色農旅休閒軸帶，定期調漲農業天災救助額度，為南投農產品找出路，讓農友有錢賺。","婦幼優先：0至6歲國家養，7至18歲政府扛，補助凍卵保障生育，提高育嬰留職津貼，擴大兒童疫苗補助，縮短公私立學雜費差距，縮小城鄉教育資源差距。","教育提升：教育改革，提升競爭力，強化科學、科技、結構、數學和藝術等學習。","南投啟航：打造觀光旅遊商機，開放陸客觀光，提升醫療院所品質，推動全民運動場館，廣設親子共融公園，繁榮客庄經濟，爭取中央經費推動重大交通建設，引進工商投資優先，驅動青年返鄉。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"79b3a3ea-f629-491c-8a99-eb027eaa6417","items":["全面檢討都市計畫並進行土地重劃，使土地更有效利用。","推動人才培育計劃，協助青年回鄉服務，解決地區人才斷層問題。","積極維護海洋生態資源，杜絕非法籠漁具捕撈作業。","政府有效運用公彩基金，擴建老人安養設施及推動各項社會福利。","興建停車場，解決民眾停車問題。","推動興建合宜住宅，解決民眾居住問題。","復興村入村道路，改善目前入村交通困境。","牛角大澳老街復興，增加地區具特色觀光資源。","保護馬祖戰地及閩東文化特色，強化內涵，以獨特性吸引觀光人","審查監督縣庫，為人民看緊政府的荷包。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"7b1bb143-d395-4753-9711-5e3bc35ef9be","items":["一 . 促進府會和諧,匡督縣政推動,力促行政革新,提高行政效率。","二 . 督促政府照顧老弱婦孺、身心障礙等弱勢團體,營造祥和、安康之社會。","三 . 促請政府廣設農特產展售中心,推動精緻、休閒、生機飲食結合觀光產業,創造就業機會,促進商機,造福農民。","四 . 促請政府在日月潭規劃世界級水上競賽活動,結合地方產業、藝術、文化帶動觀光發展。","五 . 促請縣府輔導各鄉鎮引進新科技,解決環保問題。","六 . 勤走基層、為民喉舌、爭取經費、建設地方、造福民眾。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"7b9c3b21-a259-4dbf-8793-10bfbd667248","items":["打造優質生活空間，增設公園及親水綠帶","爭取山仔頂新闢公二鄰里公園、高雙路底及陸光路舊營區改建新運動園區，增加城市休憩空間。","爭取平鎮區第九公墓興建公園及地下停車場，增加周邊遊憩及汽機車停車空間。","爭取老街溪河岸步道延伸至龍南幹線，連接龍潭成單車及步行綠廊。","道路開闢解決交通瓶頸，提升公共運輸效能","爭取平鎮民族路三段沿國道五楊段橋下空間新闢道路，紓解文化街及長安路車流。","加速推動金陵路五、六段替代道路新闢工程計畫，解決塞車問題。","爭取拓寬打通東光路201巷瓶頸道路，紓解東光路、平東路往來車流。","爭取廣北停車場改建為具停車場及商場功能的民族路轉運站，多目標複合使用。","爭取廣南停車場改建為BOT綜合停車場及商場多功能大樓。","爭取鐵路地下化後原鐵軌路廊改建林蔭大道，連結南、北桃園並增設車站周邊停車空間。","保障學童就學權益，廣設公幼","爭取大南勢地區文心路及南京路口新設國民小學，紓解周邊社區小學生總量管制難以入學之困境。","廣設公幼、附幼及非營利幼兒園並增加補助辦學，減輕家長負擔。","推動人本道路，爭取金陵路二段劃設標線型人行道，保障學童上下學安全及行人友善空間。","爭取加速地方建設及淹水改善","爭取中豐路、環南路旁設立南桃園行政中心平鎮行政園區，便利民眾辦公效率。","推動東豐路幹管接龍南幹線排水系統興建及改善桃園市龍潭、平鎮（山仔頂地區）都市計畫區雨水下水道系統重新檢討，解決山仔頂地區水患。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7baf56b3-7549-4fb8-9ab3-a8ddf13d7e8f","items":["成立台南原住民0-6歲幼兒托育照顧中心，增取相關托育補助，以減輕家庭照顧及經濟上的負擔，同時引進族語文化教育以達到傳 承文化語言之功能；","健全原住民長者照顧政策，除廣設原住民族文化健康站，協助關照長者的身心健康之外，也積極爭取長者之健康醫療補助，讓長 輩老有所依；","爭取建置「原住民族聚會所」，營造一個適合族人聚會與活動之溫暖安全的「家」，可做為部落大學、幼兒托育、長輩安養等生 活的場域，達到幼有所養、老有所依、老幼共學的目標；","爭取設置「原住民體育公園」或戶外適合大型傳統競技及球類體育活動之設施及空間，以積極推動族人健康運動之目標；","協助原住民各教會及社團辦理活動，以及增加相關補助經費，以積極發展原住民教育、文化及體育等各項活動，有助於族人身心 靈的健全照顧與發展；","建置台南原住民完善之健康醫療政策，尤其針對勞動之中壯青年族人部分，除了加強相關醫療與健康的宣導與補助之外，亦增進 相關社會福利補助之措施，以建構安全穩定之家庭照顧服務平台；","建置台南原住民勞工在就業機會、職能輔導、勞資協調、法律諮詢與溫暖陪同等全面性的服務平台，讓族人安心就業與生活，尤 其針對原住民青年及婦女就業部分提供更多的就職選擇與機會；","持續推動與建構更完善之民族教育政策，以及提供幼童免費之課後輔導，並爭取擴大學生就學（國中小及大專院校）相關補助以 及獎學金金額及名額提高，另外針對多元才藝的孩子給予多元智能培訓獎勵金，達到鼓勵與協助培育原住民多元人才的發展；","建構安全、便宜及便利之租屋平台服務，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。","持續推動「台南札哈木原住民族文創園區」工程，積極發展原住民族傳統與現代之文化、藝術、歌謠與舞蹈，並建構原鄉與台南 原住民農特產銷平台與據點，成為台南新亮點。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7beb0d2d-3cd4-40ec-b312-b3d4da75c2b4","items":["活絡三義、銅鑼、西湖三鄉鎮商圈再造，配合中央觀光政策強化在地休憩產業。","持續推動銅鑼科技園區產業進駐，鼓勵企業回饋地方、擴大在地就業、加強弱勢青年職訓輔導。","爭取設置南苗栗環保辦公室，逐年降低空污排放，監督縣內高汙染產業、惡意傾倒廢棄物情形，讓家鄉 永續發展。","持續降低農民負擔，輔導在地農業，保障農民權益、鼓勵青農返鄉，推廣休閒農業發展。","發揚苗栗在地特色產業，輔導青年回家鄉創業，活化苗栗產業競爭力，保障新住民權益。","力抗少子化，讓青年成家更輕鬆、減輕年輕夫婦養兒育女之負擔。","推動縣內雙語教學，督促縣府優化各級學校環境，讓苗栗學子未來不是夢。","服務處提供免費法律諮詢、解決民眾困難，定期公布問政報告。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7bfc192d-e933-457f-a961-426d6d47e4af","items":["建設鳳山車站6＋10層「空中鳳城」，打造全臺首座有影城、商場的車站，要求2024年底與大家見面！成為全臺第一個擁有電影院的車站，並提供商場、運動中心、空中禮堂、青創中心等多樣化的服務進駐。","成功招商三井LaLaport投資鳳山，陳其邁市長直言：「許智傑化不可能為可能！」打造佔地4甲多、建地2甲多，地上6層、地下2層的超大型百貨公司，帶來鳳山經濟好光景。","推動捷運黃線核定成功，要求2028年全線通車。並增加設計連接三井百貨公司、衛武營國家藝術文化中心及衛武營公園的地下街或地下聯通道。","推動高雄陸海空城市，督促高雄小港國際機場改造如期如質完成，各航線盡快復飛，以及打造高雄港埠旅運中心，吸引國際郵輪作為母港，發展觀光互動旅運服務。","推動國道七號核定，爭取1,537.9億元，督促114年動工、119年全線通車。","在立法院推動並通過長照及幼童津貼預算，照顧更多長輩和孩子們，並持續爭取長青照護、社會住宅及幼兒教育之社福預算與教育補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"7c155fa0-6215-44ac-9e8a-f3ca969e50d0","items":["教育升級 A++：多元樂學、教育科技：教育科技化、快樂學習有效率。","生活升級 A++：友善共融、特色公園：城市公園化、打造舒適森活圈。","交通升級 A++：暢動便捷、宜居城市：低碳智慧化、綠色交通好順暢。","福利升級 A++：老中青幼、幸福樂活：社福多樣化、有愛無礙好生活。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"7c2e0cd6-1221-40e9-a16e-c091f28bd21b","items":["繼續推動增設機車停車場及增設機車格，舒緩機車位不足問題。","繼續推動公立幼稚園及托嬰中心員額增加，並爭取學區概念，使孩子得以就近獲得照顧，不必奔波太遠。","推動集美街玫瑰停車場現址興建為多功能立體停車場，提供市民停車、休閑、集會等多元用途。","推動新北市創新育成中心，爭取免費或低價租金鼓勵創業。","推動三重第二行政中心及聯合醫院再增建新大樓服務鄉親。","推動長輩的幼稚園(日間照護機構)，協助子女照顧失能長輩。","爭取市府將各國小現有遊戲器材，汰換成共融式遊戲器材。","爭取捷運機場線A2a(博愛站)之設置。","繼續協助候友宜市長推動老舊社區都市更新，解決巷弄狹小、停車、危老建築、汙水下水道、電線地下化。","繼續爭取設置從三重忠孝碼頭到台北市大稻埕碼頭的行人及腳踏車便橋，聯結淡水河兩岸的大台北都會公園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7d167ab5-64ba-4ef1-a115-8241df0a7ab4","items":["迎新生命，深耕教育","照顧族人，爭取福利","文化傳承，身心凝聚","無論部落在哪裡，有你、有我，部落就在這裡"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"7d18f839-e0be-450c-b5fc-011cb2a36af6","items":["青年友善政策：落實居住正義，推動社宅四年8000戶，建立多元空間共享計畫。","青年友善政策：建立青年友善城市，推動成立青年事務局，整合資源孕育青創力。","青年友善政策：支持青年創業，成立青年創業基金，打造優質創業環境。","教育優先尊重文化：強化學校各項硬體設施，打造優質教學環境，提升教學品質。","教育優先尊重文化：實踐學校特色教學，創造學童多元學習環境。","教育優先尊重文化：推動國際、校際交流活動，開創學童視野與國際觀。","教育優先尊重文化：落實古蹟空間再利用，連結歷史及文化資產區域，再現土地與人民的歷史。","教育優先尊重文化：推動文化資產導覽系統，達成文化資產推廣及教育的功能。","教育優先尊重文化：因應環境氣候變遷，推動減塑政策。","教育優先尊重文化：持續要求減碳，嚴查空污，保護地球生存環境。","教育優先尊重文化：重視水土保持，推動成立國家自然公園。","教育優先尊重文化：推動在地特色大型共融公園，打造具有多元刺激、互動、有趣且舒適的遊戲環境。","教育優先尊重文化：海線雙捷運，捷運藍線四年內動工，捷運橘線通過可行性評估。","教育優先尊重文化：以輕軌連結海線沿途觀光景點，串連台中三井outlet、高美濕地、梧棲觀光漁港等景點，創造觀光產值。","教育優先尊重文化：清廉參選、重視民意，積極服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7d491561-1d25-49a6-96d2-3914ff81872a","items":["積極爭取公立托嬰及托育所,讓年輕夫婦能安心工作。","爭取社會住宅、於公有地興建住宅。","建立食安機制、讓百姓對食的安全無慮。","積極爭取現代化農機設備及農業政策推廣、協助農民的成長。","落實勞工就業及勞工退休準備金提撥率、以防止惡性歇業事件發生。","推動弱勢團體及提高老人三節敬老金與為鄉親爭取更好的福利政策,讓幼有所育 長有所尊。","爭取更多的地方建設經費以加強基層建設讓楊梅更好、如行的安全。","監督政府提高服務效率、杜絕浪費公帑。","督促政府加強推動楊梅區各項公共建設。","積極爭取秀才步道、福人步道、清水步道、保甲步道改善及12座公園增設兒童遊 戲器材、成人運動器材以推動全民保健運動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7dd6e5a9-06bf-4acf-a7e3-7308412a617f","items":["實踐清廉政治生態－破除鑽營私利與勾結，邀全民參與縣政計畫。（政治）","規劃半島輕軌火車－解決南臺灣交通瓶頸，鏈結地方產業與觀光。（觀光）","產銷農漁畜牧花果－提振屏東物產銷售量，拓展海內外銷售市場。（經濟）","實現多元族群融合－檢視聚落開發與缺失，尊重各部落文化遺產。（族群）","完善科技醫療體系－社區衛教醫療與安養，老幼婦孺照護能並重。（醫療）","活絡傳統記憶場域－活絡閩客原生活空間，重塑失落的社區樣貌。（社區）","推動青創產業再生－以數位網路行銷專案，穩定生產與行銷鏈結。（青創）","體育運動基礎建設－辦理六堆原民及縣運，再創造屏東運動大縣。（體育）","國際教育雙語交流－開發國際化教育資源，深化姊妹連結與合作。（教育）","擘劃文化藝術再生－完善青少年藝術教育，提供能進入國際市場。（文化）","教育政見：0～6歲免費入學，強化監督國中小營養午餐菜色品質，強化留校課後輔導師資及點心補助，建議外師普及化，提升雙語口說能力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7e3ac60d-84f3-400c-b587-9812a5c1e8a7","items":["推動有機產業，協助農友取得有機、友善認證。","結合鄉公所整體建設規劃，爭取縣、中央級經費挹注與建 案，建構安全的農產運輸與生活環境。","推動萬榮鄉農產集貨場及初級加工廠。","持續辦理林田山、 碧赫潭週邊地景營造，打造觀光亮點。","督促放寬核定農業類簡易水土保持計畫，保障農民權益。","推動家庭族語老師，確保族群幼苗成長能與文化相結合。","推動培育原住民各類人才，並協助輔導與就業。","推動具原鄉特色的長照服務機構與專業技術人才訓練。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7e6643e8-30cb-4448-a970-d284b15eaf15","items":["美好烏日大肚龍井區幸福城市進行式，爭取預算建設美好家園。","監督市府規劃良好社會福利，照顧弱勢獨居榮民、新住民，為身障貧困者爭取機構協助。","監督市府落實各區社會住宅，積極爭取公托公幼親子館讓年輕人專心打拼、放心宜居台中城市。","推動在宅醫療長照合作掌握資源就地診療，照護強化醫療預防保健。","監督市府落實安全農業政策，推廣特色多元行銷，增進農政收益強化競爭力。","落實教育均等加強爭取各學校軟硬體設施，穩定師資提供學童多元化學習身心均衡發展。","監督市府極力推動全齡共享、友善無障礙，並融入地方特色，打造不同主題的共融公園，提供豐富且優質安全的休憩空間。","持續監督市府，要求提升道路平整，友善通行環境，確保行車安全並創造優質生活環境。","極力爭取台中鐵路雙軌高架化延伸大慶至成功站，督促完善綠線捷運聯外交通停車場規劃。","持續監督改善空污，要求中火減煤污染保障市民身心健康。","關心勞工權益，推動勞資和諧共好。持續督促並協助市府爭取企業投資台中，創造更多就業機會。","強力監督市府落實高鐵周邊開發及監督前竹區段徵收、九德區段徵收開發進度，極力爭取立法院遷建烏日促進發展創造更多就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7e8a843e-c328-4737-855a-08ef723e7534","items":["爭取增設公托及公幼，確實減輕青年家庭幼兒教育的負擔。","爭取一次性生育補助提高至10萬元，提高生育率。","爭取補貼青年購屋貸款利息，安心成家就業。","爭取增設老人關懷據點，將閒置公有空間規劃改善再利用。","爭取設立北屯市立綜合醫院，提供更好的醫療資源。","爭取增建社會住宅，提供多元居住協助。","爭取提供定型化寵物健保契約。","爭取增設寵物公園。","監督北屯區多功能小巨蛋體育場館完工。","監督北屯國民運動中心完工，早日提供大北屯民眾使用需求。","監督「水湳轉運站」完工，提升交流道等多元轉乘的便捷效益。","監督捷運綠線延長到大坑。","監督捷運藍線儘速動工。","監督中清路捷運橘線儘速動工。","監督台中發電廠以氣代煤，改善空汙。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7e961d73-bd4e-4a8d-9c9b-11ae10db7d05","items":["監督縣政府預算執行，為人民服務，督促縣政府政策落實及效率。","加速淘汰老舊公共設施，活化各鄉鎮公有設施。","督促改善道路品質，加強交通安全設施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7efae8f4-a1c1-404e-8e8d-8f1083570e74","items":["監督縣府落實廉能政治，杜絕貪污行為發生。","督促縣府爭取企業屏東設廠，提供縣民就業機會，減少人口外流。","建議縣府整體規劃觀光發展方案，爭取觀光客回流。","屏東縣農漁特產資源豐富，縣府應積極行銷提高農漁民收益。","監督縣府落實預算執行，避免無謂的浪費。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7f04ec56-0229-42c1-b6c6-932d08f743f2","items":["空間改造 南科再躍進 1 監督南科特定區ABCDENO區開發及安定區都市計畫通盤檢討。 2 推動善化區、安定區、新市區鄉村地區整體規劃。 3 新市產業園區開發、山上工業區再造。 4 增加運動空間，加速公園綠地、道路開闢，廣設停車場域。","交通升級 南科更便捷 1 推展新市、善化段鐵路立體化，擴建台鐵善化站。 2 開闢山上工業區直達南科西拉雅大道聯絡道路、善化區烏橋中路至溪埔中路道路，興建永新路與永科北路連接橋梁。 3 優先興建捷運深綠線，發展多元創新而便捷的公共運輸。 4 積極推動共享單車、共享機車及汽車，打造智慧綠能交通生活圈。","在地關懷 南科要宜居 1 推動公幼課後照顧服務，公幼增設二歲專班，爭取資源挹注教育；增設親子館、廣設公共托育。 2 爭取青年公宅、社會住宅；保障勞動權益，推動青年返鄉工程。 3 多元挹注弱勢家庭與長輩；銀髮照顧社區化、閒置空間設置銀髮學堂。 4 加速南科區域級醫院設置，推動智慧醫療，落實長照醫療。","文創發展 南科好藝文 1 結合在地藝文、民俗活動，多元創新催生藝文產業聚落及展演場域。 2 結合科技催生農漁新經濟及特色觀旅，強化在地產業、創業及就業發展。 3 發展一區一特色，推動地方創生，協助發展地方產業與地方創業。 4 廣設特色公園、共融式遊具深入社區鄰里公園。","資源保育 南科變美綠 1 因應極端氣候，持續治水、學會親水，打造生態滯洪公園。推動水資源保護觀念普及化。 2 爭取善化區、安定區、新市區、新化區污水下水道系統，善化區雨水下水道系統。 3 增設動物友善的空間及設施，設立寵物運動公園。提昇動物收容之品質，積極監督與強化遊蕩動物之減量措施。推廣生命教育、關懷動物生命權。 4 推動愛樹、植樹活動，成為友善樹木的城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"7f1640e4-90e2-4ee7-bf22-50a5a1406c40","items":["嚴格監督縣政，看守縣庫，為民喉舌。","極力爭取老人及農、漁、蚵民之權益福利。","照顧婦幼及弱勢團體，把關黑心食品護食安。","為公教、軍警人員之橋樑爭取權益，成立義愛慈善基金會，關照貧困及極需幫助之家庭。","督促開發工商，提供縣民更多的就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7f18b070-a303-4814-b3a3-5172a9f1c7c5","items":["潭雅神豐都市計畫已經成功整合，再積極推動潭子、大雅、神岡、豐原為台中市的副都心，促進均衡發展！","督促市政府65歲以上長輩健保補貼不可少，營養午餐全免費、營養加倍！","督促市政府重新整合，原縣區的交通路網。","督促市政府持續興建社會住宅，落實居住正義及育兒各項政策升級。","積極爭取潭、雅、神地區公辦日照中心及增設親子館。","積極爭取潭子區與北屯區都市計畫整合，規劃符合現代使用的公共設施用地。","積極爭取綠空廊道立體高架橋樑及橋下各項體能、遊憩、休閒設施。","督促市政府整合國道4號、環中路、環中東路高架橋下閒置空間再利用！","積極爭取專案變更北屯區敦富路、南興路、南興北三路延伸潭子區福貴路、復興路、中山路促進潭子區的發展！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7f304f4b-6815-41b1-83a0-8239928b17e8","items":["嚴格監督預算，爭取經費建設永和，謀求市民最大福祉。","加速都市更新，重視居住安全並改善居住環境。","督促捷運萬大線完工通車，並繼續爭取永和東區捷運路線，以期帶動全區之發展。","持續爭取老舊校舍重建，充實學校軟、硬體設施，提供學子優質的學習及成長環境。","持續爭取打通瓶頸巷道以利消防、救護，整平騎樓、人行道，永和真好行。","推動身教(親子品德教育)與境教(環境、環保教育)心倫理。","推動老少共學，促請政府結合社區資源，增設托老及托育機構及銀髮族休閒空間，以迎接少子化、老齡化社會。","爭取增加生育輔助，督促政府重視婦女二度就業問題，關懷單親及新住民婦女。","持續強化公共安全，保障民眾生命財產。","繼續推動河川高灘地及瓦磘溝綠地之規畫整理及美、綠化，以減少水患並增加民眾休憩空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"7fe426e1-fa58-4d74-a986-81d1b35c08dd","items":["嘉義正能量，議會新戰將！ 啟豪堅持做對的事，用心把對的事做好。","一個願景：農工大縣，正在實現；安居樂業，幸福嘉義。","兩大任務：真誠用心服務—您的需要，我來發聲。專業優質問政—縣府施政，我來監督。","三大主軸：孩子是我們的未來—提升「育兒政策」；增進「兒童福利」；支持「教育體系」。青年是我們的希望—創造「就業機會」；活絡「地方經濟」；保障「勞工權益」。長輩是我們的寶貝—推動「樂齡學習」；健全「長照體系」；落實「在地安老」。","四大方向：農業永續；產業創新；文化紮根；觀光發展。","五大保證：骨力認真打拚！實在好央甲！有學歷有能力！還要有親和力！更要能接地氣！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"800ea5a0-c032-4b80-b8e4-fe16c3313f50","items":["打造優質生活空間，增設公園及親水綠帶","爭取山仔頂新建公二鄰里公園、高雙路底及陸光路舊營區改建新運動園區，增加城市休閒空間。","爭取平鎮區第九公墓興建公園及地下停車場，增加周邊遊憩及汽機車停車空間。","爭取老街溪河岸步道延伸至龍南幹線，連接龍潭成單車及步行綠廊。","道路開闢解決交通瓶頸，提升公共運輸效能","爭取平鎮民族路三段沿國道五楊段橋下空間新闢道路，紓解文化街及長安路車流。","加速推動金陵路五、六段替代道路新闢工程計畫，解決塞車問題。","爭取拓寬打通東光路201巷瓶頸道路，紓解東光路、平東路往來車流。","爭取廣北停車場改建為具停車場及商場功能的民族路轉運站，多目標複合使用。","爭取廣南停車場改建為BOT綜合停車場及商場多功能大樓。","爭取鐵路地下化後原鐵軌路廊改建林蔭大道，連結南、北桃園並增設車站周邊停車空間。","保障學童就學權益，廣設公幼","爭取大南勢地區文心路及南京路口新設國民小學，紓解周邊社區小學生總量管制難以入學之窘境。","廣設公幼、附幼及非營利幼兒園並增加補助辦學，減輕家長負擔。","推動人本道路，爭取金陵路二段劃設標線型人行道，保障學童上下學安全及行人友善空間。","爭取加速地方建設及淹水改善","爭取中豐路、環南路旁設立南桃園行政中心平鎮行政園區，便利民眾洽公效率。","推動東豐路幹管接龍南幹線排水系統興建，及改善桃園市龍潭、平鎮（山仔頂地區）都市計畫區雨水下水道系統重新檢討，解決山仔頂地區水患。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8016f26a-ef32-4d3f-a336-46b91f4e90d1","items":["以爭取忠一路及市中心地下道改造的成功經驗，進而推動步行城市，持續爭取系列友善行人和空間再造計畫，改善市容、提升生活品質、串連商圈、吸引觀光客。","以推動委託行再起的成功經驗，持續進行地方創生及青年返鄉計畫，同時輔導青年創業永續發展，並將週邊仁愛市場、廟口夜市、孝三美食、歷史廟宇串連，目標提升觀光及經濟產值，打造專屬基隆特色文化品牌。","以爭取廟口汰換自來水管線的成功歷程，持續監督自來水公司檢視老舊管線汰換，同時改善道路品質、活化停車空間。","以爭取成功國小改造經驗，持續推動校園核心改造計畫，讓各校發展特色，資源進入社區，融入鄰里公園，讓校園及社區共融共好。","以成功增設育仁休閒公園經驗，持續爭取活化閒置空間，提升社區生活品質。","因應高齡化趨勢，持續爭取日照中心設置仁愛區，讓老有所托，子女上班安心。","持續推動本市都市更新工作，督促市政府擬定全市都市更新期程，全力推動仁愛區都市更新作業。","推動坎仔頂漁市面貌，改善環境，打造成為台灣築地，並督促市政府將周邊環境打造成為海鮮美食聚落。","督促市政府正視獅球嶺步道改善及環境維護工作。","督促市政府發展紅淡山、獅球嶺觀光登山活動，吸引外地人利用假日時間搭乘大眾運輸工具前來登山，同時帶動市區觀光產業發展。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"802f5efe-0efb-4fdb-b523-b3ec865f0238","items":["完善大眾路網：捷運黃線—強化都會軌道路網；輕軌成圓—力促環狀輕軌2023年完工。","三民宜居好生活：建構高雄綠廊帶，創造綠化好生活；推動三民運動中心，共築健康好三民。","產業升級拚發展：緊盯產業園區建置，協助台積電加速設廠；振興車站周邊商圈，打造高雄表參道。","育兒長照做更好：持續爭取津貼加碼，養兒減負擔；推動長照據點增設，長輩生活沒煩惱。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"803078d5-9607-4c01-9055-88cbecf82034","items":["建設家園，守護台灣 新北第一席，過半最關鍵 交通問題我來解決","監督淡江大橋2025年完工","爭取台61線延伸至北海岸","爭取改善台二線道路路幅","爭取林口輕軌與機捷共構","爭取機捷A9林口站全面停靠直達車","監督五泰輕軌如期完工","爭取興建八里輕軌 照護問題我來改善","爭取經費挹注新北市老人共餐獎勵機制","爭取孕婦懷孕期一次「高層次超音波」全額補助","爭取全額補助婦女「羊膜穿刺」","爭取第一選區增設醫療園區","爭取長輩假牙補助 產業轉型我來做","爭取台北港周邊興建免稅購物中心","爭取興建北海岸海洋生物館","爭取塭仔圳重劃區增建大型展演空間","爭取興建淡水新市鎮公有市場 勞動權益我來爭取","支持提升高齡就業者勞權保障","支持在職青年參與職訓補助 教育我來監督","支持「身心適應假」設置","支持擴大投資技職教育","支持全面落實高中職免學費 環境我來守護","監督八里污水廠儘速移交新北市","爭取核後端基金挹注建設","爭取泰山區污水下水道工程加速建設"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"806bc1b0-d56a-4ee1-93fd-27516ccc9965","items":["ᑫӥНӥЎϯൺᑫၮ୏ȩǴѺ೷ܿᑫӥ‫۞ݮ‬ԋࣁԮчᆘ༜ၰǶ!","਒Шᑫ‫୔ࠔޜ‬ᇂȨ࠻ϣᡏ‫ػ‬൑ᓔ CPU ਢȩ Ƕ!","঵ྛ‫ׯ‬๓ीฝǴᗋ๏Ԯч҆ᒃ‫ݞ‬ऍ᜽य़৒Ƕ!","෧ໆǴ൨‫؃‬Ӛᅿೀ౛‫ޑ֣ڱ‬ᆘՅඹжБਢǶ!","ֹӄύᏢǴ‫ׯ‬๓୯ଯύό‫ޑى‬௨ᔒਏᔈǴߥም‫ڙ‬௲៾Ƕ!","ғ៾੻Ǵ‫ڗݾ‬೛ҥȨԮч੝௲ၗྍύЈȩǴ่ӝԐᕍǵᙍૈ‫ݯ‬ᕍ฻ӄБՏфૈǶ/!!","ཥԮᑜε౲௘ၮ‫س‬಍᏾ᡏၡᆛೕჄਢǶ!","୯ၰ΋ဦླྀᓐࢤ‫ܗ‬ቨπำǵཥԮᑜ࿶୯ᐏҬ೯‫ׯ‬๓πำǶ!!!!!!!!!!!!!!!!!!!!!!!!!","ԴᙑϦ༜ቶ൑ᆘӦ‫ูٽ‬ၯᔍ೛ࡼӼӄᔠෳǶ!","ቚࡌ॥ߘౚ൑ǵᆛౚ൑฻Ǵྣ៝ၮ୏௼ဂሡ‫؃‬Ƕ!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"807a809b-a689-4d04-bb3d-2111d407aa25","items":["推動灣區舊港觀光廊帶,帶動鼓鹽商機","爭取旗津區內與聯外交通建設,解決交通困境","專業監督高雄治水規畫,因應極端氣候","重視在地歷史文化傳承,兼顧傳統潮流","健全嬰幼兒教養托機制,打造幸福高雄","倡議城市淨零排放路徑,打造健康高雄","促進經濟產業多元發展,打造富裕高雄","加速都市更新舊城開發,打造公義高雄","完善社會安全網絡建置,打造安心高雄","推廣城市治理智能應用,打造智慧高雄"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"80ad8758-18f6-4b3a-990e-a7e499dc6e95","items":["全力支持侯友宜市長連任，齊力「侯侯做代誌」，為市民服務。","持續推動捷運「汐東線」儘速動工，督促「捷運基隆線」規劃進度。與台北市、基隆市跨市合作增闢及拓寬對外聯絡道路，逐步改善汐止、內湖、南港、基隆共同生活圈交通。","持續推動並爭取新闢「國道3號南港交流道增設南下出口橫科匝道」銜接環東大道，以紓解新台五路及大同路車流。","堅持一路走來清廉問政，傾聽民意、爭取地方建設、監督市政、推動銀髮照護、弱勢關懷、青年服務、關注動保，打造低碳樂活城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["past_achievement"]}}},{"claim_id":"80af4389-80a9-435b-85dc-3627ff2878b9","items":["捍衛軍公教警消的尊嚴、充實裝備、保障其生命財產安全。","全力推動0至99歲皆可使用之特色共融公園及寵物公園。","支持18歲公民權。鼓勵青年返鄉，督促園區開發、產業發展，增加就業機會。","持續監督高鐵宜蘭站及鐵路高架早日興建，紓解雪隧、市區交通問題。","提升醫療品質、維護醫護人員權益，以保障民眾健康安全。","保障長者、婦幼、弱勢及殘障權益，健全托嬰保母系統，杜絕虐童事件。","督促教育經費充分編列，健全軟硬體設備、推動多元教學，以提升教育品質。","加強校園毒品防制、支持嚴懲毒販，營造安全城市。","支持環保永續發展、捍衛宜蘭淨土。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"80e9237e-1233-422a-8254-96593229408a","items":["等車會舒適 ‧ 完善候車亭建設 ‧ 監督改善車輛安全與人本交通","兒童有公園 ‧ 推動共融式親子公園設置 ‧ 汰換老舊遊具，打造安全遊憩空間","青年賺有錢 ‧ 協助傳統產業轉型、青創、新創 ‧ 推動特色產業活動，增加行銷管道，打造媒合資源平台","運動有去處 ‧ 推動複合式運動場域 ‧ 監督運動空間的運用與安全","觀光能永久 ‧ 結合在地文化、產業，輔導特色觀光永續性 ‧ 監督觀光開發建設之效益","社福醫療要升級 ‧ 補強校園、婦幼安全網 ‧ 監督社福、醫療預算分配的平等性與軟硬體提升","教育藝文要紮根 ‧ 平衡城鄉硬體設備 ‧ 推動充實多元教育、技職軟實力"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"81030de4-84a0-431b-9513-b2f495ca8693","items":["爭取風雨球場建設；讓運動民眾更便利提昇運動人口","推動寵物友善空間","公園景點增設洗手台及廁所","協助爭取自來水資源普及化","新住民友善就業環境：閒置校園空間轉型活化為銀髮日照中心","新住民友善就業環境：推動新埔產業打造特色鄉鎮"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"810c6682-7141-47a2-b7ff-58418445bd66","items":["【教育不能等，紮根是基本】 透過教育，讓孩子真真切切地了解到我們的生活環境！教育不能只是課本，而是要從多元教育的認識，去更透徹的讓社會更好。不管是從反毒、環境永續、社會共融等教育內容，都是與我們的生活息息相關，更可以說這就是未來式。 政府就像是火車頭，要帶著我們的孩子將車開往未來，並且提供每位孩子舞台，幫孩子們串起一個個他們看不見卻有力量的資源，讓孩子們看見未曾想過的天空。","【交通要便民，公帑不浪費】 積極提升公共運輸服務品質，賡續發展智慧型公車資訊系統及快速/跳蛙公車，持續推動共享運具，鼓勵市民搭乘大眾運輸，閒置公有土地活化新建停車場，持續爭取樹鶯鐵路立體化、高快速公路、增設交流道、老舊大橋整建等，隨著三鶯捷運線所帶動的效益，加速推動萬大捷運線完成，辦理三鶯轉運站工程，以提升本市路網之便捷，縮短生活圈的距離。","【社會好福利，大家暖心窩】 一個進步的現代化國家，都有很好的社會福利制度，提供人民生活上的福利與保障。新北社會的福利一直以來是新北市民的驕傲，但再好的都會些許的地方是沒有被發現的，如新住民、寶貝毛孩又或是身障者就業協助以及保母托育心理照護等，這些都是我們要去關注的。而如今我們社會福利所面對的是人口高齡化與少子化的挑戰，所以在這部分上更應及早因應，為新北創造一個安居樂業的環境。","【大家動健康，地方好健康】 近這幾年持續的推廣新北動健康，慢慢大家的健康現在似乎已經轉變成一種使命，一種能夠將所學用來幫助大家更健康的使命！讓我開始接觸更多的鄉親，有的年紀超過60歲的長者、30-40歲正值人生顛峰的上班族、20歲的青年學子到國中、國小、幼稚園的小朋友甚至是新住民朋友都有，未來不止是動健康，更應該讓健康走進社區，像是共生宅、樹林醫療園區以及土城醫院，以及受到大家關注的SIY正念教育，這些都會讓我們的地方變得更加健康！ 5.【產業要創新，人才要珍惜】 台灣的企業是世界知名，而新北未來的快速成長，最好的方式就是讓人才留在新北。所以我們更應該重視輔導人材的做法。畢竟創新是過程，如何執行與媒合輔導是地方政府的首要照顧的層面。也包括他所潛藏的巨大成長空間，創新人才培訓管道，不管是在地方創生、SDGs的概念下或者更多…，彼此就會在「相信」的關係中全力以赴，因為大家都具有這種「創新新北」的潛質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8154c3f5-203c-4ad4-86dd-4a4e7f16407d","items":["爭取「捷運藍線」延伸到清水與港區,便利海線交通,要求進度加速。","爭取海線第二座社會住宅在清水區興建,讓弱勢者也能「住者有其屋」。","推動鰲峰山整體規畫,目前公墓禁葬已4年,爭取加速公園化,擴增綠地休憩空間。","海線仍有五成以上公有地未妥善利用,爭取釋出活化運用,促進地方經濟繁榮。","公共設施保留地(學校與機關用地)檢討後,督促加速市地重劃,確實還地於民,使土地資源有效利用。","爭設觀音雕像文化園區、露營區等景觀設施,增加海線觀光景點。","重視長者福利,督促政府在各區遍設銀髮族照護、關懷據點;提高「假牙裝設」補助名額。","督促市府增設公托與公幼,並提高生育津貼、幼童照顧等相關補助,讓年輕人敢生敢養。","重視學童,力促市府提高學校營養午餐的品質;加速老舊校舍改建。","振興產業,督促市府規畫工業園區或工業用地,協助廠場合法化;並積極開發台中港公有土地,繁榮地方。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"81915e0c-5bff-42cf-acb0-712d26147ceb","items":["問政報告定期提出。","議員補助款公開透明。","清白問政永不涉黑。","提升交通便利：推動增闢「國二高速公路國際路微型交流道」，舒緩塞車現況。","提升交通便利：推動和強路（和平路至東勇街段）拓寬，解決和強路塞車問題。","提升交通便利：要求定期地方說明會，強力監督捷運綠線如期如質完工通車。","提升交通便利：綠線捷運沿線擴大公車路線，爭取搭乘補助，減緩交通建設黑暗期。","提升交通便利：全區檢討路燈照度，保障夜間安全。","提升交通便利：爭取大湳、陸光社區周圍興建地下停車場。","升級教育品質：推動仁德國小、大勇國小設校，解決在地就學問題。","升級教育品質：推動永豐高中新校區取得。","升級教育品質：推動元智大學闢設第二校門。","升級教育品質：持續支持推動閩東語教學，保存「金門馬祖文化」特色。","升級教育品質：推動廣興國小、霄裡國小校地徵收案，改善教學環境。","加強社會照護功能：增設關懷據點，免費供應長者午餐。","加強社會照護功能：增設各里活動中心，強化活動中心功能。","加強社會照護功能：爭取公費肺鏈及流感施打年齡降至60歲。","加強社會照護功能：擴大長照喘息式服務補助適用範圍，降低長期照護者身心負擔。","加強社會照護功能：爭取八擴設立國民運動中心，方便八擴居民及周邊地區民眾使用。","加強社會照護功能：新住民原創聚落，消弭新住民社群與在地文化隔閡。","加強社會照護功能：爭取老花眼鏡補助，照顧弱勢長者。","加強社會照護功能：擴大樂齡學習多元課程，推動社區樂齡學習教程與據點。","加強社會照護功能：整合老年卡功能，擴大長者樂活交通補助。","加強社會照護功能：成立疫苗行動施打車，包含新冠、流感、肺鏈。","農業轉型多元化：爭取桃園農用水井適度鬆綁。","農業轉型多元化：爭取區內農業肥料補貼。","農業轉型多元化：推動科技農業講座與技術移轉輔導。","農業轉型多元化：推動田園城市示範點。","農業轉型多元化：爭取農民定期健康檢查補助。","擴大環境永續政策：擴大企業建物、工廠露天停車場設置太陽能板補助，達成2050國家淨零碳排計畫。","擴大環境永續政策：友善水環境，科技掌握並善用伏流水因應旱災。","擴大環境永續政策：放寬、延長市民購買電動車補助條件，提高補助額度。","擴大環境永續政策：加強充電樁設置密度及設置獎勵辦法。","擴大環境永續政策：推動輔導工廠登記，納管非工業區工廠。","城市景觀：加速推動移除電線桿和架空電纜（電纜地下化）。","城市景觀：擴大「八德埤塘文化節」辦理規模，形塑八德美景。","城市景觀：活化老舊閒置營區，轉作「青年夢想基地」。","城市景觀：推動閒置空間綠美化。","城市景觀：推動綠線捷運高架段沿線空間綠美化。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"81a98426-40d6-46fd-b889-25b18ec68493","items":["公托全免費，私托全補助","盤點幼教師資及空間，增加公托班級數","生育獎勵再提高，托育津貼再擴大","營造安心育兒環境，打造職場友善臨托","爭取婦幼停車位，增加哺集乳室及公共尿布台","爭取擴大不孕症治療補助 安心慢老 銀髮福利","長照2.0再進化，擴展照護據點培育專業照護員","推動「社區在宅老化、社區居家照顧」","一里一長者據點，擴大敬老卡使用範團","打造友善長者環境，獨居長者免費共餐","爭取老人照護輔具補助，佈建無障礙環境設備 雙語教育 接軌國際","推動校園全雙語教育與國際接軌","強化學生英語聽說讀寫能力","落實英語能力應用，營造校園英語生活化","中小學教材雙語化，搭配數位科技學習 都更有力 市容美麗","成立都更特戰隊，各區成立推動協調小組","積極推動公辦都更，協助危老改建更順利","增加獎勵容積率，一坪換一坪、一户一車位","改善住宅生活機能，打造安心宜居新容貌 社宅擴充 租屋輕鬆","包租代管獎勵再加碼，提升公益出租人數量","放寬租賃資格限制，完善社宅居住環境","主張社宅入住「輪候制」、杜絕社宅二房東","提高租金補貼，擴大請領族群 捷運衝刺 松信加速","加速民生汐止線、環東線115年動工","推動捷運離峰優惠票價，充實公車路網串連","擴建Youbike2.0，增加大眾運輸轉乘優惠","末班車啟動警網協助，護送婦幼安全返家 客家精神 文化傳承","培育客語師資及成立客語語文班競賽","深耕北市客家網絡，完備客庄創生基礎 青年夢想 啟動理想","成立臺北市青年局，創造青年發展新方向","資源空間再利用，打造青年創業園區","媒合青年就業機會，培養職能技術提高薪資","放寬青年貸款資格，利率優惠補貼利息 河岸友善 松信完善","基隆河岸再進化，打造臺北新灣區","河濱公園增設監視器，放心活動安全無死角","增加共融式公園，讓孩子遊戲更安全","推動松山監理所遷移、南松山市場改建","活化松菸文創園區，成為首都藝文新亮點 毛孩友善 動保實踐","打造動物友善都市，廣設友善空間與設施","全面化推動毛小孩植入晶片","防範惡意棄養，提高罰鍰金額","成立貓犬訓練機構，增加毛小孩寄宿場域"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":7,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"81ba6f2f-7050-4fc5-b0f5-2f88b47ad520","items":["推動內灣聯外道路拓寬新闢工程計畫。","針對少子化影響偏鄉教育資源不足的問題積極爭取各項因應措施。","持續強化銀髮照護推動關懷據點及老人共餐服務。","積極爭取尖石鄉設置客家多元活動中心發揚在地客家傳統文化。","推動地方發展及活化歷史建築物再利用結合周邊商圈等文化景點資源帶動內灣商圈觀光效益打造內灣所成為文化觀光亮點。","推廣在地農產品協助農民提升農作產值與行銷。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"81bd009c-9aac-4231-a470-7c397c55409a","items":["參政實在、專業認真、監督縣政、守護雲林。","強力要求縣府處理垃圾問題，以平息民怨。","監督改善空污及環保問題，給縣民清新空氣。","爭取濁水溪南岸高架快速道路，完成便捷交通網。","爭取北港溪北岸78甲快速道路，促進宗教觀光休閒活動。","活化社區在地文化，傳承人文歷史特色。","建立快速產銷通路，保障農民基本生活。","充實本縣醫療資源，照顧縣民健康。","監督縣府治水工程，保護縣民生命財產。","設立高鐵中、小學及高鐵派出所維護治安。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"81da3c9a-10a9-49ad-a590-cfde741c376a","items":["幸福宜居政策：打造多元藝文、休閒觀光文創生活圈，提升竹北幸福新亮點。","幸福宜居政策：推動社區家戶綠美化，保留綠地公園生活圈，打造美麗家園新竹北。","幸福宜居政策：「居住正義、穩定房價」爭取縣民租屋補貼措施。","幸福宜居政策：「藝文竹縣風華再現」打造新竹百老匯，縣民藝文素養再提升。","交通優質政策：積極推動竹北市循環式大眾運輸系統，建置大眾運輸動態APP。","交通優質政策：積極推動完善大眾運輸系統，建構竹北市往返竹科園區循環公車路網。","樂齡長照政策：建構多元化社區照顧系統，一社區一關懷據點，優化老人尊嚴式照顧，發展在地成功老化政策。","樂齡長照政策：推動行動醫療服務專車，提升樂齡長照長健政策。","樂齡長照政策：推動居住新模式，發展「青銀共居、青銀共樂」，建構青銀友善照顧措施。","樂齡長照政策：推動樂齡敬老愛心卡擴大多元使用範圍，提升樂齡生活品質。","樂齡長照政策：積極推動志工人力銀行政策，落實友善志工發展力。","優質教育政策：推動雙語教學延伸至幼兒園，強化中小學英語聽力及口說能力，提升教育競爭力。","優質教育政策：打造優質智慧校園，推動校園治安防護網，提升友善學習環境。","優質教育政策：「青年成家新願景」營造「願婚、敢生」，爭取青年成家無息補助貸款，生育養育補助加碼，減輕家庭生養負擔。","婦幼福利政策：推動「0-6歲國家一起養」、「0-2歲托育補助再加碼」、「2歲以上就學補助再加碼」政策。","婦幼福利政策：爭取新住民各項福利與權益，落實族群融合政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"827f66f8-a1b2-419c-adaa-1933c00ec524","items":["督促縣長競選政見的有效落實。","督促「苗栗縣社會安全網」更為有效的落實。","督促社政單位在運用公益彩券基金時，應保障身心障礙者、弱勢家庭、婦女及「社會安全網」服務對象的經費務必充實。","督促教育單位廣設公托和學齡前教育的向下延伸。","督促勞青單位對於青創中心及青年就業提出更為有效的方法，幫助青年創業及就業。","爭取文化、藝術和社區各類表演團隊的經費和練習場所。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"829ab237-b0a5-494c-bc8a-e92aff622a3e","items":["監督市政。","社區關懷據點，資源整合與運用，長輩在地樂活學習（長輩開心，晚輩放心）。","學前教育、公托資源彈性增設（減少家長育兒負擔）。","防止校園霸凌，學生安心學習（飛鳳用心，家長放心）。","鄉親用路安全，道路重鋪前置作業，跨單位工作協調討論（平安回家的路）。","延長建置捷運系統，建置完善大眾交通（增加鄉親交通方便）。","培訓社區營造人才、青年人力回流鄉里、婦女二度就業、銀髮人力運用（老中青人力運用）。","共推跨域合作，休閒觀光農業（推廣產業增加收入）。","爭取國營與在地大廠，增加錄取在地子弟（子弟在地工作，就近照顧家庭）。","公共空間環境、閒置空間再利用（更多休閒地方）。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"832b021e-84e1-4e16-a4b6-96d9fe7feddb","items":["推動公共托育：先期規劃可能閒置之校地校舍，增加公共托嬰設施、公立與非營利幼兒園，減輕家長負擔。","加強特色設施：推動公園罐頭遊具減少，廣設共融式遊具，增加親子休閒去處，吸引人流帶動周圍商圈。","爭取青創福利：設立青創空間，舉辦青創講座，推動青創基金。","活化地方商圈：鼓勵並獎勵危老都更，定期舉辦文創市集，協助商圈發掘特色。","建設友善停車環境：重要辦公商圈廣增設停車格。","建設友善停車環境：爭取全高雄婦幼市民憑診斷書、懷孕證明可以免費停車1年（婦幼友善措施）。","建設友善停車環境：免增（減免）公共騎樓地價稅。","建設友善停車環境：活絡傳統市場：協助市場改善環境，從整潔以及電子支付開始，並舉辦特色活動，增加特色攤商，吸引人潮到市場。","建設友善停車環境：新住民文化傳承與推廣：舉辦新住民文化交流活動，包含特色市集、文化特展，特色節日時舉辦活動，並舉辦新住民母語的各項活動與比賽。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"83428460-de06-4eab-8e1a-924c22838644","items":["朝國從參政開始【堅持對鄉親的承諾】 腳踏實地一步一腳印；不敢懈怠，大台中升格直轄市後帶動整個潭雅神的進步，朝國深耕地方；全職在地服務，有許多重要的地方建設還未完成，未來的四年讓朝國繼續來替鄉親打拚。","爭取鐵路潭子段高架下設置停車場。","爭取潭子區第二產業園區。","督促國道四號延伸潭子74號線早日完工。","督促74號快速道路高架銜接國道一號早日完工。","推動地方精緻農業，活絡地方經濟產業推廣。","推動社區醫療團隊照顧社區老、婦、幼保建工作","爭取潭子區內國小雙語教學資源平均分配。","爭取潭子區設置親子館及老人日間托老中心。","爭取生育、育兒津貼(就學)補助，改善少子化問題。","爭取為弱勢團體發聲謀福利；爭取更完善的照顧。","協助勞工、青年夫婦安心就業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"84ae9c2c-8cc4-4cda-8158-e4537647bc0c","items":["【樂活中和 安心安居】 1.南勢角軸線翻轉，紓解交通壅塞問題。","推動全民運動，促成中和第二運動中心。","運動樂活，培育運動人才。","加速三環六線，萬大中和線工程進度。","推動多元都更，危老重建，擴大公辦都更。","加速瓦磘溝整治河道水質，水岸景觀改善。 【加速發展 就近就業】 1.推動租稅正義。","輔導興南夜市攤商合法化。","促進灰磘產業專區整體開發。","興建更多社會，青年住宅。 【行的正義 停車容易】 1.爭取前國防管理學院運動場開闢地下停車場。","校舍老舊設備更新，新增設地下停車場。","加速佳和公園新建幼兒園公托暨共構地下停車場工程。","打造宜居環境，增設YouBike 2.0站點。 【用心護幼 優質長照】 1.完善高齡照護，廣設日間照顧中心。","長者在地安養，提供婦女二度職訓就業機會。","重視新住民文化健康爭取社會福利資源。","優化托育品質，改善幼兒遊戲場。","增加國小公幼學生課後服務。","補助學校更新硬體，改善通學環境。","改善中和動物之家收容環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"856147ad-dc46-4dea-ad79-001d60a13535","items":["促進地方經濟發展及創造就業機會：賡續督促市府加速「北五堵新市鎮」計畫落實執行以利帶動地方經濟繁榮。","促進地方經濟發展及創造就業機會：爭取市府加速提高六堵、大武崙等二大工業區容積與建蔽率，並限期提出轉型改進方案，以吸引廠商進駐帶動地方產業發展與就業機會。 【改善交通環境及提升道路品質安全】","促進地方經濟發展及創造就業機會：賡續爭取光明路人行道擴寬為七米寬，成為七堵區「光明路示範道路計畫」。","促進地方經濟發展及創造就業機會：爭取市府將七堵區工建路及工建西路兩側人行道拓寬，串聯基隆河自行車道及台五線，並爭取將共享自行車往北延伸到七堵運用示範道路空間，七堵各地公園 以及基隆河自行車道串連成為自行車路網，一步一步建立綠色運輸動脈。","促進地方經濟發展及創造就業機會：爭取市府積極將本市捷運規劃，沿線地區都市計畫通盤檢討包含計畫時程、水與綠環境改善、推動社會住宅。 【打造休憩場域及增建市民公共空間】","促進地方經濟發展及創造就業機會：賡續爭取規劃基隆河沿岸步道串聯與優質化及整治親水休閒遊憩區。","促進地方經濟發展及創造就業機會：賡續爭取百福公園重新整體大改造，讓七堵區居民能真正擁有大型活動公園。","促進地方經濟發展及創造就業機會：賡續爭取現泰安公園規劃中朝生態公園予以規劃施作，讓泰安社區擁有鄰里公共活動空間。","促進地方經濟發展及創造就業機會：賡續爭取七堵區 - 富民里公園 - 崇義河濱公園土地闢建公園經費，建置成為基隆河自行車道的休憩地點。","促進地方經濟發展及創造就業機會：爭取建請市府將七堵區明德國中禮堂改為「多功能活動中心」。","促進地方經濟發展及創造就業機會：爭取市府將七堵區長興公園重新再造，並設置地下停車場一併解決活動空間及停車問題。 【加強公托長照資源及提升社區服務】","促進地方經濟發展及創造就業機會：賡續爭取市府編列經費，補助市民家中患有重大疾病雇請外勞看護或送安養專業機構治療者，予以酌情補助經費減輕其家庭經濟負擔。","促進地方經濟發展及創造就業機會：賡續爭取全市幼兒公托班免抽籤入學，以減輕市民經濟負擔。","促進地方經濟發展及創造就業機會：賡續社區闔家歡增加篩檢名額，以利市民健康保健。","促進地方經濟發展及創造就業機會：賡續督促市府加強對本市各弱勢團體身心障礙者之福利爭取。","促進地方經濟發展及創造就業機會：爭取調升鄰長事務費比照雙北以保障權益，同時也提供市民更優質服務。 耿直親切輝動為民堅定信念深耕基層"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"85e32a71-c439-480e-ac4c-e7fcc65203ae","items":["應曉薇研擬提案成功制訂「臺北市重陽敬老禮金致送自治條例」，為台北市銀髮市民恢復重陽 禮金，未來將繼續落實已經提案之「提高敬老金金額」以完成本市敬老政策。","反廢死、強化犯罪防治以保障婦幼安全、設立更生人輔導機構。","提前因應元宇宙時代政府各項工作、提案設立台北市青年局。","爭取放寬清寒補助、提高急難救助金、協助後疫情期間市民健康保障需求。","監督萬大捷運線、雙子星大樓、市場改建重大工程如期如質完工及振興選區夜市商圈。","積極推動危老、公辦都更、擴大補助老舊公寓外掛電梯。","改造艋舺公園機能、輔導與安置街友以保障地方安全促進地方繁榮。","監督市府應即刻成立新住民專責關懷機構。","繼續推動公立IB 國際文憑教育，打造台北市多元教育環境。 應曉薇認真踏實走過25 年公益路，首屆議員期間揭發雙子星弊案成功為市民把關700 億，三屆議員以來保護家暴受虐婦幼、救助低收入家庭津貼，疫情期間發起「希望餐」活動協助商家、送愛和平醫院醫護人員，近期更協助警局瓦解柬埔寨詐騙集團搶救無辜受騙市民。未來應曉薇將如歷屆承諾落實參選政見，並持續以多聞多見監督市政，陪伴中正、萬華區市民追求更美好的生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"85e34910-93be-429d-93e4-14d4c83c68a2","items":["力挺國防軍工產業自主化，強化台灣自我防衛能力","協助拓展實質外交，融入全球民主聯盟","堅持以「對等、尊嚴、和平」為兩岸交流互動最高原則","協助落實「區域共榮」治理目標，加速改善城鄉建設發展落差","交通路網規劃與道路設計持續優化，並加速捷運工程及大眾運輸便捷化、密集化","推動藝文新創獎助，地方傳統節慶傳承進化","擴大未來世代教育、高齡長者醫療等公共服務投資，提升台南城市宜居性與發展潛力","協助農、漁民提升設備、技術與行銷能力，以利拓展市場與增加收入","進步宜居在地好生活：觀光、文創培育基地在中西區 鼓勵年青人、文創工作者參與地方創生，打造深具獨特魅力的台南在地人文風情","進步宜居在地好生活：藝文展演、運動賽事重鎮在東區 協助市府規劃副都心場館開發計畫，爭取引進國內外音樂、運動展演賽事","進步宜居在地好生活：海港休閒渡假中心在安平區 利用安平國際港優勢，協助市府打造國際級海洋休閒渡假聖地","進步宜居在地好生活：社會福利建設、環境美化示範點在南區 爭取社會住宅、高齡照護中心以南區為集中示範區，將南區打造為台南宜居生活首選"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8604e012-9ae1-400d-a9df-40297e59798c","items":["督促儘速完成大羅東地區治水防災區段徵收案。","督促早日完成宜蘭至羅東鐵路高架化及羅東轉運站共構。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"860b029c-4d2e-47be-b8ee-dff2517e15e1","items":["推動增加幼兒公共托育家園。","推動提升魚池、水里、集集、信義、地方建設。","縣內國中小學軟硬體設備及改善。","關懷新住民增加輔導課程。","勤走基層、為民喉舌、爭取經費、建設地方。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"863bfe4a-ccce-4bb5-a8af-022dc7db89dd","items":["四大主軸：專注三鶯土樹地區之經濟、觀光、教育、文化等四大主軸建設發展。","捍衛監督：捍衛侯友宜市長福民利民政策，為民喉舌嚴格監督市政府各項措施。","身心健康：強化地區巡迴身體健檢和行動心理諮商，建立身心健康的美好社區。","婦幼優先：妥善孕婦健檢、鼓勵生育福利，爭取補助兒童疫苗與幼兒教育津貼。","老人福利：平衡各區公立醫療機構，提高敬老津貼以及智慧型照護、居家管理。","交通建設：加速土城北二高交流道、三鶯以及樹林捷運線等重大交通建設進度。","行的方便：尊重機車族群酌減2段式左轉，增設行人單車重要路口十字斑馬線。","生活流動：適度補助市民搭乘捷運，提升大眾交通運能，連結各行政區生活圈。","人才智庫：連結臺北大學、教育研究院、宏國德霖科大，構築人文科技新願景。","安居專案：盤點監視系統，增設LED節能路燈，鼓勵社會住宅之青銀共居共榮。","青銀共榮：活化現有公部門多元場域，打造青年與銀髮族融合共榮之文化基地。","社會治安：強化警力裝備，維護警務人員安全，確保民眾生命財產與社會治安。","校園安全：護童專案與各級校園安全，確保孩子能快樂成長學習，讓父母安心。","優質教育：督促永續優質教育，重視學生社會情緒力，培養孩子多元性向發展。","支薪認證：爭取代理教師比照全年支薪，推動學生參與多元課綱活動頒給證明。","勞工權益：重視勞工多項權益、強化職場安全福利，提升產業經濟發展競爭力。","城市美學：整合三鶯土樹之觀光休閒資源，盡心打造各區域特色美學文化形象。","傳產文創：設置產業和設計專區，整合傳統製造與新興文化創意形成創新產業。","休閒需求：增設市民極限競速運動和寵物活動場所，以滿足市民休閒生活需求。","優化景區：提升觀光休閒區域、美化綠意景觀，增設特色景點和必要公共設施。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"87177be4-e9f5-4e72-9631-5b528681d781","items":["校園周邊行人通行號誌汰換為新式系統，維護學童通行安全。","警局派出所優先由女警受理女性報案，維護女性權益。","改進危老重建審核建照人力不足，提升建照核發率。","護學童：賢蔚熱愛棒壘球、出身體育圈，強化學童體育發展，增進健康。協助學區安全聯盟運作、持續提升校園治安及校外通學安全。 加強動物保護、生命及情緒教育，確保學童安全學習、快樂成長。校園納入共融式遊具設置處所。優化學童營養餐點。積極處置不適任教師。","助父母：提升優質托嬰服務、增設幼兒園班級數、提升幼教師資及品質。建置彈性課後照顧系統。強化社區鄰里公園活動休憩。完善親子廁所、哺乳室設置。加強第2胎及3胎以上鼓勵生育措施。爭取育嬰假彈性運用。積極招募校園志工。改善校園家長接送區設置。","顧女性：加強性別平權教育。公共工程、政策加強公民參與、納入女性視角及觀點。強化女性報案保障措施。打造女性友善生活空間。","撐青年：支持18歲公民權。監督社會住宅進度。鼓勵未婚交友聯誼活動。強化職訓機會、就業媒合。完善娛樂休閒處所、鼓勵藝文活動。","扶長青：提升長照、安養機構數。增設長者共餐共學據點、促進長者醫療用藥社區化、強化偏遠地區及行動不便者居家醫藥服務、提升醫藥護理師權益及服務量能。協助老舊公寓無障礙環境設置。促進中高齡就業措施。關懷獨居長者。加強宣導防止詐騙集團。","挺身障：協助身心障礙、罕見疾病朋友解決困境，增加福利保障、強化社區服務、推廣身障人士運動聯誼、建立電子科技網絡服務系統。","拚建設：提升北投士林科技園區產業、交通發展。整治北投溪、復育北投石、強化北投無圍牆博物館、士林文史觀光。加強危老重建、都市更新、公共工程生態工法、保存綠地增加植樹、清理河川汙水廢棄物、發展綠能及完善綠色運輸。監督促成社子島、關渡平原開發。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["candidate_introduction","past_achievement","heading_or_slogan"]}}},{"claim_id":"876ccdeb-0c3a-426b-9b92-eadf6bad1421","items":["秉持專業問政，設立服務處，提供法律諮詢，解決縣民問題，保障縣民權利。","力行清廉從政，爭取建設絕不指定包商、不拿回扣。","嚴格審查督促縣府預算之編列，讓有限財源發揮最高效益。","監督縣府確實做好區域排水系統（石笱排水、板本排水、湳港排水、東溝排水……）整治，解決水患，保障人民生命財產安全。","持續爭取員林舊百果山風景區綠美化工程，提供更友善的遊憩環境，帶動地方經濟發展。","敦促縣府早日完成員林鐵路高架下的多功能空間規劃、東彰道路北延段（山腳路外環道），讓員林的都市機能更完善。","持續爭取經費強化永靖景觀園藝園區人口意象，提升永靖觀光能見度。","爭取設置永靖鄉風雨球場以利民眾使用。","持續爭取設置大村鄉東區消防隊，以保障鄉親生命財產安全。","持續關心地方產業發展，協助勞工就業，促進勞資和諧共贏。","關心弱勢族群，確實維護其權益。","支持青年參政機會，力挺18歲公民投票權過關，讓台灣民主更進步。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"878d5cc4-2507-40fe-b4a6-dd8dee036e5c","items":["強力監督政府，拒當「黨意」立委。","反對巧立名目編列「特別預算」，拒絕債留子孫。","揭示《COVID-19疫苗採購公文》、進口蛋採購合約。 教育平等 擔住每個孩子","國中小及中等教育教育預算提高至GDP2.5%以上（#2019年台灣2%、日本2.6%、韓國3.4%、OECD各國3.4%。）。","偏鄉、非山非市學校建立智慧校園，實現平等教育。","成立三級《網路成癮對策中心》。 顧老護幼 實現世代正義","推動智慧遠距醫療、智慧遠距照顧，弭平城鄉差距。","青年創業、育成輔導獎勵。","全面檢討修訂貨物稅、所得稅、房屋稅。","65歲（含）以上長輩健保費由中央補助。","產業創新 地方創生：全面修繕縣內漁港，轉型漁業觀光港口，漁業升級智慧產業。","產業創新 地方創生：依物價波動調升公糧收購價格，調整天然災害救助金額。","產業創新 地方創生：打造生態、文化觀光軸帶，地方創生、農村再生、產業創新拚經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"883dd346-ad09-49a4-8be3-c9804677343b","items":["教育優先：活化教育內涵、適性揚才","產業發展：促進農業永續、工商協進","長者照護：爭取長照2.0、老有所養","青年創業：打造友善環境、青創圓夢"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8847bec4-6968-4c7a-b407-1426b7c3f27e","items":["中央地方聯合建設清單 催生捷運藍線：藍線四年內動工，促機場橘線核定，爭取補助 友善生養環境：公幼倍增免學費、私幼補貼、鼓勵企業設托育 外籍勞工政策檢討：協助缺工產業發聲、放寬外籍看護之申請門檻 中區文化再生：台中州廳與車站為主，打造中區文化經濟創生基地 延長國民教育：延長13年一貫國民義務教育，納5歲暨高中，重視體育專長 動物福利入法：強化飼主課責，嚴懲虐待罰責，增加動保人力 社會住宅倍增：中央撥地撥款由市府承建，2萬戶社宅為目標 捍衛勞權勞安：提高勞工薪資、落實勞安檢查、強化勞資關係 空氣品質與能源轉型：中火每年減碳、以燃氣換燃煤機組、綠電續成長 人本交通建設：廣設實體人行道、設避車彎、無障礙行人步道 健全長照永續：長照預算增至1% GDP，以長照保險挹注財源 重返廉能執政：恢復特偵組揭弊打貪，解散肥貓機關拒絕酬庸","中央法案優先推動清單 《兒童托育服務法》、《學校供餐法》立法；《食品安全衛生管理法》修法洗產地判重罪； 《道路交通安全基本法》立法；《外送平台管理暨從業人員權益保障法》立法； 《三班護病比》入法；《消防法》修正；《新住民基本法》、《新經濟移民法》立法； 《海洋保育法》立法；《揭弊者保護法》立法；《碳稅條例》立法；《住宅區寧靜法》"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"884d41e3-68e1-4ae2-9faa-549f1994426f","items":["推動南41線佳里、西港段跨曾文溪至安南區段之交通系統建設，連結西港、佳里都市計畫與新吉工業區、臺南市主要計畫區的生活圈聯絡道路。","推動國道一號增設西港交流道紓解麻豆、佳里丶西港等地區通勤民眾前往南科的交通雍塞問題。","一區一特色公園，重視城市綠化、結合地方創生、打造樂居城市應有的共融式特色主題公園。","全力配合台61沿線濱海水陸遊憩軸帶規劃建設，發展打造臺南濱海大北門區遊憩觀光並帶動地方產業生計。","爭取提高青年生育補助津貼、延長育兒補助津貼。","爭取臺南市65歲以上長者免健保費。","爭取房屋稅凍漲、停徵追溯15年，減輕民眾負擔。","加速臺南七股科技工業區開發完成為南科供應鏈衛星基地，帶動大北門區就業機會及居住繁榮。","爭取西港區拓寬東側外環道北段建設，多年爭取的東外環道南段已完工。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"88825345-54af-480b-bc6b-59108969add5","items":["強力反對焚化爐「飛灰固型物」貯存場設在縱谷地區。","要求提升熱氣球嘉年華活動品質，強力結合推廣縱谷鄉鎮在地商家與農產品行銷販售。","協助縱谷農民及商家建構網路直播行銷通路，推動縱谷地區農民、店家建構電子化通路，增加曝光度，讓客戶滑手機輕鬆下訂單。","結合各界力量爭取台鐵增加火車停留鹿野、關山、池上的班次數量。","增加補助縱谷各鄉鎮藝文活動，提升縱谷生活品質。","增加補助推動縱谷地區農村創生。","增加補助改善鹿野、關山、池上、海端基礎公共建設，村村路平、燈亮、水溝通。","爭取補助活化關山親水公園舉辦光雕節、星光音樂會等活動，讓關山鎮成為夜間休憩勝地。","爭取縣府補助鹿野鄉公所在非熱氣球季於新良濕地舉辦湖光音樂會活動。","爭取縣府在池上、關山利用縣有土地興建收費停車場，解決池上、關山假日塞車問題。","在議會加速慢速車自治條例審查，推動電輔車合法化，協助縱谷地區慢速車租賃業納保。","爭取縣府結合民間單位，為縱谷偏鄉65歲以上老人辦理代領長期處方箋及藥物、送藥到家服務，避免偏鄉老人舟車勞頓，也讓在外就業子女安心。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"88ac7387-b427-44d9-b172-1979a6427fbf","items":["爭取提升勞工權益。","爭取路竹區省道台一線拓寬。","爭取捷運北延至湖內與台南捷運系統聯結。","爭取提升農村建設,縮小城鄉差距。","爭取計畫道路開闢並維護道路品質。","督促政府提升服務品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"88d51182-62a3-4b17-92af-9fbf4a31a1f3","items":["落實福利政策，爭取老弱婦孺、傷殘之權益。","督促政府積極河川整治及堤防建設。","爭取公、教、警察人員之權益及福利。","為農、林、漁、牧業爭取權益，並為縣民爭取更多就業機會。","支持動保、爭取經費、落實結紮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"88e07955-9bce-4d5b-b901-1602b3c68176","items":["爭取設置都會區原住民參議會，落實原住民青年公共事務參與。","爭取設置都會區原住民實驗學校，強化原住民文化復育與族語推廣工作。","爭取原住民社會住宅配額，設置青年社宅，健全原住民購屋、租屋、修繕等補助機制。","持續推動原鄉產業發展計劃，設置原住民產業合作平台，強化原住民產業經濟與創業輔導。","持續爭取設置原住民主題意象場域，強化原住民族社會認同與社會地位。","落實原住民長照政策與執行，健全文健站營運輔導，強化年長者照護工作。","健全原住民社會服務網路，強化全方位社會福利服務工作。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8916c2b2-b152-4e25-aebf-2d325c65dbff","items":["【問政與服務，靖心盡力，乘風破浪精準解決問題】","理性問政、仗義直言、實事求是、精準監督、積極爭取。","監督政府公開資訊，以民意為依歸，行政程序（說明會、公聽會等）應落實民意。","以大數據為基礎監督政府，擬定政策並作為資源配置之依據。 【建立友善移居城市，一起來做竹北人】","以「移居者友善」的思維，建立公共服務，擬定公共政策。","運用科技、改善交通，減少通勤時間。","完善育兒服務、環境與補助，建立育兒喘息機制，減輕育兒負擔。","增建公托、非營利幼兒園、國中小，提供完善安全的教學環境，減少家長壓力。","強化私幼、私校管理，減少民眾家長擔憂。","以便民角度，整合政府服務；以便捷形式（例：QR Code、AI聊天機器人），提供民眾資訊。 【宜居竹北 Demo City，全台最亮第七都】","深耕本土：深耕與傳承在地文化，帶動母語使用。","行銷國際：將新竹縣人文風情、中文繁體文學與書法藝術行銷全球。","環保永續：一切城市發展，以永續為核心。","公開政府：公開政府資訊，並提供更直效的民意彙整平台。","數位環境：建立數位公共環境（例：全市停車位、AI管理）。推動政府服務AI化。","竹北女力：發展女性平台，整合女力資源。提供創業、成長、公益多元機會。","活力銀髮：推動銀髮背包客活動，帶動肌耐力訓練，激發活力與健康意識。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8939a7ed-7628-4c70-a321-411fcdd8e7c5","items":["秉持理性問政立場，貫徹強力監督角色，積極落實為民服務精神。","主張教育第一，重視品德教育工作信念，維護教師專業自主權益。","落實要求各項治安警政與消防救災救護工作，確保人民生命財產安全。","爭取與建議貫通台 11 線、台 11 丙線丶台 9 線之東西向聯絡道路，有效縮短海岸山脈東西兩側行車時間，合理增進城鄉均衡發展。","關懷並協助推動長青、婦幼丶新住民與弱勢團體之權益福利，共同打造友善和諧社會。","在萬物齊漲的通膨時期，強力監督學童營養午餐的品質，要求提高學童營養午餐的經費補貼，以維護學童健康快樂的學習。","爭取中區污水下水道工程，早日全面執行，以縮短城鄉環境衛生之差距。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"89595337-2012-4782-b912-3ce41c3a16fd","items":["士北升級 持續前進｜永續家園：推進2050零碳台北，監督北士科技區與重大公共建設。","士北升級 持續前進｜投資青年：推動地區型創業諮詢，辦理交流與媒合活動。","士北升級 持續前進｜活化空間：活化捷運淡水線高架沿線下方閒置空間，鼓勵青創進駐。","士北升級 持續前進｜樂活士北：推廣人文歷史地景，振興在地商圈。","安居有解 樂業台北｜健全租屋市場：推動包租代管，讓房東安心出租、房客安心入住。","安居有解 樂業台北｜高齡友善換居：樓梯換電梯，改變高齡者囚老困境。","安居有解 樂業台北｜危老安全升級：打造防災的韌性城市。","安居有解 樂業台北｜落實居住正義：支持囤房稅制，穩健推動社宅興建。","育兒後盾 減輕負擔｜優化托育品質：爭取士林北投定點臨托服務，留住優質人才。","育兒後盾 減輕負擔｜減輕育兒負擔：推動、優化共融式遊戲場與社區親子館服務，精進「台北育兒網」，讓育兒資訊查詢更便利。","育兒後盾 減輕負擔｜敢婚沒煩惱：增加新婚家庭社宅中籤率。","育兒後盾 減輕負擔｜敢生沒煩惱：爭取全額補助兒童接種輪狀病毒疫苗。","陪伴長者 樂齡慢老｜提升長照量能：優化日照服務中心功能，提升居住型長照機構量能。","陪伴長者 樂齡慢老｜優化樂齡運動健康中心：增加長者活動頻率，打造長輩運動社交圈。","陪伴長者 樂齡慢老｜拓展「敬老卡」使用範圍：加速與台鐵合作，提升敬老卡便利性。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"8a1d38bb-1676-4b20-a5ab-c7ce05f70f53","items":["全力推動國小品德教育，改善社會風氣。","關注婦女及新移民權益，重視單親家庭，推動愛家運動。","重視學童上下學安全，希望增加各級學校愛心志工之預算。","繼續爭取預算充實各級學校的軟硬體設備，提高競爭力。","爭取市府預算，增設婦幼活動場所，落實老年市民照顧，廣設關懷據點。","加強監督，要求擴大公車路網，多設iBike站。","督促環境衛生、食品安全、疾病防治、確保市民健康，擴大招商解決市民就業問題。","邁向健康台中，推動公共運動中心等場域倍增，提供市民更多運動休閒場所。","強力督促市府拒絕瘦肉精豬肉及日本核食進入校園及市場。","持續反對中火火力全開傷害市民的肺，堅定支持空氣清新是市民的基本權利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8a79668b-65e8-4f72-b846-02dc189acb3f","items":["堅持做好 督促縣政工作","堅持做好 原住民權益保障工作","堅持做好 爭取地方建設工作","堅持做好 促進族群團結和諧工作"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8adbefdb-8a89-4eb3-870e-dd717c502396","items":["【為經濟找活路】 1.推動鐵路地下化沿線土地開發及活化並要求制訂「高雄市綠園道自治條例」,導入公共藝術結合文創、觀光、 休閒、運動產業來活化綠色廊帶綜效,展現園道新風貌。","推動「高雄消費日」點亮高雄新經濟,營造高雄消費新未來。【為三 民拚發展】1.推動三民區都市計畫通盤檢討,以平衡區域發展。","推動「三民區閒置土地及設施」活化或再生計劃(如:加速高 雄肉品市場遷移、活化公車金獅湖站與中都磚窯廠等場域)來提升及活絡三民競爭力。","監督三民全民運動中心如期完工並推動 「三民第二運動中心」加速設立,且結合多功能用途打造更完善運動及培訓空間。【為老幼謀福利】1.推動平價幼托,增設公共 托育中心及幼兒園來減輕家長負擔,提升幼兒教育品質。","關心銀髮世代,落實社區長照關懷,推動全齡化公園讓長輩享有更多 的休閒空間。","推動中高齡就業投入職場之運作機制及獎勵方案。【為交通更便捷】1.監督輕軌二階大順段施工期間車流順暢, 降低交通黑暗期的衝擊,避免車流溢流至主幹道,要求儘速建置大順輕軌替代道路,讓三民交通更順暢。","監督捷運黃線加速動 工興建,並推動周邊相關接駁規劃更便利【為客家揚文化】推動客家文化及客語傳承並爭取在客家義民節舉辦「客家文化藝術季 」,結合客家相關團體辦理客家傑出人士薪傳獎及客家音樂、美食民俗技藝等活動。【為觀光創亮點】推動金獅湖觀光再升級, 點亮金獅湖打造「高雄入口門戶新印象」,創造觀光新價值。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8af51d7c-6b98-464e-b892-a02b512ff01f","items":["樹林：爭取樹林捷運動工、台65線浮洲橋增設匝道、新樹鶯堤外便道完成、坡內里與東山里高地自來水通水、推動醫養專區、加速柑園都市計畫等。未來將串聯鐵路沿線產業，結合大漢溪自然景觀，讓樹林成為鐵道觀光大城。","鶯歌：爭取三鶯線動工、陶博館升級、老街翻新、改建三鶯大橋、新設鳳鳴簡易車站、鶯歌車站增設手扶梯、推動地方創生、完善工藝之家、鶯歌國小歷史校舍資產活化。未來推動建立鶯歌藝術學院，培育一流職人，點亮鶯歌工藝城招牌。","新莊：汰換民安西路自來水管、光華里及民安西路電桿地下化、民安段綠美化步道、增設民安國小地下停車場、台65線浮洲橋匝道、新樹鶯堤外便道等。未來將與樹林共同規劃工業聚落，促使產業再創生並接軌國際。"],"content_split":{"method":"section","version":"election-content-items-v1","confidence":96,"reviewStatus":"auto_approved"}},{"claim_id":"8af92e61-27b4-42bb-8e49-eeec3304d307","items":["監督市政，為民喉舌，反映民意需求。","推動優質科學教育，培育科技人才，與國際接軌。","促進產業發展，策動工商投資，發展觀光旅遊。","加速都更計畫，繁榮城市新願景。","完善長照、老年安養計畫，保障婦幼權益。","促進市民運動風氣，增進市民健康。","推動嘉義市升級計畫，東區大進步，西區大發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8b475109-726e-4842-86a5-e7ca79874b66","items":["大鳳山一二三 高雄新核心，生活新都心 1 一座產業園區 2 兩條水陸運新命脈 3 三處特區未來城","衛武營國際文化特區 兼具消費與文化，打造衛武營藝術之丘；鳳山雙中城，台鐵機廠保留與再生。","捷運黃線五甲經濟城 捷運黃線，加速興建，人潮帶來錢潮；改善空汙，創造就業，好工作離家近；招商引資，協助創業，迎接疫後經濟。","全齡樂活未來城 鳳山車站新商場，青創智慧新生活；保留軍事文化，推動眷村再生；續推特色公園，孩子成長多元；打開園試所圍牆，推動多元日照中心。","潔淨能源未來城 2050淨零城市，鳳山走向世界；推動五甲潔淨能源產業園區；鳳山溪改造，親水河岸看得到。","壯大客家 六堆客家產業門戶在鳳山；爭取世界客家博覽會在高雄。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8b536486-370d-4dc2-9a4e-fc0a3544430d","items":["廟口酬神脫衣舞無罪化，並且列為傳統保護文化。","滿18歲青年第一次成人禮，市政府補助紅包。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8b70ed94-a33c-44e7-a5d2-8cb2c4e97806","items":["(一)爭取阿蓮、田寮、路竹、湖內、茄萣地方建設,促進城鄉均衡發展。","(二)重視社區發展及關懷據點設立,配合社區需求兼併老人關懷照護措施。","(三)督促市政改善水利設施,解決各區水患,加強便民措施並加強公共工程管理。","(四)舉辦地方特產傳統文化活動,推廣地方特色,建立農漁產品品牌,提高促銷能力,增加農漁民所得。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"8bd6aead-e523-4aa7-9ba4-2bd618014103","items":["文化立縣2.0——再創宜蘭文化新風華：改造文化中心：打造宜蘭文化綠園道。","文化立縣2.0——再創宜蘭文化新風華：慶典活動升級：推動宜蘭城市新名片。","文化立縣2.0——再創宜蘭文化新風華：打開文化空間：建立宜蘭文化銀行。","文化立縣2.0——再創宜蘭文化新風華：捍衛教權、顧好童學、深耕蘭學","文化立縣2.0——再創宜蘭文化新風華：捍衛教權：議會教師代言人，捍衛教師權益。","文化立縣2.0——再創宜蘭文化新風華：顧好學童：監督縣府辦好營養午餐與安全。","文化立縣2.0——再創宜蘭文化新風華：深耕蘭學：持續推動宜蘭為主題的歷史教材。","文化立縣2.0——再創宜蘭文化新風華：微笑單車：推動宜蘭設立YouBike。","文化立縣2.0——再創宜蘭文化新風華：循環公車：整合公車班次與接駁系統。","文化立縣2.0——再創宜蘭文化新風華：步行城市：推動友善步道與通學廊道。","文化立縣2.0——再創宜蘭文化新風華：青年事務再升級：推動成立宜蘭青年事務局。","文化立縣2.0——再創宜蘭文化新風華：勞動權益要重視：監督提升勞動權益與環境。","文化立縣2.0——再創宜蘭文化新風華：性別平權要落實：監督縣府性別政策與落實。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8c6b760c-4d8a-41ff-811c-7b21fe0d7ad4","items":["督促政府儘速修復南橫（勤和～拉芙蘭）路段為永久安全路廊，使其恢復榮景，促進部落產業發展","責成市府增編部落建設經費預算，打造桃源區為宜居文化鄉城，推展原住民文化觀光產業","積極爭取預算，健全桃源區部落路平專案，建設公共衛生及安全設施","為確保部落生命財產安全，督促政府積極爭取各部落護岸工程經費預算","營造部落年輕化，爭取資源鼓勵知識青年留在部落發展長才","增設桃源區完整資訊監控系統","建山里行政區土地權責移轉桃源區公所管理","督促政府修復高山島農路，嘉惠農民，利興農業發展","極力爭取興建高中里風雨球場","設置原住民專屬假日部落市集，提供族人展示空間及行銷通路","社會住宅公設空間設置原創商鋪，族人創作品有展現機會","落實保障都會區族人，爭取租屋及青年創業設備補助","建置政府與原住民教會之夥伴關係，寬列經費，使教會自主性辦理事務，凝聚族人向心力","設立原住民人民社團同鄉會聯合辦公室，檢討並明訂各項補助規定，健全人民團體服務效能","關懷大高雄原住民軍職子弟升遷及權利維護事項","全力捍衛族人勞工權益，責成市府成立原住民勞工糾紛專屬諮詢服務"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8c73fcc4-6b6f-4429-ad6b-627339b89485","items":["監督縣政,沙實施政","致力本鄉農漁業發展,督促縣府保障農濕民權益","持續發展觀光及在地文化特色","督促縣府改善,本鄉教育環境,縮小城鄉差距","爭取地方基層建設 , 改善鄉親生活品質 了. 全心全力為民服務"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8c7bd277-3bb7-435c-8469-e214d9d4da88","items":["教育：爭取每校有公立幼兒園、公立托嬰中心。","教育：活化國中小閒置教室，設置全齡進修學堂，持續推展母語教學與老人樂齡學習與運動。","教育：督促市府加速南勢文心國小發包動工。","交通：要求市府重新規劃機場捷運線由A22中壢老街溪站繼續往南延伸至平鎮山仔頂。","交通：密集人口地區增設公私立停車場，檢討街道紅、黃線規劃，改善車位不足問題。","交通：高流量道路規劃機車專屬車道，保障機車騎士安全。","居家安全：正視老屋問題，提升老舊建物的防災性能、耐震補強專案經費補助。","居家安全：爭取老舊社區巷道安全24小時全天候防護網絡建置，普設居家防護鈴，保護夜歸民眾。","居家安全：督促市府持續興設智能社宅，並優先平價出租給在地工作青年、年輕小家庭夫妻，減輕負擔，間接鼓勵生育意願。","健康醫療：全面推動8020口腔健康法則，要使未來的80歲長者能擁有20顆以上真牙，有效提升年老生活健康品質。","健康醫療：爭取市府以BOT模式引進優質醫療機構進駐平鎮，設立兒童專責醫院、教學醫院，擴大南桃園醫療量能。","健康醫療：推動「微型保險」納入地方自治條例法制化，將低收入戶、中低收入戶、身心障礙者、弱勢單親家庭全面納保，以補現行市府急難救助制度之不足。","健康醫療：發展一公園一特色，增加共融式遊戲場。","健康醫療：爭取現有公園環保廁所全面汰換，改以大方美觀之簡易廁所取代，提升公園環境品質。","健康醫療：爭取老街溪源頭整治，步道貫通至龍潭，打造南桃園最美河川。","健康醫療：爭取現有公園規劃寵物狗狗友善活動專區。","健康醫療：放寬青年創業基金申請門檻，並提供貸款利息補貼或延長繳款期間。","健康醫療：加強扶植青農、農業復育，打造精緻農業，推廣農特產品行銷，以提高農民收益。","健康醫療：強化非典型勞工（類勞工）保險機制並提供補助，實質照顧勞工朋友。","健康醫療：爭取婦女二度就業、單親家庭創業貸款利息補貼，廣開專長培育課程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8cec666c-5771-4097-a03d-633fb45babd4","items":["▶ 陪你長大 增設0～2歲公托、0～6歲公幼及非營利幼兒園；增設特色公園；爭取高雄兒童樂園；提供新手媽媽一周到府保母補貼；公有市場增設兒童遊戲專區並聘請陪玩照護員。","▶ 校園安全 增加反霸凌獨立式課程；小學雙語教育爭取一校一外師並保障三年教學；市府半額補助營養午餐並增加有機蔬果。","▶ 婦女春天 設計夜歸女性安全通報APP；就業服務擴大納入二度就業婦女；開設職業婦女支援中心，使其兼顧工作與家庭。","▶ 婚姻綠燈 導入家事管理師協助新手夫妻；每月2小時免費共同心理諮詢。","▶ 銀髮樂活 補助65～74歲老人施打肺炎鏈球菌疫苗；獎勵長輩受訓成為社區志工；舉辦高雄阿公阿嬤運動大會，藉此培養健康習慣。","▶ 青年不魯 青年創業放貸後加強輔導機制；鼓勵台積電落實企業責任，結合楠梓產業園區強化在地社區；建立租屋透明登錄機制；研擬青年購屋補助方案。","▶ 觀光品牌 蓮池潭變更為「指定觀光地區」，建設「環潭纜車」；催生在地創生組織，支持舊城文化、鼓勵青年回流；舉辦眷村美食節並媒合眷村菜餚至超商上架販賣。","▶ 空氣清新 加速公務運輸車電動化；提高工廠污染源偷排罰款；落實PM2.5科技監控。","▶ 交通不卡 刨鋪破損人行道並拓寬面積，友善輪椅族；每三個月盤點紅綠燈缺失，促進路面暢通；開闢楠梓交流道至大中路高速公路兩側之平面道路。","▶ Welcome新住民 完善勞健保，減輕就醫壓力；持續強化母語課程，打造城市多元競爭力。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8d15d9a8-fa01-4330-add2-3e6e7f84e6e9","items":["爭取建設經費，改善各鄉鎮產業道路及水利設施。","因應極端氣候，加強山區防洪整治及平地低窪區域淹水防治工作。","透過各項產品促銷活動，全力行銷雲林優質農特產品。","爭取提高各項農損補助額度，並簡化申請程序，使農民看得到也領得到。","串連各觀光景區及農產品，活化週邊設施，提升觀光商機使年輕人願意返鄉。","督促縣府更積極增設優質幼兒園，提升未來主人翁的啟蒙學習環境。","爭取提升長青食堂補助費用及廣設社區日照中心，健全銀髮長者福利。","督促縣府更新強化警消人員裝備及增加各分駐所人員配置，提升值勤之安全性。","提升生育津貼等相關育兒補助，降低年輕人之育兒負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8d3ec2c7-8a09-4d71-b101-6ac5109a5924","items":["監督縣政、全方位問政。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"8d60020a-ba32-437e-b327-cd253c84cb32","items":["現有空地增設停車場，徹底解決停車位不足問題，並達到區域均衡建設開發。","督促政府徹底解決淹水問題達成零水患。","整體檢討都市計畫發展，加速「都市更新」及「社會住宅開發建設」。","落實長照政策，增設日照中心，65歲以上老人免健保費，提高補助老人長照津貼。","落實幼兒政策，增設幼兒園、提高生育補助，督促政府廣增設公共化幼兒園教保服務及減輕家長負擔。","爭取國中小營養午餐免費，落實食材在地化，督促為幼兒食品安全及營養均衡把關。","強力監督食品安全，維護府城美食文化聲譽。","爭取居住正義，凍漲房屋稅且不得回溯，還財於民。","重視員警、義消、義警、民防、義刑、守望相助巡守隊之裝備及福利。","爭取年輕及中高齡族群多元化工作取向「訓」「用」合一。","督促傳統市場多元化、多樣化營運，提高生活機能。","積極督促政府普設各項運動專屬場館及場所，提升競技效益。","督促政府積極開發社區公園及育樂設施，並全面檢討里社區活動中心老舊重建，落實各里都有活動中心，以提升居民生活品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8dce3f1d-deab-49e0-8741-26f1fcfbe745","items":["推動地方產業發展","爭取地方各項建設","爭取婦女權益","推動日照及長期照護","增加就業機會，協助青年返鄉工作"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8e0c3871-19d1-473e-9dca-c55dcab62cbc","items":["督促縣政府全力爭取前瞻衛福部經費,積極推動長照 2.0 日照中心,讓社區整體照顧服務體系發揮最大功能。","全力爭取社區公共托育設立,減輕家長負擔。","全力支持青年、青農返鄉各項創業經費之爭取,輔導就業。","選區鄉鎮很多住戶無自來水設施,全力爭取簡易飲水管線補助,改善民生用水之問題。","全力爭取各國中、國小教材設備更新之經費。","傾聽民意,民意在我心,民之小事,淑惠之大事。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"8e217109-c3d4-4756-b28e-a401b92daac4","items":["以運動觀光帶動地方-善用白冷圳水資源，打造大坑溪環狀步道親水公園、親水河岸。","強化運動場館無障礙環境，UBIKE多元化，增加親子共乘腳踏車、電動腳踏車，改善自行車道環線設施，加強安全標示，規劃休憩景點，增設充電樁、停車格，發展運動觀光產業。","建設大型特色公園，活化74快速道路下閒置空地，打造體適能、滑步車等多元親子活動場域。","打造特色專區，結合洲際棒球場、巨蛋及國民運動中心，賦予14期區段文創新元素。","城市智慧化、生活便利化-打造智慧城市，推動電子巡簽，APP定位報案，消防救護定位回報人員辨識，停車場空位線上查詢，公共運輸無線上網，強化地方巡守救災功能。","利用公園、公共休閒空間，設置文化地圖與電子導覽，推廣地方特色與街頭藝人展演空間，爭取北屯區大型文藝表演活動。","延展獎勵青年穩定就業，提高穩定就業獎勵金額度，鼓勵年青人成功創業。","閒置教室活化，充實無障礙學習環境，多元化社區課程，增加托老托幼據點、關懷據點空間，利用代間學習增強世代互動。","增加培訓新住民專員，媒合各項資源，提供職訓、工作協助及法律諮詢，關懷生活。","提升警消人員裝備經費，加速老舊設備汰新，確保執勤人員安全。","完善交通與建設-捷運機廠聯外道路拓寬與新建，爭取捷運支線與站點大眾運輸網絡。","公園增設地下停車場，解決停車空間不足，公用空間再造，創造便民舒適的友善環境。","增設無障礙坡道，檢討人行道與無障礙設施，讓身障者與長輩、婦幼推車通行便利安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8e7088d4-2af3-4303-be00-fc15ed54f277","items":["興建嘉義市智慧園區，打造三化（國際化、商業化、科技化）城市：結合嘉義縣鄰近四個工業園區的開發，將嘉義市打造三化智慧園區，爭取工業區總部進駐嘉義市，透過租金補貼、水電優惠等誘因，吸引更多公司進駐智慧園區，鄰近縣市工業園區人員，入住嘉義市並親近使用嘉義市之醫療、教育資源，從而提昇本市人口紅利，擴大投資消費，經由國內外商務人士往來嘉義市，進而刺激商旅發展與觀光發展。","爭取綠能建設，讓國家永續發展：重新檢視嘉義市的建設需求，以綠建築理念推動嘉義市民真正需要的中小型建設；並將每日所需的交通措施逐步轉變為綠能交通，強化已上路綠能公車、U-Bike運營系統，爭取嘉義市為綠能建設示範都市，結合嘉義廣大自然景觀及歷史文化，創造嘉義市民榮耀且乾淨的環境，讓建設達到環境親善及永續發展。","提升各階層就業機會，年輕人返鄉工作不是夢：捍衛青年勞動權益，積極創造本市就業機會，並協助中小企業，挹注在地產業發展，向中央爭取智慧園區開發，改造國有閒置空間建構AI及電競基地，協助嘉義市的產業逐步轉型為科技城，吸引國內外各大公司進駐嘉義市，增加青年、新住民就職、中年轉職之機會。","縫補托育政策漏洞，讓托育及幼教系統更完整：減輕年輕父母育兒負擔，解決台灣少子化困境，讓市民敢生輕鬆養，補助措施僅是治標不治本。重新檢視並縫補托育及幼教漏洞，瞭解市民育兒需求，從社會支持、環境改善、勞動條件等修法上改善育兒困境。","培養學童適性發展並擴大多元學習目標：精進現有硬體上教育資源的使用，各校線上學習教材內容精緻化、標準化；在軟體的調整上，適時增加教師適任性評核機制，並提高教師專業性及特殊性獎助誘因，吸引更多優秀教師至本市任教，增加教材與評量制度的多元性，培養學童興趣與專長，鼓勵適性發展，脫離填鴨式教育與考試填補的校園生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8e9c039c-59c9-4b88-b4d4-28ca935e7e83","items":["持續加強社會關懷據點功能，運用政府資源與志工力量及社會資源，讓長者在社區一起運動學習、共餐聊天，生活更充實，減輕子女的照顧壓力，家庭生活更美滿。","推動兩性平權，提供婦女更多職訓機會，增加與社會接軌能力。","持續向政府爭取經費，鼓勵年輕人回鄉投入農業，種植高經濟特色作物，振興農村發展。","持續爭取地方道路、溝渠、交通號誌等地方建設。","爭取公托及日照中心的設立，減輕所有家庭兼顧職場與照顧家裡長者之壓力。","持續推動鹿港頂番婆水五金田園生產聚落及都市計畫的規劃，力拚十年內完成，讓大鹿港地區有合法工業用地，以利地方產業發展，讓年輕人有更多就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8eb5f66e-e8f2-41a7-b73f-764ddc257f4c","items":["認真做事、用心服務。愛、關懷。把民眾的事放在心上，總是想盡辦法做好","爭取增設公立幼兒園、非營利幼兒園、親子館，減輕家庭育兒負擔；強化婦幼安全維護與長照系統。","爭取提高生育補助、育兒津貼、學校營養午餐費，檢討並放寬各項福利津貼申請標準，簡化申請手續。","督促市府積極改善空氣污染，加速汰換台中火力發電廠燃煤機組，保障市民身心健康。","爭取警消健康檢查全面補助，提升警消人員裝備經費，加速老舊設備換新，以維護第一線救災執勤人員安全。","爭取敬老愛心卡擴大使用範圍，可搭乘台鐵、高鐵等交通工具，並全額折抵搭乘計程車費與看診醫療費用。","督促市府積極推動『東南草悟道』(城南之心計劃)；東南區在地產業經濟、文化、休閒全面升級，增進商機。","督促市府於公園增設地下停車場：全面檢討公園綠地友善空間，維護公園綠地，充實市民優質休閒運動場域。","督促市府積極推動各項體育運動，廣闢室內外運動場所，培養市民運動風氣：重視寵物活動友善空間。","督促市府加快汙水接管進度，改善市民住家品質，減少河川污染，提升城市競爭力。","督促市府檢討無障礙生活環境空間，並寬列預算修繕維護，提供更安全、便利的生活品質。","督促市府增設新住民關懷據點與培力中心，增加就業機會，保障新住民權益。","督促市府推動全民閱讀文化，提高市民擁書率；充實東南區文化軟硬體建設，豐富市民藝文生活內涵。","督促市府落實捷運藍線規劃，增進東區東西交通動能:落實機場捷運線規畫，提升南區南北交通效益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"8ee3e49d-e782-4756-803f-21e7b5fa5d1d","items":["推動安樂區公共污水管線全面完成佈設接管。","監督大武崙森林公園興建符合在地需求。","推動情人湖公園週邊再生計畫。","推動劉銘傳隧道週邊停車空間設置。","推動增加安一路週邊停車空間。","推動設立寵物友善公園。 我支持18歲公民權修憲案，我也將持續推動年青人共同關心基隆、關心生活，召集大家一起「顧家鄉，拚未來」！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement","heading_or_slogan"]}}},{"claim_id":"8f1d4d43-832e-444e-8b08-d694994f7a0e","items":["維護性別平權，建構性別平等之服務設施與工作環境和機會。","落實日照與長照政策，協助修法改善老人及弱勢族群安養問題。","推動 e 政府再升級，強化簡政便民之政策。","建立各項專業事務委外審查機制，提升行政效率。","監督鐵路高架完工後，鐵路兩側都市縫合之規劃與執行工作之公平性與前瞻性。","促進雲嘉嘉區域治理平台之運作，有效整合區域資源之分治與共享。","催生市政府北棟大樓及西區國民運動中心早日動工。","建立公有停車場離場自動感應扣款機制。","推動紅瓦里、北新里及大溪里聯外道路改善工程，解決單線出入之交通問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8fa82201-5d99-4d38-a264-01c1fa3d4e63","items":["輔助青農推動智慧農業，開發精緻農物、食品加工研發，提高經濟效益。","督促農業處整合農情資訊，建構產銷平台，解決產銷失衡問題。","協助解決少子化相關問題，提高生育、育兒補助，降低年輕人負擔，強化育兒政策及托育設施。","說服國土規劃，讓土地活化使用，解決人民居住權益及產業發展，以便推動阿里山沿線觀光發展。","強化防疫監測、防疫宣導及預防資源，提升醫療衛生。","推動不老社區，讓長期照顧福利更落實。正視新住民、單親、弱勢及婦女福利，爭取培養各項技能，建立職能訓練及媒合工作平台，創造就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"8fb14efc-9647-4864-9bdd-52595f58beed","items":["鐵路地下化中壢車站設站進度加速推動。","體育園區之開發案加速推動，提升後站之繁榮。","加速中山東路、龍岡路之拓寬工程。","加速龍岡國小、興南國中之遷校工程。","爭取過嶺國小、綜合商場之設立提升過嶺生活品質。","改善青埔地區，人行步道之友善行人工程。","爭取大型寵物公園之設立。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"904eeb6b-fde0-4612-96f9-be25e042a221","items":["爭取推動中山高速公路新營交流道北上出口改善工程，解決交通瓶頸問題。","爭取新營區新東里設置立體停車場，解決停車問題。","爭取柳營科學園區。","爭取 65 歲以上老人健保全額補助，並推動偏鄉醫療接送專車。","重陽敬老金比照其他五都提高至一千五百元，並依年齡累進增加。","爭取市府編列「成家基金」，提供新婚夫妻低利貸款，婚後 3 年生育子女可免繳利息，6 年生 2 胎減免3 0％貸款償還，10 年生 3 胎可免償還，以提高年輕人婚育意願。","爭取辦理嘉南大圳新營分線（新東國中旁至長榮路橋分期分段施工）渠道改建，完成新營區藍綠軸帶人行步道建設。","持續爭取新營區長榮路以北、以西農地變更為商業住宅用地。","爭取市府廣設社區型監視系統，保障人民生命財產安全。","爭取活化台糖新營總廠土地，帶動親子休閒與觀光旅遊。","持續爭取推動東山區黑曜金咖啡公路優質化工程。","爭取鹽水月津港訂為國家級燈會永久場址，串連新營天鵝湖、後壁小南海、柳營德元埤等推動水上遊樂運動設施，帶動觀光發展。","爭取台灣蘭花生物科技園區擴大，增加就業機會。","爭取白河交流道到關子嶺風景區公路擴寬，以利觀光。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"907044c6-15d1-4ca3-8a31-eb55b47c53c7","items":["督促加速落實立霧溪南岸縣有閒置土地活化利用，帶動區域農業及觀光多元性發展。","極力推動立霧溪南岸至三棧溪北岸海域之休憩觀光發展。","積極督促徹底解決順安村及康樂村市有土地承租承購問題。","爭取解決青年住宅車位不足及北埔地區停車問題，建請利用附近公有土地設置停車場。","爭取改善北埔平交道鐵路高架化或公路下地，解決交通壅塞問題。","持續推動大北埔地區公有機構（警政、消防、戶政）原地興建辦公大樓，有效提升服務品質。","維護照顧農民、勞工之權益，秉持既有誠信、關懷、專業、服務之信念，持續為鄉親服務。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"90974c26-4d44-4814-8fcb-39e81737c3ab","items":["全力推動花東快速道路興建。","加速花蓮至吉安段鐵路高架化。","落實警消值勤傷害法律免費諮詢，並編列救助經費，讓警消無後顧之憂。","積極爭取新住民及偏鄉子女教育補助，暨就業保障。","照顧毛小孩權益，爭取往生火化補助。","持續推動社會安全、經濟繁榮、環境永續、居住正義、財政紀律。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"90e2a2c6-a639-425b-818a-fa5c09242916","items":["督促76線儘速完工，擴充王功漁港服務中心、沿線增設農產果菜市場，吸引觀光人潮購買，強化輸出通路。","督促縣府設立中科二林園區專責窗口，協助廠商設廠，保障在地員工基本占比，提高薪資水準，從根本解決人口老化、外流問題。","持續推動社區據點，強化長照衛福大樓功能，亦供婦幼、在地居民使用，保障老少婦幼權益。","第一線反映農、漁民所需，配合農田水利管理處區外擴大服務，督促縣府定期改善農田溝渠，避免第一級產業成為經濟弱勢。","透過網路、現代傳播媒體等媒介，推廣在地觀光。","利用自身法律所學，協助民眾簡易案件排除。","加強濁水溪床綠化植被，沿路種植喬木，減少大城、竹塘受六輕懸浮粒子影響。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"90e92a5b-9d91-4dc2-8df6-c526f6cee5af","items":["爭取弱勢族群福利及獨居老人之照護。","爭取壯圍鄉東西向主要道路連接（濱海公路）台二線及農、水路之拓寬修整。","規劃壯圍鄉為休閒農場及無毒農業的生產鄉鎮。","爭取自來水公司為新居民或未裝設自來水之居民免費提供公共管線。","爭取宜蘭河岸堤防段為觀光河道。","推動台灣北部橫貫高速公路開闢可行性評估（可直通桃園、台中）。","高鐵縣政中心站，都市計畫要納入到壯圍鄉美福區段。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"91c7c255-51a4-4fa6-8716-84fbc2d12616","items":["監督與維護本縣勞工權益。","協助弱勢族群對抗高房價，推動社會住宅興建。","爭取軌道產業進駐，發展軌道技職教育。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"91eabd09-b525-4774-8193-b5419f2110a0","items":["連任2屆永靖鄉長8年歷練、延續服務，了解基層民眾需求，傾聽民意，解決問題，爭取建設謀取福利。","督促縣府建立區域樹枝葉、葡萄藤等木質資材回收管道，改善堆置、環境髒亂及露天燃燒環境污染問題。","持續督促永靖鄉立圖書館新建工程案進度執行，以利如期完工，不負鄉親所託。","支持警政、消防設備提升，爭取義警、民防、社區守望相助隊、義消、婦宣隊等相關權益。","督促縣府加強各社區軟硬體設施補助，提供鄉親優質的集會休閒空間。","推動永靖鄉西區農地重劃，以解決改善農路及排水問題，增加農民收入。","督促縣府加強區域排水整治及疏濬，解決淹水問題，保障民眾生命財產安全。","督促縣府積極辦理永靖鄉園藝景觀產業園區事業暨升級計畫，以利園區後續營運管理及維護，朝向永續營運目標。","督促縣府廣設社區關懷據點、巷弄長照站，以提升對於長者的服務量能，結合社區及村里籌設關懷志工隊，守護弱勢族群及獨居長者安全，健全社會福利制度。","擴大爭取幼保服務，關懷弱勢特教學童，以提供家庭安心就業，友愛照顧學子無礙。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9270cd21-dbf3-4f68-9ebb-e6ea1bb446fc","items":["監督苗栗縣財政避免繼續惡化。","爭取興建水果博物館，促進卓蘭觀光產業發展。","爭取經費打造鯉魚潭水庫遊憩景點及周邊產業資源永續發展。","爭取大湖興建週邊道路，疏困長久以來塞車問題。","輔導青年返鄉從農，協助農村社區人文生態創意，成為農業生力軍。","積極推動各社區成立關懷據點，落實照顧社區長輩施政主軸。","努力推動臺灣正名運動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"935b436c-923d-4554-8233-bb6fef0e892c","items":["爭取爬梯機免費使用-39里無電梯公寓。","爭取各里照護家屬身心諮詢據點。","提供家屬緊急照護媒合需求。","社區發展>","督促鐵路高架下方空間再運用。","爭取守望相助隊餐費補助。","爭取70歲以上守望隊員意外保險。","建國市場、第三市場、民意街創意市集-舉辦全國性購物節。","廣辦社會住宅一以租代購讓青年住地起好房子。","爭取親子、公立托兒所設立。","爭取忠明南路地下道填平。","督促「大台中轉運中心」、「台中城南之心計畫」、「東區十全公園」，如期如質完工，開放市民使用。","女性凍卵-不孕補助。","生育津貼由一胎兩萬提高為三萬。","社福安親中心-閒置教室轉為安親與課後輔導場(媒和流浪教師帶班)","動物保護>","西川里寵物公園設置。","各里協助設置寵物自助洗。","各里設置寵物便便箱。","籌措流浪動物緊急手術費用。","協助流浪動物安葬善後。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":11,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"938b21a3-ff01-4edb-9d42-731507e17691","items":["青年新希望:全力支持18歲公民權修憲!推動青年就業、創業輔導機制,降低青年失業率,提高生育補助、提升托育政策,讓年輕人敢生、能養。","鳳山健康醫療產業園區:爭取五甲農業區轉型,打造鳳山健康醫療產業園區,引進醫學中心等級醫院進駐,強化鳳山醫療量能及資源,引進智慧醫材產業鏈,讓鳳山成為南台灣健康醫療產業重地。","強化社會安全網:爭取補足治安、公安、勞安專業人員員額,並爭取汰換老舊裝備,強化社會安全網,讓市民安心。","再現黃埔風華:持續推動地方創生結合黃埔新村,連結周邊經濟產業、文化,重現黃埔風華,打造成為全台唯一活的眷村博物館。","璀璨鳳山溪:持續推動改善鳳山溪流域水質整治,美化沿岸親水空間,打造區段親水公園、裝置藝術燈區,夜晚蛻變為璀璨燈河,吸引人潮、帶動商機。","商圈生態共榮:打造全齡無差別化特色形象商圈、市場、夜市,結合地方生態活絡在地商機,形成庶民經濟生態圈,全面振興庶民經濟。","活化閒置空間:盤點、推動活化市有閒置空間,增設育幼、銀髮樂活空間、國民運動中心、兒童運動中心等。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"93a64f2d-79f5-4381-8b94-65e644dc5ff2","items":["強化地方建設：監督市府加速北士科技園區、關渡平原、社子島整體生態開發和完善配套措施，力爭居民最大權益。推動磺港溪再造計畫並促成北投市場改建，改善三層崎公園花海品質，擴建硫磺谷泡腳池、催生河雙21公園親子共融設施、雙溪濕地公園升級改造、洲美親子共融公園及狗運動公園。","促進在地繁榮：推生士林無圍牆博物館計畫與士林夜市商圈接軌，活絡在地產業，振興在地經濟、推動北投影視音科技園區發展、爭取西基地興建多座國際型多功能運動場館、爭取公有市場攤商紓困減租。","爭取長者福利：成功恢復重陽敬老金、補發110.111年敬老悠遊卡點數儲值金並要求擴大使用範圍，恢復65歲以上健保費補助，改建浩然敬老院並增建長照大樓，催生奇岩長青樂活大樓、稻香長照大樓、秀山長照園區。","提升教育資源：推動增設公立幼兒園、提高私立幼兒園補助，及育兒托嬰各項補助。提升中小學校園營養午餐品質，全面落實教科書平價化，減輕家長負擔。","捍衛居住正義：堅持士北科技園區專案住宅、奇岩公共住宅工程品質，監督「北投區機一基地」及「士林區福順段基地」公共住宅如期完工，讓青年市民過得安心，住得放心。","維護城市治安：要求全市逐步汰換監視系統，升級監視器設備，加強監視器品質及傳輸效率，打造治安零死角。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["past_achievement"]}}},{"claim_id":"93fa4be4-0f69-4077-ac0f-0aa03916f899","items":["豐原樂活城市x咖啡藝術文化廊：舉辦咖啡節，鐵馬嘉年華，豐原新興百間咖啡店擁有深厚文化底蘊與古樸藝術，包含豐富百年糕餅、漆藝館、慈濟宮、葫蘆墩圳、廟東商圈、公老坪美景，結合全台最受歡迎的東后豐綠廊道，延伸自行車道串連行銷，超越創造精采。 后里浪漫花之鄉x幸福輕旅行小鎮：全國著名的泰安櫻花季、薩克斯風、麗寶樂園、月眉糖廠、中社花市、泰安櫻花季、后里馬場、后豐鐵馬道以及馬鈴薯、葡萄等農產，結合特色多元主題觀光巴士、火車、自行車等，營造最佳輕旅行小鎮。","交通：加速推動東豐快速道路完工通車。","交通：加速后里車站東側地區案擴大，整合舊山線、公車、鐵路、自行車等大眾運輸。","交通：加速豐原交通樞紐完善：豐原轉運站順利運作加強招商、免費公車延長12公里。","交通：推動舊山線RailBike苗栗三義勝興火車站連結至后里泰安。","交通：國4銜接台74線（豐原潭子段）順利完工。","交通：推動山海環線火車，串聯大台中帶動發展。","青年：成立「青年局」，將青年事務整合在其内，透過具體政策力挺年輕人。","青年：推動新苗計畫，整合中央及地方的資源，讓青年創業初期就受到照顧與扶植。","青年：盤點台中的閒置空間，包含豐原林務局宿舍群歷史建築，並成立共享辦公室，降低青年創業成本門檻，擴大創業孵化器，進一步投入資源助創業者發光發熱。","環境：營造市民為本的空間，行人自在、騎車暢通。","環境：推動親子共融公園建置，增設友善寵物空間。","環境：旱溪、軟埤仔、葫蘆墩圳溪整治，打造豐原水岸生態地帶。","環境：全面優化綠空廊道。","環境：反空汙，最高規格把關污染源，確保居民健康，落實低碳城市。","經濟：加速推動豐洲工業區第二期，推動豐富專案，加速豐原興建國民運動中心、后里科學園區擴張。","經濟：加速在地商家智慧化電子支付。","經濟：推動觀光活動引流人潮：咖啡節、自行車嘉年華、糕餅節、麻笋文化季，強化后豐在地品牌行銷。","經濟：加強后豐在地特色產業輔導升級：木工機、漆藝、觀光工廠等。","經濟：活化豐原廟東、后里泰安商圈。","經濟：促進青農返鄉。","教育：爭取實驗教育，推動創客教育，加強雙語教學環境、強化學生職場體驗。","教育：推動后豐社區大學、樂齡學院完善、強化三級學校體育教育，增加基層教練、運動防護員、相關獎金。","教育：增加辦理台中親子文化活動，增加文化藝術展演空間。","生活：善用社宅空間增設長照、托嬰托育及創業點，資源共享。","生活：設置中市專責都市更新及住宅法人機構，強化社宅及都更新政策推動效能，提供高居住品質及服務。","生活：擴大包租代管，加強管理機制。","生活：65歲老人健保持續補助，顧長輩也顧未來。","生活：監督長照政策、落實關懷據點與醫療網絡連結，增設銀髮健身房，提供完善照護。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"94adf174-4ad2-4a7c-bb93-0f65d6048f23","items":["督促縣府擴展就業計劃，創造就業機會，提升各階層民眾就業率，以免人口外流。","督促縣府提高生育補助方案，使青年人生育意願提升。","督促縣府落實老年人「長照計劃」，讓民眾方便申請，並加強宣導，減少民眾負擔。","督促縣府做好「防洪排水」工程，對於「災害補助」能夠提高，尤其是農民的「農作損害」部份，方便申請，減少負擔。","督促縣府強化「食安」做好各項檢驗，以確保民眾健康。","督促縣府加強「治安」，尤其是「校園維安」，讓民眾生活更安全。","督促縣府注重各項體育發展，加強補助各體育運動項目，提升體育運動人口。","屏東縣有「好山好水」請縣府多方面的加強宣導，提升屏東的觀光。","督促縣府加強「新住民」的照顧與輔導，使其安心，能照顧好家庭。","請縣府多著重客家文化的活動與傳統，讓客家文化能發揚光大。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"94fb0b76-655a-4d68-a1ec-29ea59c63f49","items":["我來守護｜老人福祉 推動樂齡學習、完善長照，普及年長者健康照護服務，減輕照顧者負擔，打造友善老人適居環境，讓老年人身心權益再升級。","我來關懷｜婦幼政策 爭取生育補助政策，提高生育率。要求增設公立托嬰、公立幼稚園，減少年輕夫妻負擔。","我來爭取｜弱勢權益 推動弱勢關懷政策，落實無障礙友善環境。","我來監督｜督促縣府 要求提高公部門行政效率，監督縣府預算與執行合理透明，避免縣府濫用公帑。","我來努力｜偏鄉權益 強化偏鄉建設與發展，爭取各鄉鎮道路改善計畫。於常發生交通事故路口增設路燈、監視器，讓治安零死角，保障用路人們的安全。","我來維護｜社區需求 提升與更新村里社區的硬體設施，汰舊老化設備，活化社區村里民間的共享生活，打造村里與居住者的和諧共用空間。","我來用心｜青年返鄉 協助返鄉青年能夠生根地方，落實產業園區開發主旨，完整招商、提升就業，讓青年願意返鄉工作。","我來捍衛｜農民精神 協助農民轉型耕作，提升農業精緻度，強化在地農產品推廣市場，換取更高能見度；並且協助農民增加第二與第三專長，讓農民可以安穩過生活。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"95003930-8c20-4e6c-87d2-e566838b805a","items":["推動國土復育，監督政府於2026年完成移撥500億預算至國土永續發展基金。","支持「2050淨零排放」、「以核減煤」、「以綠永續」，確保穩定供電，務實發展再生能源。","支持消防改革，完善救災設備，增補消防人力。","推動修法，當稅收超徵時，應優先減少舉債、擴大照顧弱勢、挹注勞保基金、公教退撫基金與全民健保。","打黑金、恢復特偵組，支持徹查弊案；反對毒品除罪化，支持成立緝毒署。","「止戰於境外」，國防邁向精兵化；「備戰而不啟戰」，用實力確保和平，絕不輕易開啟戰端。","支持以對等、尊嚴、友善原則，重啟兩岸對話，持續推動交流，恢復台海和平與穩定。","支持簽署經貿協議及加入CPTPP等區域經濟整合，提升企業加薪誘因、鬆綁法規，增加勞工就業機會，創造經濟成長良性循環。","挺青年、顧青年、輕稅賦，推動青年政策專法，減輕青年學貸壓力，青年購屋超低利，提高扶養扣除額。","永續長照、放寬巴氏量表，長者安養免煩惱；檢討長照特別扣除額，改善長照家庭經濟負擔，強化社會安全網。","0至6歲國家養，增加幼保幼教經費、親屬照顧津貼。","監督捷運萬大線第一期工程，朝2027年底完工目標邁進。","監督中正橋改建工程，早日完成川端橋復舊，供行人休憩使用。","推動捷運中和光復線延伸至台北市光復南路（原中和公館線），儘早啟動可行性研究。","支持加速都市更新、協助公辦都更：大陳單元、行政園區都更。","增加停車空間：支持增建永平國小地下停車場。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"952cf790-77bc-45a7-9e65-e43c75ed1aa5","items":["基層出身 為民發聲 涂權吉｜團結拼輪替 台灣再出發 看得到 找得到 做得到 「從議會出發，往國會前進」 中央缺少許多來自地方的聲音，阿吉一路從基層歷練，擔任立委主任秘書及議員十幾年，熟悉行政法令與程序，希望把更貼近基層的聲音帶入中央，為鄉親爭取更多建設與福利！ 涂權吉主張","監督落實航空城五大承諾","修法加重詐欺罪刑期至20年","重啟特偵組追查高端疫苗、進口蛋","全面檢討課綱，重建國家認同","調漲公糧收購價，保障農民收益","檢討解編特定農業區，活化活用價漲歸農 涂權吉反對","反對官派，「水利會還給農民」","反對「SRF垃圾發電」進駐觀音","反對執政黨「實質廢除死刑」","反對「1年義務役」，兩岸和平青年不用上戰場","反對「非核家園能源政策」，以核減煤養綠 爭取經費，建設地方！大園、觀音、新屋、楊梅，共融共好"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9561bd52-12ee-4485-a158-aa354422ab79","items":["您的意見就是我關心的事務。LINE ID：0918762128","協助社區發展多元特色，增加補助社區活動經費。","改善職場環境、促進職場工作平等，使勞動者得以兼顧家庭與工作之要求。","督促縣府提供更多元微型創業平台，提供更優質青年創業機會。","督促縣府加速河川疏濬、區域排水整治，解決淹水問題，確保民眾生活安全。","督促縣府輔導農民發展精緻農業，改善農業發展，增加農民收入。","強化失智症老人照顧，提供居家服務及日間照顧服務，並輔導機構廣設失智症照顧專區。","積極推動長期照顧服務，強化發展居家式、社區式與機構照顧等多元連續性服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"95a3110b-10c4-42e5-980a-30ec46d3528e","items":["持續監督道路改善計畫","監督暖暖區道路改善計畫，保障行人、機車族路權，串聯人行道，盤點閒置公有地設置停車空間，回應停車需求。 穩定國道客運","強力監督市府扛起責任，積極處理，研議改善班次路線問題，甚至評估其他業者進場的方案。 基隆市公車營運改革／R86班次補足","續推跨區、醫療公車路線及動態系統檢討，提高市區公共運輸使用率。","續推市公車補足R86路線班次，增加八堵車站接駁載客運能！ 捷運八堵站落實公車接駁系統","提升暖暖區包租代管社宅數量，監督市府陸續興建社會住宅，小家庭住／租沒問題。","續推市府成立長照專責單位、補足專業人力、布建日照中心。 守護未來棟樑，兒童教育／遊戲權不可少","續推市府重視參與式設計，邀請親子參與鄰里空間改造，重視兒童遊戲權！","守護「教育基金」直接用於教育，提高教師合格率。","暖暖好街區 好生態 好生活：青創基地一起來！續推過港路及暖暖街市有閒置宿舍活化方案，民眾提案來改造。","暖暖好街區 好生態 好生活：續推暖暖淡蘭古道、暖暖溪散步道，以手作步道串聯暖暖區山徑系統。","暖暖好街區 好生態 好生活：持續陪伴社區討論空間規劃、改造方案，告訴市府「我們要這個」！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"95aa3683-b640-4808-9a32-4b0c4d469566","items":["持續督促市府從「水利交通」、「行政經濟」、「醫療衛生」、「知識教育」等四大面向，讓府城古都的未來發展邁向智慧型的創新與活力。","水利交通 （一）完成開闢德糖路通往奇美博物館。 （二）完成開闢高發三路通往高鐵站區。 （三）加速開闢台86線東西向龍崎延伸至內門。 （四）爭取開闢仁德勝利路通往文華路並持續督促三爺溪及港尾溝整治工程。 （五）爭取文賢消防隊、德南派出所遷建至仁德區崑崙路。","行政經濟 （一）關廟果菜市場，回歸地方使用。 （二）推動高鐵站區之會展中心辦展、參展、舉辦會議、商務等，帶動台南經濟發展，提升國際城市的競爭力。 （三）推動開發港墘段綠能產業園區，創造地方與產業雙贏。","醫療衛生 （一）推動高鐵站區設置成大醫院造福偏鄉地區。 （二）推動規劃健康園區、醫療中心。","知識教育 （一）爭取公立學校設置附屬幼兒園。 （二）關心學童教育，推動雙語學校。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"963abee7-62c1-45b6-944e-72b4d45ee5a7","items":["**與侯團隊鬥陣「侯侯做代誌」** 攜手侯友宜市長一起打造世界級城市。","**善用國道系統交通道優勢 改善汐止交通**","督促康寧街增設國一道口匝道如期完工。","推動國道三號南向銜接環東大道。","**提倡公共運輸並提升公共運輸環境** 推動台鐵納入大台北公共運輸月票項目、公車路線優化並全面汰換為電動公車。","**交通平權** 交通規劃以人為本，市區道路汽、機車使用平權。","**推動保長坑工業區轉型** 保長坑傳統工業區轉型高附加價值產業以提供市民待遇較佳之工作機會，同時分流往台北的交通壓力至汐止與基隆交界處。","**友善的社會 多元進步的新北市** 新住民、單親及同婚已成為社會的新常態，讓新北市成為兼容多元的溫暖城市。","**公托、公幼再升級** 持續提升公托、公幼收托量能，並因應不同工作型態的家庭提供更多元的托育時段。","**放寬敬老卡適用項目** 鼓勵長輩外出活動保持身心健康，爭取放寬每月480點敬老卡適用項目，讓長輩能公平的使用自己的權益。","**理工背景 務實推動智慧城市** 協助新北市政府與最新的科技與技術接軌，以提供民眾符合時代需求的公共服務。","**青春山海線 建立有山有水美麗家園** 以青春山海線為主幹串聯北海岸各鄉鎮，以地方創生打造具DNA的特色地方品牌推動觀光。","**環境永續 留給下一代宜居城市** 推動新北市2050淨零碳，擘劃以土地為主人的城鄉規劃。","**活化閒置土地 打造樂活空間** 持續盤點公有閒置土地，增闢都市綠點、特色公園、寵物專區或特定活動所需空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9644c26a-ddd5-4cc4-98ca-6ad1d2ae7969","items":["爭取縣府第二行政中心於竹南頭份共同生活圈設立。","持續推動全縣人手孔蓋地下化，並提案修正自治條例，要求管線挖掘後應即刻全車道修復以確保道路平整；推動共同管溝，減少道路因挖掘而毀損。","爭取非營利幼兒園增設幼幼班，盤點閒置空間建置公辦民營托嬰中心。","讓長輩活得健康有尊嚴，爭取65歲以上長輩免費安裝假牙。","盤點閒置空間，爭取建設頭份竹南地區寵物公園。","持續提案完成各項自治條例、行政規章的制定、修正。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"964b6b35-a22b-4e85-87c6-67d812f33432","items":["兒童教育福利：建構安全兒托育環境,爭取設置托安全設施。","兒童教育福利：爭取設置公托公幼,減輕家庭家長負擔。","兒童教育福利：幫助弱勢兒童爭取福利,建立專責輔導追蹤機構。","兒童教育福利：普查校園設施安全,爭取修繕經費補助及發展學校景觀特色。","兒童教育福利：落實兒少福利與保障,設專責輔導部門追蹤成效。","青年創業福利：設置青年正確就業資訊平台,提供公開資訊避免誤入陷阱。","青年創業福利：爭取青年創業補助,設單一窗口協辦理。","青年創業福利：青年創業平台媒合,建立青年創業詢專責機構。","青年創業福利：提升青年社會參與,建立青年事務專責機構。","青年創業福利：舉辦青年經驗分享交流座談,及戶外正當休閒活動派對展現活力。","銀髮族福利：增加高齡友善空間設計,設長者安全設施活動空間。","銀髮族福利：鼓勵社區銀髮族戶外活動,提供專用安全便捷交通運具補助。","銀髮族福利：落實銀髮族長照照護,透過各種管道廣為宣導服務內容與品質。","銀髮族福利：增加無障礙設施空間,打造銀髮族行動無礙設施。","銀髮族福利：打造銀髮族樂活場所,完善銀髮族的生活品質。","銀髮族福利：建設主題特色公園兼具休閒與教育功能,增設遮陽保護避免設施受損。","銀髮族福利：監督鐵路地下化及捷運周邊市容景觀改造。","銀髮族福利：鼓勵學校與社區結合,進行景觀美化成為藝術文化城市。","銀髮族福利：設置人行專用步道、自用道,採取人車分流安全措施。","銀髮族福利：維護社區自然生態景觀,促進友善環境升級。","銀髮族福利：活絡在地產業,振興在地經濟,置東區商家索引。","銀髮族福利：促進重要道路交通順暢,增加設置汽機車合法提停車格。","銀髮族福利：鼓勵老屋新生,活化市定古蹟或閒空間如州立農事試驗場宿舍群建築。","銀髮族福利：推動設創意文化市集,假日商圈,社區市集,促進社區鄰里商業互動。","銀髮族福利：打造社區意象新地標,促進臺南藝文化再升級。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9679cb32-9fe5-4509-b3f5-069f9c07d608","items":["爭取縣境內的台鐵鐵路高架化。","爭取調降房屋稅率。","推動阿里山森林鐵路的復駛進而帶動大嘉義地區觀光旅遊。","持續改善低窪且易淹水地區之治水，如水上鄉溪洲村水閘門、滯洪池及抽水站的功能提升。","爭取各項農業設施補助，協助農產品品牌建立，提高農產品附加價值，健全產銷制度及爭取農水路改善經費。","爭取新住民、婦幼和弱勢族群權益。","爭取醫護權益，提升醫療品質。","持續爭取提升警消人員超勤津貼。","建議縣政府推動有利提升民眾生活品質與身心健康的相關課程。","結合北回公園第一館及第二館提升為太空科學教育中心。","堅持反對日本核災食品入嘉，落實食品安全監督機制。","要求縣府致力於就業機會的提升，讓年輕人留嘉、返嘉，減少人口外流。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"96f7117d-e228-454e-a9ba-a75b5bd9c524","items":["好交通：社區小巴連捷運，市民通勤好便利","好交通：監督捷運北環段如期完工，交通大進步","好交通：北士科交通總規劃，行車好順暢","好安心：懷孕婦女產檢、新生兒6個月內接種疫苗交通補助，育兒好安心","好安心：落實高風險幼儿園退場制度，上學好安心","好安心：二胎家庭社宅優先入住，居住好開心","好生活：特色親子共融公園，大小朋友好開心","好生活：爭取士北水樂園，消暑好去處","好生活：設立次分區日照中心，銀髮好樂活","好環境：降低公辦都更門檻，提高重建意願，居住好環境","好環境：放寬容積率獎勵，增加都更意願，居住好安心","好環境：加速設置智慧垃圾回收站,不用再追垃圾車"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"97469f9f-2e58-402c-a7fa-ac64d46c8ab0","items":["爭取中山區快捷公車班次增加及多元化路線，讓通勤民眾更加便捷。","基隆西岸纜車，由國門廣場串聯到太平青鳥及 KEELUNG 地標帶動商機。","市府路平方案推動，讓道路品質全面提升，降低交通意外。","自來水管全面替換，降低破管率，讓供水更穩定。","停車位不足問題，爭取閒置公有土地增闢停車空間。","設置基隆市寵物公園及中山區親子共融公園。","外木山風景區進行整體規劃，串連自行車環海路線，美化海興觀景平台。","西岸文化觀光廊帶，串連球子山燈塔、防空洞、仙洞巖、佛手洞、白米甕砲台、外木山海景，增加"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"97f8e0fd-f912-4b2b-8e0c-0f54e5d11a3f","items":["持續爭取軟硬體建設，增進地方發展。","持續爭取獅頭山開發為綜合發展中心。","持續爭取原住民土地、文化轉型正義，還我族人尊嚴及權益。","持續爭取部落文健站、關懷站、課輔班環境改善。","全力配合協助公部門、各村、社區、學校、教會、青年會推動各項發展。","持續爭取鄉內河川疏浚、野溪整治以維護鄉民權益及財產安全。","持續爭取農產行銷及價格穩定，增加農業資材補助數量及金額。","持續推動電力公司變電所、國防部射擊場遷移案及敦親睦鄰工作。","聯合屏南地區民意代表、鄉鎮公所、議員爭取建設屏南快速道路及輕軌觀光火車以解決交通問題，增進觀光發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"98546891-ee79-4f40-b3e9-de238dbda290","items":["持續監督捷運藍線、國道匝道進度，推動市民大道第三期、加速延伸南段第四、五、六期規劃並施工。","規劃推動電桿、電信桿地下化，爭取公有停車場，老舊社區及易淹水地區自來水管汰換工程，下水道工程改善。","監督實現「台中零虐童」目標，增設公立幼兒園及托嬰中心。","推動未成年禁用電子煙、加熱煙，持續推動新世代反毒策略。","推動公立高中以下校舍耐震能力改善計畫以及太陽能節電計畫。","培育在校技術人才及建置產業鏈計畫，推動雙語持續紮根太平。","輔導設置中小型產業專區，提升產業競爭力。","爭取設立長輩關懷據點，增設長青學苑。","強化社會安全網，提升警消、社福聯繫網絡，及早協助脆弱及高風險家庭。","爭取推動老舊市場環境改善，強化食品安全及管理機制。","爭取農業生產資材補助，加強水果及優化農產品市場行銷與加工。","加速推動台中巨蛋，引進大型演藝文化產業。","加速推動台中海洋館開館，包括水母專館，以及白海豚生態環境保護專館。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"98a62649-8eeb-4f7c-93c0-f6cb10482814","items":["交通平權：捷運東環段與民生汐止線加速動工，捷運工程期間強化道路交通維持措施；爭取拓寬港湖聯外道路與港墘大橋興建、強化大數據運用分析，有效降低塞車指數。","交通平權：推動道路平權、為機車族群發聲、督促市府全面檢討，放寬對機車不合理限制；爭取公共場所參建停車場，解決停車需求。","交通平權：水域平權：水域活動開放區域回歸「原則開放，例外禁止」之立法原則。 【友善動物】加速興建新動物之家；持續推廣設置寵物活動公園，讓台北市成為友善動物城市。","交通平權：危樓、海砂屋獎勵優先更新、簡化都市更新流程。","交通平權：加速汰換瓦斯老舊管線，以維用氣安全。","交通平權：提高老舊房屋健檢獎勵，推廣安全社區認證。 【食得安全】要求加強稽查、落實管理、資訊公開透明，食品安全不可輕忽。 【拚得放心】爭取增加公立、非營利幼兒園名額；提高生育獎勵金；增設社區公共托育家園、公辦民營托嬰中心。 【老得安心】恢復重陽敬老金、擴大敬老卡使用範圍、推廣銀髮照顧在地化、獎勵青銀共居、加強日間與居家照護。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"98a6f0ba-1061-445e-b34a-0e6d7c140b98","items":["堅持清廉、勤政、愛鄉土之從政理念，捍衛台灣主權，堅持國家主體性。","支持「屏東向前、打造希望城市」之理念推動縣政，包括留縣升學、返鄉就業、在地安養、藝文發展、重大交通建設、醫療產業升級。","秉持著公平正義的精神，維護社會安全，並強化本土基礎教育。","擴大照顧新住民、單親、隔代教養及脆弱家庭等希望學童之課後輔導與學習。","協助整合政府與民間之慈善團體資源，對於弱勢家庭及邊緣戶能提供更有效率、實際之幫助。","促進萬丹、新園、東港三鄉鎮之在地觀光產業，將宗教節慶、藝術文化、自然生態及人文景觀做串連性整體規劃，以發展在地特色觀光。","推行萬丹鄉設置農特產品展售中心，透過改善農產品品質、升級農業生物科技產業及紮實農業結構，保留傳統農業精神，支持在地青農轉型農業經營型態，並朝向永續發展之價值。","開創新園鄉社區總體營造，落實社區福利制度之完整。協助漁村新興觀光產業之活絡，督促開發鹽埔漁港，以增加在地就業機會。","振興東港鎮觀光產業，將特色美食、在地宗教文化慶典以及地方觀光景點行銷至國際。","重視校園安全，積極爭取經費改善校園軟硬體設施之完善；維護鄉鎮道路安全，爭取地方公共建設，照顧人民權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"98d90834-140d-4966-82d5-9a67740eb165","items":["重視教育、關懷弱勢、專業問政、堅持清廉、認真服務。","教育是根、文化為本。協助整合教育資源，充實各項教學設施，推動特色學校；關懷學習弱勢學童，強化補救教學與輔導機制，成就每一個孩子。","爭取警察、消防人員加班費及權益；提升治安、交通、消防救災設備，保障警消人員及民眾生命財產安全。","爭取監視系統裝置及運作，建立鄰里社區安全互助網；支持檢警社區合作，全力防制毒品危害。","協助弱勢家庭，保護受虐婦幼及新住民。","督促縣府加速辦理公共設施保留地通盤檢討，促進土地有效運用。","利用公有土地開闢停車場，增加市區停車空間。","保障行人權益，適度增闢人行步道。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"98d9b65f-0482-4980-b7b8-4d77501fe6f2","items":["建立農業新典範，發展農業特色。","均衡農工商發展。","改善行政效能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"99016f49-2b39-41bb-b063-9834458c1faf","items":["捍衛生存環境品質，有效監督：噪音、河川、生態等相關汙染，提升縣民生活品質。","監督提升治安品質及加強警務人員安全防護裝備，有效打擊犯罪。","加強促進提升育兒津貼、學童教育補助及學校相關安全維護。","強力監督酒駕安全取締。","要求改善觀光風景區交通紓解問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9919fd77-7951-4044-81eb-a1ed52ca5262","items":["發展青年創意經濟：推動成立原住民青年創業輔導團、推廣中心及行銷平臺","發展青年創意經濟：推動原住民運動人才培育及運動產業發展","發展青年創意經濟：培力原住民公共事務青年人才","增加原民醫療資源：設置原住民族醫療及長照專責醫院","增加原民醫療資源：推動原住民學齡前兒童牙醫補助","增加原民醫療資源：推動原住民勞工醫療險補助","增加原民醫療資源：推動原住民長者復健補助","提高婦幼長者權益：落實原住民長者權益適用年齡全面降至五十五歲","提高婦幼長者權益：推動市府設立原住民族權益促進委員會","提高婦幼長者權益：建置婦幼家庭安全網路","振興原住民族語言：督促市府落實使用各族語言舉辦各原住民族活動","振興原住民族語言：爭取獎助族語家庭、托育托嬰機構設族語保母","振興原住民族語言：推動建置本市免費族語終身學習資源設備","振興原住民族語言：爭取獎助族語宗教團體","落實原民居住正義：推動增建原住民族社會住宅及青銀共居住宅","落實原民居住正義：提高購屋、住宅修繕、租金補貼預算","落實原民居住正義：全面推動聚落營造、在地創生及原住民共融公園","實踐族群文化傳承：推動原住民族重大歷史事件納入本市鄉土教育課程","實踐族群文化傳承：督促市府舉辦原住民族國際音樂節","實踐族群文化傳承：推動新北市族群平等自治條例"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"991c1d69-321b-49ed-b0c5-ab3c57888761","items":["爭取弱勢族群、新住民社會福利、地方建設經費，創造移居舒適環境。","行銷特色產業及觀光，促進地方經濟發展。","強化農產品產銷策略，造福農民生計。","為農民爭取農水路改善。","爭取勞工權利及在地青年就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9943d1ca-112e-4124-b25b-705b0bf15b03","items":["繼續推動小東工業區休閒運動中心（設計已進入審查階段，約6億）","爭取五福公園地下化停車場及街內六里的活動中心（納入前瞻計劃）","爭取經費改善斗南火車站前閒置10多年的地下停車空間，成為機慢車停車場（已進入設計階段）","爭取經費改善大埤農水路問題","推動華山觀光基礎建設"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"9967b4e0-6c3a-419c-a1a1-f4b48361be7a","items":["增設公托機構，減輕家長負擔","充實教育設備，改善學童膳食","重視弱勢扶助，提升長照品質"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"99d86bce-534b-45d3-adc5-dbe4ebdcf36b","items":["我全力推動新豐區的建設，長期關心弱勢團體以及獨居老人，輔導弱勢孩童英文以及為婦女團體發聲，注重社會安全，重視地方產業及觀光發展未來我會加倍爭取新豐區各鄰里基礎建設改善，如道路重鋪、水溝排水改善、交通號誌改善，以及擴大爭取特色公園等。","我會持續爭取以下建設：■爭取設立新豐區國民運動中心、關廟風雨球場。","我會持續爭取以下建設：■緊盯沙崙區域醫院成立與相關進程，提升新豐區市民醫療品質。","我會持續爭取以下建設：■緊盯捷運藍線規劃，要求市府加速辦理推動。","我會持續爭取以下建設：■增加新豐區公車接駁站、Tbike站、長照喘息服務的落實。","我會持續爭取以下建設：■活化86橋下空間，建置特色公園，汰換罐頭遊具設施，持續打造共融式公園。","我會持續爭取以下建設：■在地傳統市場再生，環境及設施改善，推動青年返鄉就業","我會持續爭取以下建設：■全面提升校園安全，補足校園警衛經費，並防堵毒品污染校園，加強宣導18歲以下禁菸(含電子菸)之健康觀念。","我會持續爭取以下建設：■爭取增加重要路口監視器數量，確保交通及社區安全。","我會持續爭取以下建設：■平衡南北歸仁發展，堅持保留在地文化，爭取活化社區老宅帶動觀光。","我會持續爭取以下建設：■持續爭取市府擴大辦理「登月計畫」(拒絕月經貧窮)。","我會持續爭取以下建設：■爭取活化現有社區活動中心、加碼補助共餐活動餐費，愛心不間斷。","我會持續爭取以下建設：■擴大辦理老人健保補助，逐年編列預算，逐年放寬年齡限制。","我會持續爭取以下建設：■建置關廟婦女親子館，增加婦女、親子活動場域，促進二性平權。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"99fec5ec-adb8-4b64-9acf-d738cc3268fb","items":["推廣設置公托公幼中心，提升公托公幼比例，解決年輕世代育兒難題。","擴大青年及弱勢族群租屋補貼，以實踐居住正義。","推動校園飲食教育，讓學生認識食物原形及來源，培養正確飲食習慣，為國民終身健康從小奠基。","督促市府落實設置智慧即時交管中心，以人性科技改善交通壅塞問題。","推廣都更設置公益性地下停車場，並請市府提撥部分停車費設立維護營運基金。","推動臺中車站周邊設立電商特區。","持續推動中西區都市更新。","督促市府面對毒品及藥害環境衝擊問題，確實建立藥物回收機制，並於校園進行反毒及藥物正確回收教育。","持續督促市府針對公衛以及用藥問題擴大稽查，藉以提升公衛水準、維護民眾健康。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9a417452-0e15-45d7-982d-aa26fa2f6d8a","items":["為弱勢族群發聲彌補政府福利政策不週延產生的不公義。","爭取廢止徵收建國自助餐私有土地。","為建民路，光復路，柳州街拓路迫拆戶，爭取保持原狀，為底層弱勢百姓，爭取生存權，財產權。","爭取林森路一巷105年7月29日被封路，於105年12月5日通過都市計劃道路變更，於111年8月15日拆除障礙物，爭取年底通車。","監督改善大洲里社區高震音高震動，噪音污染。","監督改善大湖里污染地下工廠並勸導遷移。","爭取畜牧業離社區數十公里由縣府類似工業區模式設污水場出租私宅統一集中飼養解決污染惡臭。","爭取保護楠仔樹頭營二戰歷史遺蹟，勿遭破壞。","爭取工二農地還民，頭前溪勿設產業園區污染社區。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9a572f73-1a8c-4a1a-a5b6-71b4e2f6ca62","items":["雙語教學、外師入校：推動外籍師資入校、英語口說APP全面線上學習、英語分級跑班教學，爭取每校設置AR、VR英語情境教室。","放心生養、婦幼照顧：爭取孕婦產前補助加碼並提高育兒補助，盤點閒置空間做為托育場所；爭取增設準公幼家數並增加公幼學期訪視和年終考核機制。","寶貝孩童、消除霸凌及毒品：保護學童，落實校園反霸凌措施並研議不定期尿篩驗毒，嚇阻毒品入侵校園。","主題環境、友善閱讀：持續爭取打造主題圖書館，監督三重分館(中正堂)改建進度，營造有趣環境，培養孩子的閱讀力。","倡遊戲權、統合發展：持續推動校園及公園遊戲場設置特色化、共融性遊具，促進孩童感覺統合發展，保障孩童遊戲權。","平價優質、老人照護：爭取加碼補助長照服務，降低長照家庭費用負擔；爭取廣建銀髮安居住宅，持續監督三重銀新未來城新建工程。","平價社宅、租屋加碼：爭取廣建社會住宅；提高租屋補貼，降低申請資格，減輕單身青年與婚育家庭負擔，落實居住正義。","呵護毛孩、倡動物權：設立動物保護自治條例，提升新北市動物權，打造動物友善城市。","提升醫療、促進發展：督促蘆洲南北側農業區都更進度，增設區域醫院及新建多功能大樓，扶老托幼最安心。","容積提升、居住安全：爭取提升蘆洲容積率以便加速危老建築改建及都更速度。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9acbba14-0275-49be-ab90-bae30209ded1","items":["文教提升 優化學習環境：增設0-6歲公托、公幼及非營利幼兒園，孩童學習無負擔。","文教提升 優化學習環境：持續推動特色公園，改善遊具，讓兒童開心健康成長。","文教提升 優化學習環境：改造台北市立動物園軟硬體，成就亞洲最大、世界一流的服務品質。","文教提升 優化學習環境：致力於文史、生態保護，持續推動蟾蜍山景觀範圍全區規劃與保存。","活絡商圈 繁榮地方經濟：精進貓空、貓續與貓熊『三貓商圈』計畫，發展在地特色商圈。","活絡商圈 繁榮地方經濟：持續推動東區大型活動在地舉辦，再創東區商圈熱鬧榮景。","活絡商圈 繁榮地方經濟：打破商圈不合時宜管制規定，讓市民頭家安心做生意。","活絡商圈 繁榮地方經濟：協助市場、捷運地下街攤商經濟復甦與轉型，活絡攤商經濟。","活絡商圈 繁榮地方經濟：強化建設 打造宜居城市","活絡商圈 繁榮地方經濟：已促成萬隆變電所正式地下化，未來致力空間規劃，促進地方再發展。","活絡商圈 繁榮地方經濟：成功催生公辦都更2.0，持續推升都更成功案件數量。","活絡商圈 繁榮地方經濟：推動道路雙語告示牌，打造國際友善城市。","活絡商圈 繁榮地方經濟：加速捷運南環段、東環段建設，並爭取博嘉里設站，便捷民眾通勤。","活絡商圈 繁榮地方經濟：照顧弱勢 促進社會關懷","活絡商圈 繁榮地方經濟：社區型長照機構落地大安、文山，落實在地社福優先。","活絡商圈 繁榮地方經濟：推動綜合型社福設施，協助地方社福機構進駐萬隆東社福園區。","活絡商圈 繁榮地方經濟：持續推動身障特別門診、爭取特教資源，滿足弱勢需求。","活絡商圈 繁榮地方經濟：完善身障者家屬喘息服務，減輕照護負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"9ba45c32-802c-450e-b1b4-a6a943a8ead3","items":["完善交通 暢通行：爭取泰板捷運及西盛捷運支線","完善交通 暢通行：持續推動五股交流道改善","完善交通 暢通行：台65增設新莊匝道","完善交通 暢通行：大漢溪堤外便道串聯","完善交通 暢通行：增設多元停車空間","友善安居 享生活：加速都市更新、提供足量社會社宅","友善安居 享生活：打造活力運動空間","友善安居 享生活：河川整治打造親水環境","友善安居 享生活：營造寵物友善環境","友善安居 享生活：爭取第一公墓轉型新莊森林公園","友善安居 享生活：保留綠地護公園","青壯打拚 強後盾：加碼生育補助，放心生","青壯打拚 強後盾：廣設公托及公幼，安心養","青壯打拚 強後盾：增加高齡產婦產檢及凍卵、不孕補助","青壯打拚 強後盾：協助青年就業及中高齡職涯再發展","多元教育 顧未來：深耕英語學習及母語教育","多元教育 顧未來：發展創客及多元適性教育","多元教育 顧未來：推廣音樂藝術學習及補助","多元教育 顧未來：提升代課教師待遇","多元教育 顧未來：持續更新老舊校舍及設備","文化齊放 創經濟：推動休閒娛樂產業創經濟","文化齊放 創經濟：結合在地耆老及青年發展地方創生","文化齊放 創經濟：提升就業機會，增設產業專區","文化齊放 創經濟：產業拚升級，推動生技醫療專區","文化齊放 創經濟：活化新莊老街觀光，再現古都風華","文化齊放 創經濟：友善新住民，設立服務大平台","樂齡銀髮 展新生：65歲以上長者免費裝假牙","樂齡銀髮 展新生：推廣樂齡共融活動","樂齡銀髮 展新生：健全社區醫療及長照服務","樂齡銀髮 展新生：再創高齡價值"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9ba720a1-d102-47cd-9167-19c66e7c83c4","items":["爭取山城內大型公園設置共融式親子遊戲設施。","爭取活化山城內國有地館舍、閒置空間，設置青創基地及農夫市集。","爭取在山城內設置大型室內表演及運動兩用場域。","爭取以大埔客家文化特色發展觀光、休閒。","連結山城四區分四處，每年聯合舉辦「山城大甲溪野餐節」，有在地食材特色的野餐、主題性的音樂表演、親水…等體驗活動，吸引國內外遊客前來。","促請政府重視、輔導返鄉及留鄉青年創業及就業問題。","山城四區各結合熱心的老中青農組成立案之產業促進會，由青壯年主導，配合農會輔導，由農業局考評及補助經費。","爭取簡化「生產履歷」申請手續及降低費用，以普偏化，增加產值。","幫弱势、助安心，爭取補助偏鄉山城計程車裝置敬老卡或身障卡扣款系統，方便高齡長者或身障鄉親搭乘。","依原五分車鐵道沿大甲溪連結山城四區，修築自行車道及步道，分年分段推動。","爭取儘速復建中橫，恢復原有台8線省道規格，以利地方居民、農產運輸及遊客出入。","推動東豐快速道路，早日完成全線通車並連結新社，建構山城完整路網。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9bbd4b30-ace1-489e-97b8-70be606bb625","items":["全齡樂活‧永續嘉園：為建構永續發展、全齡樂活的宜居城市，將積極督促市府做好積、淹水點改善、區域排水治理、加速污水下水道家戶接管進程，並持續推動綠能發電、精進空氣污染各項管制、鼓勵商家響應環境友善運動，共同打造「永續嘉園」的城市願景。","鐵道經濟‧翻轉嘉義：嘉義市鐵路高架化即將在民國115年通車啟用，除車站主體工程及嘉義大車站、嘉北車站兩側開發外，鐵道沿線都市計畫變更、乙種工業區檢討、路廊開發利用、東、西區交通系統縫合、爭取高鐵聯外軌道系統，期盼藉由鐵道帶動嘉義翻轉與轉型新契機。","城市革新‧開發創新：面對城際競爭，嘉義市的發展不僅不能停下腳步，還要超越再超越。未來包括興建中的三座前瞻計畫停車場、總戶數達505戶的社會住宅，即將轉型為市政園區的北棟大樓、建國二村開發案還有積極向中央爭取的圖書館總館，都是建構城市競爭力重要基礎。","文資活化‧觀光發展：積極督促歷史建築「嘉義市舊市公所」與「北興舊菸葉廠」活化再利用案能如期如質竣工；國定古蹟「嘉義舊監」轉型「獄政博物館」第二期工程儘速推展，成就文化新絲路觀光軸帶。","健康促進‧樂活嘉義：市民引頸期盼全民運動館，即將進入工程階段，未來將督促全案能如期、如質竣工，提供市民朋友優質多元運動環境，並持續優化環市自行車道與微笑單車YouBike站點設置，搭配低底盤電動公車，營造低碳運輸特色，深度體驗城市魅力。","綠能永續‧循環經濟：為達成廢棄物循環利用及垃圾自主處理目標，將積極監督「嘉義市綠能永續循環園區」包含綠能發電廠、灰渣掩埋場、底渣再利用廠、飛灰穩定暫存場、資源回收細分類廠及廚餘再利用廠等各項工程能順利推展。","數位治理‧青年創育：響應中央「數位國家、創新經濟」發展主軸，將積極督促市府運用數位科技策略導入城市治理，作為推動創新市政的願景目標，同時整合各局處業務，推動成立專責青年事務科（局），全方位推動青年創育業務。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"9c5f3d20-af8a-4964-aa9d-07fb75edaaab","items":["堅持「有事來找我，沒事來泡茶」全天候為鄉親服務。","爭取國姓、埔里、仁愛地方建設，做鄉親和政府機關的最好橋樑。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"9c82bf70-385b-405b-b611-ff7566e7dc9c","items":["一本初衷，善盡民意代表職責，做用心聆聽、建言、監督、服務及建設的小市民代言人。","水岸花都繼續前進：透過轉運中心暨立體停車場啟用、葫蘆墩公園與中正公園持續改造，以及葫蘆墩圳掀蓋、軟埤仔溪再造、旱溪健康廊道持續治理，打造豐原宜居環境。","悠遊后里：以台灣好行串聯動物之家、環保公園、后里馬場、森林公園、麗寶樂園、中社花市及泰安車站舊山線，輔以完善YouBike串聯既有旅遊景點，形塑以旅遊發展為主軸的后里。","優化商區：以豐原火車站為核心，串聯葫蘆墩圳掀蓋一期、二期至中正路，涵蓋廟東復興商圈、慈濟宮、廟東夜市、太平洋百貨周邊、中正路、豐陽路及豐原轉運中心，透過空間與街廓設計形塑特色商店街區。","地方創生：修護再利用豐原郡附屬官舍、林場舊宿舍古蹟及六座歷史建築，活化為木漆藝文化產業基地；持續辦理水岸花都文青市集、葫蘆墩音樂會、葫蘆墩講座及文化節慶社區參與等活動。","運動休憩：以鐵路綠空運動廊道為軸、豐原大道自行車道為環，串聯北坑健行桂花林道、旱溪、后豐、潭雅神自行車道及東豐綠廊，建構完整運動休憩網絡；在軟埤仔溪水域常態辦理獨木舟、輕艇、龍舟、立槳等活動；推動豐原三豐路（文高一）運動園區、豐原國民暨兒童運動中心等場館興闢。","社教照護：支持營養午餐免費政策，繼續爭取增設公立托嬰中心、托兒所、幼兒園班級，以及設立公立日照托老中心及長照據點。","青年為本：支持18歲公民權；設立青年局，加速興建社會住宅與青年宅，推動青年創業孵化平台，強化青年就業服務；積極爭取滑板、街舞等極限活動空間及藝文專屬展演場域。","福利扶助：支持65歲以上長者健保補助，持續爭取與確保弱勢者、身心障礙者扶助補助，並設置身心障礙體育資源暨共融運動設施場館。","產業聚焦：推動豐原社皮豐富專案一期，導入運動醫療、運動健康及生技產業創研中心；二期作為預防醫療康健產業基地，打造完整健康園區。","衛生環保：督促豐原污水下水道第一期接管速度與第二期工程啟動進度。","數位治理：建議創新整併市府組織，成立數位治理局，推動數位化科學治理市政。","都市發展：持續推動並通盤檢討豐原、后里及豐潭雅神縫合等三個都市計畫，作為都市永續發展基礎。","豐后再升級：力促豐原、后里產業升級，協助導入AI數位建設，提高便民服務，設立產業轉型諮詢服務平台，創造人口回流並刺激民生經濟。","空間利用最大化：完整規劃公共交通運輸建設，盤點空間增建停車格，爭取利用閒置空間設置親子及寵物友善空間。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9cd304d0-2e2d-4ff4-a373-25ecdb122bc7","items":["支持18歲公民入憲。","支持政府政策持續提高基本工資，改善全民的生活品質。","協助各校發展特色教育，結合在地文化留住優質學生。","爭取中央經費，建設地方和改善學校教學設備。","全力推動建設青年住宅，讓年輕人買得起便宜的住宅。","維護居家服務被照顧者的權益，保障照服員的工作尊嚴。","關懷新住民議題，幫助新住民解決生活適應問題，並協助解決安排其子女教育相關問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9ce76dcb-2d7e-4d46-a25a-007abe560a38","items":["【推動四大優先】 一、市民主義優先 1.南勢角齊魯兵工廠爭取經費設置公園綠地及汽機車停車場。","爭取設置新住民文化館交流據點，協助新住民在台深耕發展，並鼓勵市民對多元文化的認識。","爭取推動南勢角東西向聯外道路。","爭取推動中和交流道增設匝道。","監督推動萬大線進度：要求市府嚴格把控施工進度，縮短交通黑暗期，完成開闢金城機廠20米道路， 打通莒光路與連城路，解決交通壅塞。","開闢國管院計畫道路，提升週遭交通品質，要求市府盡速取得道路用地，開通民有街至民安街順暢路廊，打破內外員山藩籬。","市區道路品質提升，推動人行道無障礙化，並整合地下管線，將電桿地下化，重現美麗天際線。","青年生活優先 1.體育人口、運動中心倍增，強化體育場館，設置極限運動場地。","為漳和國中羽球館爭取經費地重建體育館，並增設公托中心。","遠東科技園區一帶打造中和創新育成中心：培養在地青年創新力，鼓勵青年創業，補助培育新創人才。","婦女弱勢優先 1.擴大女性凍卵補助：因應晚婚、少子女化趨勢，不再限縮對象為不孕症婦女，降低女性規劃生育計畫之經濟負擔。","爭取補助女性進行AMH(卵子存量指標)、TSH(促甲狀腺素)2項檢查。","提高老人健保補助；爭取中和優先設立長者弱勢中央廚房送餐服務；爭取65歲長者假牙補助。","環境文化優先 1.整治中和大排水環境：嚴密監控中和大排汙染源頭，生態整治水域環境。改善全線車道、人行道設施，建立美麗水岸景觀。","推動瓦磘溝親水綠帶：落實活水引入、渠底清淤，整合沿岸綠地，打造河岸親水廊道，提供市民友善親水環境。","爭取都市綠地增加，促進市民健康，以提昇生活品質。","要求成立汙水地下水道建設基金，使用費應專款專用於完善汙水處理系統，督促市府在計畫期程內完成中和最後一期下水道工程。","完善鄰里環保志工制度：放寬各里環保志工人數，建立完善工作安全保障，提供適當福利鼓勵參與。","爭取舉辦中大型藝文音樂展演活動，發展在地文化軟實力，強化產業競爭力；推廣文史探險小旅行，增強家鄉認同。","深化中和文史教育，爭取經費維護修護修繕古蹟、文化建築；編纂刊物介紹中和歷史；推廣文史探險小旅行，增強家鄉認同。","監督主管機關查核監督工會幹部會務假落實執行，捍衛勞工權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9ced0fc3-e82e-45fa-a9f8-b0939014f2d1","items":["育兒福利：公幼免費，私幼補助一萬元；提高育兒抵稅額；父母可享彈性工時。","教育優化：廢除學習歷程紀錄；加強數位教育；重視技職教育；捍衛孩童食安。","居住正義：加重囤房稅；房租實價登陸；官民合作建社宅；提高低利貸款額度。","勞工權益：建設勞工住宅；增休假天數；所得未達56萬元課稅減半；強化勞檢。","警消權益：開放組工會；檢討加班費制度。增加預算汰換設備；增補警消人力。","醫療長照：老幼健保免費；提高長照住宿補助；開辦長照保險；心理諮商抵稅納健保。","動物保護：增設貓狗活動專區；普及寵物長照；推動《茶茶法案》與《飼主責任法》。","交通安全：改善道路設施與標線設計；擴大運用科技執法；推動《交通安全基本法》。","經濟活絡：個別輔導企業轉型；延長移工續聘年限解缺工；簽訂FTA減關稅擴大市場。","能源穩定：安全重啟核能；持續發展綠電；逐步減少燃煤，淨零碳排；擴建儲能電網。","建設台中：推動捷運藍線盡速動工；西南屯水岸綠地步行環帶；打通漢翔路至東大路解決塞車。推動中火減煤除役；溪西高壓電塔地下化；串聯水湳與中科，打造經貿科技大台中。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9cfa9733-c600-4d6f-aa3b-144e0c93e8d9","items":["打造苗栗縣成為台灣客家首都，傳承永續發展客家文化。","加速完成國道1號頭份第二交流道。","爭取國道4號設置簡易出口閘道，方便卓蘭鄉親通行及農產運輸。","爭取台72線銜接國道1號高架道路，便捷交通網路。","全額補助中、低收入戶醫療費用及罕見遺傳疾病病人維持生命所需之緊急醫療有關之費用。","推動80歲以上免巴氏量表即可申請移工看護。","縮短長照服務審核流程，加速立法通過長期照顧保險法。","推動中央統一補助生產及育兒津貼。","協助縣府推動設立教學醫院及派遣主治醫師以上團隊駐診及在地醫院升級，提升苗栗門診醫療品質。","推動由中央統一補助國中小學免費營養午餐，並責令行政院整合教育部國教署、衛福部食藥署、農業部及各地縣市政府，共同為營養午餐之衛生安全及品質把關。","爭取興建苗栗縣立圖書館總館及頭份城市圖書館。","推動修訂兒少四法，建立狼師惡師退場機制，反校園霸凌。","爭取升級完全中學，編制國立大學附屬中學。","加速推動苗栗新矽谷計畫，引進航太產業進駐，擴大上中下游供應鏈與高科技人才就業。","發展整備地方創生、城鄉特色產業、觀光旅遊環境及營造原民部落、客庄產業多元發展。","推動物流與倉儲平台機制，擴大海內外銷售通路，創造穩定獲利商機。","修訂農業保險機制，降低農損補助門檻。","積極爭取開放農事操作移工，解決農業勞動不足之缺工問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9cfc6fb4-03d6-49c5-a96d-e258fe308c7f","items":["縣政發展：推動阿里山、曾文水庫觀光產業，帶動地方繁榮。","社會福利：關心少子化問題及弱勢族群，爭取長者兒童婦女福利。","鄉里建設：爭取村里道路改善，產業道路整建鋪設，農產品運輸的便利。","興建水利：推動智慧農業促進產業升級，鼓勵年輕人回鄉發展，爭取地方防洪治水工程，維護人民財產安全。","人文教育：重視新住民民生、教育與福利，促進族群融合。","產業效益：結合人文鄉土特性，以旅遊觀光產業為目標，創造更大經濟效益。","銀髮長照：重視高齡化社會問題，爭取老人照護措施，爭取經費補助紓緩家庭負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9d9c7064-dd2f-46bf-b728-c15a5df3ceba","items":["建設金門,從議會改變開始 議員素質及全方位的思維,議會必需有新聲代來推動。","監督縣府各項地方建設,改善城鄉差距,促進東半島平衡。","加強醫療服務,落實培養在地醫療人員常駐金門。","規劃養老院,讓金門的老人福利更完善,減輕年輕人的壓力。","成立個人服務團隊,協助醫療危難救助,讓百姓有感。","深入基層,了解民意,協助照顧弱勢族群。","協助民眾申請土地及房屋使用執照問題,將過去的不便民流程簡化行政程序透明化。","金門要更進步,需要您神聖的一票,大家一起來改變金門,將金門建設成為一個和平試範區 的島嶼。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9dc65fa2-996c-42b8-a265-612f6d539574","items":["好生活：推動第五公墓遷葬，妥善規劃未來用地","好生活：推動南寮集會所落成，完善活動空間","好生活：持續爭取交通、綠地、休閒等民生建設","好安心：監督焚化爐設備維護與運作，達安全標準","好安心：推動雨水下水道工程，改善在地淹水問題","好安心：持續充實警消設備資源，保障生命財產安全","好教育：爭取增設公托資源，減輕幼兒照顧負擔","好教育：持續爭取教育資源，提升地方教育品質","好教育：推動社區終身教育，促進在地文教發展","好未來：監督新漁產直銷中心進度，推動地方發展","好未來：持續完善漁民作業空間，促進產業升級","好未來：持續推動新竹漁港、十七公里海岸線、頭前溪沿岸建設與發展"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9dcd69cb-4d7a-4390-9332-bbe93d094b8c","items":["教學環境，以提升學習效果。","持續推動大溪埔頂公園，設置圖書館及親子館 共托育中心及公(準)立幼兒園，以減輕市民經濟負擔。","持續爭取重要路口設 保市民安全。","積極推動十字路口顏色管理，改善路口避免意外事故發生，確 產安全。","持續推動埔頂營區設轉運站及捷運綠色延伸至大溪，紓解大溪假日 地方發展。","持續推動國軍桃園總醫院(804)成為重度急救醫院，提升醫療品 復興醫療資源不足問題。","全力爭取大溪區三元三街傘儲庫營區，做為大員樹 憩活動中心。","全力推動大溪、復興地區觀光產業，創造就業機會，帶動地方 推動大溪區月眉、康莊、百吉、水與綠及復興區台七桃花源等休閒農業，帶 造就業機會12.加速推動大溪行政園區都市計畫，擴大都市規模。","持續督促 整體營運，帶動地方觀光發展。","以大漢溪經濟藍海概念，從國際高度規劃 濱道路、生態溼地公園，及建構水、陸、空運動休閒在大漢溪。","爭取成立 ，全面推動地方發展。","督促優化大溪經國及慈湖銅像園區，形成新亮點。 3號大溪(大鶯豐德)第二交流道整建案。","督促市府儘速完成大漢溪產業專區 機會，帶動地方繁榮。","督促市府加速推展大溪豆干博物館。","全面推動大 市民活動中心之興建。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9e71241b-d4ae-41fa-b28c-7f917303e745","items":["串聯花蓮南區瑞穗、玉里、卓溪、富里等四鄉鎮及台東北區、東區等鄉鎮，組成花蓮南區觀光圈。","藉由鄉長任內規劃富里六十石山行車路線的經驗，玲蘭將持續向中央爭取經費，使玉里赤柯山及南區各農業園區觀光動線更便利順暢。","將瑞穗文旦柚、茶葉、酪農等農業，結合泛舟等觀光產業，共創雙贏。","目前花蓮縣的農業面臨了許多困境，包括人工匱乏、工資上漲、肥料漲價，但所有的農產品依然無法提升價格，讓廣大的農民收入減少，玲蘭會帶著農民朋友的期望努力，爭取更多農業補助。","繼續爭取公益團體及企業協助各級學校，並加強推動禮義廉恥、尊親孝道及社會的倫理道德觀念。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"9e870de0-d2b2-43a2-a5d4-179ad3ceb611","items":["落實服務以民為先,積極反映人民心聲以維護人民權益。","致力提升學童營養午餐質與量,以維護學童身心健康。","廣設親子活動空間,提升優良育兒品質。","活化閒置空間、增進休閒運動場所,並以提升銀髮族長照機能。","有效監督政府施政,以提升行政效率品質。","關懷弱勢、維護農民與勞工權益。","推動綠色環保、打造鄉鎮樂活宜居環境。","落實農業政策,提升農業經濟效益,以增進農民收益。","促成國道六號延伸至花蓮,提升觀光產業產值。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9e9ac638-ed97-4c9f-a637-db9bd3072e66","items":["活化開放國有地，爭取興建停車場及公益設施。","增加共融式特色遊具公園，拓展全齡樂活空間。","三重醫院擴建升級，提升醫療品質與量能。","市立三重分館改建為多功能旗艦型圖書館。","三重好行 友善交通：督促捷運北環線如期完工，增設機場捷運A2a站，大眾運輸更便利。","三重好行 友善交通：推動符合人本交通及永續都市的「交通安全基本法」還路於民，友善婦幼嬰兒及身障弱勢者。","三重好行 友善交通：維護學童權益，優先改善校園周邊安全通行路網。 三重保障 福利安居","三重好行 友善交通：擴大公共化及準公共化托育量能，減輕家長托育費用。","三重好行 友善交通：高中職學費全免，減輕高教學費負擔，促進教育平權。","三重好行 友善交通：興建社會住宅，增加租金補貼及提高青年安心成家貸款，落實居住正義。","三重好行 友善交通：修改動保法，提高虐殺動物者的刑期及罰金，提升救援動物醫療水準。 三重防衛 安全繁榮","三重好行 友善交通：針對新型態詐騙犯罪，研擬修法加重刑度；確立虛擬貨幣法律定位，訂定相關規範。","三重好行 友善交通：落實法規調適，支持中小微型企業的發展，加速數位轉型，鼓勵地方創生。","三重好行 友善交通：強化經濟韌性及確保供應鏈安全，與民主國家建立強健夥伴關係，確保國家安全和平。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9eaa6690-39c1-487f-9b0b-d8c9f43564b0","items":["府招商設廠 . 增加本市青年就業機會。","隆市山坡地都市更新 . 改善居住環境。","電公司電桿地下化 . 以提升市容景觀。","闢大慶大城聯外道路以解該地區對外交通之困。","審查市府預算，督促市府均衡發展區域建設。","爭取中山區快捷公車班次增加及多元化路線，讓通勤民眾更加便捷。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"9efba907-a4f9-4d23-bef8-538283fd9b88","items":["積極爭取經費，充足澎湖醫療在地化設備儀器。","全力爭取澎湖休憩運動園區興建，塑造廣泛多功能休憩運動場域。","反映爭取澎防部、後備指揮部土地釋出，提供開發利用。","積極爭取經費，落實長照軟硬體設施興建及服務需求。","全力推動全民運動館興建，建構充實運動環境與設施。","督促縣府研議照護原住民、殘障、老弱、婦幼、榮民、外配等族群福利措施。","督促落實澎湖縣國土整體規劃工作，維護鄉親權益。","要求落實海洋復育措施，全力活化海洋漁業資源。","爭取公共設施用地與保安林地解編，促進土地合理利用，保障民眾權益。","積極推動設置污水回收處理中心，營造優質生活環境，潔淨地區海洋生態。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9f0a3be5-3cdc-4cdc-815f-2364e74af67f","items":["爭取建設安南區轄內兒童特色公園","增設商60消防分隊","爭取安南區公所原地重建，活化安南新中心","比照五都爭取鄰長發放工作津貼","增加新生兒津貼及育兒補助","全力爭取安南捷運線盡速開闢","打造區域公車環狀線，增加公共運輸便民使用","監督安南區汙水管線設置進度","監督安南區淹水問題","督促市府重視垃圾清運環保議題","爭取農漁民福利政策，增加在地農漁民行銷通路","爭取安南親子館設施","爭取台江文化中心藝文活動，打造安南文創環境"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9f63b565-08bd-44fd-91cd-8e30322468c8","items":["堅守預算把關支出：監督公共建設品質，確實預算執行程度。","週週免費法律諮詢：維護民眾法律權益，鄉親法治觀念強化。","健全體育藝文發展：基層體育推動支援，音樂藝術氛圍扎根。","持續動物保護關注：法令推動、陋規修正，扎根生命教育基礎。","拉近城鄉教育差距：推動相關教育政策，翻轉屏東孩童受教。","保障弱勢團體福祉：婦孺老幼、外籍配偶，竭力爭取福利保障。","重視空汙環保問題：爭取還民呼吸權益，正視民眾居住品質。","鼓勵青年返鄉就業：地方鄉鎮特色規劃，區域商圈繁榮經濟。","長照發展老化趨勢：銀髮照護比例加重，樂活長輩、輕鬆晚輩。","協助農業產銷機制：提升農民農事收入，推廣精緻農業路線。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9f772353-059a-4a17-95f6-56e811de046b","items":["「為我們的城市 為我們的未來 跨越期待 看見未來」 一、打造以新北市為核心千萬人口級的一流國際城市。","傾聽基層聲音，反應基層民意，監督市政，建設光榮希望的新北市。","選票補助款全數捐贈國中小教育 四、活得自在，活得有尊嚴。增設老人、幼兒活動設施「一里一銀髮俱樂部」、「一里一托幼」，推動「幼銀共榮」融合銀髮俱樂部與公托設施，推動「青銀共居」，打造「長照社區化」之社區長照據點。","提高獎勵生育、托育補助及幼兒教育品質，積極鼓勵青年攜幼移居，增建青年住宅。","利用公有土地獎勵民間投資或建案回饋加速設置幼兒、托老中心、停車場，解決民眾民生問題；增設圖書館，推廣學童閱讀計畫。","推動十五年國民義務教育，強化技職教育分流，獎勵新北市產業與技職教育之共榮。","打通瓶頸道路，降低公安危機；加速老舊社區更新並加速徵收開闢公園，提升居住環境安全與品質。","督促市府全面盤點現有巷弄內汽、機車臨停、禁停與消防公安間的平衡問題，整理及新設自行車道提供安全舒適的親民環境，增益民眾福祉。","爭取鄰里寵物公園專區，讓毛小孩及飼主有良好的休憩環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"9fb8f231-e02c-424a-976a-47530dbc305c","items":["普及兒童共融式公園，增進兒童遊戲安全，協助兒童健全發育。增設公園遮陰設施並加強設施養護，營造優質的親子同樂園地。","為解決中高齡婦女重返職場續航困境，在社區籌備設立婦女二度創業輔導教學中心、廣聘優良業師，傳授技能，並配合婦女低利貸款，輔導創業，迎接人生第二春。 ‧為青年發聲","擴大國中生公費施打HPV疫苗，包括男性與女性，不但可預防女性子宮頸癌，還可以同時預防多種生殖系統癌症，保護男生同時保護女生。","力求彰化交流道特定區解編，引進高科技、高產值產業鏈及物流專區，提供青年就業機會，提高彰化青年薪資水平，鼓勵青年返鄉定居。 ‧照顧長者 為體恤長者並鼓勵長者外出活動，計畫擴增長青幸福卡服務項目：長青幸福卡服務項目現有僅客運，未來積極爭取擴充：客運、計程車、醫療與休閒運動。 ‧人才留住由教育開始","配合國家2030雙語政策，爭取編列預算協助中小學外語師資資源到位，外語教育從小學紮根，每個孩童都能得到完整扎實的外語教育。","編列預算補助偏鄉學生（中小學）到選區內學校就讀交通費用，提高選區內學校就讀率。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a03f5791-5085-4181-bd52-f181a6e4634c","items":["認真監督縣政府各局、處依法行政，提高行政效率、加強便民措施","繼續爭取原鄉的基礎建設、農路的興建與改善，保障人民的生命財產安全","繼續爭取原鄉部落自來水的建置，改善簡易自來水的設施","繼續爭取土地重劃、重測經費，以減少土地糾紛","爭取經費幫農民興建蓄水灌溉設施，協助農民推銷農產品","爭取經費改善各文健站周邊環境","推動原鄉國中、小學品格、文化多元教育"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a0400f44-e891-4102-81ed-86442edabf35","items":["【新北大翻新】 1.爭取新北設置兒童醫院，完善早期療育、強化兒童重難病症專責，友善兒童醫療。","支持公辦都更，簡化程序，加速推動老舊建物更新，保障居住安全。","推動新北發展循環經濟，落實資源永續，守護家園。","改建閒置空間，成立「長輩日照中心」、「銀髮公寓」，提升長輩照護與生活品質。 【塞車問題我來解】 1.加速五股、林口交流道改善工程、105市道拓寬案及改善103市道規劃。","降低機捷票價，強化聯外公車班次及路線，提升搭乘大眾運輸工具意願。","規劃林口區內環狀輕軌，銜接機捷或五泰輕軌，緩解交通量能。","改善高速公路便道(原泰山收費站)動線，紓緩五股、林口交流道車流。","全面檢討改善道路交通號誌連貫性，維持穩定車流。","規劃增加五泰林聯外道路，提升交通便利性。","增設停車空間，減少違停狀況以改善交通動線。 【青年成家我挺您】 1.爭取增設幼幼班，幫助家長解決托幼問題。","爭取更多準公共化幼兒園，使更多家庭受惠、降低家長負擔。","鼓勵青年投入文化及科技新創產業，打造由政府主導之青創募資平台。","支持青年結婚入籍新北，每戶補助10萬元政策。 【產業升級我推動】 1.推動中小企業轉型、升級，提升產業競爭力，增加工作機會。","持續督促市府積極招商進駐泰山，彌補塭仔圳重劃流失之工作機會。","打造產業整合平台，輔導上下游廠商互利互助，建立群聚產業鏈。","督促林口工一工業區有效規劃，打造高科技產業聚落。 【打造美好五泰林】 1.還我乾淨天空，清除廢棄纜線，加速電纜地下化。","打造觀光新景點，生態工法整治貴子坑溪、大窠溪。","加速建置污水下水道，同步提升排水系統及抽水站功能。","改善老舊校舍；加強校園安全，防止毒品入侵校園。","改善道路規劃，增設人行道與綠地休閒空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a05abc8d-5a33-402f-b3d3-1347a1f34b6d","items":["社會福利：婦幼：建構完整社會安全網、橫向立即通報機制，從里鄰長、社區，保護婦幼免於恐懼、防家暴、防性侵，從幼兒園、國小紮根。","社會福利：老人：社區銀髮多元照護計畫，招募退休志工至各社區參與陪伴與活動，讓老人健康照護落實到各角落。","社會福利：弱勢：監督政府興建社會住宅，提供弱勢族群安穩住所，強化中低收入戶以外之急難救助網、弱勢供餐、臨時住所服務。","社會福利：教育 爭取國中小程式教育數位載具補助，鄉土教材在地化，法治教育列入國中小課程，加強校園安全，打造共融特色公園。","社會福利：休閒文化 地方文史導覽、推廣，強化各鄉鎮特色景點結合美食、農特產推廣，定期舉辦地方特色活動，推動產業觀光聚落。","社會福利：推動無喪葬費善終計畫","社會福利：持續舉辦彰化縣低收、獨老、邊緣戶、街友等寒冬送暖千人饗宴","社會福利：持續舉辦低收學童我愛寶貝夏令營","社會福利：致力推動各社區志工隊、慈善會、校園等巡迴演講"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a06d4ef8-1203-4514-83a0-8f63a7d82e40","items":["(一) 支持抗中保台主流民意，堅持台灣民主的價值。","(二) 鼓勵婦女參與社會活動的功能性，尊重兩性平權的精神。","(三) 配合政府施政方針，爭取村里建設，關懷弱勢團體，維護地方治安，提升生活品質。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"a0ba8580-916d-43bc-9b36-4daee4c6164c","items":["~雄來了~六大政見 一、【教育發展政策】 1.推動族語教育深耕計畫-原住民各類師資培育(文化考究、說故事、演說、線上教學培訓課程、歌謠吟唱、表演藝術等多元面向)。","為原民教育相關人員爭取提高鐘點費、交通費及暑期薪資保障。","成立青年事務所，提高原民青年公共事務參與，並匯集青年創意資源。","因應人口老化，社會結構的改變，社工、護理相關科系、老人照護系人力短缺，輔導原民子弟進入該領域，並提供諮詢與協助。","【體育發展政策】 爭取設立國家級運動訓練園區，強化各級運動選手培訓體系，建構安全友善運動環境，培育原住民運動永續的發展及品格教育。","【傳統藝術發展，越在地越國際】 1.爭取每年辦理「國際傳統藝術節」，讓新北16族群文化被國際看見。","為新北市原民演藝團體，推動表演藝術與傳統技藝成立增能培力工作坊。","【經濟發展政策】 整合原住民專業技能，推動「創業結盟」方案。","【保護海洋生態環境，為地球奉獻一己之力】 海洋與漁民、市民及原民關係密不可分，更是健康休閒的好去處，目前新北市海洋生態嚴重浩劫、垃圾汚染嚴重，進行環境保護及海洋復育相關計畫，為地球盡一份力量。","【照顧原民基本生活需求】 1.爭取新北市轄區文健站，提撥經費配置【接送車】。","爭取原住民社會住宅並降低租金。","爭取新北市原住民文化園區用地。","爭取各區增設原住民多功能活動中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a0beed75-c895-44b3-a5b9-141cc91ad35d","items":["監督縣政，為民喉舌","重視教育，培育人才","振興經濟，永續觀光","關懷弱勢，服務鄉親"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"a0d81e50-375f-4c03-84df-bc0a051f6c80","items":["嚴格監督：縣政府各項政策透明。","嚴格監督：給人民有知的權利。","嚴格監督：服務縣民。","嚴格監督：爭取福利。","嚴格監督：為弱勢代言。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a16f9e98-89c9-4476-bc0c-175b6992883e","items":["維護攤商勞工之權利，確保制度","義務法律諮詢","新住民就業輔導","北區婦女防暴聯盟","公立幼稚園的增設，增加量能","入籍兩年，年滿65歲免繳健保費","加強觀光夜市合作並舉辦美食嘉年華活動"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"a1968ccf-56e3-4725-b21e-2117839273fb","items":["我參選的區域是花蓮縣吉安鄉第三選區，包括吉安、壽豐、鳳林、萬榮、光復、豐濱六鄉鎮，本著「心繫鄉里、守護鄉親、繁榮鄉里、力拚經濟」的態度，因此我主張：六帶一路。「六帶」就是自然生態保育帶、東海岸觀光帶、都市發展中心帶、產業居住帶、教育科技帶、觀光休閒農業帶；「一路」意指蘇花高速公路銜接花東高速公路。如此花蓮才能全方位發展開來，讓花蓮值得更好。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"a22e0ddd-57cb-4bea-8ce5-742ca1af4394","items":["監督縣府兌現競選承諾、拒絕欺騙。","關懷弱勢生活、老人安養、婦幼安全，讓年輕人安心就業。","支持警消裝備提升，重視地方巡守需求，強化治安及救護。","監督食品衛生，提升醫療照護，支持學童營養午餐免費政策落實。","監督縣府預算編列與執行，避免浪費納稅人血汗錢，債留子孫。","監督政府，重視地方產業協助並結合產業、觀光、行銷，提供所有資源。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a26de2a9-c80c-4bea-811f-bbedf3dab768","items":["添運動：督促北屯國民暨兒童運動中心興建進度，並活化機關閒置空間，規劃為老中少室內外活動場所，舉辦各類運動活動。","添公園：改善公園運動設施，增設能訓練兒童感官、肢體動作發展之共融遊憩設施。","添托育：推動社會住宅持續興建及公托社區化，提升交通、醫療、養托育、租金補助，減輕家長負擔。","添平權：推動無障礙就醫環境、充實特教師資及學習資源、改善無障礙交通設施、加強身障職業培訓及企業職務再設計之觀念。","添學校：督促松強國小及廍子國中興建進度，並爭取學校不足之地區設校，保障學童就近就學權益。","添公車：爭取新增溪東地區公車路線，增加溪東居民往返市中心的選擇、提升交通機能、帶動周邊發展。","添捷運：爭取綠線延伸到大坑經補庫，打造大坑意象捷運站宣傳周邊景點，促進大坑地區觀光發展。","添UBIKE：擴大UBIKE及E電輔車租用站設置，並規劃自行車道，推廣無碳交通。","添停車：爭取敦化公園等公共設施開闢地下停車場及廣設路外停車場，以解決車位不足需求。","添毛孩：擴大增設寵物公園專區、寵物專用設施，讓毛小孩能盡情活動。","添綠肺：保護綠地老樹、增加各公園植樹面積，讓城市內保有天然綠肺，並舉辦環保活動，提倡減塑、減碳社會。","添文資：爭取編列金源吉宅第、詔安堂等古蹟修復預算，保護傳統文化價值。","添裝備：監督市府補足警消醫護人力與設備，保護警消醫護的工作環境及人身安全。","添道路：開闢東光路計畫道路、同榮段社宅東側12M及8M、25M計畫道路、后庄路789巷計畫道路、庄美街銜接后庄北路、南京東路3段銜接東山路1段開闢工程及梅川南街拓寬、北屯路291巷15M打通、松安街打通工程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a2c437b9-d432-4c80-a359-b9e7a5b249a4","items":["監督縣政，舉發貪腐，為民申冤，維護公義。","建請縣府興建芳苑工業區工區路銜接台76線以西延伸工程道路，促進地方繁榮與交通便利性。","繼續推動二林四鄉鎮農特產推廣行銷改善農民生計。","長期關懷弱勢團體，幫助其就業及補助等各項福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a2fa74d7-4170-4ae0-ab07-d405c367fb0e","items":["監督市政","監督預算"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a346889f-6674-4c15-a51e-5162f93e15c7","items":["國道2號延接61高架。","國1甲興建接到竹圍漁港。","大竹交流道高架跨越中正東路進入青埔區。","大園交流道中正東路拓寬.及電線電纜地下化。","大園都市計劃盡速開發。","爭取菓林國中設校。","爭取航空城學校興建。","爭取各里有集會所，關懹聚點。","爭取興建國民運動中心。","爭取航空城徵收戶重建經費補助。","沙崙里、北港里垃圾場出清，興建地質公園。","許厝港濕地、低碳轉運遊客中心。","爭取以法制調整徵收地上物，物價指數評點。","爭取沿海岸造林計劃。","竹圍漁港建置觀光市集、親子遊戲公園。","爭取大型醫療學術教育單位設置大園區。","爭取航空城，A15站延伸南港客運園區至草漯重劃區輕軌計劃。","爭取潮音國小遷校計劃盡速辦理。","爭取增設老人日照中心，培訓志工服務長輩。","增設公托照顧幼兒。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"a370fdd7-8d8a-4cc0-8c35-614f50c225d2","items":["全心全力 守護部落 專業監督 行政細節","生活在安全的環境：重新檢視各部落生活條件，調查潛在危機區包括道路建設、擋土設施、溪流整治、環境汙染，事先勘查、統計，編列預算提早施作改善工程，預防災害發生，達到預防勝於治療的效果，保障部落基本生活品質。有地就要有路，爭取經費，鋪設產業道路，讓族人能充分發揮土地利用價值。","定居在自己的土地：全力協助取得原住民保留地所有權狀，不要再讓族人空等待。監督國土計畫實施進度與執行細節，確保部落建物順利合法化，積極運用國土計畫工具，協助部落發展並新增部落住宅，讓返鄉定居心願成真。","產業在文化中發展：不讓青年孤單奮戰，積極統合原住民部落青年創業資源，督促政府有效搭建原住民特色產業平台，提供六級化產業類別合作支援，提高部落青年經濟收益。","文化在日常中傳承：督促政府盡速完成一部落一聚會所，同時串聯各項如文健站等軟體計劃，促使聚會所實質上成為部落文化中心，時時傳承部落文化。建立部落文化資料庫平台，提供部落青年田調口訪資源，累積耆老智慧，透過科技媒介克服空間障礙，成為新的傳承文化管道。爭取資源，擴大各部落各類型文化傳承工作。","教育在時代中精進：擴大推動民族教育，讓wawa在文化脈絡中學習世界的知識，提高原住民學生教育獎學金，精進適性教育，鼓勵投入軍警、輔導國考擔任公教人員，穩定部落青年工作職業，提高部落在社會發聲的力量。 不分黨派 全心問政 不分部落 全面服務"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a3a87927-2b8f-4f9f-abef-72c99b829481","items":["監督縣政、爭取建設。","關懷弱勢族群、爭取老人福利。","傾聽民意、反映及協助民生需求。","協助社區營造、關心新住民。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a400fa49-28bc-4e75-85a4-860e9d722582","items":["放寬申請社福移工限制，取消巴氏量表，減輕長照家庭壓力","推動核二、核三延役，以核減煤，還給台灣人乾淨空氣","推動防災都更，提高40年以上老屋容積獎勵，增加都更誘因，解決都會老舊住宅防災問題","開放大陸觀光客團客來台，振興台北市觀光產業","推動松山機場新國門計畫，打造小型航空城","追蹤政府宣傳標案，反制特定媒體壟斷政府文宣標案","重懲詐騙集團，對電信公司、金融機構課以反詐責任","強化校園反毒教育，打擊校園毒品，保障下一代健康","修法限制特別預算常態化，重建財政紀律，拒絕債留子孫"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a42f55aa-8328-4e35-acee-8d934d52df5e","items":["持續監督推動重大公共建設，包括鐵路地下化、綠線延伸中壢站、中豐北路交流道、污水下水道、全市區危老都更獎勵、瓶頸道路、路平、巷弄纜線清整專案。","發動公權力更大支援社區，有效管控公安風險（垃圾堆放、車輛擋道）。","推動寵物公園、寵物長照政策及寵物認證餐廳，多元寵物陪伴設施空間。","打造美食經濟，要求市府協助桃園餐廳入選米其林必比登等美食推薦。","監督校舍建築物安全，充實學校校安與防疫人力，建構安全校園。","敬老愛心點數擴大至台鐵、體健設施與景點適用，樂活銀髮。","推動優化校園遠距教學的軟硬體資源，因應疫情相關發展。","普及商圈的行動支付，營造社區購物消費魅力。","建物裝修行為納入損鄰爭議調解制度，減少爭議。","推動適性的公園設置、特色遊戲場和友善步行環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a466f45a-529b-4a16-ba6a-ed28d2724e26","items":["認真審查縣政府預、決算，及強力監察縣政府財產之經營管理及處分，並審慎審查縣政府所屬事業機構之組織章程。","增加社會預算比例，保障婦幼安全，健全幼兒托育環境、檢討教育品質，讓父母安心工作、孩子快樂成長；推動兩性平權，推廣家暴防治觀念、落實老人、身心障礙、特殊境遇家庭、婦幼、勞工等弱勢團體照顧，並加強職訓與生活補助。","打造員林、永靖、大村生活圈，加速周遭社區更新，全面改善周圍交通及排水系統工程以提升生活機能。","鼓勵全民終身學習，加強獎勵社區結合各項資源、增設社區關懷據點，鼓勵社區民眾參與志工服務。","定期舉辦免費法律諮詢及社區巡迴服務，堅持照顧弱勢家庭。","持續推動「警消賠償訴訟基金」作為警消後盾，以使警消執勤無後顧之憂。","爭取大村鄉門牌整編，以利消防救火單位及用路人便於尋址。","持續追蹤員林南區派出所興建進度，以確保轄區治安並妥適調配警力執勤範圍。","重視教育督促縣府寬列經費，爭取縣內國小課桌椅改為調整式課桌椅，提升優質學習環境。","督促縣府重視農業升級，積極行銷彰化地方農特產品，鼓勵年輕人投入休閒農業發展，並協助農民天然災害申請補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a48a083b-3d6a-484c-b75a-9f918ffb959d","items":["議會需要不畏懼權勢的-吳瑞芳 我與夫婿前議會大砲林民政議員,共同服務守則四條: 第一條:鄉親永遠是頭家。 第二條:乾淨參選,絕不買票、不請客、不送禮、無樁腳,服務只靠 兩隻腳,紮實服務為鄉親。 第三條:依舊秉持一人當選兩人服務,我與我的夫婿始終貫徹「杜絕 買票風氣」。 第四條:傾聽鄉親需求,議會理性問政。","加強關懷鄉鎮單親家暴家庭者、貧困身心障礙、婦幼老人等弱勢族群。","爭取增設立體停車場,以紓解假日鹿谷塞車之苦。","持續推動鹿谷、竹山茶鄉農業品牌,打造年輕人文創商業聚落平台。","建議南投縣政府提高生育補助津貼與增加營養金。","致力活化公有土地,增設長照安養機構中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a499dc38-217b-490b-b4b1-d29c0b55f2e2","items":["交通升級：力促交通平權，以人為本全面檢討道路設計，推行車速分流；檢討停車空間，廣設公共車位；監督捷運、鐵路地下化如期完工。","經濟就業：整合市府資源協助青年就業、擴大補助缺工產業、推動青創品牌曝光；舉辦活動活化商圈。","都市更新：打造資訊溝通平台，透明化加速危老建物重建。","社會福利：增加公托班數與人數，補助延長收托、設置定點臨托，增設婦幼場館；補助準公共化業者，提升社工待遇，增設長青國民運動中心。","兒少安全：普及親職教育、提升兒童人權、提供離婚夫妻子女公開公正探視場所；因應數位性暴力猖獗，警政系統成立專責單位及犯罪者資料庫；校園成立親師互助網、通報事故，普及大眾對數位性暴力的認知。","教育建設：友善雙語資訊教育，建置安心優質教育環境及設備。","特色公園：加速完成旗艦型遊樂場，佈建各地特色公園。","寵物友善：整合公私資源，建置多元寵物醫院地圖，推動高齡犬貓輔具服務。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"a521a29c-3ca0-487c-a6eb-e60992eff590","items":["地方建設：持續爭取社子島居民福利及建設： 「優惠拆遷補償條件」、「配售資格放寬」、「都市計畫完備」、「開發衝擊減緩」、「引進老人常照及醫療資源」。 2,汰換老舊公園設施，催生共融式遊具，活化台北景觀，增建更多特色公園，充分使用未開關之公共設施預定地。","地方建設：打造便捷公共交通，監督捷運環狀線設置，延伸地方公車路線，周延各地Ubike熱點。","地方建設：推動關渡平原開發或多元化使用。","地方建設：推動士北在地山水觀光，淡水河右岸與基隆河兩岸河濱公園推廣。","地方建設：推動雙河流域活動，優化北投溫泉產業，陽明山觀光產業。","地方建設：强化地區醫療體系，盤點基層醫療系統，針對疫情期間應變機制通盤檢討，讓醫院與診所雙向聯絡更加便捷。","地方建設：推行在地文化國際化，提升台北特有文化能見度，積極保存士林北投古蹟及百年宫廟，永續傳承。","社福：統整地區性醫療資源，推動長者照護社區化，保障長者權益。爭取士林北投樂齡學堂、長青學苑，讓長者共同運動、養生、學習。","社福：協助弱勢家庭與高風險家庭，簡化通報流程，追蹤後續安全照顧，並爭取放寬認定標準與提高社福補助。","社福：整合各校閒置教室，並爭取設立社區公托幼稚園、公立托兒所數，降低家長負擔。","社福：爭取提高社會住宅量能，爭取士林北投優先增設社會住宅與青年住宅，保障弱勢與青年居住權益，降低雙北生活負擔。","教育：強化國中小外語、族語師資硬體，推廣多元教育，多元語言與技藝學習。","教育：應用食農教育與認證有機食材的學童營養午餐與長者共餐，協助都市農業發展，保障學童與長者自產自銷，食農安全。 【警政】 強化社會安全網，持續監督夜歸犯罪熱點，打造婦孺安全路線，持續更新警政通報系統，保障平安回家的路。 【動保】 愛護動物，為浪浪、毛小孩權益發聲，檢討動物領養機制，爭取動保相關措施，打造動物友善城市。 【體育】 爭取士林北投體育基礎設施完備，各級學校體育班軟硬體資源挹注，透過結合士北親水資源，推廣親子水域活動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a5497a9a-b560-436d-b7f3-bada38074ab4","items":["市政歷練和教育博士，最專業認真的民意代表","市政府歷練近8年，目前擔任議員，具有教育專業，勇敢為民發聲、爭取建設！","加速推動都市更新","浮洲區盡快通過都市計畫，興建污水下水道。","發揮教育專業，改善教育政策","檢討教育制度，讓孩子快樂學習，支持多元社團活動。","讓長輩得到更好的照顧：元之博士論文研究活躍老化，會給長輩最高的尊重，改良長照制度，提升長者休閒設施，增設優質養老院，申請看護免巴氏量表。","讓長輩得到更好的照顧：翻轉國會，不做黨意立委","讓長輩得到更好的照顧：立委職責是監督政府，不管哪一黨執政，都會勇敢為民發聲。","讓長輩得到更好的照顧：修法杜絕詐騙，守護人民辛苦血汗錢。","讓長輩得到更好的照顧：強健電網，不要動不動停電；推動電線桿下地。","讓長輩得到更好的照顧：檢討交通記點制度，推動友善人本交通，取消區間測速。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"a56311fa-f86b-4428-87ac-1b9aace7d120","items":["半導體+招商國際銀行 高薪職缺翻轉產業結構","閒置空間變平價「青年宿舍」協助少年A存錢","國小在校專業「課後輔導」減輕雙薪家庭安親費","提高綠地企業認養率 節省市府開支 永續維護","「誰挖馬路誰負責」廢除路修費 馬路才能真正平 新北區","崇德殯儀館分段整建 立體化 現代化 不可怕!","北區老屋數量多 應納入「裝修補助」區域","北區出租比例高 防火預防要修訂 保障區域安全"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a5bd97e6-955f-499a-8cea-a3f9eaeaebca","items":["近幾年回嘉創業青年不少，政府如何在合理適當的政策下，輔導以及給予資源。","社會福利：在現有中央以及地方政府的政策下，設計更多適用於在地的配套，在兒少、長照、弱勢的部份可以受到更好的照顧。","社會福利：每年在嘉義市舉辦許多全國賽事，如何將各單項運動統整打造一個運動季，也可以帶來許多經濟效益。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a5be218a-23fd-4bd3-bac9-024adbbcc5d4","items":["民政局：提升生育獎勵金、修繕區民活動中心、續辦兩岸雙城論壇擴大兩岸交流。","財政局：推動市府加速債務還本、督促中央提高多户房屋持有成本，並針對單一自住房屋及公益出租人訂定房屋稅差異化區間稅率，實現居住正義","教育局：擴增公共化幼兒園、增加私立幼稚園補助及育兒津貼，減輕家長育兒負擔、提升雙語老師待遇推動雙語教育、完善校園網路基建及電力設施。","體育局：加強運動員傷害防護計畫、提供運動選手運動傷害醫療補助、爭取選手訓練補助與就業輔導相關權益、優化運動場館線上租借系統。","社會局：增加老人日照中心、增加公共托育所、增加托育補助、優化身心障礙者活動空間、擴大敬老悠遊卡使用範圍、提升長照交通接送服務量能、盡速完成北投浩然敬老院及士林陽明教養院中繼安置。","工務局：加強士林北投防洪排水建設、箱涵疏浚、側溝更新；更新維修士林北投公園體健設施、增設防曬及座椅休憩區；增加士林北投污水下水道管網系統。","交通局：士林北投停車熱區，於公園及學校興建地下停車場；加強 YOUBIKE公車捷運轉乘優惠、增加電動公車及停車場充電設施、增加智慧號誌及智慧停車、保障機車族權益。","產發局：加快士林北投科技園區廠商進駐，給予福利嘉惠士北居民、疫情期間持續減租延租免租，放寬疫情受困中小企業融資補助資格；要求商業處振興士林夜市及天母商圈、鼓勵中小企業數位轉型激勵機制；要求市場處北投市場更新完工、要求動保處推動友善動物城市、落實動保法執法效能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a5ecd655-c756-4b71-89a4-c4e2b704f40e","items":["確保各級校園軟、硬體設施完善，落實教育建設預算優先補助校園。","鼓勵青年回鄉就業輔導，增加在地創業補助，設立青年局保障青年權益。","成立新住民科，協助新住民融入在地風俗習慣及生活。","堅持落實老人長照工作，督促社區老人照護及老人日托體系完成。","協助婦女就業及建置婦幼安全網，保護受虐兒及遭家暴婦女。","堅持保護家園有效遏止空污，強力監督中火發電各項違失。","敦促水湳經貿園區各項建設開發進度，儘速完成以造福鄉里。","重視治安維護，增設監視系統，加強警民連線，聯防社區安全。","改善老舊公園設施，推動共融式遊樂場、讓「玩」變成大家的權利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"a5fe79e3-f2de-4094-b4de-ce5f4ddd51ab","items":["北區肉品市場原址推動規劃：主題公園、社會住宅、商場。","台中市交通號誌全面盤查，創造友善行的空間。","增加第三胎生育津貼並保障優先入學(公托公幼)。","推動特色主題公園之建置。","調降社會住宅租金，並提高租屋族租金補助。","爭取捷運通勤族月票優惠。","改善公車重疊路線，有效減少公車搭乘時間。","亞健康長輩陪伴照護資源爭取及完善長青學苑規劃。","民政局增設專屬新住民業務科。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a635e5ac-aa8e-4292-8635-4cfe780e5d72","items":["捍衛年輕人，促設青年局，提高預算協助青年就業、創業。","爭取65歲以上長者健保費全額補助。","重陽敬老金應比照其它五都提高至一千五百元，並依年齡累進增加。","提高0~6歲國家養政策，爭取普設公托幼托，提高生育及托育補助。","國中小營養午餐免費，減少流浪教師數額，提供代理教師完整聘期，落實特教生就學權益， 降低師生比保障師資。","優化觀光文化等地方特色產業，增加就業機會。","督促穩定民生物房價，保障消費者權益，減輕業者營運負擔。","改善假日鬧區交通，並增進公共運輸環境及品質。","強化治安補足警力，保障市民安全。","整治疏通排水系統，改善地方易積淹水地區。","提升弱勢族群保障，督促政府提供保險、補助等資源。","推動校園音樂教育多元化，讓孩童接觸學習各種音樂文化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a6800d1d-6604-4b82-8e81-ef5a4daac1e5","items":["監督長照資源妥善運用，讓長輩晚年安心、健康且有尊嚴。","推動好孕專案，擴大公共幼托服務及相關補助，讓家長安心成家育兒。","爭取設置苗南聯合服務中心，持續協助法律諮詢及陳情，推動縣政治理及服務。","爭取海線鐵路雙軌化，提升通霄、苑裡的公共運輸量能。","推動海線人文、藝術、生態產業發展及整體計畫，打造進步、永續的深度觀光。","提升就業輔導量能，打造進步的勞動環境。","監督環境污染稽查及環保犯罪查辦，守護家園環境與民眾日常生活。","監督光電、風電開發對農漁業造成的衝擊。","爭取設置苑裡休閒農業區，推動通霄、苑裡農漁業冷鏈系統。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a6d64bcb-8871-40a3-bf67-f11be5d67eb8","items":["強化社會治安，保障身家安全。","改善交通環境，增進生活便捷。","打造青銀共創、創造青年機會。","建設運動中心、提升身心健康。","監督大林蒲案、照顧在地居民。","規劃機場商務、帶動小港就業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["candidate_introduction","heading_or_slogan"]}}},{"claim_id":"a810f38b-2f05-4622-8de6-058c10bd9435","items":["捍衛農民居住正義，主張「農地農舍特登」比照「農地工廠登記納管」輔導合法化；督促市府加速「溫泉旅宿觀光業」合法化輔導，包含用地變更、請（補）照及營登。","爭取調和鄉村土地使用型態，創生東高九區風華；督促高雄市國土計畫執行，對旗美九區應合宜劃設「城鄉發展區」，提供民生商業、觀光文化及輕工業發展所需用地。","關注青年留（返）鄉方案，挹注農村新活力；督促市府成立東高區青年留（返）鄉就業輔導團，並爭取創業及從農補助方案。","體恤基層辛勞，爭取農民及鄰長應有福利及權益；爭取調漲水稻公糧收購價，要求改善農災救助時效，提議隨物價指數調增老農年金，並爭取協助政府部門第一線服務之鄰長調升交通費津貼及福利。","爭取基礎及重大建設經費，找回鄉村的價值與尊嚴；消弭城鄉發展落差，爭取基礎民生及重大建設經費，維護農村及偏鄉的尊嚴。","捍衛農村居民權益，財團種電不能侵犯影響鄰地使用；農地種電嫌惡設施應兼顧不侵犯毗鄰土地使用，督促市府審核機制應有退縮地及保護措施。","監督旗美地區易淹防洪規劃及治理，確保住居安全；持續督促地方經管之區域排水整治，並協調要求中央經管河川定期清疏及精進治理方案，以達成全流域綜合防洪效益。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"a82d2fd1-5756-41b6-8e7c-9dafd8464846","items":["後疫情時代 ，督促縣府規畫 「經濟再生方案」，協助民眾早日回復正常生活。","持續推動 「兒科急診」 專責醫院設置 ，就近照護孩童 ，讓家長放心。","加速 「屏東縣流浪動物收容所」 啟用 ，並監督其未來管理成效 ，給浪浪一個溫暖的家 ，增加民眾認養管道。","嚴格監督屏東國際棒球場工程品質 ，不讓新竹棒球場場地不佳的憾事重演。","屏東市崇蘭、潭墘地區人口眾多 ，車位嚴重不足 ，要求縣府重視該區停車空間的檢討規畫。","建議縣府多舉辦適婚聯誼活動 ，把握機會遇見幸福建立家庭 ，減緩少子化危機。","推廣產業多元化 ，引進高科技、藝術文化等領域廠商進駐 ，增加青年留鄉工作意願 ，提升屏東就業競爭力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a84c07e2-984a-4bf1-8a6b-ce26140eee01","items":["落實地方實質建設，有效監督縣政預算。","爭取警消福利經費，積極關懷弱勢族群。","監督環保守護家園，捍衛乾淨居住環境。","爭取中港溪河濱生態公園，增設動物友善空間及設施。","農業精緻化發展，整合網路行銷，鼓勵青農投入。","推動老舊市場翻新，打造亮點觀光市場。","弭平城鄉教育差距，改善學校設施設備，加強校園安全維護。","設置親子休閒環境，打造健康樂活、樂齡、樂學聚落。","爭取建設運動中心及長照機構。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a87ff3ce-7212-45a8-9f4c-7271543ab375","items":["堅持台灣主權，捍衛民主自由，推動台灣成為正常化國家。","爭取經費整建老舊校舍及體育設施，教具全面升級，優化教學環境。","持續爭取經費並監督縣府落實大埔截水溝堤岸道路及花壇排水防災改善等重大工程。","持續爭取經費進行自來水延管工程，提高自來水普及率，家家戶戶供水無虞。","持續督促貓羅溪芬園鄉縣庄段堤防整建及台化街下水道工程，改善遇雨成災問題。","督促政府落實長照政策與配套措施，並爭取彰化在地長照資源，減輕照護家庭負擔。","督促政府推動多元住宅方案，持續提升彰化社會住宅比例，滿足在地居住需求，吸引青年回流。","督促政府持續推動有感減稅政策，單身族、雙薪家庭及育兒家庭皆受惠。","持續關注、推動農民友善福利政策，擴大農業保險範圍，務農不用再看天吃飯，落實保障農民權益。","督促政府加強查緝詐騙及人口販運事件，防止民眾陷入新型態犯罪的陷阱。","持續促成中央政府與縣府推動彰化市鐵路高架化及台中捷運綠線延伸工程。","持續督促彰化台鐵舊宿舍群、中興莊及南瑤宮修復工程，促進彰化地方文化觀光發展。","持續爭取經費改善道路鋪面及護欄設施，並增加停車空間。","完善公共化住院照護，爭取住院看護全面納健保，減輕家庭照護負擔。","爭取經費協助縣府改善消防人力與設備。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"a8d0b8fd-99f4-4cad-9e42-8a3ba51b1301","items":["提昇治安工作,確保林園大寮優質安全之生活環境。","嚴密監控林園、大寮工業區之污染防治,提昇工安、環保,確保居民健康安全。","全力爭取高雄捷運系統延伸至林園,並連結大寮成一環狀系統以利地方發展。","中芸漁港擴建、觀光漁市場興建及林園海岸復育景觀再造應速完成以提升地方繁榮發展。","落實弱勢團體之照顧及各項津貼補助應予放寬。","爭取生育補助、提升托育及幼教照顧,創造人口正成長。","爭取林園、大寮地區觀光、文化、各項公共設施之早日開發以創造優質生活空間。","提昇教育品質,重視倫理教育工作,保障各級教師權益。","創造、爭取大寮、林園鄉親就業機會並適時輔導進入職場發揮人力保障生活。","協助高雄市推展各項工作,謀造全體鄉親幸福。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"a9034ba4-9944-445b-a82d-479afeabc386","items":["督促桃園市青年事務局善用每年2億2千餘萬元預算，落實照顧青年。","青年返鄉工作更有力：整合青年社團和大專校院學生團隊，對接公部門、企業和傳統產業。","孕產婦心理自費諮商適當補助。","35歲以上女性市民凍卵一次性補助和免費卵巢功能檢測。","桃園公立幼兒園重點擴增「二歲、三歲專班」；小學下課後4至6點安親的部分，由政府全額補助。","不分公幼、私幼應建立「幼兒園課程與教學品質評估表」，透明化檢視。","監督國中小學、公務機關無障礙空間。","保障特教生和一般生學子的基本受教權，讓「融合」不是口號；多元共融政策，每個學校及班級都應因適性制宜。","保障特殊教育教師助理員的薪資福利與每年受訓裝備、國中小重症身心障礙學子的特教員時數。","推動「桃園區失智老人家庭專屬活動中心」。","廣設市民活動中心，帶給長者舒適關懷據點空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"aae2b7b9-c27c-4786-ae96-6712cfd3b2a1","items":["推動在地食物銀行計畫，讓需要幫助的人獲得及時援助。","持續全力推動「嘉義市國中小營養午餐免費」。","推動國中小學電子圍籬及高解析度監視系統設置，並持續推動國際安全校園認證，以確保學童安全的就學環境。","針對全市公園內兒童遊戲設施的維護修繕，訂定全市整合的巡察修繕機制，定期巡查報修，提高使用安全性及使用效益。","積極爭取在東區設置「英語村」，提供國中小學生更多的學習機會，提升學生的國際視野。","整合嘉義市醫療資源，推動多元化「老人照護計畫」。","加強落實婦幼保護政策，提供不幸婦女第二專長訓練及輔導就業。","推動落實兩性平權，提升女性職場功能價值。","防範毒品、色情等惡害入侵家庭、校園，以創造優質生活環境。","督促衛生單位加強食物品管監控，確保市民飲食健康。","加強建構社區防護網，以確保市民居住品質。","爭取於東西區各設置一座寵物公園。","爭取興建國際規格滑板場。","推動將情緒教育納入國中小教育課程；並將國中小教師納入情緒教育的課程訓練中，讓嘉義市的情緒教育從家庭到學校，全方位無死角。","推動全面加速汰換全市國中小教室傳統燈具，達到節能省電成效，改善學童視力狀況。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"aaf55969-9be4-4b50-943b-e6fc9b0ace22","items":["積極提倡發展觀光事業，促進農、漁業合作，開創新機。","為婦幼發聲，持續為弱勢挺身。","責成警政、教育單位提出相關措施，全力防止毒與賭進入校園。","敦促教育單位加強生活與倫理教育課程，完善學子生活品格教育及法治觀念。","監督縣政，為民發聲，建立政府與民眾良好的溝通橋樑。","續為中小企業發聲，並敦促政府提供及協助良好的發展環境。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ab05846a-4e46-4905-a047-806a63f0683f","items":["保證1：絕對清廉，不讓屏南人覺得見笑。","保證2：絕對親自服務，一定找得到人。","保證3：中央→縣府→地方連一線，挺台灣、顧屏東，讓屏南大步向前！","顧交通！盯緊高捷延伸新園-東港-林邊。屏南快速道路。高鐵延伸到潮州。恆春觀光鐵道等重大交通建設進度。","顧農民！請中央加速建設冷鏈包裝加工廠、順暢行銷管道、提供完善農業資訊、提升天然災害救助補貼效率。","顧漁民！強化漁港建設、保護漁民安全。","顧勞工！要求強化職場安全，落實勞動檢查，以保障勞工權益。","顧學生！持續爭取校園內設施改善，包括老舊校舍、廁所、操場及風雨球場，讓教育資源進入屏南。","顧觀光！推動一鄉鎮一特色，以多樣化觀光元素吸引人潮，提升觀光產業產值，保障觀光從業人口權益。","顧全人！要求落實社會住宅興建，加強照顧長輩、幼兒國家養政策、政策減輕年輕人負擔，及身心障礙弱勢照顧。","顧醫療！強化偏鄉醫療，採專案增加診療科別及設備、補足醫護人力，由教學醫院支援偏鄉醫療。","顧客家！要求重視南客，挹注資源發展六堆客家文化暨產業。","顧健康！強化公共衛生政策，推動不分男女免費接種HPV（人類乳突病毒）疫苗，讓台灣HPV防癌政策跟上國際趨勢。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ab20556a-80f2-40d7-9d8a-a0bb1ad5d415","items":["推動太平區新聯合行政中心設立完成。爭取小孩國家養，推動國中小營養午餐免費以降低家長壓力並提高生育意願。","爭取建設捷運，由捷運綠線向北延伸至大坑，再由藍線向東延伸至大里、太平。","加速推動台74線銜接國一交流道，及增設十九甲、六順橋和草湖閘道，以解決台74線壅塞問題。","推動托育一條龍升級，增加嬰幼兒福利，並爭取公幼、公托及非營利幼兒園增設。","提升老人福利。如：敬老愛心卡使用範圍增加、長照政策推動、社區據點推動、老人共學延緩老化、長青學苑增設。","推動市民及親子空間設立，公園綠地普及化、公園塑膠致癌遊具逐步退場、閒置公共空間活化。","爭取太平公共停車空間，解決停車問題。爭取育賢路停車場與建立體、中興停車場加蓋以增加停車空間。","協助解決工業用地不足問題並推動產業健檢，協助夕陽產業轉型。","持續推動「農產品產銷失衡救助基金」，擴大預算規模以降低產銷失衡，並救助經濟農產品產業，確實照顧農民。","持續爭取設置監視錄影設備及建立聯防預警系統，提高破案率，有效嚇阻犯罪行為發生，還給人民免於恐懼的生活。","推動太平市民大道南段（宜文街銜接至台中小鎮永富街）都市計畫恢復及爭取施作，解決太平南北向道路壅塞問題。","太平環太東路銜接東平路777巷一路接至甲提路等堤防道路貫通，來解決東西向橫跨北屯、太平、大里等交通路網。","持續監督市府實施治水防災計畫，並推動南太平光興路設置地下雨水道，銜接滯洪池。降低急降雨造成淹水機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ab2ebe8a-7b0d-490b-aa0a-cce1ed510fed","items":["強力監督：定期將質詢內容報告民眾，全勤監督問政，用心聽取市民心聲","教育體育：加強校園安全，爭取校舍設施更新，改善國中小學生及教師教學環境","教育體育：推廣幼兒、國小食農及美感教育，改善教師待遇與福利","教育體育：推動校園特色遊戲場及運動館，更新運動設施，提升選手獎金，健全臺南體育","安心育兒：推動月嫂服務及親子悠遊空間，打造運動、交通主題特色公園提高公幼師生比，非營利幼兒園增園，公幼、非營利比例達70%","文化推展：爬梳古都歷史，再現城區古河道，推動建城四百，光榮臺南爭取科技圖書館，力推兒童圖書館及催生國家漫畫館","勞動權益：守護勞工工作安全權益，關注公教警消超時工作，持續推動職場教保服務，完善托育、課輔需求","觀光交通：推動運河改造及改善水質汙染，打造亮點廊帶，帶動整體觀光機能","觀光交通：力護機車族權益，增設停車塔及共享自行車站點，打造低碳觀光城市","觀光交通：爭取2024台灣燈會、國慶焰火，發展臺南觀光及經濟成長","社會福利：長者健保福利金全額補助，推動長照延緩失能，加速輔具申請","社會福利：加速身心障礙者輔具評估，推動二手輔具機制","社會福利：推動社宅建置，增設課後輔導班，照護單親、弱勢家庭孩童發展","社會福利：關心心理衛生中心布建，增加心理諮商免費次數，舒緩現代社會壓力","青年發聲：持續關心社宅租金，增加社宅服務空間，青年安心入住計畫","青年發聲：促生青年創業基地，打造友善青創及工作環境","青年發聲：推動青年參與政策討論會，鼓勵青年參與公共事務","青年發聲：積極打造區域發展，爭取地方創生，再現都市國際化"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ab7f0654-3b4f-4cb7-8b4d-2c5a08a74863","items":["落實土地正義 持續推動都市計畫區公共設施用地專案通盤檢討","監督政府具體改善空氣品質環境 推廣環境永續發展，維護鄉親健康","強化社會安全網 公私體系協助媒合社會資源挹注弱勢群體","發展教育硬實力 爭取各校硬體設備及教學資源","發展文化軟實力 爭取經費加強各區特色藝文活動"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ac787c39-9171-40a5-9611-0a9f90496a97","items":["嚴格監督提昇縣府行政、預算、社福、建設之功能效率。","輔導農業轉型升級，設立農產品專業特區，並健全運銷制度，減少中間剝削，提高農民收益。","推動農地改良輔助方案，降低農藥使用，提高農產品產量。","地方觀光資源開發，改善交通網及屏縣重南輕北之落差。","建立鄉鎮就業資訊服務網站，提高鄉民就業機會。","促成台糖土地開發利用，增加地方稅收及居民就業機會。","推動公辦民營安養中心，健全老人安養功能照顧。","加強六歲以下幼兒照顧，規劃幼兒及醫療補助方案。","尊重女權，保障婦女工作權益，落實兩性平等理念。","推動校園社區化，提供休閒場所，提高社區藝文水準。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ac7efd75-c964-4875-9c42-a29b74cf5b9c","items":["強化全縣網狀公共運輸接駁系統。","爭取縣民搭乘公共運輸補助。","強化樂齡服務，增設長照據點。","推動公共托育及非營利幼兒園。","打造新住民多元友善環境。","整建二龍河，打造文化、觀光、休閒園區。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ad175882-b92f-45da-b903-78b3a379d937","items":["擴大南投市都市計畫，讓新街變成南投市的衛星城市。 往名間交流道方向，進行南投市都市計畫擴大，建設輕工業區、長照中心、假日小農市集，增加工作機會，不讓污染給下一代。 往南投交流道方向，擴大生活機能，建設青年住宅與社會住宅。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ad6828fd-7597-4bb3-a791-55a587bc35b5","items":["傾聽在地聲音，提供迅速選民服務，解決民生問題，爭取市民福利。","積極推行板橋都更計畫，提升市民生活品質。","督促市府落實預算的執行，建立有效率的預算編制。","爭取警消人員權益、提升救災設備，保障市民之安全。","持續要求市政府、警察局增加社區內監視器，以維護老弱婦孺生命財產安全。","督促市府建設，改善企業投資環境，協助青年就學、就業、創業、成家、安居。","持續加速板橋地區地下停車場設立，解決市區停車位數量不足問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ad6b49bd-3f34-40fa-93de-5848321c2c43","items":["「以太保市治理經驗，擴大服務區域」，太保市是嘉義縣人口唯一正成長的鄉鎮市，也使第一選區議員席次增加一席，榮利本諸清廉、務實、真誠的初衷，爭取擴大服務鄉親的機會。","嘉科落腳太保市、水上鄉有南靖產業園區、鹿草鄉有馬稠後產業園區，本人將力促政府早日開發完成，引領台商回流，擴大就業市場。","高鐵特區暨縣治第二期都市計畫開發案，總面積達 343 公頃，目前縣政府擬公辦開發，為確保地主權益，將監督縣府，做妥善及合理的分配，比例不得低於自辦。","縣治特區對面商圈開發案停滯多年，將督促各局處力邀大賣場進駐，帶動區域發展，打造宜居宜業好住宅。","本選區轄內溫室面積為嘉義縣密度最高，為協助青農拓展優質農產品市場，將積極推動外銷通路，增加收益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"adcaaf12-8e2b-4fbb-a2b5-6d9fda543e29","items":["支持陳其邁市長的產業政策:創造高雄產業轉型,力爭台積電,催生橋頭科學園區,打造高雄時代。","支持陳其邁市長的社宅政策:面對高房價,積極興建社會住宅,並放寬社會住宅限制。","規劃從高鐵進右昌、高雄大學、橋頭科學園區的捷運紫線。","規劃左營楠梓段鐵路立體化。","台積電(原中油)南側園區南路通翠華路到民族路;縫合左營楠梓交通,2020完成打通新莊一路銜接勝利路,縮短新舊部落距離;改善國道十號交流道,持續推動國十生活圈路網便捷性。","新台17線到左營南門圓環全段已於 2022 經行政院協調,軍方定案,明年動工,拼2025全線通車。","友善育兒環境,爭取政府編列育兒津貼到每月五千元,推動非營利及公立幼兒園,減輕年輕家庭負擔。","將兒童共融遊具搬入藍田公園、右昌森林公園、國昌公園、清豐公園、福山公園、蓮池潭兒童公園。","打造溫暖、疼惜長輩的友善城市,讓長輩在年輕人上班時間可以走出家門,到巷弄照護站兼顧健康與休閒。","保存左營在地眷村文化,結合見城計畫與眷村重整,打造左營眷村觀光資產,找回左營老記憶。","推動中油宿舍區的保存與未來,宏毅宿舍應做保留,宏南宿舍空間活化,與市政府合作產業住宅,給宿舍居民一個末來。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"ae056980-6ea0-401f-ba9a-b3e6f1834761","items":["堅守台灣主權,守護本土文化,強化台灣價值及民主自由防線。","長輩友善|落實長照社區化,佈建完善老人居家照顧機制,並整合社區公有閒置空間,提供相關照顧服務。培訓長期照顧服務人力,並提高薪資福利。整合醫療資源,增設教學醫院公車路線網,提供長者更便利的就醫接駁。","育兒友善|擴展平價教保服務機構,布建多元托育資源,加強公托品質,獎勵閒置空間設置微型托育機構,提升公共化教保服務比例,持續爭取育兒資源再升級,協助家庭分擔照顧責任。","環境友善|推動能源轉型,減少燃煤,增加再生能源,督促市府成立「綠能推動辦公室」。鼓勵公民電廠,參與扎根環境教育。減少運輸工具排碳量,公車及公務汽機車全面電動化,推動全市電動機車總數占比達10%。加速推動中區焚化爐五年內除役。","交通友善|加強公共運輸的便利性,完善高雄捷運路網。持續守護用路人道路品質,加強孔蓋下地減量齊平與道路挖掘管控,增加工程施工查核頻率,推動重大建設優先施作共同管道。推動人行道整平計畫,優先針對校園、醫院、捷運站、商圈等周邊人行道進行整體改造。增加停車空間,利用公園及學校操場闢建地下停車場,紓解停車問題。","高雄安居|落實居住正義,推動公辦都更分回社宅,提升社會住宅存量,加速推動老舊社區都市更新、危老重建,擴大租金補貼,保障弱勢族群和青年居住權。","挺青年|支持 18 歲公民權入憲,鼓勵青年參與公共事務。整合市府閒置場域,持續規劃青創基地。","挺產業|持續推動產業升級,督促設立產業轉型基金,輔導在地產業轉型。規劃完整科技及生技產業園區,增加就業機會。","挺商圈|推動鐵道周邊商圈活,並打造商圈智慧聯網。","運動城市|加速三民運動中心地興建,推動公益時段鼓勵市民養成運動習慣。結合運動科學與醫療資源完善運動選手訓練環境,爭取舉辦國際賽事,創造運動新經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ae50a1c5-9df8-428e-9c25-b26624dff17c","items":["爭取六六快速道路由平鎮區金陵路六段台北商業大學高架延伸到龍潭區大昌路","爭取龍潭區福龍路拓寬為30米道路,因應未來平鎮捷運路線及六六快速道路高架延伸到龍潭區做準備。","爭取設立龍潭國民運動中心,設立在東龍路上市立龍潭高中仍有住宅區校地,希望可以配合龍潭高中共同辦理,比照中央大學內設中壢區國民運動中心模式","爭取設立龍潭國小操場施做地下三層停車場,解決市區停車問題,地下停車場由東龍路做出入口。","積極推動龍潭區廣設公立托兒所、育嬰中心及長照中心的設立。","老人三節敬老金及九九重陽節禮金提升、爭取恢復龍潭區市民全部免費入園石門水庫","推動公車轉運站,建議都市計劃變更中正路和大昌路附近農地,市地重劃做公車轉運站。","爭取國有土地興建社會住宅,目前各區都有社會住宅,龍潭區必須積極推動社會住宅的興建,方便年輕人居住。","推動親子共融式公園,湧光路和聖亭路交叉口仍有閒置三仟坪市政府土地,清理地上物,設置親子公園解決八德、聖德里沒有公園問題。","爭取板橋到龍潭,由大漢溪河岸施做一快速道路,解決北二高假日塞車問題。","龍新公路拓寬工程,龍潭區往新埔鎮道路拓寬為12米道路。","桃園市警察局龍潭分局旁空地土地,爭取興建立體停車場,解決車位不夠問題。","老街溪上游河川整頓,從燈潭橋、聖亭路前端至福龍路河道旁施做自行車人行步道,未來連接到平鎮區"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ae79614c-5765-496a-b25b-336e63596d05","items":["持續推動砂石車專用道路方案，保障民眾生命財產與生活品質。","持續爭取65歲以上假牙補助。","推動及輔導青年返鄉從農成為農業生力軍，提升產業價值與創新。","創造閒置農田媒合平台提供租用，增加人才回流意願。","推動農業在地品牌化，持續解決農業問題。","保障女性就業、消除性騷擾與歧視、積極落實職場平等。","關懷新住民文化與在地融合、生活適應、輔導家庭及孩童心理成長等。","持續爭取公托及嬰幼兒完善福利制度編訂與推動，減輕家長育兒的負擔。","補助客家社團、推動文化交流，加強客家母語教學，傳承提升客家意識與認同。","完善屏北到高雄交通跨域網絡，持續爭取國十延伸及高屏第二快速公路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"aeb239a6-2d5f-4ed7-8fc6-832e64a4ed13","items":["延續上屆政見持續推動各項建設及爭取各項福利。","爭取共融式遊戲場，打造全齡式遊戲公園。","持續推動青年創業環境，結合文創、青創基地媒合創業資源平台。","結合和美、線西、伸港各觀光景點，打造一日旅遊圈。","正視老人獨居問題，持續推動設立老人日照共餐據點。","改善和線伸交通網，爭取嘉卿路與西濱台61線貫通，便捷地方生活圈。","爭取增設新住民事務服務單一窗口，提供就業輔導機制及教育、語言、社會福利政策等各項服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"af6aa675-4808-4df4-84e6-9edf58d0dcf7","items":["爭取加強在籍鄉民搭乘交通船補助","加強爭取各村補網場及漁具倉庫興建","爭取加強各村老舊社區活動中心及鄉內老舊道路改善","爭取學生教育軟硬體各項補助","爭取各漁港持續疏濬及各碼頭改善","爭取各村入口意象，促進地方觀光發展","籲請政府在觀光、環保與漁業發展取得平衡點，捍衛漁民生存權","爭取加強解決三級離島水（海淡廠興建）、電（各村平均3台發電機）定期航線交通問題（馬公↔花嶼），（馬公↔南方四島）","建請政府增加社會福利，照顧偏鄉民眾。","主張縣府督促海管處六大承諾應予實現，不能失信於民。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"af7a2659-74fa-4c4b-9d7d-01b4a88de544","items":["落實「老有所終」老年人長期受照護，並發揮銀髮力。「壯有所用」壯年人能發揮所長，免於失業，而安居樂業。「幼有所長」幼年托育安全，人本教育並能快樂學習好好地成長。祥和富裕居住的社會環境。","推動基礎建設，從彰化熱點拉起串聯，發展觀光，促進地方產業升級並整合資源打造以發展經濟促進地方繁榮的政策方針！","結合縣府與地方慈善團體，共同照護社會弱勢，使鰥夫、寡婦、孤兒、沒有子女的老人家，以至殘疾的人，都能得到照顧。","普設彰化縣非營利事業托兒所，以減輕雙薪家庭經濟負擔","國中小學校增設冷氣裝備以利提供優質學習環境！","讓彰化成音樂之都，藉音樂撫慰民心，增進親子互動，提供街頭藝人及在校學生音樂表演平台！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b11277f1-d97c-4225-bfba-3e4e9fdbcd28","items":["強力監督金酒,守護金雞母。","督促縣府重新檢討自然村自治條例。","督促縣府通盤檢討特定區計劃(都市計劃)","推動支持興建金廈大橋。","建請成立加工出口區,提升青年創業及就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b145d599-69f2-4a32-84ba-edffcbcd6777","items":["我認為，一座城市裡最重要的是人，以人為本，城市才能穩定發展、成長。 【政治理念】好的政策，應該落實在每個人的生活中。","普設YouBike2.0，推廣淨零碳排環保城市，目標新北市建置完成1500站YouBike2.0。","智慧公車站牌增設，鼓勵使用大眾運輸工具，加速推動中和建置80站智慧公車站牌。","持續更新整平人行道及改善淹水熱點，守護市民行的安全，構築友善通行環境。","實踐雙北共同生活圈，規劃單一定期票券，不限次數搭乘雙北捷運、公車、火車及YouBike。","守護學童上下學安全，改善通學廊道，爭取年底完成50所學校通學廊道改善工程。","找回人口競爭力，目標增加公共托育中心達200家，形塑友善生養環境、打造樂活宜居城市。","讓年輕父母敢生小孩，提升新北生育率，持續爭取提高生育補助，減輕父母育兒負擔。","積極協助青年事務，改善低薪環境，推動青年創業輔導及補助。","打造新北藍帶、擁抱親水城市，110年藤寮坑溝整治成功，加速推動瓦磘溝及中原溝改造計畫。","形塑健康城市，全面增設體健設施，中和灰磘里、烘爐地山下特色籃球場規劃興建中。","關懷銀髮族權益，爭取廣設日照中心及長照機構，讓長輩無後顧之憂、安享天年。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"b1acac33-6ed8-40aa-95e0-24eb3daef8db","items":["積極傾聽民意，勤走基層，共同監督縣政，為民服務。","拼經濟：促請政府重視並扶植地方農、漁、工、觀光產業，並吸引青年返鄉就業創業，支持地方產業永續發展。","拼建設：爭取地方基礎建設，改善農水路、海堤整治、區域排水設施、各項維護民生安全與交通便利等建設。","拼教育：加強學校軟硬體設備，改善偏鄉學校教育資源不足問題。","拼觀光：整合地方休閒遊憩資源、天然海域、地方產業、宗教文化、人文活動等，共同推動台灣西海岸觀光榮景。","拼福利：保障弱勢救助、老人生活、獎勵生育、學童就學等各項福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b1bf421c-9a91-46b5-b749-7a4b1929fda7","items":["園為共融式特色遊具並爭取「新屋旗艦型公園」。","海成為「市級風景區」，台61橋下興建大型運動公園。","碳轉運中心、觀海橋重建，改善假日交通問題。","小學「一校一外師」、「班班有觸屏，人人有平板」政策。","機補助，輔導農友機械化生產。","閒農業區、推動新屋地方創生，吸引青年返鄉。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b1ec7be6-9cda-4b61-be69-7e664fa2184c","items":["王景山持續尚骨力服務：持續爭取經費，興建及修繕道路及公共設施，提升居住生活品質。","王景山持續尚骨力服務：持續爭取經費改善及修繕農水路和灌溉設施，落實重視土地，照顧農民權益。","王景山持續尚骨力服務：持續爭取路燈全面更換為環保節能的LED路燈，透過無線故障回傳通報功能縮短維修時間，讓「夜晚回家的路明亮安全」。","王景山持續尚骨力服務：爭取設立農漁產平台，輔導農民申請認證，建立特色品牌，提高農民收益。","王景山持續尚骨力服務：爭取設立冷鏈物流園區，提升溫控貯存運輸能力，確保農產品質，減少農民損失。","王景山持續尚骨力服務：善用科技，導入智慧農業，吸引年輕人返鄉投入農業、行銷屏東農產品。","王景山持續尚骨力服務：爭取提高農保喪葬津貼，讓農民得到最後的尊嚴，也減輕身後其家屬經濟負擔。","王景山持續尚骨力服務：爭取調整農業保險的理賠條件，提高農民投保意願，分散種植風險。","王景山持續尚骨力服務：爭取補助中小學生營養午餐費，並採用在地食材，一周一日有機蔬菜，從產地到餐桌建立食安鏈，讓孩子健康成長。","王景山持續尚骨力服務：爭取設置網路教學系統，並補助偏鄉小學購置平板電腦，充分運用網路以及新科技教學，弭平城鄉差距。","王景山持續尚骨力服務：爭取設立新住民服務中心及關懷據點，不僅讓新住民姊妹有專屬空間可以相聚，更可提供法律、福利、就業等協助。","王景山持續尚骨力服務：爭取提高社會福利預算，提高對單親家庭、身障人士、新住民等弱勢家庭的照護品質。","王景山持續尚骨力服務：督促政府加強防疫清消，並加強宣導注射疫苗。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"b2267180-b406-41b8-bc08-d9bce978da10","items":["監督屏東高鐵特定區、屏東科學園區計畫、及國際棒球場運動園區計畫等重大建設推行進度，並力求提升縣政府招商引資能力，從產業發展帶動薪資競爭力，讓青壯年回鄉就業。","鼓勵新創產業，培植在地青年創業，打造在地創生新品牌。","強化在地文化脈絡，打造屏東藝文觀光，全力推動觀光軟硬體之發展與建設。","督促青年勞動就業政策，透過產官學合作，讓優秀人才根留屏東。 ｜屏東好行｜","全力爭取高雄捷運大寮屏東線為優先路線，捷運南延屏東市，強化高屏生活圈。","盤點屏東市停車空間配置，平衡人口密集處及重要商圈區域均衡發展。","要求全面改善屏東市交通規劃，提升縣民用路安全及生活品質。","大力推動綠運輸比例，推廣低碳交通。 ｜屏東好窩｜","爭取社會住宅興辦，實現青年安居。","督促脫貧政策實現，關心弱勢家庭及其兒童權益。","緊盯屏東榮總兒童急診編制，關心成人健康，更重視孩童醫療。","爭取銀髮族社會福利，擴大公共設施使用敬老卡，銀髮樂活老少安居。 ｜屏東好育｜","爭取擴大育兒福利，分擔年輕爸媽養育負擔。","爭取提升學校語言學習資源，培育學童國際競爭力。","振興屏東體育大縣，持續推動體育人才留縣培育計畫，力促發展體育產業。","監督校園安全網落實，推動性別平等人權教育，杜絕校園霸凌事件。 ｜屏東好NICE｜","完善動物保護自治條例，推廣寵物友善空間。","充實警消勤務人力及裝備，提升警消權益。","監督社會安全網的實踐，普及警用監視器及提升妥善率，創造安全城市。","推動電纜地下化，整頓市容整潔，重現廣闊的天際線。","找回資源回收車，落實垃圾分類政策。","重視環境汙染問題，督促縣府管制及改善措施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b27af197-6709-463f-84b3-1e20a10132a0","items":["監督縣政，做好為民服務工作。","持續關心中興新村地區發展走向。","推動社區聯防工作，以減低犯罪率，維護治安。","監督工程品質管制，以維護公共安全。","對不合宜之法令，督促縣政府檢討並協助解決，以解民怨。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b2b41815-66b9-4083-b3b0-ecb890f48407","items":["打造宜居安南：遊子返南！定居樂業！年輕城鄉！翻轉安南區！","「綠色交通佈點」：爭取共享電動機車進入安南區。","「製鞋產業優化」：爭取全國鞋展在台南舉辦，催生「鞋藝創新據點」，向下扎根並推廣製鞋職人精神，推進台南鞋業為世界級精品的目標努力。","「農漁產業升級」：推動智慧漁業，促進養殖產業升級與提高產值，爭取延伸冷鏈公共建設、加強產銷調節能力，有效改善及提升農漁民生活品質，改善地方投資環境、實現區域均衡發展。","「特色商圈營造」：打造安南區專屬的特色商圈，帶動安南區商業經濟發展，使安南區生活機能更加完善。","衡量市府財政狀況，爭取逐步增加65歲以上年長者之健保費至全額補助、提高各項老年醫療補助。","爭取增設安南區特色公園以及溪畔休閒空間。","減輕房租、買房經濟壓力，並確保住宅消防安全。","「提高奪牌獎金」：參加全運會、全中運選手的奪牌獎金增加。","「導入運動科學」：強化基層運動隊伍訓練品質，以運動科學為基礎，提供運動傷害防護員、物理治療師、專業體能訓練等，照顧基層選手的身體。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b2bb6654-912b-40a4-a8b1-6a7d502771db","items":["積極爭取65歲以上老人健保免費。","積極爭取65歲以上老人重陽敬老金提高至3000元。","積極爭取選區內路平、燈亮、水溝通的居住環境。","積極爭取國小學童營養午餐免費。","積極爭取農民福利。","積極爭取農水路改善。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b2e43045-0737-4a56-82d2-bf28a7216bc5","items":["劉勝全十全政見：全關懷：長者幼兒照護，全人關懷。","劉勝全十全政見：全醫療：醫療量能，守護你我健康。","劉勝全十全政見：全躍升：航空城專區，產業齊躍升。","劉勝全十全政見：全樂活：綠能桃園，樂活悠遊水岸。","劉勝全十全政見：全生養：學齡前育兒津貼，安心養。","劉勝全十全政見：全教育：特色小學，雙語優質學習。","劉勝全十全政見：全交通：智慧城市，雙北快捷交通。","劉勝全十全政見：全新農：培育新農，綠金科技農業。","劉勝全十全政見：全職安：職場安全，守護勞工權益。","劉勝全十全政見：全青創：青年職能學習，創新輔導。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b37253ad-33e2-4708-93fc-bfdf23c24d35","items":["全力爭取經費建設，發展地方觀光。","促請縣府關懷老弱婦孺及身心障礙者，加強推動社會福利政策。","促請縣府提升教育、文化、醫療服務等活動。","建議政府重視阿里山沿線，國有財產局、林務局承租人權益，讓民眾安心居住永續經營。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b38b377e-3e71-467e-98d7-bac2c3a86a72","items":["堅決反對台電協和電廠改為天然氣發電，堅決反對填海造陸興建第四天然氣接收站。","強力監督市府早日完成全市污水處理接管，讓田寮河早日清澈並興建田寮河親水區。","強力要求自來水公司徹底改善大深澳坑地區高地供水，建構穩定高地供水網絡。","爭取本市各項社會福利補助應與雙北標準一致，不應淪為二等公民。","爭取本市積極活化信義區老舊眷舍、校舍，提供民眾作有效之利用。","賡續爭取更多 WOW-BUS 跳蛙公車路線，便利民眾搭乘的快捷公車。","爭取市府將原「基稅莊」活化使用，闢建為青年住宅或培育青年運動成長空間。","嚴格監督政府落實長照政策及老人福利並應充實各里老人健康休憩設施。","爭取深澳坑路86巷口交通號誌，改善微笑台北附近地區交通擁塞問題。","積極爭取62快速道路增設槓子寮交流道，以利廣大深澳坑地區通勤民眾使用。","強力監督天外天空氣品質及保麗龍處理方式，改善信義區空氣品質。","爭取放寬本市老人三節慰問金審核標準，落實敬老愛老政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b44ecb98-9d86-4843-8d6c-cd194140ffe2","items":["青年共好：鼓勵青年返鄉創業，爭取青年創業貸款利息補貼","青年共好：協助青年跨域就業，爭取交通多元補貼","青年共好：鼓勵青年返鄉成家，爭取多元社會住宅、租金補貼","青年共好：推動公私合作，爭取托育中心及補助等多元方案","青年共好：推動在地就學，爭取每區設立完全中學","青年共好：守護校園安全，積極監督毒品防治作為","銀髮共尊：爭取廣設銀髮據點，建立長照多機能及無障礙友善環境","銀髮共尊：爭取提升臨托量能，減輕家庭負擔。","銀髮共尊：爭取銀髮據點設施設備再升級打造長者尊榮空間","銀髮共尊：提升失智照顧服務量能，照顧弱勢族群","銀髮共尊：推動成立社區旗艦型服務中心，強化社區整體照顧模式","建設共展：督促淡江大橋如期完工，推動河口景觀再造工程","建設共展：加速推動淡北道路新建工程，改善交通瓶頸","建設共展：加速推動105市道全面改善及拓寬工程，建構安全回家道路","建設共展：加速推動八里輕軌及淡海輕軌延伸北海岸，形塑輕軌低碳生活圈","建設共展：爭取芝投公路及觀音山環山道路開闢，健全地方交通路網","建設共展：爭取興建八里龍源消防隊及派出所立體多目標使用大樓，強化救災量能並同時解決區民停車問題","經濟共享：積極推動台北港娛樂區及產專區加速開發，創造就業機會、打造港灣新城市","經濟共享：積極推動淡水沙崙科技園區及第二漁港加速開發，串聯三芝、石門悠遊樂活，創造北海岸新願景","經濟共享：結合八里左岸、十三行博物館與輕軌廊帶，發展綠廊經濟學，擴大青年參與地方特色創生","經濟共享：強化在地農漁業產品推廣，擴大有機化、品牌化及智能行銷","經濟共享：發展在地休閒觀光產業，左岸、右岸特色景點再升級。","文化多元：發展客家文創產業及客家觀光美食並推動北海岸客語培力發展計畫，傳承客家文化","文化多元：推動北海岸新住民培力發展計畫，增加新住民就業機會","文化多元：推廣新住民多元慶典及展演活動，促進文化融合","文化多元：推動異國文化共融發展，招募國際人才，建構友善國際生活環境。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b463597a-f45d-4e52-ba2c-800dd427dcd6","items":["專業監督預算，避免債留子孫","強化社區長照機制","充分利用閒置教室及社區空間，增設公托中心並延長服務時間","加速闢建社會、青年住宅","推動學校課後輔導機制，減輕家長負擔","持續關注校園反毒、反霸凌及食安管理","65歲以上長輩免費裝假牙","增設鳳鳴、土城重劃區中小學及地下停車場","爭取各區天幕球場","爭取台65線延伸至龍潭並闢三鶯二橋交流道","闢建寵物公園","樹林：加速樹林捷運開工並增設地下停車場","樹林：拓寬環漢路並加速新莊至鶯歌堤內道路完工","樹林：爭取大漢溪親水遊戲水域","樹林：爭取浮洲橋銜接65線完工","樹林：定期舉辦北大街道親子遊戲","鶯歌：加速三鶯捷運提前完工","鶯歌：加速三鶯大橋改建","鶯歌：加速鳳嗚火車站早日完工","三峽：推動闢建鳶山隧道","三峽：增設客家園區捷運站(LB07a)","三峽：打造三峽河小碧潭(祖師廟前)","三峽：爭取長福停車場立體化增加停車位","三峽：加速三峽分局、消防分隊大樓改建","土城：加速北土城交流道闢建","土城：遷移土城看守所，闢建大安森林公園及地下停車場","土城：爭取金城變電所增設地下停車場","土城：爭取捷運土城站公有地多功能使用"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b486a02b-58af-4662-bf0f-b7453367d183","items":["加強監督市府預算，把關資源用在教育及家庭需要上。","推動國小英語生活化，國際化是全民的權利。","強化以愛為核心的品格教育，減少校園霸凌。","投注資源預防兒少手機成癮，帶動家庭歡聚時光。","把關食品安全，建設公園綠地，照顧長者的生活。","社會住宅興建應有配套，改善交通並加快都更。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b4a88648-bb17-41c8-a465-f4b33df5ab6f","items":["堅守原住民文化，捍衛原住民權益，監督縣政，為民喉舌，爭取鄉親福祉。","促請縣府重視原住民母語教學課程，培訓原住民教師，以彌補山區老師嚴重不足的情況。","加強都市原住民文化會館周邊設施，完善館內設備，使都市原住民有良好的文化傳授、技藝學習、聚會活動的場所。","繼續爭取經費落實基礎建設，改善各村農路，提升飲水品質，健全消防系統，培訓體育人才，強化電力與電信功能，並積極爭取野溪整治及曾文溪護岸工程，以維護鄉親生命財產安全。","繼續爭取山美至里佳道路開通工程，完善鄉內道路連貫系統。","督請縣府將169線納入生活圈道路，並改善129線急彎路段及改善155線、149甲線等鄉內主要道路。","督請縣府加強山區醫療服務，加強老人照護，增加生產補助並落實急難救助等社會福利。","促請縣府重視觀光、文化、農特產及原住民傳統技藝等各項產業發展，配合部落特色，營造部落企業，繁榮地方經濟。","促請縣府寬列經費補助原住民各歲時祭儀及文化活動。","督請縣府重視遷徙至永久屋鄉親的各項權益，並輔導就業及協助發展永久屋之各項產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b4e580a9-1fa1-46c8-bd98-79fc28a12d62","items":["能源政策：以核減煤與國際同步，善用核電降低碳排及空汙，降低全民電費支出","能源政策：邁向無煤，達成2040無煤台灣目標","能源政策：擴大節能、儲能及智慧電網資源，提高調度效益，確保供電充足穩定","交通建設：加速八德綠線捷運延伸至中壢.大溪","交通建設：加速推動鐵路地下化工程促進均衡發展","交通建設：加速大湳豐德交流道建設工程，優化城市與國道連結，減輕阻塞壓力","交通建設：道路拓寬工程以系統管理、斷鏈補缺","兒老福利：80歲以上取消巴氏量表","兒老福利：看護移工與長日照體系整合，改善照護品質","兒老福利：安定基金補助，提高本國勞工就業率，減輕家庭負擔","兒老福利：爭取增設幼兒公托","青年政策：上市櫃公司提撥稅後盈餘做為員工加薪比例","青年政策：中小企業年輕人受惠放寬，基本工資調升，企業加薪可扣抵額度擴大","青年政策：扶養12歲以下子女，扣除額提高50%","青年政策：青年多元居住措施，落實居住正義，確保青年居住權益","經濟民生：加速推動自由貿易港區，結合產官學降低成本、提高效率，提升經濟競爭力","經濟民生：監督行政院農業部穩定農產價格，保障物價平衡權益","食安政策：監督衛福、農業、經濟相關部會，食品原料輸入之法令管制辦法，保障食品健康安全","全面監督爭取預算：全面爭取預算推動地方建設發展","全面監督爭取預算：全面監督修訂排除不合時宜之法令，爭取中央統籌分配及補助款合理編列","醫療照護：爭取針對醫療問題全面檢討","醫療照護：提升第醫療人力與量能","醫療照護：爭取增設八德大溪市立大型綜合醫院","文化觀光：結合在地文化產業新創","文化觀光：推動地方特色觀光","兩岸政策：尋求共同認知，建立穩定和諧管道","兩岸政策：促進兩岸民間經濟文化交流，創造和平穩定條件"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b57a3c62-8106-4f2e-9074-74af3408e938","items":["秉持「誠實、勤快、活力」的理念。盡心盡力為民服務。","積極爭取高鐵特定區、商業區周邊產業之開發與繁榮。","積極推動長照2.0居家、社區、住宿式照顧服務及家庭支持,普及照顧服務體系,實現在地老化目標。","紓解單親家庭照顧子女的經濟及托育壓力,協助弱勢家庭兒童及少年緊急生活扶助。建構完善的兒少福 利制度及安全的成長環境,促進婦女福利,維護婦女權益並提升婦女地位。","督促縣府實現休閒公園之規劃與開發,使休閒與觀光結合進而帶動地方繁榮。","督促縣府振興外埔與龍鳳漁港為休閒與觀光漁港,進而振興漁民經濟,改善漁民生活。","督促縣府重視發展建立社區特色以提升社區文化及生活品質。","積極推動如何防護少子化的衝擊與社會福利政策息息相關。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b64ae08d-d428-4d29-a4d0-79608ad7d298","items":["以顧台灣、行公義、重教育為問政理念，做清廉、專業、專職的議員。","加速屯區捷運，力促橘線(機場捷運)及紫線(屯區環線)盡速核定施工。爭取完善台74線快速道路上下匝道，緊盯草湖地區大里霧峰匝道盡速完工、嚴促十九甲地區立善橋北上出口匝道加速動工、如期完工。","爭取推動「國中小營養午餐免費、營養加倍計畫」。持續提升公托、公幼質與量、增設非營利幼兒園。持續在公園與校園增設共融遊具。優化普設親子館，廣設親子廁所及親子停車格，建構友善親子育兒環境。","優化敬老愛心卡服務項目，方便長輩使用。改善社區活動中心的空間環境，充實社區關懷據點服務能量。","力促新建大里區聯合行政中心、霧峰區聯合行政中心盡速動工、如期完工。協助中小企業與傳產永續經營，加速闢建夏田產業園區、塗城產業園區。爭取在大里、霧峰新設社會住宅。 6增設複合式立體停車場，增加 YouBike 站點及密度，優化公車路線及候車環境，普及智慧型站牌。推廣綠色能源，推動光電風雨球場、光電停車棚。","加速老舊校舍整建補強及健全校園體育設備，充實校園閱讀資源。引進多元藝文活動至社區及校園。全面檢討易壅塞路段，規劃新闢道路，督促拓寬道路工程經費編列。","持續推動旱溪排水整治計畫，新增大里霧峰親水河岸空間。整治大里霧峰區域排水，建置完善下水道系統，改善易淹水問題。","持續推動大里菸葉場活化再利用，再造地方新亮點。推動光復新村再現風華計畫，發展中台灣影視基地影視觀光產業。加強農業產銷輔導，提升農業產值。","增設優化大里霧峰自行車道及登山步道，提升公園綠地質與量，廣設社區體健設施，提供市民休憩觀光的樂活環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b680281c-40e7-4371-b54f-5daf0f649397","items":["．堅持居住正義，爭取社會住宅及青年住宅興建。 ．後疫情時代，協助在地青年輔導創業並提高青年創業基金額度。","和美 ．針對在地需求，開辦職業技能訓練，降低失業率，提高工作待遇。 ．運用公有土地，增加和美停車空間，改善市容，讓全民便利使用。 ．運用閒置空間，增加運動休閒場域。 ．推廣道東朱子文化祭，再現道東書院古蹟風華，提升古建築活化利用。","線西 ．爭取線西濱海生態公園設立，增加在地特色旅遊據點。 ．爭取台61線快速道路休息站設立，便利往來遊客，並活絡地方產業。","伸港 ．致力推動海濱觀光活動，爭取彰濱隔離水道導入常態性水上活動。 ．加強環境教育與保育，深化推廣伸港溼地生態旅遊。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"b68f2ef9-9347-4ed4-9a0d-2b419fc53a80","items":["出自基層,以回應基層需求為主要參政理念,務實與行動,是爭取地方認同的問政主軸。","強化縣府與地方的鏈結,針對後龍、造橋、竹南等地區,依照城鄉需求爭取合理資源分配,為富鎮拓建設,為僻壤爭資源,廣徵地方人士建言,使縣級、鎮級單位,以及政府與人民之間建立暢通管道,切實反應人民意見,嚴格監督預算執行成效,經費花在刀口上務求本縣財政平衡,且兼顧社會福利與地方建設。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b6b2beef-8984-4967-9d40-79d381c4b6f5","items":["交通建設：爭取洲美快速道路 ( 福國段 )，監督北士科技園區周邊交通建設、台北市路口號誌不斷電、交通號誌智慧化，解決交通問題。","校園安全：強化校園安全系統，電子圍籬導入 AI 人臉辨識技術，避免誤報干擾校園安全、校安監視系統無死角，全方位守護安全。","高齡社會：推動高齡前瞻運動中心，廣設高齡者在地運動教室、推動高齡健康產業，高齡者健康樂活 「肌」 不可失。","地區發展：發展士北在地精緻農業，結合當地溫泉與特色產業，舉辦手植季與在地學校管絃樂團音樂會結合行銷北投。","智慧城市：促進智慧城市發展，智慧燈桿功能 ALL IN ONE( 警政系統、照明、電動車充電、訊號基地全都包 )，免挖路輕鬆脫胎換骨成智慧城市。","文化保存：推動北投土地公文化融入在地生活、關注懸而未決不動明王寺廟修繕問題，促進在地文化與市民生活融合。","全民運動：廣設各區第二運動中心，提昇運動中心功能及優惠措施，培養市民運動習慣、減少健保支出，針對特定需求族群、提供專業運動指導，讓台北成為運動健康城市領頭羊。","競技運動：推動學校競技運動三級銜續，深化基層運動人才培育，厚實學校運動訓練器材及建設，因應專長項目增設專任運動教練。","兒童福利：規劃 0-6 歲兒童早療補助申請新辦法、並積極爭取 6-12 發展遲緩兒童早療補助，幫助弱勢兒童早療路上資源不中斷。","行的安全：加速汰換耐揚壓人孔蓋，雨季來臨不怕人孔蓋噴飛、爭取制定建築物公共空間地板防滑係數，民眾走路不滑跤。","資訊通暢：民眾運輸的便利與資訊暢通，盡速建置公車站牌站站有 WIFI，居民搭乘公車資訊不中斷。","地方民生：積極協調北投中繼市場停車場等問題，並繼續與市府、周邊里民共同找尋北投市場共存共榮遠景。","人文自然︰維護人文與自然平衡，保護關渡平原自然環境永存續，並與周邊人文平衡發展。","就業問題：宣導職涯評估及職場體驗，青年就業不徬徨、中高齡就業職能教育好便利，積極職缺媒合重入職場好 EASY。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b7c7b347-5b60-476f-af3f-92595039216a","items":["監督雲林科技工業區環保用地，對於未來所有申請設立之工廠，凡有污染空氣與水源之疑慮廠商，從嚴審查建照。","針對建築廢棄物，如住家裝修、廢磚頭、水泥、磁磚、馬桶等，應設置專用場地協助處理。","教育：補助生育不如補助養育，針對孩童課後輔導或上下課接送問題應提出相關辦法，避免父母因上下班時間或假期不同，而使父母蠟燭兩頭燒。","勞工：督促企業主領薪日遇到國定假日也應提前發放或當日發放。","農業：果樹枝修剪後應提供場地載運或協助破碎。","青年：針對返鄉創業或務農之青年，應放寬申請資格，鼓勵青年返鄉之意願。","寵物：設立合法寵物火葬場，讓飼主可為寵物莊嚴的善後，也可避免寵物屍體被隨意丟棄。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b7f86231-d449-4e82-bf41-8c000601a27e","items":["國會問政有方向 反詐：修法重罰詐騙，加強源頭控管 反戰：外交專業取代政治語言，志願役待遇全面升級 反特權：清算政府黑箱決策、施政訊息公開透明 宜居：支持囤房稅、租屋市場透明，落實居住正義 宜業：以核養綠，推動務實能源政策；爭取產專區享中央政策優惠 宜生活：政策鼓勵生育、捍衛勞工權益、增加長照資源","選區經營有願景 爭取預算增購機捷車廂、把關捷運棕線、捷運綠線進度、爭取國道客運與公車專案預算，全面升級大眾運輸，為人本交通打基礎 國一甲東段重啟討論、打通各區域瓶頸道路 溝通中央，都市計畫尊重地方意見、合理審查 活化閒置公有地，增設共融式公園、停車場、公車駐車站 大崗高中獨立設校、爭取選區各級中小學設校及擴建經費，解決爆班問題 反對國光、長生電廠擴建；要求煉油廠逐年轉型；南崁溪水質加強監測 檢討公寓大廈管理條例，輔導管理品質再升級 重啟「行政區劃程序法」議案，加強政府跨域治理能力"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b852c88a-d6d8-4f36-bd3d-1ef79b5328e3","items":["嚴格把關政府預算編列及執行","爭取社區高齡友善軟硬體服務配套","要求縣府發展主題觀光振興秋冬旅遊市場","爭取幼兒照顧及青年創業補助"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b8979149-f30b-4af8-b443-bc615bb0d0ba","items":["面臨百業蕭條的經濟局勢，需要振興家鄉，我們就必須做多方面考量、找出原因、對症下藥，將聘請北斗區地方賢能士紳組成策略顧問團，一起為北斗區四鄉鎮的建設及福利認真打拼。","我將盡議員之責，審查監督縣府預算之職責，為大北斗地區之縣民爭取福利。","必需加強治安及消防設施，充分利用資源，使警消系統更加完備堅強。","督促縣府落實社會福利政策，保障婦女、兒童、老人、殘障朋友、勞工及弱勢族群之權益。","勸導鼓勵失學及待業的青少年，輔導他們學習第二專長，並依其專長、興趣，參與縣府合法登記之民間文化、藝陣等社團，改善青少年治安問題。","整合北斗區四鄉鎮地方特色、文化之美、花卉之都、美食街、農家特產品，結合奠安宮等廟宇，促進地方觀光事業均衡發展。","強化大北斗地區醫療網。","提昇國中（小）教育硬（軟）體建設，落實偏遠地方教育、減少城鄉差距。","維護及提倡鄉土文化之延續，使本土文化發揚光大。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b8a2a7ff-2d96-48c1-bdd8-33a947f77da4","items":["力促縣府推動地方創生、建構創業平台，提供青年優質創業環境。","打造居家照顧與照護平台，落實長照2.0，媒合長者長照需求，讓長者獲得專業照護，並讓子女安心就業。","爭取興建社會住宅，力挺青年成家，只租不賣。","打造安心學習環境，延續校園運動風氣，提供優秀選手更好的培育場域，建構安全城市網，推動教育均質化。","督促縣府於蘇澳鎮內廣設親子共融遊具與親子公園，打造蘇澳兒童樂土，讓父母無憂、長者無慮，增加消費市場。","積極爭取公立托老與臨時托育空間，廣設公共托育、公立幼兒園與臨時托育，解決父母育兒壓力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"b8b8051b-6aec-4659-ad91-306d68c442e7","items":["成立公民企業,由政府、企業及人民集資金門產業、發展經濟,落實人民共同富裕、壯有 所用。","善用轉型正義條例,軍管時期軍方不當取得土地,應全數返還人民、宗親會或金門縣政 府,實現土地正義。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"b902e3ee-7a9a-4cc7-b8b6-a9425641f0ce","items":["關懷老弱婦幼 爭取農民權益","爭取地方建設 提升居住品質","督促創造就業 鼓勵青年返鄉","關心食安衛生 加強環境保護","升級公共設施 確保民眾安全"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b95cad20-581e-43bc-b520-f7431648badf","items":["推動老舊市區都市更新，擴大老屋拉皮補助，整頓人行道，優化公園設施，活化閒置國有土地，提供市民更多元的休憩場所，建立美麗新桃園。","縮短交通黑暗期，推動共享經濟廣泛建構U-Bike2.0、U-moto及各型交通工具的分享，積極推動棕線、綠線捷運及鐵路地下化的興建，解決都市交通擁擠及空污問題。","加強天羅地網建置密度，減少治安死角，充實警力維護治安、交通，為市民的生活安全把關。","鼓勵生育，普設公共托嬰中心，爭取向下延伸義務教育一年，減輕家長育兒負擔。","廣設創業基地，服務青年朋友充分就業或創業，加強就業輔導，協助中高齡者重回職場。","推動桃園區特色觀光，一山 (虎頭山)、二水 (南崁溪、埤塘) 、三商圈 (站前商圈、藝文商圈、博愛路商圈) 、四個歷史建築 (忠烈祠、七七藝文町、桃園文學館及農會穀倉) ，打造桃園成為全國最好玩的城市。","催生桃園市立醫院成立，提升桃園醫療資源，加強食品藥物源頭及衛生管理，推動食安資訊透明化，為市民健康把關，加強建築物消防安檢，建立防災地圖，確保市民居住安全。","輔導社福機構健全發展，增設各種非營利組織，加速無障礙、輔具補助效率，照顧弱勢族群。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b98f9729-37f3-492d-927b-305832f455bc","items":["運動休閒遊憩：鄭文燦市長103年未完成政見，促新中福計畫（文中路旁）興建巨蛋，更將促打造森林公園或多元運動園區。","運動休閒遊憩：爭取並已通過，促於113年前完成龍安長青型國民運動中心。","運動休閒遊憩：連續七年多不斷建議中平路老舊市立游泳與緊鄰公有市三用地，應整合為國民運動中心，任內將完成。","運動休閒遊憩：持續七年多發聲爭取，中路地區泰昌、宏昌街之間5200餘坪〔公2公園〕2年內將全開發，並興闢地下公有停車場。","交通建設：區段徵收方能連通國際路與南平路，續促速向內政部提出計畫。","交通建設：促鐵路地下化全線明挖應早於台鐵局表訂時間119年完工期程，對交通衝擊最短。","交通建設：續促國道客運應落實監控，滾動式檢討與客運業者協商機動增加班次，更應研議路權延伸、增加路線。","社福與安全：保障婦幼，落實社會安全網。","社福與安全：護衛食安，續促加強稽查，肉品、蔬果、加工食品進口、產地、履歷標示，每月稽查成效公告於官網。","社福與安全：老舊公寓大樓電梯維修、汰換補助，爭取設立專責專款協助處理；倘急迫性基金經費不足，准予分期攤還。","社福與安全：依上班族動線、生活機能持續增設親子館、公托、老人日照中心、關懷據點。","社福與安全：率先質詢嚴批噪音改裝汽機車獲重視後，陸續已有10組「移動式聲音照相設備」投入執行科技執法，將再促增加。","社福與安全：敬老卡爭取增加至1000點，台鐵將整合系統，督促任內可搭乘鐵路及用於公立醫院看診自費。","社福與安全：持續關注復康、長照巴士量能、服務品質。","教育文化：國民小學廣設美語村、加速國中小班班有冷氣、爭取增加投入互動智慧教學軟硬體設施。","教育文化：圖書總館及分館持續充實多元藏書。","都市發展：舊城區、後站持續催化助燃民間推動都市更新，以寬化路幅便於停車、友善人行。","都市發展：保障權利為前提，輔導補助夜市、傳統市場現代化以吸引商機。","都市發展：因應大樓發展，促添購子母車，以效率收取社區垃圾；小型子母車深入社區處理分類後之垃圾、廚餘。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"b9bdd0ec-0c7a-4f98-b076-f6593d3959f6","items":["依竹山、鹿谷的產業特色,結合觀光、文創、農特產等打造休閒旅遊美麗山城。","爭取中央資源,協助地方改善水利灌溉設施河岸堤防、農路,讓農民有完善的灌溉系統,安全平順的生產運輸農路,保障生命財產安全","極力爭取偏鄉無自來水區,自來水延管工程,提升鄉親生活品質","全力推動竹山防空壕作戰指揮所暨日本時期宿舍群為「竹山町昭和村文化藝術園區」帶動竹山、鹿谷地區觀光、經濟發展","全力推動木屐寮生態園區設置「水環境調蓄水源功能暨親子生態戲水池」創造觀光產質,帶動地方繁榮"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ba230df2-871b-45f4-b9ad-5744c543c192","items":["福老喜幼老中青幼就學順心、托老放心、就業更安心推動一國中學區一日照提升公托涵率建立照護體系安心獨老社區共好","便捷好運-動電線地下化,現路平計畫,改善交通瓶頸,重視機車路權,推行人本交通。捷運藍線服務至歸仁、關廟市中心 仁德鐵路立體化 台86高架銜接國3延伸至內門","處處有趣-重視兒童遊戲權,重德游泳池,再造都會公園遊戲場,找回屬於孩子的彩虹。台86線橋下空間全面活化 一里一公園 一區一共融遊戲場 新豐區國民運動中心","經濟先鋒-持續推動經濟動能建設,老工業區造,提升沙智慧綠能科學城效益。仁德轉運站升級物流金融行銷中心 沙崙綠能產業專區 創新醫療健康產業鏈","新豐好水-治水、水、親水、利水,到河、到側溝,整體水域環境整治。三爺溪與二仁溪整體水域整治 提升汙水管線接管率 關廟大潭埤環境營造","人寵均安-推動遊蕩犬問題解方,提升並活化收容園區,找回生態合存。寵物強制險政策 乾淨安全餵養制度 保護生態推動綠鬣蜥清零計畫"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ba844082-78ea-48e7-a2cb-dd6a1dc53d15","items":["銀髮族照護，樂活人生：增設長輩日照中心，提供優質的長期照護系統，減輕家庭照顧負擔。增加社區長青學苑、社區關懷據點。","拚下一代幸福、挺教育：增加生育及育兒津貼、公立托嬰中心、公立幼稚園。老舊校園重建及設備升級。校園雙機。數位雙語教育。","拚青年希望：爭取就學貸款零利息，減輕學子負擔。重視技職教育。推動興建社會住宅，優先出租給弱勢、青年，實現居住正義。","愛運動愛閱讀：培植體育人才，爭取國際運動賽事舉辦、推廣各類運動及電競。持續活化政府閒置空間，規劃市民運動場域，爭取各區及旗津運動場、農16圖書館、微型創意閱讀空間。","幸福高雄，打造鼓山、鹽埕、旗津優質居住環境：監督政府全面優化防洪排水系統、檢視路平、完善高雄大眾運輸系統建設。爭取老舊大樓整修與安全維護補助。捍衛旗津居民免費搭船權益，爭取旗津第二條過港隧道結合大眾運輸。","創造優質藝文、親子環境，挺藝術、文化、流行、音樂產業深耕高雄：推動高美館、海洋流行音樂文化中心、駁二、哈瑪星、鹽埕、旗津海岸公園等辦理各項藝文、親子、流行、音樂、藝術表演、創意市集。","捍衛勞工權益、提高薪資、重視職場安全。挺新住民權益。性別平等。","嚴格監督政府、捍衛市民權益。打擊空污、重視環境保護、捍衛食品安全。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"bae6fa06-1cbf-4e01-80a4-7a5ec00b3539","items":["嚴格審查市府預算，確實監督施政成效；秉持家婆認真精神，爭取市民福祉。","賡續建設佳里區第二聯合活動中心、七股區三股活動中心，將軍區扇形鹽田觀景台、舊馬沙溝漁港再造，學甲區糖鐵綠美化往山寮延續，擴寬七股區176線往雷達站及西港往南科保西橋道路等工程。","極力爭取大北門藝文中心在佳里，新建七股區大寮景觀公園、內含室內體育館室，新建西港綠川廊道第五期綠美化；厚植民眾文化涵養，完善青少年活動空間，提升市民休閒品質。","整體規劃大北門區域發展，儘速啟動七股工業區，強化佳里、西港、學甲工業區基礎建設，增加就業機會、促進經濟發展。","照顧勞工權益，新建社會住宅，增加幼兒津貼，提高租屋補助；以減輕年輕人負擔，厚植國家生產力及競爭力。","落實社福政策，加強長照2.0服務網；輔導新住民就養，關懷高風險家庭及弱勢族群；推行偏鄉醫療服務，照顧銀髮族群就醫就養。","完善保母及托育品質，改善學校設施及教育設備；加速偏鄉小校轉型整合，落實資源分享。","消防、警政員額編制確實，充實救災設備，完整教育訓練，確保人員安全；嚴格取締毒品、槍枝，保障人民生命財產安全。","重視農漁牧業基礎建設，推動年輕族群返鄉參與；建立相關產品產銷平台，輔導自主產品開發、販售，增加農漁牧業收益。","支持低碳永續之生活理念，綠色環保愛地球；強化區域排水系統，建置抽水站，溝渠定期整治疏通。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bb023245-9d9e-4db4-afb2-4623bde82f1f","items":["為減少空氣汙染顧及民眾健康，全面推動沿海地區進行植被綠化工作。","督促台塑六輕廠內生產線及石化管線應定期檢測保養，確保地方民眾的安全，做好汙染防制措施。","督促政府設置長照機構，落實年長者照顧工作。","督促縣政府早日實施雙語教育，提升學生外語能力。","督促縣政府向中央爭取經費，整治沿海魚塭、堤岸，以提高養殖收入。","為提高農民收成，督促縣府全面整修農水路，減少作物災害損失。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bb485175-3582-4afb-8b35-33ea4239966f","items":["監督縣府預算及執行效能","督促縣府關懷婦幼安全及權益、弱勢族群照護、銀髮族身心保健。","全力支持警政消防預算，以保障社區鄰里的治安與婦幼安全。","督促改造公共空間，爭取閒置土地栽植花木，營造宜居城市。","督促政府對於弱勢家庭的實質給予補助。","積極推動發展在地特色產業、文化慶典、觀光景點，凝聚在地鄉親的力量，發展特色觀光產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bb4eeaa3-33e7-44f3-9485-f09a24a68f75","items":["爭取原住民族傳統競技、體育發展、培育原住民運動專業人才預算經費提昇。","督促政府活化原鄉學校閒置空間，積極發展老幼共學環境。","督促政府扶植原住民各項產業、強化原住民各項職業訓練，打造屬於花蓮縣原住民族文化創意產業，以改善原住民經濟，提升就業機會。","加速推動設立「原住民流行音樂基地」，透過音樂活動爭取文創產業能見度，吸引流行音樂產業匯聚，打造花蓮縣成為太平洋左岸音樂重鎮。","支持原鄉回流青年，督促政府培植輔導跨部落原住民族青農或創農企業，推動跨部落休閒農業連結。","協助原鄉爭取交通基礎建設經費，逐步改善各部落農路及主要聯絡道路，以維護鄉親生命財產安全。","督促縣府加強原鄉醫療服務，強化老人照護並落實急難救助等社會福利。","督促政府落實「一部落一聚會所」，促成各部落聚會所工程如期如質完工，以提供部落族人優質的生活休憩與歲時祭儀活動空間。","督促政府推動與建構完善之民族教育政策，提升族語文化的地位。","推展原住民技職教育，輔導取得各職類技能證照，爭取企業民間等實習實戰經驗以利未來求職及創業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bb74b63a-4f5f-4c65-b562-6042d581fcda","items":["監督要求政府公開、透明作業泰山楓江地區都市計畫，爭取優化地方發展、協助地主及居民爭取權益保障。","爭取五股區夏綠地(垃圾山)開放二次申請，輔導尚未申請之地主依政府規定申請合法使用。","解決五股交流道及林口交流道壅塞問題，需以疏通分流為之。","爭取增設台65線銜接北上高速公路。","增設高速公路不下五股直接高架接台64線至台北港。","增設泰山交流道，分流泰山民眾車輛從泰林路三段接至林口(中山路、中正路、仁愛路)僅需7分鐘到達，分流林口交流道車輛。","建請縮小林口保護區範圍，予以適當開放，並加強修繕連貫各保護區內之休閒登山步道。","監督塭仔圳都市計畫重劃區加速完成： 1.鄉長任內爭取增設之機場捷運線A5a站興建使用。","加速貴子坑溪大排親水廊道計畫，打造\"新北清溪川\"銜接\"泰山塭仔圳萬坪公園\"。","監督加速完成區內汙水下水道工程，使雨水及汙水系統分離。爭取完成大窠坑溪生態復育及河川整治，再爭取第二期改造工程至 山腳公園接至黎明公園，全長約1.5公里的休閒步道。","強力爭取學區劃分(學校興建)合乎比例原則，讓孩童可以在地就學，不用再舟車勞頓、跨區就讀。","全面解決停車位不足問題，爭取新建立體停車場，並且有效利用公共建設空間，將地下停車場與公共建設結合，活化空間使用。","推動校園培養五育均衡發展(體育、技能語言等)，符合現行108課綱發展，\"實施有效教學，達成適性揚才\"。","友善城市計畫，爭取兒童福祉及教育、關懷長者及身心障礙者權益、重視新住民權益橋樑搭建、多元性別平等空間使用、寵物友善建設爭取。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["web_promotion"]}}},{"claim_id":"bbaf80f9-1a4b-47b1-903a-477e8c7764ec","items":["監督市政府施政品質與執行進度","加速世賢路以西北港路區段徵收","爭取經費開闢八米道路","爭取電纜地下化，重現美麗城市天際線","提升公園環境品質，建設特色共融式遊具，打造全齡共享之公園","爭取嘉義高鐵站聯外軌道系統，提升交通便利性","爭取婦女福利政策，廣設公共托育，提升育嬰津貼","督促設立總圖書館，以推廣閱讀風氣","監督國中小營養午餐食材品質，確保嘉義校園零萊豬","監督汙水下水道施工，打造魅力親水城市","中央排水溝治整工作，提升市民生活品質","爭取身心障礙者福利、老人福利，廣設關懷據點","爭取設立低汙染科學園區，鼓勵青年返鄉就業","發展觀光業，促進經濟發展","提升自行車友善環境，健全自行車用路系統","監督社會住宅設立，實現居住正義","監督西區全民運動館興建","督促市政府於公36興建嘉菸文化園區，提升城市美學"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bbe1ecad-12c5-4cca-87aa-177335335af7","items":["增設市區停車位，推廣智慧停車APP。","爭取更換LED路燈，加速建置智慧感應系統，讓「夜晚回家的路明亮安全」。","獎勵文創及微型企業，打造在地文化，振興在地經濟。","結合菸廠、縣民公園、屏東總圖、孔廟、勝利星村及遺構公園等景點，打造屏東市觀光新廊道。","持續推動電線、電纜全面地下化，淨化市區天空景觀。","爭取公園及校園的兒童遊具逐步汰換為共融式遊具。","爭取打造寵物友善公園讓毛小孩有專屬的友善遊戲空間。","推動社區「全人服務學習中心」，讓幼青壯老、互相照顧扶持。","爭取設立新住民服務中心，提供法律、福利、就業等協助。","監督路平、路面挖掘及管線管理，提升道路工程技術標準。","提高空屋稅及囤房稅率，抑制非自住的投資炒作，讓房價合理化。","空屋稅及囤房稅及公家土地釋出的收益，應提撥成立青年購屋補貼基金。","爭取興建智慧型社會住宅，鼓勵青銀共居，打造特色公宅。","保障勞工權益，增加勞動檢查次數，提高工作場域安全檢驗標準。","爭取提高社會福利預算，提高對弱勢家庭的照護品質。","爭取補助中小學生營養午餐費，並採用在地食材，一週一日有機蔬菜。","改善空污，強化「源頭管理」，落實檢測。並爭取建置空氣及水品質檢測儀器。","落實沼氣發電及沼液沼渣回歸農田的政策，改善畜牧場糞尿的氣味。","全面提升育兒及托嬰各項補助金額，落實改善青年家庭各項生育負擔。","爭取補足警察消防員額，加班費核實支付，讓警消無後顧之憂。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"bbed76a0-8164-4fc3-9933-0a1b3f48ca16","items":["在地成長台美雙律師，國際律所專業歷練，期許自己為市民的律師，為您伸張正義、爭取權益。","清廉參政，追求市民未來共同的想望與願景、更乾淨清新的政治。","推動親子設施、增加幼托照顧，讓青年返鄉成家定居。","打造樂齡生活圈、友善高齡公共設施及服務，讓長者行的安全、活的多采。","活化運用本區豐富的文藝、運動、教育、宗教文化，推動市民參與，融入公共建設。","針對商圈短中長期需求逐項推動，結合在地情感記憶亮點，讓商圈各有特色、再生活躍、永續不熄。","加速推動危老重建、都市更新，再現本區新風華。","引進商機，結合國際商業思維，增加就業機會，留住在地人才。","盤點閒置空間、改造活化為多元活動中心，興建社會住宅、推動高雄成為安居城市。 挺邁，拚一席女性、青年、專業的關鍵新力量。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bc2da4e9-4934-4e62-b435-84f756c0cf55","items":["清除米蟲 專業議會-改革選制,直點金權政治死穴!競選不得花錢,僅限公辦政見辯論;議員要準時開會、收支和出國考察透明化;議員助理工作專職化、透明化。","平價社宅 安心居住-人人住得起,人人有屋住!社宅租金不得超過家戶收入的三分之一;兒家庭優先入住;盤點鄉間軌道運輸沿線公有空屋。","老人照護多管齊下-獨立老不要孤獨老!整合並開發銀髮學習互助資源;推動社區醫療聯絡簿、區域行動醫療;盤點閒資源,推動老年日照和幼童托共享院所。","人本交通 行走暢通-走路是基本人權!整頓人行道騎樓、落實執法;汽機車不分流,降低肇事率;交通號誌標線總體檢","文化城市 在地認同-以文化凝聚城市認同!歷史記憶再現於城市空間,規劃人權遺址路線;搶救母語全面復振,推動一區一全母語國小。","寵物友善 城市親水-重視生命,生活升級!推動一區一寵物友善公園;老舊市場整建轉型;打開可能之水域空間,例如德慶溪、柴頭港溪。","落實0-6歲政府養-翻轉台南連續六年「生不如死」!建公共坐子服務;增設公托,公幼增加課後和寒暑假照顧;設立嬰幼兒物資交流站讓產後照顧、養育和親子遊憩公共化。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"bc394785-6516-4b46-ae0e-052bd24eaa36","items":["新北翻新：繼續推動兒童醫院在新北；重視早期治療，孩子健康不能等","新北翻新：加速都更危老城市翻新；興建青年社會住宅，實現居住正義","新北翻新：打造人本交通城市；提升行人、自行車與機車用路權","新北翻新：增設公托公幼與非營利幼兒園，減輕家長養育負擔","新北翻新：免費裝假牙、提升敬老卡福利；整合長照資源，協助子女照顧長者","新北翻新：充實警消、清潔隊勤務裝備，工作更有力","新北翻新：打造動物友善城市；完善法規，打擊不法，讓浪浪安居","板橋翻轉：繼續推動新北軌道建設；完成泰板及社後輕軌規畫","板橋翻轉：加速浮洲都市計畫更新；妥善安置在地產業","板橋翻轉：持續興建地下停車場，規劃新停車空間，道路不再壅塞","板橋翻轉：興建板橋第二運動中心、簡易足球場，讓市民快樂運動","板橋翻轉：增設兒童特色遊戲場，充實公園休憩設施，打造新樂園","板橋翻轉：增設微笑單車站點，打造自行車路廊，推廣綠色運具","板橋翻轉：加速電桿地下化，清除廢棄纜線，重現乾淨天空","板橋翻轉：支持建設活化藝文場館，保存推廣古蹟歷史建築，促進文化發展","板橋翻轉：結合觀光、商圈再造，繁榮老城區，再現榮光。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"bcb97e8e-11ae-4879-8c88-129077d9335b","items":["關心西區的建設與未來發展；督促改善區域交通及路面的整平。","持續關心大鵬新城地下室漏水整修事宜，務求如期如質完成；並建議重建凌雲公園。","建議市府積極改善曲溪里居民生活環境；及加強與新竹縣政府的溝通平台，逐步解決縣有土地問題。","公道三開通後衍生的問題，如延平路二邊的標線、紅綠燈設置等，一定要重視住戶反應，妥善處理。","爭取開放「靖廬」作為公園使用，讓曲溪里和附近民眾增加一個休閒、運動去處。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bce09751-57bd-4b91-a8e1-a3c38c9b8ccb","items":["縣議員補助款有基礎建設補助、設備補助、活動補助三種，我將以公開透明的方式，每個月公佈補助用途、金額。","監督縣政府，來自中央的統籌分配款必須按春日鄉的分配公式，全數撥入原鄉鄉公所。","監督縣政府，來自中央的計畫型補助經費應按計畫目的撥入原鄉鄉公所執行，不得挪為縣政府煙火活動用途。","屏東縣求職不易、人口流失，原鄉尤其嚴重。要求縣政府「勞動暨青年發展處」提出促進就業方案，並每個月公佈就業績效。","屏東原鄉多為小農旱作，銷售不易。要求縣政府「農業處」提出原鄉農產品促銷方案，並每個月公佈促銷績效。","媒合社會慈善團體，針對原鄉老弱病殘進行長期扶助專案。","與立法委員高金素梅成立聯合服務處，從中央到地方，聯手監督政府，聯手服務鄉民。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bd42dbfd-789f-4070-978f-46f9cf828afa","items":["爭取政府預算，補助壯圍鄉內各級學校數位學習設備，提升線上數位學習效能；爭取雙語情境教室，擴大辦理雙語課後輔導；加強推動各項體育競賽活動，促進學子學業與體育健全發展。","督促政府落實年長者照顧及幼兒托育福利，滿足壯圍鄉長期照護及幼兒托育需求。","爭取政府推動壯圍地方創生計畫，結合東北角旅遊服務園區觀光圈，提供青年創業、就業機會，吸引人口回流，打造宜居壯圍。","要求政府重視並改善沿海海岸侵蝕問題；加強壯圍旅遊服務園區及其周邊至東港榕樹下遊憩區的建設，持續辦理壯圍沙丘地景藝術節，帶動壯圍鄉觀光產業發展。","督促政府如期如質完成廍後抽水站、壯東第一大排抽水站、後埤抽水站工程，持續改善鄉內排水問題。","爭取政府經費改善本鄉農水路，以利鄉民從事農作及交通往來。","爭取政府補助壯圍鄉農產品，推廣產品特色並輔導培育技術，提升農產品品質及競爭力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bd4f2803-ca58-4ca2-ab3e-96aa9de808fc","items":["落實原住民族基本法維護原住民傳統領域及原住民保留地，爭取回復邵族原住民 應獲得保障的固有傳統土地資源、居住生活及文化產業經濟發展等權利。","全職為民服務，爭取地方建設，加強農業、觀光休閒及工商業發展，提升縣民生 活水準、就業機會及收入。","持續關懷協助落實弱勢老弱婦孺福利措施，爭取更完善保障中低收入戶、老人、 身心障礙及單親家庭等弱勢族群權益的政策。","繼續為提升都會區原住民生活、居住、工作、就學、就醫與文化傳承發展權益， 加強向政府爭取更多立即可行的措施方案。","落實每年舉辦都會區與原鄉平地原住民歲時祭典文化等常態性活動。","全力爭取興建「南投縣都會區原住民文化活動聚會所」。","服務不分區域，照顧不分族群，以南投縣原住民族群需求與權益為優先。","落實保障原住民族政治文化、經濟社福與教育權，堅持土地資源環境與居住正義， 促進地方均衡永續發展及族群和諧共榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bd708886-98b1-4601-a49c-21bbe865c4c4","items":["建請縣府成立外來投資聯合局處小組，可加速審核速度，提高投資意願。","針對秀姑巒溪流域研議強化泛舟活動及任何可行的水上遊憩行為，並增設親水公園等空間。","重視南區觀光及農業産業，研議多時節經年常態性之中大型活動來為南區帶入更多的人潮及就業機會，增進活絡在地產業。","加速瑞穗溫泉區開發計劃，檢討特定農業區地目之存廢，讓瑞穗溫泉區能夠有實質之發展。","優化或建置南區公共運輸系統，推行銀髮就醫固定班次接駁往返，讓長輩就醫無憂。","以南區四鄉鎮為主軸結合各區農特產品，邀請各大銷售通路做規劃配合，讓農民不再為銷售煩惱，共創雙赢。"],"content_split":{"method":"manually_reviewed_platform_items","version":"election-content-items-v1","confidence":100,"reviewStatus":"auto_approved"}},{"claim_id":"bd77a11e-97f1-4114-adb6-a5f6fa5a6d2f","items":["監督縣政，為民喉舌。","配合地方需求，向上級爭取經費。","督促對老人照顧、弱勢團體、婦幼社會福利政策的落實。","爭取改善農業生產環境，提高農民收益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"bdda0412-4002-4312-9832-46b8eb5fbaac","items":["打造科技發展重鎮 串連嘉科南科爭取新營設立都市型科學園區納入南部科學發展S型廊帶。","積極發展交通建設 持續爭取新營火車站前後站周遭倉庫土地活化/新營交流道增設匝道，重塑新營東西向聯外交通，找回臺南門面的驕傲。","加強社會福利關懷 爭取65歲以上長者免健保費/鑽石婚慰問金，減輕青年照顧家中長輩的負擔。","保存珍貴文化遺產 爭取鹽水月津港景觀橋重新打造，讓昔日媽祖入港民俗再現。","關注基本民生議題 持續爭取東山白河山區自來水供給普及。","文創結合農業產業 挹注文創量能活化白河蓮花節及蓮花產業，打造白河農業品牌。","再創臺南蘭花驕傲 後壁蘭花園區今年開始由中央接管，未來爭取園區及活動內容升級，打造國家級蘭花產業專區。","打造親水水域空間 臺南擁有非常豐富的水域資源應多加利用，未來持續爭取柳營德元埤荷蘭村、新營天鵝湖、鹽水月津港，增加水域活動，打造親水安全空間。","持續爭取活化糖廠 新營糖廠位居新營中心地帶，長期閒置對於新營地區發展造成阻礙，未來也會持續爭取糖廠活化，帶動溪北整體發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"be085316-aac3-404d-83f2-5bbd550db7e4","items":["水岸生活：建構太平溪兩岸的水岸生活，督促縣府重視大豐地區之發展與生活品質。","運動生活：發展快樂運動城市，特別要發展活水湖並推動縣立室內溫水游泳池。","動物生活：推動台東成為動物友善縣，並提高對於浪浪的相關經費。","美學生活：推動主題公園並且鼓勵設立小型博物館美術館進而形成群聚。","住宅煩惱：督促縣府提供更多的租或售公宅。","托育煩惱：增加公共托育量來解決父母的困擾。","停車煩惱：盤點公私有土地來提供市區停車共用。","婦女煩惱：針對單親與職業婦女以及外籍配偶提供更多協助。","看見經濟：農業與觀光並重，完整監督縣府的農業與觀光政策。","看見青年：推動縣府成立青年事務發展委員會。","監督清新：力拚議會成立黨團以利監督。","行政清新：協助做好民眾與公務部門的溝通橋樑。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"be314023-bc20-4745-96ca-e172930acd60","items":["能源國安・產業根基 國艦國造、國機國造、國氣國運，打造高雄海洋國際運籌中心。","智慧科技・農業升級 擴大農民保險、導入AI科技、冷鏈技術，增加農漁民收入。 建構科技廊帶，推動中小企業自動化、智慧化，產業升級強化競爭力。","順暢交通・建設繼續 持續推動捷運林園線、捷運黃線、國道七號、高屏第二快速道路。 持續爭取全區防洪治水、造橋鋪路經費，保障居民安全。","百年大計・首重教育 接軌世界、放眼國際，持續推動「校校有外師」雙語教育。 校園升級、強化教育，持續爭取校園軟硬體建設經費。 持續媒合產學合作，培養下一代競爭力。 持續爭取生育津貼、孕婦津貼、托育補助，打造友善育兒環境。 宜居城市、親子共融，爭取特色公園、共融式遊具。 擴大推行老幼共園兼顧長照幼教。 強化動物保護，持續推動友善動物環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"be6056ff-3f46-43c4-8266-af3afa076843","items":["爭取苗119線銅鑼至三義儘速拓寬。","爭取西湖鄉河堤共構至銅鑼段加速完成。","爭取台13線銅鑼至三義高架橋拓寬完成。","爭取三義外環道儘速興建完成。","爭取縣政府寬列預算增加補助弱勢家庭。","爭取縣政府寬列預算增加長照服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"befe9d96-0943-486a-901c-ae826d36d0ab","items":["重視鳳山溪北建設，要求溪南溪北均衡建設，AI親子公園，國民綜合運動中心，埤塘步 道休閒推展。","湖口人文氣息的尊重，中大型藝文中心需求爭取。","檢討公車行駛問題，解決偏村交通，爭取湖口環狀公車。","農業精緻化，科技化打造湖口宜居綠城鎮。","監督嫌惡設施，嚴審縣政不當施政。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bf70b46f-aa5d-4f96-ad5a-8cb996900850","items":["監督縣政工作落實，財政用到最適當。","督促縣政加強經濟發展、創造就業機會、帶動年輕人返鄉工作。","落實長照制度、加強對年長者生活照顧。","加強有計劃性精緻農業、照顧農民、提高農民收入。","加強排水功能、應付氣候異常天氣以利人民居家安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bfbc43ab-5010-4d71-9bb6-35777c8894c4","items":["爭取永康區正南三路高架化﹐從康橋大道平交道為起點往北銜接台一線與鹽水溪北外環道﹐徹底解決鹽行地區的交通讓要上高速公路的車子更順暢。","大灣交流道改善案﹐北上引道往北延伸能容納更多北上車流﹐才不會回堵在交流道口。","次10-5號15米計畫道路從國光五街往高速公路便道已要開闢了﹐應打通往復華三街更能產生更大的效益，以減輕大灣交流道流量。","爭取大型羽毛球場館，以利舉辦大型比賽(場地至少10面以上)，因羽球已是全民運動了。","督促市府社會住宅目標數量務必達標﹐以利無殼蝸牛的居住正義並普級化。","全市警力分配率，應重新檢討，配備更新，以降低人民受害，提高社會安定，百姓安居樂業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"bfd69eb3-5753-4e0c-b24a-2aaca0c078a0","items":["落實國中小情感教育，推動全市超過三十所學校參與及教案補助，培養孩子情緒智能，社會問題從根本解決。","顧民生：擴大敬老卡使用項目：成功開放運動中心使用，未來持續爭取擴大至西醫、中醫保健，增加臨時托老據點。","健全租屋市場：監督「租賃住宅市場展及管理條例」執行，保障房客方權益。","強化青年政策，創造友善職場, 勞動權：加速推動公宅：積極強化新創及微政策。","爭取新創中心：監督市府於北投士林科技園區之開發，爭取功能最完善之新創中心，增加地方經濟動能及降低青年負擔，創造青年就業機會。","強化雙語教育，協助多所學校推進雙語時程，監督市府擴充國小雙語教育、外語師資及環境，提升下一代國際競爭力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"bfee0c02-8db3-4d9e-9915-4bcc44ef56e3","items":["加強縣內防災救難人員組織培訓：1. 提高保險額度保障加倍；","強化社區互動與聯結，設置社區福利餐廳與課輔教室。","加強青少年戶外體適能活動，補助設施及經費，爭取運動場地，以強健體魄。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":8,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"bff4c3d2-6b36-455a-8915-c89ad4171b55","items":["積極推動原住民族部落文化傳承及教育 ,改善部落整體建設 ,創造部落新風貌。","推廣部落農產品、手工藝品、繪畫、特色美食等 ,提升部落產業能見度 ,促進地方經濟發展。","強化長照服務系統,增進文化健康站安全設施,提高照服員服務品質,建造老人友善環境。","爭取興建大型多功能體育館及修復部落集會所設施經費,推動安全運動及舒適集會空間。","辦理各項體育、技藝活動,加強培訓、獎勵原民優秀體育、技藝人才及扶助養成教育。","維護與爭取軍、公、教及士農工商各行業從業族人之權利。","關注與監督國土計畫原住民族土地之重整及規劃 ,確保族人權益,並保護傳統領域。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c024ca36-5f3a-47cf-b61c-f85c1170e593","items":["強化「0-6歲國家一起養」政策，爭取普設公托公幼，提高生育及托育補助，減輕年輕家庭育兒負擔。","國中小營養午餐免費、減少流浪教師數額、提供代理教師完整聘期、落實特教生就學權益，降低師生比，保障師資。","爭取65歲以上老人健保全額補助，並推動老人看病公車。","重陽敬老金應比照其他五都提高至一千五百元，並依年齡累進增加。","因應通膨驚人房物價高漲，中低收入戶審議標準應適當調整以落實照顧弱勢之宗旨！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c054dfbc-383f-4941-8fe2-43d4ffb2033e","items":["監督縣政。","爭取地方建設經費、促進地方繁榮縮短城鄉差距。","促進竹山、鹿谷地區茶農、筍農產銷權益。","爭取免費國中小學童營養午餐繼續辦理。","爭取國中小學童學雜費減免。","關懷獨居老人、照顧弱勢團體。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c06ae890-97d0-40cd-a46f-e456c16bb85f","items":["加快都市更新 改善居住品質","提升行政效率與執行力，包括簡化及整併審議程序、加速審議效能，並積極由公家單位輔導執行相關案件成案。","落實公正的協商機制，政府從被動轉為主動，擔任住戶與建商的橋樑，建立市民對都更程序的信任與信心。","全盤檢討都市計畫書及容積制度，將重點發展區域、公共交通走廊、區域性公共設施、公益回饋及房屋市場共同整併研議。 落實道路安全 減少事故傷亡","推動「Vision Zero」（零傷亡願景），建構對行人更友善的用路環境，並以標線改造降低交通事故風險與傷亡。","透過大數據分析及更多智慧號誌系統的設置，紓解台北市塞車路段，還給台北市民更安全與便利的交通環境。 提升英語教育 強化國際競爭力","提升各校的英語教學能量與應用英語環境，培養更多國際人才，建立一座更有國際競爭力的台北市。","聯合地方與中央，共同解決英語教學在軟硬體設施及師資上所遇到的問題，確保每個學校皆享有優質教學環境。 推動國際合作 與民主世界同行","強化各項城市交流並積極締結姊妹市關係，與民主夥伴國建立更多在經貿、教育、文化及學術等方面的交流。","號召更多國際企業、NGO 及其他組織來台北市設立辦公室並舉辦活動，創造商機並提升台北國際形象。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c1008595-986a-44be-822f-cf5431e05140","items":["嚴格監督縣政、爭取縣民權益及福利。","持續推動全縣觀光產業、以利帶動台東經濟活絡方案。","強力推動爭取弱勢族群及低收入戶最高福利。","苦民所苦謂為天職、當仁不讓為民謀福利最為優先。 建智出生於貧困家庭最懂縣民的需要、真摯、誠心、保證用服務回報鄉親"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c129f52d-e1cb-4971-a26b-a372efbbdeae","items":["民主和平，維持現狀：以「中華民國台灣」團結台灣社會，以「四個堅持」維持現狀：堅持自由民主的憲政體制、堅持中華民國與中華人民共和國互不隸屬、堅持主權不容侵犯併吞，以及堅持中華民國台灣的前途必須遵循全體台灣人民的意志。","四大支柱，追求和平：提升嚇阻防衛能力、強化經濟韌性及確保供應鏈安全、與全世界民主國家建立夥伴關係，以及維持務實、一致的兩岸政策，以具體且負責任的行動向全世界展現台灣致力維持現狀、追求台海和平的決心。","人民作主，開放政府：組成公開透明的政府，讓全民都能參與並監督政府施政，積極贏得人民對政府的信任；落實民主大聯盟的精神，跨黨派、跨世代、跨領域為國舉才，用人不分黨派，持續推動國家的進步與繁榮。","均衡台灣，在地希望：深化地方自治，建立區域治理平台，均衡區域發展；建構以人為本、智慧安全的交通系統；推動地方創生，創造多元就業，吸引人才回流；完善農民福利體系，確保糧食安全，提高農民收入，促進農村再生；推動觀光立國，將台灣打造成國際旅遊品牌。","0-22，投資未來世代：推動「0-6歲國家一起養2.0」，擴大公共化及準公共化托育量能，增加補助減輕家長負擔，實施彈性的育嬰假，全面落實高中職免學費，挹注資源提升特教品質，補助私立大專院校學生3.5萬/年學雜費，公立大專院校弱勢助學最高達2萬/年，投資高教品質、教研及國際化，設立百億海外圓夢基金，擴大投資技職教育。","健康台灣，樂齡社會：推動「長照3.0」，擴大長照服務涵蓋率，增加重度失能者的住宿式服務機構量能，提升相關補助至每月最高1.5萬元，改善巴氏量表，建立多元標準，對家庭照顧者提供喘息服務，並鼓勵企業提供彈性工作安排；通過「健康憲章」，提升醫事及護理人員的待遇及勞動環境，支持三班護病比入法，設立「百億癌症新藥基金」，優化兒少醫療，擴大「年輕族群心理健康支持方案」，擴大全責照護制度，確保健保永續經營；成立「體育暨運動發展部」，預算提升至200億元，推展全民運動，完善競技選手及專業人才培育發展。","創新經濟，智慧國家：以投資人才、產業創新、科技創新、金融創新及創新創業，帶動經濟的創新驅動成長；鞏固高科技優勢，發展半導體、人工智慧、軍工、安控及通訊「五大信賴產業」，持續推動加入CPTPP、IPEF等區域經濟合作機制；促進AI產業化、產業AI化；以社會需求帶動數位轉型，強化提供數位公共福祉，推動台灣成為數位民主的新典範；鼓勵金融創新，兼顧金融監理與發展；協助中小微、服務業及傳統產業發展，實現包容成長，並化氣候挑戰為契機，追求綠色成長。","文化永續，世界台灣：提高文化預算，推動「再造歷史現場2.0」並強化文資保存；推動「重建台灣藝術史2.0」，發展藝術產業，續推16-22歲青年文化幣；成立「國家語言研究發展中心」，提出博物館政策白皮書，推動在地藝文創生，強化藝文工作者權益保障；壯大文化傳播及「台流經濟」，行銷國際，未來十年帶動至少千億投資。","淨零轉型，永續台灣：發展多元綠能，推動深度節能、科技儲能及智慧電網，確保供電穩定與電力去碳化；透過科技研發、金融支持與碳定價，推動產業的數位與綠色雙軸轉型，促進綠色製造與循環經濟；建立專業團隊提供廠商諮詢服務，並定期公布因應指引；確保不同個人、社群及地區的公正轉型。","公義社會，溫暖台灣：推動「囤房稅2.0」，至2032年累計達成興辦25萬戶社會住宅、25萬戶包租代管、50萬戶租金補貼，以協助百萬租屋家戶，並增加青年安心成家貸款額度與利息補貼；強化弱勢兒少的就學、交通、營養及健康等協助；提升高齡者生活安全及弱勢保障，發展高齡產業；促進無障礙的環境與服務，擴大補助老舊公寓增設電梯或升降機；4年完成建置100處社區心理衛生中心；擴大社會安全網，調整中低收入認定標準，協助近貧家庭；堅定打擊黑金、槍、毒與詐騙。","尊嚴勞動，友善職場：持續調高基本工資，完成《最低工資法》立法，積極協助失業勞工再就業，強化非典型勞動權益保障；支持「雙就業、雙照顧」，建立性別友善及育兒友善的職場環境，縮減女性與男性勞工薪資差距，協助媒合中高齡及高齡者勞動參與，保障新住民就業零歧視；持續挹注勞保年金，支持勞保財務穩定。","尊重多元，社會平權：強化女性決策參與，促進女性身心健康與經濟安全；深化多元全齡的性平教育，落實性平措施；推動多元性別社會平權，增進同志家庭權益保障；提出「族群主流化政策綱領」，促進族群生活圈社會經濟發展，推動多元族群的文化產業發展，構築尊重多元族群的教育環境及公共空間，迎向多元共榮的民主共同體。"],"content_split":{"method":"official_numbered_lines","version":"presidential-platform-items-v1","confidence":100,"reviewStatus":"auto_approved"}},{"claim_id":"c25d40b6-1cbe-4d4a-bfbf-dfd8669a1588","items":["督促成立友善育兒家庭托育環境","補助居家托育人員的軟硬體設備","公幼增班，增設非營利幼兒園、準公共化幼兒園","增設公共場所男女廁尿布檯","建立各族群友善大眾運輸環境","推動城市共享運具","「銀髮照顧・敬老台北」","友善銀髮休閒活動空間：推動多元型日照服務中心","提供臨時托老服務：力挺18歲公民權，擴大青年參與","提供臨時托老服務：成立國際事務局接軌國際","提供臨時托老服務：要求市府公共工程重視在地生態維護","提供臨時托老服務：提升動物福利，推動寵物出生登記"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c28af338-ff5e-4adc-b8b7-8ae216823daa","items":["監督政府、開源節流、打貪瀆。","合力支持老、幼福利政策。 A.老人年金繼續發放。 B.補助0～3歲幼兒奶粉尿布津貼。 C.原有的政策照舊。","所有的經費將以公平、公開方式分配到各鄉鎮，有效運用，杜絕厚此薄彼的不良現象。","尊重民意需求，關懷民生福利，確實監督縣政施政與福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c2adfd92-dd4b-4575-a4f4-9cd0c991ad95","items":["1:持續推動S科技廊帶,發展高科技產業以促進左楠地區繁榮,完成高雄產業轉型,創造更多就業機會。","2:推動鐵路地下化從左營延伸到楠梓。儘速解決楠梓百慕達交通困境。","3:捷運東西向的高雄學園紫線,應與南北向的右昌高鐵線銜接,便利沿線七所大學及發展楠梓、右昌地區的交通路網。","4:推動老舊公園,更新為共融式特色公園。","5:保存既有眷村文化,注入多元面向;推動合群里內老舊社區都更,以利明建里舊有社區修繕再造,以恢復眷村文化榮景。","6:爭取維護中油宿舍原有居民的居住權。並改善其生活環境,提高生活品質。","7:有效運用閒置空間,廣設公托、公幼、育兒資源中心,長照、社宅,停車場等做高效益開發。","8:爭取左營、楠梓設置多功能聯合活動中心,並爭取社會住宅內廣設弱勢團體使用空間及居住權益。","9:爭取增設楠梓第二戶政事務所。擴建左營第二戶政事務所,以便利及擴大市民服務。","10:持續爭取「路平」、「燈亮」、「水溝通」,要給市民安全回家的路,及無慮的生活環境。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"c2e95c16-f16d-4d38-99d4-1b66230aaf1a","items":["推動容積獎勵提升、老舊社區公辦都更，加速城市更新","提升社會住宅建設量，調降租金、讓青年、弱勢優先承租","監督捷運萬大線施工品質與工程進度，確保2025年完工通車","提高北市托育品質，增加幼托人員待遇，讓好人才留在台北市","推動校舍改建、提升教育資源，同時提升學區鄰近社區更新動能","增設寵物友善空間、寵物運動公園，打造毛孩宜居城市","整合觀光資源，發展各區特色觀光，聯合觀光推廣讓效益1+1>2","持續推動洛陽停車場及西寧國宅聯合開發，順利改建，成為淡水河岸新地標並帶動台北西區新活力"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c388ce25-deaa-486a-8f71-5ac285049477","items":["監督縣政反映民意，爭取經費建設地方，協助產業及社區發展，傳遞民情、為民發聲。","督促政府落實社會福利政策，打造全齡友善安全環境。","督促政府整合提升育兒資源，打造親子共學遊戲空間。","督促政府推動公部門連結產業，協助青年職訓就業，青銀共創世代共融。","督促政府推動農村社區土地重劃，促進土地合理利用，合法發展產業及觀光。","督促政府推廣地方文化、工藝教育，深根傳承在地文化。","督促公部門輔導農民及文化產業，強化數位培訓，擴大銷售管道，促進數位轉型發展。","督促政府強化縣民就醫便利性及可近性，開辦免費醫療專車，提供就醫及探病一車到位的交通接送服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c3e7ede5-f924-456c-9e71-1d0bbf8ccd0c","items":["建議縣府將縣道145（彰水路一段二段）擴寬為24米道路。","建議中科四期二林園區，聯外道路沿東螺溪兩岸道路高架化，聯接1號高速公路。","協助推展精緻農業，謀取農民最佳福利。農民生活好過，政府才會安定，照顧農民是我最大的原動力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c415c804-ed90-438b-9276-4fa1420f2935","items":["交通觀光：推動台82線延伸高架串接台61線。","交通觀光：擴建嘉46線延伸段連接長庚醫療院區。","交通觀光：爭取灣內橋、介壽橋、八掌溪二號橋拓寬改建。","交通觀光：設置台61線休息站、壽島白沙遊憩區。","交通觀光：爭取北回車站立體化連結水上機場。","交通觀光：解決水上車站、東石先天宮周邊道路阻塞問題。","交通觀光：布袋港區活化再造。 農漁牧","交通觀光：爭取老農津貼8,550元，排富條款不動產所得至少800萬元。","交通觀光：依CPI與最低薪資調漲，檢討公糧與雜糧收購價格。","交通觀光：落實多元取水，確保灌區與雜糧區用水。","交通觀光：推動「外傘頂洲固沙特別條例」，專款保持東石、布袋港航道暢通，並推動第三漁港延伸防波堤。","交通觀光：利用碳權交易所綠、藍、黃碳匯方法，創造造林、濕地、海洋、養蚵產業新價值。 國防","交通觀光：堅持續推「國機國造」「潛艦國造」，強化國防武力。","交通觀光：修法護國安，加重共諜外患罪刑責，不容僥倖。","教育：廣設中央廚房，並補助送餐車，落實營養午餐與社區食堂三章一Q。","教育：爭取經費補助師資，強化課後輔導、提升學習能力。","教育：校園國際營隊交流常態化，增加學童視野。","教育：全面落實高中職免學費，並補助私校生3.5萬元學雜費，縮短公私立學費差距。","社福：建置東石醫院、新塭、六腳機構型長照中心。","社福：推動視訊診療，檢討健保點數、強化偏鄉醫療。","社福：爭取國民年金提高至5,000元。","社福：放寬巴氏量表適用規定。","社福：提高住宿型長照機構補助至18萬元。","社福：所得稅「長照特別扣除額」提升至20萬元。","社福：0至6歲幼兒第一胎起得聘用外籍保母。","青年：所得稅「幼兒學前特別扣除額」，第二胎提高到20萬元、第三胎提高到24萬元。","青年：打造朴子與水上社會住宅。","青年：爭取朴子運動中心附設游泳池。","青年：爭取警察、消防合理編制員額。 水利","青年：落實河道清淤，擴大出海口感潮段河床斷面。","青年：續建太保牛稠溪、水上赤蘭溪、八掌溪堤防，增設與加高。","青年：水環境經費改善堤防景觀。 產業","青年：爭取台積電落腳嘉義科學園區，水上南靖園區加速招商。","青年：推動嘉太、朴子、義竹工業區公共設施活化改善。","青年：蒜頭糖廠東倉庫加速招商，西倉庫設火車博物館。","青年：興建嘉義會展中心、藝術品拍賣會。","青年：馬稠後工業區二期爭取園中園，中心園區交由國科會管理。","青年：打造義竹無人機試飛、競技專區。","青年：督促朴子現代化屠宰場盡快完工。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c4366e8d-2c58-4a23-9276-829a13a55322","items":["成立台南原住民0-6歲幼兒托育照顧中心，爭取相關托育補助，以減輕家庭照顧及經濟上的負擔，同時引進族語文化教育以達到傳承文化語言之功能；","健全原住民長者照顧政策，除廣設原住民族文化健康站，協助關照長者的身心健康之外，也積極爭取長者之健康醫療補助，讓長輩老有所依；","爭取建置「原住民族聚會所」，營造一個適合族人聚會與活動之溫暖安全的「家」，可做為部落大學、幼兒托育、長輩安養等生活的場域，達到幼有所養、老有所依、老幼共學的目標；","爭取設置「原住民體育公園」或戶外適合大型傳統競技及球類體育活動之設施及空間，以積極推動族人健康運動之目標；","協助原住民各教會及社團辦理活動，以及增加相關補助經費，以積極發展原住民教育、文化及體育等各項活動，有助於族人身心靈的健全照顧與發展；","建置台南原住民完善之健康醫療政策，尤其針對勞動之中壯青年族人部分，除了加強相關醫療與健康的宣導與補助之外，亦增進相關社會福利補助之措施，以建構安全穩定之家庭照顧服務平台；","建置台南原住民勞工在就業機會、職能輔導、勞資協調、法律諮詢與溫暖陪同等全面性的服務平台，讓族人安心就業與生活，尤其針對原住民青年及婦女就業部分提供更多的就職選擇與機會；","持續推動與建構更完善之民族教育政策，以及提供幼童免費之課後輔導，並爭取擴大學生就學（國中小及大專院校）相關補助以及獎學金金額及名額提高，另外針對多元才藝的孩子給予多元智能培訓獎勵金，達到鼓勵與協助培育原住民多元人才的發展；","建構安全、便宜及便利之租屋平台服務，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。","持續推動「台南札哈木原住民族文創園區」工程，積極發展原住民族傳統與現代之文化、藝術、歌謠與舞蹈，並建構原鄉與台南原住民農特產銷平台與據點，成為台南新亮點。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"c47fa015-61ca-41b1-a7ab-990df5ced3f4","items":["從政理念： （一 ）善盡縣政監督 ，服務不分黨派。 （二 ）關懷弱勢族群 ，誠心服務鄉親。 （三 ）聽民聲解民憂 ，切實解決民願。 （四）落實社福政策 ，守護屏東家園。","具體政見： （一 ）督促縣府落實老幼婦孺、身心障礙、新住民等弱勢族群之社會福利政策 ，整合社福資源 ，打造全民健康安心的幸福家園。 （二 ）督促縣府落實空氣品質惡化管制措施 ，配合中央並推動高屏跨縣市合作 ，積極改善屏東空品不良問題。 （三）督促縣府落實寵物登記、結紮與飼主教育 ，多管齊下策略解決流浪動物造成之社會問題。 （四）結合社區及地方民意代表基層力量 ，協力縣市首長推展各項軟硬體建設及政策 ，讓屏東產業創新再升級。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c4a368fa-a273-4d13-88d5-d3c6bd87c74b","items":["正常國家新願景十項主張— 「台灣正名」、「公元紀年」、「世代新憲」、「縣市平權」、「責任政治」、「智慧交通」、「人才留鄉」、「居住正義」、「安心生養」、「老後照顧」。","徹底改善北區、中西區排水系統，找出淹水關鍵成因，建構完整排水規畫，提昇居民生活品質。","持續要求市府活化公有及私有空地，擴大獎勵機制，解決汽機車停車位不足問題。","實踐居住正義，持續追蹤台南市社會住宅興建及招租進度，提供青年及弱勢族群可負擔的優質居住空間。","持續爭取設置特色公園，讓特色遊戲場遍布社區公園，並利用公民參與，涵蓋實際使用者意見，為家庭提供優質的親子休憩空間。","加強警消人員的人力及裝備；全面普及警用監視器系統，建構路網監測完整性。","讓陽光照進非法繁殖場，要求市府補足相關稽查人力，強化台南動物保護；爭取增設寵物公園，打造動物友善城市。","持續監督赤崁文化園區改造工程儘速完成，期盼未來下沉式博物館有實現的可能。","「西市場」修復計畫早日活化重生，讓文化觀光與區域經濟相輔相成，帶動地方繁榮發展。","爭取傳統市場、觀光商圈之空間改造以及特色行銷，增強消費者舒適感受。積極發展特色市集，提供台灣在地文化創意品牌舞台。","重視府城街區防災議題，針對歷史街區修復工程納入防災消防管線探討，實際執行防災演練，保障人民生命安全。","成立青年事務專責單位，為青年完整發聲，建議設立台南市青年局。","成立學生社團辦公室，協助學生社團的發展與交流學習，培養世代青年的領導力。","推動青年設計基地、扶持青年多元文化發展。","督促政府設立創業青年共享辦公室，並安排一對一輔導、以及擴大募資機會，提供新創相關產業實習機會。","規劃全面性生育政策，包含孕前檢查服務補助、羊膜穿刺篩檢服務補助、人工生殖技術補助、中醫孕前助孕調理及孕期養胎調理等措施，從孕前到孕期體貼孕媽咪的辛苦，以行動支持年輕家庭。","健全幼兒托育及長輩托老照護環境，持續推動長照政策，督促長照創新整合性服務據點、大和社區活動中心、勝安社區活動中心、正覺里活動中心、華德社區長者日照活動中心、淺草里活動中心早日完工啟用。","關注台南市教育議題，打造優質多元教育環境，並重視家庭教育，強化親子互動，減輕孩子升學壓力。","促成體育局成立，持續關注體育發展培訓環境，讓選手和教練得到完善照顧，提升獎金制度，為台南市培育更多體育人才。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c53e955f-a161-48be-9761-d920b23f6464","items":["長照與社福：身障早療照護加倍","長照與社福：要求政府落實長照政策，照顧長輩","長照與社福：敬老愛心卡點數加倍，擴大使用範圍","運動與環境：提倡運動讓新竹市變成健康且友善的運動城市","運動與環境：爭取改造頭前溪左岸台68線橋下間置空間，興建步道、運動場地、生態教育廊道等空間。","運動與環境：重視頭前溪河川生態，落實保護環境喝好水、河川復育，加速佈建污水下水道系統，提高家戶接管率，建構健康幸福的宜居城市。","運動與環境：新竹油庫基地回饋市府之公園用地，爭取設置文化體育園區，活化具文資價值的油槽，及規劃標準足球場、標準網球場，透過運動經濟學提升城市競爭力。","幸福毛小孩：設置毛小孩友善公國，","幸福毛小孩：持續推廣TNVR，以零安樂死為目標。","幸福毛小孩：從教育扎根，國中小學應落實毛小孩生命教育課程。","婦幼與教育：公托臨托親子館加倍。","婦幼與教育：增加學童營養午餐預算。","婦幼與教育：關埔中小學加一，滿足就近入學需求。","婦幼與教育：補足國中小正式教師，代理教師不超過8%。","婦幼與教育：督促市府超前規劃，於2030年以前完成雙語城市政策目標。","財政與交通：持績要求市府爭取中只哺助，建設地方。","財政與交通：預算把關，要求市府改善財政間題，逐年降低負債，達到財政收支平衡。","財政與交通：慈雲路空橋朝HOPSCA概念規劃興建，增加公共空間符合多功能使用，保造市民通行安全。","財政與交通：支持竹科X計畫2.0，透過擴大都市計畫取得推動跨頭前溪替代道路及果菜市場遷建用地、支持興建新竹輕軌，提供市民安全便捷的交通工具。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"c55c3964-3aed-4f1f-bb68-70bf7e2726f4","items":["車場拆除後爭取車棚綠能，全面運用太陽能板增設汽機車加電站、電池交換站。 福車站汽機車停車處設綠能雨陽棚。 區公園是我的家，管理公園硬體建設之維護，落實花草樹木照護修剪。 護 : (1) 協助流浪在外毛小孩，認養給予一個溫暖的家。","爭取大型寵物公園選址在百福公園，另外一里 小型寵物公園。","推動催生爭取寵物銀行第二期工程 - 於寵物銀行周邊增闢墓園植葬生命園區。 展七堵鐵道公園。 運之後續，攸關七堵區未來的發展，督促基隆市政府落實基隆捷運建設。 動中心 : 七堵區社宅旁爭取興建基隆市第二座國民運動中心，以嘉惠市民。 串聯基隆河自行車步道，強化步道周邊綠美化及公廁設施。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c6932a01-d594-4387-82a7-6ce59cd3adf4","items":["推動設置彰化市金馬路和中央2座通勤車站。","督促盡速推動台中捷運延伸到彰化和鐵路高架化。","推動解除高速公路特定區之限制，均衡城鄉發展。","繼續推動擴大東區都市計畫、爭取南、西、北區都更。","提高勞工生育補助、反對勞退金改革，保障勞工權益。","檢討疊床架屋之法規、簡化行政程序，提升政府服務效能。","改善彰化、花壇、芬園國中、小學之校園環境和運動設施。","秉持傾聽民意、勤跑基層，以解決民眾迫切需求之目標前進。","振興永樂商圈及大佛風景區，配套彰化特色美食和展演等措施。","推動彰化、花壇、芬園設立農業、生物科技園區，創造就業機會。","向下紮根，爭取幼兒園就學免學費，推展弱勢及單親家庭之照護。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c6a18d49-8f03-4ee4-a0ba-ec400d235cd1","items":["積極爭取開闢停車場並納入地下化，解決停車及市容問題","強化警力佈建，防制犯罪發生，加強市民生命財產保護","推動新北建教合作深化，加強職涯發展，讓學子能一展長才","擴大公幼公托增班，提升社福協助弱勢兒少脫貧","爭取普設日間照護中心，加強各社區長照體系讓長者樂活","落實中低收入戶及急難救助支援系統，確實照顧弱勢族群","推動新北好生活全民健走運動，提升休閒運動風氣","推動綠能發展，守護環境議題，全力對抗空污惡化"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"c6f32536-bed0-4eca-8d12-41f061808f08","items":["監督縣政為民喉舌，善盡民意代表的職責，堅持做鄉親的代言人。","極力爭取雲164線縣道拓寬第二期工程，全線打通口湖、水林、北港三鄉鎮交通網路任督二脈，促進大北港地區之繁榮與發展。","強力監督大北港區科技產業園區進程，提供在地子弟就業機會並促進地方繁榮與發展。","督促縣政府針對北港、水林、口湖地區防洪治水作通盤檢討，徹底解決易淹水地區之惡夢。並於易淹水地區增設抽水站，降低農漁牧業受災害損失。","建言提升社會福利、提高老人敬老津貼，加強獨居老人照顧及弱勢族群關懷。","建議縣政府建構農業資訊平台，控制農作物耕種面積，防止因超量種植造成市場供需失衡，並嚴厲建議政府勿在農作物採收期開放進口，以穩定農產品價格。","加強社區營造，提供聚落集會聯誼場所。","建議縣政府針對學童營養午餐，比照其他縣市免費供應。","建議政府爭取經費建構78甲線由東西向78線延伸施設高架道路直通北港，活絡北港區交通網，提升宗教觀光區之交通便捷性。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c73ae4c9-c6c2-43bf-8868-226ee2420a01","items":["擔任議員期間，我著墨最深的就是交通，這是大家最切身相關也期望最高的議題，也因此我付出最多的心力來監督改善，目前達成初步成果的有「光復路交通工程標線改善」、「兩線道取消禁行機車」、「機車不強制兩段式左轉」、「爭取新設實體人行道」、還有與新竹縣夥伴余筱菁議員共同爭取的「公共自行車縣市互通」。","未來仍須繼續努力的目標還有竹科聯外路線的 相關改善，包含「525巷上班尖峰調撥單行往園區」、「園區一路橋下直通慈雲路」、「慈雲路全區空橋興建」，大眾運輸則要推動「共享機車」、「竹科輕軌捷運聯絡線核定」，多管齊下來改善園區從業人員的通勤環境。","而我也關心教育與環境保育，推動「新科國中雙語教育」，提出「總量管制辦法修正與學區合理化」 並爭取「光武建功新建校舍」期望落實「就近入學」也積極處理「避免宗教團體進入校園」讓孩子學得安心；至於環保除了倡議「垃圾費隨袋徵收」以求減量外，也和筱菁議員共同「力阻大新竹地區第二焚化爐」興建，更聲援「頭前溪乾淨水」並推動污水管理條例。","還有許多的目標需要長期的努力倡議與爭取，我會堅定的在公共事務上發出「竹科人的聲音」，希望在接下來的四年與未來的每一個四年，都要與市民朋友與園區同仁們一起努力，讓我們的城市繼續向前邁進。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"c742ed7c-e5c5-454f-a7c6-2decda56c55c","items":["秉持公平、正義與比例原則，力促縣政府落實執行地方均衡之發展。","積極爭取營造原鄉特色之基礎建設，推動並扶持原鄉部落文化、生態及農業遊憩觀光產業。","力促縣政府積極改善原鄉農、產業道路，以改善並活絡原鄉農業之經濟產業。","力促縣政府優先改善原鄉教育環境與設備，以縮短城鄉教育資源之差距。","力促縣政府積極扶持原鄉民間長照機構之設立，以落實原鄉老人及弱勢族群之起居生活與身心健康照護。","力促縣政府落實都會原住民就業輔導與經濟、生活之照護。","積極爭取十六省道之拓寬改善工程，以確保農產運輸與交通的安全。","積極爭取濁水溪線消防分隊（站）之設立，以保障人民生命財產之安全。","積極監督縣政府落實中央政府制定或推動之原住民族相關政策與事務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c767adc9-88c7-4eb6-83e0-8464ae34d8b9","items":["持續推動反對廢除死刑，堅決要求速審速決。","酒駕、毒品零容忍，保障市民安全。","協助保障爭取軍公教警消勞現職與退休權益。","增設長照服務機構，同時建置友善安養環境。","整治道路交通標誌標線規劃，改善交通壅塞問題。","廣設共融式遊具，創造在地特色公園。","提升新北居住品質，加速危老建築改善。","活化閒置空間轉型青年社宅，放寬入住資格條件，減輕青年租房壓力。","加強科技力量與創新變革，優化新北智慧城市，擴展國際能見度。","持續整治雜亂電纜線，改善市容景觀，還給市民乾淨的天空。","監督食安法規確實執行，守護全民健康。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"c7749c27-5393-4ef4-9ca2-74d8b66f688d","items":["督縣政、支持縣政推動。","市計劃通盤檢討，擴大自然村範圍。","府興建合宜住宅，帶動青年人成家立業。","橋通車後，請縣府自己編列預算或向中央爭、擴大重建烈嶼的道路，以及基礎建設","車後，請縣府做好各項配套措施，讓烈嶼有新的發展，包括觀光及經濟。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c7b8ce10-7810-4913-868f-dca17bb8d0b1","items":["中小學全面雙語教育,為孩子奠定國際競爭力。","增設夜間籃球場及複合式運動區,滿足市民運動需求。","推動寵物公園,落實動物生命及環境教育。","加速國道七號興建,守護沿海路周邊居民交通安全。","0 減輕年輕人照顧負擔,出外打拼沒煩惱。","成立長照局,讓長照推動更有效率,照顧長輩更周全。","嚴厲監督空污,提升公共運輸效能。","落實青年社會住宅,有巢讓年輕人安心築夢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c808e60f-1c67-49df-9653-d8e7f73db268","items":["研議於現有公園增設寵物運動空間。","提高流浪犬貓絕育比例，降低跨縣市流浪動物數。","推動「寵物生命紀念自治條例」，並建立「嘉義市樹灑環保葬紀念園區」，提升寵物喪葬品質。","長者與托育：補助年長者相關社交育樂活動。","長者與托育：提升公共托育資源。","長者與托育：推動嘉義特色青創中心，支持青年創就業預算。","長者與托育：促成嘉義縣市「前店後廠」合作，配合嘉義縣園區商機，發展嘉義市相應軟體服務業。","長者與托育：鐵路高架化妥善規劃","長者與托育：鐵路高架騰出空間的規劃，應回歸在地居民需求。","長者與托育：爭取設置「新北興市場」。","長者與托育：要求成立「拆遷辦公室」，守護鐵路拆遷居民利益。","長者與托育：因應極端氣候，提高雨水下水道防洪標準。","長者與托育：納入防洪新思維，於公園及易淹水區域推動滯洪池、增設吸水鋪面。","長者與托育：提高設置綠能屋頂誘因。","長者與托育：提升充（換）電基礎設施。","居住與文化：爭取木屋老宅災害防控補助，讓市民住得安心。","居住與文化：支持典藏並發揚嘉義市文化資產。","居住與文化：支持母語及台文預算。","交通：完善公共自行車站點。","交通：完善自行車路廊，確保自行車道路安全。","交通：推動人行道與騎樓齊平，保障行人及身障者安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"c82d4447-a31c-4487-ac8b-4fde1c2243d1","items":["公費長照 降低公費補助門檻、提高補助金額、擴大私立長照機構補助範圍。","保障青年入企實習名額 凡台北市公共工程、大型標案均需雇用30%以上本市青年。","凍卵補助、拒絕月經貧窮 保障女性生育選擇權，凡本市35歲以下未生育女性，均可一次性申請凍卵補助，及往後10年的保存費用。","提高生育補助及育兒津貼 生育獎勵金提高為第一胎5萬、第二胎6萬；第3胎起，每胎7萬，育兒津貼延長為0到6歲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c852488c-ed1a-4e36-97b9-b665c60acd7c","items":["嚴格監督縣政預算執行，杜絕浪費公帑。","持續推動各項基礎建設，提升民眾優質生活環境。","督促幼兒托育服務品質，保障幼童受照顧權。","持續爭取設置特色共融式遊戲場，重視兒童遊戲權。","督促提升長照、養護中心佈建率，保障銀髮族健康照護。","督促重視婦女各項福利權益及人身安全，建構友善婦幼環境。","督促強化衛生醫療環境改善，提升醫療照護品質。","持續爭取升級青年事務設置層級，落實推動青年事務發展。","健全在地農特產品輔導、推廣與行銷，積極拓展銷售通路。","推動觀光與文化整合加值發展，創造在地觀光特色產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c9115bde-f00c-4a7e-8061-d360007ad220","items":["教育篇：提高公立幼托比例：增加公托、公幼班數及非營利幼兒園等，減輕雙薪家庭負擔，落實平價優化托育服務。","教育篇：補助弱勢家庭網路資訊費，每月500元。","青年青創篇：增加青年專屬公宅與青年入住公宅比例。","青年青創篇：青年租屋補助每月5,000元，減輕青年租屋負擔。","社會福利篇：建置完善的健康銀髮養生村，並設立長者陪醫制度，增設慢性病床和長照安養中心。","社會福利篇：協助退休長者二度就業，增進社會參與，成為退而不休的銀髮職人。","新住民篇：設置專人或專責機構，提供新住民法律諮詢、生活協助與就業輔導，使其快速融入在地生活，成為我們的一份子。","新住民篇：增加新二代新住民語言學習課程及機會，建構南向就業機會和環境。","交通篇：監督路平專案執行達成率並嚴查各路平驗收報告。","交通篇：加速各區瓶頸道路改善執行成效。","動保篇：爭取設置寵物運動公園，讓毛小孩與主人歡樂同遊有更多選擇。","動保篇：廣宣毛小孩領養代替購買的觀念，爭取增加預算改善收容所環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"c9ac4321-1713-47a0-8834-2e6e3e334dd8","items":["顧婦幼 推動優質、平價、近便性高的公共托育。 公私協力，推動企業友善生育政策。 完善供餐、陪醫制度，提高長照居家照護量能。","要食安 營養午餐精緻化，在地食材，結合食農教育，減少食物碳排。 落實食安稽查，加強溯源機制，讓市民安心選擇。 食安自治條例再修訂，明確標示，加強業者自主管理。","拚建設 都市計畫檢討鬆綁，為都市更新添柴火。 推動疫情後商圈復興計劃，規劃內湖南港特色商圈。 加速鄰里公園改造，更符合周邊里民需求。 智慧城市治理，港湖出發，爭取港湖成為智慧城市政策先行。","護交通 東環段、民生線、汐東線、信義線東延，加速規劃興建。 從基層展開，推動以人為本的鄰里交通安全思維。 東區門戶再升級，加速南港成為台北東區交通樞紐。","守教文 加強校園反毒工作，向毒品說不。 國小雙語教學、程式語言、STEM 教育列入國小必修課程。 推動運動中心 2.0，強化兒童、銀髮世代運動設施、課程。 從公共空間，到就醫便利，推動友善毛小孩政策。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"ca2043a1-718b-4eff-9adc-0f14869e0180","items":["打造湖西好鄉、議福家轅","推動湖西總體社造"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ca2a38b6-609a-4716-a77a-7a3c72da5371","items":["青年有所本：贊成18歲公民權，鼓勵青年一起與公共事務。","青年有所本：爭取中和青創基地、創業補助，開創青創新契機。","婦幼有所依：增設公托中心與試辦夜間托育，擴大保母證照課程並爭取親屬保母津貼。","婦幼有所依：增設雙語學校，加設校園安全網整合平台。","婦幼有所依：提供婦女、銀髮族終身學習課程及教室。","婦幼有所依：提供家暴防治、學校霸凌防治諮詢與協助。","長者、弱勢不孤單：落實長照社區化據點，增設「一里一銀髮俱樂部」融合公托推動「幼銀共榮」。","長者、弱勢不孤單：面對高齡化，提供銀髮就業職涯諮詢。","長者、弱勢不孤單：提供身心障礙及獨居長輩服務，落實居家照護，爭取補助親人照顧者津貼。","多元文化、族群融合，在中和：積極舉辦星光電影院及推廣各項藝文活動。","多元文化、族群融合，在中和：推廣客家、原住民、新住民文化，展現多元人文風華。","多元文化、族群融合，在中和：關心新住民，爭取中和會館，強化聯絡據點。","多元文化、族群融合，在中和：關心榮民、榮眷，爭取榮民會館，增加專屬照護系統。","美麗城市、安心家園，在中和：爭取警消廳舍改建及擴增派出所、消防隊，建構安心家園。","美麗城市、安心家園，在中和：捷運緊密結合U-bike微笑單車據點，上下班輕鬆行。","美麗城市、安心家園，在中和：美化登山步道及安全平整的環河自行車道。","美麗城市、安心家園，在中和：打造河岸景觀公園、活化傳統公園兼具親子特色及創意。","在地關心 在地服務：強力連結各里長，解決各里大小事。","在地關心 在地服務：維護役男及後備軍人權益、提供法律諮詢扶助。","在地關心 在地服務：專業服務團隊，溝通協調公部門各項服務，提供每週免費法律諮詢。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ca5efe1e-1999-424a-be84-75696eea4b43","items":["爭取推動蘇澳鎮教育、文化、社會、經濟、交通等各項建設，提高人民生活品質。","爭取縣政府於蘇澳地區普設長青食堂、長照關懷據點，結合社區、廟宇等社會資源提供多元服務，提升社區老人生活品質，增進老人福利與老人日間照顧。","重視婦幼及弱勢團體福利，落實社會福利制度。","鼓勵青年返鄉就業、創業及創新，爭取租金補助。","建請縣政府重視農漁業及基層農漁民心聲，維護農漁業永續經營；拓展行銷在地優良農漁特產品，增加農漁民收益，確保農漁民權益及福利。","推動活化鎮內風景區與觀光景點，結合冷泉資源，使蘇澳成為冷泉觀光城市。","爭取將利澤焚化爐回饋金分配發放對象納入蘇澳新馬地區的隘丁里、港邊里、永榮里、新城里、存仁里等地，嘉惠周邊受影響區域，並以回饋機制改善環境，確保居民權益。","爭取蘇澳鎮南方澳港區商場改建、增設公共停車場並改善交通，以利地方工商觀光發展。","推動南澳有機休閒農業區開發，讓當地青年子弟返鄉就業及創業，帶動地方觀光人潮。","健全水患防災能力，推動河川防洪整治工程，強化災害防救能力，減少鎮民災損，保障人民身家性命安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cab038ce-4b2c-443e-8aa4-8c85e105658b","items":["淑君為南部孩子，一卡皮箱上來板橋生根，台灣人在說「番薯不怕落土爛，只求枝葉代代湠」，淑君參政的初衷是希望可以在板橋湠根服務，延續何博文團隊的服務精神，未來淑君將會著重： 1.交通安心：新北市幅員遼闊，交通問題是新北需要不斷檢討之問題，落實交通安全需要有耐心跟經驗，未來淑君將會針對不同區域的問題，對症下藥。","號誌加裝UPS(不斷電系統)，提供急難使用。","檢討待轉區設立，不要讓待轉區變成待撞區。","推行無號誌化路口，簡化號誌設立同時，強化動線檢討，並加強標線規劃。","都市計畫檢討道路之設置，從源頭解決交通問題。","增設停車空間。","教育安心：新北市有最多的兒童就讀，孩子不同階段的教育都需要被重視。","增設公托、兩歲專班及公幼。","推動非營利幼兒園。","建立保母媒合平台，加強保母及家長的幼兒照顧教育訓練。","落實兒童照顧機制，建立兒虐及高風險家庭通報平台。","吃得安心：新北市人口眾多，除要落實食材登錄平台，從小、從生活重新認識食品安全及食農教育十分重要。","定期稽查食品製作過程，確保食材的品質。","降低食品碳排放量，鼓勵在地取材食用。","落實食農教育，推行生活綠美化，從根本調整身體健康。","醫療安心：近年來疫情肆虐，讓我們深刻認知到醫療環境改善的重要性，以確保醫療資源充足。","建立板橋醫療園區，並定期追蹤BOT進度跟人民報告。","推動地方婦幼門診，讓孩子能夠及早接受治療，並且有充足的醫療資源可以供應。","增加生育率：爭取凍卵補助、建立不孕症諮商管道。","落實心理照護機制，讓新北市民不再依靠憂鬱症藥物。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"caf89809-2876-4f26-ba9f-b427578a2398","items":["為民服務。","改革從心、帶領農業、觀光創新。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"cb2d4892-07cb-4c69-9ac1-e22840742ab6","items":["監督縣政，落實施政。","致力本鄉農漁業發展，督促縣府保障農漁民權益。","持續發展觀光及在地文化特色。","督促縣府改善，本鄉教育環境，縮小城鄉差距。","爭取地方基層建設，改善鄉親生活品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cb6b0210-a874-40c7-8af6-af25aba15df2","items":["要提高公幼、公托及準公托的質與量:增設公幼及公托中心,提高生育津貼補助,減輕家長育兒負擔","要打造高齡友善環境:增設社區照顧關懷據點,優化長照服務,減輕家庭照顧長者的壓力","改善空汙:反對南電北送,加速淨零排放時程,加速發展氫能及綠能產業,加速電動公車全面化、設立電動汽機車充電樁(站)","要解決熱區停車位不足問題:增設立體停車場","持續推動社會住宅:四年內再興建 2 萬戶社會住宅,增加青年及弱勢族群居住比例,落實居住正義","持續加碼租金補貼,減輕租屋族負擔","持續推廣城市運動風氣:成功推動高雄銀行培育在地優秀體育選手之後,繼續推動公營事業單位培育在地優秀體育選手,完善學校三級培訓制度,並優化現有場館設施","協助青年就業:迎接未來高科技產業人才需求,積極培育在地人才就業,接軌在地工作機會","強化監控警示系統:持續改善現有道路監視系統良率,增設巷弄監視器,確保婦幼人身安全","持續爭取路平:嚴格把關高雄市各道路的施工品質,並減少人孔蓋的設置,確保民眾行的安全","持續改造傳統市場:全面補強傳統市場硬體設備及改善公廁環境品質,增設機車停車位,提供安全、舒適的購物環境"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"cbd202c3-9607-4931-8619-01c7ceaeb59b","items":["六年幼托，免負擔： 1.加強教保人員身心健康，以保障受托幼童之安全。","落實三胎的優先權利。","十年長照，零負擔： 1.廣設社區型老人關懷據點，因應快速的老人化社會。","設立銀髮社區，活化老人文化。","都更改建，保家園： 1.為居的安全，加速都更進度。","以里為單位，辦理都更說明會，協助都更完成。","雙語教學，國際化： 1.推動國中小，學校全面雙語課程規劃與實踐。","辦理各項英語活動，讓語言可以在日常生活中落實。","醫療量能，要保全： 1.確保三重聯合醫院的醫療效能顧及三重蘆洲。","加速蘆洲醫院的興建工程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cc03cdf1-b263-4a07-ba63-c6ed2863c637","items":["監督長照資源妥善運用，長輩晚年安心健康、有尊嚴","爭取設置苗南聯合服務中心、持續協助法律諮詢及陳情，推動縣政治理及服務進步","推動海線人文、藝術生態產業發展及整體計畫，打造進步、永續的深度觀光","監督環境污染稽查、環保犯罪查辦，守護家園環境，民眾日常生活安心","爭取設置苑裡休閒農業區，推動通苑農漁業冷鏈系統"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cc376e14-44d9-4606-934d-cd19b4f7b248","items":["積極爭取原住民權益 , 建請落實原住民基本法及修訂各項配套法令。","持續關懷照顧弱勢家庭 , 結合各項資源 , 全力協助及爭取應有權益與福利。","鼓勵及尊重多元宗教信仰 , 扶助宗教團體各項活動與充實軟硬體設施。","督促政府積極培育原住民體育、 藝術、 文化等相關人才。","全力維護警察人權 , 爭取充實各項裝備 , 以強化執勤安全。","爭取文健站、 關懷據點各項設施 , 建立完善部落老人照護體系。","爭取接收金崙村原觀光局 38 公頃土地, 規劃興建為具運動、 休閒、 醫療、 文化等園區。","持續爭取永久屋土地所有權 , 以符財產及居住正義。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cc8821c8-d770-47bc-beab-f36d31083e31","items":["ㄧ、積極推動豐富園區經濟效益及人口就業機會。","全力監督豐原國民暨兒童運動中心，力拼113年底完工。","爭取完成打卡新景點「心鎖花之道」，持續美化景觀。","督促打造鐵道下方綠廊空間為停車及遊憩休閒場域。","爭取完成豐原轉運中心，持續監督招商及停車、轉乘便利性。","全力爭取「美樂地公園」打造老幼皆宜的休閒空間。","持續推動加強校園安全零死角，讓學生安心、家長放心。","推動設立「新住民科」，協助新住民融入在台生活。","爭取推動公托公幼倍增，減輕家長負擔。","爭取提升育兒津貼補助。","繼續推動65歲以上長者免繳健保費，減輕家庭負擔。","繼續嚴格監督市府預算，為市民荷包把關。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cd0608c6-3790-4564-aa73-31d9ed4e6f95","items":["未來將繼續協助推動老人日照中心，特別是推動閒置學校空間設置老人電競中心，讓健康長者增加更多活動選擇。","台北市應持續加強幼兒照顧及協助生養，將幼兒免學費年齡由5歲向下降低到4歲，並配套增加3至4歲幼兒專班，減輕年輕上班父母養育子女負擔。","推動市府組織再造，成立青年發展局，協助青年求學、就業、創業及安居需求。","因應未來人工智慧發展，台北市應推動人工智能實驗國、高中，強化台北市學子競爭力。","繼續落實技職教育產學銜接，提高技職教育預算比例，鼓勵及創造技職教育產學合作，技職教育適才適能、充分就業。","挽救衰退及沒落的商圈，市府應持續提出振興商圈方案。","繼續推動以認養代替購買，強化推廣校園流浪動物收容，增加校園犬、降低流浪動物，也建立學生對生命教育的認識；提高民眾認養流浪動物補助，增加誘因。","降低公辦都更門檻，增加民眾參與公辦都更誘因。","全面檢討台北市容積率，並建立容積回饋市府及公益機制，以提高都更誘因。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"cd127a85-9a06-41b7-93c1-b1db5d876d26","items":["1：民意優先、繁榮地方、照顧弱勢、提振經濟。","2：防疫第一、配合指引、平安健康、保護庶民。","3：監督縣政、服務鄉親、看緊縣庫、做好鄉親與縣府之間的橋樑。","4：關懷長輩、關心年輕人、關照婦幼，讓老有所終、壯有所用、幼有所長。督促縣府全方位重視社會福利。","5：教育是百年大計，持續爭取各級學校軟硬體建設，加強營養午餐食材控管暨質的提升。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cd26ea34-d89d-4648-b89d-00f58c0fe6fe","items":["女性延後生育照顧更好：爭取適齡女性凍卵補助，照顧有延後生育規劃的女性。","東區交通品質更好：持續爭取人行空問優化、爭取通學步道建置，給長輩、孩子一條安全的路。","東區交通品質更好：爭取慈雲路空橋建置，提高人行環境安全及生活品質。","東區交通品質更好：爭取園區一路直通慈雲路，提高車輛運輸流量。","東區交通品質更好：爭取慈雲路橋下（往光復路方向）拓寬為雙線道，增加儲車空間、舒緩龍山西路／慈雲路口瓶頸。","東區交通品質更好：持續爭取增加汽、機車停車空間。","東區交通品質更好：推動公車站牌電子化，優化候車空間。","東區交通品質更好：爭取youbike2.0自行車廣設站點。","東區交通品質更好：敦促大眾運輸系統建置，推動輕軌建設以及接駁交通完善，提高轉乘速率。","舊城區更好：復興舊城區商圈，推動青年在地創生補助，培育新竹市在地企業人才。","舊城區更好：推動人本交通，完善無障礙街道空間，打造適宜購物環境。","醫療品質更好：敦促台大分院浦雅院區擴院建置，提升醫療環境。","世代共好，生活品質更好：監督社會住宅建置計畫，落實居住正義。","世代共好，生活品質更好：敦促老人年金、重陽敬老金按時發放。","世代共好，生活品質更好：爭取親子、長輩適用共融式公園改造，提升休憩環境品質。","教育品質更好：爭取關埔二期中小學新校建設，落實就近人學，緩解就學壓力。","教育品質更好：爭取調整學區合理劃分，保障就學權益。","教育品質更好：爭取代理教師一整年完整聘期保障，具體改善代理教師基本權益。","教育品質更好：爭取體育人才扎根新竹，提高體育特色校園運動環境、器材品質，補足教練缺額，培養在地體育選手，並發展城市運動經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ce00b1e5-982e-4412-b7b3-634caae016d6","items":["以年輕的手推動苗栗的發展與傳承。","關懷長輩及弱勢，落實急難救助。","推廣特色產業，帶動地方發展。","發揚青少年運動，培育在地人才。","優化教育環境，發展多元學習。","爭取提升醫療品質，區城醫療系統升級。","理性問政，爭取建設，造福鄉里。","延續發展社區關懷據點並提昇服務品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ce9c8860-3d80-4b8f-b691-cf987fef152d","items":["爭取續發65歲以上安老津貼","爭取65歲以上長輩免費健康檢查","擴大敬老愛心卡補助適用範圍","爭取社區關懷據點共餐、課程開辦補助","爭取北區第二座親子館的增設","爭取改造士林市場門面與周邊環境","爭取微笑單車UBIKE一里一站點","爭取輕軌二階段經國路─南寮","加速新建台68武陵連通竹北"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cea47719-cc96-425c-8813-bd10d1304730","items":["議會新女力 問政即戰力！ 【監督加速士北科園區招商與設施建置，串連產業發展廊帶 關渡平原保留重要社會價值聚落，公園用地研議規劃運動園區】 育兒不費力！親子友善","增加公托據點並社區化，讓家長降低接送時間成本。","增加公園親子廁所，讓家長與孩子不再為上廁所或换尿布而煩惱。","提倡產官合作，具一定規模公部門與企業增設幼兒園。","增加雙語教學據點，提升語言競爭力，爭取雙語教學教師津貼與進修補助金。","推動30歲以上凍卵補助，職場打拼更安心。 長青樂活力！銀髮友善","擴大老人卡使用通路，讓老人卡點數可每月累計。","「牙口好,人不老」，補助65歲以上長者免費裝假牙。","推動長輩與身障者換居計畫，翻新公營宿舍、老公寓為青年住宅，長輩換居電梯住宅。","增加安養照護及日照中心。 通勤更便利！交通友善","加速興建捷運環狀線北環段。","增加公車智慧站牌並優化設備。","監督路面鋪設工程品質，改善無障礙空間，保障用路人安全。","基隆河淡水河整治，碼頭設施優化，產官合作研議水路交通船解決塞車問題。","危險路口、路段應優先改善道路設計，降低交通事故風險與傷亡。","應用大數據分析、AI動態號誌系統(智慧綠燈)，兼顧交通順暢與安全。 住宅更新力！居住友善","都市更新、違老重建、興建社會住宅大加速！","整建住宅列為優先公辦都市更新區域。","推動住宅無障礙設施改善計畫，提高老宅增設電梯補助金。","士林北投電纜地下化，用電更穩定。 創新發展力！青年友善","推動成立「青年事務局」整合青年創業、國際交流、資金募集、輔導諮詢平台。","青創資金募集、補助步驟簡便化，整合產官學平台，增加一對一業師輔導，營造友善創業環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ceeb7778-b8ee-43f6-86f1-635671054fa6","items":["堅持「敢講、會做、拼服務」之問政理念，手機0936161617專線24小時服務。","為新北市全力打拼，提升中和區整體發展。","督促中和秀山消防分隊成立及廳舍興建。","增設中和第2納骨塔。","加強和治安死角的消滅，保護婦幼安全無恐懼空間。","爭取廣設公共托老中心及安養中心，關懷獨居老人，提供老人急救轉診服務。","促進兒童人權與福利，健全弱勢族群、婦幼、榮民、榮眷之福祉。","監督市府改善經濟環境，增加工作機會，提高就業機會。","督促市府加強公共安全檢查，保障人民生命財產安全。","爭取廣設公共幼兒園，加強學童雙語教學，從小紮根。","持續督促市府加強中和區淹水區域排水改善。","持續推動捷運環狀線、萬大線及莒光支線早日完工。","協助推動老舊房屋都更，廣建社會住宅提升居住品質。","督促市府增闢公園、停車場、YouBike等公共設施。","督促市府行政作業透明化，杜絕貪提高行政效率。","促進現有工業區發展，轉型高科技工商綜合區。","爭取興建南勢角公路隧道，直接北二國道。","推動山坡地社區自來水由政府做高地供水代管。","推動中和污水全面接管。","中和灰磘及南勢角農業區闢建為軟體科技園區。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cf083c19-a203-4cdd-87ec-0ac1dc247be0","items":["爭取廣設風雨操場。","爭取停車空間。","爭取暖暖水源地成為水資源生態教育文創園區。","增設銀髮族健身俱樂部。","爭取長者所需，日照、安養、養護長照機構。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cf26fbdc-43dc-4056-b8f1-bd5ee2b577ee","items":["爭取闢建新豐街聯外道路紓解塞車情況 2. 改善藍色公路使用機制。","公共托育：增設公共托婴中心、擴大托育津貼補助 2. 擴大托育人員輔導與培力計畫，增加托育人力。","醫療保健、長照服務：活化閒置校園空間，打造「長幼共學」樂齡空間。","醫療保健、長照服務：改善整體長照服務體系，包含提高長照服務提供單位之分布密度、促進長照相關資源之發展、監督服務品質 效率，滿足民眾各階段之長照需求。","醫療保健、長照服務：擴大長照人員輔導與培力計畫，增加長照人力量能，降低家庭照顧負擔。","醫療保健、長照服務：爭取布建社區式、住宿型長期照顧服務機構等資源，優化以人為本，以社區為基礎之整合式服務體系。","醫療保健、長照服務：推動中正區地方歷史文化創生、中正區觀光廊帶及文創聚落。","醫療保健、長照服務：打造親子共融公園、寵物友善公園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"cf7d4bd6-3988-4265-8b1a-fd659f1dea4e","items":["爭取機場捷運(橘線)路線自臺中國際機場起至大里霧峰。","爭取台74線下平面道路霧峰段儘速完成通車。","爭取霧峰區中正路與振興街打通工程，使甲寅、本鄉、本堂、中正里等民眾進出免繞道。","儘速增設台74縣十九甲北出匝道，提供十九甲、大里及太平地區居民更便利的行車環境。","爭取中興路一段2巷拓寬工程，有效改善大里溪南地區對外交通。","爭取普遍增設「微笑單車2.0電輔車(YouBike2.0E)」讓民眾騎乘時可以更輕鬆省力。","關注農產品行銷、農業和農產品相關政策，協助農民解決蟲害防治並提高農損補助。","持續爭取友善共融公園，讓市民擁有更好的休閒運動空間。","增加公托量能、公幼倍增計畫，提高對0-6歲嬰幼的經費補助，提升年輕人生孩子的意願，減輕育兒負擔。","推動絕育取代撲殺，把關市府編列之相關預算，為流浪動物福祉嚴格把關。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"cfc79630-cc4a-42c7-8342-a7aa3e2f8f9f","items":["年少有魄力、新動力、有責任，傾聽民意、重視公民力量，全力做最好的服務。","透過馬稠後工業園區及嘉義科學園區創造優質就業環境平台，鼓勵及輔導青年返鄉就業。","監督縣政府各部門施政執行成效，積極爭取各項資源及基礎建設，打造完善公共設施，塑造及提升生活環境。","面對氣候變遷，針對易淹水地區全面檢討排水系統與加強河川整治，建立治水園區。","推廣商圈市集及文化相關活動，打造旅遊新地標。","國際局勢詭譎多變，為維護農漁民權益，積極輔導優質農漁產品，強化內銷及拓展國際通路。","提高本縣生育獎勵金補助，以落實照顧婦幼核心價值。","重視各地長照據點照護資源，安定長者生活，讓福利服務需求有所依。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d12cc49e-dfa5-4653-8438-7835d7f0390f","items":["鄉親社會福利：爭取多舉辦親子活動及課程。","鄉親社會福利：廣設公共托兒園，獎勵企業設置非營利幼兒園。","鄉親社會福利：老人在地安養政策，協助社區活動中心辦理老人日托。","鄉親社會福利：關注竹北市民居住權，提案推動社會住宅。","鄉親社會福利：關懷弱勢、身心障礙者，有效利用有聲號誌，打造友善行人空間。","鄉親社會福利：推動在宅醫療和長期照護的合作，掌握社區醫療照護資源與地方長照機構。","鄉親社會福利：實際監督竹北中小學總量管制。","鄉親社會福利：爭取增加公托地點及名額。","鄉親社會福利：強化校園霸凌與性侵通報系統。","鄉親社會福利：關心西區農政照顧農民，監督縣府落實農業政策，全力推廣在地特色農產品。","鄉親社會福利：推動公園綠化及空汙數據公開。現有公園積極推動更新設備，增加休閒去處。","鄉親社會福利：爭取YouBike專用道，改善與汽機車爭道問題。","鄉親社會福利：改善大眾運輸，提出獎勵方式以減輕市區塞車困擾。","鄉親社會福利：要求縣府增加交通工程預算，修整老舊橋面及路段。","在地就業環境：推動地方勞工權益及中小企業輔導。","在地就業環境：建立創業基地，提供青年創業者相關設施，提升縣民創業意願。","在地就業環境：增設職業訓練中心，開設符合現今市場需求之課程，並幫在地企業媒合職工。","在地就業環境：常設議員服務處，讓選民方便聯繫及詢問。","在地就業環境：推動議會透明化，讓監督議員更簡單。","在地就業環境：聆聽鄉親的需求，協助各種選民服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d14ac998-0394-4e2c-b666-93216b707bf2","items":["2018政見落實 投資未來|連結在地|數位電競 80% 在地創生|清新通暢|智慧城市 95% 多元學習|取消朝會|安全綠能 85% 擴大公托|區域均衡|把關品質 70% 加強勞檢|公開檢驗 80% 喘息服務|社區照護 75% ------------------------------------------------------------- 2022 漂亮台北 力挺青年","廣告招牌管理、巷道纜線清整、電桿地下化，設立市容委員會，找回城市歷史紋路。","花博園區回歸會展用途，打造北市第三座世貿展覽中心，帶動中山、大同區域發展，結合在地文化走向世界。","增進國際交流，議會互訪，分享地方自治經驗。提升台灣首都能見度，強化城市外交關係。","用路平權|以人為本|交通安全：提倡以車向分流為主的交通計畫，減少車流交織，汽機車路權平等。","用路平權|以人為本|交通安全：增設實體人行道，檢討巷弄違停、騎樓佔用問題，營造友善行人、輪椅族及嬰兒車的通行環境。","用路平權|以人為本|交通安全：廣設行人庇護島、增設導盲行穿線、設置通學巷、公車全面安裝智慧防撞系統，提升用路安全。","用路平權|以人為本|交通安全：居住正義|力挺青年|綠能減碳","用路平權|以人為本|交通安全：調降社會住宅租金，確保家戶可負擔。","用路平權|以人為本|交通安全：提高租屋補貼、簡化申請手續隨到隨辦，減輕年輕家庭經濟負擔。","用路平權|以人為本|交通安全：加速更新電動公車、公有房舍導入綠能、檢討氣候預算，跟上全球2050淨零碳排腳步。","用路平權|以人為本|交通安全：友善育兒|關懷長者|愛護毛孩","用路平權|以人為本|交通安全：校園閒置空間轉為公共托育家園及非營利幼兒園、提升準公共化參與、增進教保員勞動 環境，讓育兒更輕鬆。","用路平權|以人為本|交通安全：增加日照中心據點、媒合高齡長輩就業、重視長者心理健康，營造樂齡生活。","用路平權|以人為本|交通安全：推動市立動物醫療單位、增設寵物活動空間，毛小孩也是城市的一分子。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d18ed7df-eff5-461b-a692-71d6232d2502","items":["打造鶯歌外環道，分散市區車流。","新建鶯歌生命紀念園區。","加強區域排水系統，因應極端氣候。","持續爭取鶯歌公四公園興建多功能活動中心、運動休閒場所，政府機關辦事處。","推動智慧公車系統，增加公園、老街、博物館及各景點路線及班次。","持續推動提供清明公墓除草服務、鶯歌清潔隊服務中心興建。","加速興建捷運三鶯線、樹林萬大線、鳳鳴臨時火車站。","推動樹林、鶯歌鐵路立體化，消弭危險平交道。","新設北二高金城交流道。","推動土城司法園區設立生態公園綠地。","持續推動三峽長福及鶯歌公八公園停車場立體化、三峽河整治及長福橋改建。","爭取設立三峽大豹溪風景區。","持續推動設置各項親子及長者共融性特色公園。","督促市府輔導污染業者，加強稽查非法棄置垃圾，於污染熱區設置空氣、水質感測器，還給居民乾淨之生活環境。","設置寵物公園讓毛小孩及飼主有良好的休憩環境。","閒置教室，轉化為公托公幼並延長服務時間，強化社區長照機制；加強學校課後輔導，減輕家長負擔。","關懷弱勢族群，結合公家及民間資源，持續捐出每票30元之選舉補助款給社福團體。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"d2366ece-d3c4-4437-9d42-2961650b4701","items":["文化：增編經費、推展族語、傳承傳統手工藝、促進都市原鄉交流。","教育：兒童課輔、充實原民教育課程、推展部大教育取得大專學位、原住民子女教育獎助學金、持續爭取原住民部落大學經費。","幼老：增加育兒津貼、托育津貼補助、幼教福利；關懷長者，增設「文化健康站」、老人假牙補助。","青年：設立青創基地、青年會議、觀摩交流、原植培力青年。","勞工：安全衛生講座、職安卡訓練、勞工權益安全網。","社福：原住民微型意外險續辦（免保費、團保）、房屋建構及修繕補助、租屋租金補貼、健保自行額補助。","就業：就業媒合、職業訓練、暑期大專工讀、婦女創業研習班、職業汽車訓練補助、取得專業級證照市府補助。","體育：增編體育經費、促進縣市交流、培植原民體育人才、辦理各項體育活動。","經建：爭取「一區一聚會所」、爭取七堵社會住宅原住民保留戶、改善會館週邊環境、完成地區經建設備。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d2407541-aed5-463c-8e69-114fb3b5f643","items":["發展多元學習管道，積極推動官方第二美語政策，要求增加雙語教學制度、與強化特色學校的設立，並推動國際姐妹市學童交流。","積極協助推動學校成立棒球、足球校隊，培育選手強化足球與棒球根基，與協助建置國手培養的升學管道。","增加毒品防治政策預算，強化緝查與推動立法強制感化機制，建置防護網預防毒品進入校園殘毒年輕學子。","嚴格把關校園營養午餐並建置安全食品供應鏈，讓學童吃的放心；推動老舊校舍改建，維護學童就學安全，藉由改建爭取興建地下停車場，規劃獨立出入口讓學童安心上課。","爭取擴大不孕症的補助，包含年齡放寬及取卵次數的增加等項目。","積極推動台灣無形與有形文化資產古蹟保存；爭取松菸文化園區與台北機廠鐵道博物館串連與活化再利用，讓文化價值與人文資源得以傳承。","積極推動都市更新及老屋更新，協助文化藝術及活力注入社區型塑新風貌，並爭取放寬老舊房屋附掛電梯或爬梯機之條件及法規。","鼓勵都更加速，爭取大眾運輸導向型發展TOD 升級版，將公共建設的「社會住宅」周邊500 公尺範圍納入都更推動區，提高容積獎勵回饋公共空間設置托嬰托老設施。","已爭取完工的健康公宅、動工中的廣慈公宅與即將發包的三興公宅及六張犁公宅規畫及興建預算超過315 億元，並爭取降低住宅租金費用，未來也會持續協助中央住都中心興建社宅數量。","以尊重民意協助推動催生民生汐止線興建；積極爭取中央預算補助捷運南北向東環段興建，建置完整捷運路網，改善信義區縱向交通便利。","已爭取台北市動物保護專戶設立，由動保處規劃設立執行方針，擴大動物救援、媒合民間協助，以利動保資源整合。","針對虐待動物累犯已正式提案除加重處分及刑事責任外，並須強制接受感化，協助中央與地方推動立法。","法制化寵物飼養與照顧指南，提升飼主的責任；並建立其他非犬貓小動物絕育補助、及收容場所的規劃。","持續推動市府閒置空間作為青年創業辦公室及青年創業貸款零利率，鼓勵青年創業。","支持國內服裝設計產業，全力媒合在地設計師與國際接軌；推動時尚設計平台，提供設計師由校園育成階段至創業之協助。","落實長照在地化，建置社區照護機構爭取照服員居家照顧，並持續要求市府恢復發放重陽敬老禮金及推動滿65歲長者假牙補助與視力健檢。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["past_achievement"]}}},{"claim_id":"d28e2adf-4857-4704-98e1-10f1a7543421","items":["監督縣府施政，落實地方建設。","爭取充實消防服務量能，保障縣民生命財產安全。","關懷婦幼、青少年、老人權益，照顧弱勢族群，推動社會福利。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d2a91c3a-e7d8-4091-b321-009dc211f4ba","items":["監督縣政","爭取建設"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d2d8acaa-1884-4df3-9182-92426aec6a56","items":["國道七號開闢前,規劃足夠之港區大型車替代道路疏通運輸流量,確保小港交通安全順暢。","大林蒲遷村條件從寬從優,爭取民眾應有權益。","南區焚化爐更新案由市府自建,維持純公益性,嚴格控制焚化量。","改善空污,工業區減碳,台電燃煤機組提前除役。","持續監督地下石化管線管理及預警機制。","督促205 兵工廠及亞灣區加速開發。","輕軌支線至前鎮漁港、穿越第二過港隧道到旗津。","推動五育並重的教育,打造優良學習環境。","推動反毒教育,反毒宣導應確實有效。","推動各里樂齡空間、全齡化公園,公共設施全齡使用。","推動無障礙旅遊、銀髮旅遊環境,發展友善觀光。","推動動物保護,建立友善生養照護環境。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"d2f65e5d-e051-4d0f-9d13-8e7d627e7151","items":["擴大設立雙語公托，爭取彰化縣內各國民小學從一年級起納入英文教學。","爭取嬰幼兒A型肝炎疫苗補助，降低家長自費負擔。","認真問政、落實地方建設。","全力為弱勢族群發聲，爭取照護和福利，加強照顧老人、婦女、兒童及弱勢家庭。","爭取國中、小營養午餐提高費用。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d2f6b364-873e-4d07-bdf3-dc759cbb06f6","items":["乾淨選舉、理性監督縣府施政、杜絕貪汙瀆職、誠信服務。","督促縣府積極進行全縣土地使用計劃，推動城鄉發展擴大都市計劃，以縮短城鄉差距繁榮地方經濟，提升就業機會。","推動改善區域排水，避免豪雨成災，保障人民生命財產安全。","督促道路拓寬工程，並推動全面電線電纜地下化，以改善道路景觀及居住環境。","爭取設立農產品產銷中心增加農民收益，活絡地方產業文化，促進地方繁榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d39b24ae-f59a-46fe-8a8c-b95caf7b6542","items":["全力爭取鄉親權益","專業監督政府施政","督促政府發展產業","爭取實列原鄉預算"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d3a1f273-942d-4590-9f5c-2c4733baa928","items":["監督縣政，讓嘉義縣朝向農工大縣大步向前行","爭取建設，讓義竹布袋成為是一個宜居的鄉鎮","爭取銀髮族相關活動設施，讓長者可樂齡生活","爭取擴大工業區開發範圍，增加民眾就業機會","爭取地方特色產業行銷機會，增加農特產銷售","整合政府及民間資源，投入教育縮短城鄉差距"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"d3c8a651-9992-431d-af17-10d995e5a4fa","items":["推動閒置空間活化再利用。","推動增設社區公共托育家園,減輕小家庭的負擔。","結合政府與民間的資源,持續關注銀髮族、弱勢族群的照護及福利。","推動設置YouBike點,連結偏鄉,帶動當地觀光。","強化青創基地的功能,輔導青年創業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d43ba1da-3d89-44db-8e7b-3b5235169e8b","items":["嚴格監督縣政預算執行,杜絕浪費公夭。","持續推動名項基礎建設,提升民眾估質生活環境。","督促幼兒托育服務品質,保障幼童受照顧權。","持續爭取設置特色共融式遊戲場,重視兒童遊戲權。","督促提升長照、養護中心佈建率,保障銀髮族健康照護。","督促重視婦女各項福利權益及人身安全,建構友善婦幼環境。","督促強化衛生醫療環境改善,提升醫療照護品質。 一","持續爭取升級青年事務設置層級,溢實推動青年事務發展。","健全在地農特產品輔導、推廣與行銷,積極拓展銷售通路。","推動觀光與文化整合加值發展,創造在地觀光特色產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d449d0e2-8f15-41ef-94eb-98fdd1858125","items":["八年首長行政經驗，專業監督縣政。","強力監督垃圾處理，焚化爐營運安全。","傾聽民眾反應，協助解決人民的需求。","推動縣政觀光發展，建構安全、整潔、友善及交通便利的觀光城市。","爭取農、漁民福利，整合農、漁產業通路，協助農、漁民行銷台東農漁特產。","提升警察、消防專業配備，守護民眾生命財產安全。","扶助婦幼弱勢族群，落實長照2.0社區友善照顧網，提供普及、平價銀髮照護措施，建構台東高齡樂活友善生活圈。","督促縣府落實生活基礎建設，提供市民優質生活環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d4583b25-26ad-4a57-ab84-f3649297fa07","items":["公立幼兒園及非營利幼兒園比例，減輕家長負擔。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d493a215-b575-4996-a520-b6195af0ed33","items":["督促縣政府對於人民申請案件,建立透明查詢機制,以掌握時效。","打造南投一日生活圈,建構更便利的交通網絡。","建請縣政府盤點公有土地,主動釋出,以共營方式提供地方創生、生產場域,留住青年。","重視長輩的身心照護,加強推動各項福利措施,營造友善環境讓老有所養,老有所依,人人能安 居樂業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d4a0fa1b-7e57-48d3-8b91-eb6b17c16576","items":["深耕基層，反映民意，監督縣政，撙節公帑。","持續推動港埠建設，提升海運及港埠作業安全。","強化長照計畫，提升醫療健康照護品質。","優化旅遊環境，提升觀光產業發展。","提升教育環境設施及資源設備，精進教學品質。","關懷弱勢族群及新住民生活照顧，保障就業機會。","重視勞工權益及福祉，輔導青年創業，創造多元產業。","爭取解決廟宇土地之爭議。","爭取基層建設，推動及營造一村一特色優質居住環境。","爭取簡化合法建物申請流程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d4ae2e21-3e95-4704-bbf4-cc85926988b6","items":["（一）重視社會福利，照顧弱勢族群及婦孺的權益。","（二）推動觀光建設，促進在地農業升級。","（四）改善道路交通安全及基礎建設。","（五）積極督促政府施政、增加地方就業率。","（六）妥善維護環境生態、改善居住品質。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d4b39520-4978-4e27-81fd-131f376f1a4d","items":["支持公民權下修至18歲。","反對家族干政，建立廉能縣府。","幼教向下延伸，逐年增設公立托嬰中心、增加收托人數，讓年輕家庭安心就業。","因應高齡化與人口結構變化，積極鼓勵生育，持續爭取辦理縣民生育補助，減輕鄉親負擔。","持續爭取經費改善幼兒園軟硬體設備、強化師資培育，提供優良學習環境，落實學齡前兒童快樂學習目標。","爭取設置公民館，開辦各類樂齡學習、親子共學。","爭取設置親子共融公園與風雨運動場，提供親子兒童遊憩、青年運動與親子旅遊新亮點。","爭取設置長照專區，引進民間資源設立養生村、失智照護及安養機構。","結合休閒農業區，促成產業合作交流，導入綠色旅遊，拓展休閒農業食農、食漁教育與生態環境旅遊行銷；輔導青年創意，活化利澤老街與廟宇節慶，打造五結鄉成為宜蘭國際宜居、宜遊亮點城鄉。","積極爭取中央及地方預算資源，合力推動縣政建設及地方整體發展，提供優質服務。","持續爭取經費挹注蘭陽溪口休閒農業區及冬山河休閒農業區，規劃休閒農業區體驗與觀光遊程，提高農民收益、促進地方農業發展。","持續結合縣內各鄉鎮高中職、國中小及體育會，培育更多優秀體育人才，協助縣內推展全民運動。","持續爭取五結、學進及羅東擴大都市計畫通盤檢討，因應五結地區未來發展潛力。","加速辦理清水大閘門改建工程，積極爭取增設抽水站，解決冬山河流域淹水問題。","持續爭取噶瑪蘭大橋及蘭陽大橋改建工程；儘速規劃開闢二結聯絡道191甲線至台二線路段，建構完善交通網，促進地方發展。","爭取於利澤焚化爐園區內設置溪南溫水游泳池暨多功能運動中心。","打造五結觀光品牌，利用冬山河水域、傳藝中心、閒置農田與清水利澤海岸，新創四季活動、打造地景藝術，創造五結旅遊新風潮。","遷移鄉公所、衛生所及戶政等行政單位，爭取於高速公路東側與五結中路之間設立行政園區與物流園區。","爭取打造傳藝中心至羅東火車站的傳藝路，成為醫療照顧、物流倉儲、地景藝術、行政中心等產業與觀光廊道。","爭取二結聯絡道、國五、大三結地區與五結中區的治水防災堤防工程，加快羅東北水網中下游水利防災工程。","爭取拓寬五結中路二結平交道至五結分駐所路段，並將二結聯絡道向東延伸至濱海公路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d50b80a9-02d3-4c62-987d-0ca6559300b7","items":[" 全面整治防洪、打造親水無災，讓民眾免於淹水之患，保障生命財產安全。"," 啟動希望城市、關懷基層弱勢，挹注社會資源、建置安全防護網，落實政策保障。"," 建構濱海觀光、活化海線經濟，結合自然、宗教與人文，連結農漁特產品，促進發展。"," 滿足產業需求、規劃整體開發，擴編工業區，營造優質環境，鏈結產業聚落，振興經濟。"," 捍衛土城權益、守護環境永續，要求城西焚化廠更新案後，不得增設處理設施；優先處理掩埋場垃圾，造林規劃綠林公園；明年度，增加回饋金及周圍6 所學校營養午餐全額補助。"," 守護生命財產、居民過得安心，啟動和順國宅公辦都市更新，改善整體生活品質與環境。"," 樂活健康安南、建構城市美學，全民運動館建設於九份子綠帶河道，提供優質的運動場域。"," 尋找合適地點、規劃設立泳池，完善運動設施，增進民眾健康與運動好習慣。"," 建構完整路網、推動海線發展，加速曾文溪大橋完工、規劃台61 線南延專線。"," 串聯交通網路、帶動區域發展，北汕尾三路至公學路六段道路開闢。"," 保障學生就學、解決跨區就讀，爭取九份子第二期校舍、PU跑道及操場，提供完善的校園。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"d5435035-0f80-4952-9816-b7aede1eefee","items":["爭取增設公立幼兒園，並協助私立幼兒園公共化","爭取補助老屋健檢及裝設住宅火災警報器","爭取成立寵物公園","鏈結國際，中等以下學校全面推動SDGs教育","監督市府興建平價公宅，落實居住正義"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d565dbfc-e74d-44c7-ae6b-7211749978ed","items":["完善現有公園設施，並爭取親子公園的增建。","爭取鐵路高架化及台中捷運南延等交通建設，彰化市作為本縣中心，應該跟上台中市發展的腳步，減緩人口流失。","持續爭取立體停車場的興建，改善車位不足的狀況，屏東市人口約19萬已經有5座立體停車場，彰化市人口約22萬如今才剛準備興建2座立體停車場，絕對有增建需求，以完善彰化觀光設施。","擴大友善人行步道及加強推動騎樓整平，彰化市區點到點之間距離並非遙遠，但因路程障礙多，導致行走不便；若完善路程，可將彰化打造成為如波士頓般行人友善城市。","完善自行車道劃設。","主張公共空間如圖書館或民俗館推動外觀美化，建構彰化都市美學。","市容改造，以補助的方式，從區域劃分開始，鼓勵屋主進行老屋翻新，營造城市新氣象，並協助青年返鄉創業。","落實雙語教育，逐步在全縣複製鹿江模式。","塑造城市形象，透過歷史建物或故事的整體營造，提升縣民對於故鄉的認同感。","廣泛種樹，仿效新加坡綠化經驗，建設現代綠蔭城市，改善市區內空氣品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d5760d30-ed69-4ef9-b741-a0ca3afb0b8d","items":["國寶擔任四任民意代表，以『感恩的心、走一輩子的路』不忘初衷 監督市府各項政策讓市民擁有更好的生活品質。","積極爭取65歲以上健保費全額減免。","監督機場周邊、頭前溪沿岸都市計畫及香山24里的城鄉發展。","爭取受工業污染農地，成立產業園區，解決農民因土壤問題無法耕作困境。","成立『青年創業育成中心』提供無償提供臨時辦公室以及法律、稅務申請青年貸款等疑問諮詢。","落實毒品防制，加強校園反毒宣導、強力反對廢除死刑。","機場周邊住戶福利政策爭取與推動。","積極爭取增設香山區『微笑單車you bike』設置點，解決交通問題＆推廣觀光。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d58539ba-840f-4345-a223-84475b9ddbd8","items":["監督心力量：實事求是，公平正義。","經濟心力量：擴大招商，增加就業機會，提高經濟環境。","親子心力量：增設親子友善公園，打造共融式遊具場地。","樂齡心力量：打造長青育樂中心，增加育樂設備。","農業心力量：拓展農產品行銷通路，廣設技術交流平台。","新住民心力量：加強落實新住民專責服務窗口。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d6289e4a-6526-4d65-a0ed-3012a2ab201a","items":["搭乘計程車敬老愛心卡單趟補助提高到一百元，並納入台鐵連線。","筏子溪迎賓廊道延伸至烏日建國路橋，並增設自行車道。","爭取幹線公車穿越南屯地區，特別是五權西路、向上路、公益路。","爭取南屯拖吊場儘速遷移，並改建為文化圖書館及停車場。","督促文中52儘快設校招生，解決文山地區學童就學之苦。","積極推動南屯水肥廠優化與遷移，比照臺中肉品市場模式。","早日催生南屯國際足球園區完成硬體建設，帶動地方建設繁榮，提升臺中足球國際水準。","持續督促推動道路燙平專案及共融公園陽光公廁建設。","比照班班有冷氣，督促市府向中央爭取學童營養午餐費用全額補助。","督促市府積極推動共享人力及電動運具普遍化，減少碳排放，邁向永續環境。","努力爭取溝墘里活動中心早日完成，兌現市府的承諾。","中台社區大型開發日益增加，水土保持的超前佈署應落實，減低民怨。","精密機械園區附近高壓電塔應儘速完成地下化，讓周遭居民免於恐懼陰影。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d66e1e90-9962-4680-874e-9a8ea5b3cd46","items":["改善國道一號豐原路段壅塞問題：拓寬后里-大雅路段，增設豐原交流道南出入口匝道","監督東豐快復建進度，爭取銜接新社129線，力拚2025年完成東勢石岡段，2027年全線通車","監督中橫復建進度，持續提升中橫便道安全強度，力促回復省道規格","實現「豐富專案」計畫，打造運動產業健康園區","力拚「豐原國民暨兒童運動中心」，2024年完工啟用，打造多功能運動中心","監督「白冷圳節餘水利用計畫」工程進度","爭取興建「旱溪堤外自行車道」，完善豐原大道自行車道路網","持續推動危老校舍改建，優化學習環境","爭取新建豐原漆藝館二館，保存發揚漆藝文化","加速活化東勢林業文化園區，再現林業風華","爭取擴建東勢客家文化園區，發揚大埔客家文化","開闢多元農產品銷售通道，強化農業發展韌性","緊盯不法農產進口查緝，杜絕非法農產於境外","爭取農業設備、天災農損補助，擴大農友保障","爭取登錄白冷圳為「重要文化景觀」，申請成為「臺灣世界遺產潛力點」","推動東勢納入參山國家風景區，整合觀光資源","落實氣候變遷因應法，推動2050淨零碳排配套","優化生養環境，讓父母育兒無憂","捍衛居住正義，加速社宅興建","擴大產業量能，協助在地就業","鼓勵青年返鄉在地創業，深耕家鄉青創力","推動80歲以上及70歲以上癌症二期長者，申請外籍看護免巴氏量表"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d69ffd05-0446-490e-bc96-b9b01f1a8938","items":["打造未來 煥然一興","增加親子遊憩設施：爭取新建親子生活館，同時檢視現有親子遊憩設施不足之處，並設法加以改善。","爭取提高生育津貼及喪葬補助：為了提高縣內生育率，應提高生育津貼；並提高喪葬補助減輕家庭經濟負擔。","爭取恢復國中、小營養午餐免費：檢視縣府財政，用於補助國中、小營養午餐免費之經費。","爭取增設公托及臨托中心：落實中央0-6歲國家一起養政策，減輕雙薪家庭照顧幼兒負擔。","單項體育運動推廣：推動落實三級制，讓優秀選手得以留在苗栗縣為縣爭光。","醫療資源整合：積極爭取設置急重症醫療中心及老人醫療照護中心。","爭取藥師公會定期辦理用藥安全宣導：協調藥師公會定期至社區及關懷據點舉辦用藥安全宣導，讓民眾更加了解用藥安全的重要性。","檢視並落實社區關懷據點：協助爭取更多經費提供更多元的樂齡學習課程，不僅是知識的增長，亦是心靈的滋養。","爭取每年於竹南舉辦啤酒節：爭取竹南啤酒廠與縣府合辦啤酒節，打造夏季音樂派對，期望此活動成為全台重要盛事。","打通海岸線自行車道：將極力爭取經費補助，完善區域內各景點設施，同時藉由打通自行車道來吸引遊客到此觀光遊憩。","活化閒置空間：盤點縣內的閒置空間，進行活化改造，引進文創產業也推廣地方創生。","督促改善各鄉鎮市街容美觀：督促縣府與台電公司及各家電信業者協商，將電纜線得以地下化。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d6a468c2-8102-4b8a-84d7-5f6680fe553c","items":["改正國高中歷史課本開羅宣言不實內容確保台灣主權。","傳承父親李文正前議員熱愛鄉土精神一人當選兩人服務。","環保局應實施省時省力省錢升降子母車定點收垃圾從大樓開始。","透天厝污水接管有補助公寓大廈污水改管也應補助才符合公平並提高污水接管率。","營造鯤喜灣成為世界級親水海岸通盤檢討整體規劃帶動地方發展。","輔導媲美四草綠色隧道四鯤鯓紅樹林自然生態旅遊。","廢止公職選舉每票30元補助。","解構台南運河水域營造親水環境帶動沿岸水上觀光發展。","利用河道港灣碼頭停泊遊艇帆船發展離島藍色公路使台南更具海洋城市魅力。","行政區單位應隨選區調整合併減開源節流增加老人福利。","督促建平8街西端、華平路尾拓寬、和緯路連接安北路、遠洋漁港連接永華路跨港大橋儘速完成。","恢復古都全馬設計一鯤鯓到七鯤鯓路線以建城400年賣點。","增加人力物力儘速結紮tnr解決流浪動物社會問題。","補助老人裝假牙經費能夠全部到位。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d6ca3abe-1a48-4452-a00d-25cbb9c62e2c","items":["對人的尊重：理想的社會要多元共融，平等對待每個個體，所以我傾聽不同族群的聲音。","價值觀念倡議：縣府應落實民主，以包容多元意見為施政原則，所以我要求縣政重視普世價值。","人與環境相依：我們依附自然、人文、社會、經濟各種環境生存，所以我關心人與環境的互動。","縣府施政效能：行政品質影響人民生活，預算應用在對的地方，所以我嚴格監督縣府施政品質。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"d7532f57-1233-4c67-8765-39061d9d259e","items":["生育補助及5 歲未滿6 歲學費補助加碼、0-2歲托育及2-4歲學費補助","青年入住公宅租金減免且二胎優先入住、產官學資源整合，協助就業發展","釋放學校機關閒置空間，增設公托、公幼與安養機構、社區活動和綠化","南機場和萬大捷運線沿線 TOD 等都更容獎提高，沿線劃定產業專區加速都更","西園整宅與艋舺大道周邊劃定策略型都更示範區，提高容獎帶動老舊社區更新","重陽敬老金加碼不縮水，萬華健康中心改建，完善銀髮族健康生活空間","繼續推動龍山國中與成功高中校舍做EOD 整體規畫改建","監督東園、萬大和忠義三所國小捷運共構進度品質，提升學童就學環境","艋舺學園教育資源周邊學校共享，老舊校舍逐年分批改建、推動雙語科技教學","形塑商圈特色、輔導數位化轉型和店家改造，活絡商圈發展","艋舺公園街景再造、結合商圈市集景點，串聯局處活動，振興經濟帶動觀光","建構智慧監視系統、結合警政社區巡守、加強校園安全，建構生活安全網","監督萬大捷線施工進度，周邊公共建設加強與在地藝術化","繼爭取南門市場改建後，監督漁果菜市場和環南市場順利改建","推動東門和西寧市場改建，市場夜市精進計畫補助，優化環境共同行銷","公園學校增設地下停車場，機關學校下班課後停車空間開放","新移民家庭生活支持就業輔導、監督福民平宅西寧國宅改建、保障弱勢居住","開放民眾通報髒亂地點、蚊蠅孳生與污染源，市府48小時清理","疫情影響的失業或收入劇減市民，實質經濟協助與就業輔導"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d795187b-a88f-4995-b445-438eeafa935e","items":["建議縣內閒置建物活化再利用，轉型為社區長照或社區協會關懷服務據點。","持續推動青年返鄉，發展e化科技農業，提升農產品價值，以增加農產收益。","輔導申請休閒農場，發展田園民宿觀光，增加當地多元休閒農場的獨特性。","持續推動花蓮縣內石雕藝文對外展覽及交流，以增加花蓮石藝品對外的能見度。","持續推動縣府增加綠能產業，如電動汽機車、太陽能設備，減少碳排放量。","建請縣府鼓勵第二胎、第三胎以上生育津貼，以增加花蓮縣民人口數。","不分族群，鼓勵新住民（大陸、越南、菲律賓、印尼）積極參與社區活動。","持續推動維護客家及原住民等各族群文化語言、技藝傳承的工作。","為民喉舌，監督縣政，做好人民與縣府溝通的橋樑。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d7cc1718-3c9d-4ed2-8638-bcb4cb44fb73","items":["西屯會更紅 矽谷+曼哈頓! ．推動國際會展產業，讓台中產業躍上舞台。 ．加速半導體聚落成型，打造西屯成為亞洲矽谷。 ．水浦經貿招商金融業，打造西屯曼哈頓特區。 ．打通延伸市政路、漢翔路、拓寬福林路。","青有所居 老亦有所托 ．短期有屋住，長期有房產，「社宅」「平價國宅」並行推動。 ．青年成家、新婚育兒、三代同堂社宅優先加權、抽籤。 ．增設社區老人日照機構，增加照顧者喘息服務時數。 ．擴充仁愛之家建設增加收容人數，照顧獨居長者。","願生敢養 安心好成家 ．增加公托和公幼2歲專班，名額倍增為青年家庭減壓。 ．獎勵第二胎生育、托育津貼加碼，公托抽籤加權。 ．國小設立課後平價才藝，減少家庭安親費用支出。 ．增設親子館，提升親子課程質與量，打造優質親子空間與師資。","友善西屯 宜居又好行 ．人行道整平移除障礙物行人、娃娃車、輪椅族行得安心。 ．改善公園環境，遊憩設施全面安檢，增設共融式遊具，兒童安全拚第一。 ．中央公園結合在地機場歷史文化，美化升級成為台中新地標。 ．筏子溪廊道延伸至西屯改善河岸景觀，打造台中新門面。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d7e095db-52b4-4eeb-ac25-b75d7b13b4bb","items":["監督政府落實社會福利，照顧身心障礙及孤苦等弱勢族群。","督促政府輔導及開拓農產品銷路，改善農民生活。","結合政府與社區資源，照顧榮民榮眷及外配新住民家庭。","積極推動社區關懷據點活動，營建祥和社會。","強力督促政府招商引資作為，建構子弟返鄉就業願景，減少人口外流。","監督警政預算及執行，加強保護婦幼安全。","要求縣府寬列教育預算，有效落實貧困、單親、不幸兒少、失能弱勢家庭之照顧與輔助。","爭取在地青年就業、創業優惠補助方案，強化在地青年競爭力，根留屏東。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d7edb7ae-fe90-4753-9f18-adc75b92ed70","items":["堅持為七美，鄉親擺優先"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"d811812c-a74b-48de-82eb-1a689ef49b27","items":["建設：推動水利工程建設加速執行，持續監督雨水下水道及道路側溝清疏檢查，提升都市防洪標準。","建設：持續監督永康砲校遷移進度，加速永康創意設計園區開發工程。","建設：加強推動地方基層小型工程及里活動中心新建改善等建設，建構宜居城市。","建設：推展健康友善之運動風氣，監督推動永康首座國民運動中心落成啟用。","建設：監督臺南重大都市開發加速推動，帶動地方繁榮，如六甲頂醫療專用區、二王及五王等市地重劃。","交通：監督臺南標竿道路建設加速執行，如都會北外環道路、永康創意設計園區北側聯外道路及忠孝路開闢工程等。","交通：重塑道路型態，提升人行步行及無障礙設施，建構以人為本友善環境。","交通：加密公車服務路網，推動市區直捷幹線公車及厝邊便利公車。","交通：加速軌道建設執行，落實永康鐵路地下化及高架捷運單軌系統正式動工。","交通：推動公共自行車營運新模式，擴增營運服務站點，建構最後一哩路公共服務。","交通：落實居住正義，推動臺南公宅加速興建，如精忠二村、東橋安居及橋北安居等。","交通：提升親子互動空間，監督推動永康首座親子悠遊館落成啟用。","交通：維護弱勢長者基本經濟生活，發揚傳統敬老倫理精神，持續推動各項長者福利措施。","交通：持續推動精緻平價幼兒教育，擴大非營利、公共化及準公共幼兒園服務，並提升補助幼兒就學、降低就學費用。","交通：推動多元建置學生沉浸式學習環境，增加雙語學校覆蓋率，培養學生雙語能力，增進國際競爭力。","交通：監督推動溫室氣體管制、氣候變遷調適執行方案及執行各項淨零轉型減碳調適工作，打造臺南低碳永續願景。","交通：監督加強防疫整備、落實疫情監控、提升疫苗接種涵蓋率及強化民眾衛教宣導。","交通：加強推動營造婦女友善醫療環境、母嬰親善哺乳環境、孕產婦健康管理、生育保健、新生兒聽力篩檢、學齡前兒童視力、聽力篩檢及保健，落實婦幼健康生活。","交通：加強推動65 歲以上老人免費裝置假牙計畫，協助缺牙之長者有較佳之咀嚼功能以利營養之攝取。","交通：加強構築文化網絡系統，推動在地文化資源多元應用及創意加值，發揚在地文化特色及形塑社區品牌。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d885278f-5d31-4a1d-8995-fa37f5e166a7","items":["社福好、生活好、交通好 ! 給曾威4年，給您滿滿的3好 !","社福教育 老幼共好 ．將幼兒園遷入國小或新建幼兒園，將社區活動中心留給長輩使用，讓孩童、長者都有專屬的活動空間。 ．推動國中小營養午餐免费，家長每月省一千。 ．推動社會住宅興建，四年倍增八千戶。","友善環境 生活共好 ．公墓公園化，推動烏日溪埧公墓、龍井三德公墓規劃為運動公園。 ．爭取一區一全民運動館。 ．爭取各區增設大型親子共融公園 ．爭取烏溪、大里溪沿岸整治，規劃河濱公園。 ．加速推動生活圈4號線大肚段。 (烏日環河路一大肚護岸路一龍井西濱快速道路) ．加速推動大肚山遊園路一帶都市計畫規劃案完成，以利後續增建公共設施。","通行便利 交通共好 ．爭取台鐵大慶站到烏日站鐵路高架化、並解決學田地區平交道壅塞問題。 ．爭取捷運藍線新設坪頂站，提升大肚山生活交通品質。 ．爭取捷運綠線延伸至學田、高鐵特區，九張犁站設置南側出口。 ．加速推動大肚和美大橋興建與周遭整體交通規劃。 ．持續爭取更多公車路線，並增設YouBike站點，完善交通轉乘。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d886f0f8-a16b-49a4-ab33-8ff0cc822c9b","items":["打造孩童的空間：爭取更多公園與婦幼館。","安心回家的路：全面監督路平。","大眾運輸提升：加速推動公車與輕軌路網。","爭取機車路權：消弭車種歧視。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"d8a22250-18eb-4232-b718-a6187065fac0","items":["「為人民服務」是我們從政的宗旨，「捍衛原住民族主權」是我們的承諾，一起進立法院籌組原住民族「黨團」是我們的目標。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"d8e520cc-b682-4cf7-8efc-91248d99b3d3","items":["改善北區停車及交通問題 俞融將充分規劃北區現有停車空間，並運用閒置的公共場所，增加停車位，改善一位難求的問題。 俞融將協助推動捷運藍線四年內全面動工，加速核定紫線、橘線，完善台中市的捷運路網，有效解决北區的交通問題。","提升學生外語能力 北區是台中市最重要的文教區，內有三所大學及四所高中。 俞融將推動公立中小學增加外語教師比例，讓學生有更多機會接受多元文化刺激，提升外語能力。","力推社會住宅即刻啟動 俞融將共同推動四年內8000戶社會住宅動工，達到社宅總量14000戶，讓青年朋友在減輕負擔的同時，能有更多的選擇。","租屋人口眾多完善法規保障 北區租屋人口眾多，為保障承租雙方的權益和安全，俞融將推動修訂完善的法規，針對安全問題及設備維護提供必要的保障。","培育台中青年國際大使 與在地社團連結，共同推動國際事務活動，透過城市外交，讓台中，特別是北區，提升國際能見度。","爭取學生營養午餐免費及提升食安控管 俞融將全力推動學生營養午餐免费，並確保食品安全，讓孩子吃得健康、家長安心。","高齡房屋比例增加全面強化住宅安全 俞融將積極爭取老屋健檢經費及活化拉皮補助，保障高齡社區的建築結構、居住安全和環境美學。","北區水岸生活綠廊美化城市生態 梅川和柳川貫穿整個北區，俞融必爭取河川整治預算，營造北區高品質的自然悠閒河岸景觀，並帶動沿岸的經濟發展。","創造北區商機活絡在地經濟 後疫情時代，商圈發展要復甦，舉辦行銷活動，帶動地方活水。俞融將爭取更多商圈活動經費，引進人潮，促進北區商業發展。","強化長者福利政策 俞融堅定支持65歲市民健保補助，並推動老人假牙補助材質升級，將爭取更多長者福利，增進銀髮寶貝的生活品質。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"d9524568-4a80-423f-a404-02e54c0269d9","items":["雅芬當選議員即努力爭取重大建設,左楠要成為優質生活圈,建設仍有許多需要補強之處。雅芬期待您的支持,繼續為鄉親幸福+芬。","為主婦安心加分:雅芬是五個孩子的母親,最了解婦女需求。左楠托兒、日照據點必須大幅增加;多數長輩仍有社會參與能力,設長青局推動高齡友善樂活事務。","為青年成家立業加分:楠科(中油舊廠址,台積電將進駐)、橋科廠商提撥適當名額優先錄用在地子弟,工作期間結婚者,要求市府視財政狀況補助房租,生育者發獎金。","為教育質量加分:爭取楠梓國小新建校舍、增設藍田國小。未來爭取楠梓新設國中、科學實驗中學留在楠梓、高雄大學附設中小學,強化雙語、科技教學。","為洽公、活動便利加分:後勁設楠梓第二行政中心、高大特定區新建合署辦公大樓。增設里民活動中心;高大特定區藍田等三里、右昌國昌等四里、清豐里;爭取左營新光、菜公里與楠梓坑東寧等五里。","為交通順暢加分:左楠道路系統多處嚴重塞車,未來橋科、楠科車輛大增,園區西側與台1線聯絡道路、鐵路高架或地下化、消除「百慕達」、捷運紫線必須加速完成。","為生活品質加分:楠科開發不容許污染,後勁部落應都市更新。左楠老舊公園、兒童遊戲場必須重整,人行道必須整平。強化運動中心機能,增設夜間運動場地。右昌淹水改善計畫早日完成,後勁溪親水環境再提升。","警消待遇加分:雅芬是警眷,深知警消辛勞。警消車輛、裝備、電腦老舊,爭取逐年汰舊換新。高雄市警察繁重加給為雙北市七成,爭取至同一標準。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"d9e5dfd1-cb9d-44ad-9936-aa2295531de3","items":["老城：守護老城文化。整合中西區文化資產的修復與再利用，訂定上位計畫，以台中州廳為旗艦領航，打造「城市博物館聚落」。","老屋：推動老屋再生。設置「都市再生中心」 ，推動公辦都更、連結公私跨部門資源，活化閒置空間，促進舊城再生。","老故事：再現中城老故事。推動文化觀光巴士串聯景點，配合西區爵士音樂節與中區鈴蘭通踩街，舉辦以舊城區為主體的大型藝術季慶典。","好玩：打造好玩公園。設置「特色公園總顧問」，鼓勵參與式設計，規劃「一大五中」：一個全市級指標型遊樂場、五個區域級大型遊樂場。","好行：發展好行交通網。持續推動人本交通體檢、落實車向分流取代車種分流優化公車路線及服務、加速捷運藍線進度、爭取YouBike站點佈建。","好地方：建設中西區好地方。爭取西區國民運動中心、美村路地下停車場、麻園頭溪沿岸整治、推動歷史街區示範帶、台中公園全面升級、增加寵物友善空間。","敢拼：讓青年敢衝敢拼。推動社宅興建。發揮草悟道、審計新村、中興一巷、美術園道、刑務所官舍群、綠空鐵道、舊火車站等區位優勢，營造新創友善環境。","敢養：讓家長敢生敢養。推動生育補助加碼、提升育嬰留職停薪津貼男性使用比例、營養午餐再升級、心理衛生資源投入、貫徹兒虐零容忍。","敢希望：讓台灣人敢於希望。務實推動台灣獨立、非核家園、能源轉型、性別平權。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"da04bb42-672d-44e2-bd13-94b7729d6f21","items":["親子教育：北區增設公托、臨托、親子館。","親子教育：光華國中操場跑道、球場與校園通道徹底翻修。","親子教育：國中、小每週營養午餐加50元。","歷史文化：加速新竹監獄日式宿舍群活化再利用。","歷史文化：續修《新竹市誌》，保留歷史記憶、傳承竹塹精神。","增設You bike 2.0：爭取磐石中學、竹光國民運動中心、成功路、空軍醫院、舊社國小、金雅重劃區及南寮沿線增設YouBike 2.0。","公園翻新：改善境福里機場圍牆旁公園、南寮中光公園、港北崇和公園。","公園翻新：湳雅公園增設公共廁所。","公園翻新：持續推動南寮第五公墓翻新為特色公園。","纜線下地、號誌共桿：爭取中正路、竹光路、民富街、水田街、沛雅街纜線下地與號誌共桿，改善市容、提升交通視野。","纜線下地、號誌共桿：強化供電穩定，持續爭取南寮地區防災型纜線下地。","排水更加順暢：增建南寮地區雨水下水道，解決中寮、港北積淹水。","排水更加順暢：機場內增設滯洪池，解決境福、福林、士林、古賢積淹水。","交通優化：持續改善北區危險路段號誌標線。","交通優化：爭取55路公車復駛。","金雅重劃區：檢討交通號誌規劃、優化公園綠地、加速推動污水接管。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"da2fc974-8431-4d8b-8d19-b038802a217e","items":["時托育中心，「一區一臨時托育據點」減輕育兒負擔；健全幼教補助，普設公辦托嬰，提升私幼品質。","園安全，補足駐衛警和電子圍籬；落實小班教學，爭取國中小「情感教育」，社會問題從根本解決。","語教育，擴充國小雙語教育、外語師資及環境，提升下一代國際競爭力。","勢家庭與高風險家庭，簡化通報流程，追蹤後續安全照顧。","年創業，提供青創者諮詢服務與業界媒合，爭取提高青年創業補助。","年政策，創造友善職場 , 維護勞動權益；加速推動公宅；積極強化新創及微創政策。","保政策，關懷生命，打造友善動物城市；擴充專業人力，提升收容中心環境；推動寵物友善場域。愛護動物，為浪浪、","權益發聲，檢討動物領養機制，爭取動保相關措施，打造動物友善城市、推動特色公園，實現兒童遊戲權。","一路、基金一二三路電線、電纜地下化，改善市民生活與居住環境。","善基金一二三路交通及大武崙地區、安樂社區麥金路等區域排水，增強防洪功能。","舊安樂社區蚵殼港等各里增設停車空間。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"da379a12-d96b-4f98-809a-30ba32d400bc","items":["感恩楊梅鄉親相挺，玉琴從政20餘年，秉持著「同理心關懷萬家事、入里鄰建設好家園」的服務信念，有機會和大家一起努力建設楊梅，共同見證了楊梅的改變。監督市政、建設楊梅、服務鄉親，我都要求自己和服務團隊要面面俱到，大家都以「好周到」自我期許。","第二屆市議員任內，欣見工程經費將近8億元的楊梅體育園區運動場館新建工程已經動工；楊梅社子溪水系中的七條溪流整治工作已經逐步完成，投入數億元的護岸步道，已經建設成為結合景觀、防洪、休閒為一體的環狀休閒步道。秀才步道、福人步道、保甲步道已經修繕成為登山賞景的最夯步道。","楊梅持續在改變，天天在進步，生活品質持續在提升，楊梅區的公園設施變多了、功能變好了，多處公園甚至還結合興建了文康中心。里長和鄉親們反映的各里道路加封、瓶頸巷道打通、道路新闢與拓寬、交通號誌和標誌標線改善、電線電纜地下化路段持續增加等，限於篇幅，無法細數，歡迎大家參閱並持續關注玉琴的FaceBook臉書及line@，裡面皆有完整的紀錄。","玉琴為回報鄉親們的支持，將持續關注追蹤楊梅區榮平路（幼獅路二段至快速路五段）拓寬；富聯路道路瓶頸打通、豐興街122巷瓶頸打通、環南路80巷至校前路道路拓寬、裕成路二期道路開闢（至福涵）等建設與發展，繼續爭取鄉親們支持連任第三屆市議員，下屆任期將爭取市府善用楊梅區擁有4個台鐵火車站、中山高3個交流道的交通優勢，發展鐵道文化、茶文化、桃園仙草節等觀光活動，爭取在楊梅富岡設立國家級「鐵道博物館」，打造楊梅成為最宜居的城市。","第三屆桃園市議員選舉，玉琴再度懇託鄉親們繼續牽成！感恩！"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"dad10d28-5564-4952-a7c1-af2dfaee0557","items":["督促縣府增加城市綠覆蓋面積，打造綠色城市。","推動屏東科學園區發展航空、航太產業，成為屏東特色產業。","打造屏東市成為台、日、韓職棒春訓基地，發展運動產業、促進國際交流。","爭取高捷延伸屏東市，建立便捷大眾運輸系統，發展高屏共榮生活圈。","屏東新住民日益增加，爭取增設新住民科，促進文化交流，加速新住民融入台灣社會，打造多元友善城市！","面對高齡社會，持續推動社區關懷據點、長照、喘息服務，使青壯世代打拚事業無後顧之憂！","爭取65歲以上健保補助，增加敬老卡使用範圍，如火車、國道客運等大眾運輸。","屏東市已八年無資源回收車服務，爭取恢復屏東市資源回收車業務，落實回收環保習慣，便利民眾資源回收需求。","爭取屏南快速道路，改善屏南長久以來交通瓶頸以及假日塞車問題。","扶植在地表演藝術團隊、藝術家，進駐演藝廳、美術館、藝術館、屏東菸廠，舉辦表演、展覽，活化屏東市各大公共場館。","打造屏東城中城，規劃修復後的勝利星村成為屏東市觀光景點，結合歷史文化將周邊地區、商圈風格連貫設計，提高園區完整性。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"dae84e7b-3183-4781-93b7-ced24efbc465","items":["落實監督政府預算,預防舞弊案件,為弱勢群體發聲","建立社區醫療體系組織,整合醫療與社區,讓民眾遇到問題時能第一時間諮詢,並引導民眾至合適的醫療體系就診。","建立多點免費社區法律輔助資源,協助民眾解決法律的認知與需求問題","要求政府落實建立桃園托育、長照、就業三合一照顧政策,以社區為單位,建立平價有品質的老幼照顧體系","建立社會住宅概念,辦理社會住宅,持續追蹤桃園社會住宅進度只租不賣,打造租金合理、環境優質的友善住宅,讓年輕人、中產階級、單親家庭、身心障礙者和老年人都容易找到安心居住的家。","推動桃園社區駐點,上門照護主動關心整合社會資源,建立關懷據點","增列桃園動保預算,擴充動保專業人力,建立專業管制隊;落實寵物登記及飼主責任教育;補助犬貓絕育;推動認養代替購買,推廣工作犬、陪伴犬計劃;改善公立及民間收容所的照顧環境;加強繁殖場輔導,嚴格取締違法繁殖場;推廣生命教育。","增加多點串連警政巡邏據點,認養監視器維護,建立快打部隊群組,快速反應減少治安死角,打造安全居住合宜的桃園","假牙補助:增加補助款6萬,降低補助門檻原住民50歲,一般民眾55歲","交通建設:追蹤加速鐵路地下化,捷運三線安全建設","推動遷葬環保葬獎勵之辦法,鼓勵遷葬環保葬有提供2萬元獎勵金","督導區政業務,健全區里組織,暢通桃園市政府與基層溝通之管道,定期辦理里鄰長研習暨市政參觀活動推動里鄰資訊傳遞E化,鼓勵里鄰長能建立臉書專頁,或是Line公開帳號,讓里民們能隨時得知里鄰的最新消息","增加活動中心的透明化:網頁展示桃園市各區的實際活動場所圖,讓市民能夠瞭解各區活動中心擁有甚麼設備,租用使用金額也要公布於網頁中,甚至提供網路平台租借場地,推行各區的活動中心財務透明化,讓市民得知各區活動中心的營運狀況","桃園區大興橋改建(改建成協張橋面)可增加路面拓寬(改單側兩車道設計)改善行車壅塞問題(經國路&春日路)","(開瓶計畫)桃園區同德12街(費用:2億),天祥一街(費用:7千萬),桃園區南平路(費用:4億)開闢連接到國際路及幸福路開闢到中正路等","校園食安:持續監督校園禁用核食,萊豬確保學童飲食健康安全。 目前已要求教育局與農業局組成聯合稽查小組對於各校營養午餐加強檢查、督導","爭取校園:新增冷氣力求達到班班有冷氣,保障學童讀書環境","改變桃園文化沙漠的既定印象要求市府積極爭取文化招商,規劃引進大型樂園或是環球影城改變桃園,創造就業機會","推動桃園區小檜溪重劃區增設派出所,鼓勵設立桃園第二分局,完善桃園社會安全網","推動桃園全民運動風持續爭取設立運動中心,強化滿足桃園居民身心健康","推動市府數位轉型:整合52個機關罰鍰規費系統與完善桃園圖資,工務局道路普查系統、水務局水情資訊系統、都市發展局都市規劃資訊查詢系統、經濟發展局產業投資標的盤查及建置資料庫、警察局天羅地網整合查詢系統及資訊局整合式陳情列管系統"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"db05de4c-ea18-47ab-bbcd-ffe0f2984c6f","items":["落實「老有所終」老年人能長期受照護,積極關懷各村、里的社區設備及環境綠美化。","督促縣府重視台灣地理中心碑的開發,以結合在地的農產品發展特色觀光產業。","建請縣府積極修繕,規劃縣內景點觀音瀑布,以利觀光發展。","建請政府爭取補足警消人力,持續爭取巡守隊及義警、義消裝備經費補助,進行監視器總體檢,杜 絕治安死角。","強化校園毒品防範,提供師生安心教育環境,並持續關心校園安全的軟硬體需求,為師生、家長打 造安心校園教育環境。","尊重多元文化,督促縣府重視新住民,持續關心新住民,打造各鄉鎮市為多元文化共存共榮的好環 境。","敦促縣府持續對環境保護、垃圾、空污、廢水、有毒廢棄物等問題,要有效處理加強管制稽查。","持續關心流浪動物保護議題,爭取設置公辦流浪動物收容所,推動友善動物城市。","督促縣府積極推動埔里鎮開發福興溫泉農場,以埔里為新地標。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"db25fe04-132b-4213-a26c-3f082249ca65","items":["督促捷運環狀線儘早完成以利市民搭乘，爭取新莊捷運線延伸至桃園。","督促電影文化中心第二期儘速施工。","建議市府寬列體育、文化、教育及社會福利經費，增設市立托兒所，增加生育、獨居老人照護、中低收入戶、急難救助補助。","督促市府檢討規劃給孩童上、下學安全友善通行環境。","爭取各級學校教育普設86吋教學觸控電視設備，充實教學設備改善及教學環境。","督促儘速完成台65高架道路增設引道聯接高速公路，以改善五股交流道擁塞交通。","優先完成塭仔圳重劃區內30公尺計劃道路，疏導交通。","儘速完成塔寮坑溪及中港第三抽水站，以維護大新莊地區防洪安全。","增設兒童共融式遊憩場所，提供孩童優質活動空間。","督促儘速完成污水住戶接管，改善居住環境衛生。","督促規劃潭底溝及十八份坑溪為生態河川，改善沿岸鄰近住宅生活環境。","爭取新泰國小增設地下停車場。","爭取文高一設多功能運動中心及地下停車場。","徵收私有土地完成新莊文明文德活動中心與新莊國小球場共構改建，設公托、長照、老人、社區活動中心及地下停車場。","督促知識產業園區原司法用地興建多功能轉運站。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"db7c3788-fd69-4648-a098-83d46f907231","items":["反對家族干政，廉能宜蘭縣政。","支持公民權下修18歲。","爭取建置更完善的員山童玩公園規劃。","爭取員山鄉開發多功能零售市場。","督促縣府提報員山鄉農地重劃案。","友善耕作富麗農村，爭取員山鄉設置有機生產基地及農特產品展銷平台。","爭取推動員山公園後方防汛道路貫通至台七線，作為疏解市區車輛的替代型外環道路。","督促縣府儘速拓寬金泰路、大園路、八甲路、內城路、榮光路、惠民路及枕山路自來水廠等道路銜接工程。","爭取員山鄉設置長者日照中心及體能運動中心。","健全員山鄉內及對外交通路網，提升觀光價值，帶動休閒產業發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"dba5f80c-14ca-40d1-819b-a46f21135da1","items":["活化東港溪沿岸","活化沿岸（內埔、竹田、萬巒、潮州）景觀營造與生態保育發展，利用公有閒置土地，打造河川綠色廊帶。","因應空間與環境可行性統籌整體規劃，提供民眾休閒遊憩與活動設施空間需求。","打造全方位枋寮漁港，「枋琉線」重現。 枋寮是南屏東最繁忙的交通重鎮，從枋寮火車站到枋寮漁港，步行到漁港僅10分鐘，站在枋寮漁港用肉眼也可清晰看見小琉球。目前只有東港、新園及大鵬灣3條固定航線，枋寮漁港則屬傳統漁港；枋寮鄉也曾努力爭取枋琉線但未果，宗廷將持續推動全方位的枋寮漁港，打造「枋琉線」藍色公路。","雙外環計畫，紓緩假日枋寮路段塞車壓力。 目前除了交通部核定屏南交通改善計畫，枋寮東外環路工程可舒緩枋寮路段塞車壓力外，宗廷建議拓寬強化縣道185號之利用。縣道185號北起高樹、南至枋寮，行經內埔、萬巒、新埤等鄉鎮；拓寬道路讓民眾多一條選擇的道路，同時可以避開水底寮塞車路段，打造枋寮雙外環，紓緩假日枋寮路段塞車壓力。","推動美食旅遊團，促進地方觀光收入 民以食為天，從內埔客家美食到竹田農特產美食，品嘗萬巒鄉的特色豬腳到潮州鎮燒冷冰，嚐遍新埤鄉的地方粄條與枋寮鄉漁水產海鮮，絕對可以讓旅客大飽口福。宗廷規劃串連鄰近鄉鎮美食團，推動美食旅遊團，協助鄉鎮促進地方觀光收入。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"dbeb06c1-16ef-435a-a7ea-5dba187c2c8a","items":["康寧街南下匝道，同興路延伸康寧街，吉林街盡速拓寬，交通立即可改善","推動二高南下銜接環東","推動汐止轉運中心","汐止站增設出入口並爭取無障礙空間至經貿園區","推動全國動保專線，並爭取興建汐止寵物公園","推動汐止棒球三級制，並爭取棒球場興建","台62線快速道路延伸至萬里","推動萬里行政大樓，公有市場都更，全新打造新商場，停車空間","提升北海岸醫療，長照服務，推動台大金山分院升級","打造北海岸深度旅遊，推動海岸線自行車專用道串聯"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"dcbca160-19b3-4945-aaff-72bceb8b15b6","items":["都市發展縫合，樹林鶯歌鐵路立體化！","長照公托升級，青年打拚無後顧之憂！","加速電纜下地，新北街道更整齊安全！","增加公園綠地，監督市政府落實都計！","改善車位不足，減少補挖路平真好行！","補足警力缺口，提升治安民眾滿意度！","公布塞車熱點，月檢討交通改善計畫！","重視綠色通勤，規劃完整自行車路網！","土城：人口快速增加公共設施全面升級","土城：完善土城交流道啟用路網規劃","土城：幼托、長照增加 生養照護政府幫","樹林：監督萬大樹林線如期如質完工","樹林：土地利用活化 都計通盤檢討","樹林：運動球場設備翻新、增設停車位","三峽：活化蚊子館 打造茶文化新商圈","三峽：空汙監測加強 維護居民呼吸權","三峽：長福停車場與長福橋一起改建","鶯歌：鶯歌車站原址改建不遷移","鶯歌：陶瓷老街設施改善、活化產業","鶯歌：美術館陶博館串連國際"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"dcc1856c-8c48-4af3-8d38-53e15f7352fa","items":["（一）打造長照友善城市：建設特色長照公園；普及日照中心，達成一鄉鎮一日照。 （二）多元功能社宅建立：推動建立社宅，將融入照護弱勢、創業青年優先、長照照顧等多元的社會福利價值空間。 （三）打造跨域數位整合醫療服務：推動行動醫療，用主動出擊來彌補資源缺乏的鄉鎮需求，消弭偏鄉醫療落差；同時盤點整合縣內醫院各科，避免資源浪費；推動打造 All in One 24小時整合照顧服務，補足現行長照制度的缺口問題。 （四）打造生活品味：進行全盤城市規劃，讓縣民生活、城市景觀融為一體，打造遊客賓至如歸、居民生活有品味的新風貌。 （五）增設運動中心：提高運動風氣，建設提升居民健康生活習慣養成的空間，重造宜居城市、建設運動之鄉。","（一）大眾運輸路線改良：進行合理的大眾交通路線規劃，以城市永續進步、節能減碳為目標，鼓勵縣民乘坐大眾交通工具，推出宜蘭縣縣民公車10公里享有免費優惠，鼓勵大家都乘坐公共運輸。 （二）自有運具永續化、便利化：推動自有運具的永續化，鼓勵縣民購置電動運具，能根本地改變宜蘭縣的交通運輸碳排放。廣設停車空間，並附有自行車停車場；停車場內設置充電樁與電動機車電池更換站。","更新軟體拚經濟：創造出永續城市、山海城市的品牌符號，這些軟實力工程，將成為宜蘭再次蓬勃發展的關鍵因素。打造宜蘭城市品牌。 （一）建立山海城市品牌：為宜蘭旅遊經濟創造新高峰。 （二）設置水上活動專區：開放並建設水上活動專區，吸引更多玩家聚集宜蘭觀光遊憩，打造更全面、舒適的水上活動遊憩體驗。 （三）整合地方創生系統：整合縣內地方創生者搭建創造平台，改善投資環境，讓更多工作者加入旅遊創生的產業鏈行業，打造更加精緻有底蘊的城市品牌。 （四）國際旅貨更暢通：提升蘇澳港發展成旅貨運港口，接合具有地方特色的旅遊一條龍服務產業鏈，促進經濟發展。","更新軟體拚經濟：宜蘭有能力發展成世界知名的城市品牌，是真正的名山。若有機會為大家服務，我們將開大門走大路，整合地方既存資源，發展優秀軟體服務，同時合理分配中央統籌分配資源，投資在旅遊產業發展、城市品牌建立與社會服務建構，讓宜蘭成為世界性的觀光都市。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"dcfabc79-e935-4d3e-a4dd-c3ba4271144d","items":["檢視長照政策，提升安養品質。","落實幼兒照護，減輕家長壓力。","把關食品安全，維護全民健康。","打造專業劇場，扶植在地團體。","支持人文藝術，建設美麗家園。","推動纜線清整，減少跳電擾民。","健全城市路網，改善交通亂象。","爭闢活化用地，解決停車問題。","杜絕詐騙猖獗，啟動警民連線。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"dd1b4d15-1b69-4ccc-a237-718528e703f4","items":["健全社會福利,增加市民權益:督促市政府落實年幼及長者之相關社會福利措施與服務,強化婦女權益與人身安全保障。","活絡地方經濟,創造就業機會:加速推動前鎮漁港改造計畫,創造整體觀光經濟效益,督促市政府規劃發展地方經濟,扶 助商圈夜市經營,活絡庶民經濟,強化招商引資,創造就業機會,降低失業率。","強化社會治安,保障身家安全:督促市政府加強社會治安之改善,增添警力設備,廣設及維護監視系統,加強社區巡守, 確實保障市民安全。","改善交通環境,解決交通問題:爭取加速興建國道七號,保障小港市民用路安全,督促市政府增建停車場,紓解社區停車 位不足問題。","降低空氣污染,補助人民健檢:督促市政府嚴格管控前鎮小港工業大廠,要求提出改善並降低空氣污染,嚴格執行高雄港 區船隻車輛低硫燃油政策,爭取以空污基金補助市民健康檢查。3","點亮前鎮小港,建設美好家園:督促市政府持續推動新草衙、籬仔內、崗山仔等舊部落都市更新,推動危老建築重建,嘉 惠地方;儘速完成大林蒲遷村計劃,早日落實居住正義。","加強就業服務,保障勞工權益:督促市政府加強就業服務,保障勞工就業權利,推動就業管道,落實勞動檢查。33","爭取社宅興建,推動智能住宅示範場域:爭取社會住宅興建,並爭取將智能設施應用在社會住宅上,推動前鎮小港成為智 能社區示範場域,讓市民住的更安全、更便利。","爭取全齡化公園、保障兒童遊戲權:爭取多元化遊具設施讓老幼能共同遊憩,督促市府落實既有公園遊具維護,保障兒童"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"dd3cb926-bb63-4bea-bc99-4d1f4836706d","items":["串聯花蓮南區瑞穗、玉里、卓溪、富里等四鄉鎮及台東北區、東區等鄉鎮，組成花蓮南區 觀光圈。","藉由鄉長任內規劃富里六十石山行車路線的經驗，玲蘭將持續向中央爭取經費，使玉里赤 柯山及南區各農業園區觀光動線更便利順暢。","將瑞穗文旦柚、茶葉、酪農等農業，結合泛舟等觀光產業，共創雙贏。 農業：目前花蓮縣的農業面臨了許多困境，包括人工匱乏、工資上漲、肥料漲價，但所有的農 產品依然無法提升價格，讓廣大的農民收入減少，玲蘭會帶著農民朋友的期望努力，爭 取更多農業補助。 教育：繼續爭取公益團體及企業協助各級學校，並加強推動禮義廉恥、尊親孝道及社會的倫理 道德觀念。 人親，土更親，玲蘭腳踏實地的在南區土地上生活了五十年，了解南區鄉親的需求，請鄉親再 給玲蘭服務的機會。真心實意，為您發聲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"dd6448a3-3988-4c8a-a893-c1d3f36036dc","items":["虐嬰虐童零容忍，對重大違規業者予以撤照嚴懲。","捷運藍線四年內動工，疏解臺灣大道交通壅塞問題。","國中小學童營養午餐全面免費，減輕家長負擔。","老人健保及假牙裝設補助不中斷，增加關懷據點及長青學苑經費挹注。","促請市府完成市政路第二階段土地徵收作業，早日延伸打通到工業區段。","爭取打通漢翔路延伸至東大路段、福林路延伸至中科路段，解決中科園區上下班交通壅塞問題。","筏子溪完成全流域整治，推動西屯區段迎賓親水升級，營造水岸綠廊空間。","爭取水湳中央公園成為飛機航空主題公園。","持續推動居住正義，督促市府加速興建社會住宅。","落實環境汙染稽查及輔導改善，守護空氣水質不受汙染。","持續爭取路平、騎樓整平、人行道改善及無障礙設施。","敬老愛心卡使用範圍再擴大，搭乘計程單趟抵扣200元。","設立市立醫院及老人福利機構，健全台中醫療與長照體系。","增設公托、公幼及非營利幼兒園，並擴大育兒福利及津貼，讓年輕人敢生養得起。","提升警消及民防系統裝備配置，廣設及維護監視器系統，防範治安死角守護市民安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"dd8ab096-c26a-476c-9100-732f0ab5ec8d","items":["位於嘉義縣新港鄉與雲林縣元長鄉之界、跨越北港溪之崙仔大橋，興建至今已近40年，橋面寬僅8米，兩方會車險象環生，時常造成車禍傷亡事件；極力爭取重建，將橋面擴寬為18米，並增設行人及機車道，以維交通安全，總經費約9億8千萬元。","稻穀是本縣最大宗農作物之一，因應肥料、農藥、工資等物價上漲，增加農民成本，而公糧價格多年來並未調高，建議政府應調高公糧收購價格，保障稻農收益。","縣內6個分駐所（派出所）幾乎每所缺人，但該執行之勤務並沒減少，增加警察負擔，遇有狀況增加風險；建議上級單位儘速補足編制名額，以維警察權益及治安效率。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ddafd0db-b6e8-42ea-816e-5538a4b30391","items":["推動老人長期照護升級版，減輕老人及家屬醫療負擔。","推動安心成家，生育、托育、教育，無後顧之憂。","爭取興建串聯高鐵、台鐵、森鐵，三鐵一條龍（台鐵支線）。","推動西區大開發，建設為繁榮的嘉義新都心。","爭取西區設立公立高中職。","推動全民體育運動，更新場館設備，安全活動空間。","爭取多功能全民科技電子競技館，發展電競科技。","爭取產業園區，留住年青人在「嘉」，創造就業機會。","推動政府大數據執行，提高行政效能，便民大躍進。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"dde23055-bc85-4785-adfe-5c6763588130","items":["堅持正直、重義、同理心的服務理念，為布袋、義竹鄉親打拼。","堅持監督縣政平衡發展，維護布袋、義竹鄉親、新住民同胞應得的權益。","堅持督促縣府推動科技農漁牧業，有效提升產值、減少勞動力付出，並降低損害，藏富於鄉親。","堅持督促縣府落實並提升長照、日托服務，確實照顧、維護鄉親幸福、安心的生活。","堅持督促縣府徹底改善區域、村里及農漁排水，有效解決社區及農漁牧產業，免除鄉親水患苦境。","堅持持續督促縣府加強廣設路口監視系統及照明設備，維護社區治安，讓鄉親安居樂業。","堅持爭取資源，致力發展布袋、義竹觀光產業，並推展在地特色宗教、民俗、文化與藝文活動。","堅持制訂政策，結合政府、慈善團體資源，強化弱勢鄉親服務與照顧。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ddf580b9-92ca-4970-a73b-4b86b2a30c07","items":["每位產婦坐月子津貼1萬，保障產婦基礎營養。","補助每位新生兒之安全座椅4千，保障嬰幼兒童乘車安全。","讓全縣155間國中小營養午餐優化，從最低標案方式改成最有利標，讓學童吃更好。","邀約跨局處把關學童交通車安全、稽查補習班師資良民證。","不定期稽查校園飲水機濾心品質，學童喝得更安心。","建置食農教育教學資源平臺，讓國產食材內容深入校園。","繼續盤點地方需求，爭取中央與地方建設工程經費。","舉辦法律座談會，與民共同提升法律知識。","推動性平講座，同時支持18歲的青年爭取公民權。","打造嘉義縣最大運動賽事「跑若飛天公盃路跑」，共創地方商機。","推動社區營造、農村再生及地方創生，帶動地方多元發展。","栽培地方學子成為舞蹈運動國手，將來為國爭光。","復興朴子真人藝閣文化，維護地方傳統。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"de6ffe7a-1c15-4e58-9845-bfe5135ec8c9","items":["推動都市計畫，縫合八德生活圈，活絡商業，打造八德成為桃園東區門戶。","打造生活圈路網，改善交通瓶頸、調整路幅並整平騎樓。","加速電纜地下化，清除廢棄纜線。","落實美學校園，提高公共建設設計品質。","增設公托及幼兒園。","推動教育創新。","增加特色共融式公園，打造孩子的遊戲場。","爭取小而美的社區型寵物公園，讓居民散步就能到。","舉辦多元藝文活動，鼓勵藝文團體駐村培育人才。","完善運動休閒空間，發展運動產業，成立運動發展基金。","打造地方創生中心，設立新創、青創園區，推動特色旅遊觀光。","推動八德長照醫院、中大智慧醫療園區興建、兒童早期療育、產後護理、長者長期照顧，並保障勞工權益及關懷弱勢。","全民監督施政，定期舉辦重大建設彙報。","公開服務處財報，議員建議款納入參與式預算。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"de75ac7b-a056-4788-b7b8-bfe426d69c0f","items":["強力敦促政府修改身心障礙鑑定辦法，放寬認定標準及身障者補助條件。","強力敦促政府優化醫療工作環境，提升醫護待遇。","強力敦促政府立即開發社子島，並解除陽明山地區之禁建。","強力敦促政府加速建造社會住宅並提升社宅品質。","強力敦促政府加強水庫清淤，推動水質普檢，並增建海水淡化廠及開發再生水場。","強力敦促政府推動公辦都更，增加容積獎勵，鼓勵危老重建。","強力保障本國醫師執業權利及醫學生實習名額，捍衛本國醫學生受教權。","強力敦促政府將迷幻藥品升級為二級毒品，俾能以刑法嚇阻並強制勒戒吸食者。","強力敦促政府廣設全日型長照機構，保障老者、身心障礙者生活需求。","強力敦促政府推動淨零碳排政策，以因應歐盟碳邊境稅法，並維護全球環境。","強力敦促國軍做好不對稱作戰準備，並加速落實潛艦國造。","強力敦促政府全力開發歐洲友台之非邦交國，以達實質外交之成效。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"de9c586b-a05a-485c-a204-1a5a3e999d5c","items":["優化高危險妊娠之孕婦權益：從產前至接生與大醫院打通綠色通道。","爭取六個月新生兒健檢提供補助。","爭取更多0至3歲幼兒專責計畫名額。","爭取地方兒童成長篩檢項目：針對兒童發展遲緩、內分泌及代謝異常進行篩檢。","對多童政策及連續照顧體系給予持續性補助。","爭取開發兒少多元升學管道。","爭取廣設公托。","爭取補助配套措施：整合公私營托嬰中心，並訂定托育體系的評鑑及監督機制。","爭取更多私立幼兒園加入準公共化。","活化長照體系，促進老幼共托。","活化特色公園並督促其維護。","打造戶外運動空間，如籃球場、網球場等。","建立流浪動物送養媒合機制。","製作寵物友善地圖。","定期舉辦文化議題、政策論壇，推動具體可行的文化政策。","結合古蹟、古圳、老樹等地景特色，形塑竹北文化新風貌。","關注新竹縣美術館興建設置規劃案，催生新時代的地方美術館。","推動「東興圳水圳文化復興運動」，打造東興圳沿岸成為竹北綠園道。","關注豆子埔溪改善計畫，還給竹北母親河美麗面容。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"dea629a3-4705-4850-a7fc-716e9a5b3793","items":["爭取外埔區大東里第一公墓遷葬及地目變更後建設為多功能停車場與綠美化公園或運動休閒中心、推動大甲美人山運動公園建設；聯結溫寮溪替代道路發展周邊生活圈，提供居民更多生活休閒空間。","國中小營養午餐補助，減輕家庭負擔。","爭取甲安埔區新增建公立托嬰中心及幼兒園，落實青年敢養敢生。","強化銀髮日照與居家服務、擴大共餐與健促、落實社區長照政策。","推動臨時保母托育平台、婦女平權與社會工作的推廣，媒合就業及社會安全網的落實。","爭取甲安埔區寵物公園暨設立動物專責機構，簡化行政流程處理相關流浪動物衍生問題。","閒置公有土地增設地下或立體停車場，解決停車空間不足，妥善運用公用空間再造，創造便民舒適的友善環境。","甲安埔區特定農業區改編，以利偏鄉產業發展；擴增大甲幼獅工業區，增加就業機會。","加速建置雨水下水道工程，預防氣候變遷所造成的不可抗力洪災。","電路管線地下化及共同管道建置，減少管線維修與道路開挖。","結合甲安埔文化觀光(大甲媽祖文化季、外埔區忘憂谷、松柏漁港觀光魚貨集散及大安媽祖文化園區)，促進文化觀光產業的發展，增加地方經濟效益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"debbde04-80c2-4d13-b2b4-4fb461495360","items":["### 教育品質提升","* 協助發展各區域特色教育。 * 推動幼老共園，實踐在地老化社會創新。 * 重視學童發展，汰換課桌椅，爭取可調式課桌椅。 * 推動新住民基礎教育、協助適應環境發展潛能。","* 活化閒置場館，整合產官學三方資源，拓展地方特色。 * 推動青創中心成立，扶植新創力，規劃文創市集，提升藝文產業。 * 增設自行車駐點、露營車泊點，創造新型態友善旅遊環境。","### 農業發展完善","* 協助青農返鄉，扶植農業產銷。 * 監督政府保障農民退休福利。 * 監督農田水利建設完善公共工程。","* 審視道路安全，規劃設置自行車、電動車、嬰幼兒推車、輪椅無障礙等設施。 * 設立停車格，重視違停問題，提升民眾用路品質。 * 改善民眾運動環境、公廁衛生，推動成立共融公園、寵物公園。 * 監督縣府空汙、垃圾問題處理，解決環保問題。","### 社福政策落實","* 提升心理衛教資源，照護身心障礙者及照顧者。 * 整合關懷據點資源，推動長者市集，傳承智慧，老有所用。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"df155553-dd1f-479e-aef2-99f03cc1f422","items":["無黨參政沒有政黨包袱服務不分黨派，鄉親優先。","照顧關懷弱勢族群共融，創造和諧社會。","爭取地方建設，縮短城鄉差距。","敦促警政機關落實地方治安，維護人民生命財產安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"df66f06a-9851-45bb-9768-8f1bde8f81fa","items":["從政多年，世正始終堅持：不收紅包、不炒土地、不包工程！為什麼如此堅持？因為每張選票都是選民的信賴與託付，不該是牟取自己私利的工具！今年仍將本此信念爭取鄉親們的支持，當然還有這些年的服務成績，如更新校園設施、改善社區環境、打通交通瓶頸、增加停車空間、協助佈設社區關懷據點、修訂建築施工損鄰處理規則以幫助弱勢鄰損戶、公廁全面換裝感應式水龍頭、推動胖卡餐車試辦計畫…等各種提高鄉親生活品質的服務項目。","提升托育服務：增加公托量能，協助提高準公托教保品質，協助年輕家長養育寶貝下一代。","建設特色公園：近年共融式公園概念興起，將推動港湖公園更新現代化，讓孩子開心安全成長。","加速日照佈建：臺北市邁入超高齡社會，日照服務需求逐年增加，有必要加緊增建長者日間照護中心。","強化青年服務：推動市府青年發展處升級，強化對青年族群工作、協助生涯規劃及社會參與之服務。","加強地方建設：路平、燈亮、水溝通、污水接管、停車空間增加、改善交通瓶頸，推動捷運民生汐止線及東環線盡快動工…"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","candidate_introduction"]}}},{"claim_id":"dfe91a82-203b-4bea-a6f6-d4c00311f36e","items":["爭取提高國中小營養午餐經費補助。","推動舊校舍翻新，營造優質教育環境。","督促早日設置航空城開發區內具現代化、科技化之新校園教育環境。","爭取各地區普設托嬰中心、公立幼兒園或準公共化幼兒園，解決幼兒托育困境，減輕年輕家長負擔。","爭取航空城開發區興建社會住宅與建立多處停車場，解決未來停車問題，並成立青年住宅專區。","增加青年創業貸款額度，免費提供青年專業技能教育訓練，提升青年本職學能，創造高薪機會。","督促早日完成清華大學桃園醫療及教育園區興建與提升醫療服務品質。","持續爭取興建大園體育園區早日完成，造福百姓。","積極爭取台15線至台61線、國二甲延伸第二階段路廊建置。","爭取「捷運輕軌」大園觀音線早日規劃興建，帶動大園、南港客運園區、草漯、觀音新生活圈的發展。","爭取機場捷運A15站航城路直接銜接國二東向道路，以減輕中正東路之交通流量。","國家級重要濕地「許厝港濕地」配合自行車聯絡網及遊客服務中心，督促政府做好完善的規劃與興建。","積極爭取市區瓶頸道路打通，建構完整市區連通網。","持續爭取大竹交流道改善，國二道往青埔特區跨越中正東路二段高架道路早日完成。","積極爭取五青路往青埔特區路段拓寬。","積極爭取國際路一段新街溪順水左岸堤防道路至民族街口，分流國二甲線至台61線車潮。","全力爭取拆遷戶提高重建補償價格，協助徵收戶早日重建家園。","督促早日完成安置街廓配地與安置住宅之興建。","爭取航空城開發區公園（公25）內建置龍樹坑路祭紀念公園，及其他公園內建置寵物公園。","爭取建置社區及各路口監視系統完整化，維護社會治安、提高破案率。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"e09aa4f7-f411-4e58-9021-15e4ef4850cc","items":["城市建設好用「興」 1.加速推動公辦都市更新程進程、建立自辦都更整合輔導機制。","獎勵民間參與危老重建計畫、爭取都更容積獎勵最大化。","設置數位智慧城市設施、擬定市容景觀、建築美學綱要計畫。 長者福利最「興」 1.落實長者居家服務、日間照顧、居家復健、喘息服務、輔具購買及無障礙空間改造輔助、公費安置、送餐服務、到宅沐浴、交通接送的服務。","輔導成立長者社團，鼓勵健康長者投入鄰里服務，社區托育、社會公益、主動學習等活動，體現敬老尊賢的倫理價值。","爭取65歲以上長者假牙補助、持續發放敬老年金，增加敬老愛心點數。 婦幼關懷好安「興」 1.提高生育津貼，整合社區資源，打造友善育兒環境。","增設公幼托兒機構與托幼補貼；因應國家雙語政策，加強雙語教育課程。","規劃學童與夜歸婦女安全回家通道。","婦女可申請3萬元一次性的凍卵補貼，往後3年也可申請一年5000元的卵子保存補助。 青年創業最貼「興」 1.結婚入籍永和生活的年輕人，每一戶可獲新台幣10萬元「成家基金」。","善用閒置公有房舍，成立青年新創基地、青年設計基地，並給青創貸款。","啟動疫情後經濟振興計畫，推動原有商圈再生活化，並發展永和主題旅遊及創意遊程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e0e8d6d6-a878-4edd-b2fe-5236a3ca423d","items":["運動建設：增設大型國民運動中心，提倡全齡運動。","運動建設：擴增不同類型運動場地，提升市民運動風氣。","運動建設：爭取培育體育運動選手相關補助與場地。","都市發展：要求煉油廠限期停工遷廠，爭取原址規劃高科技園區。","都市發展：加速推動工五工業區擴大，創造就業機會。","都市發展：要求市府續辦A7二期開發，落實土地公平正義。","交通建設：加速捷運棕線開工，完善北北桃生活圈路網。","交通建設：爭取跨區公車路網，滿足通勤需求。","交通建設：增設路口行人庇護區，停等安全受保障。","交通建設：人行道、騎樓設置無障礙坡道，讓長者、行動不便者及嬰兒車能夠安全通行。 兒童文教","交通建設：加速文青國中小及大崗高中建校進度，滿足就學需求。","交通建設：推動特色公園及大型共融式遊戲場，實現兒童遊戲權。","交通建設：更新校園環境及教學設備，提供優質學習環境。","社會福利：推廣多元日間照護中心，完善托老托幼服務。","社會福利：增設老人文康中心，提供多元課程，豐富高齡生活。","社會福利：關懷低收入戶、身心障礙、急難救助，增加社會福利保障。","社會福利：關懷新住民文化、語言學習、就業權利。","警消安全：爭取補充警察人力及消防員額，寬列預算精實裝備。","警消安全：爭取義警、民防、義消、義交、巡守隊志工之設備經費補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e0eca319-1cd1-4723-81ee-a90b8c8fbf81","items":["加速並圓融南門市場的整體改造","優先保障舊攤商權益。","檢討及因應消費型態轉變，開創更能迎客之商機。","結合並優化在地人文視角，以嶄新的歷史文創，再次呈現竹塹南門的價值與光榮感。","體恤“婦幼＂及“高齡長者＂，規劃“市區免費關懷公車＂每日上午與下午至少2班隨招隨停服務，以落實「老吾老以及人之老；幼吾幼以及人之幼」的中華尊養之道。","加速推動「客雅大道延伸通往科學園區及高翠路工程計畫」以利建構環狀路網的車流順暢，並有效舒緩市區交通的嚴重阻塞，此乃新竹市民刻不容緩的殷切期盼。","針對低窪排水措施因設施老舊、保養不周或建置不足等相關事宜，積極偕同鄰里長實施周期滾動式勘查與緊密聯繫，以防止並降低積淹水所造成的生活不便及財物損失。","配合已有積極照護獨居老人之鄰里，協助爭取適時的送餐人需、醫療物需…等，以填補家人因在職或外出所可能的照顧不足之處。","新竹八景之一的青草湖遠近馳名，吸睛且雅緻及應景的藝文休閒設施或親子活動及戶外教學及各項適宜安全的親子活動，定期或不定期的搭配新媒體文宣，積極推廣促進青草湖園區周邊觀光及活動。","打造新竹市南區商家達人AI雲端市集，並配合推廣、輔導在地店家、才藝達人，以提升庶民宅經濟的能見度及營運績效。","因應快速化高齡社會的來臨，藉用社區鄰里辦公室建立五十歲以上資深公民的長照自主管理的線上、線下知識教育，強化五十歲至六十五歲的長照協力志工時間點數回饋數位化機制，來彌補長照護養、尊養的人力不足之處。","藉由APP各項社群智能串流平台，定期及不定期推動新竹市南區在地各景點的活動，以利年輕族群的接收訊息及並前往參與。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e0efea8f-a5d4-486d-9500-573f30a15d04","items":["敬老愛心卡搭乘計程車、捷運、高鐵、公共運輸，每月1,000元。","前瞻停車，東南區立體停車場新闢(大台中轉運中心、公兒30)。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e1fcf7fc-2e9a-4f2c-b1f9-2335c1cd172d","items":["監督縣政執行,撙節公帑。","督飭農業發展加速推動地方建設。","重視民情為民喉舌,勤走鄉親聆聽民情爭取權益。","推動社會福利關懷耆老、弱勢族群以提昇幸福家園。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e214666a-5bc8-4835-8e88-5eaafc334bb7","items":["監督、連結、媒合、推動","以誠摯的心，為族人服務"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"e27f3386-f7e3-4c0b-9381-3e95d56a66f3","items":["教育&體育培植 1.推動全齡化族語學習制度，族語教學納入補教體制，設立模範族語家庭獎勵機制。","推動設立阿美族沉浸式族語實驗小學。","制訂完整體育人才培育及退役後輔導計畫。(包含全國原住民運動會選手之培植) 4.推動全國原住民族運動會「社會組別及傳統項目」運動員選拔機制設置。","推動原住民族食農教育園區設置、原民作物可食地景規劃。","文化發展傳承 1.爭取舉辦本市「原住民族嘉年華會」。","要求市府重新審定族群領袖選拔制度，尊重各族群推舉方式。","制訂各地區文化事務推動獎勵機制，鼓勵各族群推舉方式。","文化祭儀預算，除依人口比例外，應考量少數族群需求，給予相對應資源。","經濟產業升級 1.爭取本市境內各大產業園區之「原住民專屬空間」，前期租賃費用減半。","爭取設置原住民青創產業孵化器及加速器，編訂長期預算聘請專業團隊輔導陪伴。","爭取開辦原住民族傳統工藝職業訓練，並與企業合作，增加族人斜槓收入。","結合新興產業趨勢，輔導中高齡傳統產族人利用已具備之技能，開創其他收入。","爭取開辦新興創業工具之課程教學輔導，提升原住民族青年職場競爭力。","落實居住正義 1.訂定本市各河海濱聚落安置短中長期計畫設置。","保障現有原住民國宅之河海濱聚落遷移住戶之永久居住權益，推動「以租代購」方案，取得所有權。","爭取多處設置原住民族專屬社會住宅，持續爭取提高現有社宅原住民族人之比例。","整合中央及地方現有資源，增設青年購屋、族人租屋諮詢服務窗口。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e3c3ad0b-79d4-43ea-bc11-6d674ccf959a","items":["讓苗栗發展與市民的生活品質再升級。","照顧老人、讓長輩有健康、快樂、尊嚴的社區生活。","落實社會福利,加強關懷扶助弱勢團體。","活化特色商圈,規劃城市漫遊路線,連結觀光景點,促進地方繁榮。","加強推動各項公共建設與發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e3ccec0f-e6e9-47b8-b307-6023c9af00cc","items":["推動社區安親及多語學習，弭平城鄉教育資源差距。","爭取國中女生生理用品補助，解決「月經貧窮」的存在。","爭取老人遠距醫療服務及交通接送，解決長輩就醫不便。","協助農漁民轉型，推動農（漁）電共生，創造「海口新經濟」。","爭取沿海鄉鎮納入台塑免費健檢，督促六輕工安環保，確保員工和居民安全。","活絡海口相關產業，強化「青年創業金」補助，讓青年願意返鄉安居。","各地方創生及文藝推廣，結合在地特色，成為「海口觀光新指標」。","全力推動獨居長者、身障者、單親、弱勢家庭等各項社會福利政策。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e3f888cb-11a5-4fa3-8faf-ae61aa627294","items":["要求花蓮縣政府實施花蓮縣全民意外保險,讓全民生活更有保障。","弱勢的守護者 ~ 低收入戶、身障戶加碼投保醫療險,以免因為生病無法負擔自負額、看護費用而讓生活陷入困境。","未達中低收入戶標準之邊緣戶,無法補助者,有急難救助需求時,向各社團及慈善團體勸募進行救助。","爭取大陳新村主要道路開闢經費,創造都市更新之機會。","全縣老舊建築物外觀拉皮及增建電梯補助,更新市容,活化老舊建築物。","十六股大道延伸至美崙溪慈濟路,並擴寬美崙溪防汛道路。","擔任基層勞工、仲介業、建築業、觀光業、職業工會勞工代言人為業界、為勞工爭取權益,創造全民利益。","放寬沿海地區得依法建築之土地建築執照之申請促進觀光、民宿各類產業發展。","督促相關單位加速吉安住一住宅區、東華大學特定區、重慶市場附近遊憩用地等重劃、區段徵收時程,加速相關區域產業發展。","建議縣政府比照前任傅崐萁縣長時期,降低吉安住一住宅區回饋金比例。","加速新城鄉、吉安鄉、花蓮市,大花蓮都市計劃合併變更計劃,促進大花蓮共同繁榮開發。","督促相關單位,爭取花蓮市、吉安鄉路段,鐵路高架化,讓各重要路段恢復往日繁榮。 13 督促花蓮縣政府都市計畫科增設【核發全縣都市計畫分區使用證明】便民中心,一律每筆收費 20 元,以免民眾各鄉鎮奔波申請之苦。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e4216a69-c0c5-4410-82e3-3fb296337502","items":["爭取社區週邊與重要道路兩側之特定農業用地開放，以利地方產業均衡發展。","推動六級農業，強化精緻農業與農特產品品牌化、網路行銷，以利休閒農業發展，提升農民經濟效益。","推動青年創業輔導計畫與職訓，提升青年在地創業與就業機會。","爭取政府落實社會福利政策之公平，讓農業縣與六都享平等福利。","敦促都市計畫通盤檢討，活化新港、民雄競爭力，爭取建設以民雄和新港為核心的新都心。","督促河川疏濬整治，設置大型抽水站，解決低窪地區水患。","督促社區道路側溝與下水道定期清淤，以利環境衛生與雨季排水。","持續爭取新港台糖265公頃農場設置「台灣農業機械暨農產加工智慧園區」，以利區域發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e46a9611-7119-4a43-8051-60751111e443","items":["NCC轉型正義，保障收視平權","合理監督軍購，追蹤交貨期程","科學重啟核電，扭轉火電家園","解密疫苗採購，清查光電弊端","加速松信再生，更新鐵道博館","補助女性凍卵，提存人生選擇"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e4748697-448e-436a-bdb3-c161e016d74e","items":["爭取旗山區籌建殯儀館（非火化場），讓東高雄居民能夠尊嚴地走完最後一哩路。","爭取市府閒置空間成為老人長照或幼兒托育之據點，並推動老幼共學協助分擔照顧責任。","爭取東高雄地方建設，城鄉並進、均衡發展，讓在地青年有更多返鄉就業的機會。","爭取台84線延伸至甲仙區，並持續監督台86線延伸至內門區之進度。","持繽監督於旗山區設置運動中心之進度，完善東高雄運動空間。","重視偏鄉長輩就醫或日常接駁的便利性，並持續改善候車亭、提升安全性。","關注市府對於農民災害相關補助的審查合理性，保障農民權益。","為毒品防制擔任永遠的防毒志工，為打造無毒高雄而努力監督。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e4c988f2-608e-440a-9bc9-2694eb8b8159","items":["交通便利 完善公共運輸路網，推動海線鐵路雙軌化及山海環線輕軌建設、爭取捷運橘線延伸清水、藍線台中港站與港務公司大樓共構；督促盡速完成臺1線大甲及大安溪兩座橋梁改建。","觀光發展 打造海線觀光廊帶成為國際景點，持續推動綠能博物館、觀光漁港、鐵馬道等，帶動台中觀光產業發展；爭取國際航線航班至臺中機場，增加中部民眾旅遊便利及經濟發展。","幸福親子 持續支持海灣繪本館，續辦幸福親子藝文季，爭取「0-6歲孩子國家一起養」政策擴大照顧；續爭取學校設施改善，給孩子在安全舒適環境中學習成長；公共場所建立友善親子設施，讓父母能夠方便地照顧和陪伴孩子。","鞏固勞權振興農漁業 完善勞動法規，強化性別平等法律和政策，防制就業歧視，督促政府持續撥補勞保基金，以維護勞保與勞退基金的財源穩定，增進勞工退休生活保障。爭取整修灌溉水路；爭取農路闢建整修，輔導農民投入農業碳匯，協助農漁民取得貸款，健全農漁民保險及福利，繼續推動優化各漁港設施提供漁民作業空間。","安居樂活 爭取闢建休閒運動空間場所及增加公園綠地；完善海線自行車道路網；持續推動台中港北堤釣魚專區、龜殼生態園區、高美濕地、大安濱海樂園；鰲峰山、鐵砧山觀光服務設施再升級，爭取打造特色夜市和傳統市場。","青年未來 減輕教育費用負擔，私立大專學費補助2.5萬、高中職學費全免；減輕購屋租屋負擔，爭取擴大租金補貼、加速興建社會住宅；鼓勵青年創業，加強創業教育和培訓、建立創業資金支持機制。","健康銀髮 減輕照顧者負擔，建立完善的長期照護體系，增加老人照護資源和設施；鼓勵長輩參與社會和文化活動；推動友善老人的醫療環境，確保及時獲得治療和照護。","安心社會 爭取警消資源更全面，維護社會治安和打擊犯罪；擴大預防詐騙，建立完善的詐騙舉報和處理機制；督促加強防制酒駕，爭取道路改善，打造友善行人的國家。","壯大台灣 繼續推動壯大台灣相關的法案、政策與預算，並透過國會外交，深化民主同盟國家之友誼，促進經貿及各項實質交流，締造互惠雙贏、永續發展的合作關係。","永續家園 以生態保育、社會公平和經濟發展為原則，推動2050淨零碳排、建立永續城鄉發展規劃；推動綠色建築、低碳交通、低碳能源以及提升能源效率；加速台中電廠以氣換煤，在2035年之前完全去煤，還給人民乾淨的空氣；持續推動海線地區自來水家戶接管率普及化；以自然解方保護及修復生態，提高家園面對極端氣候的韌性；推動永續教育，從小培養公民的永續意識和行動能力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e54b141f-8bfb-48c6-a786-323f2a96b1d0","items":["推動沿海四鄉鎮合併成為10萬人口以上人口數之城市，促使城鄉平均發展並與台塑企業共生共榮。","推動麥寮港升級為工商綜合港，促進地方繁榮發展。","強力監督縣府施政方針，以縣民利益為優先。","繼續爭取經費整治河川及區域排水設施，使沿海居民免受淹水之苦。","強力監督台塑六輕廠之環保、公安等問題，以確保鄉民居家安全，生活環境不受污染。","繼續爭取企業優先錄用在地子弟就業，以落實敦親睦鄰政策。","要求政府單位及企業重視在地產業、生態環境、人體健康，持續推動專案補助。","推動台塑企業擴大健檢專案，為更多沿海鄉鎮居民爭取福利，並加速增設麥寮長庚安養中心（護理之家）。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e56efdbd-8795-4f3b-b658-02772a49d0ec","items":["全心全力做好選民服務，包含文化、教育、體育、老人福利、兒童福利、道路建設、水利設施、農漁業設施、地方特色等等。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"e56f3f94-e46a-4f75-b2e5-256ae4ede5d0","items":["推動長照據點普及化，結合地區醫療診所定期社區健檢，65歲以上獨居失智行動不便長者定期訪視。","檢討排水系統與改善河川與水資源污染及整治，提升防洪功能美化環境強力監督改善轄區排水問題。","推動地方產業提升與轉型，爭取優質就業機會，擺脫低薪惡名。","簡化青年創業獎勵補助政策，鼓勵青年人成功創業。","提升警義消人員裝備經費，加速老舊設備汰新，確保執勤人員安全。","廣推共融遊戲場域，打造育兒友善環境，建立全齡的無障礙公共空間。","推動縣內農業升級，推廣農產品多元行銷通路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e596b28c-8fdc-4d22-9a51-074e7d96a2c8","items":["基於國際「兩公約」及誠信原則，潭雅神居民應有免於迫遷的恐懼。","爭取潭雅神興建社會住宅。","爭取增加潭雅神公托公幼數量，提升托育品質及設施。","爭取改善各級學校教學及教室設施。","爭取特殊教育學生教育友善環境，健全特教師資。","爭取潭雅神兒童公園設立特色安全遊具。","爭取潭雅神輔導商圈成立。","爭取改善綠園道及潭心自行車道人車分道系統設置。","監督豐洲二期園區開發，盡速協議補償承租戶。","監督擴大神岡都市計畫產業園區規畫及區段徵收。","爭取機場捷運延伸至豐洲科技園區。","爭取推動潭子火車站周邊都更。","爭取頭家路開通至昌平東七路。","爭取潭興路二段拓寬。","爭取動物保護經費，關切流浪犬貓問題，讓台中成為動物友善社會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e596ec8f-eaef-4d35-9b28-4073b23cd023","items":["四大政見、十五項堅持，關切公共議題、堅持清廉參政、深植基層服務，強化市政監督功能，全力捍衛市民權益與謀求市民福利。","地區發展：強化勞動局就業媒合功能，為失業者提供多元就業輔導方案，保障勞工權益，留住優秀人才，擺脫低薪困境。","地區發展：持續爭取港湖建設，放寬容積獎勵、危老社區改建，加速都市更新，並監督都更處執行進度。","地區發展：打造傳統市場新樣貌，為傳統市場注入新元素。","地區發展：增進港湖地區觀光發展，打造白石湖園區及南港茶葉文化園區。","地區發展：捍衛港湖好山好水，推動關閉內湖焚化爐，改設環保博物館。","地區發展：全力改善港湖地區交通問題，監督捷運民生汐止線與捷運環狀線東環段興建期程，改善內湖科學園區及南港軟體園區周邊動線。","居住安全：爭取增建青年社會住宅，制定青年能負擔之社會住宅租金，政府帶頭降房租，讓青年租得起臺北市房屋。","居住安全：全力推動瓦斯儲存槽退出住宅區，確保市民安全及監督達使用年限之住户瓦斯管線汰舊換新。","居住安全：強化醫療衛生及健康中心之功能，推動弱勢醫療照顧中心及免費巡迴駐診。","居住安全：加強社區治安及員警巡邏，提升值班警員為民服務品質。","親子照護：有感育兒政策，包含：增加公托數量、提升托育人員就業率、閒置小學校舍改設為托育中心、企業彈性工時、凍卵補助。","親子照護：促進在地托嬰、老年人日間照顧，降低中低收入戶就業障礙，關懷獨居老人，並推動社區關懷、警民合作，提高生活及居住品質。","親子照護：爭取銀髮族長輩更多妥善照顧及優惠福利，包含：公立醫院65 歲以上免收掛號費、社會住宅增設長者入住專區、臺北市立聯合醫院進駐社會住宅設立診所、提升公立長照中心設置比例，社會住宅或閒置學區增加長、日照機構比例、提高長照中心工作人員待遇及福利，訂定相關管理辦法。","親子照護：寒冬送暖愛心活動持續發光發熱，讓弱勢族群孩子擁有快樂童年，得到應有照顧。","親子照護：推廣毛小孩領養代替購買觀念，改善收容所環境，落實寵物登記制度，增設寵物運動公園、全力打造動物友善城市。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e5a2e579-3bcf-4023-a4ce-8db565423217","items":["提升原住民土地價值：讓保留地能發展產業、也能順利貸款！ 結合原民會、環境部、農業部、經濟部、國發會、財政部等跨部會資源，調查全國保留地土質及環境條件，研究發展原生草藥及高經濟作物，結合地方創生與生技產業綜合輔導，並推動銀行受理保留地授信貸款，提高保留地經濟價值。","增進原住民勞工照顧：勞保補助、免費健檢、增進職業安全衛生教育！ 爭取補貼聘僱原住民勞工勞保費用，促進原住民勞工就業。以巡迴健檢車模式，提供原民勞工預防職業病健康檢查服務。提高原住民勞工職業安全衛生教育訓練比例。","保障原住民體育人才：專案培育、協助就業！ 修改《國民體育法》，保障各單項體育協會原民理監事名額。全面發展原住民社區、學校、競技等各項賽事，完善從基層到國手的人才養成，及專案協助退役選手就業。","紀錄傳承原住民文化藝術及人物故事：讓文化妥善典藏運用！ 結合政府、學術單位、博物館與產業界，數位典藏傳統到近代文化藝術內容及人物故事，如音樂、電影、文學、工藝、大眾文化等，以供研究、策展、推廣及發展文化產業運用。","族語發展 AI 化：改善族語學習困境！ 將各族族語資料及知識內容數位化，並導入生成式 AI，發展人工智慧化的族語學習工具（如 AI 族語家教）、族語應用工具（如 AI 族語翻譯系統）。","照顧族人居住權益：讓族人租得起、買得到、住得好！ 推動「原住民購屋貸款專案」並提高貸款成數。設置專線提供族人申請租金補貼、社會住宅、購屋貸款等諮詢，以協助族人安心居住、放心成家。","支持族人返鄉服務：讓公部門調任與升遷更順暢！ 要求所有中央部會於原住民族地區之所屬機關單位中，明定任用原住民比例，提供名額讓族人返鄉服務。","推動全民原教、落實族群主流化：讓原住民族受到理解與尊重！ 為破除層出不窮的網路霸凌和歧視，要求教育部與各級學校依據《原住民族教育法》製作教材、設計課程，提供學生、教職員全面的原住民族教育知識，促進族群理解與尊重。","深化原住民外交：讓世界看見台灣原住民族！ 深化南島民族論壇（Austronesian Forum）及原住民族經濟貿易合作協議（IPETCA）成果，並持續培育原住民族國際事務人才，透過國與國的原住民族外交，增進台灣在國際社會的正面影響力。","陳瑩將持續推動族群平等共榮、原住民族土地及海域法、自治、金融等法案！"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"e5a86d17-9f3a-44da-a853-dd147752a558","items":["府提升長照政策，爭取設置適合年長者之運動場所，以因應老年化社會的需求。","動「廣設公共托嬰中心及托育幼兒園」，並提升非營利幼兒園與托嬰等相關補助，以減輕市民育兒負擔。","多基礎環境建設及多元化工商業進駐基隆，提升青年就業機會與紮根意願。","地方傳統產業與市場發聲，督促政府以專案輔導其形象轉型，締造更多商機。","央於基隆市之閒置空間規劃為公有停車場，並提供合理收費優惠市民停車，以改善防火巷道停車問題。","督促政府重視學童體育發展相關經費與機會，以培育更多優秀選手。","的核心是人，唯有以人為本、用心思考、行動向前，才能與基隆共同奔向璀燦的未來！","忠一路及市中心地下道改造的成功經驗，進而推動步行城市，持續爭取系列友善行人和空間再造計畫，","容、提升生活品質、串連商圈、吸引觀光客。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"e5d90969-3840-41a4-b7a6-dd5ae6f5199b","items":["美麗新莊：整治福營潭底溝，去污活化又除臭","美麗新莊：爭取冷氣新市場，環境衛生又舒爽","美麗新莊：加速重劃塭仔圳，提升公園綠覆率","交通新莊：捷運轉乘要配套，機車格數不能少","交通新莊：聯外橋樑要檢討，汽車平權免爭道","交通新莊：區間測速要合理，壽山拓寬速限提","安全新莊：重劃區內零死角，監視器材還太少","安全新莊：全面提升見警率，民眾心安不憂慮","安全新莊：警用裝備再升級，員警放心去值勤","運動新莊：運動中心再增加，落腳福營南新莊","運動新莊：職業球隊在地化，回饋地方願景佳","運動新莊：夜間球場不熄燈，揮灑汗水投三分","教育新莊：結合輔大外語力，雙語教育接國際","教育新莊：在地球隊齊心力，重視體育拚奧運","教育新莊：產業園區技職力，在地就業興經濟"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"e62c7569-ffc3-40a7-aeec-055af3e23479","items":["爭取社區共食食堂免費。","提高老人安養補助金。","人口少子化提高生育獎勵金。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e63c71bd-aa46-4fe6-8caa-07bf971d0284","items":["加強督促縣政府對新住民各項福利及輔導措施，以利新住民順利進入社會融入社區。","加強督促政府機關維護各項戶外運動休閒登山步道等設施。","鼓勵生育，爭取學齡前幼兒托育照顧全面補助，減輕家長負擔。","全力爭取碧興路延伸至台中市環中路，以促進地方觀光及經濟產業發展。","主張在草屯興建大型醫院，提升醫療品質，照顧縣民健康。","解決山坡地開發回饋金、農地移轉增值稅問題，減輕農民負擔。","積極爭取投17線爽文路段繼續延伸至南中寮139線，俾利地方經濟及觀光產業發展。","環鄉道路投22至投26線（清水村－和興村段）完成後，繼續爭取投26線福盛村瓶頸路段拓寬，以維道路之整體性及交通出入安全。","中寮鄉觀光休閒產業推動，促使年輕人返鄉，提高農民收入。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e641c434-4250-4b67-9ced-29dbd07218ad","items":["「台北監督連線」民生第一4 大主張","推動公共托育：增加公共托嬰設施、公立與非營利幼兒園，減輕家長負擔。","保障青年樂業：提高青年創業貸款額度；擴大企業實習策略聯盟。","廣建公共住宅：公共住宅結合公共與社福設施，打造特色公宅；加速危老建築重建；提升社會住宅戶數。","增設樂齡照護：65 歲以上長者免掛號費，擴大敬老卡使用範圍；增加日照中心，到府沐浴車服務，老有所終。","個人政見：已實現長者免繳健保費、議會質詢網路直播等多項公開透明政見，展望未來冀望達成以下目標","支持18 歲公民權修憲：全球已一百多個國家，用法律保障18 歲公民權，籲請支持台灣進步的力量。","推動分包商在驗收後30 日內取得報酬：參酌歐盟法(Directive 2011/7/EU on combating late payment in commercial transactions) 以及美國聯邦政府之US Prompt Payment Act 規定，確保政府採購所有下包商在30 日內取得報酬，避免統包商挾其市場影響力，對下游分包商款項拖欠，違背公平交易精神並危及中小微企業與其職工之生存權。","推動降稅措施：這三年來受疫情重創，應對於娛樂稅、營業稅採優惠稅率措施，恢復昔日消費人潮與榮景。","向中央爭取財稅合理：牌照稅為地方稅，稅率中央明訂，中低收基本交通工具稅，多比房屋稅高，實有檢討必要。","支持廣建共融式遊戲場；淘汰老舊設施，加強安全維護，拓展市民休閒空間。","強化勞資爭議平台，督促勞工權益、職業安全衛生等教育訓練，以提升職場環境安全衛生及勞僱和諧。","持續監督打擊詐騙：率先質詢出國打工淪詐騙犯問題，要求科技辦案，強化消費者保護，確保市民財產。","要求合理建管政策：漏水鑑定金額過高，市民無法負擔，應予調降，頂樓加蓋政策相較其他五都仍有檢討必要。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e64afce3-a082-433b-bdab-203d27f29e1f","items":["大寮林園，于軒10大幸福「軒」言！ 居住環境我來拚！","打擊空、水污！強化污染監測。","爭取大寮林園民眾健檢補助，守護民眾健康。","積極推動污水接管工程；大寮林園排水系統進行總體檢並改善排水問題。 爭取建設我來拚！","替中庄、後庄爭取公園綠地結合地下停車場，一次解決休憩和停車問題。","林園要社宅＋運動中心！讓居民住得優質、動得開心。","推動捷運大寮林園線，讓兩區往來更便利。 守護婦幼我來拚！","爭取全面發放學童隨身警報器，守護孩子的安全。","三個孩子以上市府養，增加公托公幼的比例，提高私立補助，減輕家長養兒育女的壓力。 選區發展我來拚！","大寮、林園進行都市計畫重新檢討，以促進地方經濟發展。","發展觀光和在地物產，如大寮紅豆和林園洋蔥；發揚林園的海洋文化，規劃觀光路線，讓民眾感受大寮林園的文化底蘊。 于軒專業問政，勇於發聲！為您爭公義、捍權益、要建設！請守護認真做事的邱于軒！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e6e9456b-c8b6-4f4e-adeb-2f0c6821faef","items":["建立都更詢中心，至里辦公處巡迴駐點座談","興建都更中繼宅、推動TODxEOD公有建物活化再生","強化社區智慧安保系統並防治詐騙案件","增加多元托育補助方案、擴大公托覆蓋率","建立社區保姆平台、活化人力並減輕家長負擔","特色共融式遊具增設，協助公共遊憩場改造","公私協力增設日間照顧中心、住宿型安養機構","設置樂齡專屬健身中心、提供肌力訓練課、減少臥床期","以包租代管推動高齡換屋，並鼓勵青銀共居、照護交換居住空間","建設人行道無障礙設施，確保用路人權益與安全","持續推動東區門戶計劃、港湖產專區權益保障及內湖六座瓦斯槽遷址","補助社區節能減碳、能源自主設施","設計美學教育推廣、公私協力導入美學設計至城市空間及公用設施","串聯內科、南軟及新創基地，由民眾提出需求，政府作為平台，補助產業及新創研議解方","輔助產業低碳轉型、提供ESG諮詢接軌國際","保障寵物權益、建立動保視訊119APP、動保專家遠程指導救助","推動18歲公民權、海洋教育及多元文化等公民對話平台","公私協力為社會弱勢及近貧家庭提供社會安全網"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e709e4b3-c6d2-4073-ab3b-2454e3e9eec9","items":["主張嘉義市編列經費補助65歲以上老人免費裝全口假牙。","監督市府落實北排整治與清淤，解決水患。","督促市府將中庄里、仁義里、義教里、後湖里、頂庄里、荖藤里納入污水下水道接管工程。","要求市府做好路平，保障市民行車安全。","嘉義市鐵路高架化，監督市府做好高架化後都市縫合。","推動嘉義市觀光發展，串連嘉義山海景點。","為嘉義市原住民及新住民爭取權益，保障基本生活。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e75d7e05-821d-4e91-b459-1c8e9c3657b6","items":["推動文創古城翻新 農業加值、宗教加值、歷史加值；敦促縣府再造西螺風華，提升在地自我認同的光榮感；文創、經濟加值，結合觀光帶動濁水溪畔三鄉鎮發展。","改造生活、收入增加 持續敦促政府建立蔬果價格崩盤預防機制；監督提高交通、水利、防洪、農水路養護基礎建設預算比例；擴大辦理長輩關懷據點；敦促縣府把關國土計畫法，保障農民生存權益。","加速西螺觀光發展 持續敦促縣府爭取高鐵班次，新增高鐵西螺接駁公車；發揚西螺七崁文化，推動七崁武術文化園區。","落實耕耘基層教育 敦促縣府營造各校溫馨的閱讀空間，培養學生獨立思考基礎；加強改善弱勢學生受教不平等；持續推動武術扎根校園計畫；建構校園與社區優質體育運動環境；培養學生強健體魄與良好運動觀念。 西螺風華再升級，文創經濟再翻新；深耕在地李明哲，睿智幸福好抉擇。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e7839acd-3e54-4806-9c87-5f35f89c1708","items":["監督縣政，理性問政。","為民服務，爭取地方建設及老人婦幼福利，關注學生教育。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e7fec229-d217-4237-b048-ecff0f841107","items":["監督政府打造體育優質環境,落實培育潛優選手,發展體育觀光之願景","監督政府落實婦幼及老人照護政策,共同打造養生健康快樂島嶼","監督政府戮力營造青年就業環境,落實協助青年在鄉服務政策","監督政府落實教育政策,營造優質的學習環境"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e8018430-913b-4ce9-934d-8e4043c2c4c5","items":["盡速推動確認捷運路廊、務必及早通過環境影響評估、讓捷運工程進度早日落實、以帶動地方繁榮。","督促市府落實長照 2.0 及降低公辦幼托收費政策、敦使民間疾苦充分改善。","北五堵研發新鎮進度一直落後，未來將督促市府加緊規劃進度、以期地方因而共榮共享、並遏止人口外移及造就 更多就業機會。","監督市府落實路要平、水要通、燈要亮的基本建設政策，使基隆成為一個既宜居又友善的城市。","爭取更多經費淘汰老式監視系统，品質提昇、數量務必需要增加以彌補警力不足，確保人民居家環境安全。","在中央政策山坡地比例對基隆解編放寬後，將建議市府能借此機會簡化手續及開放既有道路用地販售，做為容積 移轉之條件，推動都市更新案件使多數危老能更新改建。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e88cc5ff-54fb-4355-adb2-7429e733c319","items":["監督路平品質，改善永春（東）路、黎明路等重要道路之平整，防止龜裂破損，保障市民行車安全。","全面體檢道路標線，改善路口人車分流設計。","盤點公有閒置空地，增設停車空間，停車資訊電子化。 友善幼托 防範虐童再發生 充足南屯教育資源","落實訪視輔導及評鑑，淘汰違法業者，資訊揭露公開透明。","檢視南屯區國小閒置空間，增設公幼公托。","嚴格監督南屯溪西地區新設國中期程與規劃，保障當地學童就學權益，並持續爭取足夠的教育資源。 藥有專業 把關健康我最行！","推廣藥師專業，完善社區照護。","重視醫療人員之基本權益，落實醫藥分業，保障基層勞動條件。","嚴防空汙 守護你我環境：督促文山焚化爐加速轉型、減少排放量，要求資訊、進度公開，定期執行健康風險評估。","嚴防空汙 守護你我環境：監督市府落實管制各項空氣污染源排放，明訂中火、中龍鋼鐵及排污工廠減排時程。","嚴防空汙 守護你我環境：提升南屯污水下水道接管率，讓工業區污水處理廠協助接手水肥處理，停用南屯水肥廠。 居住正義 宜居城市 監督社宅不跳票","嚴防空汙 守護你我環境：拒絕市府不當賣地賺錢、圖利建商，落實社會住宅興建。","嚴防空汙 守護你我環境：推廣特色兒童遊戲場，共融遊具合格零風險。 議會革新 勇敢揭弊 打擊不公義！","嚴防空汙 守護你我環境：開放議會，擴大公民參與，促進資訊透明化，議會紀錄即時公開上網。","嚴防空汙 守護你我環境：定時公布助理費流向，杜絕詐領助理費。","嚴防空汙 守護你我環境：去除議員特權歪風，杜絕關說壓迫行為。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e8ab79a3-a252-4b93-8b78-08bc3a29a597","items":["「安居樂業、世代連結」是我所提倡的主軸。我致力勤訪基層、傾聽民意，並透過多元管道監督市政，為民意發聲。","「歡迎回家」——安樂區為全市人口數量最高的行政區域，亦為通勤人口最密集的區域。目前我已實踐「安樂－內湖線」跳蛙公車，未來將持續推動9026+公車路線優化，並同時關注基隆捷運議題，致力拓展公共運輸服務能量，讓通勤族多睡一些且能早點到家。","「安樂三創」——創新、創業與創意。安樂區行政中心建物已逾40年，基隆市政府新市政大樓已著手規劃，安樂行政中心內部各局處也將歸建，此時應積極思考整合附近土地新建安樂區複合型行政大樓之可行性，提供停車需求、複合辦公空間、商場創業等服務。","「安樂樂活」——世代連結的管道之一是提供休憩空間，讓親子、長幼等不同族群能樂活其中。我將持續監督大武崙森林公園各期進度，並爭取擴建安樂三期公園，並要求持續盤點閒置公共空間，提供市民生活遊戲服務需求。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved"}},{"claim_id":"e8ec29af-d974-4076-af1d-d58192d13713","items":["持續爭取排水整治工程經費，以改善安南區在強降雨後淹水情形。","爭取65歲以上老人健保福利津貼全額補助，比照其他五都、採有條件排富。","因應外來人口移入重劃區，督促重劃區內民生建設進度，增加道路開闢，以求一併帶動地區繁榮。","安南區人口遞增，為地方治安，同時不加重警察勤務負擔，力爭市府補足員警編制，讓警民比同時維持平衡。","為促進產業發展，協助工業區廠商與市府溝通，改善園區內交通及道路等基礎建設，提升百姓就業機會。","爭取編列鄰長事務費比照六都實施，以符合公平正義。","為農漁民福祉發聲，農漁道路持續鋪設及維護，並督促市府做好穩定價格等相關措施。","注重民眾精神生活，爭取安南圖書館增加館藏，讓內部閱覽空間相關設施更舒適完善。","持續監督市府就天馬電台自2013年完成遷移後，原基地的開發招商進度。","關注國中小各學校特色，加強本土教育，融入傳統技藝，深植環境保育愛地球觀念，健全學生德智體群美均衡發展。","爭取安南區增加興建國民住宅，抑制房價高漲，讓百姓能有購屋期待。","爭取中央動漫博物館，落腳安南區台灣歷史博館園區。","爭取警察、消防、義警、義消、義交人員等裝備防護安全提升，以保護執勤救災時生命安全保障。","監督城西焚化爐運作，妥善營運狀況及地方回饋措施。","監督政府兌現各項婦幼津貼、幼兒教育等補助及長照施行政策，落實社會福利以照護百姓。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e940b280-16a1-407f-bcf6-ed863c1de6fb","items":["支持同意滿 18 歲公民投票權","推動成立青年事務局，建構輔導青年創業及就業","加速推動全市各區成立長照中心，強化照顧貧困失養老人","要求市政府完成虎頭溪沿岸整治工程，杜絕水患，確保市民生命財產安全","爭取預算改善農水路更新，加速推動農路建設","督促市政府行銷農產品，帶動相關休閒農業與觀光旅遊，活絡農民收益","監督市政府兌現各項福利政策，爭取提高婦幼津貼，生育津貼，幼兒教育補助","爭取公共閒置空間活化再利用，促進地方發展","爭取健保福利補助及鄰長事務費，比照其他直轄市五都實施","推動地方創生，發展合適地域特色產業，讓青年回流，趨緩人口及發展不均等問題"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e94798ec-3a98-4b2d-b78f-d7113c6f5dc0","items":["「永續生存」 透過法令保障與法律協助，實質保障權益","訂立友善原住民族生存發展的法令，永續保障族人生根茁壯。","提供專業法律諮詢，解決法律問題，陪伴處理調解糾紛維護權益。","守護原住民勞工權益、工作機會、居住生存，保障族人發展空間。 「創新福利」 精進各項原住民福利政策，貼近族人實際需求","推動長輩照護優化政策，讓長輩安心在地安養。","關懷原住民婦幼、老人及身心障礙者，扶助翻轉人生。","多元爭取預算，辦理保障弱勢原住民權益及福祇政策。 「文化傳承」 整合教育資源，發展在地特色文化，形塑產業發展","整合原住民文化教育資源，多元管道學習原民文化、技藝、語言。","扶植本市特色原住民文化，多元開發與交流凝聚發展產業。","督促原住民博物館推動期程，結合城市發展成為南島文化重鎮。 「運動發展」 培育原住民族運動人才，促進多元休閒活動","訂定扶助條例或辦法，多元保障原住民發展運動專長。","敦促市府定期辦理原住民族各項休閒運動賽事及活動。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e96ba4b5-9e0e-448b-ac70-2af143fb1d9a","items":["長期關注並推廣扶老攜幼的青少年、銀髮族議題,讓年輕人願意留在花蓮發展,安居樂業,創建青銀共好環境。","安全、適當的幼教環境體系建置,鼓勵生育並重視幼兒相關福利政策,減緩超高齡社會的嚴峻情況。","構築公園新亮點,打破傳統公園既定印象,創造創新、安全、適合各年齡層的新式公園,提升在地居住好品質並創造觀光新景點。","持續監督美崙溪整治計畫,妥善整體規劃休憩環境與景觀建設。","打造花蓮市成為步行城市,推動生活便利安全性,宜居、安居、樂居。","推動社區巷弄經濟學,提高花蓮特色經濟發展。","爭取改善停車空間,解決觀光高峰期在地人停車的困境。","提升在地傳統市場,各方面進行改善,友善店家友善民眾,打造安全、衛生、乾淨新五星級市場。","持續推動各項公益活動,讓愛傳遞下去。支持推動花蓮加入參與聯合國 SDGs 永續發展行列。","積極監督政府各項政策及工程,讓花蓮環境更加成為友善城市,加強並維護花蓮的軟硬實力,帶動整體經濟。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e98945eb-6529-4942-9241-c0f042bb199d","items":["實在，才是最好的時代，歷經四十個春秋的堅持，完整了幾代香山人的夢想，堅持做對的事情，串接香山與大新竹連外建設，讓香山更長遠的發揮，積累的實力，講究不將就，從政40年，實在不一樣，用心不一樣。","公道三都市計劃近30年的爭取推動，已於2022年竣工通車，接續加速促進香山與大新竹交流與新建設，整合未來發展前景。","便捷香山交通與新竹順勢暢行，平衡在地路徑與城市發展魅力。","延伸香山山海生態環境，自然而然形成共融資源，產業順向發展。","推動香山友善親子生活圈，整體發展大新竹衛城定位，營造自然共好空間。","延伸17公里海岸線，推動共享單車與沿線設施景觀服務，供需舒適環境流量。","形塑香山濕地與南港賞鳥區，推動香山生態永續保育，創生在地環保教育。","推波香山文旅，走讀香山散策計劃，加深人文、古蹟、傳產、休閒觀光，帶動地方產業國際競爭力。","擴大敬老卡，公共效應使用範籌。","強化銀髮族，養生活與再造專業。","落實社區長照功能，推廣共餐食堂。","充實香山園區圖書館資源，實力展親子共學空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"e9daff0e-02dd-452a-b12e-db1f820885e8","items":["督促市府重視各項產業經濟發展。","設立法服中心，提供民眾法律等相關服務。","爭取身障團體及弱勢族群福利與就業。","重視動物保護議題，推動公立動物火化場。","成立南寮地區電力改善監督小組。","監督南寮海水淡化廠。","落實社區巡守協助警力維護地方治安。","爭取興建機場滯洪池，改善低窪地區及南寮地區排水問題。","推動客家文化及客家語言發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"e9f855d9-358d-46bd-8f3f-260830f2d3a0","items":["「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」","強化原住民主體性，落實推動原住民政策主流化。","監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。","爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。","活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。","重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。","提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。","強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。","充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。","積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。","積極協助推動蘇花安—東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ea11a107-364a-466f-8b26-3c3a14f9d2d4","items":["高齡化的社會，鄉親長輩們一生為家庭、社會奉獻心血，在長青樂齡時更需要關懷及長照。素梅會用心爭取福利，讓長輩們能得到最好的照顧。","督促政府重視青年就業機會，素梅會積極建請政府落實青年創業就業平台的功能，有效協助在地青年留鄉發展。","堅持關懷婦女，提升婦女社會地位，爭取婦女各項權益；並關懷弱勢族群，爭取經費，提升福利。","要求縣政府對於農委會有損農民權益的不合理解釋函令，應向中央強烈反映，替農民爭取權利。","持續要求縣政府向中央反映優先排序，早日將順安變電所作室內地下化。","爭取中央前瞻經費：將冬山河流域包括丸山遺址、八寶公埔圳、生態綠舟，以水來說故事、水環境串聯，並結合優質民宿來發展地方觀光。","爭取國定丸山考古遺址入口處私人土地早日徵收及園區開發，以帶動地方觀光。","督促政府對於台二庚線路線早日定案，並爭取梅林路段優先拓寬；爭取國五冬山交流道早日施作，及鐵路高架、高鐵延伸早日定案。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ea198f77-42f6-443e-94f6-a64590af2fa6","items":["確實監督彰化縣政府預算，開源創造收益，進而增加社福比例。","監督彰化縣政府有效活化中興莊，並保留歷史記憶。","協調台化彰化廠增加睦鄰方案，產業與民眾繁華共生。","基層街舞文化推廣，將彰化打造成街舞文化發展重鎮。","加快推動鐵路高架化進程，縫合沿線街廓以利後續發展。","盤點彰化都市計畫，並建議融入城市美學及地方特色。","打造友善校園環境，讓孩子快樂學習、健康成長。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ea5ee72f-9981-4b5f-b6ba-787a86ebf068","items":["「嘉倍幸福，一言為定」郭定緯以細膩、堅定態度，站在第一線，把關市政、挺身捍衛市民權益，讓嘉義更宜居、更幸福。","堅持理性問政，捍衛公益與市民權益。","放寬青年創業補助門檻，並發展創業募資平台，吸引青年回嘉創業。","閒置公有地增建青年住宅，讓青年返鄉買得起房。","推動嘉義市圖書總館，豐富城市精神食糧。","增加重點體育學校經費，培植優秀體育選手。","閒置空間增設日照中心，創造友善銀髮城市。","普設居家照護鈴，塑造老齡友善社區環境。","增加行人徒步區，擴大市區無障礙步行空間。","增設自行車專用道，提高公共空間自行車停車設施。","提高生育津貼，並推動施行坐月子津貼。","爭取增設公辦托育、幼兒園，落實社區保母優質化。","爭取推動市立動物醫院，並規劃專屬寵物公園。","增設公園狗便清潔箱，兼具美化與境教功能。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":12,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ea7d1627-79b0-4c9c-a190-0a5ac9f3ed36","items":["生活要提升：持續爭取釋出公有空間，增加休閒運動空間，提升市民生活品質。","社會要福利：持續推動老人長照政策，爭取提高老人津貼，提升年長者生活品質。爭取預算輔導青年創業及社會新鮮人就業機會，保障勞工權益。","教育要顧好：持續推動國中、小教室全面增設冷氣設備。推動增設公共托育中心，及公、私立幼兒園雙軌平衡發展。","公共要建設：結合新建公共工程，爭取地下停車場共構，紓解停車空間不足，保障機車停放權益。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ea90f294-7559-4416-a9c9-3143e67a6579","items":["基礎建設：要求普查老舊道路橋樑、天橋地下道等之安全性。","人本交通：爭取道路順平、人行便橋、路外停車、共享運具。","親水綠地：爭取老樹保護、河川水質的改善及麻園頭溪整治。","文史聚落：爭取文資保存與活化，拓展藝文聚落與地方創生。","城市發展：社會住宅：減售市地增建社宅，提供青年或弱勢合宜的居所。","城市發展：數位治理：爭取交通疏導、警政治安、防災救災等市政應用。","城市發展：青年事務：成立專責機關協助青年創業就業、職涯訓練事項。","城市發展：觀光旅遊：要求觀光體檢，開辦全國性活動、發行台中NFT。","城市發展：低碳樂活：監督防制空污作為、推動韌性都會林並倡議綠能。","社會安全：遏止兒虐：督促強化查察與通報機制,防治虐童案件之發生。","社會安全：預防性侵：落實兩性平權教育，建構被害人保密與協助機制。","社會安全：強化治安：結合協勤民力與保全，提升社區及鄰里互助能量。","社會安全：體恤基層：改善基層警、消配備，爭取人力，增加健檢補助。 社會扶助 ―、家庭照顧：爭取托育津貼、孕婦福利、早療補助、設親子館。","社會安全：老人健康：爭取廣設日照托老、關懷據點,推在宅醫療服務。","社會安全：弱勢關懷：要求定期訪視協助貧苦、獨老、遊民、高風險者。","社會安全：育成孵蛋：爭取經費扶植具有特色及競爭力的台中在地企業。","教育文化：環境更新：爭取老舊廁所跑道及遊具整換，推廣社區共讀站。","教育文化：數位學習：爭取數位設備，並優化網路環境，倍增數位課程。","教育文化：終生學習：爭取經費推動全齡學習，如樂齡教室、社區大學。","教育文化：免費午餐：督促落實免費、健康、均衡飲食、可溯源的午餐。 運動休閒","教育文化：全民運動：爭取經費興建選區運動場館設施,培養運動人口。","教育文化：電子競技：續推動電競場館設立、加強產業發展及人才培訓。","教育文化：鄰里公園：檢討空間環境，爭取共融遊具，讓設施安全好玩。","教育文化：動物友善：改善收容待遇、查緝非法繁殖、增動物友善空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"eab9b436-926a-430c-a1bd-cc01e1bb6e96","items":["爭取金廈大橋,永保兩岸和平;推動小三通盡速復航。","加強醫療改革與服務,提升本縣醫療水平。","爭取幼托及長照措施升級轉型,改善高齡化及少子女化問題。","運用教育資源,提升地區學生學力,輔以多元學習管道,落實全人教育。","振興地區觀光旅遊與各產業均衡發展,增加就業機會。","地區特色文化再提升,推展兩岸文化宗教體育交流。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"eb6fad57-5f24-4e24-bc6c-fe148215edd0","items":["積極爭取經費 ，重視強化各部落基礎建設。","重視原住民各族文化傳承 ，輔導創意產業發展 ，創造在地就業機會。","督促政府重視在地觀光開發 ，休閒旅遊創造就業機會增進收益。","督促政府重視單親弱勢婦幼安全福利 ，保障婦幼權利。","督策政府提升原住民老人社會福利 ，部落獨居老人長期照護計畫 ，醫療照顧的福利。","督促政府加速原保地核發權狀 ，國有地放租解編作業。","督促政府重視原住民音樂、舞蹈、運動人才 ，提升多項才能人才培育。","不分鄉鎮、社區、部落全方位服務努力爭取族人權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"eb9a9042-3511-4373-9db9-390a0e637761","items":["監督縣政","反對家族干政，建立廉能宜蘭縣政。","推動地方自治修法與立法。","落實性別平等教育。","推動多元教育","強化各語系母語傳承。","建立閒置教育資源使用機制。","增設新住民及原住民族第二母語學習課程。","落實長輩樂齡生活","建立長青食堂特色。","活化地方觀光：活化社區，強化社區自身特色。","活化地方觀光：完善公車路線與英語標示。","活化地方觀光：推動修正水域開放申請等相關法規。","活化地方觀光：結合現有民宿及周邊社區景點，建立特色套裝行程。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ec200292-25c8-4545-a0ed-ef0f4eacee08","items":["督導青年政策規劃執行，爭取青年創業補助，讓年輕人回留彰化。","推動社區建立關懷據點，結合相關福利資源，營造健康的社區環境，讓長輩無憂，晚輩無慮。","迎向科技化時代，推動各級學校發展AI教育，提升教育品質與效能。","爭取地方建設，改善老舊道路排水系統，保障人民生命財產安全。","爭取婦女權益，開設各類學習課程，協助女性創造自我價值，提升獨立自主的能力。","建構優質育兒環境，爭取平價優質托育服務，監督強化托育品質，讓家長安心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ec750301-0c29-4803-a5b3-fe7c6e8b1818","items":["關心教育事務，減輕學生與家長負擔：支持營養午餐免費、讀書免書籍費，健全教育現場軟硬體，協助推廣閱讀。","解決交通瓶頸，增加停車空間：督促建構全線鐵路高架化，紓解交通瓶頸，爭取合宜停車空間規劃。","完善河川防洪整治工程，強化災害防救能力，保障人民身家性命安全。","完善長幼照護，促進全人關懷：持續爭取老人日托、長青食堂及社區照顧關懷據點，建構完善育兒照顧環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ecbe119c-72e4-4ee8-b626-f6840a8b14ac","items":["八堡一圳景觀廊道拓建，將田中八堡一圳廊道往北延伸至社頭鄉張厝村，再往南打通田中二水瓶頸段串連到名間，成為台灣最美麗、最適合運動的水圳觀光廊道。","田中馬拉松結合二水、社頭一起走向國際，將台灣米倉馬拉松延伸至二水、社頭打造國際大賽事。將社頭襪世界、田中尋米樂、二水柚香中的地方景觀產業透過馬拉松運動有效行銷至全世界。","大力推動老人社會福利化，二十一世紀台灣已成為銀髮族的新世紀，迫切需要有長期規劃的政策、有效監督政府的社區老人在地老化政策得以落實。鼓勵創造就業機會讓青年返鄉照顧老人，使其晚年活得有尊嚴，還能受到良好的照顧！","加速推動高鐵交通連結、雙鐵接駁站、大型展覽館、MOOVO自行車建置等，讓田中、二水、社頭快速連結都市化發展。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ecdb048b-db11-4c82-a0f8-cf4eb167a0bd","items":["持續爭取台61線儘速延伸至永安、彌陀、梓官。","爭取橋頭科學園區交流道延伸至海線","持續推動路平、燈亮、水溝清。","因應極端氣候來臨,要求市府完善保險補助機制。","加速推動智慧農漁業補助措施。","推動大岡山地區在地商圈活化、再造榮景。","推動增設漁業博物館。","持續推動公有市場改建及更新","解決空屋率高與社宅興建緩慢,希望達到一區一社宅,推動配對租屋獎勵。","持續要求危老建築擴大補助及都市更新。","爭取生育津貼與托育補助要加碼。","爭取高齡長者居家安全設施補助。","持續推動新闢或更新為親子共融式公園。","持續推動現有社區及里民活動中心設備維護與更新。","推動海線海岸觀光開發與設施興建,強化海線觀光資源"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ed2d1791-1a13-4786-9a54-b9bab6f9e6fe","items":["持續推動太平區閒置公共空間增設公設民營托嬰中心、社區公共家園、親子館，滿足新手爸媽就近托嬰需求。","持續增設公共化幼兒園並增設2歲專班，提供優質教保服務，讓小資家庭家長安心就業。","持續追蹤太平區聯合行政中心興建進度，示範綠建築，帶動區域繁榮。","持續推動屯區環線大平霧捷運計畫、捷運藍線延伸太平區，導引區域均衡發展、屯區市區化。","持續促成太平區市民大道三期興建工程，規劃「南太平延伸段」健全路網，促進南太平便捷繁榮。","持續推動太平坪林地區辦理擴大都市計畫，擴大市區發展核心，釋出軍方太平區土地，完善公共設施，提升生活環境品質。","爭取新訂太平光興隆地區為擴大都市計畫區域，有秩序讓南太平都市發展能適地適用。","爭取依「都市計畫法」劃定太平頭汴坑風景特定區，發展多元山岳遊憩旅遊，推動低海拔山區觀光，協助青年返鄉就業。","爭取國中小學營養午餐免費、營養加倍，落實「食農教育法」，吃當季、食在地、惜食，符合生態永續的飲食生活。","爭取社宅倍增四年八千，落實居住正義；新設青年事務局輔導年輕人就業、創業、職涯發展、公共參與，陪伴青年自我實現。","推動整合市政府相關新住民的局處資源，建構教育文化、進修就業、福利救助……等單一窗口，建構新住民友善環境。","荔枝樁象結合產官學採取綜合防治，全方位、全區防治，導引農民學習新觀念、新技術及補助資材，友善從農環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"edba885b-a174-4add-8278-b68864a920df","items":["健全澎湖縣緊急醫療救護作業系統，充實醫療基層人力，保障鄉親民眾生命安全。","整修衛生所室場域，增購汰換老舊復健器材，滿足長者需求。","爭取普設各鄉污水下水道工程，以維海洋潔淨，活化海洋資源，建構優質生活環境。","協助反應漁民及漁業發展障礙與困難事項，維繫地方漁業永續發展。","爭取漁港疏浚整治工作，並充實改善周邊漁具倉庫等港埠設施，符合漁民需求。","全力推動地方特色農漁產品行銷，拓展市場銷售通路，開創活絡地方商機。","加強推動觀光遊憩景點開發建設，結合文創產業，帶動地方整體發展。","爭取社區活動中心汰舊換新經費。","選擇公有地，營造親子活動遊憩設施環境，廣泛設置共融式公園。","強化社會福利措施，照護弱勢族群。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"edd6cd74-1efc-4cb9-b780-02384a842c54","items":["監督預算,健全財政。","爭取縣府重視觀光及休閒發展,使遊客及鄉親都能有更好的遊憩場所。","督促縣府推動品德教育,培養孩童優良人格。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ee058f16-75c8-4f8b-a91c-0aeff23e4731","items":["全力監督市長，把關市政！！","督促市府廣建公幼、公托！！","督促市府推動公辦都更！！","督促市府增加都更獎勵！！","督促市府減少都更限制！！","督促市府加速都更審查！！","督促市府建置捷運民生汐止線！！","督促市府降低公有市場租金！！","督促市警局恢復護童專案！！","督促市警局恢復查緝違禁藥品！！","督促市府嚴格把關大巨蛋使用執照，並確保市民公安與市庫權益！！","督促市府雙子星開發進度與品質！！"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"ee26b9d1-ce4f-4d38-a8ec-21280a2ddfc8","items":["爭取解編東區水源保護區，帶動東區都會發展。","爭取汀甫圳河川整治、美化。","爭取建置東區治安、交通防護系統。","爭取舉辦全國性眷村美食及推動眷村文化傳承。","推動社區型世代共融日照、安康中心。","推動政府整合交通事業─接送學童上下學。","爭取設置國際標準足球場域。","爭取增設風雨籃球場地。","爭取設置公辦青年多元運動、競技場域。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ee323a51-fbfd-4a4c-b96e-930818273c88","items":["科技新創｜AIoT打造智慧城市：支持推動輕軌建設，加速興建空橋，打通交通壅塞環節。","科技新創｜AIoT打造智慧城市：擴大使用AI科技，加速增設瓶頸路口時制重整及智慧號誌。","科技新創｜AIoT打造智慧城市：科技輔助改善停車位及人行道問題。","科技新創｜鼓勵創新創業：設置創業導師·全方位、大力度支持創新創業。","科技新創｜鼓勵創新創業：加碼補助·鼓勵女性及青銀創業。","科技新創｜營造支持後盾：逐年增加育兒津貼及托育補助金額，至少各加三千元。","科技新創｜營造支持後盾：市府扮紅娘，擴大辦理單身青年聯誼活動，媒合好姻緣。","運動康健｜監督落實市民喝好水政策：增加公共汙水下水道接管戶數成長三成以上。","運動康健｜監督落實市民喝好水政策：專管回收工業、醫療廢水以及汙水，從源頭管控廢汙水排放。","運動康健｜打造一公園一特色運動：專項運動融入公園設施，推動特色運動公園（直排輪、滑板、各種球類等）。","運動康健｜打造一公園一特色運動：政府媒合運動專才，協助推廣特色運動。","運動康健｜提昇城市運動競爭力：優化現有運動場館（場地）之軟硬體設施，保障運動安全。","運動康健｜提昇城市運動競爭力：舉辦城市特色運動賽事，帶動市民運動風氣。","多元教育｜推動多語教育：推動國語、英語、母語、程式語言的多語言學習環境。","多元教育｜推動多語教育：推動多語言納入課綱·發展各校語言學習特色教育。","多元教育｜推動創客教育：推動STEM教育，培養孩子的思考與創造能力。","多元教育｜推動創客教育：結合3D列印、鼓勵孩子動手實作，敵動孩子的學習力。","多元教育｜精緻成人教育：社大結合職業訓練需求補助開設第二專長養成課程。","多元教育｜精緻成人教育：滿足中高齡者的學習需求，結合社區與長照據點擴大課程開設。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ee7d68b4-0563-46c7-92f7-c2fa701e33e4","items":["理性監督縣政、反映民意、善盡民意代表之責。","督促持續整治員山各處河流，確保全民生命財產安全。","促請早日完成東西向道路銜接北宜高速公路。","爭取專款改建員山老社區活動中心。","促請持續辦理員山風景區景觀再造、環境改善、開發觀光據點。","促請設農產品直銷中心，增加農民收入。","積極促使充實教育設施及社會福利政策。","督促查核工業空氣污染、水質污染改善問題。","少訴訟、多調解，認真打拼向前行、服務、調解永遠第一名。鄉親有冤情，浴沂永遠和鄉親站同邊。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"eea8f385-5e76-4b47-9d1d-0ea7952116f0","items":["社區 UP：營造優質公共空間，擴增老人食堂、社區關懷據點優化量能。","環境 UP：優化村里生活環境，道路交通安全改善。","教育 UP：落實教育平權，活化教育培育國際接軌能力。","創新 UP：鼓勵傳統產業升級，品牌化經營，藉由產官學合作，提升整體創新能力。","農業 UP：結合上、下游產業，活絡在地市場，開拓多元農產品加強行銷通路。","產業 UP：督促產業園區開發，提升就業率，帶動地方經濟。","觀光 UP：發展特色旅遊及產地旅行，強化異業合作，完善觀光環境。","文化 UP：提升本土產業文化，推動藝文與地方連結。","育成 UP：支持青年回鄉發展，強化育成及青年交流。","食安 UP：推動國產優質農產品，提升嘉義優鮮品牌，讓民眾食的安心。","監督 UP：認真問政、反映民意，實質監督，清廉把關。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"eebadac3-e479-4ef5-8749-79c1c860fd30","items":["城鎮發展：積極爭取新竹縣輕軌鏈結科技生活圈串連設站竹東站，完善公共運輸缺口與提升交通系統效率，改善現有交通瓶頸。","城鎮發展：積極推動中興河道水岸生活空間再造二期計畫，打造水與綠新市鎮。","城鎮發展：積極爭取鎮內閒置空間綠美化、打造無齡別特色空間，提供鎮民、銀髮族、孩童等休憩場域。","城鎮發展：積極要求通盤檢討暨可行性評估都市計畫外五里（頭、二、三重等地區）新外環道路開闢，完善交通建設解決交通困境。 社會福利推行","城鎮發展：多元社會福利持續力爭推行，老人年金發放及幸福升級長照2.0。","城鎮發展：因應新竹縣外移人口增加，要求研議提高生育補助津貼、育兒津貼、提升學童營養午餐品質，並且推動社區型公共托育家園，完善嬰幼托育制度。","城鎮發展：要求持續發放身心障礙福利及低收入戶補助等。","城鎮發展：要求研議通盤檢討新竹縣民意外保險額度及範圍，健全縣民生命保障制度。","城鎮發展：推動早期兒童療育相關政策納入政府補助，通盤檢討增加個案管理中心人力及物力資源、廣推融合教育，並研議開放全年特殊生托育中心及特教員培訓課程，以健全遲緩兒童教育權。 教育面向","城鎮發展：強力要求推動英語教學，積極爭取外師制度，提升竹縣學子國際競爭力。","城鎮發展：推動母語教學及全民閱讀習慣，培養學子族群認同。","城鎮發展：強力爭取外五里地區非營利幼兒園結合親子圖書館。 青年面向","城鎮發展：積極要求支持青年創業、根留竹東。","城鎮發展：要求研議健全青年創業計畫與補助方案。 其他","城鎮發展：嚴格監督落實地方建設品質，完善竹東生活機能。","城鎮發展：爭取竹東外五里新建衛生所。","城鎮發展：要求落實執法飼主寵物登記、植晶片，有效杜絕棄養，支持領養代替購買。","城鎮發展：爭取輔導農民保險及農損補償機制，輔導農產品加工製成計畫暨設備補助。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"eee109e2-1488-404f-bd4a-44d6fb319a8b","items":["擴大辦理國小學童營養午餐有機米及有機蔬菜。搭配牛奶或優酪乳。","爭取二到四歲幼兒私幼每學期補助20,000 元。","打造英語友善城市，推動南港優先示範區，擴大辦理英語夏令營。","打造親子科學數位圖書館，持續推動親子生物數位圖書館。","持續推動親子爆米花電影院結合市圖行動書車推廣閱讀。","市政大建設：推動南港六本木結合東區門戶計畫，打造台北新都心，建立南港空橋連接系統，自中國信託到南港車站到北部流行音樂中心，再到南港機廠社會住宅。","市政大建設：爭取「捷運信義線東延地下化」從玉成公園至南港國宅再到中央研究院，成功獲得市府回應延伸至廣慈/ 奉天宮站規劃案已留設尾軌（設於中坡南路下方），在工程上已保留具有續行延伸至中研院地區之可行性，持續推進中。","市政大建設：設置義民廟並發展更具特色的客家文化主題園區。","市政大建設：推動設備完善的幸福友善銀髮養生村。 樂活好幸福","市政大建設：持續推動寵物運動公園設施再升級。舉辦毛小孩運動會。變裝趴、愛心美容健檢等專屬活動。","市政大建設：65 歲以上申請敬老悠遊卡或愛心悠遊卡，使用點數倍增，持卡每月免費1000 點，並擴大點數可使用範圍。","市政大建設：關心內湖復育園區設施，爭取舉辦親子活動。","市政大建設：活化世大運網球場。","市政大建設：增加活化商圈行銷活動；強化青年創業輔導；保障新住民就業及社會保險權益。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"eef01492-2404-45ba-8f22-03a1f22c049e","items":["產業與農業：促進產業升級轉型，媒合跨產業合作，兼顧2050淨零排放目標，輔導產業永續發展。","產業與農業：優化就業環境，吸引青年返鄉扎根，緩解產業缺工問題。","產業與農業：爭取調高老農津貼與放寬排富標準，全面檢視農水路品質，守護農業從業環境。","產業與農業：擴大青年優惠貸款並持續辦理租金補貼及社宅政策，打造青年宜居環境。","產業與農業：延長育嬰留職停薪申請年限並爭取托育延托方案，擴大準公共托育。","產業與農業：提高長照服務品質，持續擴大長照服務量能與據點，加強辦理喘息服務，打造長輩及照顧者友善生活環境。","產業與農業：持續爭取文化資產修復及維護重要古蹟，協助地方文化傳承。","產業與農業：活絡文化創新產業並結合地方特色，打造獨特文化生活體驗。","產業與農業：維護國家語言發展，發揚臺灣多元文化特色。","交通安全：爭取美港公路高架化3年內動工，縫合路網，提高民眾用路品質。","交通安全：擴大路網維護能量，順暢六鄉鎮交通，帶動地方觀光經濟發展。","交通安全：改善交通品質，強化道路交通安全意識，守護用路人安全。","交通安全：持續爭取學校建設升級，更新學校設施設備，提供孩子安全的學習環境。","交通安全：推動程式及母語教育，符合產業需求及文化傳承，兼顧經濟與文化發展。","交通安全：依照各式產業需求進行人才培育，推廣職場體驗，畢業即就業，共創產學雙贏。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":4,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"ef3620c0-7d3c-4c29-8c55-6f3688123fb5","items":["強化社區營造","為各村爭取觀光特色產業"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"efc73c9c-4f91-4b16-bc53-153f8152b365","items":["監督縣政：監督縣府依法行政，保障公務人員依法作業的基本權利與原則；嚴謹審查預算編列，避免排擠及公帑濫用。","服務地方：依本鎮民意需求，做好橫向、垂直的跨單位溝通，加速且有效率地解決問題。","關注議題：關注交通、治安、環境、教育及觀光文化等議題，透過座談、說明會等方式，讓鎮民更深入瞭解和關心。","支持建設：全力爭取合法合理的建設；必要的軟硬體建設皆有助本鎮正向發展、提高能見度。","支持公民權下修至18歲。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"efd58160-ee06-4139-8187-e9dd6d9eb5cd","items":["選一個懂科學懂技術的縣長，機械黑手天才發明家。","發展國際認知旅遊與全世界作朋友。","楊同學看政見！還我金門價值、戰地文化、閩南僑鄉文化。導入世界級車輛、船舶賽事、 遊艇產業。","生態、教育、地方發展共存共榮、公共工程精進、落實基礎建設，實現居住正義、廉政、 落實司法改革。","挺公益、挺創業、監督政府、司法特權、資源永遠是要放在對國家社會能產生最大價值的 地方。交通、醫療、長照、0-6歲國家養，金門先行懷孕就幫你養。過橋免費比照大小金門 交通輪。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f0095e4d-fe24-4ecf-829a-a5916edb004f","items":["根據台北市政府研考會的民意調查，2018年迄今，五年來台北市民平均最不滿意的市府施政項目為：「中小學教育」、「公共工程」、「社會福利」、「文化活動」 和 「交通」，五年的平均滿意度都在40%~59%；而在公共治理上，台北市民對市府的十項作為也給了平均40%~59% 的滿意分數，包括：「決策一致」、「有明確施政方針」、「重視產業發展」、「有創意想法」、「關心市民福利」、「重視民意」、「負責任」、「公共正義」、「值得民眾信任」、「節約 ( 節省開支 )」，這十項公共治理指標，市政府都不得民心。而這些市政府做不好，民眾不滿意的施政作為，也正是慧珠持續努力的目標，持續監督市府、為民喉舌！","另外，慧珠是選區中公認的「最勤快的市議員」，未來四年，，慧珠仍將秉持 「勤走基層」、「熱心服務」的理念，做一個市民隨時找得到的老朋友、好議員！"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f0173f72-e191-4e75-941b-e3bf4b6b2a4f","items":["加速推動都更及危老重建修法，提供更合理的條件與容積獎勵，以提高都更的意願及速度。","減輕長期照顧與高齡養護家庭的稅負負擔，並且發放照顧者津貼。","簡化並加速申請移工照護的程序，提升移工技能，以確保照護品質。","改善食品安全監控制度，保障人民健康權益。","監督政府施政，打擊詐欺犯罪。","制定妨害司法公正罪，嚴懲司法關說。","恢復特偵組，嚴查各項貪贓枉法的犯罪。","捍衛新聞自由，追究NCC箝制新聞。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f060e7c8-5f45-4e2a-8da5-e599838f8321","items":["【挺18公民權】 世界上許多民主國家透過法律保障18歲青年享有公民權利及義務，台灣是亞洲首屈一指的民主國家，複決投下同意票支持18歲公民權修憲，完成世代平權，民主台灣再向前！","【爭取婦幼福利】 持續增加公托、共融式公園，並在龜山設置臨時托育中心，延長收托時間，要求增加托育人員待遇及爭取托育補助加碼。","【投資教育環境】 繼續監督大崗高中設校進度、持續督促文青國中小設校完成、爭取龜山新設圖書館、增加國際專班、推動學校雙語教學、本土語言課程及智慧教室數量。","【改善交通路網】 繼續監督捷運棕線實質進度、再增加龜山公車路網、完善候車系統、引進多元共享運具、設置交通寧靜區、繼續監督A7二期計畫道路打通進度。","【提升長輩照顧】 持續爭取龜山新設老人文康中心，擴充關懷據點功能，要求擴大敬老愛心卡使用範圍，照顧銀髮族好生活。","【支持青年發展】 繼續推動龜山設青創基地挺青年創業、爭取青年就業津貼加碼、持續監督龜山社會住宅興建、督促國民運動中心興建進度。","【觀光休閒產業】 將虎頭山風景特定區、楓茶米休閒農業區、龜山苗圃露營區、桃林鐵道、南崁溪自行車道整合成《大桃園生態都會公園》，吸引人潮前來龜山消費，振興市場活絡地方經濟；推動大棟山風景特定區核定將歷史與人文故事融入周邊商圈創造地方繁榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f098cca2-0d71-4b5c-8b8a-a043a9b8fe8f","items":["持續協助改善教育環境。","協助強化公共運輸貼合民眾需求。","提高生活環境質感。","運動（提高運動風氣、健全運動環境、舉辦運動活動）。","環境保護。","照顧銀髮族生活各面向。","持續爭取縣府相關資源挹注芎林鄉。","協助鄉內人民團體爭取資源舉辦公益活動。","協助改善五華工業區環境。","監督芎林鄉衛生所興建，平衡芎林鄉各村醫療資源。","協助照顧芎林農業與農民。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f1911e77-4e32-45b2-9fa2-8370c5465947","items":["用心監督：率先揭發「機六」用地變更案，為羅東鎮民保住4,000坪全民用地；持續監督工業區保護區區段徵收案，防止不合理或有圖利之嫌的情事；把關縣政與預算執行，反對家族干政，建立廉能縣府，維護全民公益。","認真服務：提升羅東污水接管率，持續協助鄉親排除困難；秉持民眾的事就是我的事，設身處地服務，對每一件服務案件傾力找出解決之道。","照顧長者：加強長照2.0服務量能，持續推展長者日托系統，提供失智長者照護者喘息服務，健全老人長照機構。","照顧婦幼：普設公辦托嬰，推動定點臨時托育與到宅托育機制，鼓勵年輕家庭生育；打造室內友善親子空間，改善兒童共融式遊憩公園，並爭取各鄉鎮平等補助6歲以下兒童。","照顧青年：全力支持降低參政門檻，將公民權年齡限制下修至18歲，爭取打造智慧化青年社會住宅。","照顧治安：爭取補足警消人力員額、充足救災設備並依年限更新汰換，要求業務回歸專業，健全警消業務。","照顧交通：持續推動台鐵高架化，監督太平山森林鐵路路線並爭取未來共構轉乘；更新台七丙線公路路線，避免三星至國五高速公路的車流導入羅東市區，快速連結高速公路並解決交通問題。","照顧文教：活化歷史建築與閒置空間，維護師生權益，改善校園學習環境及軟硬體設施。","照顧體育：打造優質全民體育運動園區，結合籃球場加蓋、室內樂齡運動場館、爭取溫水游泳池、加速棒球場整修及設置全民共享多功能教室，營造友善體育環境，提升全民運動風氣。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f1968c70-e338-4b8a-ae70-45e5d931c862","items":["｢正派做事、理性問政、視民如親、熱忱服務｣"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f1d17fe7-59bb-483b-9999-8a8ba845216c","items":["政策論述・興利除弊：下架民進黨，找回台灣光榮；恢復特偵組，徹查貪腐疑雲。 兩岸和諧・穩健前行：維持台海現狀，共創兩岸雙贏；重啟溝通平台，創造和平氛圍。 經濟升級・國際接軌：加入區域經濟組織，提升產業優勢；核心產業根留台灣，保障就業機會。 財政重劃・力挺青創：爭取提高桃園中央統籌分配款補助；強化青年職涯發展平台與青創基地。 交通建設・領航桃園：加速中豐北路及大竹交流道建設；加速鐵路地下化，中壢車站翻新；續推動機捷A23、綠捷延伸中壢。 健全社福・市民安居：加強弱勢補貼，擴充長照量能；加速公宅建設，落實居住正義。 教育優先・體育紮根：充實學校硬體建設，重視品格教育；重點發展各項體育，推廣全民運動。 社會公義・族群共榮：維護勞工、農民、軍公教權益；尊重多元文化，族群包容共榮。"],"content_split":{"method":"paragraph","version":"election-content-items-v1","confidence":90,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f1e38805-4d1a-441d-a52d-339ec8af6031","items":["爭取中埔三和地區設立高中或完全中學，讓三和地區及鄰近學子得以就近就學培育人才。","爭取都市計畫內老舊高壓電塔完全地下化整治市容，以利地方繁榮發展。","爭取易淹水地區老舊排水道改善，監督執行地下水道改善工程。","為維護地方治安爭取增設三和派出所，以利便民服務。","監督三和地區都市計畫完成通盤檢討之執行。","推行地方休閒運動及場設改善。","爭取中埔鄉設立托育中心及水域縣民運動中心。","監督改善吳鳳廟特區環境改善，以利地方經濟效益發展。","持續推動客家文化協會永續經營。","全心全職為民服務排解艱難──追求幸福與繁榮。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f22513c8-9a1b-4ba0-8a74-582c4dcf14ae","items":["都市發展：提高危老獎勵：容積獎勵、費用補助、貸款和利息補貼、稅務減免。","都市發展：提升活動中心使用透明性：優質集會空間，促進區里平衡發展。鄰里作業調整，深化基層服務功能。","都市發展：社會住宅餘域空間，設置微型運動中心。","交通建設：推動人工智慧AI號誌控制、智慧交通控制偵測、智慧交通安全路口防護計畫，並使科技執法全面化。","交通建設：中平路銜接國道二號新匝道工程，紓解南桃園交流道阻塞壓力。","交通建設：公共空間規劃電動車充電設施及充電環境。","交通建設：南崁溪大埔橋上游及東門溪氨氮削減設施，降低氨氮汙染量，加速改善南崁溪流域水質。","交通建設：加強遊蕩動物管制措施，執行TNVR，改善攻追行為。","社會福利：擴大復康巴士量能，保障行動不便者行的權利。","社會福利：增設安家食物銀行，提供弱勢家庭民生物資。","社會福利：推動托育公共化政策。","關心教育：提升校園設備，建置校園安全防線。","關心教育：改善校園男女廁所比例，增設性別友善廁所。","關心教育：推動雙語學校計畫，提升外師涵蓋率。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f2440f84-6f35-47ae-a99c-c764017feb01","items":["推動捷運大寮週邊道路開通及商圈開發。","爭取林園、大寮一里一公園。","爭取大坪頂特定的開發。","爭取大寮三隆路拓寬。","爭取大寮區81期重劃內,設置綜合性活動中心。","爭取義仁里天池路往鳳山水庫道路拓寬。","督促市政府重視青年就業及勞工低薪問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f252682d-91f9-4102-9bec-54c9314d1a75","items":["與大專院校英語、翻譯系所合作成立中小學雙語教學專責單位，開發雙語教材，減輕教師負擔","運用線上資源培訓雙語師資，協助推廣中小學雙語教育","與國內外英語、教育相關系所合作，辦理沈浸式營隊，在臺灣營造雙語學習環境 教育均值化、優質化","因應人口需求，重新檢討學區劃分","推廣「就近入學」，規劃增班設校（國小到高中）","合理分配中小學教育資源，達到「校校皆是明星學校」的目標","爭取代理教師權益、減少教師流動率、保障教學品質 推廣中小學「心理衛生教育」","與國內外民間單位合作，讓學生及早認識並且預防憂鬱症、躁鬱症等心理疾病 改善交通安全","完成「光埔空橋」建設、保障學童通學安全","關埔重劃區增設機車格、減少交通亂象","規劃增設人行道，讓學生安心走路上下學","檢討公車路線及班次，推廣大眾運輸與共乘 落實居住正義","推動囤房稅、空屋稅，限制不合理囤房、炒房","支持興建社會住宅，落實居住正義","推廣包租代管，保障租客權益 推動長照服務","要求市府規畫未來長照服務的財源","推動身心障礙者、低收入戶等弱勢族群的長照服務"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f2fc3752-ebfc-4e80-8738-c36e5dda11c7","items":["【婦幼、青年 拼未來】 1.力推社會住宅，並納入綠地及各項公益設施，提供青年負擔合理且舒適的居住環境。","爭取平價托育環境，持續推動共融及特色遊戲場，照顧年輕家庭需求。","建構性別友善城市，提升環境空間婦女權益、關注女性醫療需求。","確保弱勢家庭、新住民及二度就業婦女就業權益，推動多元就業輔導及培訓資源。","厚植校園運動風氣，提供基層選手完善培育資源及舞台。 【產業、交通 大振興】 1.持續監督淡江大橋、淡北道路、關渡新橋及台二線優化等工程並如期、如質推動及完工，兼顧交通建設及環境平衡。","推動道路平權、綠色運具、人本環境，打造平等且安全的道路環境。","建立智慧交通路網，提升道路使用效率；建置偏遠地區小黃公車隊，彌補公車不足。","推動地方創生，包含農村再生、觀光整備，帶動經濟振興，推展北海岸地方特色。","督促市府積極招商，增加就業機會；推動青年創業基地，支持在地產業發展。 【文化、環境 齊照顧】 1.持續推動文化資產保存、修復、活化，與在地文史資源永續發展。","推動各區特色藝文化活動、爭取藝文展演平台，發揮北海岸藝文軟實力。","維護河、海岸生態環境，持續推動污水接管；加強外來種防治作業，落實生態保育。","提升城市綠覆蓋率，打造有氧綠色城市，提供更多舒適綠地休憩環境。","盤點閒置公共空間，廣設社區照顧據點，提供長者、學童完善照顧。 【迎接淡水好時代】 1.淡海新市鎮新設國中、圖書館、公托及公幼等福利設施，打造宜居新市鎮。","推動淡海二期產業園區，輔導特定工廠轉型。","建議規劃淡海醫院，因應北海岸新興人口醫療照護需求。","打造寵物友善環境，加強流浪動物源頭管理，改善動物之家收容環境。","推動竹圍、紅樹林地區公設用地解編，加速公園綠地建設。","持續爭取全齡共融及特色遊戲場，公園設施更多元豐富。 【實現八里好發展】 1.督促產業用地加速招商，創造就業機會。","加速推進八里輕軌及纜車，結合八里觀光軸帶振興八里觀光產業。","持續要求八里東海四季游泳池活化轉型，建設八里運動中心。","監督八里汙水處理廠處理設施再升級，移交新北好管理。","建議八里國中遷校，教育場域及品質再升級，提升在地就學意願。","建構地區醫療照護網，優化急重症患者醫療品質。 【三芝石門好生活】 1.推動三芝萬坪公園、石門遊艇碼頭活化，發展海洋休閒觀光產業。","推廣環境友善耕作、食農教育，發展特色休閒農業旅遊、建構多元銷售通路。","爭取醫療、長照資源挹注，提升衛生所服務項目、健全復健所設施。","持續爭取特色遊戲場、戶外健身房、銀髮體健設施及綠地休憩空間。","監督核一廠除役計畫如期推動，反對石門區作為核廢料最終處置場。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f30c71cd-fe25-4619-b134-81fd243e8f8a","items":["招商引資上水：左營高鐵之星、楠梓台積電，帶動產業轉型。","交通改善上水：打破交通瓶頸，完善道路安全整體規劃。","國際教育上水：落實2030雙語國家政策，強化本市教學環境。","婚育友善上水：強化青年婚孕政策，敢愛、敢婚、敢生養。","運動城市上水：廣設國民運動中心，促進友善便利健康環境。","青年發展上水：擴大推動青年志工參與，與國際接軌。","城市美學上水：實踐特色公園環境，進步市容再提升。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f3754f44-ba01-4edd-a08e-e4ef1e0b1b3b","items":["速建國道七號,從海邊貨櫃碼頭直接引流大貨卡車上國 1 國 10 台 88 遠離平面道路","比照台北松山機場爭取小港機場南北牆邊道路美化及穿越機場地下道工程","續爭取前鎮新草衙土地處理自治條例成效及鄉親權益維護與優惠大沿海遷村工程","督促水利局加速防災極端氣候、下水道生活溝排水清淤清理工程暨環境工程","質詢並督促加強公私監視系統,整合聯防機制,汰舊更新器材","提案並督促市政府鼓勵青年愛國從軍、立業致富、生涯規劃、青年創業輔導事宜","督促市政府爭取長照暨日照中心資源,促進社政和醫政整合、加強噴藥減蚊","續監督市政府跨局處合作,協助高污染產業轉型減污暨成年青少年學童毒品防治工作","督促市政府透過公共建設或土地獎勵投資,增加公私停車場位","爭取各區推動雙語教育增設公私幼兒園,落實資源均衡,打造安全移居幼兒城市","爭取完善專業安全前鎮小港複合式運動中心暨各級學校 PU 跑道新增與改善","爭取前鎮漁港改造、周邊道路綠化暨捷運黃線延伸前鎮漁港暨各巷道重刨鋪工程","續爭取設立前鎮小港各處增設公共自行車 2.0 租賃站","爭取近億元整治美化中安路旁鳳山溪前鎮河及數座抽水站工程"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f3c65c83-23e2-4348-861c-0989037ab2a5","items":["區域發展：監督捷運汐止-民生線速執行可行性評估，便利東西向交通的路網。","區域發展：建構中山大同文化產業，促進地方繁榮，打造國際觀光人潮。","食品安全：強化食品安全，定期、不定期檢驗市面各類食品是否符合國家安全標準。","食品安全：支持TNR(Trap Neuter Return)，強化「以認養代替購買」，嚴懲虐待及棄養者，打造動物友善環境。","美好環境：盤點中山、大同公共空間，結合地方創生，媒合產業扶植青年創業。","美好環境：增設中山、大同共融公園，以利兒童大腦與肢體多元發展，同時兼具長者休憩運動功能。","社區安全：建立社區及校園安全網，推動並建置智慧型巡檢系統，以點、線、面的連結佈建安全網。","社區安全：推動居住正義，提高租金補助，增加社會住宅，並加速老舊住宅都市更新效率。","社區安全：普及「通用設計」的概念，增設樂齡照顧中心， 加強中、低收入戶及弱勢族群生活照顧。","社區安全：改革少子化問題，提高0-5歲之育兒津貼，整合幼托人力，健全後疫情時代托嬰制度問題。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f3ccfc08-6d79-4e29-a8b3-e71d0b8060b1","items":["農工大縣，琴來實現；議會尚青，專業問政；深耕、做事、顧弱勢。","老人福利：督促縣府向中央爭取老人福利，落實中央政府長照計畫。","農、工業：推動農漁牧產品精緻化、科技化農業，保障農民生計，輔導農業轉型升級。引進AI產業進駐嘉義，發展無人機產業，設置科學園區。督促縣府實現農工大縣的願景。","社區：爭取各社團辦理活動經費補助，設置青少年活動場地，並提高各社區的補助額度。","教育：改善各中小學軟硬體設備，爭取中低收入戶學童營養午餐免費，推廣並補助民俗文化藝術經費。","婦幼：爭取外籍配偶及中低收入戶家庭，提供幼兒免費托育服務。","農路：加速早期農田水路改善工程，全面興建擋土牆，並鋪設柏油路面、拓寬路面，以利農機出入。","治水：爭取整治六腳排水及易淹水地區抽水站之設置，確保民眾安全，全面改善轄區大、中、小排水系統，並增設各聚落排水溝加蓋，以護民眾行的安全。","觀光：結合大阿里山風景區及中崙溫泉、瑞里風景區、東石漁人碼頭、民雄演藝廳、新港奉天宮、民雄大士爺廟、民雄鵝肉街、故宮南院等景點，成為獨具地方特色之觀光路線，並結合各地方社區營造，提升總體經濟價值。","衛生防疫：督促縣府配合中央防疫指揮中心落實防疫工作，並請縣府規劃後疫情時代來臨時各局因應方針。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f41d6aea-e5b3-4a32-b9ae-8b12c2bc2c71","items":["苗栗縣縣議會第二十屆縣議員選舉議員候選人朱仲一之原住民政策政見","落實原住民基本法實體內涵，保障原住民權益， 9、提升原住民交通出行權益，建構部落地區與都會 並推動原住民自治。 原民地區專屬交通移動服務。","致力於服務全體原住民，縮小城鄉差距，不分族 10、推動原住民觀光、文化、經濟產業，鼓勵青年 群不分地區，地位相等，福利權益皆受保障。 返鄉，輔導並支持原民青年創業。","成立原住民法律權益保障組織，免費提供法律諮 11、增進原住民文化與語言推廣講師、工藝師等文 詢與相關協助。 化工作者權益與待遇，促進文化推展與傳承。","加強都會區原住民權益照顧，特聘都會區原住民 12、活絡原住民農產品、文化、工藝產業與產銷通 專員，監督建設都會區原住民聚會所。 路，穩定增加族人經濟收入。","讓補助感受得到，強化原住民福利政策宣導，專 13、積極反應原住民區域住家安全、產業道路、公 案聘用人員協助完善相關申請文件。 共設施之建設，讓回家的路更安全。","解決原住民失業與轉業問題，加強培訓輔導職業 14、爭取廣辦縣內原住民各族群的文化聯歡（相親 技能機制，提高原住民工作能力與收入。 活動、慶生會）、歲時祭儀，積極推廣各族文","爭取國小國中高中大學學費全額補助，專案協助化特色並凝聚族人。 原民青年出國留學與比賽，全面提升原民教育。","提升原住民耆老、弱勢的居家與日托照顧品質， 文化、法律、產業、行銷與國際人才，健全原 提升文化健康站照服員待遇與法律權益保障。 住民事務人才庫。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f4ae4786-b5c0-46e7-b575-4b5e36cf5c49","items":["湖口不是殯葬矽谷！堅決反對在湖口鄉波羅村設立第二個生命紀念園區。","爭取湖口往來新竹高鐵站接駁車。","爭取湖口設立室內多功能綜合國民運動中心。","具體改善湖口工業區交通壅塞與停車格短缺問題。","爭取人口紅利，編列經費落實6歲前小孩政府養，18歲前青少年政府跟家長一起教。","勞工人權覺醒，設立勞工急（危）難救助單一窗口受理機制。","因應缺電危機，爭取設立再生能源專區，讓新竹縣成為再生能源的示範縣。","高漲房價讓年輕人負擔不起，建立完善的社會住宅制度，讓有房不再是難題，緩解不合理房價推升。","爭取經費推動村村有長輩共餐食堂，提供日照、保健服務，讓子女安心工作減輕負擔，落實關懷長輩。並提供送餐照顧弱勢家庭。","爭取中小學營養午餐費每人由45元提高為65元。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f4b7473d-269d-4891-ac19-2b5718b24fa0","items":["老吾老以及人之老，爭取年滿65 歲以上長者健保費全免。","幼吾幼以及人之幼，爭取06 歲至12 歲兒童免費塗氟。","爭取生育獎勵金提高到第一胎三萬元、第二胎五萬元。","分擔家長育兒經濟壓力，新生兒至03 歲尿布免費。","住者適其屋，監督社宅營造、安平二期國宅改建、有效利用資源、落實居住正義。","廣設並加強停車場之規劃，舒緩停車困擾，並增加交通流暢，改善交通秩序。","增設或修建里、社區活動中心，以利民眾集會及辦理文康育樂活動，增強社區凝聚力。","監督市政建設品質，嚴禁貪瀆力行廉能政府。","督促安平自由貿易港區開發儘速完成。","加速推展鯤喜灣文化園區各項文化、休閒、觀光事業，以期成為帶動南區繁榮原動力。","爭取改善南區、安平區老舊鄰里公園設施，提供市民安全舒適的休憩空間。","督促市府全面檢測南區、安平區易淹水地區，排水系統全面性規劃，徹底解決淹水問題。","推動警察、消防弟兄勤務合理化，強化安全設備。","關心勞工失業問題及爭取勞工權益。","全面推動社會福利，加強各項長照服務整合。","爭取增加身心障礙者的就業機會及相關津貼，全力達到無障礙城市的目標。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f4db64dc-ed67-4993-b5d2-5f04136fa950","items":["督促縣長，履行對縣民的承諾","服務不分大小事"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f51c59b4-9082-4a60-a775-7633819569ba","items":["打造土城科學園區","設立鶯歌市立醫院","新建青年社會住宅與公園","鶯歌鐵路改善工程","新闢土城司法園區","各區汙水處理工程","火葬周邊2.5公里空氣品質改善","土城多功能行政園區","樹林多功能行政園區","增加鶯歌及北大高中公共托育","爭取65歲以上長者假牙補助","增加青年及家庭租金補貼","設立親子無煙公園","增設噪音科技執法"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f540fb76-2f4b-414b-b616-6a506aa3e944","items":["打造產業升級，促進經濟就業，提升勞工薪資","推動北高雄半導體及扣件等產業聚落，加速橋頭科學園區開發並推動橋科第二園區。協助傳統產業解決用地不足困境，增加產業用地。鼓勵廠商優先晉用在地青年，友善職場環境，敦促勞工局北高開課培訓，提升勞工薪資。","推動海洋經濟首都，打造高雄「農漁產品牌化」，拓展永安、梓官、彌陀、岡山、燕巢等地農漁產國際通路。美化海岸線「彌陀南寮海岸光廊」、「永安永新灣親水公園」、「蚵仔寮海洋及漁業文化親子館」及「燕巢瓊林有機農場」。","完善交通建設，縮短城鄉差距","加速推動及爭取「岡山火車後站連通捷運岡山站跨站天橋」、「岡山第二交流道」、「橋科匝道」、「高鐵橋下台39線打通」、「岡山交流道下兩側連通橋科」、「高捷紫線—高雄學園線」、「捷運岡山延伸湖內」、「台鐵地下化延伸岡山」。","降低交通、消防、公安意外，持續推動巷弄打通，如岡山火車後站出口巷弄打通、岡山區新樂街15巷園道、彌陀鹽埕大排、梓官仁愛路、梓官平安街及其他都市計畫內巷弄打通。","都市計畫檢討，爭取有感施政、優化宜居環境","都市計畫各區重新檢討，推動區段徵收加速繁榮地方，老舊行政中心整併重建，讓市政資源公平挹注各區發展。推動醒村成為青創基地，發展三軍眷村觀光。爭取北高雄第二座社會住宅、國民運動中心，推動防災智慧安全城市。","關懷婦幼弱勢動保、促進社會和諧 維護婦女權益、安全及福利；推動北高雄兒童夜間急診、增加托嬰中心、臨時托育；持續關注弱勢者基本權益並爭取更全面性的福利照顧。致力減少流浪動物，爭取動保專業人力，增加犬貓絕育等執行預算。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"f557442f-2e17-47f3-9f4f-c89c896f60ad","items":["推廣藝文活動，支持在地藝術家","加速推行地方／行政機關支付e化","解決「月經貧窮」，守護婦女權益","整合社會資源，落實弱勢族群之生活","增設完善人行道、自行車道，增加用路安全","推行南投旅遊電子套票、促進觀光，增加觀光財","推展創客，提升南投軟實力"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f55ee060-4f98-4fb4-8de1-cf631bc0ef67","items":["老人小孩國家養，婚後孕前健康檢查補助，提高生育補助，增設公共托嬰及育兒資源中心。","推動平價優質幼稚園，增設公立與公辦民營幼兒園，減輕家長負擔，提升幼兒教育品質。","關懷橘世代、銀髮世代，落實長照關懷，推動全齡化公園，興建加速「北高雄長青中心」。","整合左營楠梓族群、宗教、自然、文化觀光資源，引進文創設計產業，提升區域經濟發展。","新台十七線如期如質完工，改善台積電楠梓產業園區聯外交通。","捷運高雄學園線、右昌高鐵線、燕巢高鐵線合併，列為優先路線，北環圈一次到位。","配合2030雙語國家政策、實現「校校有雙語」，重視學生品德教育，強化反毒宣傳，拒絕校園霸凌。","維護居住正義，保障中油後勁勞宅既有權益，社區道路公園由高雄市政府代為養護。","配合2024年奧運新增競賽項目，推廣滑板、霹靂舞、運動攀岩等運動，增加室內練舞練團空間。","善用海洋流行音樂中心、衛武營藝文中心等場館設施，扶助在地音樂、藝文人才，發展音樂、藝文產業。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f5751894-d3fa-480f-8f8e-792808d20a2d","items":["強力監督市政府預算、決算及整體資源分配，落實基層服務。","爭取公共托育中心與公立附設幼稚園的設立、推動過嶺地區增設國小、持續關心龍山國小及青埔國中興校進度，並爭取學校地下室設立公有停車場；爭取設立單親家庭免費課後輔導中心與弱勢家庭餐點補助，以減輕家庭負擔。","提倡全民運動健康生活，活用閒置公有建物、空地，增設里民活動空間，規劃全年齡居民都可以參與的豐富多元課程，鼓勵舉辦各式活動競賽，讓生活有氧更年輕。","推動老屋重建與公辦都更，讓城市翻新、讓市容更好；打開瓶頸道路、改善交通，進而提升居家安全。","持續推動全市電線、電纜全面地下化，還給市民乾淨的天際線。","督促過嶺地區增設消防分隊及青埔消防分隊遷移進度，提升救援能量，守護市民家園。","推動低碳、綠能，完善交通路網，串聯捷運輕軌、公車、YouBike及電動運具，降低空污；強化相關配套，增加大眾運輸搭乘誘因，永續家園。","推動第二行政園區盡速建置，以利民眾洽公。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f5852594-854b-47b2-859b-422cd8c0d701","items":["健康台北：各行政區增闢運動中心二館，校園夜間開放市民租用，讓市民就近運動。","安全城市：擴大獎勵公辦都更，危老房舍改建，容積增設地下停車場，共創官民雙贏。","青年首都：公托、臨托社區化，減輕雙薪家庭托幼負擔，提高年輕人落籍北市意願。","樂活都會：盤點閒置市有房舍、土地，規劃社區整合型長照、日照與居家服務。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f5ab3d65-94f1-4af3-87c2-803448286650","items":["爭取廣設公立、民營托幼機構,提升幼童、國中小、高中及大學之各項教育補助。","落實都會區國中小原民重點學校推動原住民族教育,確保各族語言傳承,依桃園市原住民族語言發展計畫,提升學習族語意識,規劃階段教學、族群知識為本之課程,有效提升語言復振工作。","推動原住民觀光夜市,整合文化創意產業,農耕示範區農業暨傳統美食文化,增加經濟效能。","爭取職業證照培訓專班,讓原民就業環境更好。","落實長照養護政策,持續推動文健站服務長者品質,維護原民長者健康。","落實居住正義,建立包租代管業務原民專屬平台,讓租屋補助政策看的到吃的到。","加強原民法律扶助服務功能,確實解決族人法律問題。","強力監督市府施政,爭取原民預算,提升原住民權益及福利政策,為全國原民政策領頭羊。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f5c88281-acff-4b33-88dd-1bddce56f9b1","items":["文化發展要提升","推動「龜山眷村文化節」、「新住民特色文化節」等大型戶外藝文活動，帶動觀光人潮，推廣龜山之美。","公墓遷移，爭取第一公墓比照蘆竹生命園區建置及美化綠地、興建公園、停車場。","教育興建要推動","推動增設大崗高級中學，促成「大崗完全中學」。","推動完善校園，爭取「幸福國中」操場增設，及解決停車場問題。","交通發展要快速","加速推動長庚轉運站營運，整合機捷、客運、汽機車。","加速推動捷運棕線儘速興建。","爭取移除電桿、清除電線，電纜地下化美化市容。","休閒育樂要推動","爭取新興里、文青里、楓福里增建里民活動中心，供所在里民與周邊里民使用，促進里民交流。","爭取新建大坪頂國民運動中心，完善體育設施，提升居民生活品質。","爭取規劃豐達重劃區增設親子館，完善親子教育設施。","環保治安要落實","改善道路噪音污染，還市民一個清靜城市。","提升環境權，空污廢水監測減排。","警消配備制度升級，及在職執勤保險加碼，提供更高額的保障。","三有好好生活：幼有所養：推動0至6歲兒童醫療保險；廣設公共托嬰中心；推動雙語學校；營養午餐減免。","三有好好生活：壯有所用：社會住宅加速；爭取就業青年房租補貼；廣設青年創業基地、就業輔導；婦女生育坐月子月薪補貼；推動女性凍卵補助。","三有好好生活：老有所依：改善無障礙設施環境；加強長者醫療安養照護；推廣公共托老中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f5dddd0f-33db-4cdb-a4f8-ce783386eb95","items":["爭取並監督蘆洲地區規劃蘆洲醫院預定499綜合型區域醫院！","爭取並監督台電徐匯中學捷運站旁三公頃變電所！規劃室內化及運動公園並將鄰近電線桿移除！","積極監督捷運北環段動工時程！早日完成！讓三重蘆洲的市民直達內湖原45分鐘時間縮短為22分鐘抵達！","爭取並推動監督碧華國中舊址土地建置銀新未來城！規劃設置日間照顧中心及住宿型長照機構！停車場等因應老人社會！","有里就有銀髮俱樂部、里里銀髮俱樂部！提升銀髮族照顧照護！加強對不符合長照服務資格等！提供喘息！","增設幼幼班及幼兒園優化幼兒服務，加強學齡教育！政府不排除以現金補助家長！公私立幼兒園由家長擇定亦可！才能普及化！","新北可多增設青少年需求的滑板場以及攀岩場！以及所有的公園應該都是共融性的體健設施公園讓老中青少可使用！","督促青年局應該針對青少年的需求去實施協助他們！補助就業創業等！更應了解少子化的真正原因？這是國安問題市府務必重視！","督促市府停車的需求？應多加規劃老舊的校園以及公園地下規劃停車場等等？都必須未雨綢繆！","爭取在蘆洲及三重東區堤防外增設海世界水樂園。","督促並監督市府！保障汽機車族的安全！應不定時全市的橋面伸縮縫做全面檢視！以保市民的生命安全！","督促市府零到六歲國家養？絕對不是補助個幾萬塊？應該全面性的做檢討！才能夠解決少子化的危機！","全面監督市府下水道以及抽水機組超過18年以上！必須淘汰更新對於低窪地區常淹水！必須找空曠的地方！地下室做透保水工程蓄水池才對！","爭取並督促市府早日完成第二行政中心讓溪北、溪南資源共同分享！三蘆區會是最進步的城市！","爭取並督促市府，早日新建五華國小教學大樓，目前已不足23班，未來仁義段、真武宮會再增萬餘人口。","爭取長安機械停車場(忠義廟旁)新建平面停車385位。","爭取並監督新北市所有人行道老舊重新施作讓行人有行走的空間！","重視弱勢家庭坐月子到宅服務、新生兒生育獎勵金提高、增設幼兒園、優化幼兒園服務，加強學齡教育！","打造市民安心的用餐環境！因應萊豬進口、加強稽查食品豬肉、原產地標示符合性，食安智慧監控中心稽查檢驗、資訊透明化、使民眾食在安心。","推動幸福宜居健康新三蘆！推動社區照顧、關懷據點、服務在地長輩活躍化、延緩失能失智發生、讓長輩達成終生學習與成功老化的目標！","推展城市觀光發展！配合各項節慶湧蓮寺、護天宮、保和宮、義天宮、先嗇宮等大型節慶！讓三蘆成為城市觀光新風貌！","爭取三重蘆洲地區、路面淹水感測器及監視器讓防汛資料透過智慧防汛平台，即時掌控水情資訊、避免局部積水、情況加劇、達到防汛最佳狀況！","監督市政府打造微笑5G全齡化公園！好方便、好生態、好健康、好安全、好貼心等、全齡友善無礙、友善公園活動空間！","爭取設立青年創業場域補助及鼓勵青年創業！","爭取推動都市危險及老舊建築物！應專案加速、重建提升都更審查效能協商機制、應簡化便民！","因應新冠疫情衝擊、市府應針對受疫情影響就業單位、勞工、加強訪查及輔導，更應提供專業律師諮詢、勞工權益、市政府加強勞動職場檢查。","積極爭取推動品德教育！辦理服務學習公益行動研習！品德教育實踐等活動更落實！"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f60cac61-c4b3-4793-a7e2-834db2ecafb4","items":["爭取設置海線寵物公園 爭取大小犬分離的運動區域，設置跳躍跨欄、隧道水泥管、棧橋、遮陽和避雨等設施。","AI系統確實在高中職端落實 (一)在人才培育方面規劃AI教育向下扎根。 (二)實際動手操作，進一步了解人工智慧。","協助海線南山截水溝計畫第三期推動 協助推動南山截水溝計畫3期，造福約1萬9000人，以解水患之苦。","督促捷運藍線跨黨派推動小組，儘速啟動徵收與開工作業 儘速成立「台中市捷運推動小組」，共同攜手合作，推動台中捷運藍線動工。","港務回饋金專款專用於台中港區 將落實了解各區分配額度及使用情形，並爭取港務回饋金專款專用於台中港區。","梧棲大村里、大庄里及永寧里、永安里、興農里等二里三里多功能聯合活動中心經費到位， 督促儘速動工 經費一到位，督促儘速興建運動休閒設施及里民活動中心，促進地方發展。","慢飛天使資源不能停 未來將督促市府在早療天使政策推動，未來能更加周全。","爭取梧棲新行政中心 便利民眾洽公促進地方繁榮 梧棲區公所為四十年老舊建物，辦公、停車空間都不足，將爭取梧棲新行政中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f63698bc-e508-46b6-8848-1c92dd20db12","items":["爭取區內機車考照公共練習場。","改善獨老、低收及失依兒少之社會福利分配，並推動婦女二度就業及失業勞工就業培訓。","整合廢棄校舍，推動日托、日照及青銀共食，並爭取區內老人免費營養午餐。","整合外木山當地漁港觀光休閒及水上遊憩產業，並成立管理委員會維護周邊環境。","爭取西定河高架道路及各里巷弄監視及照明系統，保障居住安全。","彙整區內各易肇事路段，如中山一、二路轉彎處，研擬改善方案，保障行車安全。","督促政府建設中和路大慶大城聯外道路之進度，爭取公共停車場，解決當地停車問題。","督促落實各里自來水管汰舊換新，並改善高地缺水問題，保障用水權益。","爭取區內國有土地及港埠用地釋放原住戶買賣，保障居住權利。並活化閒置國有土地作為停車場或道路等公共建設使用，提升生活機能。","推動危老重建及都更計畫，轉型社會住宅，解決區內老舊房舍環境及衛生問題。","強化倫理道德及人文藝術教育，並推動產學合作，提升基隆青年就業機會。","為中山區建立青年參與政策平台，攜手共同打造共榮家園，提升年輕人 U-Turn 與 J-Turn 的意願。","推廣中山區內環境教育及食魚教育，海港形象活化，還給中山區民眾里山里海的兒時記憶。","延伸基隆火車站商圈至中山區並串聯區內各景點，促進地方經濟發展，錢留中山，繁榮地方。","爭取外木山自行車道人車分離，串聯至八斗子「望海藍帶鐵馬景觀棧道」，推動基隆藍色自行車道。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f68ae746-8f27-4a7c-a5e8-631a3579ad19","items":["爭取美寮路拓寬工程，保障居民、學子出入通行生命財產安全。","爭取塭仔港泊地，推動定位觀光景點。","爭取保障老年、婦幼、弱勢團體，其應有權益福利。","協助農漁會，保障農民耕作權、漁民漁業權及爭取農漁民權益、福利，改善農漁民生活。","監督縣府為民喉舌、民意優先。","推動並支持彰化縣自然生態環境保護及動物保護自治條例各項的相關法案。","嚴格監督彰濱工業區廢棄物處理機構並要求落實環境保護工作、保障民眾身體健康及漁業資源。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f6ac1add-8b59-476f-b4a6-a5bbfd3e4dc8","items":["民意優先監督市政","推動後疫情新時代","婦幼共融多元照護：積極推動國中、小雙語教學課程，規劃良好英語教學環境。","婦幼共融多元照護：積極要求市政府將田寮河的景觀改造、河水整治給市民一個運動休閒的地方。","婦幼共融多元照護：積極爭取經費改善易淹水地區路面及排水系統，以利市民免受淹水之苦。","婦幼共融多元照護：促請自來水公司更換老舊管線，改善高地供水加壓設備，增加大型蓄水池，以利民眾供水問題。","婦幼共融多元照護：促請市政府建設兒童、青少年的活動場所。","婦幼共融多元照護：促請市政府維護全市砲台，保存文化資產。","婦幼共融多元照護：促請市政府持續市民安全意外保險制度。","婦幼共融多元照護：促請市政府加強婦幼、身心障礙、老年、失業者等弱勢族群照顧與保護。","婦幼共融多元照護：積極推動救急救災通報系統，健全監視系統，做到治安無死角。","婦幼共融多元照護：積極要求市政府路平專案並改善騎樓的地面高度一致，推動市容整頓，加強公共建設，營造美麗新基隆。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f6c5c336-9a2a-4be9-b4e2-d9d36f891af5","items":["成功催生 You Bike 並精進2.0版，使 You Bike 成為台北之光、台灣之光。","成功在信義計畫區爭取第一座狗活動區，為狗狗打造鑽石級活動場域。","善盡議員職責，並承先啟後，提升整體議會問政品質。","致力城市生態永續發展，監督市府相關施政建設配套。","繼續優化 You Bike 為3.0版，落實節能減碳新生活。","為友善動物城市持續發聲，創造寵物、飼主及市民三贏。","監督市府改革都市更新沈疴，提高容積獎勵、提升效率、擴大公辦都更。","擴大生育及托育照護補助，減輕年輕夫妻負擔，解決少子化危機。","推動北市為敬老、尊老的長者樂園，增加老人照護相關經費。","減少人口流失，責成市府新團隊提出具體方案，再創北市競爭力。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan","past_achievement"]}}},{"claim_id":"f7228b9d-ff25-4a88-bd04-7a130b15cb2d","items":["■信守承諾 延續老議長林清都的政治理念為鄉親打拼。 ■陽光問政 為農民勞工與漁友兄姊伸張正義維護權益。","■爭取建設：改善東港鹽埔漁港泊區為現代化漁港，持續發展東港漁業。","■爭取建設：興建東港低溫拍賣魚市場，確保水產品衛生品質，建立漁業新形象。","■爭取建設：改建東港老舊圖書館，新建在地特色之圖書藝文展演文化中心，提升教育文化水準。 ■督促政府","■爭取建設：加速開發大鵬灣，發展觀光振興經濟，增加地方就業機會。","■爭取建設：加速興建東港地區行政中心（王船文化館、縣屬機關聯合辦公大樓、轉運中心、社會福利綜合館及立體停車場等新建案），並重視公共工程品質，早日改善鄉親洽公環境及提升行政效率。","■爭取建設：推動農漁產業升級永續經營，帶動地方發展。","■爭取建設：重視老人婦幼及身心障礙者等弱勢團體之福利政策。","■爭取建設：重視地方治安與教學環境改善工作。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f7374f7c-abe3-4ee4-b1e2-1b83e824d76b","items":["積極爭取原住民權益，建請落實原住民基本法及修訂各項配套法令。","持續關懷照顧弱勢家庭，結合各項資源，全力協助及爭取應有權益與福利。","鼓勵及尊重多元宗教信仰，扶助宗教團體各項活動與充實軟硬體設施。","督促政府積極培育原住民體育、藝術、文化等相關人才。","全力維護警察人權，爭取充實各項裝備，以強化執勤安全。","爭取文健站、關懷據點各項設施，建立完善部落老人照護體系。","爭取接收金崙村原觀光局38公頃土地，規劃興建為具運動、休閒、醫療、文化等園區。","持續爭取永久屋土地所有權，以符財產及居住正義。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f73c884e-e92e-4af2-963c-9ee11afb7e8b","items":["勞工權益：爭取設置勞工權益平台，專責輔導勞資爭議訴訟、法律諮詢、職業災害急難補助、失業勞工急難生活及子女就學補助，並加強實施例行勞動檢查，維護勞工權益與職場安全。增加縣內勞資協調地點，簡化申請方式與縮短協調時程，盡速解決勞資爭議以利勞資和諧。盤點縣內教育資源，並協調社區大學與大專院校開辦勞工在職教育課程，且協助求職者就業、輔導創業，每年應至少辦理4場以上大型就業博覽會。","動物保護：爭取家畜疾病防治所醫療設備環境改善，並擴編防治所人事編制，持續推動領養流浪動物活動，除現有免費施打疫苗、晶片置入外，領養寵物贈送一年份寵物保險。增加竹北市家犬、貓免費結紮、晶片置入、狂犬疫苗施打場次及補助款，並結合縣內國中小舉辦參觀活動及宣講，使生命教育從小扎根，培養學童正確觀念。","交通優化：要求縣政府全權收回轄內道路挖掘管理權，規範所有單位統一辦理開挖；且道路應預埋管溝，以免重複開挖確保道路品質。擴大規劃全縣「交通寧靜區」，學區人行道優先增設，統一制定並提高人行道防滑係數，並規範車輛限速30公里，讓學童上下學更安全。開發新一代手機APP結合視障友善有聲號誌，並於行人穿越線上繪設視障導引標線、人行道設置無障礙坡道與導盲磚，來輔助定向師教導視障朋友通過路口，以改善視障朋友無障礙用路安全。提倡綠色運輸計畫，研擬加開公車班次與路線與增設YouBike站點，獎勵使用大眾交通運輸，達到碳減量與塞車問題；縣內公有停車場提供一定比例的免費電動車專用車格及比照六都全縣公有車格電動機車免費停車，以達到低碳城市目標。","銀髮樂活：強化教育部與新竹縣政府合作，結合在地組織及民間團體，建構各個里「樂齡學習中心」及擴大「社區照顧關懷據點」，讓長者能夠就近學習與關懷；並配合多元文化講座及施政宣導，讓竹北變得更有溫度；健銘希望竹北不但是年輕人離鄉打拼的地方，更是長者退休的宜居城市，可以安心繼續快樂健康的社會參與。","青年參政：推動縣政府持續擴大青年參與，加重各局處年度青年相關事務（業務）的權重指標，並重新評估修正新竹縣政府青年諮詢委員會設置要點；增加青諮委員人數，並將縮短意見彙整時間；方能招攬更多優秀人才，強化青年與縣府溝通機制，建立多元且快速的彙整管道，做為縣府施政規劃；輔導青年創業及就業基金，並成立青年就業獎勵計畫，打造新竹縣成為青年友善的標竿。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f7a16640-a0ee-4067-8c91-081b790a8570","items":["爭取過港路、源遠路、八堵路「示範道路」","爭取本市首座「寵物公園」設置於暖暖","爭取本市設置 U-bike系統 & 電動車換電站","爭取本市第二座國民運動中心","爭取暖暖區行政中心 - 區公所更新改建（整合區公所、户政事務所、衛生所及派出所 ), 連同周邊市場用地進行聯合開發，開挖地下停車場以便利民眾辦理相關業務及紓解暖暖停車空間不足問題！","爭取複合式商場 ( 美食廣場與菜市場 )","爭取第二身障洗車中心設置過港 ( 身障者庇護工場 & 職訓基地 )","盤點現有閒置空間盤點 , 全力爭取各部門單位經費活化再造","過港路道路品質提升 ( 人本環境 - 人行專用空間、電桿移除纜線地下化、道路鋪面重新鋪設 ) 並比照示範道路規範，兩年内不得再開挖！","優化過港河濱公園 ( 夜間照明、步道平整、植栽美化 )","八堵地區活化再造 , 以 TOD 大眾運輸導向都市發展，盤點八堵車站周邊交通、道路、土地使用，讓八堵再現風華！","爭取八堵四里里民活動中心","八堵路道路品質提升 ( 人本環境 - 人行專用空間、電桿移除纜線地下化、道路鋪面重新鋪設 ) 並比照示範道路規範，兩年内不得再開挖！","舊眷舍活化","惠明新村拆除後積極對外招商","東暖新村拆除後建闢停車空間","源遠路道路品質提升 ( 人本環境 - 人行專用空間、電桿移除纜線地下化、道路鋪面重新鋪設 ) 並比照示範道路規範，兩年内不得再開挖！","優化碇内河堤散步道 ( 吊橋整修與 LED 燈具更新、路樹修剪與步道平整 )","持續推動「愛分享惜食冰箱系統」廣佈本市各行政區與關懷據點","持續關注社會及民生議題 ( 食物銀行、弱勢照顧、日照中心、公托公幼 )","持續關注並努力解決目前暖暖區内通勤族朋友乘車品質不佳之窘況","持續推動在地創生與青年返鄉創業。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f7a71a18-fadb-4b8b-9fdc-88940c23b659","items":["完善家庭照護者支持體系，承接不同需求家庭，建構社區共照空間，發展嬰幼兒及長青臨托制度，讓照顧者有喘息空間。","增設公托、公幼及非營利幼兒園，減輕雙薪家庭育兒困境。","毛小孩也是我們的家人。推動毛孩健保，執行動物保護行政監督，並促成動保警察以加速動物虐待的通報與查緝。","打造各式特色公園，除了親子友善共融公園，銀髮體健、親水生態及毛小孩運動公園更是未來的建設重點。","文化觀光：發揚蘆竹的在地文化及景點，串聯觀光廊道，振興在地經濟。","文化觀光：督促打造具有溫度與質感並且專屬蘆竹的城市美學風格，展現蘆竹多層次之美。","文化觀光：提升農業休閒園區規模，打造宜居美麗的市區後花園。","文化觀光：扶植藝術文創產業，讓蘆竹兒童從小培養美學競爭力。","交通建設：善用蘆竹作為陸、海、空交通樞紐的地利之便，強化聯外跨區交通網絡，減輕民眾通勤負擔。","交通建設：發展新型態的綠色運輸，增設YouBike站點及爭取在公有停車場設置電動車充電樁。","交通建設：全面檢討蘆竹汽機車停車規劃，活化閒置空間以解決停車需求。 多元共榮","交通建設：擁抱多元，打造最友善的移民環境，提供新住民進修、就業、生活諮詢服務。","交通建設：完善族群融合，除了客閩宗教活動，開辦原住民祭典及新住民節慶多元文化座談與活動，發展蘆竹多元文化樣貌。","交通建設：爭取教育經費，督促本土語、族語及新住民語的完整配套措施。","交通建設：完善新住民保障相關法令，研擬各族群文化特色商圈。","生活安全：騎樓整平，提供銀髮長者、輪椅族、嬰幼兒推車安心順行，持續爭取電線桿地下化，以保障民眾行的權益。","生活安全：健全社會安全網，建置社區災害警示通報系統。","生活安全：嚴格監督民生基礎建設，落實路平、燈亮、水溝通的執行力。","生活安全：建置空污、水污、噪音智慧監測系統，加強交通科技執法。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f7a9e1af-404c-4c10-8cdb-c2a7f0dd19d2","items":["守護健康安全：提升醫療品質，強化院際合作。","守護健康安全：加強石虎保育、提升動物福利。","守護健康安全：守護山林土地，要求縣府妥善監督嫌惡設施。","友善育兒環境：增設公立托嬰中心，鼓勵企業設立托兒設施。","友善育兒環境：推動智慧托育，讓家長安心、老師教學更順心。","友善育兒環境：補助自然產減痛分娩與剖腹產術後止痛。","友善育兒環境：公共場所落實親子廁所與集哺乳室設置。","友善育兒環境：改建頭份圖書館，爭取頭份市區設立高中，提升頭份文教資源。","友善育兒環境：推動沉浸式客語教學與非營利幼兒園，積極營造母語學習環境。","友善育兒環境：推動中港溪河濱公園，增加休閒遊憩及親水環境。","友善育兒環境：活化頭份、竹南交流道下空間。","友善育兒環境：加速推動社會住宅，加碼鼓勵包租代管。","友善育兒環境：落實道路平權，整合偏鄉運具，便利長途移動。","友善育兒環境：持續推動頭份第二交流道，爭取串接北橫。","友善育兒環境：設立頭份轉運站，辦理快速公車，改善塞車問題。","友善育兒環境：設立交通專業局處與運動發展中心。","友善育兒環境：爭取頭份、竹南第二行政中心。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":6,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f7bef694-3c7e-4779-855f-958d78934f44","items":["督促相關單位加速審議五股、泰山輕軌工程。","支持市府建設26公頃貴子坑溪河川環境營造，打造「泰山溫仔圳-新北之心」。","持續爭取「機捷票價」納入1280元方案，減輕通勤負擔並鼓勵搭乘大眾運輸和減少車流。","督促加速發包林口A交流道「南出北入」立體化工程。","爭取擴大林口鄰近交流道市地重劃範圍，以利於增設第三交流道之腹地使用和籌措經費並可大幅改善聯外交通。","督促105市道(林口高爾夫球場到八里)環狀高架及A3.40米計劃道路(後湖&中華路文化北路口)如期通車。","爭取108市道宏昌街往長道坑口以及南福路口往蘆竹的拓寬工程。","持續推動「幸福到你家」計劃，主動送愛給長輩即時的關懷！ 十二、督促興建南勢國中和爭取文小五設校，以便利就近就學並繼續增設公托、幼兒園。","持續推動為愛貓愛犬健檢植晶片及施打狂犬病疫苗和鼓勵認養。","督促林口污水處理廠二期工程如期完工。","爭取公共自行車2.0租賃站設置，提供大眾運輸最後一哩路服務，向綠能、環保、減碳、 健康目標邁進。","淑君阿姨將繼續全力支援選區內大小防疫工作！疫情期間共已募集捐贈1100萬 。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["candidate_introduction"]}}},{"claim_id":"f7d16225-ae90-496d-8b22-1d85ffb5748c","items":["翻轉都市更新流程，增加都市更新誘因。活化故宮國寶資源，台北國際觀光城市。","檢討簡易都更流程，加速老舊社區重建，利用提高獎勵鼓勵高齡社區住戶加速整合並解決釘子戶問題，改善台北居住品質落實都市更新。","善用中華文化文物資源，台北市應利用故宮國寶增設地標型建築博物館與美術館、活化閒置土地( 如空總)，提升觀光與經濟產值，讓台北成為華人世界的觀光、藝術、文化首都。","雙北合作，推動景美溪與新店溪流域整治。","創新規劃，改善交通動線。永續環境，調整土地負載。","解決辛亥隧道壅塞，二殯新路明年完工，將紓解交通動線。","加速推動捷運南環線工程以及捷運東環段，落實公車站牌全面數位化。","增建地下停車場，充電停車格法規優先改專用，檢討街道紅、黃線規劃。","加速公私墓遷移，落實山坡綠美化與水土保持。","優化教育，引入資源。社區合作，落實終身學習。","持續增設公立托育機構，廣設校園課後安親班。","結合里辦公室及社區發展協會，營造終身學習環境。","服務鄰里，強化社區治安。弱勢照護，創造安心環境。","結合里巡守隊，維持監視器妥善率，社區緊急安全鈕，落實即時通報，強化治安。","繼續電線桿及變電箱地下化工程，保障用路安全。","科技協助輪椅族權益，落實無障礙以及大眾運輸友善環境。","增設公辦民營長照機構，讓青年安心工作。","檢討法令，確保執法正當性。簡化程序，提升政府效率。","建構市民與市府雙向溝通平台，簡化行政流程，增進施政效能。","檢討不合時宜法令，剷除惡法，保障公務體系執法正當性。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f7d5275c-fa17-4777-9a7a-77f89d4fc070","items":["加速推動彰化市鐵路高架化，捷運綠線建議延伸至花壇可行性","彰化高速公路使用特定區解編，彰化大埔截水溝堤岸兩旁道路拓寬工程","爭取多功能複合式結合藝術展演之北彰化演藝廳","發展推動農業升級，彰化、花壇、芬園成立農產品產銷中心購物廣場","彰化市、花壇、芬園增設運動中心","監督縣府預算相關單位之預算執行成效","增設公辦民營小型日照機構及處所","興建青年住宅，鼓勵青年留鄉回鄉創業工作安心成家","協助解決弱勢族群健保欠費問題，回復健保權益","擴大彰化市東區都市計畫"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f7d9ea3a-be08-4b21-812a-1c36fe0b94ae","items":["爭取編足老人健保費補助","爭取提高生育津貼","監督三爺溪整治工程","監督新豐區大型醫療園區後續落實問題","重視龍崎偏鄉老人醫療需求","爭取二空眷村文化園區保留眷村文化","監督完善二空都市更新計畫","爭取改善台86線與台19甲線路口尖峰時間塞車情形","重視易淹水地區溝渠阻塞問題","重視台南市社會住宅實現民眾居住正義","重視關廟區人口流失增加在地工作機會","爭取增加新豐區共融式特色公園數量","建設大新豐區觀光紐帶","積極監督動保議題完善優化動保政策擬定"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f881b011-7025-4c7f-8083-47c2a20f7d8c","items":["監督政府提出抑制房價政策 ，例如提高空屋稅、囤房稅 ，防止投資炒作 ，讓房價合理化 ，並將增加之稅收成立購屋補貼基金。","爭取提高社會福利預算 ，提高對低收入戶、單親家庭、身障人士、新住民等弱勢家庭的照護。","爭取經費修繕農水路、產業道路及灌溉設施 ，落實重視土地 ，照顧農民權益。","爭取補助中小學生營養午餐費 ，並採用在地食材 ，每週一日有機蔬菜 ，提升午餐品質及減輕家長負擔。","督促政府加強維護校園安全不讓毒品、黑道介入 ，讓學生享有安全學習的教育環境。","汰換老舊監視器 ，建置城市動態影像 A1感知平台 ，推動智慧城市數據治理。","監督路平、路面挖掘及管線管理 ，避免各管線單位重覆挖掘，影響道路品質 ，危及行車安全。","提升公托量能 ，強化托育品質 ，提高育兒及托嬰各項補助金額 ，落實改善青年家庭各項生育負擔。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f88dc7b2-dd0b-40c3-8b1e-535b9140282b","items":["加速新莊第一公墓遷葬，推動公墓用地變更，設置新莊森林公園","爭取福營運動中心興建，加速閒置公有土地活化，平衡南北新莊發展","調整里基層工作經費核發標準，依人口數設置級距，均衡新舊社區里民待遇","呼籲恢復社團活動補助款，專注銀髮樂活照顧與在地青年社區營造工作，提升社群互助動能","建立社區型防災與全民防衛機制，擴大新莊區民參與，有效對抗天災人禍風險","推動塭仔圳土地開發共榮機制，重劃區開發兼顧周邊既存社區需求，開發效益回歸在地居民","運用重劃後市府配回土地，推動替代發展模式，改善交通瓶頸與用路問題"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"f8a290db-fc23-41e7-b4ac-c5069288fe12","items":["堅持正直、重義、同理心的服務理念，為布袋、義竹鄉親打拼。","堅持監督縣政平衡發展，維護布袋、義竹鄉親、新住民同胞應得的權益。","堅持督促縣府推動科技農漁牧業，有效提升產值、減少勞動力付出，並降低損 害，藏富於鄉親。","堅持督促縣府落實並提升長照、日托服務，確實照顧、維護鄉親幸福、安心的 生活。","堅持督促縣府徹底改善區域、村里及農漁排水，有效解決社區及農漁牧產業， 免除鄉親水患苦境。","堅持持續督促縣府加強廣設路口監視系統及照明設備，維護社區治安，讓鄉親 安居樂業。","堅持爭取資源，致力發展布袋、義竹觀光產業，並推展在地特色宗教、民俗、 文化與藝文活動。","堅持制訂政策，結合政府、慈善團體資源，強化弱勢鄉親服務與照顧。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f8eca269-c3b6-4b56-9a42-cfe9909f97a5","items":["楠梓科技產業園區設置,推動專業進修產學合作,聘用在地人才,增加青年就業,加強周圍建設及生活機能。振興高雄經濟,市府不任意舉債。","加速右昌高鐵線連結高雄學園捷運紫線、新台十七線全線通車、鐵路地下化延至楠梓,楠梓火車站站體更新,串聯北高雄交通路網。","爭取生育、育兒、托育津貼提高,增設公托、公幼、托嬰中心,減輕家庭經濟負擔。","落實長照福利政策,重視長輩及弱勢安全照護;爭取新住民權益、婦女福利,放寬補助門檻。","重視勞工權益,提供多元就業輔導,培訓產業人才,促進二度就業機會。","持續推動蓮池潭觀光園區,結合舊城古蹟、見城計劃、半屏山,發展高鐵站商圈,創造觀光與文創產業。","爭取左營海軍眷村文化景觀整體規劃,增加興建社會住宅,老舊社區住宅維護。","改善空氣汙染,節能減碳,生活減塑;推動綠能交通、綠能產業,打造健康宜居生活。","爭取學校軟硬體設備更新,網路教學,擴充圖書館藏書,強化英語教學,監督營養午餐品質。","爭取高雄大學特定區公共設施,提升生活機能,設立圖書館,督促文小2國小校舍、兒8多功能大樓、楠仔坑運動中心儘速完工、打造後勁溪生態公園。","爭取左營曾子路與華夏路口多功能活動中心,增設左營第二運動中心,廣設風雨球場。","推動城市科技化、強化治安網路、網路警察;增設監視器,提升警消裝備,保障市民安全。","推動「路平專案」、友善人行空間、維護行道樹、無障礙設施、加強排水設施,打造多元公園,增加各年齡層遊具、規劃公園友善寵物空間。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"f8efab6c-8056-4018-9d50-79498ba1ae86","items":["交通：監督確保忠孝路擴寬20米計畫道路如期完工，並延伸至中興街五叉路口，提前結合二王公墓市地重劃計畫。","交通：監督永康次17-1號新闢道路完工並加速17-2號、17-3號計畫道路開闢，以利區域整體規劃發展。","交通：爭取自強路經永科北路至王行東路跨橋連接許縣溪對岸新化永新路，打通除台一線、台二十線外，增加第三連結道，以利永康、新化區域發展。","交通：加速開闢已列入都市計劃但未開闢之道路徵收及公園綠地，爭取預算編列收購私人既成巷道，減少民眾權益受損。","交通：延續監督成功里立體停車塔(一、二樓為活動中心)進度，再續爭取忠孝運動公園全民運動館與風雨球場設置，及納骨塔新設電梯與立體停車塔(一、二樓為活動中心)。","交通：監督光復里活動中心施作進度，爭取大灣里活動中心用地取得與預算編列","交通：下水道是一個城市的主動脈，加強水利局、工務局水溝巡檢與淤積排除列為緊急業務。","交通：國中小營養午餐免費、65歲以上長輩健保費全額補助、減少流浪教師數額、提供代理教師完整聘期、落實特教生就學權益降低師生比保障師資。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":5,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"f9fbbc0c-ac43-4612-9c32-20fb3889845a","items":["爭取生育補助加碼。","督促政府增設公托、公幼。","加強警消之裝備及訓練,爭取警消權益。","推動觀光產業,促進經濟發展。","爭取婦幼及弱勢福利。 讓苗栗更美好。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fa79dacd-f551-4d95-9315-d31891463bee","items":["協助部落推動觀光產業發展，提供青年返鄉就業機會。","維護鄉民用路安全，復建災後沖毀道路、橋樑。","協助改善永久屋居住空間，維護鄉民生命財產安全。","維護山林國土保育，發展林下經濟。","重視文化教育，傳承魯凱百合精神，延續族人命脈。","爭取社會資源挹注衛生醫療、協助法律輔導，減少鄉民訟累。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":2,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"fa923c67-badb-4e80-badb-d8b55cabb640","items":["文化教育：監督縣府辦理國中小多元文化教育課程、建置零至二歲托育資源系統、推動食農教育，提升學童綠色飲食知識。","社福照顧：監督縣府提升長照師資專業能力、推動生育津貼加碼補助、完善現代社會住宅，打造青年安心居住環境。","環境保護：將農廢與垃圾轉作生質燃料，解決垃圾問題。推動綠色低碳旅遊計劃。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"fa9eb3d9-ac1b-442e-8c82-dbbe2d241ea8","items":["爭取提升雲林縣醫療資源，就醫不再是長輩的重大工程。","普設社區長青食堂，建立各鄉鎮中央廚房，讓長輩吃得營養均衡健康。","推動老人學堂及樂齡教育，身心靈都健康。","配合縣內中央民代，要求雲林縣政府爭取台糖公司釋出土地，設立精緻專業農業園區及工業區，招商引資創造青壯年就業機會。","加速改善各農地重劃區內農水路設施。","幼兒整合，要求縣府盤整校園空間規劃再利用。","積極爭取經費，逐步達成全縣中小學營養午餐免費。","向下扎根，爭取全面實施中小學雙語教育與國際接軌。","加速虎尾高鐵特定區的繁榮","要求雲林縣政府設立海線第二辦公室，成立高鐵特定區行政中心。","以古坑綠色隧道成功經驗，爭取縣府在虎尾農博公園設立假日農業市集及藝文表演，提供農民交易平台及縣民假日親子休閒空間。","爭取新住民教育及就業機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"fac7bbe4-8b37-49ae-9a66-5f751aef0983","items":["爭取廣設市立托嬰中心，提高幼兒教育補助；推動國中小校校有英語外師，同時外師至各公幼做共融式教學，強化學生國際觀的教育環境。","推動社會住宅，讓無殼蝸牛有舒適便宜的住宅可以租賃。","爭取置設青創基地，提供青年研究辦公室，提供迅速完整創業資訊，輔導青年創新創意及行銷通路，並協助青創貸款，讓年青人創業不是夢。","督促市府儘速完成圖書總館的規劃設計及興建，並爭取新建一所圖書館多元化場域，讓市民有更豐富多元的休閒閱覽空間。","打造嘉義市成為水漾城市，爭取八掌溪高灘地成為河濱公園，北排治理成嘉義柳川，南排爭取淨水廠，鹿寮排水及野溪整治為親水小溪。","普查嘉義市各室內外場運動館所，升級設施器材活化利用，讓市民有好的運動環境，同時爭取運動競賽來嘉比賽，用運動經濟帶動本市經濟發展。","營造嘉義市成為西部走廊的觀光消費新都心，行銷觀光軸帶並結合各宗教廟宇及博物館的文化底蘊，讓來嘉遊客盡情暢遊各觀光景點和品嚐地方小吃，帶動觀光業發展增加商機。","爭取經費照顧身障團體及清寒家庭。","親力親為全心服務做市民代言人，為市民爭建設謀福祉。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fb8a4fa4-d6df-4cba-b086-a29291f3560b","items":["嚴格監督台積電設廠動工進度、施工品質,並如期提供高雄市民工作機會。","嚴格監督輕軌(博愛大順路、美術館路、中鼓山、鹽埕)施工品質及交通軌道安全。","爭取鼓山區內惟段 9 小段 54~55 地號土地,未來開發興建規劃,應納入鼓山行政機關及鼓山(里)聯合活動中心等空間,提供鼓山居民洽公及社團活動使用。","督促鼓山區內惟藝術中心工程品質,並如期完工開放提供市民使用。","爭取龍子里凹子底森林公園、龍水里美術園區經常性舉辦親子共融活動。","爭取政府編列預算鼓勵鹽埕、鼓山、旗津老舊公寓修建或重建補助。","爭取幼兒教育、國小、國中、高中,全民教育費由政府負擔。","爭取鹽埕區老舊商場重建或修建機制,由政府公權力協助召開重建及修建機制,達成繁榮的鹽埕商場場域。","督促鹽埕、鼓山區國民運動中心興建進度,並持續爭取旗津區興建國民運動中心。","督促政府正在研議旗津第二過港隧道路線規劃的進度,俾便後續工程規劃。","向中央政府爭取國民年金老年給付金額調升至每月 5000 元以上(因國內物價指數升高)","爭取婦女權益落實保障,工作待遇符合兩性平等工作權。","爭取國家協助青年首次購屋(20~30 坪)自備款由政府墊支,爭取政府土地興建青年社會住宅,責成政府成立青年第一次購屋自備款墊支基金專戶。","督促國民雙語教育於 2025 年落實,加強國際語言教學,以提升台灣人民未來在國際的競爭力。","爭取市府與民間醫療機構合作興建近海離島旗津長照醫療中心。","支持滿十八歲青年公民權入憲,為了讓年輕人更了解自己可以決定自己與國家的未來。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fbb6218d-4970-4614-88e7-e05d2ad64b41","items":["⭕教育、文化：爭取市府籌措財源，價購科園國小運動場用地提升學校競爭力。","⭕教育、文化：爭取有效調整學區、試辦安心通學專車。","⭕教育、文化：爭取增設數位課程、強化學生數位競爭能力。","⭕教育、文化：爭取透過都計程序增加交流道附近新設國中用地。","⭕教育、文化：爭取儘速新建連結關埔空橋，保障路人安全與提升行車效率。","⭕教育、文化：爭取於全市各公部門廣設借書機，便利市民閱讀便利性。","⭕教育、文化：爭取重建潛園爽昤閣，充寶竹塹文化內涵與提升全國能見度。","⭕社福：爭取預算將關懷站配置長照專員人力，","⭕社福：從5天10個時段之要求降低為3天6個時段，以有效增加關懷站開站數目與意願爭取編列預算。","⭕社福：在許可條件下增加公辦月嫂照顧胎兒之時數、提升新生兒照護品質。","⭕社福：爭取新建及現有公園無障礙遊具設施，維護身障者使用權益。","⭕生活：爭取舊城改造，以提升停車位前提打造步行商圈，重拾東門商圈繁榮與市民記憶。","⭕生活：監督落實總圖書館興建與棒球場整修工程，矯正原址重建遺憾。","⭕交通：爭取擱置大新竹車站計畫，保留日後爭取鐵路地下或高架化可能性。","⭕交通：爭取設置智慧公車APP，改善公車車體更新與候車亭改善，強化市民搭乘公車意願。","⭕交通：爭取增設ubike2.0並連結大新竹系統，提升使用便利度。","⭕交通：爭取加開醫療路線專車，造福就診不便民眾。"],"content_split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"}},{"claim_id":"fbdc2171-2370-4d10-bbf2-cdfef472b871","items":["拚經濟：引中央資源開發聚興產業園區、豐洲科技產業園區、擴大神岡都市計畫產業園區。","拚教育：爭取中央教育經費補助各校老舊校舍改建、耐震補強工程及改善充實教學環境設備。","拚交通：要求中央儘速核定捷運藍線綜合規劃，力拚2026年動工；台中捷運橘線可行性研究，力拚2026年核定；督促國道1號后里到大雅路段拓寬並增設南出及南入匝道計畫、國道一號大雅交流道銜接台74線工程如期如質完工。","拚觀光：爭取舊山線復駛，中央資源補助優化潭雅神綠園道、后豐鐵馬道及興建旱溪堤頂自行車道、潭子綠空廊道跨越台74線橋下自行車橋。","拚生活：協調法務部中部地區大型贓物庫遷建，並透過都市計畫通檢變更為住宅區，增加住宅用地及公園綠地等各項公共設施。","拚長照：督促豐原醫院后里分院及長照機構如期如質完工，持續推動完整的長期照顧體系，保障失能老人與身心障礙者能獲得適切照護，整合政府與民間資源，提升長照服務品質。","拚幼托：透過「稅賦減免、公托增額、私托補助」0-6歲孩子由政府來照顧。","拚文化：爭取文化部補助潭子、大雅、神岡、后里市定古蹟12處、歷史建築8處，能夠獲得更完善的保存、傳承與發揚。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"fbecc4a7-6b87-49a1-8f0e-6e561b0c21a5","items":["安裝公園監視設備：掃除治安死角、保障民眾安全。","提升道路標線、孔蓋防滑係數：確保用路安全。","清查地下管線埋設深度：杜絕管線淺埋，守護公共安全。","落實大貨車通行政策：確保市民生命安全。","強力監督捷運故障排除：保障乘客運輸安全。","用心教育 托育環境：活化閒置校舍：杜絕空間浪費、打造校舍多元使用。","用心教育 托育環境：增設公立幼兒園：減輕家長負擔、讓孩子開心上學。","用心教育 托育環境：提升企業托兒意願：開創工作與家庭兼顧的友善職場。","用心教育 托育環境：增加臨時托育服務：讓托育更彈性、讓父母育兒無壓力。","用心教育 托育環境：推動女性運動員生理用品免費：杜絕「月經貧窮」，讓女性運動員無後顧之憂。","用心教育 托育環境：公私協力撐起弱勢女學生：持續透過公私資源整合推動「百位女孩希望樹計畫」，與女性學子一同圓夢。","用心教育 托育環境：爭取廣設YouBike站：均衡各區發展，便利市民生活。","用心教育 托育環境：推動電桿、電箱全面下地化：還給市民乾淨天際線與安全舒適人行空間。","用心教育 托育環境：增設公園綠地：提升市民健康休閒生活。","用心教育 托育環境：廣設巷弄標線型人行道：提升行人安全。","用心教育 托育環境：強化毛孩活動空間：爭取增設寵物運動公園、均衡各區寵物活動空間。","用心教育 托育環境：爭取增設巷弄路燈：掃除治安死角，提供市民安全的通行動線。","用心教育 托育環境：全面推動側溝更新：杜絕老舊側溝惡臭、坍塌問題，提升市民優質生活環境。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":3,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"fc000505-0790-4108-a2f4-18430b31340d","items":["培植青年下一代健全價質競爭力 催生成立青年局，厚築青年實力走向國際、汐止秀峰中學危樓拆除重建，校內師生不再冒險上課、爭取營養午餐採有機食材，創造環境永續孩童健康雙贏、增設及改善中小學視聽設備及多功能教室、擴充預算充實圖書館藏豐富學童閱聽。","實現住行安心便利 協力促成捷運汐東線、力爭多條新巴士轉型社區公車、部分公車路線延長、汐止保長里聯外道路都市計劃完成、重要幹道拓寬(如：台2線、汐萬路、八連路、康寧街等)、交通熱區建造社會住宅、無自有住宅者提供租金補貼。","打造家園樂活宜居 爭取設立全齡共融星際主題特色公園-汐止星際公園、主導金山中山堂溫泉會館由飯店BOT案，改為全民共享之溫泉公園、活化金山休閒運動場館，並增設多項健體設施、發展圓潭溪(大鵬國小段)SUP立槳活動、設置好孕專車及孕婦產檢車資補貼。 〔未來〕玲繼續「用心聽，努力做」，您與玲在相信和信任的路上幸福同行！"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["past_achievement"]}}},{"claim_id":"fc30625f-b6db-4b90-a002-ca726fc031c8","items":["督促縣府暢通產品通路，增加農民收入。","督促縣府健全校園守衛制度，加強校園安全。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"fc5fa0ad-654a-4303-9662-76f685254655","items":["持續爭取治安、治水丶防災經費，解決水患，保障人民生命丶財產安全。","堅持清廉問政，監督市府推動各項政策，嚴格把關人民的納稅錢，防止貪弊。","維護居住環境衛生，監督市府落實稽查，避免農、漁、畜牧業用地遭受污染。","配合工業區的開發，鼓勵青年返鄉就業，與企業共同合作輔導訓練，培育優質人力，提倡優質工作環境。","推動各區在地觀光產業丶精緻農業，將各區傳統農業發展為高價值產業並強化行銷地方文化與特色，串連商圈推動輕旅行，創造商機。","爭取各區增設主題特色公園及運動場館，並提升休憩品質。","推動整合醫療照顧與長照機構相關資源，加強照護長輩服務體系，廣推長照 2.0 。","持續爭取擴編生育補助丶育嬰補助及幼兒教育補助，增加生育率，減少家庭負擔，爭取增設公托丶公幼，推動幼兒托育相關政策。","續推政府增加補助農業保險金額，增加農民參與保險意願，減少天災帶來的損失。","推動職業安全衛生及健康管理，提倡安全的工作環境，避免職業災害，創造幸福家庭。","爭取設置臨托場所，讓照顧長輩及幼兒者，有更充裕的時間可利用及喘息。","爭取下營區六里聯合活動中心。","爭取官田區隆本里及隆田里聯合活動中心。","爭取麻豆區跨曾文溪大橋連接善化烏橋中路進入南科。","爭取農水路及道路修繕經費，讓人民有條安全回家的路。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fc6251d9-0e36-40a8-b0dc-86be9eaa7b49","items":["台灣民眾黨是個以台灣人民為主體的政咎,重視人民民生生活,人台東在藍綠之外應有一個能夠真正為人民福祉監 督的第三政黨,為青年開創機會,為弱勢服務。","加強推動產業進駐台東,增加在地就業機會,促進台東青年職業發展。","推動創造無玻視、無障礙、有利身障環境的友善社會。","加強長者醫療、保健與長照服務,減輕子女照護負擔。","推動道管統一挖補制度,減少路面重複施工,增進市民行車便利。","強化台東城鄉教育的均衡發展,增加台東兒女人生翻轉機會。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fcd6c818-c122-4ef3-98b7-3db3089b4eb1","items":["督促市府儘速完成豐洲科技工業園區第二期開發案及補償金發放。","加速推動綠能、儲能光電產業升級。","爭取神岡區新庄擴大工業園區開發案審查通過。","爭取神岡區北庄路12米道路拓寬工程。","爭取神岡高工校地擴建（增）及增班招生。","積極推動機場捷運線開發案。","爭取『豐科軸線』捷運線開發案。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fd473f4c-f2f1-4452-8015-e9dd721550db","items":["持續爭取縣內新設高中及公立高中職增班，讓孩子能就近就學。","積極爭取竹北鑽石型交流道改善興建，以利改善光明六路平面道路往交流道南北雙向車流壅塞。","積極爭取國道一號新設竹北第二交流道分流紓解台元科技園區周邊平面道路交通壅塞。","積極爭取國道三號新設竹東二重交流道。","持續推動臺68快速道路連接國道一號及國道三號。","持續推動臺68快速道路銜接竹東民權路交流道及推動新闢公道五連接竹東二重光明路聯絡道路。","持續推動爭取竹科三期及臺灣知識經濟園區審議通過，促進地方產業發展提升。","督促臺68快速道路延伸竹東-橫山段工程儘速完工通車。","持續推動大新竹輕軌捷運的建置完成、爭取機場捷運延伸至新竹縣市。","推動竹北高鐵站道路進出改善計畫。","持續推動都市更新及電桿、電箱電纜地下化工程。","推動勞工加薪、企業減稅、基本工資逐步調高至33000元。","加強推動「客家語言發展法」立院過關、促進客語保存及推廣。","積極爭取打造浪漫臺三線茶葉博物館及設立農特產品展銷中心。","積極爭取客委會設置客家義民文化園區，傳承客家義民爺忠義精神。","積極爭取經費打造竹北頭前溪右岸運動休閒公園及竹東河濱公園再進化。","推動獎勵企業興建工業住宅政策、創造勞工企業雙贏。","持續推動興建社會住宅，提供年輕族群及弱勢家庭有屋住。","推動提供初入職場青年每年五十萬意外險、持續兩年。","推動18歲公民權、召開青年國是會議。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"fe45f33b-e689-462d-bb3d-dbff8ef51fcf","items":["督促落實老人、弱勢族群福利措施、社會救助，保障其經濟安全、健康維護、生活照顧。","督促本縣社區照顧關懷據點計畫，落實辦理長者送餐、定點取餐、定點共食服務，並積極推動增加其服務天數時段，完善生活照顧。","督促政府提升醫療水平，爭取縣政提撥經費強化醫療軟硬體設備，並爭取增加專業醫療人員常駐金門。","推動嶄新的醫療技術的發展，如增設遠端會診設備...等，完善本縣醫療資源填補醫療資源缺少居民赴台看診之不便與不安。","督促縣府重視觀光產業服務品質，落實景區設施經常性養護修繕、經營管理，建立友善旅遊環境。","推動各鄉鎮特色景點開發，積極行銷在地活動節慶、創意話題、美食及伴手禮，均衡全島觀光蓬勃發展。","提升公共托育品質，爭取預算編列育兒補助、托育專業人員久任獎勵辦法，減輕托育壓力，友善托育職場及托育環境。","督促政府輔導青年打造多元就業管道，推動創業青年培訓課程並爭取經費補助，全面性的完善青創培育。"],"content_split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"}},{"claim_id":"ff823713-b44a-4364-ad07-21cef434fed3","items":["爭取跨縣市工作者交通費補助金,每月1000元","爭取社會住宅符合申請者,若未中籤差額由市政府補助","爭取興建重劃區公車運輸(如中路、經國、小檜溪)","爭取符合接種年齡者全面施打子宮頸癌疫苗","爭取增加各公園的主題性,使其成為主題公園,帶動桃園觀光,提升效益","為因應捷運開通,重新檢視桃園區紅綠燈設置秒數、街距、以改善交通便利","結合在地創業青年,發展桃園觀光打造特色都市"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"}},{"claim_id":"ffb55e60-d2e9-481b-96ed-43c5fd20861b","items":["教育推廣更普及： 1.持續推動國家兒童未來館的建置。","持續推行公共托育中心及公立附設幼兒園的建置。","持續優化教學環境：校舍補強、老舊校舍改建，完成班班有冷氣。 生活品質更提升： 1.設置專款基金，補貼青年弱勢族群租金。","優化長者照護及推廣優質課程。","發展新創事業及招商，增加就業機會。","爭取建置新北表演中心，推廣優質藝文活動。 城市發展再進化： 1.有效改善污水下水道工程。","持續推動老舊社區都更，改善市容。","推動電桿電纜地下化，整頓市容。","增闢停車空間解決停車問題。","持續持動泰板經浮洲輕軌，完成三環六線最後一塊拼圖。","爭取建置體育局及資訊局。"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}},{"claim_id":"fff4fdd6-ed16-4436-802b-e0f0612fda3c","items":["爭取南科特定區","增加生育補助金","確保農作物價格","保障軍公教福利","提高重陽敬老金"],"content_split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","excludedItemCount":1,"reasonCodes":["heading_or_slogan"]}}}]$platform_items$::JSONB) AS release(
    claim_id UUID,
    items JSONB,
